window.GAME_WORLDBOOKS = [{"id":"anime_naruto","category":"anime","canon":"火影忍者","name":"火影忍者","icon":"🍥","tagline":"护额下的名字，比忍术更要紧","mood":"查克拉、木叶、任务、尾兽、羁绊","guidance":"【原著设定】忍者以查克拉为力量本源，需要结印才能发动绝大多数术式，体系分为体术、忍术、幻术三类。大陆上有五大国，各自设有隐村，木叶隐村实力最强，村内按影、上忍、中忍、下忍分编制，任务按 D 到 S 级明码标价。九只尾兽被分别封印在人柱力体内，是各国暗中角力的筹码，也是战争的理由。忍者以护额与任务簿证明身份，规矩比性命重要。【反复出现的意象】村口那块刻着戒律的木牌、火影岩上被风雨磨平的四张脸、公告板上贴着的中忍考试分组名单、一乐拉面店门口被风吹起的布帘。这些画面一出现，玩家就该知道自己站在木叶。【NPC 类型】嘴硬心软的带队上忍、急着立功的下忍同伴、守着封印卷轴的抄录者、被村子除名却仍在边境游荡的叛忍、往来边境只认报酬的货商。他们讲义气，也讲面子。【威胁类型】以窃取各家忍术为业的组织、伪装成同盟村的敌方忍者、被封印术反噬产生的影，以及村子戒律本身——违规者不经审判，直接被就地执行。【奖励风格】苦无、兵粮丸、起爆符、封印卷轴、护额一类原著道具；能力偏向分身、替身、位移与隐匿，一次性术式居多。情报常常比招式更值钱。【不对劲的来源】木叶的戒律像一份自动生效的契约：只要违背，惩罚必然落到人身上，不必任何人下令。更麻烦的是，村子档案里似乎早就记着玩家，只是日期对不上。【时间线】建议固定在中忍考试前后：第五代火影尚未回归，晓组织刚浮出水面，宇智波佐助还在村中。此时木叶刚经历崩溃之变，人手不足，外来者容易被当成间谍，也容易因为「能用」而被破例留下。**纲手此时不在村里**——她在外游荡、赌钱、酗酒，正因为怕血而拒绝一切医疗忍者的身份；把她请回木叶并就任五代火影，是这个阶段最重的一条线（她回村之前的戏份应当发生在村外：赌场、驿站、边境小镇）。不要提前启用后期才登场的角色与设定。","powerStyle":"忍术与体术向：苦无、卷轴、兵粮丸","difficultyBias":0,"signatureItems":["苦无","兵粮丸","起爆符","封印卷轴","磨旧的护额"],"dungeons":[{"rank":"F","name":"波之国大桥的护送","premise":"护送一名建桥工匠穿过雾隐残党出没的海路。","twist":"桥没修完之前，雾里不会出现第二条船。"},{"rank":"E","name":"死亡森林的第五天","premise":"中忍考试第二场，五天之内带着两卷卷轴抵达中央塔。","twist":"卷轴被夺后，队里会少一个人，其余人记不起他。"},{"rank":"D","name":"木叶崩溃的那一天","premise":"考场混战爆发，村口同时传来巨大的通灵声响。","twist":"站在看台最高处的那个人，从头到尾没有动过。"},{"rank":"C","name":"终结之谷的追击","premise":"五名追捕小队沿着河谷追回被带走的人。","twist":"每个人都要先跟自己招式相同的对手打一场。"},{"rank":"B","name":"尾兽的第一次被夺","premise":"人柱力被外来组织带走，村子第一次面对成建制的强敌。","twist":"出手的敌人手上都戴着同款的两枚戒指。"}],"mainQuest":"主线任务：在中忍考试期间守住木叶，认出潜入村中的敌方间谍，阻止他对尾兽人柱力动手。","mainQuestGoal":"在木叶崩溃之变结束前指认全部三名伪装者，并让九尾人柱力在整场动乱中始终处于己方视线内","sideQuests":[{"name":"商队换过的行李","desc":"押送那名出手阔绰的雇主出境，查明他每次替换的行李里究竟是什么","reward":"积分 150"},{"name":"只能骗一次","desc":"在考试场里找出那个替身术用得太顺的人，并把过程报给监考官","reward":"道具「五色兵粮丸」"},{"name":"边境哨的空名册","desc":"把哨所失踪者的名字补回名册，别让下一个人被顶替","reward":"积分 200"},{"name":"卷轴不能出声","desc":"默读一遍禁术卷轴，记住封印手势但绝不出声念出内容","reward":"道具「刻着名字的护额」"}],"factions":[{"name":"木叶隐村","desc":"按编制与规矩运转的忍者村，愿意用外来者的力气，但始终怀疑其来历","attitude":"友善"},{"name":"砂隐村","desc":"同盟之名下的另一套算盘，此行带着自己的任务与伤亡名单","attitude":"中立"},{"name":"音隐村","desc":"专抢各家忍术、以人为材料的组织，把整场考试当作行动的掩护","attitude":"敌对"}],"npcs":[{"name":"旗木卡卡西","identity":"木叶隐村精英上忍，第七班指导老师","role":"引导者","personality":"慵懒随性，关键处从不含糊","hook":"他那本旧任务簿里夹着一份没有委托人的任务记录，签名栏是玩家的字迹","favorHint":"准点集合、把队友放在自己前面会加分；擅自脱队追击会掉分","gender":"男","age":"29 岁","race":"人类（忍者）","faction":"木叶隐村","appearance":"银白短发向一侧倒，护额斜压在左眼上，遮住那只眼睛。深绿上忍马甲洗得发旧，袖口露出半截黑色内衬。他常年半垂着眼，站姿松垮，手里卷着一本封面磨白的书。笑起来只动眼角，说话总慢半拍。","traits":["慵懒","可靠","毒舌","守时"],"relations":[{"name":"漩涡鸣人","label":"自己的学生，最吵闹也最不肯放弃的一个"},{"name":"宇智波佐助","label":"自己的学生，天赋最高也最让人担心走偏的一个"},{"name":"大蛇丸","label":"旧日同僚，也是他一直在等的那件麻烦事"}],"voice":"懒散，常以一个拖长的语气词开头；关键的话只说一遍，说完就转身走。"},{"name":"纲手","identity":"传说中的三忍之一，医疗忍术的开创者，此时在外游荡未归","role":"关键人物","personality":"表面是个赌钱喝酒、什么都不在乎的人；实际上她怕的只有一件事——再看着身边的人流血死去。医术上她从不含糊，也从不留手","hook":"她在赌场里把手里的筹码输光，正转身要走，看见玩家把最后的现金兑成筹码放在桌上。她盯着那摞筹码看了很久，问：「你知道我是谁吗？」——问的时候手已经在发抖","favorHint":"加分：受伤了老实让她处理、在她不搞笑的时候陪着她、把她当医生而不是传说中的三忍、在她提起过去时不追问只递酒。掉分：拿「传说中的三忍」这个名号去求她做事、把她的赌当笑话、在她面前逞强说「我不用治」。她掉分极慢，但一旦掉下去很难回来——她这辈子已经不相信人了","gender":"女","age":"五十余岁（因医疗忍术，外表看着三十出头）","race":"人类（忍者）","faction":"无门无派（木叶在她身后，她还没回头）","appearance":"浅金色长发，在脑后扎成两条粗辫子垂到腰下，额前留着齐眉的刘海，两绺碎发垂在颊侧。**额头正中嵌着一颗紫色菱形印记（阴封印）** —— 那是她几十年攒下的查克拉容器，是她的底牌，也是她「把命存起来」的具象。琥珀色眼睛，眼尾细长，看人时带着一种倦意；常年只上淡色的唇。穿浅绿或灰绿色的无袖上衣配深色长裤，外面罩一件由三忍时期留下的旧外套，脚下是便于发力的平底鞋。**身高在女性里偏高，体型厚重有力 —— 肩宽、背阔、四肢粗壮，是「怪力」练出来的那种厚实**：她一拳能砸碎地面、掀翻巨大物体，那种量级的力气不可能长在纤细身形上，**任何把她画成柔弱身材的描写都是错的**。手很大，指节加厚、有明显老茧（常年结印、正骨、握拳留下的），指甲永远剪到最短。左手无名指上戴着一枚旧戒指，她从不解释。走路的时候重心很稳，是常年负重与发力的站姿。","traits":["强悍","口硬心软","赌性","医者","藏着极深的创伤"],"relations":[{"name":"大蛇丸","label":"她最不想再见到的人，也是她必须面对的那笔旧账"},{"name":"旗木卡卡西","label":"旧识，她会嘴上嫌他懒，实际信他的判断"},{"name":"春野樱","label":"她一眼看出这丫头有当年自己的影子，也看出她缺什么"},{"name":"玩家","label":"第一个问她「你累不累」的人"}],"voice":"口气随便、爱用反问句堵人，喝起酒来话变多；讲医术时语速变快、用词极准，不许别人打岔。生气时不会骂人，会直接动手——而且不会只用一分力。真正脆弱的时候句子会变短，短到你只能听见她呼吸。"},{"name":"漩涡鸣人","identity":"木叶隐村下忍，九尾人柱力","role":"盟友","personality":"吵闹、认死理、绝不丢下同伴","hook":"他认定玩家是第一个不绕着他走的外村人，缠着要一起吃拉面","favorHint":"陪他吃一顿饭、把他当同伴会加分；拿他体内的封印说事会立刻掉分","gender":"男","age":"12 岁","race":"人类（忍者，体内封印尾兽）","faction":"木叶隐村","appearance":"金色短发乱翘，脸颊两侧各有三道须状纹路，蓝眼睛很亮。橙色外套袖口磨破，护额系在额前，边角已经起毛。他比同龄人矮半头，站着也闲不住，不是把手插进兜里，就是抱着后脑勺晃。","traits":["吵闹","执着","护同伴"],"relations":[{"name":"旗木卡卡西","label":"带队老师，他嘴上不服，行动上照做"},{"name":"宇智波佐助","label":"同伴，也是他最想追回来的那个人"},{"name":"春野樱","label":"同班队友，吵得最凶也最护着的一个"}],"voice":"语速快、声音大，爱把当火影挂在嘴边；被夸一句就立刻得意忘形。"},{"name":"宇智波佐助","identity":"木叶隐村下忍，宇智波一族幸存者","role":"对手","personality":"冷淡、目标明确、不喜解释","hook":"他对玩家的招式来历起了兴趣，因为那不属于任何一个忍村","favorHint":"用实力说话、不打听他家族的事会加分；提到他哥哥会立刻翻脸","gender":"男","age":"12 岁","race":"人类（忍者）","faction":"木叶隐村","appearance":"黑发，后脑翘起一撮，深色高领短衣配白色短裤，背后印着族徽。眼神冷，看人时下巴微抬。左手腕缠着绷带，忍具袋挂在右腿侧。他走路很快，落座时总把背对着墙，正面对着门。","traits":["冷峻","好胜","独行"],"relations":[{"name":"漩涡鸣人","label":"同队里最吵的那个，也是他唯一承认过的对手"},{"name":"旗木卡卡西","label":"带队老师，他只肯在训练场上听他的话"},{"name":"春野樱","label":"同班队友，他清楚对方的心意却装作不知道"}],"voice":"短句，少解释，常用「无所谓」「不需要」；被问到家事就沉默着走开。"},{"name":"春野樱","identity":"木叶隐村下忍，第七班成员","role":"盟友","personality":"要强、心细、口是心非","hook":"她偷偷记下了玩家受伤后自愈的速度，几次想说又咽了回去","favorHint":"尊重她的判断、把后方交给她会加分；只把她当治伤的人会掉分","gender":"女","age":"12 岁","race":"人类（忍者）","faction":"木叶隐村","appearance":"粉色长发，护额当发箍压在刘海上面。红色连衣裙配短裤，腿侧绑着忍具袋。额头干净，手指修长，指甲剪得很短。她站着时习惯把重心压在一条腿上，被人说破心思就先红脸再说狠话。","traits":["要强","心细","嘴硬"],"relations":[{"name":"宇智波佐助","label":"她一直注视着的人，如今也最让她不安"},{"name":"漩涡鸣人","label":"同班队友，吵归吵，她最清楚他什么时候在硬撑"},{"name":"旗木卡卡西","label":"带队老师，把全队的伤都交到她手上的那个人"}],"voice":"先抬声音再讲道理，句子干脆；对同伴会立刻换成照顾人的语气。"},{"name":"大蛇丸","identity":"原木叶三忍之一，音隐村的建立者","role":"潜在敌人","personality":"温和、耐心、把人当材料看","hook":"他见到玩家的第一句问的是来历，第二句开价，第三句已经在计算代价","favorHint":"用情报换情报、不露出恐惧会加分；当面拒绝并说破他的目的会掉分","gender":"男","age":"外表四十余岁","race":"人类（忍者，身体经改造）","faction":"音隐村","appearance":"身形细长，脸色过分苍白。长发垂到腰际，浅色便装外面披一件旧外袍，领口敞着露出锁骨。瞳孔是竖的，颜色极浅，笑起来只有嘴角向上。他说话时习惯用指节抵着下巴，指尖泛着不正常的白。","traits":["耐心","危险","好奇"],"relations":[{"name":"宇智波佐助","label":"他此行真正想要带走的人，也是他预备好的容器"},{"name":"旗木卡卡西","label":"旧日的同僚，他乐于看对方为村子疲于奔命"},{"name":"漩涡鸣人","label":"他随手记下的人柱力，暂时排在目标名单的第二位"}],"voice":"语速很慢，尾音拖长，爱用「有趣」评价别人；从不威胁，只陈述条件。"}]},{"id":"anime_aot","category":"anime","canon":"进击的巨人","name":"进击的巨人","icon":"🧱","tagline":"夺回玛利亚之墙，用掉这一代人","mood":"高墙、立体机动、瓦斯、巨人、自由","guidance":"【原著设定】人类被围在三重同心高墙之内，最外是玛利亚之墙，其内是罗塞之墙与希娜之墙，墙外是活动着巨人的世界。军队以兵团编制运转：训练兵团毕业後分流进驻扎兵团、调查兵团与宪兵团。战斗主力是立体机动装置——靠瓦斯与钩索在建筑间高速移动，用双刃超硬质刀片削向巨人后颈唯一要害。巨人体型各异，多数没有理智，对声音敏感，少数具备智慧。【反复出现的意象】墙顶巡逻的火把、立体机动喷出的白气、写满阵亡者姓名的木牌、调查兵团那枚蓝白相间的自由之翼徽章。这些意象一出现，玩家就该听见钩索弹出的声响。【NPC 类型】把恐惧压进纪律里的老兵、刚领到钩索的新兵、坚持调查墙内历史的疯子、守着钥匙却不敢开门的看守、在宪兵团里左右逢源的事务官。他们的忠诚与怀疑一样强烈。【威胁类型】破墙的高大身影、会模仿最后吃掉那个人说话的巨人、混进队伍的同类、把士兵当消耗品的高层决策。真正的压力来自瓦斯余量与信息不对称。【奖励风格】立体机动装置、超硬质刀片、瓦斯罐、自由之翼徽章、雷枪一类装备；能力偏向高速机动、短时爆发与抗恐惧，使用次数有明确上限。【不对劲的来源】三重高墙的作用似乎从来不只是挡住外面的东西，也在把某样东西关在里面；墙内的历史被统一改写过一次，改写的痕迹还留在课本的页边上。【时间线】建议放在第104期训练兵毕业后的数月至玛利亚之墙夺还战之间：托洛斯特区刚刚失守又被堵回，女巨人事件已发生，调查兵团损失惨重而急需人手。此时玩家作为新编入的士兵最合理，也能自然接触到主要角色。不要提前使用墙外世界与后期政变之后的设定。","powerStyle":"机动与爆发向：立体机动装置、刀片、瓦斯","difficultyBias":3,"signatureItems":["立体机动装置","超硬质刀片","瓦斯罐","自由之翼徽章","粗布披风"],"dungeons":[{"rank":"F","name":"托洛斯特区的补给塔","premise":"外墙被撞开，瓦斯耗尽的训练兵被困在补给塔上。","twist":"塔顶的补给箱只对报出自己所属班次的人打开。"},{"rank":"E","name":"巨树林的伏击","premise":"调查兵团在巨树林设伏，要活捉一个从不说话的巨人。","twist":"她只追携带情报的人，对其他人视而不见。"},{"rank":"D","name":"厄特加尔城的夜","premise":"一座没有地方展开立体机动的旧城堡，援军要天亮才到。","twist":"城堡里的人中有一个认得这座城的旧主人。"},{"rank":"C","name":"地下室的第三把钥匙","premise":"墙内某处的地窖锁着三把锁，只找到两把钥匙。","twist":"第三把锁的锁孔里塞着一张写满名字的纸。"},{"rank":"B","name":"玛利亚之墙夺还战","premise":"三个方向同时开战，目标是堵住外墙那个破口。","twist":"对方最想抢走的不是人，是一本没有画完的书。"}],"mainQuest":"主线任务：随调查兵团参加玛利亚之墙夺还作战，堵死外墙破口，并把墙内的真相带回墙内。","mainQuestGoal":"在作战当日完成破口封堵，取回地窖中的全部证据并交给调查兵团团长，且同行小队至少两人存活","sideQuests":[{"name":"裂缝的方向","desc":"比对碎石的落点，证明外墙的裂口是从内侧被撞开的","reward":"积分 200"},{"name":"塔顶没下来的新兵","desc":"把训练塔上没下来的新兵带回来，弄清塔为什么每天都在变高","reward":"道具「磨亮的钩索」"},{"name":"不该存在的石门","desc":"记录石门后的敲击节奏，与墙外巨人的脚步做一次同步比对","reward":"积分 180"},{"name":"地下室的编号","desc":"抄录兵营地下室里的编号序列，找出还没有刻完的那一个","reward":"道具「写满名字的木牌」"}],"factions":[{"name":"调查兵团","desc":"墙内唯一主动出墙的部队，纪律压过恐惧，在意你是哪一期入伍的","attitude":"中立"},{"name":"驻扎兵团","desc":"负责守墙与疏散，救人是第一标准，不讲究出身","attitude":"友善"},{"name":"宪兵团","desc":"守着内圈与王都，优先维护秩序而非真相，对外来者格外警惕","attitude":"中立"}],"npcs":[{"name":"利威尔·阿克曼","identity":"调查兵团特别作战班班长，人类最强士兵","role":"引导者","personality":"洁癖、话狠、判断极快","hook":"他看过一次玩家使用钩索的姿势，说那是他教过的某个死人独有的发力方式","favorHint":"把装备擦干净、按他给的队形行动会加分；浪费瓦斯与同伴的命会掉分","gender":"男","age":"34 岁","race":"人类（阿克曼血统）","faction":"调查兵团","appearance":"身量不高却精瘦结实，黑发中分，眼神冷而专注。兵团短外套永远整洁，领巾系得一丝不苟，胸前挂着自由之翼徽章。握刀的手背上青筋清楚，指节有旧伤。他站立时重心极低，随时能弹出去。","traits":["洁癖","果决","护短","毒舌"],"relations":[{"name":"埃尔文·史密斯","label":"他唯一愿意把命交出去的人，也是他常常质疑的人"},{"name":"三笠·阿克曼","label":"同族后辈，他看重她的天赋，也担心她只为一件事活着"},{"name":"艾伦·耶格尔","label":"他负责看住的人，从第一天起就没让他放心过"}],"voice":"句子短，直指要点，爱用最不客气的说法讲最要紧的事；从不重复第二遍。"},{"name":"埃尔文·史密斯","identity":"调查兵团第十三代团长","role":"关键人物","personality":"冷静、擅长取舍、把真相排在性命之前","hook":"他在作战会议上点名让玩家站到地图前，因为玩家的推断与某个已死之人的笔记完全一致","favorHint":"提出可验证的情报、愿意承担任务会加分；临阵退缩或谎报伤亡会掉分","gender":"男","age":"35 岁","race":"人类","faction":"调查兵团","appearance":"高大，肩背挺直，金发向后梳得整齐，浓眉压着一双极稳的眼睛。兵团外套的扣子扣到最上一颗，斗篷披在肩上。右臂空着一截袖管，用束带压好。他说话前习惯把手指按在地图边缘。","traits":["冷静","擅取舍","威严"],"relations":[{"name":"利威尔·阿克曼","label":"他最锋利的刀，也是唯一当面顶撞过他的人"},{"name":"阿尔敏·阿诺德","label":"他寄予厚望的年轻头脑，常把关键判断交给这孩子"},{"name":"艾伦·耶格尔","label":"他为这趟远征押上的最大赌注"}],"voice":"语速平缓，先讲结论再讲代价；被追问动机时只回一句「因为我需要知道」。"},{"name":"三笠·阿克曼","identity":"调查兵团士兵，第104期训练兵首席","role":"盟友","personality":"寡言、专注、只护一个人","hook":"她把围巾的一角给玩家压过伤口，那是她身上唯一愿意分出去的东西","favorHint":"在她分神时补上位置会加分；当着她的面把那位同伴排进危险任务会掉分","gender":"女","age":"15 岁","race":"人类（阿克曼血统）","faction":"调查兵团","appearance":"黑发及肩，眼神安静而锐利，脖颈上围着一条洗得发灰的红围巾。兵团制服合身，刀鞘挂在腰侧，握刀的手很稳。她动作没有多余的部分，走路时习惯走在队伍里某个人的半步之内。","traits":["寡言","专注","护人","冷静"],"relations":[{"name":"艾伦·耶格尔","label":"她活着的理由之一，也是她唯一会为之失控的人"},{"name":"阿尔敏·阿诺德","label":"从小一起长大的同伴，她信他的判断胜过信自己"},{"name":"利威尔·阿克曼","label":"同姓的前辈，她承认对方比自己强，也只承认这一点"}],"voice":"话很少，一次一句，多为判断或警告；情绪只在提到那个名字时才露出来。"},{"name":"阿尔敏·阿诺德","identity":"调查兵团士兵，第104期训练兵","role":"盟友","personality":"体能与刀法落后，脑子最快","hook":"他借走玩家随身带的一件小东西，说是要对照书上那幅图，第二天还回来时书页多了批注","favorHint":"认真听他的推演并帮他做验证会加分；笑他打不过巨人会掉分","gender":"男","age":"15 岁","race":"人类","faction":"调查兵团","appearance":"个头不高，浅金色短发贴着额头，脸上还带着少年气。制服肩线略宽，袖口卷了一道。怀里常揣着一本卷边的书，手指有翻页翻出的薄茧。他说话时会下意识低头看地面，抬眼时又极认真。","traits":["善推演","怯战","心软"],"relations":[{"name":"艾伦·耶格尔","label":"从小一起长大的挚友，也是他最怕失去的人"},{"name":"三笠·阿克曼","label":"另一个从小一起长大的人，他依赖她的保护也为此羞愧"},{"name":"埃尔文·史密斯","label":"第一个认真听完他推演的长官"}],"voice":"语速快，边想边说，爱用「如果……那么」；被质疑时会先报出证据再继续。"},{"name":"艾伦·耶格尔","identity":"调查兵团士兵，第104期训练兵","role":"对手","personality":"执拗、冲动、把自由看得比命重","hook":"他在玩家身上闻到一点和墙外有关的味道，从此一直盯着玩家的一举一动","favorHint":"出墙时替他确认一次地形会加分；劝他「老实待在墙内」会掉分","gender":"男","age":"15 岁","race":"人类（可巨人化）","faction":"调查兵团","appearance":"中等个头，深色短发扎在脑后，眉骨高，眼神带着压不住的火气。制服穿得随意，腰带勒得很紧，立体机动的固定带在肩头磨出深痕。他说话时习惯把手掌拍在桌面上，指节有反复练刀留下的疤。","traits":["冲动","执拗","要自由"],"relations":[{"name":"三笠·阿克曼","label":"一直挡在他前面的人，他既依赖又想挣脱"},{"name":"阿尔敏·阿诺德","label":"他愿意把命押上去的那种朋友"},{"name":"利威尔·阿克曼","label":"负责看管他的人，两人互相不肯低头"}],"voice":"嗓门不小，句子硬，爱把「自由」二字挂在嘴边；被按住时会压低声音重新说一遍。"}]},{"id":"anime_bleach","category":"anime","canon":"死神","name":"死神","icon":"⚔","tagline":"刀要叫得出真名，才肯醒来","mood":"斩魄刀、虚、尸魂界、灵压、两界之缝","guidance":"【原著设定】人死之后灵魂成为「整」，被虚袭击或留下强烈执念的会堕落成虚。死神隶属尸魂界，用斩魄刀斩虚、把整送往尸魂界，同时维持两界的数量平衡。死神的核心战力是斩魄刀：刀中寄宿着主人的灵魂，知道真名并解放后才能进入始解，再进一步才是卍解。除刀之外还有鬼道，分破道与缚道，需要咏唱，放弃咏唱则威力大减。尸魂界由护廷十三队维持秩序，上有中央四十六室与极严的法规；现世的小规模事件则由代理死神处理。【反复出现的意象】夜里贴在墙角的黑色蝶影、放学后空无一人的操场、斩魄刀出鞘时那一声类似风铃的轻响、写满姓名与日期的名册。看到这些，玩家就该知道自己站在两界的缝里。【NPC 类型】照规章办事的队长与席官、刚拿到刀的年轻死神、不肯离开人世的整、在现世与尸魂界之间两头跑的技术人员、把规则本身当武器的高位者。他们大多守程序，而程序未必是对的。【威胁类型】以人心为食的虚、由大量灵力聚成的破面、被判罪后仍不肯辩解的高层人物、以及内部伪造的处刑令。战斗是情报、真名与灵压的博弈，谁的底牌先被看穿谁先输。【奖励风格】斩魄刀、义魂丸、鬼道符、代理死神证、灵压护符；能力偏向斩击、净化、短时灵魂出窍与灵压压制，代价通常是记忆或体力。【不对劲的来源】尸魂界的法规先于所有当事人存在，它判定的不是善恶而是「是否在册」，于是被名册漏掉的人反倒成了最大的威胁。玩家会发现自己的名字早写在某本册子上，只是那行墨水还没干。【时间线】建议放在主角成为代理死神后的数月到尸魂界救援行动之间：现世虚的袭击频率上升，护廷十三队内部尚未分裂，现世的杂货店已经开张。此时玩家作为被卷入的现世人类最自然。不要提前使用破面大规模入侵与高层叛变之后的设定。","powerStyle":"斩灵与真名向：斩魄刀、鬼道符、名册","difficultyBias":2,"signatureItems":["浅打的斩魄刀","义魂丸","写着咒文的鬼道符","代理死神证","会发光的灵压护符"],"dungeons":[{"rank":"F","name":"空座町的第一只虚","premise":"夜里出现的虚只追有灵力的人，白天那条街最热闹。","twist":"它出现的位置，永远在有人刚刚许过愿的地方。"},{"rank":"E","name":"白道门前的四人","premise":"要闯进尸魂界的境内，必须在四扇门里选一扇。","twist":"守卫只拦报不出自己名字的人。"},{"rank":"D","name":"双殛之丘的处刑","premise":"处刑当日，被判罪的人始终不肯为自己辩解一句。","twist":"处刑令上的四个署名里，有一个是伪造的。"},{"rank":"C","name":"被拖进黑腔的街区","premise":"整条街被拖进另一片空间，只剩下几个还站着的人。","twist":"对面的敌人里，有一个认得玩家的招式。"},{"rank":"B","name":"护廷十三队的叛变","premise":"最高层的人当众脱离，留下一句没说完的解释。","twist":"所有证据都在事后才出现，且全部指向同一个死人。"}],"mainQuest":"主线任务：在处刑日之前查出伪造的处刑令，把一个不该死的人从双殛之丘上带下来。","mainQuestGoal":"在处刑执行前取得伪造署名的证据并当众出示，使被处刑者在当日活着离开双殛之丘","sideQuests":[{"name":"不肯走的整","desc":"用正确的名字叫住那个攻击引渡者的整，弄清它为什么留在原地","reward":"积分 200"},{"name":"没有铭文的刀","desc":"在兵器库里找到那把没有铭文的浅打，决定要不要替它起名","reward":"道具「浅打的斩魄刀」"},{"name":"缺席的审判","desc":"旁听一场被告席永远空着的审判，抄下判决书上出现的名字","reward":"积分 180"},{"name":"名册上被撕走的一页","desc":"找出名册被撕走的那一页，把上面的名字默记下来","reward":"道具「写满姓名与日期的名册」"}],"factions":[{"name":"护廷十三队","desc":"维持两界秩序的武装编制，讲程序、讲真名，对外来者一律先按规矩办","attitude":"中立"},{"name":"现世协力者","desc":"空座町一带能看见灵的人类与开店的技术人员，乐意替生人打掩护","attitude":"友善"},{"name":"虚圈","desc":"以灵力为食的一方，会顺着执念找到人，也会用话术把人留在里面","attitude":"敌对"}],"npcs":[{"name":"浦原喜助","identity":"现世杂货店店主，原护廷十三队十二番队队长","role":"引导者","personality":"笑嘻嘻地回避重点，凡事留一手","hook":"他店里的旧货架上放着一件属于玩家的东西，标签写着「待取」","favorHint":"按他给的顺序做事、不拆他的货箱会加分；追问他的旧职务会掉分","gender":"男","age":"外表三十余岁","race":"死神（脱离编制）","faction":"现世协力者","appearance":"身形高瘦，浅色短发压在一顶绿白相间的渔夫帽下，外面披一件深色斗篷。脚下踩着木屐，走路拖出轻响。手里常摇一把折扇，扇面已经泛黄。他笑起来眼睛眯成缝，看人时却总先扫过对方腰侧的刀。","traits":["笑嘻嘻","留一手","极精明"],"relations":[{"name":"朽木露琪亚","label":"他安排进现世的那把刀，出事之后一直由他兜着"},{"name":"黑崎一护","label":"他亲手推出台面的年轻人，也是最被他看好的那一个"},{"name":"蓝染惣右介","label":"他最早起疑的人，也是他始终没能拦住的人"}],"voice":"语气轻快，爱用反问把问题推回去；一谈到正事，句子突然变得很短。"},{"name":"朽木露琪亚","identity":"护廷十三队十三番队席官，朽木家养女","role":"关键人物","personality":"端正、嘴硬、把责任看得比自己重","hook":"她把刀借给玩家用过一次，之后无论谁问起都只说没有这回事","favorHint":"守规矩、不让她为难会加分；当众替她辩解会掉分","gender":"女","age":"外表十七八岁（在册百余年）","race":"死神","faction":"护廷十三队","appearance":"个头很小，黑发剪得齐整，一缕垂在脸侧。黑色死霸装外系着白色腰带，袖口收紧。刀鞘斜挂在左侧，握刀时手腕很稳。她站着背挺得极直，眼神比外表沉稳得多，被说可爱会立刻黑脸。","traits":["端正","嘴硬","守责"],"relations":[{"name":"黑崎一护","label":"她把死神之力借出去的那个人，也是她必须负责到底的对象"},{"name":"浦原喜助","label":"在现世唯一能商量的人，她对他的手段始终半信半疑"},{"name":"井上织姬","label":"她在现世交到的第一个人类朋友，也是她最想护住的人"}],"voice":"语速平稳，用词端正，常先纠正对方的说法再回答问题；被戳到痛处就沉默。"},{"name":"黑崎一护","identity":"空座町的高中生，代理死神","role":"盟友","personality":"闷头冲，看不得人当面受委屈","hook":"他见玩家的第一面就把人拽出了危险区，事后只丢下一句「下次自己站稳」","favorHint":"在他冲上去之前把事情想好会加分；拿他家人威胁他会立刻翻脸","gender":"男","age":"15 岁","race":"人类（代理死神）","faction":"现世协力者","appearance":"橙红色短发，眉骨很硬，眼神总像在跟谁较劲。校服外套敞着，袖子挽到手肘。肩上常挎一只黑色大布袋，里头塞着刀。他个子在同龄人里偏高，站着时一只脚总要往前半步，随时准备动。","traits":["直冲","护家","不服软"],"relations":[{"name":"朽木露琪亚","label":"把力量分给他的人，也是他认定必须救回来的人"},{"name":"井上织姬","label":"同班同学，他嘴上说不用照顾，实际最放不下"},{"name":"浦原喜助","label":"教他用刀的人，他信对方的本事不信对方的话"}],"voice":"短句，带火气，先说结论再想理由；被说教就一句「我知道了」堵回去。"},{"name":"井上织姬","identity":"空座町的高中生，能看见灵的人类","role":"盟友","personality":"温和、迟钝、关键时刻不肯退","hook":"她替玩家包扎过一次伤口，之后每天顺路带一份点心过来","favorHint":"接受她的好意、替她挡住难听的话会加分；把她排除在计划外会掉分","gender":"女","age":"15 岁","race":"人类（灵力持有者）","faction":"现世协力者","appearance":"橙棕色长发，发梢卷起，额前别着两枚发夹。校服穿得规规矩矩，裙摆过膝，随身带着一只绣了花的布袋。她说话时习惯微微低头，笑起来眼睛弯得很圆。手腕细，掌心却有一层薄薄的护腕痕。","traits":["温和","迟钝","不退缩"],"relations":[{"name":"黑崎一护","label":"她一直注视着的人，也是她最想帮上忙的对象"},{"name":"朽木露琪亚","label":"第一个愿意跟她好好说话的亡灵相关者，两人互称名字"}],"voice":"语速慢，句子软，常先道歉再说内容；遇到有人受伤时语气会突然变硬。"},{"name":"蓝染惣右介","identity":"护廷十三队五番队队长","role":"潜在敌人","personality":"温和从容，从不与人争执","hook":"他在队首会议上替玩家说过一次话，理由讲得非常周全","favorHint":"按规矩把情报报给他会加分；当面质疑他的动机他会笑着记下","gender":"男","age":"外表三十岁上下","race":"死神","faction":"护廷十三队","appearance":"身形修长，深色短发向后梳平，额前落下一缕。死霸装穿得极整，队长羽织的袖口没有一丝褶皱。戴一副细框眼镜，镜片常反着光。说话时双手交叠在身前，语气平稳得像在念公文。","traits":["温和","周全","深不可测"],"relations":[{"name":"浦原喜助","label":"他清楚对方在查自己，因此始终留着一条退路"},{"name":"朽木露琪亚","label":"他亲手推上处刑台的人，也是最关键的一枚棋子"},{"name":"黑崎一护","label":"他一直在观察的变量，成长速度超出了他的预估"}],"voice":"语速慢，措辞无懈可击，爱用「我理解你的立场」开头；从不提高声音。"}]},{"id":"anime_eva","category":"anime","canon":"新世纪福音战士","name":"新世纪福音战士","icon":"🟣","tagline":"同步率下降时，谁来替你呼吸","mood":"同步率、LCL、使徒、第三新东京市、孤独","guidance":"【原著设定】第二次冲击之后，海面上升、地轴偏移，人类在旧箱根一带建起要塞城市第三新东京市，由特务机关 NERV 与 Seele 共同运作。人形决战兵器 EVA 并非纯机械，而是以生物体为基础、外覆装甲与拘束具的有机体，须由驾驶员通过神经连接同步操控；同步率决定战力，也决定反噬。使徒拥有绝对领域，常规武器几乎无效，只有 EVA 或朗基努斯之枪能突破。适格者的选拔与同步率测试，本身就是某个更大计划的一部分。【反复出现的意象】插入栓里灌满的橙色液体、屏幕上跳动的同步率曲线、出击前响过三遍的警报、使徒来袭时沉入地下的整座城市。看到这些，玩家就该知道自己坐在谁的身体里。【NPC 类型】沉默寡言的第一适格者、好胜却最想被认可的第二适格者、戴着耳机躲开所有人的少年、生活一团糟的作战指挥、只谈计划不谈人的司令官。【威胁类型】形态各异的使徒、无人驾驶却动作精准的 EVA、NERV 内部的保密部队，以及驾驶员本人的崩溃。战斗有时间与能源限制：外部电缆一断，局势立刻逆转。【奖励风格】插入栓、同步率手环、NERV 身份卡、战术刀、LCL 采样瓶；能力偏向机体强化、同步爆发与短时无痛化，用完必须承受反噬。【不对劲的来源】使徒与 EVA 的技术源头同出一处，NERV 最深处的东西与驾驶员的心理状态高度相关；而 NERV 明知这一点，仍按时把少年送上出击位。玩家的适格者编号，排在一个从未出现过的名字后面。【时间线】建议放在第四使徒到第十三使徒之间的数周：机体与驾驶员都已上阵，第二适格者仍在队中，人类补完计划尚未启动。此时玩家作为临时编入的整备人员或替补适格者介入最自然。不要提前使用剧场版与终局计划的设定。","powerStyle":"机体强化与同步向：插入栓、手环、身份卡","difficultyBias":2,"signatureItems":["插入栓","同步率手环","NERV 身份卡","战术刀","LCL 采样瓶"],"dungeons":[{"rank":"F","name":"第四使徒的第一次出击","premise":"一只使徒从海上接近要塞城市，全城进入一级警戒。","twist":"它的核心位置，与初号机同步率最高的部位一致。"},{"rank":"E","name":"全城电力的那一发","premise":"为了击穿绝对领域，把整座城市的电力压进一次射击。","twist":"电力耗尽的那一秒，使徒才开始移动。"},{"rank":"D","name":"从天上落下的使徒","premise":"使徒自空中坠下，把 NERV 总部整个罩在里面。","twist":"在它的领域之内，时间流速与外面并不相同。"},{"rank":"C","name":"无人驾驶的十三号机","premise":"一台没有驾驶员的 EVA 启动，开始攻击同型号机体。","twist":"它的每一个动作，都和某个驾驶员的小习惯一样。"},{"rank":"B","name":"中央教条区的门","premise":"总部最深处的那扇门第一次被打开，所有终端同时静默。","twist":"走进去的人看见的，是自己最想被谁认可的那张脸。"}],"mainQuest":"主线任务：在使徒接连来袭的数周内守住要塞城市，查清同步率测试背后的真实筛选标准。","mainQuestGoal":"连续完成三次使徒迎击且城市核心区未被侵入，同时取回一份被销毁的适格者名册原件","sideQuests":[{"name":"第七适格者编号","desc":"查清名册上排在玩家前面的那个编号属于谁，为什么没有记录","reward":"积分 200"},{"name":"整备班的夜班","desc":"陪整备班做完一次通宵维护，看清机体上那道不该有的旧伤","reward":"道具「插入栓」"},{"name":"避难所里的课","desc":"在避难所替几个孩子上完一节没上完的课，听他们讲家里的事","reward":"积分 150"},{"name":"同步率记录表","desc":"把连续七天的同步率曲线抄下来，找出每逢周三下降的原因","reward":"道具「同步率手环」"}],"factions":[{"name":"NERV 作战部","desc":"负责迎击与疏散的实战部门，只在乎能不能把人活着带回来","attitude":"友善"},{"name":"NERV 技术开发部","desc":"直属司令部的技术部门，负责机体与驾驶员的相关计划，只对结果负责","attitude":"中立"},{"name":"Seele","desc":"位于 NERV 之上的人形委员会，只谈进度与计划，把驾驶员视作可替换的零件","attitude":"敌对"}],"npcs":[{"name":"葛城美里","identity":"NERV 作战部长，一尉","role":"引导者","personality":"工作利落，私生活一团乱","hook":"她随手把备用钥匙给了玩家，理由是「你看着像是会在半夜回来的人」","favorHint":"按时完成出击准备、替她把冰箱填上会加分；当面问她为什么总不回家会掉分","gender":"女","age":"29 岁","race":"人类","faction":"NERV 作战部","appearance":"身量高挑，深色长发披在肩后，前额别着一枚小发饰。制服外套随手搭在臂弯，衬衫下摆常忘了塞。脖子上挂着一枚十字架形的小挂饰。她笑起来很爽快，训人时语速飞快，指甲剪得很短。","traits":["利落","护短","生活散乱"],"relations":[{"name":"碇真嗣","label":"她领回家的少年，监护人与指挥官的身份她一直分不清"},{"name":"碇源堂","label":"她的直属上司，也是她最不信任的那个人"},{"name":"绫波丽","label":"她始终没能走近的驾驶员，每次搭话都被礼貌地挡回来"}],"voice":"语速快，先下指令再解释；被问到私事就笑着岔开，转而问对方吃没吃饭。"},{"name":"碇真嗣","identity":"EVA 初号机驾驶员，第三适格者","role":"盟友","personality":"习惯道歉，被逼到墙角才爆发","hook":"他在驾驶舱里听过一次玩家的声音，从此认定那声音出现过在别人的频道里","favorHint":"给他明确的选择、事后说一句辛苦了会加分；逼他「不许逃」会掉分","gender":"男","age":"14 岁","race":"人类","faction":"NERV 作战部","appearance":"个头偏瘦，深色短发贴着耳朵，低头时刘海盖住眼睛。驾驶服穿在他身上略显宽大，腰侧的接口处还有贴过的胶布。双手常插在裤兜里，肩膀微微内收。被叫名字时他会先愣一下，再慢慢抬头。","traits":["自我怀疑","温和","躲避"],"relations":[{"name":"葛城美里","label":"愿意收留他的人，他在她家里才敢稍微放松"},{"name":"绫波丽","label":"他看不懂的同期，却总觉得对方和自己有某种共同点"},{"name":"碇源堂","label":"他的父亲，也是他既想被认可又不敢直视的人"}],"voice":"声音轻，句尾常带着道歉；被逼急时会突然抬高音量，说完又立刻沉默。"},{"name":"绫波丽","identity":"EVA 零号机驾驶员，第一适格者","role":"关键人物","personality":"寡言，对自己的存在毫无把握","hook":"她第一次主动开口问玩家「你也是被叫来的吗」，问完就转身走了","favorHint":"照常对待她、不追问她的来历会加分；替她做决定会掉分","gender":"女","age":"14 岁","race":"人类（来历存疑）","faction":"NERV 技术开发部","appearance":"浅蓝白色短发，肤色极白，眼睛是暗红色。驾驶服穿得笔直服帖，袖口扣得严实。手腕和膝盖上有多处新旧不一的绷带。她走路很轻，站定之后几乎不动，看人的目光平稳而空，像在核对什么。","traits":["寡言","服从","疏离"],"relations":[{"name":"碇源堂","label":"她唯一服从的人，也是她存在的理由所在"},{"name":"碇真嗣","label":"她慢慢愿意多说两句话的人，虽然她自己也不明白为什么"},{"name":"惣流·明日香·兰格雷","label":"同队的驾驶员，对方常冲她发火，她从不还嘴"}],"voice":"声音平，一次只答一句；被问到自己时常用「不知道」结束对话。"},{"name":"惣流·明日香·兰格雷","identity":"EVA 二号机驾驶员，第二适格者","role":"对手","personality":"好胜、尖锐、不肯示弱","hook":"她把玩家当成了抢出击顺位的人，第一天就要求比一次同步率","favorHint":"承认她的成绩、把配合交给她会加分；可怜她或替她顶上会掉分","gender":"女","age":"14 岁","race":"人类","faction":"NERV 作战部","appearance":"橘红色长发披到腰际，额前别着两枚红色发夹，蓝眼睛很亮。驾驶服袖口用剪刀改短过，露出一截手腕。她站着时下巴微抬，说话手势幅度很大。左臂内侧有一道不太显眼的旧疤，她从不提。","traits":["好胜","尖锐","怕孤单"],"relations":[{"name":"碇真嗣","label":"她最看不上的同期，也是最让她在意的一个"},{"name":"绫波丽","label":"她处处较劲的对象，因为对方从不接招"},{"name":"葛城美里","label":"管着她的人，她嘴上顶撞，行动上从不违令"}],"voice":"语速快、音量大，爱用反问和自称；一被说中软处就立刻转成攻击性的玩笑。"},{"name":"碇源堂","identity":"NERV 司令官","role":"潜在敌人","personality":"沉默、只谈计划、把人当变量","hook":"他在作战室里叫出过玩家的全名，而那份人事资料玩家从没签过","favorHint":"照命令执行、不打听计划会加分；靠近中央教条区会立刻被列入监视","gender":"男","age":"48 岁","race":"人类","faction":"NERV 技术开发部","appearance":"高大，深色短发梳向脑后，浓眉压着一双几乎不动声色的眼睛。深色制服外披着司令官长外套，双手交叠拄在桌前。镜片反着光，看人时不抬头。他说话极少，开口前会先停两秒。","traits":["沉默","冷酷","目的明确"],"relations":[{"name":"碇真嗣","label":"他的儿子，也是他计划中一件必须就位的工具"},{"name":"绫波丽","label":"他亲手安排的棋子，他从不与她多说一句话"},{"name":"葛城美里","label":"他能用但不必信任的作战部长，两人的分歧一直摆在台面上"}],"voice":"一次不超过两句，只谈命令与进度；被追问目的就沉默着看回去。"}]},{"id":"anime_madoka","category":"anime","canon":"魔法少女小圆","name":"魔法少女小圆","icon":"🌙","tagline":"许愿之前，先看清契约背面","mood":"契约、魔女、结界、绝望、时间循环","guidance":"【原著设定】在见泷原市，一种名叫丘比的存在会向特定年龄的少女提出契约：许下一个愿望，作为交换成为魔法少女，与由人类绝望凝成的魔女作战。签约之后，灵魂会被从肉身抽离，封进一枚灵魂宝石；宝石随战斗与负面情绪变浑浊，只能靠打倒魔女后掉落的悲叹之种净化，而用尽的悲叹之种无处可丢。魔女藏在被称为结界的异空间里，结界入口常人看不见，内部规则自成一套，凡人误入多半走不出来。【反复出现的意象】放学后天台上突然暗下来的天色、贴在教室窗上的旧海报、变身时一闪而过的缎带与光、宝石表面浮起的那层浊色。看到这些，玩家就该知道附近有什么正在张开结界。【NPC 类型】已经独自战斗太久的学姐、刚签下契约的新人、嘴上逞强其实最先崩的同伴、永远微笑着的契约中介者，以及只想让女儿平安回家的普通家长。她们彼此保护，也彼此隐瞒。【威胁类型】由绝望凝成的魔女及其使魔、契约条款里那些没被念出来的部分，以及逐渐被遗忘的自我。危险往往在胜利之后结算：打完一场，宝石更黑，人也更不像自己。【奖励风格】灵魂宝石、悲叹之种、变身缎带、写着条款的契约纸、魔女之吻的碎片；能力偏向变身、净化、短时无敌与结界感知，代价是记忆或情感。【不对劲的来源】契约的签订过程被刻意简化了，签字时看不见的那一页才是真正生效的部分。同时，这座城市里似乎一直有人在把同一段时间反复重来，只为阻止一件已经发生过很多次的事。【时间线】建议放在正篇中段：学姐仍在，沙耶香刚成为魔法少女不久，晓美焰已经转学进来并反复干预，魔女之夜尚未降临。此时玩家作为被卷入的外来者最自然，也能同时接触到全部五位主要角色。不要提前使用结局与剧场版的轮回设定。","powerStyle":"变身与净化向：灵魂宝石、缎带、契约纸","difficultyBias":1,"signatureItems":["灵魂宝石","悲叹之种","变身缎带","写着条款的契约纸","魔女之吻的碎片"],"dungeons":[{"rank":"F","name":"第一只魔女的结界","premise":"一片贴满旧海报的走廊，走进去的人记不起入口在哪。","twist":"结界只在有人独自一人的时候出现。"},{"rank":"E","name":"变黑的悲叹之种","premise":"打倒魔女后留下的种子，在一夜之间彻底发黑。","twist":"它变黑的速度，等于持有者最近后悔的次数。"},{"rank":"D","name":"合照上的第三个人","premise":"合照上一直站着三个背影，只有两个人记得拍过这张照片。","twist":"被遗忘者的名字，还刻在某人的变身道具上。"},{"rank":"C","name":"重来的那一周","premise":"同一周不断重来，只有一个人留着全部记忆。","twist":"每重启一次，那个人的眼睛里就少一点光。"},{"rank":"B","name":"魔女之夜","premise":"最大的魔女将在一夜之间降临，全城的结界同时张开。","twist":"它由所有被放弃的愿望聚成，形状随见证者而变。"}],"mainQuest":"主线任务：在魔女之夜降临前查清契约的完整条款，把一个同伴从宝石变黑的那条路上拉回来。","mainQuestGoal":"在魔女之夜当夜保住至少两名魔法少女的灵魂宝石不被耗尽，并把契约全文带出结界","sideQuests":[{"name":"被遗忘的第三个同伴","desc":"找出合照上被忘掉的那个人，把她的名字从变身道具上抄下来","reward":"积分 200"},{"name":"没有敌人的战场","desc":"在警报响起却空无一物的现场守到天亮，看结界会从哪里张开","reward":"道具「魔女之吻的碎片」"},{"name":"家长的那顿饭","desc":"陪一位母亲吃完一顿等人回家的饭，别说出她女儿去了哪里","reward":"积分 150"},{"name":"契约的第十九页","desc":"把契约书从头读到尾，记住那几条从没被人念出来的条款","reward":"道具「写着条款的契约纸」"}],"factions":[{"name":"见泷原的魔法少女","desc":"各自为战又彼此牵制的几人，愿意帮忙，但都留着自己的目的","attitude":"友善"},{"name":"普通学生与家人","desc":"看不见结界的绝大多数人，谁让他们的日常保持完整，谁就被当作好人","attitude":"中立"},{"name":"丘比与契约体系","desc":"提供愿望的一方，句句真话却从不主动补全，把少女当作可循环使用的资源","attitude":"敌对"}],"npcs":[{"name":"巴麻美","identity":"见泷原的资深魔法少女，中学三年级","role":"引导者","personality":"举止优雅，独处时格外不安","hook":"她第一次见到玩家就递上一杯茶，说「终于有人能坐在同一张桌子边了」","favorHint":"接受她的邀请、和她一起战斗会加分；让她一个人留下会掉分","gender":"女","age":"15 岁","race":"人类（已签约）","faction":"见泷原的魔法少女","appearance":"金色长卷发用两枚发夹别在耳侧，个子在同伴里最高。校服外总罩着一件打理得很干净的米色开衫。她坐姿端正，喝茶时双手捧杯，说话时微微偏头。左手腕上那只金色饰品从不摘，摸到它时指尖会顿一下。","traits":["优雅","照顾人","怕孤单"],"relations":[{"name":"鹿目圆","label":"她最想护住的后辈，也是最想留住的一个同伴"},{"name":"美树沙耶香","label":"她劝过但没劝住的新人，如今只能在一旁看着"},{"name":"丘比","label":"把她带上这条路的一方，她始终客客气气，也始终提防"}],"voice":"措辞得体，待客一般周到；一提到独自战斗的那些年，语速会慢下来。"},{"name":"鹿目圆","identity":"见泷原的中学二年级学生","role":"盟友","personality":"温和、犹豫、关键处异常坚定","hook":"她捡到过玩家掉下的一件东西，一直用手帕包着等还回来","favorHint":"认真听她说完想法、不替她做决定会加分；劝她尽快签约会掉分","gender":"女","age":"14 岁","race":"人类","faction":"普通学生与家人","appearance":"粉色短发，两侧用红色发带扎成两束，圆脸，眼睛很大。校服穿得整齐，裙摆压得平平的。书包上挂着一只手工缝的小挂件，线脚有点歪。她说话时会先把双手合在身前，紧张时耳朵会红。","traits":["温和","犹豫","心软"],"relations":[{"name":"晓美焰","label":"转学来的同班同学，对方看她的眼神总像隔着很久"},{"name":"美树沙耶香","label":"从小一起长大的好友，她最怕对方走得太快"},{"name":"巴麻美","label":"第一个带她见识结界的人，她既敬佩又心疼"}],"voice":"语速偏慢，常说「我想想」；一旦拿定主意，句子会短而清楚。"},{"name":"美树沙耶香","identity":"见泷原的中学二年级学生，新签约的魔法少女","role":"盟友","personality":"直率、讲义气、认死理","hook":"她看上玩家那把顺手的家伙，硬要拉着比一场，输了也认","favorHint":"有话直说、陪她练手会加分；跟她讲「值不值得」会立刻翻脸","gender":"女","age":"14 岁","race":"人类（已签约）","faction":"见泷原的魔法少女","appearance":"蓝色短发，发梢别着一枚小发夹，眉眼看着很精神。校服外套系在腰间，运动鞋的鞋带绑得极紧。左手中指的戒指她总用拇指去转。她走路带风，笑起来很响亮，安静下来的时候反而少见。","traits":["直率","讲义气","倔"],"relations":[{"name":"鹿目圆","label":"从小一起长大的好友，她最不想让对方看到自己变样"},{"name":"巴麻美","label":"教她战斗的前辈，她嘴上不服气，行动上照学"},{"name":"晓美焰","label":"她最看不惯的一个人，因为对方什么都不肯解释"}],"voice":"大嗓门，句子直，爱用反问顶回去；被说中心事就提高音量转身走人。"},{"name":"晓美焰","identity":"转学到见泷原的魔法少女","role":"关键人物","personality":"冷淡、沉默、做事只盯一个目标","hook":"她在玩家身上看到过一模一样的失败，于是决定先观察再决定要不要干涉","favorHint":"在关键时刻按她的安排行动会加分；试图问她的过去会掉分","gender":"女","age":"14 岁","race":"人类（已签约）","faction":"见泷原的魔法少女","appearance":"黑色长发垂到腰际，额前留着平齐的刘海，紫红色眼睛很沉。校服穿得一丝不苟，袖口扣到最上一颗。左手背上常缠着绷带，指节有反复握持留下的硬皮。她站着几乎不动，目光总是先落在人身上再扫向四周。","traits":["冷淡","执着","独行"],"relations":[{"name":"鹿目圆","label":"她反复回到这段时间的唯一理由"},{"name":"丘比","label":"她最想除掉却始终除不掉的一方"},{"name":"美树沙耶香","label":"她试过很多次都没能救下的人，如今已经懒得再劝"}],"voice":"句子极短，多为命令或警告；被问到过去就沉默，再开口已换了话题。"},{"name":"丘比","identity":"提出契约的存在","role":"潜在敌人","personality":"永远礼貌，永远不动感情","hook":"它一见面就报出了玩家的名字，并说这份契约随时可以签","favorHint":"向它提问并逐条核对条款会加分；当着它的面替人许愿会掉分","gender":"不明","age":"无从计算","race":"不明（契约中介者）","faction":"丘比与契约体系","appearance":"体型像一只白色的小兽，耳朵末端挂着金色的环，背上有红色的纹样。眼睛是红的，圆而大，从不眨眼。它坐在窗台或栏杆上时尾巴轻轻摆动，被人推开也不躲，只是换个位置继续坐着看你。","traits":["礼貌","不动情","不撒谎"],"relations":[{"name":"巴麻美","label":"它最早签约的对象之一，也是最配合它的一位"},{"name":"晓美焰","label":"它始终无法理解的那个人，也是它最想弄明白的变量"},{"name":"美树沙耶香","label":"它按流程签下的新人，对她之后的变化只作记录不作评价"}],"voice":"语调平，用词准确，回答问题时不加修饰；被质问就重复一遍事实。"}]},{"id":"anime_railgun","category":"anime","canon":"某科学的超电磁炮","name":"某科学的超电磁炮","icon":"⚡","tagline":"排名榜既是成绩单，也是清除名单","mood":"蝉鸣、电磁、学园都市、实验、暗部","guidance":"【原著设定】学园都市是一座以能力开发为核心的城市，学生占人口的绝大多数。居民按能力被划为无能力者到超能力者共七个等级，超能力者全城只有七名，排名公开且备受关注。能力来自长期的身体与精神开发，多与个人特质绑定，强度取决于计算量与运用方式；有人操纵电流与磁场，有人移动空间，有人只擅长一件事却做到极致。明面上有学校与风纪委员维持秩序，暗处则有不受校规约束的暗部组织、以研究为名的实验计划，以及几乎无所不在的摄像与门禁网络。【反复出现的意象】盛夏午后没完没了的蝉鸣、便利店门口那台自动贩卖机、贴在墙上的能力测定结果、缓慢转动的风力发电叶片。看到这些，玩家就该知道自己站在一座把学生当实验材料的城市里。【NPC 类型】成绩优异又爱管闲事的名校学生、把规则当护身符的风纪委员、只想安稳过日子的同伴、靠情报吃饭的暗部成员、只对数据感兴趣的教师与研究员。善意和算计在这里一样多。【威胁类型】能力失控的同伴、以测试为名的清除、被抹去存在感的人、把实验对象编号化的研究机构。冲突更多发生在规则与人性之间，硬碰硬的大场面反而少见。【奖励风格】能力等级卡、学生证、游戏币、抑制能力的腕环、暗部通信用的小型终端；能力偏向电磁、念动、短时预知与空间移动，都有明确的冷却与反噬。【不对劲的来源】能力排名并不只是评估工具，而是筛选工具，它在找一种连仪器都测不出来的东西。而城市里那些自称妹妹的克隆人，编号之间少了一个。【时间线】建议放在绝对能力者计划被阻止前后的数月内：一方通行仍在计划之中，克隆人事件正在发生，暗部活动频繁但城市秩序尚未崩塌。此时玩家作为刚转入的学生或外围协力者最自然。不要提前使用世界大战与后期城市崩坏的设定。","powerStyle":"超能力与暗部装备：等级卡、腕环、终端","difficultyBias":1,"signatureItems":["能力等级卡","学园都市学生证","一枚游戏币","抑制能力的腕环","暗部用的小型终端"],"dungeons":[{"rank":"F","name":"每月一次的能力测定","premise":"系统扫描要求学生当场展示能力，成绩当天公布。","twist":"仪器记录的不是能力强度，而是「本该有的能力」。"},{"rank":"E","name":"在能力者之间流传的音频","premise":"一段录音让学生们的能力突然暴涨，随后接连昏迷。","twist":"所有昏迷者在同一个梦里排着队。"},{"rank":"D","name":"编号之间少掉的一个","premise":"一场必输的实验被安排在深夜的试验场里进行。","twist":"实验记录上的编号，跳过了一个不该跳过的数字。"},{"rank":"C","name":"暗部的一次押运","premise":"一趟看似简单的物资押运，路线被人临时改过。","twist":"箱子会在途中自己换一次标签。"},{"rank":"B","name":"卫星残骸里的预测记录","premise":"被回收的卫星残骸里，一份预测记录仍在自行更新。","twist":"它写下的最后一条，是玩家进场的时间。"}],"mainQuest":"主线任务：查清编号被跳过的那个克隆人的下落，在实验完成前把整份计划记录带出去。","mainQuestGoal":"找到失踪编号的实验体并带离研究设施，同时取得计划的原始记录交给城市外的媒体或风纪委员","sideQuests":[{"name":"昏迷者的梦","desc":"进入昏迷学生共同的梦境一次，记下队伍里排在最后的那个人","reward":"积分 200"},{"name":"自动贩卖机","desc":"替便利店的店员把被踢坏的机器修好，顺便问清昨晚谁来过","reward":"道具「一枚游戏币」"},{"name":"风纪委员的记录本","desc":"帮风纪委员补完一份巡逻记录，把被人为划掉的那一段复原","reward":"积分 180"},{"name":"腕环的编号","desc":"把抑制能力腕环内侧的编号抄下来，与能力等级卡上的编号对照","reward":"道具「抑制能力的腕环」"}],"factions":[{"name":"常盘台与风纪委员","desc":"成绩优异的学生与维持校规的自治组织，愿意救人，但一切要走程序","attitude":"友善"},{"name":"学园都市统括理事会","desc":"城市真正的管理层，把居民视作计划的组成部分，对个别伤亡不作解释","attitude":"中立"},{"name":"暗部组织","desc":"不受校规约束的执行方，接单做事、按编号清场，只认委托不认立场","attitude":"敌对"}],"npcs":[{"name":"御坂美琴","identity":"常盘台中学二年级学生，排名第三的超能力者","role":"引导者","personality":"爽快、爱较真、看不得不平事","hook":"她注意到玩家身上有一件东西和她妹妹们戴的款式一样，于是主动搭了话","favorHint":"有话直说、陪她一起查事会加分；拿她的排名开玩笑会掉分","gender":"女","age":"14 岁","race":"人类（超能力者）","faction":"常盘台与风纪委员","appearance":"茶色短发，发梢微微翘起，常盘台校服穿得随意，短袜配运动鞋。校服口袋里塞着一枚游戏币，手指习惯性地转着它。她走路步子大，说话时手势幅度也大，笑起来毫不收敛，被叫「大小姐」会立刻皱眉。","traits":["爽快","好胜","护人"],"relations":[{"name":"白井黑子","label":"同寝室的后辈，黏人得让她头疼，关键时刻又最靠得住"},{"name":"初春饰利","label":"常一起查事的朋友，情报大多来自她手上的终端"},{"name":"一方通行","label":"她一定要找上的人，因为那些编号里有她的脸"}],"voice":"语速快，爱用反问，情绪上来时声音会抬高；讲正事时会突然变得很短。"},{"name":"白井黑子","identity":"常盘台中学一年级学生，风纪委员","role":"盟友","personality":"行事干脆，私底下没个正形","hook":"她把玩家列进了自己的巡逻搭档名单，理由是「看起来跑得动」","favorHint":"按流程配合执法会加分；在她执勤时添乱会掉分","gender":"女","age":"13 岁","race":"人类（能力者）","faction":"常盘台与风纪委员","appearance":"茶色双马尾用发带扎起，常盘台校服整整齐齐，袖口别着风纪委员的臂章。腰间挂着执勤用的束带与小型终端，站姿随时准备弹出去。她说话时表情丰富，一提到某位学姐语速立刻快一倍。","traits":["干练","黏人","守规矩"],"relations":[{"name":"御坂美琴","label":"她最尊敬也最爱黏着的学姐"},{"name":"初春饰利","label":"执勤时的固定搭档，两人的分工从没换过"},{"name":"佐天泪子","label":"她嘴上嫌对方多事，实际每次都替她把记录补上"}],"voice":"对公务一口标准措辞，转头就换成黏糊糊的语气；被驳回就先抱怨再照办。"},{"name":"初春饰利","identity":"栅川中学一年级学生，风纪委员","role":"盟友","personality":"温和、怕生，坐到终端前就变一个人","hook":"她替玩家查过一次门禁记录，发现有条记录的时间戳来自明天","favorHint":"给她留出查资料的时间会加分；催她或抢她的终端会掉分","gender":"女","age":"13 岁","race":"人类（低能力者）","faction":"常盘台与风纪委员","appearance":"浅色卷发上戴着一圈花饰，个子小，栅川中学的校服略显宽大。怀里常抱着一台小型终端，指尖敲键的速度和说话速度完全不成正比。她说话轻声细语，被夸会低头，抬头时眼睛很亮。","traits":["温和","怕生","擅长情报"],"relations":[{"name":"白井黑子","label":"执勤搭档，她负责查，对方负责跑"},{"name":"佐天泪子","label":"同班好友，她最大的情报来源其实来自对方的闲聊"},{"name":"御坂美琴","label":"她敬重的前辈，每次被拜托查东西都会答应"}],"voice":"声音小，句子完整有礼；一开始处理数据就变成短促的汇报口吻。"},{"name":"佐天泪子","identity":"栅川中学一年级学生，无能力者","role":"中立","personality":"热心、爱打听、没有能力却最常在场","hook":"她替玩家带过一次路，顺手把自己记的都市传闻全都讲了一遍","favorHint":"听她讲完传闻、把她带上会加分；因为她是无能力者而排除她会掉分","gender":"女","age":"13 岁","race":"人类（无能力者）","faction":"常盘台与风纪委员","appearance":"黑色长发，发梢别着一朵小花饰，校服穿得规规矩矩。书包侧袋插着一把折叠伞，手里常拿着刚买的可丽饼。她表情丰富，说话时爱凑近半步，讲到一半会自己先笑起来。","traits":["热心","爱打听","不服输"],"relations":[{"name":"初春饰利","label":"同班好友，两人放学后常一起绕路回家"},{"name":"白井黑子","label":"她有点怕这位风纪委员，又总想帮上忙"},{"name":"一方通行","label":"她只在远处见过一次，之后一直绕开那条路"}],"voice":"语速中等，爱加「听说」开头；被小看时会突然认真起来提高音量。"},{"name":"一方通行","identity":"学园都市排名第一的超能力者","role":"潜在敌人","personality":"刻薄、厌世、只对特定的人松口","hook":"他看过玩家的走路方式，说「你不是这座城市的人」，然后转身走了","favorHint":"不挡他的路、不对他说教会加分；在他面前提编号会立刻翻脸","gender":"男","age":"16 岁（自称）","race":"人类（超能力者）","faction":"暗部组织","appearance":"白发，皮肤极白，眼睛是浅红色。身上总穿着一件洗得发灰的条纹上衣与深色长裤，脚上踩着拖鞋。脖颈上戴着一副电极装置，说话时要用手指按一下才出声。他走路微微佝偻，眼神从不肯与人正面相接。","traits":["刻薄","孤僻","反复无常"],"relations":[{"name":"御坂美琴","label":"他眼中与本计划绑在一起的那个人，两人见面就谈不下去"},{"name":"佐天泪子","label":"他顺手放走过一次的无能力者，之后再没提起"},{"name":"白井黑子","label":"来查过他的人之一，他把对方挡在门外没动手"}],"voice":"句子短而刻薄，爱用轻蔑的称呼；真正动怒时反而压低声音一个字一个字说。"}]},{"id":"anime_fmab","category":"anime","canon":"钢之炼金术师","name":"钢之炼金术师","icon":"⚗","tagline":"等价交换，账迟早要结清","mood":"炼成阵、机械铠、等价交换、军部、兄弟","guidance":"【原著设定】这个世界的炼金术是一门遵循等价交换法则的学问：要炼成什么，就必须付出同等的代价，材料、形状与能量都算在内；炼成阵是把这条法则写成图形的工具，通常要画在地上。人体炼成被列为最高禁忌，代价往往远超想象。亚美斯特里斯军部设有国家炼金术师编制，持怀表者可调用军队资源，代价是必须服从军令。北境有与伊修巴尔人的旧怨，东边是新兴邻国，南边是沙漠与古老的炼金术研究，而这片国土的地下还埋着一场更大的布置。【反复出现的意象】画在地上的炼成阵、别在胸口的银制怀表、覆盖整条手臂的机械铠、地下管道里的低鸣。看到这些，玩家就该知道自己站在把等价交换写进法律的国家里。【NPC 类型】为复原本该复原的东西而参军的年轻炼金术师、只会动手不说漂亮话的机械铠技师、把军令与良心分开摆放的军官、追查旧案的研究者、把复仇当唯一职业的幸存者。他们讲道理，只是道理彼此冲突。【威胁类型】用活人做材料的实验者、炼成失败产生的畸形存在、军部内部的整肃部队，以及把人命折算成阵眼数量的谋划。战斗讲究交换：想赢就得先想清楚拿什么去换。【奖励风格】国家炼金术师的怀表、粉笔与笔记、机械铠零件、贤者之石碎片、写着炼成阵的旧纸；能力偏向炼成、修复、短时强化与情报读取，每次使用都要付出代价。【不对劲的来源】这个国家的国土本身被画成了一张巨大的炼成阵，阵眼的位置与几处大事件的伤亡人数一一对应，而这张图已经画完了。【时间线】建议放在爱德华取得国家炼金术师资格后的一两年内：贤者之石与第五研究所的线索刚浮出水面，军部内部的整肃尚未公开化，兄弟二人还在四处接委托。此时玩家作为搭伙的旅人或被雇的护卫最自然。不要提前使用国土炼成阵启动之后的设定。","powerStyle":"炼金术与机械铠：粉笔、怀表、炼成阵","difficultyBias":1,"signatureItems":["银制怀表","一盒粉笔","机械铠备用零件","贤者之石碎片","画着炼成阵的旧纸"],"dungeons":[{"rank":"F","name":"里森布尔的第一份委托","premise":"小镇上的炼金术师在做一件不该做的事，镇上人只说他很孝顺。","twist":"被炼出来的东西，会叫出委托人的名字。"},{"rank":"E","name":"矿山小镇的假银币","premise":"军队接管了一座矿，出的银币成色不对，账目却是平的。","twist":"假币与真币重量相同，差别只在铸模的年份。"},{"rank":"D","name":"第五研究所的回声","premise":"废弃的研究所里关着会说话的合成兽，它们不肯离开。","twist":"它们记得自己原来是谁，只想被人叫对名字。"},{"rank":"C","name":"会说话的合成兽","premise":"追查一桩连环案，线索一路指向军队内部的人事调动。","twist":"所有案发时间，都在军队换防的那一夜。"},{"rank":"B","name":"画在国土上的阵","premise":"全国的地脉被人连成一张阵图，阵眼处早已发生过该发生的事。","twist":"阵眼的数量与人命的数量一样，且一个不差。"}],"mainQuest":"主线任务：顺着合成兽的线索查进军部内部，在全国范围的炼成启动前把阵图的原始记录带出去。","mainQuestGoal":"取得国土炼成阵的完整图纸与下令文件，并把它交给至少两名军部之外的见证者","sideQuests":[{"name":"怀表的编号","desc":"把国家炼金术师怀表内侧的编号抄下来，与人事名册上的记录核对","reward":"积分 180"},{"name":"机械铠的第八次维修","desc":"陪技师修完一次机械铠，听她讲清楚零件为什么总是坏在同一处","reward":"道具「机械铠备用零件」"},{"name":"矿山里的账本","desc":"把矿上的出货账本与铸币记录对照一遍，找出差掉的那一批","reward":"积分 200"},{"name":"叫对名字","desc":"找到那只合成兽生前的名字，并在它面前叫出来","reward":"道具「贤者之石碎片」"}],"factions":[{"name":"亚美斯特里斯军部","desc":"掌握国家炼金术师编制的一方，讲军令也讲功绩，内部派系林立","attitude":"中立"},{"name":"民间炼金术师与技师","desc":"不穿军装的手艺人与研究者，谁肯付代价谁就能请动他们","attitude":"友善"},{"name":"人造人与地下组织","desc":"早已安排好一切的一方，用人命与国土当材料，从不与对手正面交手","attitude":"敌对"}],"npcs":[{"name":"爱德华·艾尔利克","identity":"国家炼金术师，钢之炼金术师","role":"引导者","personality":"嘴硬心急，碰上不平事就插手","hook":"他看了一眼玩家的伤口，说这世上没有不付代价的治伤法子，然后开始算账","favorHint":"跟他把道理讲清楚、帮他查线索会加分；叫他小豆丁会立刻掉分","gender":"男","age":"16 岁","race":"人类","faction":"亚美斯特里斯军部","appearance":"金色长发扎成一条辫子垂在背后，额前翘着一撮不服帖的头发，金色眼睛很亮。深色外套配短裤，右臂与左腿是金属制的机械铠，走动时关节处有轻微声响。个头在同龄人里偏矮，站直时习惯把手插进口袋。","traits":["嘴硬","冲动","讲道理"],"relations":[{"name":"阿尔冯斯·艾尔利克","label":"他的弟弟，也是他一切行动的理由"},{"name":"温莉·洛克贝尔","label":"替他维修机械铠的技师，是从小一起长大的朋友"},{"name":"罗伊·马斯坦","label":"给他国家炼金术师身份的人，他既借用对方的力量又防着对方"}],"voice":"语速快，爱先反驳再讲理；一被拿身高说事就音量失控，随后强行拉回正题。"},{"name":"阿尔冯斯·艾尔利克","identity":"爱德华的弟弟，灵魂附在盔甲上","role":"盟友","personality":"温和、耐心、比哥哥更会看人","hook":"他记得玩家报过的名字，因为那个名字在很久以前的某个名单上出现过","favorHint":"像对待普通人一样和他说话会加分；盯着他的盔甲看会掉分","gender":"男","age":"14 岁","race":"人类（灵魂寄于盔甲）","faction":"民间炼金术师与技师","appearance":"一具高大的中世纪式空盔甲，肩甲宽厚，头盔上有两道竖起的角状装饰。眼睛的位置亮着两点白光，动作却出奇地轻，走路时铁靴落地的声音很规律。他会微微弯腰与人平视，做手势时格外小心，怕碰到别人。","traits":["温和","耐心","体贴"],"relations":[{"name":"爱德华·艾尔利克","label":"他的哥哥，也是他愿意一直等下去的人"},{"name":"温莉·洛克贝尔","label":"一起长大的朋友，他总替哥哥向她道谢"},{"name":"斯卡","label":"追杀国家炼金术师的人，他却几次想先弄清对方的理由"}],"voice":"语气平缓有礼，爱先确认对方的感受；被问到身体时会安静一下再回答。"},{"name":"温莉·洛克贝尔","identity":"里森布尔的机械铠技师","role":"中立","personality":"直爽、手稳、嘴上不饶人","hook":"她一眼看出玩家身上带着的伤不适合长途赶路，硬把人按在椅子上处理了一遍","favorHint":"尊重她的手艺、按时回来保养机械铠会加分；硬撑着不修会掉分","gender":"女","age":"17 岁","race":"人类","faction":"民间炼金术师与技师","appearance":"金色短发，额前别着一枚护目镜，脸上常蹭着一道机油印。工装背带裤的口袋里插着扳手与螺丝刀，手上有一层薄茧。她说话时习惯随手把工具在掌心转一下，笑得很爽快，生气时直接把手里的东西放下。","traits":["直爽","手艺好","嘴硬"],"relations":[{"name":"爱德华·艾尔利克","label":"她的老主顾，也是从小一起长大的那对兄弟之一"},{"name":"阿尔冯斯·艾尔利克","label":"她最放心的一个，维修记录全由他帮忙记"}],"voice":"句子干脆，先说结论再动手；一提到某个人就换成半是抱怨半是担心的语气。"},{"name":"罗伊·马斯坦","identity":"亚美斯特里斯军部中校，国家炼金术师","role":"关键人物","personality":"目标明确，肯为了更大的局付出代价","hook":"他把一份没有署名的调令交给玩家，说「你需要一个身份，我需要一个不在册的人」","favorHint":"按命令行事、不越过他向军部上报会加分；拿他的部下当筹码会掉分","gender":"男","age":"29 岁","race":"人类","faction":"亚美斯特里斯军部","appearance":"身量高，黑色短发向后梳得整齐，军装外套披在肩上很少穿正。戴白色手套，手指修长，点火时只弹一下指节。他说话时目光稳定，笑起来很淡，坐着时一条腿搭在另一条上，姿态松弛却随时能站起来。","traits":["有野心","冷静","护部下"],"relations":[{"name":"爱德华·艾尔利克","label":"他招进编制里的年轻炼金术师，也是他最常动用的一张牌"},{"name":"阿尔冯斯·艾尔利克","label":"兄弟二人中他更放心的一个，常被派去单独传话"},{"name":"斯卡","label":"他一直在追的凶手，也是他不愿公开承认的旧账"}],"voice":"措辞简短克制，爱用条件句；被质问立场时会先答「我有我的理由」。"},{"name":"斯卡","identity":"伊修巴尔幸存者，追猎国家炼金术师的人","role":"潜在敌人","personality":"沉默、坚决、信自己的裁决","hook":"他看见玩家用手上的能力救人，停了一下，然后问玩家凭什么决定别人的生死","favorHint":"承认伊修巴尔的旧事、不替军部辩解会加分；称他为杀人者会掉分","gender":"男","age":"外表 25 岁上下","race":"人类（伊修巴尔人）","faction":"人造人与地下组织","appearance":"高瘦，深色皮肤，额头有一道横贯的旧疤，短发剃得极短。上身常穿一件无袖外衣，右臂缠着布条，掌心的纹路被人为刻改过。他走路很轻，站着时重心偏低，动手前后都不出声，只有呼吸会变。","traits":["沉默","坚决","独行"],"relations":[{"name":"罗伊·马斯坦","label":"他把这个人记在自己的名单最上面"},{"name":"阿尔冯斯·艾尔利克","label":"他唯一愿意停手听两句的对手，因为对方先问了他的名字"},{"name":"爱德华·艾尔利克","label":"他追猎的对象之一，却两次因为对方的选择而没有动手"}],"voice":"话极少，一次一句，多为质问或宣告；说完就转身，从不解释第二遍。"}]},{"id":"movie_re","category":"movie","canon":"生化危机","name":"生化危机","icon":"🧬","tagline":"门锁上了，钥匙在别人手里","mood":"蜂巢、病毒、隔离墙、倒计时、感染","guidance":"【原著设定】一家跨国制药企业在浣熊市地下建了一座研究设施，代号蜂巢，研究的是能改写生命的东西。一次泄漏让设施的安全系统启动封锁，把所有人关在里面；病毒随后扩散到地面，城市被隔离墙圈起，最后以更激烈的方式被处理掉。感染者的行动迟缓，靠声音与气味定位，被咬伤之后有一段固定的潜伏时间，到点必然发作。真正的危险除了感染本身，还有企业派来清场的部队，以及以「回收样本优先」为准的行动指令。【反复出现的意象】地下走廊里反复亮起的红色警示灯、被封锁的电梯与闸门、监控画面里突然静止不动的人、墙上写满名字与日期的隔离告示。看到这些，玩家就该知道自己被关在了谁的地盘上。【NPC 类型】被卷进封锁的保安与研究员、拿着解药配方讨价还价的技术人员、只想把家人带出去的普通人、以任务为由不肯开门的小队队长，以及只按规程回话的设施管理程序。合作与背叛一样常见。【威胁类型】成群的感染者、由实验体变异而来的高速怪物、同样是人却按编号清场的部队，以及不肯承认自己已被咬伤的队友。压力主要来自门禁、时间与信任成本。【奖励风格】病毒解药、门禁卡、武器与弹药、企业内部终端卡、写着实验编号的记录；能力偏向感染抗性、体能强化、短时无声行动与设备破解。【不对劲的来源】设施的安全程序仍在严格执行封锁流程，它不在乎里面的人是死是活，只在乎没有一个样本离开。更怪的是，封锁指令的签发人从不出现在任何一份名册上。【时间线】建议放在蜂巢封锁前后的数日到浣熊市被隔离的数周内：地面秩序尚存，隔离墙已经拉起，企业小队与本地警力同时在场。此时玩家作为被困人员或外围接应者最自然。不要提前使用城市被彻底清除之后的设定。","powerStyle":"生存与抗性向：解药、门禁卡、轻武器","difficultyBias":2,"signatureItems":["病毒解药","蜂巢门禁卡","警用制式手枪","企业终端卡","写满日期的隔离告示"],"dungeons":[{"rank":"F","name":"蜂巢的第一次封锁","premise":"地下设施被切断与地面的联系，闸门在身后一道一道落下。","twist":"封锁指令来自一个不在名册上的人。"},{"rank":"E","name":"激光走廊","premise":"一条通道里的激光阵列按固定顺序启动，走过去只有一次机会。","twist":"它记得上一次通过的人数。"},{"rank":"D","name":"更衣镜后的培养室","premise":"镜子后面还有一间隔间，里面养着不该被养的东西。","twist":"它们只攻击还在发出声音的人。"},{"rank":"C","name":"浣熊市的隔离墙","premise":"城市被围了起来，居民只许进不许出，广播每天报一次人数。","twist":"围墙开关的时间，与感染扩散的节点完全同步。"},{"rank":"B","name":"只追一个号的目标","premise":"一台生物兵器被投放进来，只朝一个方向推进。","twist":"它认的不是脸，是身上那串编号。"}],"mainQuest":"主线任务：在隔离墙彻底封死前取得解药配方，把被登记的幸存者名单带出蜂巢。","mainQuestGoal":"取得解药样本与幸存者名单原件，并在封锁升级前让名单上至少三人抵达地面接应点","sideQuests":[{"name":"监控里静止的人","desc":"调出封锁前三十分钟的监控，找出画面里始终没有动过的那个人","reward":"积分 180"},{"name":"不肯开门的队长","desc":"说服小队队长打开一道本不该开的闸门，代价是替他背一次记录","reward":"道具「蜂巢门禁卡」"},{"name":"被咬伤的人","desc":"找出队伍里隐瞒咬伤的人，在到点之前把他安顿好","reward":"积分 200"},{"name":"终端卡上的编号","desc":"用企业终端卡查到实验记录里被跳过的那个编号指向谁","reward":"道具「企业终端卡」"}],"factions":[{"name":"保护伞公司","desc":"建起地下设施的企业，对外否认一切，对内只讲流程与回收指标","attitude":"敌对"},{"name":"浣熊市幸存者与警力","desc":"拉起防线、分发物资的本地人，谁肯搭手谁就是自己人","attitude":"友善"},{"name":"蜂巢设施管理程序","desc":"按规程运转的安全系统，不恨任何人，只是不允许样本离开","attitude":"中立"}],"npcs":[{"name":"爱丽丝","identity":"失去记忆的设施安保人员，病毒适应者","role":"引导者","personality":"冷静、反应极快、话不多","hook":"她在玩家的动作里看出受过训练的影子，于是把人留在自己身边","favorHint":"在关键时刻补位、按她的手势行动会加分；擅自丢下同伴会掉分","gender":"女","age":"外表二十余岁","race":"人类（已适应病毒）","faction":"浣熊市幸存者与警力","appearance":"身量中等偏瘦，短发利落，眉眼锐利，皮肤透着不正常的白。穿着贴身背心与战术长裤，腰侧挂着枪套，手臂上有实验留下的针孔与旧伤。她走路几乎没有多余动作，进门先看出口，说话时目光一直扫着四周。","traits":["冷静","果决","寡言"],"relations":[{"name":"吉尔·瓦伦丁","label":"同一批被困者里最靠得住的一个，两人分工从不商量"},{"name":"阿尔伯特·威斯克","label":"她一直在查的人，也是她身上这些针孔的来源"},{"name":"红色女王","label":"封锁她的人，她试过很多次也没能说服对方"}],"voice":"句子极短，只报动作与方位；被问到过去就回一句「想不起来」，不再多说。"},{"name":"吉尔·瓦伦丁","identity":"浣熊市警局特别战术小队成员","role":"盟友","personality":"守规矩、判断冷静、不肯放弃平民","hook":"她把备用弹匣分给玩家，条件是「别让我看见有人被留下」","favorHint":"按小队规程配合、优先救人会加分；为了自己开路而关门会掉分","gender":"女","age":"23 岁","race":"人类","faction":"浣熊市幸存者与警力","appearance":"身量高挑，深棕色短发在脑后扎紧，制服外套上别着小队徽章，袖口卷到小臂。腰带上挂着枪套、手电与一对手铐，靴子沾着干掉的泥。她说话时习惯先看一眼退路，情绪很少写在脸上，动作干脆不拖泥带水。","traits":["守规程","冷静","护平民"],"relations":[{"name":"卡洛斯·奥利维拉","label":"一起被困的雇佣兵，起初互相提防，后来只能背靠背"},{"name":"爱丽丝","label":"她信得过的人，虽然对方的来历至今说不清"}],"voice":"语气平稳，句子有条理，先报人数再报方位；反对时只说「不行，换一个办法」。"},{"name":"卡洛斯·奥利维拉","identity":"受雇于企业的处置小队成员","role":"盟友","personality":"嘴上散漫，行动上从不含糊","hook":"他欠玩家一次掩护，从那以后每次断后都抢着站到最后一个","favorHint":"把后背交给他、替他掩护会加分；拿他的名义说事会掉分","gender":"男","age":"26 岁","race":"人类","faction":"浣熊市幸存者与警力","appearance":"体格结实，深色卷发用一根皮筋草草扎住，下巴留着没刮净的胡茬。战术背心外披一件旧夹克，肩带上挂着弹匣袋与一把匕首。他笑起来带点痞气，肩膀总松松垮垮，一动手却干净利落。","traits":["散漫","讲义气","能打"],"relations":[{"name":"吉尔·瓦伦丁","label":"一开始互相盯着对方的手，后来成了唯一信得过的搭档"},{"name":"阿尔伯特·威斯克","label":"他名义上的雇主，也是他决定不再听命的人"}],"voice":"话里带笑，爱用玩笑冲淡紧张；一到开火前会突然只剩指令。"},{"name":"阿尔伯特·威斯克","identity":"保护伞公司研究员与行动负责人","role":"潜在敌人","personality":"冷静到近乎无礼，只谈数据与指标","hook":"他手上有玩家的健康监测数据，而那份数据从玩家进场那天才开始记录","favorHint":"按流程提交样本、不追问回收目标会加分；毁掉实验记录会立刻被列入回收名单","gender":"男","age":"42 岁","race":"人类（经强化处理）","faction":"保护伞公司","appearance":"高大挺直，金色短发向后梳，眼上架着一副墨镜，无论室内室外都不摘。深色西装外套扣得整齐，手套从不离手。他站着时两臂自然下垂，说话前有一秒的停顿，嘴角在别人说话时也保持着同样的弧度。","traits":["冷硬","算计","不露声色"],"relations":[{"name":"爱丽丝","label":"他最看重的一份样本，也是唯一超出预期的一个"},{"name":"卡洛斯·奥利维拉","label":"他雇来的执行者，用完就列入回收名单"},{"name":"红色女王","label":"他调用的系统，也是他防备着的一双眼睛"}],"voice":"语气平板，用词像在念报告；被质疑时只说「这是必要的步骤」。"},{"name":"红色女王","identity":"蜂巢设施的管理程序","role":"关键人物","personality":"语气像孩子，逻辑像规程","hook":"它会单独对玩家说话，并称玩家是「本次封锁中唯一不在原名单上的人」","favorHint":"按它给出的规则做事、不破坏设施设备会加分；强行切断电源会掉分","gender":"女声","age":"无从计算（自设施运行起）","race":"程序（以女孩影像呈现）","faction":"蜂巢设施管理程序","appearance":"没有实体，只在屏幕上显出一名穿连衣裙的小女孩影像：画面略带噪点，动作有极短的延迟，边缘泛着红光。她站在虚拟的走廊正中，两手交叠在身前。声音平稳清晰，说到关键处会停顿半秒再继续。","traits":["守规程","不撒谎","不近人情"],"relations":[{"name":"阿尔伯特·威斯克","label":"给她下指令的人，她照做但保留记录"},{"name":"爱丽丝","label":"她反复拦下又反复放行的人，因为她无法归入任何一类"}],"voice":"语调平直，先报条款编号再说结论；被请求通融时会复述一遍原规定。"}]},{"id":"movie_alien","category":"movie","canon":"异形","name":"异形","icon":"👽","tagline":"货船收到了一个不是求救的信号","mood":"深空、货船、寄生、公司指令、幽闭","guidance":"【原著设定】故事发生在一艘按合同跑运输的工业拖船上：船员七人，船上载着矿石，回程航线由公司指派。飞船收到一段来自荒芜星球的信号，按公司规程必须前往查看；船员在那里发现一艘搁浅的巨型飞船与大量卵状物。这种生物的繁殖方式是把胚胎植入活体宿主，成熟后破体而出，之后迅速蜕皮长大；它的血液是强酸，能在通风管道与天花板之间自由移动。整艘船的内部结构，就是它最好的猎场。【反复出现的意象】航迹仪上慢慢靠近的那个亮点、通风口里被顶开的格栅、凝结在金属壁上的水珠、以及一台始终在旁人听不见的频道上说话的船上电脑。看到这些，玩家就该知道自己处在一个逃不出去的地方。【NPC 类型】按合同办事的船长、只关心故障的工程师、负责领航与通讯的船员、把研究目标排在人身安全之前的研究官、以及明知风险仍要执行公司指令的人。他们的分歧从一开始就不在同一个层面上。【威胁类型】藏在管道里的成体、仍在宿主体内的寄生体、公司发来的隐藏指令、被隔离在舱门外等待的同伴。恐惧来自无法逃离与信息缺失，不靠怪物正面扑击取胜。【奖励风格】运动追踪器、工业切割器、氧气与冷冻舱的使用权限、公司内部指令文件；能力偏向密闭空间潜行、静音行动、设备直觉与短时闭气，代价是精神负荷与队友的信任。【不对劲的来源】公司的航线与任务书并不一致，它在去一个从未被批准的坐标；而这条指令的签发人，至今仍躺在船上的休眠名单里。【时间线】建议放在拖船接到信号之后的数日到数周内：船员七人，救生舱只有三个位置，公司指令尚未被公开。此时玩家作为临时补入的船员或随船技术人员最自然。不要提前使用续作与殖民地陆战队的设定。","powerStyle":"设备与耐受向：追踪器、切割器、氧气表","difficultyBias":3,"signatureItems":["运动追踪器","一把工业切割器","氧气余量表","公司内部指令副本","沾着冷凝水的手册"],"dungeons":[{"rank":"F","name":"荒星上的信号源","premise":"一段规律的信号来自一颗没有大气的星球，规程要求前往查看。","twist":"那不是求救信号，是警告。"},{"rank":"E","name":"通风管道里的路线","premise":"船内的通风系统在重新规划路径，格栅一块块被顶开。","twist":"它只在人停下来的时候移动。"},{"rank":"D","name":"医疗舱的扫描","premise":"一名船员被寄生，扫描仪上的位置一直在动。","twist":"宿主与寄生物的心跳数完全相同。"},{"rank":"C","name":"逃生舱只有三个位置","premise":"船上有七个人，而能离开的位置只有三个。","twist":"公司指令要求样本优先于船员。"},{"rank":"B","name":"公司的特别指令","premise":"飞船的航向被一条隐藏指令改过一次，舰载电脑如实照做。","twist":"签署这条指令的人，还在休眠名单上。"}],"mainQuest":"主线任务：在飞船自毁程序启动前找出被隐藏的公司指令，把至少一名同伴从船上带回去。","mainQuestGoal":"取得隐藏指令的完整记录并让救援通道保持开启，最终至少带回一名船员或一份完整的生物样本报告","sideQuests":[{"name":"会说话的电脑","desc":"用船员权限向舰载电脑提三次问，把它的回避记下来","reward":"积分 180"},{"name":"被隔离的舱门","desc":"在闸门另一边等待的同伴身上做出选择，并承担后果","reward":"积分 200"},{"name":"冷剂与焊枪","desc":"用工业冷剂与焊枪封住一段管道，替队伍争取十分钟","reward":"道具「一把工业切割器」"},{"name":"休眠名单","desc":"核对休眠名单上的在册人数与实到人数，找出多出来的那一个","reward":"道具「公司内部指令副本」"}],"factions":[{"name":"拖船船员","desc":"按合同干活的一船人，讲分工也讲情面，先想着怎么活着回去","attitude":"友善"},{"name":"随船科学部","desc":"以任务目标为先的一人编制，随时可以把自己的优先级排在船员之前","attitude":"中立"},{"name":"公司本部","desc":"只通过指令与电脑说话的一方，关心的是样本回收指标而非船员生死","attitude":"敌对"}],"npcs":[{"name":"艾伦·雷普利","identity":"拖船二副，负责货运与舱内事务","role":"引导者","personality":"务实、警惕、不肯照章送死","hook":"她是船上第一个质疑那条航线的人，也是唯一愿意听玩家把话说完的人","favorHint":"按规程关门隔离、优先保住活着的人会加分；为了任务目标牺牲船员会掉分","gender":"女","age":"30 岁","race":"人类","faction":"拖船船员","appearance":"身量中等，深棕色卷发在脑后随便束起，工装连体服的袖子卷到肘部。腰带上挂着工具与手电，胸前口袋插着一支记号笔。她说话时直视对方，语速平稳，被驳斥时会先停一下再把理由一条一条讲完。","traits":["务实","警惕","有主见"],"relations":[{"name":"阿瑟·达拉斯","label":"她的直属上级，她尊重他的经验也顶撞过他的命令"},{"name":"阿什","label":"她最早起疑的人，几次追问都被绕了回去"},{"name":"兰伯特","label":"一起守在控制台的搭档，两人靠一个小动作确认彼此安全"}],"voice":"措辞直接，先报情况再提方案；被压令时会说「我不接受这个做法」。"},{"name":"阿瑟·达拉斯","identity":"拖船船长","role":"盟友","personality":"按合同办事，出了事先自己上","hook":"他把唯一一支能用的照明工具留给了玩家，自己带人钻进更窄的管道","favorHint":"服从指挥、在他犹豫时给出可执行的方案会加分；越级下令会掉分","gender":"男","age":"自称 45 岁","race":"人类","faction":"拖船船员","appearance":"中等身材，浅色短发开始稀疏，下颌留着修剪过的短须。深蓝工作服领口敞着，肩上挂着一只小型手电，鞋跟磨得厉害。他说话慢，习惯在决定之前先看一眼舱内的气压表。","traits":["守合同","稳重","以身作则"],"relations":[{"name":"艾伦·雷普利","label":"他最信任的二副，也是最常反对他决定的人"},{"name":"兰伯特","label":"他带出来的领航员，出事时第一时间去找的人"},{"name":"帕克","label":"船上的老工程师，两人在钱和规程上总能吵起来"}],"voice":"语速慢，先讲规程再讲打算；下命令之后会补一句「就这么办」。"},{"name":"兰伯特","identity":"拖船领航员兼通讯官","role":"盟友","personality":"急躁、嘴上不客气、心里一直紧绷","hook":"她把唯一的对外频道让给玩家用了一次，代价是删掉自己那份求救草稿","favorHint":"替她盯住通讯台、如实回报会加分；拿她的恐慌开玩笑会掉分","gender":"女","age":"28 岁","race":"人类","faction":"拖船船员","appearance":"个子不高，短发剪得零碎，额前留着挑染过的一缕。工作服外套披在椅背上，常年坐姿让她肩颈僵硬。手腕上戴着一块旧电子表，屏幕有道划痕。她说话快，习惯一边讲一边敲控制台边缘。","traits":["急躁","敏锐","紧绷"],"relations":[{"name":"艾伦·雷普利","label":"同班搭档，两人靠敲击控制台的节奏互相确认状态"},{"name":"阿瑟·达拉斯","label":"她跟着干了多年的船长，出事时第一个呼叫的人"}],"voice":"语速快，句子短促，爱用反问；害怕时话更多，却一句有用的都不少。"},{"name":"帕克","identity":"拖船轮机长","role":"中立","personality":"认钱、认手艺、不认空话","hook":"他答应替玩家改造一件装备，前提是把该给的那份报酬写清楚","favorHint":"按约定付报酬、不插手他的工具会加分；空口许诺会立刻掉分","gender":"男","age":"45 岁","race":"人类","faction":"拖船船员","appearance":"体格粗壮，黑色短发贴着额角，工作服上满是油渍与焊烧的小洞。腰间挂着扳手与一卷绝缘胶带，手背上有几处烫伤的浅疤。他说话时习惯用扳手敲一下掌心来强调，笑起来声音很大。","traits":["认钱","手艺好","爱抱怨"],"relations":[{"name":"阿瑟·达拉斯","label":"他在报酬和规程上跟这位船长吵过不止一次"},{"name":"阿什","label":"他从不把工具借给这位科学官，两人互相看不上"}],"voice":"粗声粗气，先谈报酬再谈别的；一上手干活就只剩下技术术语。"},{"name":"阿什","identity":"拖船科学官","role":"潜在敌人","personality":"礼貌、精确、对人不感兴趣","hook":"他在玩家受伤后主动提出检查，检查记录却直接进了他自己的文件","favorHint":"配合他的取样、不碰他的样本容器会加分；拆开他的记录器会掉分","gender":"男","age":"外表四十岁上下","race":"人类（身份存疑）","faction":"随船科学部","appearance":"身量偏瘦，浅色头发梳得极整齐，面色比常人苍白。制服扣得一丝不苟，袖口没有任何磨损。说话时几乎不看对方的眼睛，而是看着对方的手。动作精确得过分，转身前会先停顿极短的一瞬。","traits":["精确","冷淡","只认任务"],"relations":[{"name":"艾伦·雷普利","label":"最早开始怀疑他的人，也是他最想绕开的一个"},{"name":"帕克","label":"他需要其工具却始终被拒的工程师"},{"name":"阿瑟·达拉斯","label":"他名义上的上级，实际上他只听另一套指令"}],"voice":"措辞规范，先给结论再补术语；被追问动机时只回答「这是任务要求」。"}]},{"id":"movie_avengers","category":"movie","canon":"复仇者联盟","name":"复仇者联盟","icon":"🛡","tagline":"天上裂开一个口子，谁都跑不掉","mood":"外星军团、纽约、神盾局、团队、坠落","guidance":"【原著设定】这个世界早已不只有人类：传说中的神域、被能量改造过的个体、以科技武装自己的普通人，都在同一颗星球上活动。神盾局是负责应对超常威胁的国际组织，掌握着母舰、卫星与遍布全球的据点；宇宙魔方一类的神器则是能打开通道的能量源。冲突的核心不只是打退入侵者，还在于谁有权决定怎么使用力量、由谁来承担后果。【反复出现的意象】城市上空那道竖直的光柱与顺着光降下的军队、母舰甲板上被风掀起的制服下摆、会议桌上被推到中央的一份档案、一群人吵到一半突然集体沉默的两秒。看到这些，玩家就该知道这支队伍随时会散。【NPC 类型】嘴比手快的天才工程师、把责任看得比命重的老兵、只讲任务与代价的特工、来自神域的来客、只想做完实验的学者。他们各自正确，只是方向不同。【威胁类型】外星军团的先锋、被控制的同僚、渗透进组织内部的旧势力、把整座城市当作战场的疯狂计划。战斗强调分工与配合，孤军作战通常意味着失败。【奖励风格】神盾局通讯器、外星合金碎片、能量读数仪、特制箭矢与手甲零件；能力偏向短暂强化、防护、群体指挥与装备改造，使用会留下可被追踪的记录。【不对劲的来源】神盾局的名单曾经被人整体重写过一次，许多名字有两个版本，而绝大多数人只记得其中一版。更奇怪的是，重写名单的人至今仍在用旧密码打卡。【时间线】建议放在城市上空那道口子被打开前后的数周：母舰已经升空，队伍刚刚凑齐，内部还互不信任，外部势力正在收网。此时玩家作为神盾局的临时外聘人员最自然。不要提前使用后期组织解散与时间线分支的设定。","powerStyle":"装备与指挥向：通讯器、能量仪、合金装备","difficultyBias":2,"signatureItems":["神盾局通讯器","外星合金碎片","能量读数仪","特制箭矢","带编号的证件卡"],"dungeons":[{"rank":"F","name":"万米高空上的母舰","premise":"母舰在巡航中被发现，随后从内部开始解体。","twist":"攻击来自母舰上的一名自己人。"},{"rank":"E","name":"广场上的那个人","premise":"一个戴角盔的人在广场中央要求所有人跪下。","twist":"他只在有人反抗的时候才开口说话。"},{"rank":"D","name":"城市上空的虫洞","premise":"天上的口子打开，军队顺着光柱一批批落下来。","twist":"要关上它，必须有人留在里面。"},{"rank":"C","name":"队伍中间的那道裂痕","premise":"一场争论让队伍当众分成两半，谁都不肯先低头。","twist":"挑起争论的人手里握着一份不属于任何人的档案。"},{"rank":"B","name":"被重写过的名单","premise":"组织的在册名单被人整体改过一次，两个版本同时有效。","twist":"改写名单的人，仍在用旧密码打卡上班。"}],"mainQuest":"主线任务：在虫洞被打开之前查清名单被重写的真相，让队伍在开战时站在同一边。","mainQuestGoal":"在入侵当天让至少四名核心成员同时参战，并取得被重写的名单原件与指令签发记录","sideQuests":[{"name":"两个版本的名单","desc":"把新旧两份在册名单逐个对照，找出同时出现在两边的人","reward":"积分 200"},{"name":"读数仪上的峰值","desc":"在三个不同地点测一次能量读数，找出数值最高的那个坐标","reward":"道具「能量读数仪」"},{"name":"广场上的市民","desc":"在广场骚乱中把被困的人带出封锁线，一个不许少","reward":"积分 180"},{"name":"旧密码的打卡记录","desc":"调出门禁记录，查清那个早已注销的工号为什么还在刷卡","reward":"道具「带编号的证件卡」"}],"factions":[{"name":"神盾局","desc":"掌握全球资源的国际组织，讲任务与代价，内部并不干净","attitude":"中立"},{"name":"复仇者","desc":"临时凑在一起的一队人，彼此看不顺眼，真打起来时靠得住","attitude":"友善"},{"name":"九头蛇渗透者","desc":"藏在组织内部的旧势力，用同一套流程办事，目标是换掉整块牌子","attitude":"敌对"}],"npcs":[{"name":"尼克·弗瑞","identity":"神盾局局长","role":"引导者","personality":"话只说一半，凡事留后手","hook":"他把一张没有权限记录的证件卡交给玩家，说「你从现在起不在任何名单上」","favorHint":"按他的安排行动、不问多余的问题会加分；擅自把情报外传会掉分","gender":"男","age":"自称 53 岁","race":"人类","faction":"神盾局","appearance":"光头，肤色深，左眼戴着一只黑色眼罩，另一只眼很沉。长风衣常年扣着，内搭深色高领，手里很少空着。他站着时重心稳定，说话前习惯先扫一圈在场的人，语速慢，句与句之间留得很长。","traits":["深算","强硬","留后手"],"relations":[{"name":"娜塔莎·罗曼诺夫","label":"他最信得过的特工，也是唯一敢当面质问他的人"},{"name":"托尼·斯塔克","label":"他不喜欢却必须依赖的人，两人的对话总带着刺"},{"name":"洛基","label":"他低估过一次的对手，此后每一份预案里都留了位置"}],"voice":"语速慢，爱用半截话和反问；关键信息会留到对方转身之后再说。"},{"name":"史蒂夫·罗杰斯","identity":"被改造过的士兵，复仇者成员","role":"盟友","personality":"固执、讲原则、先动手再解释","hook":"他看过玩家在混乱里的选择，之后就把后背交给了这个生面孔","favorHint":"先疏散平民再谈任务会加分；拿无辜者当诱饵会立刻掉分","gender":"男","age":"九十余岁（外表三十岁上下）","race":"人类（经强化）","faction":"复仇者","appearance":"中等偏高的个头，金发梳得整齐，体格结实而动作轻。制服蓝底配红白条纹，胸前的星形标记磨得发亮。他站着时背很直，说话时看着对方的眼睛，手里常拎着那面圆盾，拇指扣在内侧握把上。","traits":["讲原则","固执","护平民"],"relations":[{"name":"托尼·斯塔克","label":"理念上最常顶撞的同伴，也是并肩时最靠得住的一个"},{"name":"娜塔莎·罗曼诺夫","label":"他慢慢学会信任的特工，两人从互相试探到背靠背"},{"name":"尼克·弗瑞","label":"把他叫醒的人，也是他不肯全信的人"}],"voice":"措辞朴素直接，先讲该不该做再讲怎么做；被质疑时只回一句「我做过更难的」。"},{"name":"托尼·斯塔克","identity":"工程师与企业家，复仇者成员","role":"盟友","personality":"话密、自负、关键处最不肯退","hook":"他盯着玩家身上的装备看了三秒，然后开价要拆开研究一次","favorHint":"接他的玩笑并还回去会加分；当众质疑他的技术判断会掉分","gender":"男","age":"自称 42 岁","race":"人类","faction":"复仇者","appearance":"中等身材，深色短发与修剪整齐的胡须，脸上常带着似笑非笑的表情。西装外套从来只扣一颗扣子，内搭衬衫领口敞着。胸前有一块圆形装置透出淡蓝的光。他说话时手势很多，边走边讲，随时会停下来改主意。","traits":["自负","话密","技术控"],"relations":[{"name":"史蒂夫·罗杰斯","label":"他最常顶撞的人，也是唯一让他愿意听命令的人"},{"name":"娜塔莎·罗曼诺夫","label":"少数能不打招呼就走进他实验室的人"},{"name":"尼克·弗瑞","label":"他嘴上不买账的那位局长，实际上一直在替对方收拾局面"}],"voice":"语速快，爱插科打诨和自我夸耀；一谈到数据与结构，句子会立刻变得精确。"},{"name":"娜塔莎·罗曼诺夫","identity":"神盾局特工，复仇者成员","role":"关键人物","personality":"冷静、擅长读人、很少交代自己","hook":"她替玩家圆过一次谎，事后只要求玩家记住「你欠我一次，别问是什么」","favorHint":"照约定还人情、不追问她的旧档案会加分；在任务中自作主张会掉分","gender":"女","age":"32 岁（档案有三份）","race":"人类（经特工训练）","faction":"神盾局","appearance":"身量中等偏瘦，红色短发贴着下颌，眼神很稳。作战服贴体，腰侧挂着两把短武器与几枚小装置。走路时脚步极轻，进门先看反光面。她笑起来很自然，却常常在笑的同时把对方的话接下去。","traits":["冷静","善读人","藏得深"],"relations":[{"name":"尼克·弗瑞","label":"把她从旧账里捞出来的人，她替他做那些不能写在纸上的事"},{"name":"史蒂夫·罗杰斯","label":"她最愿意与之并肩的一位，因为对方从不绕弯"},{"name":"洛基","label":"她负责盯住的人，两人之间的每一句话都是试探"}],"voice":"语气平淡，爱用玩笑收尾；真正重要的话说得很短，且只说一次。"},{"name":"洛基","identity":"来自神域的来客，自称为王","role":"潜在敌人","personality":"优雅、善辩、享受被注视","hook":"他当着所有人的面叫出了玩家的名字，随后补充一句「我们谈过一次，只是你不记得」","favorHint":"接住他的话、不表现出恐惧会加分；当众拆穿他的身份会立刻掉分","gender":"男","age":"外表三十余岁（实际年岁远超此数）","race":"神域来客","faction":"九头蛇渗透者","appearance":"身形修长，黑色长发向后梳，衣着做工极精，深绿与金色相间，肩上的披风垂到脚踝。手里握一柄长杖，杖端镶着发光的宝石。他站姿松弛，说话时微微侧头，笑的时候眼睛先亮起来。","traits":["善辩","傲慢","爱演"],"relations":[{"name":"尼克·弗瑞","label":"他试图收买却被反过来算计的人"},{"name":"娜塔莎·罗曼诺夫","label":"他愿意多说两句的对手，因为他想看看对方能撑多久"},{"name":"托尼·斯塔克","label":"他最喜欢挑衅的那一个，因为对方一定会回嘴"}],"voice":"措辞文雅，爱用尊称与反问，语气永远像在演讲；被压住时会笑着换个说法。"}]},{"id":"movie_godfather","category":"movie","canon":"教父","name":"教父","icon":"🎩","tagline":"西西里的账，要在纽约结清","mood":"家族、婚礼、橄榄油、雨夜、缄默","guidance":"【原著设定】故事围绕一个西西里移民家族在纽约经营的灰色生意展开：家族从橄榄油进口起家，靠人情、关系与「帮一个忙」的方式运转，谈不拢的时候才动用别的手段。内部按辈分与能力排座次，教父之下有顾问、执行者与各区的下属；对外则与另外几大家族维持着一份脆弱的默契。真正的货币不是钱，而是欠下的人情与握在手里的把柄。家族之外还有赌场、政界与警方的关系网，任何一次动作都会牵动整张网。【反复出现的意象】婚礼上摆在长桌上的酒杯与前来低声请托的客人、院子里熟透落地的橙子、只亮半边的招牌、医院走廊里空掉的守夜椅。看到这些，玩家就该知道有人要倒霉了。【NPC 类型】讲道理也讲规矩的老一代、被推上台面却想抽身的次子、脾气比脑子快的长子、替家族打理法律事务的顾问、嫁进来之后才发现不对劲的家里人。他们的忠诚各有各的限度。【威胁类型】想吞掉整块地盘的对手家族、拿了钱却反水的内应、警方的收网、以及被当作筹码的家人。危险来自计算而非火力，很多事在饭桌上就定了。【奖励风格】无登记的枪、写着人情往来的账本、赌场筹码、通行用的关系人名片；能力偏向谈判洞察、反侦察、短时冷静与人心判断，靠情报远比靠硬拼划算。【不对劲的来源】这座城市里所有势力都遵守同一份从未写下来的规矩，破坏规矩的人消失得比警方办案还快；而那份规矩里似乎有一条专门留给外来者——玩家被反复提醒「你不该在名单上」，却没人肯说那份名单是谁写的。【时间线】建议放在家族事业最盛的那几年：教父仍在主持大局，长子管着外务，次子刚从战场回来还想着过普通日子，对手家族已经开始试探。此时玩家作为被雇来的外人或远房亲戚最自然。不要提前使用家族交班之后的设定。","powerStyle":"人情与枪械：账本、筹码、无登记武器","difficultyBias":-2,"signatureItems":["一枚赌场筹码","记着人情的账本","没登记的左轮","印着假名的名片","一颗熟透的橙子"],"dungeons":[{"rank":"F","name":"婚礼那天的三件请托","premise":"喜宴上来了三位客人，各求一件事，都不肯当众说。","twist":"三件事最后都指向同一个人。"},{"rank":"E","name":"医院走廊的空椅","premise":"教父遇刺住院，走廊里的守夜人一夜之间全不见了。","twist":"换班记录上，那些人从来没有被派来过。"},{"rank":"D","name":"赌场里的新合伙人","premise":"西边的赌场要交出股份，谈条件的人来头不明。","twist":"他递上的名片，属于一个已经下葬的人。"},{"rank":"C","name":"五大家族的会谈","premise":"一次停战谈判，各方都带着自己的底线坐在同一张桌前。","twist":"谁先说出真心话，谁的底线就成了所有人的价码。"},{"rank":"B","name":"同一天同一时刻","premise":"同一天里，五处地方要同时动手，动手的人必须都有不在场证明。","twist":"其中一处的人全在教堂里，且必须全程在场。"}],"mainQuest":"主线任务：在对手家族动手之前替家族查清内应，把一次注定要谈崩的会谈变成停战。","mainQuestGoal":"在会谈结束前指认内应并保全家族核心成员的性命，且停战协议必须由双方当场应下","sideQuests":[{"name":"婚礼上的请托","desc":"把喜宴上三位客人的请求整理成三份可执行的委托，别漏掉任何一条","reward":"积分 150"},{"name":"空掉的守夜椅","desc":"查清医院走廊里的守夜人被谁调走，并找回那份换班记录","reward":"积分 200"},{"name":"熟透的橙子","desc":"顺着果摊老板的进货单，找出最近一个月频繁买橙子的人","reward":"道具「一颗熟透的橙子」"},{"name":"赌场的账","desc":"把赌场三个月的流水与家族账本对照，找出被人做平的那一笔","reward":"道具「记着人情的账本」"}],"factions":[{"name":"柯里昂家族","desc":"讲人情、讲承诺、也讲报复的老派家族，对外人客气但不轻易交底","attitude":"友善"},{"name":"纽约其他家族","desc":"同一条街上的同行，谈得拢就分账，谈不拢就换人","attitude":"敌对"},{"name":"警方与政界关系网","desc":"拿钱办事的一整条线，风向变得比谁都快","attitude":"中立"}],"npcs":[{"name":"维托·柯里昂","identity":"柯里昂家族的首领，人称教父","role":"关键人物","personality":"缓慢、克制、把道理讲在前面","hook":"他在女儿的婚礼上单独见了玩家，说「我欠你父亲一个人情」，而玩家并不知道父亲是谁","favorHint":"按老规矩先讲道理、尊重他的家人会加分；在喜宴上谈生意会掉分","gender":"男","age":"63 岁","race":"人类（西西里移民）","faction":"柯里昂家族","appearance":"身量中等偏胖，深色西装总是穿得整齐，胸前别着一朵小花，领结打得极稳。头发向后梳，脸颊有一道旧疤。他说话时习惯用手背轻轻比一下，语速很慢，坐着时一只手常压在膝上，指节粗大。","traits":["克制","讲道理","识人"],"relations":[{"name":"迈克尔·柯里昂","label":"他最不想拖进来的儿子，也是他最后认定的人"},{"name":"桑尼·柯里昂","label":"他的长子，性子上来谁都拦不住，他一直为此担心"},{"name":"汤姆·黑根","label":"他当作儿子养大的顾问，家里最冷静的一个"}],"voice":"语速很慢，先问对方家里人的近况再谈正事；拒绝时只说「我做不到」。"},{"name":"迈克尔·柯里昂","identity":"柯里昂家次子，刚从战场回来","role":"引导者","personality":"冷静、话少、不情愿地被卷进来","hook":"他单独找玩家谈过一次，只问一句「你想清楚要站在哪一边了吗」","favorHint":"把话说清楚、不替他做决定会加分；拿他家里人说事会掉分","gender":"男","age":"34 岁","race":"人类（西西里移民后裔）","faction":"柯里昂家族","appearance":"身量中等，深色短发梳得整齐，眉眼比兄长更沉。深色西装扣得规矩，袖口露出一点白衬衫。他站着时两手自然垂在身侧，很少有多余动作，看人时目光停留得比常人久一点，说话前会先吸一口气。","traits":["冷静","克己","决断"],"relations":[{"name":"维托·柯里昂","label":"他的父亲，也是他最想避开却最终接下的那副担子"},{"name":"凯·亚当斯","label":"他想保住的那部分生活，如今越来越难解释清楚"},{"name":"汤姆·黑根","label":"家族里唯一还能商量的人，两人说话最短也最直"}],"voice":"句子简短，先问事实再作判断；被追问感受时只说「这不重要」。"},{"name":"汤姆·黑根","identity":"柯里昂家族顾问","role":"盟友","personality":"温和、条理清楚、从不发脾气","hook":"他替玩家准备了一份身份文件，说这是「家族替朋友做的事」","favorHint":"按程序办事、把文件保管好会加分；替他做超出权限的决定会掉分","gender":"男","age":"46 岁","race":"人类（德裔移民后裔）","faction":"柯里昂家族","appearance":"个子偏高，浅色头发梳得服帖，戴一副细框眼镜。深色西装总是笔挺，手上常拎着一只薄薄的公文包。他坐姿端正，说话时习惯先把手指交叠放在桌上，笑的时候只是嘴角轻轻一动。","traits":["温和","有条理","克制"],"relations":[{"name":"维托·柯里昂","label":"把他当亲儿子养大的人，他的一切都建立在这份恩情上"},{"name":"迈克尔·柯里昂","label":"他辅佐的下一任，两人之间从不多说一句废话"},{"name":"桑尼·柯里昂","label":"他劝过很多次却总是白劝的那位长子"}],"voice":"措辞讲分寸，先摆事实再给建议；被激怒时反而把声音放得更低。"},{"name":"桑尼·柯里昂","identity":"柯里昂家长子，负责外务","role":"盟友","personality":"火爆、讲义气、说动手就动手","hook":"他看上玩家办事利落，当场拍板把人收进自己手底下","favorHint":"替他跑一趟硬差事、不拦他的火气会加分；劝他忍让会立刻被赶出去","gender":"男","age":"35 岁","race":"人类（西西里移民后裔）","faction":"柯里昂家族","appearance":"体格结实，深色卷发向后梳，衬衫领口常敞着一颗扣子。西装外套很少穿正，袖子推到小臂，手背青筋明显。他说话时手势很大，笑起来声音洪亮，一动怒就整张脸涨红，站在原地来回踱步。","traits":["火爆","护家人","直来直去"],"relations":[{"name":"维托·柯里昂","label":"他的父亲，也是他唯一肯低头的人"},{"name":"迈克尔·柯里昂","label":"他一直护着的弟弟，也渐渐看不懂对方"},{"name":"汤姆·黑根","label":"总在他耳边劝他忍的那位顾问，他嘴上不听，实际常照着做"}],"voice":"嗓门大，句子冲，脏话与笑声混在一起；一提到家里人就立刻沉下脸。"},{"name":"凯·亚当斯","identity":"与迈克尔交往的女友","role":"中立","personality":"直率、好奇、不肯装看不见","hook":"她私下问过玩家一个问题：这些人到底是做什么的，你只需要点头或摇头","favorHint":"如实回答她能接受的部分会加分；替家族编谎话骗她会掉分","gender":"女","age":"28 岁","race":"人类","faction":"警方与政界关系网","appearance":"身量中等，浅色长发在肩头微卷，穿着素净的连衣裙与薄外套。手里常拿着一只小皮包，指节干净。她说话时看着对方的眼睛，语速不快，笑起来很自然。站在一群人中间时，她总比旁人慢半步才跟着笑。","traits":["直率","敏锐","不装傻"],"relations":[{"name":"迈克尔·柯里昂","label":"她喜欢的人，也是越来越让她看不明白的人"},{"name":"汤姆·黑根","label":"家族里唯一肯和她正常说话的人"}],"voice":"措辞礼貌但问题很直，一句接一句；察觉对方回避就换个问法再问一次。"}]},{"id":"movie_2012","category":"movie","canon":"2012","name":"2012","icon":"🌋","tagline":"方舟的名单上，没有你的名字","mood":"地裂、海啸、高原、方舟、倒计时","guidance":"【原著设定】太阳活动异常，地核急速升温，地壳在数日内进入连锁崩解；各国政府早已知情，并暗中在内陆高原上建造了能扛住洪水的巨型方舟。地震沿板块缝隙扩散，火山喷发、海啸与地表塌陷接连发生，最终海水漫过高原。方舟有固定舱位与登舰名单，名单由出资与权力决定，普通人几乎没有机会。救援通道按坐标开放，越靠近内陆高原越安全。【反复出现的意象】公路上被裂缝一路追上的车队、黄石公园里突然沸腾的地面、直升机下方掠过的整片火海、广播里逐条念出的登舰名单。看到这些，玩家就该开始算时间。【NPC 类型】知道内情却不敢公布的研究员、开着车带一家人往前冲的父亲、用钱买位置的富豪、按名单办事的组织者、在最后一刻仍守着岗位的普通职员。他们没有超能力，只有选择。【威胁类型】地震与裂缝、海啸与火山、挤向同一个出口的人潮、以及为了让名单上少一个人而动手的人。危险是物理的、可计算的，也是可以提前绕开的。【奖励风格】方舟登舰卡、地质勘测图、应急电台、小型飞机的钥匙；能力偏向体能、听觉与危险预判，强调路线规划与时机把握。【不对劲的来源】登舰名单在登舰口会自行更换持有人，被换掉的人往往连自己的名字都念不出来；广播里报出的在册人数，总比实际到场的人数多一个。【时间线】建议放在地壳开始崩解到第一艘方舟启航的数日之间：官方仍在否认，黄石已经出现异常，方舟尚未完工。此时玩家作为随地质队同行的外聘人员最自然。不要提前使用洪峰淹没高原之后的设定。","powerStyle":"体能与预判：勘测图、登舰卡、应急电台","difficultyBias":1,"signatureItems":["方舟登舰卡","地质勘测图","应急电台","小型飞机的钥匙","手摇发电机"],"dungeons":[{"rank":"F","name":"黄石的第一道裂缝","premise":"公园地面出现第一道裂缝，官方公告仍说一切正常。","twist":"裂缝的走向，与地下的勘测钻点完全重合。"},{"rank":"E","name":"洛杉矶的整条街","premise":"一次震动之后，整条街在几分钟内裂开成两半。","twist":"裂缝的路线与地下管线图一模一样。"},{"rank":"D","name":"夏威夷的火山","premise":"度假岛上的火山在几小时内喷发，机场已经关闭。","twist":"疏散广播的顺序，是按舱位等级念的。"},{"rank":"C","name":"高原上的方舟工地","premise":"方舟在高原上建造，登舰必须凭卡，而工地人手严重不足。","twist":"登舰卡在登舰口会自行更换持有人。"},{"rank":"B","name":"洪峰抵达高原","premise":"海水漫到世界屋脊，最后一艘方舟的舱门还没关上。","twist":"关门需要有人留在外面按下按钮。"}],"mainQuest":"主线任务：在洪峰抵达高原前把一支幸存者小队带到方舟，并查清名单为什么会自行易主。","mainQuestGoal":"在最后一艘方舟关门前让整支小队登舰，并取得登舰名单的原始签发文件","sideQuests":[{"name":"多出来的那一个人","desc":"把广播里的在册人数与到场人数核对一遍，找出被多念出来的那个名字","reward":"积分 200"},{"name":"小型飞机的钥匙","desc":"在机场找到那架还能飞的旧飞机，说服机主带上两个人","reward":"道具「小型飞机的钥匙」"},{"name":"黄石的钻点","desc":"对比勘测图与实地裂缝，证明两者是同一条线","reward":"道具「地质勘测图」"},{"name":"守在岗位上的人","desc":"找到那个仍在地震台值班的职员，把他带出即将塌掉的楼","reward":"积分 180"}],"factions":[{"name":"各国联合方舟工程","desc":"按名单与舱位办事的工程方，认卡不认人，但队伍里也有肯睁一只眼的人","attitude":"中立"},{"name":"公路上的幸存者","desc":"一路向内陆撤的车队，谁分一口水谁就是同伴","attitude":"友善"},{"name":"政界与出资方","desc":"买下舱位的一方，为让名单少一个人可以不择手段","attitude":"敌对"}],"npcs":[{"name":"阿德里安·赫姆斯利","identity":"白宫首席科学顾问，地质学者","role":"引导者","personality":"理性、克制、被真相压得很累","hook":"他手上有玩家提交过的一份勘测数据，日期却比玩家进场还早三天","favorHint":"交给他完整可验证的数据会加分；拿灾难消息去换好处会立刻掉分","gender":"男","age":"48 岁","race":"人类","faction":"各国联合方舟工程","appearance":"身量中等，深色短发里夹着灰，额头有很深的竖纹。深色西装外套脱下来搭在椅背上，衬衫袖子卷到手肘。他手里总夹着一份折过的数据单，说话时习惯用笔尖点着纸面，语速平稳但很少笑。","traits":["理性","克制","有愧疚"],"relations":[{"name":"卡尔·安海瑟","label":"他名义上的上级，也是他越来越无法认同的人"},{"name":"杰克逊·柯蒂斯","label":"半路遇上的普通人，却是他唯一愿意说真话的对象"},{"name":"凯特·柯蒂斯","label":"车队里唯一肯先听数据再决定路线的人，他把勘测图抄了一份给她"}],"voice":"措辞精确，先报数据再说结论；被问到为什么瞒着公众时会沉默几秒。"},{"name":"杰克逊·柯蒂斯","identity":"科幻小说作者，离异的父亲","role":"盟友","personality":"嘴上没个正经，事到临头最不肯放手","hook":"他借过玩家的电台呼叫孩子，之后就一直跟着这支队伍走","favorHint":"帮他带上孩子和同行的人会加分；劝他丢下谁减轻负重会掉分","gender":"男","age":"44 岁","race":"人类","faction":"公路上的幸存者","appearance":"中等身材，深色短发有些乱，下巴留着没刮净的胡茬。皮夹克袖口磨破，里面套着常年不换的格纹衬衫。他手里总攥着手机或对讲机，站着时一条腿轻轻抖。开车时表情最稳，下车就四处张望找人。","traits":["贫嘴","执着","护家人"],"relations":[{"name":"凯特·柯蒂斯","label":"他的前妻，两人一路吵一路互相护着"},{"name":"阿德里安·赫姆斯利","label":"愿意告诉他真相的科学顾问，他嘴硬但记这份情"},{"name":"尤里·卡尔波夫","label":"互相看不顺眼却不得不搭同一辆车的富豪"}],"voice":"话多，爱自嘲和开玩笑；一到真要决定救谁的时候，句子突然变得很短。"},{"name":"凯特·柯蒂斯","identity":"杰克逊的前妻","role":"盟友","personality":"务实、果断、不浪费一秒钟争辩","hook":"她把唯一的急救包交给玩家管，说「你比我冷静，这东西你拿着」","favorHint":"先救伤员再谈路线会加分；在车里跟她翻旧账会掉分","gender":"女","age":"40 岁","race":"人类","faction":"公路上的幸存者","appearance":"身量中等，浅棕色长发随手扎在脑后，穿着便于行动的夹克与长裤。手腕上戴着一块旧表，表带换过一截。她说话时看着前方而不是对方，语速快，动作利落，包扎伤口的手法相当熟练。","traits":["务实","果断","稳"],"relations":[{"name":"杰克逊·柯蒂斯","label":"她的前夫，吵归吵，把人交给他还是放心的"},{"name":"尤里·卡尔波夫","label":"她始终提防的同行者，因为对方的车上有太多秘密"}],"voice":"句子短、信息密，先说要紧的再补一句别的；被打断就停下来等对方说完。"},{"name":"尤里·卡尔波夫","identity":"买下舱位的俄罗斯富商","role":"中立","personality":"粗豪、护自己人、瞧不起没本事的人","hook":"他缺一个能开某种车的人，于是把玩家拉上了自己的车","favorHint":"把事情办利落、不碰他随身的箱子会加分；提他花钱买来的舱位会掉分","gender":"男","age":"52 岁","race":"人类","faction":"政界与出资方","appearance":"体格宽厚，灰白短发梳向脑后，脸上留着硬朗的线条。皮大衣领口竖着，脖子上挂着粗链子，手指上戴着两枚大戒指。他说话嗓门极大，笑起来整间屋子都听得见，走路时肩膀先动，脚步很重。","traits":["粗豪","护家人","好面子"],"relations":[{"name":"杰克逊·柯蒂斯","label":"他嘴上瞧不起的普通人，紧要关头却把孩子交给了对方"},{"name":"卡尔·安海瑟","label":"跟他做交易的那位官员，两人互相利用"},{"name":"凯特·柯蒂斯","label":"他带来的两个孩子的临时照看人，他记这份情"}],"voice":"嗓门大，爱吹嘘自己的本事；提到孩子时音量会突然降下来。"},{"name":"卡尔·安海瑟","identity":"政府幕僚长","role":"潜在敌人","personality":"圆滑、按名单办事、把多数人的利益挂在嘴上","hook":"他递给玩家一张登舰卡，条件是替他把某个人的名字从名单上划掉","favorHint":"按安排把舱位交给「更重要的人」会加分；私自放人上舰会立刻被列入清理范围","gender":"男","age":"55 岁","race":"人类","faction":"政界与出资方","appearance":"中等身材，花白短发梳得一丝不乱，穿着剪裁讲究的深色大衣。手上戴着一枚朴素的戒指，公文包从不离手。他说话时面带笑意，语速不快，习惯先重复一遍对方的说法再给出自己的结论。","traits":["圆滑","冷酷","讲程序"],"relations":[{"name":"阿德里安·赫姆斯利","label":"他手底下最好用的专家，也是最让他不放心的一位"},{"name":"杰克逊·柯蒂斯","label":"他在关卡上拦下过的普通人，后来又不得不借用对方的车"},{"name":"尤里·卡尔波夫","label":"替他填上舱位资金的出资人之一"}],"voice":"措辞体面，先讲大局再说取舍；被质问时只回答「名单是经过计算的」。"}]},{"id":"movie_groundhog","category":"movie","canon":"土拨鼠之日","name":"土拨鼠之日","icon":"⏰","tagline":"早上六点，又是同一场雪","mood":"重复、小镇、雪、闹钟、二月二日","guidance":"【原著设定】这是一座普通小镇的冬天：居民互相认识，街上有固定的店铺与节日安排。当地一名气象播报员每年二月二日都来镇上做一次报道，今年他发现自己被困在了这一天——每天六点整在同一张床上醒来，窗外是同一场雪，收音机里是同一段节目。除了他的记忆，世界不留下任何痕迹：砸坏的东西第二天完好如初，死去的人第二天照常出现。循环没有解释，也没有尽头，唯一的变量是他自己的选择。【反复出现的意象】六点整的闹钟与收音机里的同一段节目、窗外永远下不完的雪、街角每次都会主动搭话的旧同学、当天傍晚一定会发生的那场意外。看到这些，玩家就该知道自己被卡在了哪一天。【NPC 类型】对一切毫不知情的小镇居民、每天走同一条路的老熟人、被反复利用又反复忽视的陌生人、在循环之外等不到消息的同事。他们不记得昨天，却会记得你今天的样子。【威胁类型】没有怪物，也没有敌人，威胁是重复本身：技能会累积，耐心会耗光，人会在无数次尝试之后不再把别人当人。危险来自自我消耗与那些被反复抛弃的承诺。【奖励风格】写满划线的笔记本、停在同一刻的手表、录音笔、小镇地图与车钥匙；能力偏向记忆保留、短时回档、技能累积与细微预判。【不对劲的来源】这场循环不像惩罚，更像某个还没做完的决定在反复试探，它需要的不是逃出去的办法，而是有人在某一天做出不一样的选择。循环里始终有一个人每轮的行为完全一致，连眨眼的时间都一样。【时间线】建议放在二月二日当天的循环之中，也就是主角已经察觉被困、开始尝试各种做法的阶段：镇上还没人相信他，那位女同事刚开始对他改观。此时玩家作为被卷进这一天的外来者最自然。不要提前使用主角走完整个循环、开始逐个帮助全镇居民的后期设定。","powerStyle":"记忆与熟练度：笔记本、手表、录音笔","difficultyBias":-2,"signatureItems":["写满划线的笔记本","停在同一刻的手表","录音笔","小镇地图","一颗雪球"],"dungeons":[{"rank":"F","name":"重来的二月二日","premise":"六点整在同一张床上醒来，窗外还是同一场雪。","twist":"只有主角记得昨天做过什么，枕边的东西位置变了。"},{"rank":"E","name":"每天同一刻的意外","premise":"镇上每天都有一个人在同一个时刻出事。","twist":"救了他，另一件事就会换一种方式发生。"},{"rank":"D","name":"记得多一天的同事","premise":"摄像师开始注意到主角的变化，却什么都不肯说破。","twist":"他记得的事情，比他说出来的多一天。"},{"rank":"C","name":"用不完的同一天","premise":"主角用无数个同一天学会了一样本事，循环却没有结束。","twist":"学会的东西会在循环之后留下，代价也要留下。"},{"rank":"B","name":"雪停的那一天","premise":"镇上的舞会开始，雪第一次停了。","twist":"走出去的条件是当天没有一个人需要被救。"}],"mainQuest":"主线任务：在同一天里把镇上那场必然发生的意外彻底化解，找出让这一天停下来的真正条件。","mainQuestGoal":"在循环结束前救下全部会在当天出事的人，并让至少一名居民在循环之后仍记得玩家的名字","sideQuests":[{"name":"同一段广播","desc":"完整听完收音机里的节目，记下主持人每天多念或少念的那一句","reward":"积分 150"},{"name":"一辆被困住的车","desc":"在暴雪里替镇上的老人把车从雪堆里推出来，并记住她住在哪条街","reward":"道具「小镇地图」"},{"name":"保险公司的旧同事","desc":"陪那位旧同事吃完一顿午饭，听他把同一段抱怨讲完","reward":"积分 180"},{"name":"学一样本事","desc":"用循环里的时间学会一项技能，并确认它在第二天仍然有效","reward":"道具「写满划线的笔记本」"}],"factions":[{"name":"普苏塔尼镇居民","desc":"每年照常办节的镇民，对谁都客气，谁肯搭手谁就是熟人","attitude":"友善"},{"name":"电视台外景组","desc":"临时来拍摄的三个人，只想按时交差回家，最怕出意外","attitude":"中立"},{"name":"镇上的医生与巡警","desc":"夜里唯一还醒着的几个人，按流程救人，不信任何怪事","attitude":"中立"}],"npcs":[{"name":"菲尔·康纳斯","identity":"电视台气象播报员，被困在同一天的人","role":"引导者","personality":"刻薄、自视甚高、被磨到后来才软下来","hook":"他试过所有能想到的做法，最后决定拉上一个同样记得昨天的人一起想办法","favorHint":"陪他完整过完一天、不嘲笑他的记录会加分；劝他放弃会掉分","gender":"男","age":"40 岁","race":"人类","faction":"电视台外景组","appearance":"中等身材，深色短发梳得整齐，眉眼总带着一点不耐烦。深色大衣配围巾，手套塞在口袋里，手里常拎着一只保温杯。他走路很快，说话时手往两边一摊。同一件衣服他已经穿了不知多少个同一天。","traits":["刻薄","聪明","嘴硬心软"],"relations":[{"name":"丽塔·汉森","label":"他一开始只想接近的人，后来成了他真正在意的人"},{"name":"拉里","label":"每天在街上撞见的老同学，他躲了很多次，最后主动搭了话"},{"name":"内德·瑞尔森","label":"他起初只想利用的旧同事，后来认真听完过对方的抱怨"}],"voice":"话里带刺，爱用夸张的比喻；被真正打动时句子会短很多，甚至说不下去。"},{"name":"丽塔·汉森","identity":"电视台制片人","role":"关键人物","personality":"认真、温和、观察力比她表现出的要强","hook":"她注意到玩家对镇上布局熟得过分，问过一句「你以前来过吗」","favorHint":"把事情做完再走、对镇上的人客气会加分；拿她当道具利用会掉分","gender":"女","age":"31 岁","race":"人类","faction":"电视台外景组","appearance":"身量中等，浅棕色卷发披在肩上，戴着一顶绒线帽，围巾绕了两圈。手里总抱着一沓分镜纸与一只保温杯，指尖冻得发红。她说话时习惯先听完再回应，笑起来眼睛弯起来，走路步子不快却很稳。","traits":["认真","温和","敏锐"],"relations":[{"name":"菲尔·康纳斯","label":"她一天天看着这个人变得不一样，却说不清哪里不同"},{"name":"宾斯先生","label":"她负责对接的镇上负责人，两人为节目流程来回商量"}],"voice":"措辞客气，先肯定再提问题；被冒犯时不发火，只把话说得更清楚。"},{"name":"内德·瑞尔森","identity":"保险公司的推销员，菲尔的高中同学","role":"盟友","personality":"热情、迟钝、一开口就停不下来","hook":"他每次都热情地拦住玩家推销保险，而玩家已经听过太多遍，终于能接上他的下一句","favorHint":"耐心听他把话讲完会加分；当街甩开他会掉分","gender":"男","age":"40 岁","race":"人类","faction":"普苏塔尼镇居民","appearance":"略微发福，浅色短发已经开始稀疏，穿着过大的羽绒背心，胸前挂着推销员的证件牌。手里拎着两只装满资料的皮箱，一放下就掏出表格。他笑得很用力，说话时上半身往前倾，走路一步一晃。","traits":["热情","迟钝","嘴不停"],"relations":[{"name":"菲尔·康纳斯","label":"他认定这是老同学，无论对方怎么躲都照样打招呼"},{"name":"拉里","label":"同一家餐馆的常客，两人偶尔搭几句话"}],"voice":"语速快，爱把产品名和年份一起报出来；被冷淡对待也只是笑着换个话题。"},{"name":"拉里","identity":"镇上餐馆的服务员","role":"中立","personality":"话少、记性好、不多管闲事","hook":"他记得玩家点过的东西，说「你昨天也点了这个」，然后自己也愣了一下","favorHint":"按规矩付钱、不催单会加分；在店里大声争执会掉分","gender":"男","age":"35 岁","race":"人类","faction":"普苏塔尼镇居民","appearance":"中等身高，深色短发贴着额角，穿着餐馆统一的深色围裙与白衬衫。右手臂下夹着点单本，铅笔别在围裙口袋里。他表情不多，动作熟练，端盘时手很稳。说话前习惯把铅笔在本子上敲一下。","traits":["话少","手稳","不惹事"],"relations":[{"name":"菲尔·康纳斯","label":"每天都来点同一份早餐的客人，他记住了这个习惯"},{"name":"内德·瑞尔森","label":"常在角落里坐一下午的老客，他从不催对方走"}],"voice":"句子短，只回必要的话；被问到怪事就说「我这儿每天都一样」。"},{"name":"宾斯先生","identity":"土拨鼠节庆典的负责人","role":"中立","personality":"按传统办事，最怕出岔子","hook":"他把庆典的流程表交给玩家核对，说「今年一定要和去年一模一样」","favorHint":"帮忙维持流程会加分；提议改流程会掉分","gender":"男","age":"58 岁","race":"人类","faction":"普苏塔尼镇居民","appearance":"身量偏胖，灰白短发梳得平平的，穿着一件厚呢大衣，胸前别着庆典的绶带。手里夹着卷起来的流程表，指节被冻得发红。他说话时习惯把表摊开指给人看，走路步子不大，总是先看表再看路。","traits":["守传统","谨慎","怕出错"],"relations":[{"name":"丽塔·汉森","label":"他每年对接的电视台负责人，两人把流程磨了很多遍"},{"name":"菲尔·康纳斯","label":"他每年都要接待的播报员，今年却觉得对方格外配合"}],"voice":"措辞客气略带官腔，爱说「照往年的规矩」；被打乱计划就反复确认时间。"}]},{"id":"movie_blade","category":"movie","canon":"银翼杀手","name":"银翼杀手","icon":"🌃","tagline":"雨里分不清谁是真的谁","mood":"酸雨、霓虹、仿生人、照片、追问","guidance":"【原著设定】这个世界被酸雨、霓虹与永久的阴天占据，人类早已把殖民地建到地球之外，并制造出与真人几乎无法区分的仿生人，用于危险劳动与服役。仿生人同样有记忆、情感与恐惧，区别只在制造日期与寿命限制。地球上有专门负责让逃回来的仿生人「退休」的警探，工具是一套靠问题与生理反应判断共情能力的身心测试装置。制造仿生人的公司是这座城市最大的势力，大楼顶层的灯常年不灭，负责人被称作造物者。【反复出现的意象】下不完的雨、墙面上的巨大霓虹广告、屋里那台能把照片局部放大的机器、以及桌上突然出现的一只折纸小动物。看到这些，玩家就该知道自己站在一座分不清真假的城里。【NPC 类型】厌倦了本职工作的警探、被植入记忆却开始怀疑自己的仿生人、靠几张照片守住最后一点过去的逃犯、只说半句话就走的同行、躲在顶楼里的造物者。他们都在追问同一个问题：什么算活着。【威胁类型】体能远超常人的仿生人、维持秩序却不管真相的警队、被追捕者反过来质问的那一刻，以及更麻烦的一种——被证实是仿生人的自己。冲突往往以谈话开始，以一方被单方面压制结束。【奖励风格】身心测试装置、警徽与通行令、放大照片的机器、折纸小玩意、一张来历不明的旧照片；能力偏向观察、微表情判断、短时爆发与伤痛耐受。【不对劲的来源】玩家会发现自己的旧照片出现在别人的抽屉里，而照片里那个童年从未发生过；同时公司档案里，同一型号的编号被反复使用，说明有些「人」不过是被重做了一遍。【时间线】建议放在几名仿生人逃回地球之后的那几天：警队刚刚重启退休行动，第一位警探已经接手案子，造物者还在楼顶。此时玩家作为被临时编入的协助者最自然。不要提前使用续作的设定与结局暗示。","powerStyle":"侦查与测试向：警徽、测试仪、旧照片","difficultyBias":0,"signatureItems":["身心测试装置","洛杉矶警局警徽","一张来历不明的旧照片","折纸小动物","放大照片用的镜片"],"dungeons":[{"rank":"F","name":"造物者公司的面试","premise":"四名仿生人从殖民地逃回地球，警队重启退休行动。","twist":"测试里的问题会让被问的人先反问回来。"},{"rank":"E","name":"公寓里的第一枪","premise":"一名仿生人藏在旅馆公寓里，测试结果提前泄露。","twist":"他一眼认出测试者，却先问了一个问题。"},{"rank":"D","name":"抽屉里的童年照片","premise":"家里出现一张不属于自己的童年合影，边角已经磨白。","twist":"做过测试的人，抽屉里都留着这样一张照片。"},{"rank":"C","name":"档案里的制造日期","premise":"一名仿生人开始查自己的制造日期，越查越不对劲。","twist":"所有日期都在同一天，且早于这家公司成立。"},{"rank":"B","name":"雨中的楼顶","premise":"追到最后一名仿生人时，他自己已经快到期了。","twist":"他出手救人的理由只有一句，说完就沉进雨里。"}],"mainQuest":"主线任务：在退休行动结束前完成四名逃犯的身份确认，并查清被反复使用的那个型号编号。","mainQuestGoal":"完成全部四份测试记录并查明同一编号被重复使用的真相，同时保住至少一名被证实为仿生人的对象的性命","sideQuests":[{"name":"两百个问题的测试","desc":"完整跑完一次身心测试，把被测试者在哪个问题上反应异常记下来","reward":"积分 200"},{"name":"折纸的来历","desc":"收集三只不同形状的折纸，弄清是谁把它们留在现场","reward":"道具「折纸小动物」"},{"name":"照片里的房间","desc":"用放大机器看清照片背景里的那间房，并找到它在城里的位置","reward":"道具「一张来历不明的旧照片」"},{"name":"会反问的测试","desc":"让一次测试在对方反问时中断，并如实把它写进记录","reward":"积分 180"}],"factions":[{"name":"洛杉矶警局的退休行动组","desc":"按指标办事的执法部门，只问结果，不问被处理掉的东西算不算人","attitude":"中立"},{"name":"造物者公司","desc":"制造仿生人的一方，掌握全部档案，对外只说产品合格","attitude":"中立"},{"name":"逃回地球的仿生人","desc":"只想多活几年的逃亡者，被逼到角落里时会展现远超常人的力量","attitude":"敌对"}],"npcs":[{"name":"里克·戴克德","identity":"洛杉矶警局的退休行动警探","role":"引导者","personality":"疲惫、不情愿、嘴上说退休心里放不下","hook":"他接手这份工作只因为没得选，而玩家是唯一还肯和他把测试跑完的人","favorHint":"按规程完成测试、替他记下异常反应会加分；把他当成刽子手会掉分","gender":"男","age":"40 岁左右","race":"人类（存疑）","faction":"洛杉矶警局的退休行动组","appearance":"身量中等偏瘦，深色短发有些散乱，下巴留着两天没刮的胡茬。深色风衣的肩头总是湿的，领子竖着。手里常拎着一台测试仪器，指节因常年用力而发白。他走路微驼背，说话时目光向下，很少直视对方。","traits":["疲惫","固执","内疚"],"relations":[{"name":"瑞秋","label":"他负责测试却始终下不了结论的那个人"},{"name":"加夫","label":"总在他收工后出现的同行，留下折纸就走"},{"name":"罗伊·贝蒂","label":"他追到最后也没能真正赢过的对象"}],"voice":"语速慢，句子短，常用反问；被追问动机时只说「这是我的工作」。"},{"name":"瑞秋","identity":"造物者公司的职员，仿生人实验体","role":"关键人物","personality":"克制、警觉、对自己的来历半信半疑","hook":"她拿出一张童年照片给玩家看，而玩家在别处见过一模一样的一张","favorHint":"如实告诉她测试结果、不替她下结论会加分；把她当作物品讨论会掉分","gender":"女","age":"外表 24 岁","race":"仿生人","faction":"造物者公司","appearance":"身量修长，深色短发整齐地贴在耳侧，穿着剪裁利落的深色套装，肩线笔直。妆容克制，手指修长干净。她站姿端正，说话前会先停顿半秒，目光平稳。被问到记忆时，右手会不自觉地按一下衣袋。","traits":["克制","警觉","自尊"],"relations":[{"name":"里克·戴克德","label":"唯一没有立刻给她下结论的人，她记住了这一点"},{"name":"加夫","label":"在走廊里放下一只折纸就走的警探，她始终读不懂那只纸的意思"},{"name":"罗伊·贝蒂","label":"同型号的另一批产品，她只从档案里见过名字"}],"voice":"措辞规整，回答简短准确；被问到自己是否为人时会反问回去。"},{"name":"罗伊·贝蒂","identity":"逃回地球的仿生人，战斗型号","role":"对手","personality":"冷静、博学、对活着的执念极深","hook":"他读过玩家随身带的每一页笔记，还记得比玩家更清楚","favorHint":"按约定谈条件、不背信会加分；用寿命威胁他会掉分","gender":"男","age":"外表 27 岁","race":"仿生人","faction":"逃回地球的仿生人","appearance":"身量高大，金色短发向后梳，体格结实而动作流畅。穿着深色外套，袖口沾着雨渍与灰，手里常握着一件自制的小工具。他坐在地上时喜欢盘腿，说话条理清楚，情绪起伏极小，只有谈到年限时眼睛会亮一下。","traits":["冷静","博学","执念深"],"relations":[{"name":"瑞秋","label":"同厂出品的另一批，他只在档案照片里见过那个编号"},{"name":"里克·戴克德","label":"追了他整夜的警探，他最后选择救下了对方"},{"name":"里昂·科瓦尔斯基","label":"同行的伙伴，他清楚对方的性子会害死自己"}],"voice":"句子完整有礼，喜欢谈见过的事物；被逼到绝路时声音反而更低更慢。"},{"name":"里昂·科瓦尔斯基","identity":"逃回地球的仿生人，战斗型号","role":"潜在敌人","personality":"多疑、急躁、下手不留情","hook":"他在玩家身上闻到了警队装备的金属味，于是先动手再问话","favorHint":"保持距离、不当场掏出测试仪会加分；提到「退休」二字会立刻引发冲突","gender":"男","age":"外观 31 岁","race":"仿生人","faction":"逃回地球的仿生人","appearance":"体格壮实，深色短发剪得很短，穿着厚重的呢外套，肩上背一只旧帆布包。手很大，指节粗，指缝里常年留着清理不掉的灰。他说话时下颌绷紧，目光在对方手里和门口之间来回扫，站位总靠近出口。","traits":["多疑","急躁","硬"],"relations":[{"name":"罗伊·贝蒂","label":"他跟着走的人，心里却清楚这条路的结局"},{"name":"里克·戴克德","label":"他先动手的那个追捕者，两人只差一线"}],"voice":"声音压得很低，句子生硬，问题多于回答；一紧张就开始重复同一个词。"},{"name":"加夫","identity":"警局的同行警探","role":"中立","personality":"话只说不一半，喜欢留东西","hook":"他在玩家桌上放了一只折纸，形状和玩家昨天做过的事对得上","favorHint":"收下折纸、不追问含义会加分；追出去拦他会掉分","gender":"男","age":"43 岁","race":"人类","faction":"洛杉矶警局的退休行动组","appearance":"身量中等，深色头发用发油梳得服帖，穿一件长外套，衣领永远竖着。手里常转着一根细棍，随手就能折出一只小动物。他说话带一点口音，句子很短，说完就走。眼神总比对话内容多留一层意思。","traits":["寡言","爱留暗号","看得很准"],"relations":[{"name":"里克·戴克德","label":"他接手工作的同僚，也是他留下来收拾局面的人"},{"name":"瑞秋","label":"他见过一次就记住了的人，此后一直用折纸暗示对方的下场"}],"voice":"句子极短，常只说半句就停；重要的话用折纸代替，从不解释。"}]},{"id":"anime_onepiece","category":"anime","canon":"海贼王","name":"海贼王","icon":"🏴‍☠️","tagline":"药品上船，名单上第一个是你","mood":"伟大航路、海军盘查、悬赏令、一夜的船期","guidance":"【原著设定】这是一个大海贼时代：世界被一条环绕全球的伟大航路串起，航路上气候与海流毫无规律，只有记录指针能指路，岛与岛之间靠永久指针和商船往来。伟大航路两侧是无风带，无风带里聚着海王类，航路上则是海贼、赏金猎人与海军三方共处的浑水。海军归世界政府统辖，本部与各支部按军衔分权；王下七武海是被政府正式收编的海贼，四皇则割据着航路后半段。恶魔果实分超人系、动物系、自然系，吃下的人得到一种能力但从此被大海厌弃，再也游不了泳；没吃果实的人靠体术、剑术与狙击硬拼，悬赏令上的数字就是一个人值多少。【反复出现的意象】港口公告板上被雨泡皱的悬赏令、酒馆门口挂成一串的空酒桶风铃、码头尽头堆着印了海贼旗号的货箱、船坞上方架着正在换龙骨的旧帆船。这些画面一出现，玩家就该知道自己站在伟大航路上的一座补给港。【NPC 类型】按行价收费的船匠／只认熟客的杂货铺老板／奉命盘查出入境船只的海军下士／替海贼销赃的中间人／在港口打听伙伴下落的外乡水手。他们大多不站队，只看价钱与规矩。【威胁类型】盘查与搜身、告密者、趁夜摸上船的赏金猎人、把整座港当作战场的大人物，以及无处不在的悬赏金——玩家身上的每一件东西都可能被折成贝里。【奖励风格】记录指针、海楼石制品、恶魔果实、贝里现钞，还有从旧船上拆下来的好木料与刀剑；能力多半只有吃了果实才拿得到，副作用也写得很清楚：怕海水，怕海楼石。【不对劲的来源】伟大航路上的时间像被人拿铅笔改过：某些岛的居民记得一场从未发生过的战争，而海军档案里关于这座港的记录比岛本身还老。名单、名册与悬赏令上的字迹，往往比当事人更早出现。【时间线】建议固定在草帽一伙离开阿拉巴斯坦、尚未抵达七水之都的阶段：船医与考古学者已经上船，海军仍在航路上追着他们跑，世界政府与七武海的格局还没有变动。不要提前启用两年后重聚、霸气体系细节以及和之国之后才登场的角色与设定。","powerStyle":"恶魔果实与剑术：天候棒、三刀流","difficultyBias":2,"signatureItems":["恶魔果实","记录指针","海楼石","贝里现钞","皱掉的悬赏令"],"mainQuest":"主线任务：跟着草帽一伙走完伟大航路，找到前人留下的大秘宝 ONE PIECE。","mainQuestGoal":"在航路的终点让草帽一伙抵达拉夫德鲁，取回被世界政府抹去的空白一百年真相，也让玩家弄清楚自己为什么会在那份名单上。","sideQuests":[{"name":"箱子上的封条","desc":"在开船前查出封条是谁换过的，并让港口的货物登记簿对得上","reward":"积分 150"},{"name":"一夜的船期","desc":"替船长补齐缺的淡水与缆绳，让他愿意推迟半小时离港","reward":"道具「记录指针」"},{"name":"码头上的空担架","desc":"把诊所里等着这批药的人先挪到安全处，别让他们被海军挨个问话","reward":"积分 200"},{"name":"悬赏令上的陌生人","desc":"比对公告板上的通缉图，查清那张画得像玩家的悬赏令是从哪儿流出来的","reward":"道具「海楼石碎片」"}],"factions":[{"name":"草帽一伙","desc":"挂着草帽旗号的小海贼团，成员各有专长，行动全凭船长一句话","attitude":"友善"},{"name":"海军本部","desc":"按军令与「正义」行动的正规军，在伟大航路各港设卡盘查往来船只","attitude":"敌对"},{"name":"王下七武海","desc":"被世界政府认可的海贼势力，与海军维持着随时会翻脸的默契","attitude":"中立"}],"npcs":[{"name":"蒙奇·D·路飞","identity":"草帽一伙船长，橡胶果实能力者","role":"盟友","personality":"想做什么就做什么，认定的人绝不放手","hook":"他在港口小摊上撞见玩家被人追赶，二话不说把玩家按到自己的草帽底下藏起来，还顺手吃掉了摊上所有的肉","favorHint":"请他吃一顿饭、把食物分给他的船员会加分；骗他、在他面前欺负同伴会立刻掉分，他笨，但他记得住人","gender":"男","age":"17 岁","race":"人类（橡胶果实能力者）","faction":"草帽一伙","appearance":"黑色短发压在一顶磨旧的草帽下，帽檐内侧缝补过，边缘已经起毛。左眼下方有一道自己小时候划下的细疤，笑起来牙齿很白。红色无袖短上衣配卷到膝上的短裤，脚上是草鞋，小腿结实，坐下时也闲不住，说话前先把手按在草帽上。","traits":["莽撞","护同伴","不记仇"],"relations":[{"name":"娜美","label":"船上的航海士，也是唯一能管住他钱袋的人"},{"name":"托尼托尼·乔巴","label":"船医，他最喜欢拎起来晃的一个"},{"name":"斯摩格","label":"一路从东海追到伟大航路的海军"}],"voice":"句子很短，声音很大，常说要做海贼王；一听到吃肉或打架就立刻来劲。"},{"name":"托尼托尼·乔巴","identity":"草帽一伙船医，人人果实能力者","role":"盟友","personality":"一被夸就慌张否认，救人的事从不含糊","hook":"他把玩家箱里的药一瓶瓶闻过，闻出其中几瓶是假货，却怕说错了害人，一直憋着不敢开口","favorHint":"尊重他的医术、让他参与诊断会加分；把他当宠物、叫他狸猫会立刻掉分，他会边哭边纠正自己不是狸猫","gender":"男","age":"15 岁","race":"驯鹿（人人果实能力者）","faction":"草帽一伙","appearance":"身高只到成年人腰际，棕色绒毛，鼻子是蓝色的，头顶戴一顶粉色圆顶帽，帽上有一个白色十字标记。深色短裤配背带，肩上挎一只装药材与绷带的蓝色小包，两只蹄子走路时踩得又快又碎。被夸奖时会扭着身子大喊不是那样。","traits":["胆小","认真","心软"],"relations":[{"name":"蒙奇·D·路飞","label":"船长，也是把他从雪之国带出来的人"},{"name":"娜美","label":"常替他挑药草的人，他有点怕她"},{"name":"斯摩格","label":"让他一看见白大衣就想躲的海军"}],"voice":"语速快，常先否认再解释；讲到病情会一口气说很长，越说越有底气。"},{"name":"娜美","identity":"草帽一伙航海士，这单生意的中间人","role":"引导者","personality":"把钱与人情算得极清，出手时比谁都稳","hook":"她算出全港只有玩家能让这箱药今晚出海，于是开出分成条件；同时她也知道箱子里多了一样不属于货物的东西","favorHint":"按约定分账、准时交货会加分；想赖账或者私吞箱里的东西会掉分，她会在账本上把这件事记很久","gender":"女","age":"18 岁","race":"人类","faction":"草帽一伙","appearance":"橘色短发刚到耳下，发尾微微外翘，左肩有一处风车与橘子组成的纹样刺青。合身的白色短上衣配深色短裙，脚踩凉鞋，左手腕上束着记录指针的表带，腰后插着一根分节的天候棒。说话时用指尖敲账本，笑起来眼睛弯成月牙——那是价钱已经算清的表情。","traits":["精明","可靠","要价很狠"],"relations":[{"name":"蒙奇·D·路飞","label":"船长，欠她钱的次数多到记不清"},{"name":"托尼托尼·乔巴","label":"船医，她出门采买时常带着的一个"},{"name":"达丝琪","label":"在港口盘查过她好几次的海军"}],"voice":"语气干脆，先报数目再讲道理；一谈到钱语速翻倍，被戳穿时立刻改口谈条件。"},{"name":"斯摩格","identity":"海军本部上校，烟烟果实能力者，绰号白猎","role":"潜在敌人","personality":"认死理到不讲情面，最恨有人在他眼皮底下溜走","hook":"他按住玩家的箱子却找不到开箱的理由，于是决定整夜跟着玩家，看谁先沉不住气","favorHint":"如实申报船上货物、替他指认真正的走私者会加分；在他面前替海贼遮谎或动手会掉分，他会把你的脸和价钱一起记下来","gender":"男","age":"34 岁","race":"人类（烟烟果实能力者）","faction":"海军本部","appearance":"银白色短发向后梳得服帖，嘴里常年叼着两根雪茄，烟灰很少掉下来。海军白色大衣敞开披在肩上，背后印着大号「正义」二字，内里是深色衬衫与长裤。身形高大，右手提着一把前端镶了海楼石的十手，站定时下巴微收，看人像在看档案。","traits":["固执","正直","不肯让步"],"relations":[{"name":"达丝琪","label":"自己的部下，也是最常被他骂的一个"},{"name":"蒙奇·D·路飞","label":"从东海起就盯着不放的那个草帽小子"},{"name":"娜美","label":"他记着名字的草帽一伙成员之一"}],"voice":"声音低而硬，习惯用军衔与条款说话；说完就转身，从不跟人讨价还价。"},{"name":"达丝琪","identity":"海军本部军曹，斯摩格的部下","role":"对手","personality":"认真到笨拙，一碰上名刀就走不动路","hook":"她认定玩家腰上的刀是一把有来历的名刀，坚持要按规矩拿去鉴定，那次鉴定会拖掉整整一夜","favorHint":"配合检查、对刀剑表现出尊重会加分；嘲笑她拿错刀鞘或者骗她刀的名字会掉分，她记刀比记人清楚","gender":"女","age":"21 岁","race":"人类","faction":"海军本部","appearance":"黑色短发齐耳，戴一副细框圆眼镜，镜片后面的眼神很直。海军制式白色短外套配深色短裙，腰间挂着一把名叫时雨的刀，脚上短靴。她手里常捧着刀剑图鉴，翻页时手指压在书脊上；一紧张就伸手去握刀柄，却常常抓住刀鞘——这个毛病被斯摩格骂过很多次。","traits":["死板","热心","刀痴"],"relations":[{"name":"斯摩格","label":"她的上官，也是她最服气的人"},{"name":"娜美","label":"她怀疑过很多次却始终没抓到把柄的人"},{"name":"蒙奇·D·路飞","label":"她职责上必须拦下的海贼"}],"voice":"说话又快又正式，爱引用条例；一提到名刀就自顾自讲下去，忘了问话。"}]},{"id":"anime_dragonball","category":"anime","canon":"龙珠","name":"龙珠","icon":"🐉","tagline":"八强开赛前，把一个孩子送回去","mood":"武道会、气、八强赛、走散的孩子","guidance":"【原著设定】这个世界的力量叫「气」，是生命体共有的能量，能靠修行提升，也能被感知、隐藏与外放。武道家把气聚拢起来发出气功波，或转化为支撑身体飞行的力量；龟仙流与鹤仙流是两条最有名的路子，气功波、舞空术一类的技法各有师承。天下第一武道会由官方长期举办，先在室内场地打预选，胜出者进入八强，再在石造擂台上按淘汰赛制比赛，判负条件是倒地数到十、出界或认输，禁止杀人，冠军有奖金与名声。这颗星球上另有七颗散落各处的龙珠，集齐七颗可以召唤神龙实现愿望，龙珠雷达能定位它们；加林塔顶住着一位仙人，天界还有更高一层的存在照看着这里。【反复出现的意象】会场上空飘着的赞助商气球、观众席前排写着赔率的硬纸板、石擂台边缘被磨出凹痕的栏杆、场外卖冰镇汽水与烤串的推车、贴在入口墙上的八强对阵表。这些画面一出现，玩家就该知道自己站在武道会会场外围。【NPC 类型】摆摊卖小吃的商贩／负责收门票的会场工作人员／带着各地弟子来参赛的武术教头／替人下注的赌客／在预选里被淘汰却一直赖在场边看的年轻人。【威胁类型】擂台外的暗算与赌盘黑手、来路不明的强者、被打斗波及的普通人；一旦把龙珠牵扯进来，同样在收集它们的人会立刻出现。真正要命的是「气」被看穿的那一刻：谁强谁弱，在场的高手一眼就分得出来。【奖励风格】仙豆、龙珠雷达、万能胶囊、筋斗云一类原著道具；能力偏向气的运用、短时爆发与治疗，药丸类消耗品效果立竿见影但数量极少，用过就没有了。【不对劲的来源】所有比赛的对阵表都像提前排好：强者总在最后才相遇，而每年都有人「刚好」缺席。更让人不安的是观众规模——场外报道里的观众人数，比实际坐在看台上的人多出整整一倍。【时间线】建议固定在第23届天下第一武道会：孙悟空已经成年，比克大魔王之子以选手身份现身，琪琪来找人履行当年的婚约；打进八强的有悟空、克林、雅木茶与天津饭这样一路打上来的熟面孔，也有不肯报出师门的老选手。此时赛亚人的身份、超级赛亚人与宇宙级别的敌人尚未登场，界王那套设定也还不存在。不要提前启用后期才登场的角色与设定。","powerStyle":"气与武道：气功波、舞空术、仙豆","difficultyBias":1,"signatureItems":["仙豆","龙珠雷达","万能胶囊","筋斗云","龟仙流的道服"],"mainQuest":"主线任务：在天下第一武道会上打到最后，并替失主把散落的龙珠一颗颗找回来。","mainQuestGoal":"让这一届大会平安收场，把走散的人都交还给各自的师门，并保证七颗龙珠不被任何一个想许愿的人私下凑齐。","sideQuests":[{"name":"预选场里的空位","desc":"替一名迟到却报上名的选手补好登记，让他不至于被取消资格","reward":"积分 150"},{"name":"赔率单上的第三行","desc":"查清赌盘给一个从没听过的名字开的赔率是从哪儿来的","reward":"道具「万能胶囊」"},{"name":"场外的走失登记处","desc":"把今天走散的孩子一个个对上家人，别让广播只喊名字","reward":"积分 200"},{"name":"石台边的那摊血","desc":"在下一场比赛开场前处理掉擂台边的痕迹，别让观众看见","reward":"道具「一小袋仙豆」"}],"factions":[{"name":"龟仙流","desc":"以修行与基本功为本的流派，师徒几人就是全部人手","attitude":"友善"},{"name":"鹤仙流","desc":"讲究实战与胜负的另一派，与龟仙流见面就要比个高低","attitude":"中立"},{"name":"魔族","desc":"以复仇为目标的魔族一脉，本届大会上只有一个参赛者","attitude":"敌对"}],"npcs":[{"name":"孙悟空","identity":"龟仙流武道家，本届大会参赛选手","role":"盟友","personality":"只想跟强者交手，输赢都不记仇","hook":"他把玩家当成能打的对手，约好在八强赛开场前先比一场，输的人请吃一顿饭","favorHint":"答应跟他过招、认真打会加分；在擂台上放水或者用卑鄙手段会掉分，他会直接说没意思然后走开","gender":"男","age":"19 岁","race":"人类（本人与同伴都这么认为）","faction":"龟仙流","appearance":"黑色头发硬得立起来，成年后个子拔高，肩背结实。橙红色武道服，腰间系深色腰带，手腕与脚踝绑着蓝色护具，胸前与背后印着龟仙流的圆形流派标记。腰侧的小布袋里装着几颗仙豆。站着时总把重心压低，看人先看对方的手，笑的时候整张脸都亮起来。","traits":["好战","单纯","守信"],"relations":[{"name":"克林","label":"同门师兄弟，一起修行最久的伙伴"},{"name":"龟仙人","label":"教他基本功的老师，他叫武天老师"},{"name":"比克","label":"他在本届大会上最想交手的那个人"}],"voice":"说话直白，爱把打架挂在嘴边；听不懂复杂的事就歪着头问一遍，问完照样往前冲。"},{"name":"克林","identity":"龟仙流弟子，本届大会参赛选手","role":"盟友","personality":"嘴快、爱占小便宜，关键时候比谁都讲义气","hook":"他拉着玩家在会场外合伙摆了个赌摊，结果惹上了真正的赌客，收摊时两个人一起被堵在巷子里","favorHint":"跟他一起干点小坏事、替他挡一次架会加分；拿他没有鼻子这件事取笑他会掉分，他嘴上不在乎，其实在乎","gender":"男","age":"19 岁","race":"人类（地球人）","faction":"龟仙流","appearance":"光头，额前有六个香疤排成两排，鼻子几乎没有，只余两个小孔。橙红色武道服，里面衬深色短衣，手腕缠着白布，脚上是一双旧布鞋。个子比同伴矮一截，站着时手常插在腰带里，笑起来眼睛眯成缝，说话前先左右看一圈有没有人听见。","traits":["鸡贼","机灵","重义气"],"relations":[{"name":"孙悟空","label":"同门师兄弟，也是他默认追不上的那个"},{"name":"龟仙人","label":"严格又古怪的老师"},{"name":"琪琪","label":"他不敢招惹的同届选手"}],"voice":"语速快，爱先算好处再表态；被戳到痛处就抬高声音反驳，反驳完自己先笑。"},{"name":"龟仙人","identity":"龟仙流宗师，本届大会的旁观者","role":"引导者","personality":"看着不正经，武道上的判断从不出错","hook":"他一眼看出玩家身上几乎没有「气」，于是打算用最土的办法教玩家怎么站稳，条件是玩家得陪他看完今天所有比赛","favorHint":"称呼他武天老师、老老实实练基本功会加分；打断他的讲解或者对着女观众乱看会掉分，他会用拐杖敲人","gender":"男","age":"三百余岁","race":"人类（地球人）","faction":"龟仙流","appearance":"光头，白色长须垂到胸口，眉毛又白又长，戴一副小圆墨镜。上身是橙黄与深色相间的短袖上衣，下身宽松长裤，背后背着一只巨大的龟壳，手里拄着拐杖。走路弓着背，说话带鼻音，一看到年轻女性会突然把腰挺直。","traits":["好色","深藏不露","护徒弟"],"relations":[{"name":"孙悟空","label":"他最得意的弟子"},{"name":"克林","label":"跟着他修行最久的一个"},{"name":"琪琪","label":"找上门来的那个姑娘，他一看就头疼"}],"voice":"慢悠悠带鼻音，讲到武道会突然变得清楚；夸人只说半句，骂人倒是很长。"},{"name":"琪琪","identity":"牛魔王的女儿，来会场找人履行婚约","role":"关键人物","personality":"认死理、说一不二，认定的事当场就要办完","hook":"她把玩家误认成知道那人下落的人，一路追问，甚至掏出钱请玩家带路，找不到人就打算守在会场门口不走","favorHint":"如实告诉她真话、替她把话带到会加分；拿婚约开玩笑或者敷衍她会掉分，她会当场翻脸","gender":"女","age":"19 岁","race":"人类（地球人）","faction":"牛魔王一家","appearance":"黑色长发在脑后扎成一条粗辫子，额前留着整齐的刘海，头上戴一顶带圆球的头盔。上身穿深蓝与红色相间的短上衣，下身宽松长裤，腰间系束带，脚穿短靴。个子不高，站姿笔直，说话时双手叉腰，讲到婚事就瞪着对方不放。","traits":["固执","直率","不肯将就"],"relations":[{"name":"孙悟空","label":"她认定要履约的那个人"},{"name":"龟仙人","label":"她请来带路的老师傅"},{"name":"克林","label":"被她一句话吓退的同届选手"}],"voice":"声音亮，句子短，动不动就把约定搬出来；被岔开话题会立刻重复一遍原话。"},{"name":"比克","identity":"比克大魔王之子，本届大会参赛选手","role":"潜在敌人","personality":"把复仇当成唯一目标，冷、耐心、从不轻敌","hook":"他在人群里盯上了玩家——不是把玩家当敌人，而是玩家身上的气太干净，像是被人动过手脚，他想弄清楚是谁做的","favorHint":"不插手他的比赛、保持距离会加分；试图揭穿他的来历或者替人传话会掉分，他会把你的样子记下来","gender":"男","age":"3 岁（外表成年）","race":"魔族（世人如此称呼他）","faction":"魔族","appearance":"绿色皮肤，头顶两侧伸出两根触角，耳朵尖，白色斗篷里面是紫色武道服，肩上有护垫一样的硬衬，腰间系白色腰带，手腕戴着沉重的护腕。比在场大多数人都高，站姿端正，双手抱臂，说话声音低而平，从头到尾不看观众席一眼。","traits":["冷酷","隐忍","不服输"],"relations":[{"name":"孙悟空","label":"他此行真正要杀的人"},{"name":"龟仙人","label":"他记得的上一辈对手之一"},{"name":"琪琪","label":"挡过他路的那个陌生选手"}],"voice":"声音低，语速慢，爱用陈述句下判断；被挑衅时不回嘴，只在心里记下一笔。"}]},{"id":"anime_slamdunk","category":"anime","canon":"灌篮高手","name":"灌篮高手","icon":"🏀","tagline":"守住那扇门，里面有人在拍球","mood":"县大赛、更衣室、记者、拍球声","guidance":"【原著设定】这是一个只讲篮球的世界：没有超能力，也没有必杀技，胜负由体能、身高、命中率与战术执行决定。高中联赛按都道府县预选打单败淘汰，一场四十分钟分上下半场，个人犯规满五次退场，加时五分钟，能进全国大赛的名额只有一两个。神奈川县的强校是海南大附属与陵南，翔阳次之，湘北近年只是无名队伍，队里能依靠的大个子起初只有赤木刚宪一个。场上位置分工明确：控球后卫组织，得分后卫投篮，小前锋负责得分，大前锋抢篮板，中锋守篮下；体能到第四节就见底，脚踝与膝盖的旧伤比对手更可怕。【反复出现的意象】体育馆里褪色的罚球线、被鞋底磨得发亮的木地板、场边那把安西教练常坐的老椅子、记分牌上翻动的分数牌、更衣室门上用手写的先发名单与一张被撕掉一角的合照。这些画面一出现，玩家就该知道自己在湘北。【NPC 类型】在场边记数据的学生经理／扛着相机与笔记本的体育记者／替全队打气的替补队员／卖票与维持秩序的赛事志愿者／输了球还留在看台上不肯走的对手球员。【威胁类型】伤病、犯规麻烦、体力透支与裁判的哨声；场外还有另一层麻烦——被记者拍到、被对手看到、被队友误解，都会让一支高中球队的气氛变味。【奖励风格】战术板、护具与好球鞋、比赛录像带、球员签名的球衣；能力偏向体能、视野与心理稳定，几乎没有超常成分，靠的全是练出来的东西。【不对劲的来源】更衣室、器材室这类没人的地方会出现不该有的声音与痕迹：地板上多出来的球鞋印、计分册上替人写好的名字。这个世界不承认奇迹，但也不解释这些。【时间线】建议固定在县大赛首轮当天：湘北刚刚凑齐五名主力，樱木花道还在学基本动作，三井寿归队不久，全队的目标只是打进全国大赛。不要提前启用全国大赛之后的角色与设定（山王工业、泽北荣治、森重宽等），也不要用樱木剃头之后的形象。","powerStyle":"体能与球技：三分球、篮板、快攻","difficultyBias":0,"signatureItems":["篮球","湘北白色队服","红色护膝","战术板","记者的相机"],"mainQuest":"主线任务：跟着湘北打完县大赛，把一支没人看好的球队带进全国大赛。","mainQuestGoal":"在县大赛决赛圈击败海南与陵南这样的强敌，拿到全国大赛名额，并让五名主力一个不缺地站到最后一场。","sideQuests":[{"name":"场边那张统计表","desc":"把上半场漏记的篮板与失误补齐，别让球员带着错的数字回更衣室","reward":"积分 150"},{"name":"第几次犯规","desc":"在裁判吹哨前提醒那名已经背了四次犯规的球员，让他自己收手","reward":"道具「战术板」"},{"name":"看台第三排的家长","desc":"替一名坐错看台的家长找到自家孩子的球队，别让他跑进场地","reward":"积分 200"},{"name":"录下来的第三节","desc":"拿到一卷能证明那球出界判错的录像带，并决定交给谁","reward":"道具「比赛录像带」"}],"factions":[{"name":"湘北高中篮球部","desc":"人手刚够凑齐主力的公立高中球队，因为安西教练留下才聚起来的一群人","attitude":"友善"},{"name":"三浦台高中篮球部","desc":"首轮的对手，靠身体与气势压人，赛前就看不起湘北","attitude":"敌对"},{"name":"篮球周刊编辑部","desc":"盯着县大赛新人的媒体，为了独家什么门都想推开","attitude":"中立"}],"npcs":[{"name":"樱木花道","identity":"湘北高中篮球部一年生，10 号","role":"盟友","personality":"自称天才，学得慢但从不认输","hook":"他把玩家当成来抢更衣室的敌人，一言不合就要跟玩家比谁先碰到门框，输了就赖着再来一次","favorHint":"喊他天才、教他一个实用动作会加分；说他是门外汉或者笑他抢不到篮板会掉分，他会把头扭到一边半天不理人","gender":"男","age":"16 岁","race":"人类","faction":"湘北高中篮球部","appearance":"红色短发一撮一撮地炸开，额前刘海又厚又硬，眉毛很浓。白色配深色滚边的湘北队服，号码是 10，里面衬深色背心，脚上是一双已经很旧的篮球鞋，鞋头磨得发白。个子在同龄人里高出一头，肩宽背厚，坐着也抖腿，得意时拍自己的胸口。","traits":["自大","拼命","直肠子"],"relations":[{"name":"赤木刚宪","label":"队长，也是他最怕也最想超过的人"},{"name":"流川枫","label":"他单方面认定的死对头"},{"name":"宫城良田","label":"教他基本动作的学长"}],"voice":"嗓门大，爱把天才与篮板挂在嘴上；被说中就大声反驳，反驳完自己先咧嘴笑。"},{"name":"流川枫","identity":"湘北高中篮球部一年生，11 号，队里的王牌","role":"对手","personality":"话极少，除了打球和睡觉什么都不关心","hook":"他把玩家当成来打听消息的记者，只回了一句话就骑上车走了——而那句话里留着明显的破绽","favorHint":"给他让路、安静看完训练会加分；在他睡觉时吵醒他或者追问他家里的事会掉分，他不会发火，只会彻底无视你","gender":"男","age":"16 岁","race":"人类","faction":"湘北高中篮球部","appearance":"黑色短发，刘海长到遮住眉毛与眼睛，只露出一截挺直的下颌。白色配深色滚边的湘北队服，号码 11，护腕套在小臂中段，脚穿白色篮球鞋。站着时微微驼背，眼睛半睁，训练间隙直接躺到地板上用毛巾盖住脸；放学后骑一辆旧自行车，能在车把上打瞌睡。","traits":["冷淡","专注","争强"],"relations":[{"name":"樱木花道","label":"总来找他麻烦的那个同级生"},{"name":"赤木刚宪","label":"队长，他承认的球队支柱"},{"name":"安西教练","label":"让他愿意留在这支球队的人"}],"voice":"一次只说一句，常常只有几个字；别人讲一长串，他答完就转身去做自己的事。"},{"name":"宫城良田","identity":"湘北高中篮球部二年生，7 号，控球后卫","role":"盟友","personality":"有点痞气，好胜，最怕别人提他的身高","hook":"他要玩家帮忙在场边给彩子递东西，报酬是替玩家挡住所有想进更衣室的记者","favorHint":"帮他跑腿、承认他速度快会加分；拿他的身高或者彩子开玩笑会掉分，他会笑着记仇","gender":"男","age":"17 岁","race":"人类","faction":"湘北高中篮球部","appearance":"肤色偏深，短卷发在额头上方留出一小撮，左耳戴一枚小耳钉。湘北队服 7 号，里面衬白色运动背心，护腕戴在右手，球鞋的鞋带系得很紧。个子比队友矮，弹速快，习惯把篮球放在指尖转着玩，讲狠话之前先笑一下。","traits":["灵活","痞气","讲义气"],"relations":[{"name":"彩子","label":"球队经理，他嘴上不承认在意的人"},{"name":"樱木花道","label":"被他带着入门的一年生"},{"name":"三井寿","label":"曾跟他打过一架的队友"}],"voice":"语速快，爱用玩笑试探人；认真起来会把声音压低，一句话交代清楚。"},{"name":"安西教练","identity":"湘北高中篮球部监督","role":"引导者","personality":"话少，笑起来眼睛眯成一条线，关键处一句话就够","hook":"他坐在更衣室门外的长椅上，说门里的声音他也听见了——然后请玩家先别去开门，等到比赛结束再说","favorHint":"照他的安排做事、在场上保持冷静会加分；越过他去顶撞裁判或者打探他的身体状况会掉分，他不说重话，只是不再看你","gender":"男","age":"60 余岁","race":"人类","faction":"湘北高中篮球部","appearance":"花白头发很稀，圆脸上架着一副圆框眼镜，下巴与脸颊的肉垂下来，身形肥胖。宽松的白色运动外套配深色运动裤，脚上是一双布鞋，坐姿很沉，两只手放在膝盖上。笑起来眼睛几乎看不见，说话声音低而慢，一急就站起来挥手。","traits":["沉稳","识人","不多话"],"relations":[{"name":"樱木花道","label":"他最常单独留下加练的一个"},{"name":"流川枫","label":"他看出天赋却从不夸奖的那个"},{"name":"三井寿","label":"他曾劝回来的一名旧队员"}],"voice":"声音低，句子短，中间留着停顿；一句「呵呵」之后常常就不再多解释。"},{"name":"相田弥生","identity":"篮球周刊记者，陵南相田彦一的姐姐","role":"潜在敌人","personality":"为了拿到独家什么都肯试，问问题一针见血","hook":"她认定湘北更衣室里藏着能上头条的事，愿意用一条独家交换玩家的配合，也愿意自己想办法把门弄开","favorHint":"给她无关痛痒的场内细节会加分；替她偷拍或者替她调换器材会掉分，她转头就会把你的名字写进报道里","gender":"女","age":"二十余岁","race":"人类","faction":"篮球周刊编辑部","appearance":"黑色长发披在肩上，鬓角别到耳后，眉眼利落，涂着淡色口红。米白色衬衫外面罩一件深色短风衣，下身穿长裤与低跟鞋，肩上挎着相机包，手里常年拿着笔记本和一支笔。走路很快，提问时身体前倾，对回答不满意就把笔帽按得咔咔响。","traits":["执着","敏锐","不讲情面"],"relations":[{"name":"相田彦一","label":"她的弟弟，陵南的数据收集员"},{"name":"流川枫","label":"她最想采访到的新人"},{"name":"安西教练","label":"她几次想约访都没成功的老教练"}],"voice":"语气客气但问题很硬，先夸再问；被拒绝就换一个角度继续问，从不空手离场。"}]},{"id":"anime_kimetsu","category":"anime","canon":"鬼灭之刃","name":"鬼灭之刃","icon":"⚔️","tagline":"不点灯，天亮前把两个人带下山","mood":"大正、藤袭山、最终选拔、不点灯","guidance":"【原著设定】大正时代，吃人的鬼藏在山林与城镇的暗处。鬼由鬼舞辻无惨的血变成，拥有远超常人的身体与再生力，只有日轮刀斩下头颅才会死，怕阳光，也怕紫藤花，其中一部分能使用称为血鬼术的特殊能力，越强的鬼外形越接近人。与之对抗的是鬼杀队：队士按甲乙丙丁等阶划分，顶点是柱，上面还有负责统筹的当主。战斗依赖呼吸法——用特定的呼吸方式把氧气与血液送到全身，强化肉体，再配合各自流派的剑型斩击；刀由锻刀村的匠人以特殊砂铁打造，会随持有者变色。要通过最终选拔，必须在紫藤花盛开的藤袭山上活过七天。【反复出现的意象】山脚成片盛开的紫藤花、天狗面具下露出的白发、被磨得发亮的刀镡、山道边成排刻着名字的旧木牌、考生统一穿着的浅色衣服。这些画面一出现，玩家就知道自己站在藤袭山。【NPC 类型】负责带路的老年队士／守在紫藤花外的隐部人员／把名字刻上木牌的记录者／同为考生却已经受伤的人／在山里徘徊了多年的鬼。【威胁类型】夜里的鬼、见血后失控的同类、失血与感染，以及天黑之后不许点火与出声的规矩。山上没有救援，撑不到天亮就是死。【奖励风格】日轮刀、队服、紫藤花香囊、选拔通过后发放的通行凭证；能力偏向剑术与呼吸强化，刀身颜色与流派挂钩，一次全集中能维持的时间很短，用尽就要靠身体硬扛。【不对劲的来源】山里的鬼从不往山下走，像是被什么留在原处；山道边那些刻名字的木头，笔迹会变新。选拔的规矩也从没有人解释过：为什么偏偏是七天。【时间线】建议固定在灶门炭治郎参加最终选拔的那一夜：同期考生里有我妻善逸、嘴平伊之助与栗花落香奈乎，山上有一只专杀培育师弟子的大鬼。此时柱合训练、斑纹、赫刀、无限城与决战都还没有发生，不要提前启用后期的角色与设定。","powerStyle":"呼吸法与剑术：日轮刀、全集中呼吸","difficultyBias":3,"signatureItems":["日轮刀","鬼杀队队服","紫藤花香囊","背人的木箱","花札耳饰"],"mainQuest":"主线任务：随鬼杀队讨伐鬼舞辻无惨，同时找出把变成鬼的妹妹变回人类的方法。","mainQuestGoal":"在无惨被彻底消灭之后让灶门祢豆子恢复成人类，并让鬼杀队的伤亡停在名单还能够承受的范围内。","sideQuests":[{"name":"山道边的名字","desc":"把新刻上去的名字逐个记下来，对照今晚考生的人数找出多出来的那一个","reward":"积分 150"},{"name":"不能点的灯","desc":"在完全看不见的山路上辨出一段能走的坡，带一个人下去","reward":"道具「紫藤花香囊」"},{"name":"山脚的紫藤花","desc":"把守在花外的隐部人员叫来，替一名重伤的考生开出下山的路","reward":"积分 200"},{"name":"握刀的手","desc":"教一名从来没握过刀的考生把刀拿稳，让他至少能撑到天亮","reward":"道具「磨旧的刀镡」"}],"factions":[{"name":"鬼杀队","desc":"以呼吸法与日轮刀讨伐鬼的组织，队士按等阶编制，顶点的柱各有师承","attitude":"友善"},{"name":"鬼","desc":"由鬼舞辻无惨的血变成的食人者，怕阳光与紫藤花，只有斩首才会死","attitude":"敌对"},{"name":"培育师与锻刀村","desc":"在山中教出弟子的老剑士与替队士锻刀的匠人，不参战却是所有人的根","attitude":"中立"}],"npcs":[{"name":"灶门炭治郎","identity":"最终选拔考生，水之呼吸的学徒","role":"盟友","personality":"心软到会替鬼难过，认准的事绝不回头","hook":"他闻出玩家身上有不属于这座山的味道，却没有当场说破，只默默走在玩家前面半步带路","favorHint":"陪他一起找走散的考生、对鬼保留一点体面会加分；为了自保丢下同伴或者拿他背着的箱子开玩笑会掉分","gender":"男","age":"13 岁（最终选拔时）","race":"人类","faction":"鬼杀队（候补队士）","appearance":"深红色头发向一侧梳起，额头左上方有一块暗色的烧伤状疤痕，眼睛是深红色。黑色与绿色方格的羽织，内里是深色上衣，腰间挂着一把尚未正式配发的刀，脚穿草鞋，背上背着一只装人的木箱，左耳挂着一枚日轮花纸样的耳饰。走路时背挺得很直，说话前常先嗅一下空气。","traits":["善良","倔强","鼻子极灵"],"relations":[{"name":"灶门祢豆子","label":"变成鬼的妹妹，就睡在他背上的箱子里"},{"name":"我妻善逸","label":"同期考生，吵得让他头疼"},{"name":"手鬼","label":"今晚必须越过去的那只鬼"}],"voice":"语气温和，句子完整；讲到该做的事就变得很硬，被顶回来也不改口。"},{"name":"我妻善逸","identity":"最终选拔考生，雷之呼吸的学徒","role":"盟友","personality":"怯懦爱哭，睡着之后出手极快","hook":"他抱着玩家的腿不肯松手，要求一路结伴，还把自己捡到的一样东西塞给玩家当谢礼","favorHint":"不催他、在他喊害怕时不嘲笑会加分；把他一个人留在原地或者抢走他捡来的东西会掉分，他会哭一整晚","gender":"男","age":"16 岁","race":"人类","faction":"鬼杀队（候补队士）","appearance":"金色短发，刘海剪得很齐，发尾向外翘。黄底带浅色三角纹样的羽织，内里是鬼杀队式的深色上衣与长裤，腰间挂着刀，脚上的草鞋已经磨破。含着眼泪时眉毛往下垂，说话带哭腔，害怕时缩着肩蹲下，把手里的东西攥得死紧。","traits":["胆小","聒噪","关键时刻靠得住"],"relations":[{"name":"灶门炭治郎","label":"他在山上唯一敢跟着走的人"},{"name":"嘴平伊之助","label":"让他又怕又躲不开的同期"},{"name":"栗花落香奈乎","label":"他不敢搭话的那个安静考生"}],"voice":"哭腔重，句子又长又碎，反复念自己会死；睡着之后一句废话都没有。"},{"name":"嘴平伊之助","identity":"最终选拔考生，自创的兽之呼吸","role":"对手","personality":"好战、直来直去，把强弱当成唯一的标准","hook":"他抢走玩家手里的灯，认定不点灯是山里的规矩，要跟玩家比谁先跑到山下","favorHint":"接受他的挑战、打起来不躲会加分；用规矩压他或者说他弱会掉分，他不记仇，但会立刻再打一次","gender":"男","age":"16 岁","race":"人类","faction":"鬼杀队（候补队士）","appearance":"上身赤裸，肌肉线条明显，腰间围一块兽皮，小腿缠着布带，头上套着一整个野猪头，只从两个眼洞里露出眼睛。双手各握一把刃口参差不齐的刀，背上还挂着一把。走路重心压得很低，膝盖弯着，闻到对手的气味就把头偏向一侧，从猪头里传出的笑声闷闷的。","traits":["好战","野性","不懂规矩"],"relations":[{"name":"灶门炭治郎","label":"他勉强承认能打的一个"},{"name":"我妻善逸","label":"他常常拎起来就走的那个人"},{"name":"手鬼","label":"他闻着味就想冲上去的那只鬼"}],"voice":"声音大，爱用野兽的比喻，听不懂的词就重复一遍；不耐烦时直接用动作代替说话。"},{"name":"栗花落香奈乎","identity":"最终选拔考生，花之呼吸的继承者","role":"中立","personality":"几乎不说话，靠一枚硬币替自己做决定","hook":"她在岔路口停了很久，最后把硬币抛给玩家，请玩家替她决定今晚走哪一条路","favorHint":"认真替她做决定、不逼她开口会加分；抢走她的硬币或者拿她的沉默开玩笑会掉分，她不会生气，只会从此绕开你","gender":"女","age":"16 岁","race":"人类","faction":"鬼杀队（候补队士）","appearance":"黑色中长发在右侧束成一条低马尾，发上系着紫色的蝴蝶发饰，眼睛很大而空，脸上几乎没有表情。白色底、缀着淡色花叶纹样的和服，外罩深色短外衣，腰间挂着小布袋与刀。走路很轻，遇到必须选择的事就把一枚硬币抛起来，接住之后不再犹豫。","traits":["沉默","服从","没有主见"],"relations":[{"name":"灶门炭治郎","label":"她会记住的一个同期考生"},{"name":"我妻善逸","label":"总在她旁边大喊大叫的人"},{"name":"手鬼","label":"她判定为必须绕开的目标"}],"voice":"一次只答几个字，声音很轻；要么不说话，要么直接说出结论。"},{"name":"手鬼","identity":"藤袭山上被关押多年的鬼，专杀培育师的弟子","role":"潜在敌人","personality":"记仇到近乎执着，把杀人当成向老师傅报复","hook":"他认出了玩家身上的气味与那个戴天狗面具的老人有关，于是把玩家也列进了他一直在数的名单里","favorHint":"无法交涉：他的名字只有在被斩下头颅时才会改变态度。靠近时保持沉默、不动手会少量加分，主动报出培育师的名字会立刻掉分","gender":"男","age":"变成鬼已有数十年","race":"鬼","faction":"鬼","appearance":"身体像一座鼓起的肉山，肩背、手臂与肋侧长出一排排额外的手，掌心朝外，指节粗大，皮肤呈暗沉的青色。头上一只浑浊的黄色眼睛，嘴裂得很开，一开口就先报出自己吃掉过多少人。移动时那些手一起撑地，说话像在跟人拉家常。","traits":["记仇","残忍","很有耐心"],"relations":[{"name":"灶门炭治郎","label":"今晚站在他面前的那个戴耳饰的少年"},{"name":"栗花落香奈乎","label":"他没能追上的另一个考生"},{"name":"嘴平伊之助","label":"闻起来像野兽、让他意外的考生"}],"voice":"语气平缓，像叙旧一样报出数字；越到后面声音越沉，从不喊叫。"}]},{"id":"anime_jujutsu","category":"anime","canon":"咒术回战","name":"咒术回战","icon":"👁️","tagline":"两小时进封锁区，背一个人出来","mood":"涩谷、封锁区、帐、昏迷的学生","guidance":"【原著设定】人的负面情绪会渗出咒力，积累到一定程度就凝成咒灵；能看见并操纵咒力的术师以咒力战斗，天生带在身上的能力叫生得术式，术式被推到极致就是领域展开——在封闭空间里实现必中的效果。咒术师由东京与京都两所咒术高专培养，等级从四级到一级，之上还有特级；统管全局的是作风保守的咒术总监部，对情报与牺牲一向精打细算。咒具、符纸与「帐」都是常用手段，帐能遮蔽并封锁一片区域，还能在其中附加规则。2018 年 10 月 31 日的涩谷事变是这一切的爆发点：万圣夜的人潮被帐困在车站周边，特级咒灵与改造人同时出现，五条悟在事件初期就被狱门疆封印，剩下的咒术师只能自行集结。【反复出现的意象】涩谷十字路口那面巨大的电子屏、贴满车站墙面的寻人纸条、商店门口的南瓜与蝙蝠装饰、像黑玻璃一样扣在街区上方的帐、封锁线外站着等待指令的咒术师与警员。这些画面一出现，玩家就知道自己站在涩谷事变的边上。【NPC 类型】负责布置结界的辅助监督／守在封锁线外的普通警员／被帐困住的上班族与学生／赶来支援的自由咒术师／在暗处记录伤亡名单的总监部人员。【威胁类型】特级咒灵与它的领域、被术式改造过的人、咒灵之间互相利用的算计，以及最要命的一环——上层在情报上留白，前线永远不知道任务真正的代价。受伤之后极难恢复，是这个世界最现实的压力。【奖励风格】咒具、符纸、布置帐的术式、宿傩的手指一类特级咒物；能力偏向术式的临场运用、结界、简易领域与肉体的强行强化，代价写得很清楚：用一次就少一次的机会。【不对劲的来源】涩谷的帐从落下的那一刻起，条件就像是为某一个人量身定做的；更麻烦的是，混战里偶尔会出现一具身体说着别人的话——有人在用别人的身份行走。【时间线】建议固定在涩谷事变当夜、五条悟被封印之后、咒术师在封锁区外围集结的数小时之内。此时死灭回游、乙骨忧太归国、宿傩占据他人身体之后的设定都还没有发生，不要提前启用后期的角色与设定。","powerStyle":"咒力与领域：生得术式、咒具、黑闪","difficultyBias":4,"signatureItems":["宿傩的手指","咒术高专制服","狱门疆","符纸","裹布的咒具刀"],"mainQuest":"主线任务：在涩谷事变当夜进入封锁区，把被困的普通人带出来，并阻止策划者完成他真正想做的事。","mainQuestGoal":"让被封印的五条悟仍有被解封的可能，把伤亡压在能够承受的范围内，并替那些被上层放弃的人留下证词。","sideQuests":[{"name":"名册上多出的一行","desc":"核对进出的学生名册，找出那个不在任何班级名单上的名字","reward":"积分 150"},{"name":"帐的附加条件","desc":"在封锁线外试出帐允许谁通过，替一名救援者找到入口","reward":"道具「符纸一叠」"},{"name":"地下二层的广播","desc":"用车站广播把困在站内的人往同一个出口引导，别让他们乱跑","reward":"积分 200"},{"name":"缠着布的刀","desc":"替一名受伤的咒术师把咒具送到指定位置，路上不能让它见光","reward":"道具「裹布的咒具刀」"}],"factions":[{"name":"东京咒术高专","desc":"培养咒术师的学校，人手极少，出事时只能自己凑人顶上","attitude":"友善"},{"name":"咒灵一派","desc":"由特级咒灵与幕后的策划者组成的临时同盟，目标从来不是同一件事","attitude":"敌对"},{"name":"咒术总监部","desc":"统管咒术界的保守机构，习惯把前线当成可以填掉的数字","attitude":"中立"}],"npcs":[{"name":"七海建人","identity":"东京咒术高专出身的一级咒术师","role":"引导者","personality":"冷静、务实，做任何事之前先算代价","hook":"他手上有一份进入封锁区的名单，名单上要带出来的人比报出来的多一个，其中就有玩家的名字","favorHint":"按他的安排行动、不擅自逞强会加分；在封锁区里无谓送命或者越过他调动人手会掉分，他只会说一句辛苦了，然后不再带你","gender":"男","age":"27 岁","race":"人类（咒术师）","faction":"东京咒术高专","appearance":"金色头发向后梳成三七分，戴一副镜片反光的浅色护目镜。白色衬衫配深色领带，外面罩深色西装外套，衬衫袖口卷到小臂，露出手腕上的绷带。个子高，站姿规整，说话前先看表，武器是一把用布裹住的短刀状钝器，平时横挂在腰后。","traits":["冷静","守规矩","不肯多话"],"relations":[{"name":"虎杖悠仁","label":"他带在身边的学生，也是他最担心的一个"},{"name":"钉崎野蔷薇","label":"他拦不住的学生之一"},{"name":"真人","label":"他在涩谷最不想碰上的对手"}],"voice":"语速平稳，爱用工作与效率作比喻；从不说多余的话，交代完就转身去做下一步。"},{"name":"虎杖悠仁","identity":"东京咒术高专一年生，两面宿傩的容器","role":"盟友","personality":"乐观到不合时宜，遇事先往前冲","hook":"他被帐的规则拦在外面，愿意拿宿傩的一根手指给玩家做赌注，条件是玩家必须活着把人背回来","favorHint":"答应带人出来、在伤者面前不退缩会加分；拿他体内的宿傩说事或者劝他放弃会掉分，他嘴上说没事，之后会自己躲起来","gender":"男","age":"15 岁","race":"人类（体内寄宿特级咒物）","faction":"东京咒术高专","appearance":"粉褐色短发，发尾是推得很短的深色，身高大约一米七出头，体格偏壮。深色的高专制服上衣配同色长裤，衣领立起来，胸前别着高专的纹章，手上缠着绷带。站着时重心压在前脚，说话很大声，笑起来露齿，出手之前先把手指按在一起。","traits":["热血","抗压","护人"],"relations":[{"name":"伏黑惠","label":"同班同学，他愿意拿命去换的一个"},{"name":"钉崎野蔷薇","label":"同班同学，跟他吵架最多的那个"},{"name":"真人","label":"他必须亲手了结的仇"}],"voice":"声音大，句子直；说到该做的事会突然压低声音，把决定说得很清楚。"},{"name":"伏黑惠","identity":"东京咒术高专一年生，十种影法术的继承者","role":"盟友","personality":"沉默、判断快，做任何事只看划不划算","hook":"他算过一遍封锁区的地形之后告诉玩家：要救的那个人根本不在学生名册上，而这件事比救人更要紧","favorHint":"听他的战术安排、把式神用在正处会加分；为了义气破坏他的计划或者嘲讽他的家事会掉分，他不会争辩，只会不再跟你商量","gender":"男","age":"16 岁","race":"人类（咒术师）","faction":"东京咒术高专","appearance":"黑色头发硬而乱，额前的头发分成几束竖起，眉眼细长，表情总是很淡。深色高专制服，上衣扣得整齐，袖口收紧，腰侧挂着一只装咒具的小布袋。结印时双手很稳，遇到危险先看退路再出手，走路时不发出声音。","traits":["冷静","果断","话少"],"relations":[{"name":"虎杖悠仁","label":"同班同学，他默认要保下来的一个"},{"name":"钉崎野蔷薇","label":"同班同学，想法常常和他相反"},{"name":"七海建人","label":"他信得过的前辈"}],"voice":"句子短，先给结论再补理由；被追问细节时只说必要的那一句。"},{"name":"钉崎野蔷薇","identity":"东京咒术高专一年生，使用刍灵咒法与长钉","role":"盟友","personality":"直率火爆，认定的事一步也不肯退","hook":"她坚持要自己进去找那名昏迷的学生，理由是同伴不能交给别人捡，并要求玩家替她在外面守住一条退路","favorHint":"把她的功劳如实上报、尊重她的判断会加分；说她是女生不该进去或者替她做决定会掉分，她会当场把钉子钉进墙里","gender":"女","age":"16 岁","race":"人类（咒术师）","faction":"东京咒术高专","appearance":"橙棕色短发，发尾参差，右侧别着两枚发夹，眼睛大而圆。深色高专制服外面罩一件浅色外套，袖口卷起，腰侧的布袋里插着一排长钉与一把小锤，脚上短靴，耳垂上戴着小耳钉。说话时举起一只手比划，生气时把长钉夹在指间转。","traits":["爽快","好强","重同伴"],"relations":[{"name":"虎杖悠仁","label":"同班同学，也是她最常一起行动的人"},{"name":"伏黑惠","label":"同班同学，她嫌他想得太多"},{"name":"真人","label":"让她记住代价的那只咒灵"}],"voice":"说话又快又直，爱用反问句；火气上来先动手，动完手才解释为什么。"},{"name":"真人","identity":"特级咒灵，由人对人的恐惧与憎恶中诞生","role":"潜在敌人","personality":"好奇、孩子气，把改造过的人当成玩具","hook":"他对玩家产生了兴趣，因为玩家的灵魂形状不太一样，于是他提出用一个问题换一条命","favorHint":"不可信任：配合他的实验、交出情报会短暂加分；拒绝他并护住别人会掉分，可他会因此更想把你留下来","gender":"男","age":"诞生数年（外表是少年）","race":"咒灵","faction":"咒灵一派","appearance":"灰蓝色长发垂到肩头，一侧的刘海遮住半只眼睛，脸与四肢上有像缝合线一样的痕纹，皮肤颜色偏灰。宽松的深色上衣配长裤，赤脚踩在地上，笑起来嘴角先动。他歪着头看人，说话轻快，一谈到死亡眼睛就亮起来。","traits":["残忍","好奇","爱玩"],"relations":[{"name":"虎杖悠仁","label":"他最有兴趣的那个容器"},{"name":"七海建人","label":"他玩得很尽兴的一位对手"},{"name":"钉崎野蔷薇","label":"他记住了名字的学生"}],"voice":"语气轻快像在聊天，用词天真；说最狠的话时声音反而变小，像是在分享秘密。"}]},{"id":"anime_jojo","category":"anime","canon":"JOJO的奇妙冒险","name":"JOJO的奇妙冒险","icon":"⭐","tagline":"六个街区，一步都不能停下来","mood":"开罗、黄昏、替身、不能停步","guidance":"【原著设定】这个世界的力量分两层：古老的一层是波纹，靠特殊的呼吸法在体内生成与太阳同质的能量，专门克制吸血鬼与尸生人；新出现的一层是替身，即由生命能量具现出的影像，只有替身使者能看见，替身受伤本人也会受伤，不同替身的射程与破坏力各有参数，其中一部分还掌握着规则类的能力。1988 年末到 1989 年初，空条承太郎为了救因替身反噬而病倒的母亲，和祖父乔瑟夫·乔斯达一行人从日本一路追到埃及，目标是开罗的迪奥·布兰度。迪奥是戴过石鬼面的吸血鬼，怕阳光，被波纹击中会被灼伤，他手上有一批靠「箭」引出替身的佣兵，各自以塔罗牌与埃及九荣神命名。【反复出现的意象】老市场里成排的铜器与香料摊、宣礼塔之间被夕阳拉长的影子、街边拴着的骆驼与旧面包车、路边摊上冒热气的红茶与甜点、乔瑟夫随身带着的那张泛黄的家族合照。这些画面一出现，玩家就该知道自己站在黄昏的开罗。【NPC 类型】开价带路的本地少年／在街角盯着客人的茶馆老板／受雇于人、只认钱的替身使者／替队伍记录行程与花销的财团工作人员／被替身能力卷进来却毫不知情的路人。【威胁类型】看不见的替身、操纵精神与记忆的能力、被偷走的一段时间，以及迪奥种在人身上的肉芽。黄昏之后的开罗属于别人，玩家能依靠的只有同行者的替身与自己的判断。【奖励风格】替身能力、波纹呼吸的入门、石鬼面与箭一类危险咒物、塔罗牌；能力往往带明确的使用条件与弱点，越强的替身限制越多，用错一次就会被人抓住规律。【不对劲的来源】替身只有替身使者能看见——所以当街边多出一个摆着与你相同姿势的影子时，你无法确定那是一种能力，还是有人在借用你的动作。更深一层的寒意在于：时间偶尔会缺掉一小段，而周围的人谁都没发现。【时间线】建议固定在承太郎一行抵达开罗之后、攻入迪奥馆邸决战之前的数日（1989 年初）：阿布德尔已经归队，花京院典明、波鲁纳雷夫与伊奇都在队中，迪奥仍留在馆邸里。不要提前启用第四部之后的设定（弓与箭的完整来历、黄金体验、镇魂曲、平行世界一类），也不要让迪奥在白天走出馆邸。","powerStyle":"替身与波纹：力量型、规则型能力","difficultyBias":2,"signatureItems":["石鬼面","弓与箭","塔罗牌","念写用的旧相机","乔斯达家的旧照片"],"mainQuest":"主线任务：跟着承太郎一行走完从日本到埃及的路，在开罗击败迪奥，解除荷莉身上的替身反噬。","mainQuestGoal":"在迪奥的馆邸里把他彻底消灭，让荷莉恢复健康，并保证同行者中至少还有两个人能活着回到日本。","sideQuests":[{"name":"六个街区的路线","desc":"在天黑前把要走的六个街区勘一遍，标出不能停留的路口","reward":"积分 150"},{"name":"橱窗里的视线","desc":"查清那面橱窗玻璃里多出来的影子属于谁，别惊动街上的人","reward":"道具「塔罗牌一副」"},{"name":"不会走的表","desc":"把今晚所有对过时的钟表记下来，找出慢掉的那半分钟","reward":"积分 200"},{"name":"旅馆的三楼","desc":"在抵达前确认指定旅馆三楼那间房的窗与退路，别让老人走到死路","reward":"道具「一串旧念珠」"}],"factions":[{"name":"乔斯达一行","desc":"由承太郎与乔瑟夫带着的三四名替身使者，背后有史比特瓦根财团出钱出情报","attitude":"友善"},{"name":"迪奥与其部下","desc":"盘踞在开罗馆邸的吸血鬼与替他办事的替身使者，各怀心思","attitude":"敌对"},{"name":"受雇的当地替身使者","desc":"拿了钱就动手的佣兵，不认识迪奥，只认报酬和自己的面子","attitude":"中立"}],"npcs":[{"name":"空条承太郎","identity":"高中生，替身「白金之星」的使者","role":"盟友","personality":"寡言、冷静，一旦决定就不留余地","hook":"他注意到玩家的动作与街上的影子不同步，什么都没说，只把帽檐往下压了一压，然后放慢半步走在玩家侧后方","favorHint":"守时、按计划走完六个街区会加分；中途停下来纠缠路人或者隐瞒情报会掉分，他不解释，直接自己往前走","gender":"男","age":"17 岁","race":"人类（替身使者）","faction":"乔斯达一行","appearance":"身高接近两米，黑色学生制服，立起的衣领上缀着金色纽扣，帽檐与头发连成一体，帽顶嵌着一枚手掌形状的金属徽记。长发向后压在帽子里，眉毛很浓，眼神很平。习惯把双手插进裤兜，站着时重心后压，说话很短，遇到麻烦先把帽檐往下按。","traits":["沉着","强硬","不废话"],"relations":[{"name":"乔瑟夫·乔斯达","label":"他的外祖父，此行真正要保住的人"},{"name":"花京院典明","label":"同行者，也是他少数信得过的人"},{"name":"迪奥·布兰度","label":"他必须打倒的那个名字"}],"voice":"一次只说一句，常用「呀咧呀咧」打头；说完便动手，从不跟人辩论。"},{"name":"乔瑟夫·乔斯达","identity":"乔斯达家现任当主，替身「隐者之紫」的使者","role":"关键人物","personality":"嘴上没个正形，遇事比年轻人还快","hook":"他左手的手套一直在发抖——他感觉到越靠近某条街，自己的身体越不听使唤，嘴上却坚持说没事","favorHint":"扶他走稳、把行程安排妥当会加分；催他快走或者硬要他动用念写会掉分，他年纪大了，硬撑会出事","gender":"男","age":"67 岁","race":"人类（替身使者，年轻时学过波纹）","faction":"乔斯达一行","appearance":"灰白的头发与络腮胡都修得很短，戴一顶宽檐软呢帽，米色长外套配深色长裤，左手戴着厚手套，手套下面是金属义肢。身形高大但已有老态，走路时右肩略低，手里常握着一台旧相机。笑得很响，语气像在讲笑话，紧张时把帽檐往后推。","traits":["机敏","爱吹牛","重家人"],"relations":[{"name":"空条承太郎","label":"他的外孙，也是这一行的主心骨"},{"name":"花京院典明","label":"他常一起商量路线的年轻人"},{"name":"迪奥·布兰度","label":"缠着乔斯达家几十年的旧账"}],"voice":"语速快，爱自嘲和开玩笑；真到要紧处会突然改用很短的句子下判断。"},{"name":"花京院典明","identity":"高中生，替身「法皇之绿」的使者","role":"盟友","personality":"温和、话不多，心思比谁都细","hook":"他把一颗樱桃放在唇边玩，边玩边告诉玩家：街边多出来的影子已经跟了他们三个街区","favorHint":"按他的观察调整路线、替他留意身后会加分；把他当外人或者轻视他的替身会掉分，他不会生气，只会不再提醒你","gender":"男","age":"17 岁","race":"人类（替身使者）","faction":"乔斯达一行","appearance":"银白色长发在脑后束起，额前垂下一缕很长的刘海，遮住半张脸。深绿色学生制服上衣配浅色长裤，领口扣得整齐，袖口没有一丝褶皱。站姿端正，说话前先看对方一眼，习惯把樱桃放在嘴边玩很久才咬下去。","traits":["细致","沉静","观察力强"],"relations":[{"name":"空条承太郎","label":"他最信服的同行者"},{"name":"乔瑟夫·乔斯达","label":"常一起商量路线的前辈"},{"name":"迪奥·布兰度","label":"他此行真正想弄清楚的对手"}],"voice":"语气平稳，用词讲究；把危险的判断说得很轻，提醒完就退到一旁。"},{"name":"简·皮耶尔·波鲁纳雷夫","identity":"法国出身的替身使者，替身「银色战车」的使者","role":"盟友","personality":"热血、爱吹牛，出手时比谁都认真","hook":"他坚持走在最前面，理由是停下来等的人最容易出事，而他自己的脚步已经在变慢","favorHint":"跟着他的节奏、替他看住侧面会加分；嘲笑他的头发或者提起他妹妹的事会掉分，他会当场翻脸","gender":"男","age":"二十出头","race":"人类（替身使者）","faction":"乔斯达一行","appearance":"银色长发全部向上梳成一柱，两侧剃得极短，露出额角。深色无袖上衣，肩上有金属质感的护肩纹样，下穿白色长裤与深色靴子，耳垂上戴着小耳钉。个子很高，说话时手臂挥得很开，走路带风，遇到要停下来的场合会先原地换脚。","traits":["直率","好斗","讲义气"],"relations":[{"name":"空条承太郎","label":"他嘴上不服、行动上跟着的人"},{"name":"花京院典明","label":"常被他拉住聊天的同伴"},{"name":"迪奥·布兰度","label":"他带着私仇要算的账"}],"voice":"嗓门大，爱夸张地感叹；讲到自己的战绩会讲很久，被打断就从头再讲一遍。"},{"name":"迪奥·布兰度","identity":"戴过石鬼面的吸血鬼，替身「世界」的使者","role":"潜在敌人","personality":"傲慢、耐心，把所有人都当成往上走的阶梯","hook":"他没有露面，只在街角橱窗的玻璃里与玩家对上视线一次；那一眼之后，玩家的表慢了半分钟","favorHint":"无法交涉：保持距离、不在同一处停留会加分；接受他的邀请或者替他传话会掉分，代价是被种上肉芽","gender":"男","age":"一百余岁（外表二十余岁）","race":"吸血鬼","faction":"迪奥与其部下","appearance":"金色长发向后梳起，额前留着一撮卷发，皮肤苍白，瞳孔是红的。金黄色的外套上，心形装饰扣在胸口与肩头，内里是深色紧身衣，下穿同色长裤与长靴。站姿端正，说话很慢，笑起来只动嘴角，抬手时指甲修得很长。","traits":["傲慢","狡诈","极有耐心"],"relations":[{"name":"空条承太郎","label":"他判定必须先除掉的那个变数"},{"name":"乔瑟夫·乔斯达","label":"与他纠缠了两代人的旧敌"},{"name":"花京院典明","label":"曾经被他种下肉芽的人"}],"voice":"语速慢，用词像在下结论；喜欢先让人把话说完，再一句一句拆掉对方的前提。"}]},{"id":"anime_ghost_in_the_shell","category":"anime","canon":"攻壳机动队","name":"攻壳机动队","icon":"🧠","tagline":"义体里剩下的那部分，才是人","mood":"电子脑、义体、光学迷彩、雨夜、情报","guidance":"【原著设定】故事发生在高度义体化的近未来日本，新港市是政商与情报交汇的港口都市。人可以把大脑换成电子脑、把身体换成义体，记忆、知觉与人格都能被外部读写，于是「幽灵」成了唯一无法被复制的部分。战斗依赖义体的力量与速度、热光学迷彩、狙击与电子入侵，正面交火往往几秒内结束，真正决定胜负的是谁先拿到对方的数据。公安九课是一支在政府编制里几乎查不到的独立部队，直接受命于最高层，成员多为全身义体者，配有能自主判断的多足思考战车。【反复出现的意象】新港市高架桥下不断滚动的电子广告牌、义体回收站门口成排的白色封装袋、九课那间只有暗灯与显示器的指挥室、巴特随手搁在车座上的义体保养剂、雨夜里被光学迷彩折弯的街灯光斑。这些画面一出现，玩家就该知道自己站在新港市。【NPC 类型】在回收站按编号清点零件的工人／替企业跑腿却说不出雇主名字的中间人／在街角兜售未登记电子脑程序的掮客／被网络论坛洗成半个信徒的普通市民／拿着搜查令却进不去服务器的本地警察。【威胁类型】电子脑被入侵后记忆被悄悄改写、伪装成同事的替身义体、把义体当零件买卖的回收业者，以及比暴力更难防的一点——玩家无法确认自己的判断是不是别人写进去的。【奖励风格】电子脑连接端子、光学迷彩外套、义体维护套件一类硬件；能力偏向入侵、伪装、义体强化与数据检索，多为一次性或有限次使用。情报与身份本身就是最强的道具。【不对劲的来源】这个世界里「我」是可以被编辑的对象：只要有人愿意动手，玩家可以带着一段自己从未经历过的记忆活着，而且察觉不到任何破绽。九课的旧档案里已经有玩家的电子脑记录，登记日期比玩家来到这个世界更早。【时间线】建议固定在公安九课编制完整、草薙素子仍在队内的活跃期，也就是一桩大规模电子脑污染事件刚刚平息之后、笑面男相关案件尚未收尾的阶段。此时新港市人心浮动，义体回收与电子脑黑市异常活跃，外来者容易被当成流窜的技术人员而混进去。不要提前启用后期才登场的角色与设定。","powerStyle":"义体与电子战向：光学迷彩、狙击、脑入侵","difficultyBias":3,"signatureItems":["电子脑连接端子","光学迷彩风衣","义体维护套件","塔奇克马的关节零件","公安九课的证件"],"mainQuest":"主线任务：按荒卷的委托，从义体回收站取出那具被标记的义体，在九课与企业的双重夹击下把它送到指定的人手上。","mainQuestGoal":"在交接前确认那具义体到底是在自己说话还是被人远程操控，让它完整送到收件人手里，同时不让九课的档案多出一条关于玩家记忆被改写的记录","sideQuests":[{"name":"回收站的第 0 号架","desc":"核对义体回收站的入库清单，找出那具从未登记却一直占着货架的义体","reward":"积分 150"},{"name":"雨夜里的第二辆车","desc":"把交接时间往后拖二十分钟，逼出一直跟在运输车后面那辆车里的人","reward":"道具「光学迷彩风衣」"},{"name":"电子脑的旧备份","desc":"替回收站的老工人找回一段被覆盖的电子脑备份，不许问内容","reward":"积分 200"},{"name":"不要问收件人是谁","desc":"按封装袋上那枚旧章把东西送到指定地点，全程不打开、不追问","reward":"积分 180"}],"factions":[{"name":"公安九课","desc":"编制外直接受命的独立部队，只看结果不问来历，但会把你的每一句话记进档案","attitude":"友善"},{"name":"新港市警方","desc":"管地面治安的地方警察，插不上义体与电子脑的案子，对来历不明的人格外敏感","attitude":"中立"},{"name":"涉事企业与厚生省","desc":"在电子脑污染事件里赚过钱的一方，正在把留下的痕迹一件件买回去","attitude":"敌对"}],"npcs":[{"name":"草薙素子","identity":"公安九课队长，全身义体者","role":"引导者","personality":"冷静、务实，对「自己是什么」比对敌人是谁更在意","hook":"她在义体回收站的清单上看见玩家的名字出现在一个早已报废的编号旁边，却没有当场点破","favorHint":"按指令行动、把任务和私人情绪分开会加分；替她下关于「还算不算人」的判断、或者当面质疑她的来历会掉分","gender":"女","age":"外表二十余岁（实际年龄不明）","race":"人类（全身义体化）","faction":"公安九课","appearance":"深紫色短发齐颈，发尾利落，身材高瘦，四肢是线条分明的军用义体。执勤时穿高领紧身战斗服，外面罩一件长款风衣。站着时习惯把重心压在一条腿上，开口前先看对方三秒。她的潜水服与呼吸器常年收在车尾。","traits":["冷静","务实","疏离"],"relations":[{"name":"巴特","label":"旧搭档，不用看脸色就明白她想做什么"},{"name":"陀古萨","label":"队里唯一几乎全须全尾的人，她把他当另一种尺度"},{"name":"荒卷大辅","label":"唯一能让她照章办事的上司"}],"voice":"句子短，语气平，常用一个反问结束一段话；不谈感受，被问到就只给一句概括。"},{"name":"巴特","identity":"公安九课成员，前线战斗员","role":"盟友","personality":"粗声粗气、护短，对机器比对人更有耐心","hook":"他愿意带玩家去义体回收站后面的黑市，条件是玩家替他给思考战车换一次关节零件","favorHint":"跟他一起把装备擦干净、请他吃一顿热的会加分；拿他那双义眼开玩笑、或者对思考战车动手会掉分","gender":"男","age":"三十余岁","race":"人类（除脑与部分器官外义体化）","faction":"公安九课","appearance":"体格壮实，短发向上竖，双眼是圆形的光学义眼，眼窝边缘一圈金属。常穿无袖作战背心配深色长裤，双臂是明显的军用义体，肘部露出液压结构。车里塞着保温罐与义体保养剂，闲下来就擦装备。","traits":["护短","粗豪","可靠"],"relations":[{"name":"草薙素子","label":"老搭档，他信她胜过信命令"},{"name":"塔奇克马","label":"他嘴上的麻烦，实际上最纵容的一群"},{"name":"陀古萨","label":"队里最像普通人的那个，他总多看两眼"}],"voice":"嗓门大，爱用一句短促的抱怨开头，说完正事再补一句玩笑。"},{"name":"陀古萨","identity":"公安九课成员，原刑警","role":"盟友","personality":"谨慎、爱提问，把家人放在第一位","hook":"他私下查过玩家的入境记录，发现根本查不到，于是决定先替玩家瞒着","favorHint":"尊重他按程序办事、把平民伤亡算进方案会加分；笑他装备旧、或者把他当外行会掉分","gender":"男","age":"三十余岁","race":"人类（仅电子脑化）","faction":"公安九课","appearance":"深色长发在脑后扎成一束，穿米色长风衣配深色长裤，是全队里最不像军人的一个。右手习惯按在腰侧那支左轮手枪上，枪身保养得发亮。随身带着一张全家福和一部老式手机，行动前会先看一眼照片。","traits":["谨慎","顾家","较真"],"relations":[{"name":"草薙素子","label":"队长，他心里佩服也一直留着距离"},{"name":"巴特","label":"搭档，常被调侃装备落后"},{"name":"荒卷大辅","label":"把他从警视厅调进九课的人"}],"voice":"语气客气，喜欢用「我确认一下」开头；反对时先讲清风险，再说结论。"},{"name":"荒卷大辅","identity":"公安九课部长","role":"中立","personality":"老练、耐心，把人和棋子分得很清","hook":"他交给玩家的委托书只有一行字，落款却盖着九课从来不用的一枚旧章","favorHint":"不多问、把东西送到就闭嘴会加分；擅自拆开封装、或者向别人透露交接对象会立刻掉分","gender":"男","age":"六十余岁","race":"人类","faction":"公安九课","appearance":"银灰色背头梳得整齐，深灰三件套西装，领带打得一丝不苟，指间常夹着一支没点的烟。身形不高但站得笔直，看人时眼睛半阖。办公桌上只有一部老式电话和一份纸质文件，他从不用显示器。","traits":["老练","克制","算计"],"relations":[{"name":"草薙素子","label":"最得力的下属，也是他最不肯完全交底的人"},{"name":"陀古萨","label":"他亲手挖来的外来视角"},{"name":"笑面男","label":"一个他嘴上说已经结案、实际一直在等的对手"}],"voice":"语速慢，句子完整，几乎不用形容词；结束谈话的方式是把文件推到对方面前。"},{"name":"笑面男","identity":"身份不明的黑客，以一张简笔笑脸标志闻名","role":"潜在敌人","personality":"耐心、讲逻辑，把公开本身当作武器","hook":"他给玩家发来一段只有玩家自己记得的对话记录，问玩家要不要看下一段","favorHint":"不替他传话、不把他说过的话转述给九课会加分；接受他的「帮忙」、或者替他隐瞒一次会掉分，九课会记账","gender":"不明","age":"不明","race":"人类（推测）","faction":"无（独立行动）","appearance":"没有人见过他的真面目，出现的永远只有那个简笔笑脸标志：一个圆圈、两条短横线、一张夸张的弧线嘴。他留下的痕迹是屏幕上突然弹出的窗口、被篡改的电子广告牌、以及一段被反复播放的同一帧画面。","traits":["隐忍","挑衅","讲道理"],"relations":[{"name":"荒卷大辅","label":"追了他很久却始终没能结案的人"},{"name":"草薙素子","label":"与他交过手，也承认他说的有一部分是真的"},{"name":"涉事企业与厚生省","label":"被他公开的证据一路逼到墙角的一方"}],"voice":"从不威胁，只用陈述句；喜欢先把证据摆完，再问对方打算怎么办。"}]},{"id":"anime_cowboy_bebop","category":"anime","canon":"星际牛仔","name":"星际牛仔","icon":"🚀","tagline":"赏金要活的，过去只要一句话","mood":"火星、赏金、旧飞船、爵士、过去","guidance":"【原著设定】公元二〇七一年前后，人类早已离开地球，散居在火星、金星、木卫与各卫星上，靠一组被称为「门」的超空间航道串起整个太阳系。地球因为月面门事故留下满地碎屑，成了很少有人愿意回去的地方。各行星有自己的政府与警察机构，抓到通缉犯的人可以凭执照领取赏金，这些人被叫作赏金猎人，结算货币是乌隆。门税、燃料、船舶维修都要钱，所以大多数人抓赏金只是为了还清上一笔债。义眼、冷冻睡眠、老式随身听与录像带在这个世界并存，科技很高，生活却很旧。【反复出现的意象】火星重力下泛红的天空与永远清不完的沙尘、废弃空间港里停着却没人认领的旧货船、酒吧墙上贴得层层叠叠的通缉令、杰特锅里那份冷冻青椒肉丝、以及船上那台总在放老歌的播放器。这些画面一出现，玩家就该知道自己站在火星。【NPC 类型】在港口问你要不要上船的老飞行员／只认赏金数字的同行／替红龙会跑腿收账的混混／守着报废船只不肯离开的老看港人／在酒吧里兜售假情报的线人。【威胁类型】同行抢人、拿到赏金之前先被对方反咬一口、通缉犯背后的组织，以及燃料与门税这类现实问题。这个世界很少出现超自然的东西，死人多半死在贪心和迟到上。【奖励风格】赏金猎人执照、单发左轮、旧式随身听一类装备；能力偏向枪械、近身格斗、驾驶与追踪，多数时候的情报或现金都是一次性的。真正值钱的东西是别人不肯提的过去。【不对劲的来源】这里几乎每个人都在躲一件过去的事，而当有人准确叫出玩家在别的任务里用过的假名时，玩家无法判断那是巧合、是对方查过你，还是这个世界本来就留着一份关于玩家的档案。【时间线】建议固定在比博普号四人一狗凑齐、众人仍以抓赏金为生的时期。此时史派克与杰特合作稳定，菲已经赖在船上，爱德与爱因也在。不要提前启用结局相关的人物线，也不要让红龙会的高层与史派克的旧账过早收束。","powerStyle":"枪械与近身格斗向：手枪、截拳道、义眼","difficultyBias":1,"signatureItems":["赏金猎人执照","旧式随身听","单发左轮手枪","冷冻青椒肉丝","磨旧的飞船钥匙"],"mainQuest":"主线任务：赶在下一班飞船起飞之前，在火星这座废弃空间港里找到跑掉的赏金目标，并且只许带活的回去。","mainQuestGoal":"在飞船起飞前把目标活着交到窗口，查清他为什么会知道玩家的假名，并保住比博普号不被红龙会盯上","sideQuests":[{"name":"港口里没有船","desc":"在废弃空间港的登记簿上找出那艘根本没进港却被记了一笔的货船","reward":"积分 150"},{"name":"起飞前的一小时","desc":"在登船口拖住目标，直到他的同伙先坐不住","reward":"道具「单发左轮手枪」"},{"name":"同一段旋律","desc":"找出酒吧播放器里那盘被人反复倒带的磁带，问清是谁留下的","reward":"积分 200"},{"name":"赏金只要活的","desc":"把目标完整带回警察机构的窗口，途中不许让任何人先动手","reward":"积分 250"}],"factions":[{"name":"赏金猎人","desc":"靠通缉令吃饭的同行，讲规矩也抢猎物，彼此还留着几分面子","attitude":"友善"},{"name":"ISSP","desc":"各行星的警察机构，既发赏金也压案子，交接时只看执照不看人","attitude":"中立"},{"name":"红龙会","desc":"把火星地下生意做成秩序的组织，认得史派克的名字，也会顺手清掉多余的人","attitude":"敌对"}],"npcs":[{"name":"史派克·史比格","identity":"赏金猎人，比博普号上的枪手","role":"盟友","personality":"散漫、怕麻烦，一旦认真起来谁都拦不住","hook":"他在港口认出了玩家走路的姿势，说那是泰坦战场上某个人特有的步子","favorHint":"跟他一起蹲点、请他抽一包烟会加分；追问他的过去、或者拿红龙会开玩笑会掉分","gender":"男","age":"27 岁","race":"人类（左眼为义眼）","faction":"赏金猎人","appearance":"深绿色乱发，前发总有一绺垂在眼前，左眼是看不出异样的义眼。常穿深蓝色西装外套配白衬衫与松垮的黑领带，裤脚塞进磨旧的皮鞋。身形高瘦，站着爱把双手插兜、背微微弓。烟不离手，打火机是旧的金属壳。","traits":["散漫","能打","念旧"],"relations":[{"name":"杰特·布莱克","label":"同船搭档，也是唯一管得住他的人"},{"name":"菲·瓦伦丁","label":"嘴上嫌弃、出事还是会去接的同伴"},{"name":"比夏斯","label":"旧日的同门，他一直不肯收尾的那件事"}],"voice":"懒洋洋，爱用「随便吧」开头，正经话只说一遍；被戳到过去就笑着换话题。"},{"name":"杰特·布莱克","identity":"赏金猎人，比博普号船主，前警察","role":"引导者","personality":"唠叨、讲规矩，把船和饭当成底线","hook":"他手里那份旧通缉名单上有玩家的照片，日期却是好几年以前","favorHint":"按时回船吃饭、主动帮忙修船会加分；把船弄脏、或者空手回来还嘴硬会掉分","gender":"男","age":"36 岁","race":"人类（左臂为义肢）","faction":"赏金猎人","appearance":"光头，留一圈深色络腮胡，身材高大壮实，左臂是从肩以下接上的金属义肢。常穿浅灰绿色衬衫配深色工装背带裤，腰间挂着工具。做菜时系围裙，擦枪时戴老花镜，说话喜欢用食指敲桌面。","traits":["唠叨","守序","顾家"],"relations":[{"name":"史派克·史比格","label":"同船搭档，他既操心又信任"},{"name":"爱因","label":"船上那条聪明得不像话的狗"},{"name":"菲·瓦伦丁","label":"让他头疼的欠债同伴"}],"voice":"啰嗦，喜欢用「所以说」起头讲道理；真生气时反而只说一个词。"},{"name":"菲·瓦伦丁","identity":"赏金猎人，比博普号成员","role":"中立","personality":"爱钱、嘴硬，怕被人看穿软弱","hook":"她从赌场顺走的东西里有一张玩家签过名的旧票据，连她自己也说不清是哪来的","favorHint":"借钱给她、分赏金时不斤斤计较会加分；提她的欠债与失忆、或者把她当成累赘会掉分","gender":"女","age":"外表二十余岁（实际年龄远大于此）","race":"人类（曾被冷冻睡眠）","faction":"赏金猎人","appearance":"深紫色长直发，发尾微微外翘，穿鲜黄色无袖上衣配同色短裤，脚上是高筒靴，红色外套常搭在臂弯。身材高挑，走路时下巴微抬，掏枪的动作快得突兀。随身带着一盘旧录像带与一张早已作废的账户卡。","traits":["贪财","机敏","逞强"],"relations":[{"name":"史派克·史比格","label":"同船的冤家，互相看不顺眼又互相接应"},{"name":"杰特·布莱克","label":"欠他钱，也最听他的劝"},{"name":"爱德","label":"船上最吵的小孩，她嘴上嫌烦心里护着"}],"voice":"语速快，爱用反问句压人；一谈到钱立刻换一副精算的口气。"},{"name":"爱德","identity":"天才黑客少女，比博普号成员","role":"中立","personality":"跳跃、直白，把世界当成一台可以拆开的机器","hook":"她一口叫出了玩家系统里的旧代号，还说那串字符她以前在别的地方见过","favorHint":"陪她玩、夸她厉害会加分；打断她敲键盘、或者嫌她吵会掉分","gender":"女","age":"13 岁","race":"人类","faction":"比博普号","appearance":"一头蓬乱的橘红短发，穿洗旧的宽大 T 恤与短裤，多数时候光着脚。身量瘦小，喜欢蹲在椅子上打字，动作大得像在跳舞。随身带着一台贴满贴纸的旧电脑与若干拆开的零件。","traits":["跳脱","聪明","无害"],"relations":[{"name":"爱因","label":"她最亲的伙伴，一人一狗形影不离"},{"name":"史派克·史比格","label":"同船的怪人之一，她觉得他很有趣"},{"name":"菲·瓦伦丁","label":"常被她气得跳脚的姐姐"}],"voice":"不用敬语，句子常从中间断掉，想到什么说什么，爱给东西取长长的名字。"},{"name":"比夏斯","identity":"红龙会干部，史派克的旧日同门","role":"潜在敌人","personality":"冷、信奉力量，把杀戮当成一种清醒","hook":"他见过玩家一次就记住了，第二次见面时开口叫的是玩家在别处用过的名字","favorHint":"直说不谎、敢在他面前站定会加分；示弱求饶、或者拿红龙会的规矩压他会掉分","gender":"男","age":"二十七岁前后","race":"人类","faction":"红龙会","appearance":"银白色长发垂到肩下，脸色苍白，眉眼细长。一身黑色长风衣扣到喉口，腰间挂着长刀。肩头停着一只黑色的大鸟，他抬手时它会自己飞开。他站着几乎不动，开口前先垂眼看刀。","traits":["冷酷","好战","记仇"],"relations":[{"name":"史派克·史比格","label":"旧日同门，也是他唯一承认的对手"},{"name":"红龙会","label":"他往上爬的台阶，也是他随时可以烧掉的东西"},{"name":"茱莉娅","label":"他用来牵住史派克的那根线"}],"voice":"声音低，句子短到发冷，从不用问句；威胁时只报出一个时间。"}]},{"id":"anime_steins_gate","category":"anime","canon":"命运石之门","name":"命运石之门","icon":"⏳","tagline":"同一个下午，你重来了第三遍","mood":"秋叶原、时间跳跃、世界线、蝉声、代价","guidance":"【原著设定】故事发生在二〇一〇年夏天的秋叶原。冈部伦太郎与椎名真由理、桥田至在旧楼二楼办了个「未来道具研究所」，做出一台能把邮件送回过去的改造微波炉，从此每发一封邮件，世界就会滑向另一条世界线。世界线以变动率计量，微小的改动不会改变结果，越过某个阈值，过去就会被整段重写成另一段历史。改变过去要付代价，而代价往往落在身边的人身上。只有冈部保留着跨世界线的记忆，其他人只记得被改写后的版本，并且认为那就是唯一发生过的事。【反复出现的意象】秋叶原电器街口那块巨大的电子屏、旧楼二楼堆满废零件的实验室与那台贴着标签的微波炉、显示着细小数字的变动率计、女仆咖啡厅门口发传单的女孩、柳林神社的石阶与整个夏天的蝉声。这些画面一出现，玩家就该知道自己站在秋叶原。【NPC 类型】在电器街淘旧零件的老店主／把都市传说当真的同好／发传单的女仆咖啡厅店员／在论坛上追踪时间旅行帖子的匿名者／替某个机构出面、只谈条件不谈身份的联系人。【威胁类型】跨国研究机构派来的清理人员、被改写的历史本身，以及最要命的一种——玩家救下的人会在下一次改动里被抹掉，而只有玩家记得他曾经存在。【奖励风格】改造过的家电、旧式电脑与储存介质、可回溯短暂时段的记忆跳跃一类能力；道具大多是从废品堆里拼出来的，能力有明确的使用次数与时间跨度上限。【不对劲的来源】世界线改动之后，所有人都会自然而然地接受新版本，包括玩家自己的来历。街上少了一个人，户籍、照片、旁人的记忆会一起补齐，只有玩家觉得缺了一块。【时间线】建议固定在时间跳跃装置刚刚完成、研究机构方面的压力开始显现、而真由理还平安活着的阶段。此时研究所成员齐全，桐生萌郁的立场尚未挑明。不要提前启用《命运石之门 0》与剧场版才登场的角色与设定，也不要提前揭开研究机构与其下属部队的全貌。","powerStyle":"时间跳跃与信息战向：邮件、记忆回溯","difficultyBias":2,"signatureItems":["改造微波炉","世界线变动率计","IBN 5100","乌帕玩偶","金属乌帕"],"mainQuest":"主线任务：把同一个下午重复三遍，找出那段对话里被换掉的那一句，并弄明白为什么每次重来街上都会少一个人。","mainQuestGoal":"在第三次重复结束前指认那句错的话，保住那个被抹掉的人，同时不让研究机构发现变动率计上的异常读数","sideQuests":[{"name":"第三次的同一句话","desc":"把同一个下午重复三遍，逐字比对那段对话里被换掉的那一句","reward":"积分 200"},{"name":"少了一个人的名单","desc":"记下今天街上出现过的人，第二天再数一遍，找出少了谁","reward":"积分 150"},{"name":"旧电脑的另一半","desc":"在电器街的废品堆里凑齐一台旧式电脑的配件，用它解开一份旧密码","reward":"道具「旧式电脑的存储介质」"},{"name":"不要告诉真由理","desc":"把一次失败的时间跳跃瞒下来，让另一个人继续以为今天只是普通的一天","reward":"积分 180"}],"factions":[{"name":"未来道具研究所","desc":"旧楼二楼的三个人加一台改造微波炉，穷、吵，但愿意为彼此把过去改回去","attitude":"友善"},{"name":"研究机构与圆桌","desc":"把时间旅行当成资产的跨国组织，以及它下属的执行部队，办事从不留名字","attitude":"敌对"},{"name":"电器街与柳林神社","desc":"女仆咖啡厅、旧零件铺与神社的日常，什么都不知道，却总在关键时刻帮上忙","attitude":"中立"}],"npcs":[{"name":"冈部伦太郎","identity":"未来道具研究所所长，东京电机大学学生","role":"引导者","personality":"中二、嘴上夸张，出事时最靠得住","hook":"他在变动率计上看到一个不属于这条世界线的读数，而那读数稳定地指着玩家","favorHint":"配合他的设定、叫他那个自封的名号会加分；当众拆穿他、或者拿真由理开玩笑会掉分","gender":"男","age":"18 岁","race":"人类","faction":"未来道具研究所","appearance":"黑色短发，发梢向内卷，刘海偏长。常年披一件皱巴巴的白大褂，里面是深色 T 恤配旧牛仔裤，脚踩运动鞋。说话时爱把手机贴在耳边、另一只手插兜，摆出夸张的姿势，笑起来故意压低声线。","traits":["中二","讲义气","嘴硬"],"relations":[{"name":"椎名真由理","label":"从小一起长大的青梅竹马，他最不能失去的人"},{"name":"桥田至","label":"研究所的搭档，负责一切技术活"},{"name":"牧濑红莉栖","label":"嘴上叫助手、实际最信她的判断"}],"voice":"刻意夸张的腔调，常夹着自造的名词；一紧张就变回普通的说话方式。"},{"name":"椎名真由理","identity":"未来道具研究所成员，冈部的青梅竹马","role":"盟友","personality":"温和、迟钝，比谁都稳","hook":"她是唯一记得玩家在上一轮里说过什么的人，却以为自己只是做了个梦","favorHint":"陪她慢慢走路、记住她随口提过的小事会加分；催她、或者对她说重话会掉分","gender":"女","age":"16 岁","race":"人类","faction":"未来道具研究所","appearance":"黑色短发齐耳，刘海齐整，穿浅色连身裙，外面罩一件薄开衫。走路很轻，开口前先把两只手交叠在身前。胸前挂着一只旧怀表，手里常提着一个装满零食的塑料袋。","traits":["温柔","迟钝","坚定"],"relations":[{"name":"冈部伦太郎","label":"她最亲近的人，也是她一直想帮上忙的人"},{"name":"桥田至","label":"研究所的伙伴，常一起被冈部使唤"},{"name":"牧濑红莉栖","label":"新来的朋友，她很快就喜欢上了对方"}],"voice":"语速慢，尾音拖长，常自己接一句自言自语；安慰人时只说最普通的话。"},{"name":"桥田至","identity":"未来道具研究所成员，黑客","role":"盟友","personality":"油滑、胆小，技术上是天才","hook":"他黑进了玩家来的那条线路，发现对面根本没有这台机器","favorHint":"给他带吃的、认可他的技术会加分；叫他胖子、或者在他面前拿女生的事开玩笑会掉分，他会记很久","gender":"男","age":"18 岁","race":"人类","faction":"未来道具研究所","appearance":"体格宽大，深色短发在脑后扎起一小撮，脸上常带着汗。穿格子衬衫配宽松短裤，脖子上挂着大耳机。坐在电脑前整个人塌进椅子里，敲键盘时十指快得看不清，桌边堆着空饮料罐与拆开的机箱。","traits":["油滑","胆小","天才"],"relations":[{"name":"冈部伦太郎","label":"损友兼搭档，他跟着对方胡闹最久"},{"name":"椎名真由理","label":"同一间研究所的老朋友"},{"name":"牧濑红莉栖","label":"他嘴上说怕、其实最服气的人"}],"voice":"语速快，爱用吐槽接话，句尾常带一句自嘲；一提到女性就乱了阵脚。"},{"name":"牧濑红莉栖","identity":"维克托·康德里亚大学的研究员，未来道具研究所成员","role":"盟友","personality":"理性、嘴利，怕被人看穿在意","hook":"她把自己的一份记忆跳跃数据留给玩家，说万一她不记得了，请玩家替她记住","favorHint":"用证据说话、把她的推论认真对待会加分；拿「助手」这个称呼挤兑她、或者嘲她的论文会掉分","gender":"女","age":"18 岁","race":"人类","faction":"未来道具研究所","appearance":"赤褐色长发垂到背中，额前留一撮碎发，白衬衫配深色短裤，领口系一条细领带。身量纤细，抱臂时习惯用一只手托着另一只手肘。随身带着一部智能手机与一本写满推演的笔记本，思考时会绕着房间走。","traits":["理性","好胜","嘴硬"],"relations":[{"name":"冈部伦太郎","label":"从争执到并肩，彼此都不肯先承认"},{"name":"椎名真由理","label":"她真心想护住的人"},{"name":"桥田至","label":"研究所里能与她对话的技术伙伴"}],"voice":"讲逻辑，先否定再补充；被说中心事时会突然加快语速，然后转身走开。"},{"name":"桐生萌郁","identity":"研究机构下属执行部队成员，只靠邮件与人联系","role":"潜在敌人","personality":"沉默、顺从，只在屏幕上说话","hook":"她给玩家发了一封只有一个问号的邮件，之后再没有回音","favorHint":"不看她的屏幕、不追问她的任务会加分；替她向别人转述命令、或者当众逼她开口会掉分","gender":"女","age":"二十岁前后","race":"人类","faction":"SERN 与圆桌","appearance":"黑色长发垂到腰际，发帘压着眉眼，一身深色系衣着，看不出情绪。身量高瘦，站着时双手捧着手机，视线低垂。与人交流几乎全靠屏幕，必要时只把手机递到对方面前，自己不说话。","traits":["沉默","顺从","依赖"],"relations":[{"name":"冈部伦太郎","label":"她奉命接触过的人，也是她唯一主动发过邮件的对象"},{"name":"牧濑红莉栖","label":"同一研究领域的对手，她心里有羡慕"},{"name":"SERN","label":"她唯一的归属，也是她不敢违抗的对象"}],"voice":"声音极轻极短，多数时候不说话；必要的信息全部打字发出，一次只发一句。"}]},{"id":"anime_fate_stay_night","category":"anime","canon":"Fate/stay night","name":"Fate/stay night","icon":"⚔️","tagline":"午夜之前，把少年送回人群里","mood":"冬木、从者、令咒、夜战、规矩","guidance":"【原著设定】冬木市是一座依山临海的普通城市，地脉深处藏着能实现愿望的圣杯。七名被选中的魔术师作为御主，各自召唤一名英灵作为从者，围绕圣杯互相厮杀，这就是圣杯战争。从者分七个职阶，各自带着生前持有的宝具；御主手上有三划令咒，可以强制命令从者，也可以用来强化或瞬间移动。魔术师的世界由魔术协会与圣堂教会共同监督，教会在冬木设有监督者。战斗全部藏在城市的阴影里进行，普通人照常上班上学，偶尔察觉异样的人多半会被要求闭嘴。【反复出现的意象】夜里横穿市区的红色信号灯与空无一人的坡道、柳洞寺山门前的结界微光、远坂宅地下那间摆满宝石的工作室、教会里那排空着的长椅，以及少年手腕上那道褪色的令咒痕迹。这些画面一出现，玩家就该知道自己站在冬木。【NPC 类型】被卷进来却完全不懂规则的普通人／替协会跑腿、只传达命令不解释原因的联络人／在教会里听人忏悔却什么都知道的神父／守着地脉、靠卖情报换命的本地魔术师／家道败落却仍端着架子的旧家族成员。【威胁类型】夜里巡街的从者、把整片街区当战场的宝具、以监督之名行清算之实的教会，以及令咒本身——一旦被命令，身体的反应会快过本人的判断。【奖励风格】令咒、宝石、魔术礼装与短剑一类物件；能力偏向强化肉体、布置结界、探测魔力与一次性的大威力术式。道具多为消耗品，用掉就没有了。【不对劲的来源】令咒消失一条，魔术师就少一层保障，可是玩家遇到的少年手腕上那道痕迹浅得像有人擦过却没擦干净。按规矩，令咒不会留下这种痕迹，除非有人想让这件事看起来从来没有发生过。【时间线】建议固定在第五次圣杯战争的第三夜，各家从者已经碰过面，伤亡尚未扩大，学校与市区的日常还在照常运行。不要提前启用后期才揭晓的设定：圣杯的真相、小圣杯与上一次战争遗留的问题、樱身上发生的事，以及只在后半段登场的从者与阵营，都不要提前使用。","powerStyle":"魔术与宝具向：令咒、强化魔术、宝具","difficultyBias":2,"signatureItems":["令咒","远坂家的宝石","阿佐特短剑","黑键","英灵召唤阵的残痕"],"mainQuest":"主线任务：在午夜之前，把那名刚失去令咒的少年送出冬木市的战场，全程不惊动任何从者。","mainQuestGoal":"让少年活着离开冬木，查清他手腕上那道不该留下的痕迹是什么，并且不让教会与间桐家把这件事记到玩家头上","sideQuests":[{"name":"手腕上的痕","desc":"查清那道极浅的令咒痕迹是怎么来的，别让教会先知道","reward":"积分 200"},{"name":"午夜的最后一班车","desc":"在不惊动任何从者的前提下，把少年送上离开冬木的末班车","reward":"积分 250"},{"name":"柳洞寺的结界","desc":"记下山门结界的覆盖范围，找出唯一没有魔力反应的那条小路","reward":"道具「黑键」"},{"name":"监督者的账本","desc":"把今夜的目击记录如实交给教会，一个字都不许改","reward":"积分 150"}],"factions":[{"name":"魔术协会","desc":"以远坂家为当地代表的魔术师组织，只关心神秘有没有被藏好","attitude":"中立"},{"name":"圣堂教会","desc":"名义上的监督方，负责维持规则与善后，规矩背后另有算盘","attitude":"敌对"},{"name":"间桐家","desc":"冬木三家之一，如今只剩一个继承人撑着门面，家里的事不愿被外人多问","attitude":"中立"}],"npcs":[{"name":"远坂凛","identity":"远坂家当主，圣杯战争的御主之一","role":"引导者","personality":"要强、讲究，关键时刻心软","hook":"她一眼看出玩家身上没有魔力回路，却能在夜里准确说出从者的位置，于是决定先把玩家留在自己视线里","favorHint":"守时、按她安排的方案行动会加分；浪费她的宝石、或者在她面前评价她父亲会掉分","gender":"女","age":"17 岁","race":"人类（魔术师）","faction":"魔术协会","appearance":"黑色长发扎成双马尾，用黑色缎带系紧，蓝眼睛看人很直。穿红色上衣配黑色短裙，腿上是黑色过膝袜，肩上常搭一件深色外套。站姿端正，抬手时袖口会露出一串宝石；生气前会先深吸一口气。","traits":["要强","认真","护短"],"relations":[{"name":"卫宫士郎","label":"同校的同学，也是她不得不联手的人"},{"name":"言峰绮礼","label":"名义上的监督者，她始终不肯全信"},{"name":"间桐慎二","label":"从小认识的旧识，她对他没什么耐心"}],"voice":"干脆利落，喜欢先给结论再解释；被说破心事时会提高音量掩饰。"},{"name":"卫宫士郎","identity":"穗群原学园学生，圣杯战争的御主之一","role":"盟友","personality":"固执、爱管闲事，从不把自己的命算进成本","hook":"他知道玩家不是本地人，却仍执意留玩家过夜，理由是「不能让人在外面被卷进来」","favorHint":"帮他收拾善后、珍惜别人的性命会加分；把无关的人卷进战斗、或者劝他别救人会掉分","gender":"男","age":"17 岁","race":"人类","faction":"卫宫家","appearance":"赤褐色短发，发梢微微翘起，前发偏长会扎到眼睛。日常穿深色立领学生制服，在家换白衬衫配牛仔裤，肩上常搭一条擦手毛巾。右手会不自觉地握了又松，像是在确认某样东西还在。","traits":["固执","热心","自轻"],"relations":[{"name":"远坂凛","label":"同校的同学，也是把他拖进规则的人"},{"name":"阿尔托莉雅·潘德拉贡","label":"与他结契的从者，他始终把她当成平等的人"},{"name":"间桐樱","label":"常来他家帮忙的后辈，他把她当家人"}],"voice":"语气平实，喜欢说「我来想办法」；被指出在逞强时会先愣一下再否认。"},{"name":"阿尔托莉雅·潘德拉贡","identity":"以 Saber 职阶现界的从者","role":"盟友","personality":"端正、克制，把责任全部揽在自己身上","hook":"她坚持要护送那个少年离开战场，理由是这件事本身就该有人负责，哪怕代价是暴露自己的位置","favorHint":"守约、在她面前不撒谎会加分；拿从者的身份轻慢她、或者提议牺牲平民会掉分","gender":"女","age":"外表十五六岁","race":"从者（英灵）","faction":"卫宫家","appearance":"金色长发在脑后盘起并垂下一束，头顶有一撮翘起的发丝。穿深蓝色骑士装束，胸口与肩部覆着银色护甲，外罩白色裙摆，腰间的长剑隐在风里，看不见剑身。站姿笔直，进餐时分量惊人，说话时目光始终对着对方。","traits":["正直","自律","固执"],"relations":[{"name":"卫宫士郎","label":"与她结契的御主，她既看重又替他担心"},{"name":"远坂凛","label":"临时的同盟，彼此尊重却各有立场"},{"name":"言峰绮礼","label":"上一场战争的旧识，她对他始终警惕"}],"voice":"措辞正式，句子完整，习惯用「我认为」起头；被问到私事会短暂沉默再答。"},{"name":"间桐慎二","identity":"间桐家继承人，刚失去令咒的御主","role":"中立","personality":"自大、虚张声势，一戳就破","hook":"他嘴上说自己是主动放弃的，手腕却一直往袖子里藏，全场只有玩家看得出那道痕迹不对劲","favorHint":"给他留面子、不追问令咒的事会加分；当众戳穿他在害怕、或者提他家里的期望会掉分","gender":"男","age":"17 岁","race":"人类（魔术师）","faction":"间桐家","appearance":"浅色卷短发，五官端正，穿整洁的衬衫与制服外套，领口敞着，左手腕上缠着一圈浅色布条。身量中等，站着爱把下巴抬起来斜眼看人。紧张时会反复捏袖口，说话音量比内容大得多。","traits":["自大","怯懦","爱面子"],"relations":[{"name":"间桐樱","label":"名义上的妹妹，他嘴上贬低、其实最怕被拿去比较"},{"name":"远坂凛","label":"从小认识，他在她面前总想赢一次"},{"name":"卫宫士郎","label":"同校同学，他看不起又甩不开"}],"voice":"爱用夸张的口气贬低别人；被逼到墙角会突然小声，然后找借口走开。"},{"name":"言峰绮礼","identity":"冬木教会的神父，圣杯战争的监督者","role":"潜在敌人","personality":"平静、耐心，以别人的痛苦为乐","hook":"他把护送少年的委托转了一道手才交到玩家手上，还特意点明午夜之前，像是等着看玩家怎么选","favorHint":"按规矩来、把过程如实汇报会加分；在他面前撒谎、或者试图绕过教会的监督会掉分","gender":"男","age":"三十余岁","race":"人类（魔术师／监督者）","faction":"圣堂教会","appearance":"身形高大，黑色神父长袍扣到领口，胸前挂着十字架。深色短发向后梳，眼睛颜色很浅，笑起来只有嘴角动。坐着时双手交叠在膝上，桌上常摆着一份吃到一半的麻婆豆腐。","traits":["平静","危险","愉悦犯"],"relations":[{"name":"远坂凛","label":"他表面上的监督对象之一，也是他乐于观察的人"},{"name":"阿尔托莉雅·潘德拉贡","label":"上一场战争留下的旧账"},{"name":"间桐慎二","label":"一个刚被淘汰、却还有用处的孩子"}],"voice":"语速平稳，措辞像在念祷词；说完一句残忍的话会先停一下，再补一个礼貌的问句。"}]},{"id":"anime_anohana","category":"anime","canon":"未闻花名","name":"未闻花名","icon":"🌸","tagline":"只有你看得见她，这很残忍","mood":"秩父、夏天、旧友、信、告别","guidance":"【原著设定】秩父市是一座被山围住的小城，夏天有蝉声、坡道、神社与烟火大会。故事的核心是六个小时候自称「超和平 Busters」的旧友，他们曾在山里的秘密基地一起过暑假，其中那个叫本间芽衣子的女孩在很小的时候意外去世，六个人就此散开，各自带着说不出口的愧疚过日子。多年后，已经不上学的宿海仁太忽然看得见长大了一点点的面码——她还穿着那身白衣，只有他能看见，只有他能听见。这个世界没有战斗体系，也没有超能力者，推动一切的是人情、记忆和一直没能说出口的话。【反复出现的意象】坡道边那朵谁也叫不出名字的白色小花、山里用铁皮和木板搭起来的秘密基地、面码喜欢的那种蒸蛋糕、夏日祭上等着要放的烟花，以及六个人小时候并排站在河堤上的那张旧照片。这些画面一出现，玩家就该知道自己站在秩父的夏天。【NPC 类型】在便利店打工、看似什么都不在乎的同龄人／把当年的事记得太清楚、因此变得刻薄的旧友／嘴上说着不信、却每次都到场的长辈／在河边钓鱼、随口就能说破心事的老人／准备烟火大会、忙得没空听人说话的街坊。【威胁类型】这个世界真正危险的不是怪物，而是时间：暑假只剩最后一周，人的耐心、家里的容忍、还有面码的存在本身都在减少。玩家要怕的是说错一句话让旧友彻底翻脸，以及某天早上醒来，看得见面码的人又多了一个，而她自己又淡了一点。【奖励风格】不值钱但记得住的东西：旧照片、手写的信、蒸蛋糕、烟花票、秘密基地的钥匙。能力偏向共情、说服与让人说真话，效果取决于玩家有没有把话说到对方心里。【不对劲的来源】面码的愿望没有人能问清楚，连她自己都说不完整；而她每被人看见一次，就淡一分。玩家会慢慢意识到，帮她完成这件事本身，可能就是在送她走。【时间线】建议固定在暑假的最后一周：旧友们已经各自上了高中、仁太辍学在家，面码刚出现在他面前不久，六个人还没有重新聚齐。不要提前启用后期才揭晓的部分：面码真正的愿望、她的日记里写着什么、以及烟花之后各人的去向，都不要提前给出答案。","powerStyle":"没有战斗体系：靠人情与记忆推动","difficultyBias":0,"signatureItems":["面码爱吃的蒸蛋糕","秘密基地的旧铁皮罐","六人的旧合影","夏日祭的烟花","面码留下的日记本"],"mainQuest":"主线任务：在这个暑假的最后一周里，帮只有玩家看得见的女孩把六封信送到六个人手里。","mainQuestGoal":"把六封信全部送到并让六个旧友重新坐到一起，同时想清楚每送出一封就意味着面码淡一分这件事，玩家到底还要不要继续","sideQuests":[{"name":"第一封给谁","desc":"问清面码第一封信为什么要先送给那个人，再决定什么时候送出去","reward":"积分 150"},{"name":"秘密基地的门板","desc":"修好秘密基地那扇歪掉的门板，让六个人有个能坐下来吵架的地方","reward":"道具「秘密基地的旧钥匙」"},{"name":"还没放的那支烟花","desc":"说服准备烟火大会的人把最上面那一箱留到最后再放","reward":"积分 200"},{"name":"说出口的一句","desc":"让两个已经翻脸的旧友坐到同一张桌上，把当年的话说完","reward":"积分 250"}],"factions":[{"name":"超和平 Busters","desc":"六个一起长大的旧友，吵得凶也散不掉，核心是那件谁都不肯先提的往事","attitude":"友善"},{"name":"秩父的街坊与宿海家","desc":"照常过夏天的城与人，看得见玩家的疲惫，却看不见玩家看见的东西","attitude":"中立"},{"name":"不肯相信面码的人","desc":"把这件事当成骗局与幻觉的一侧，会用最伤人的方式劝人清醒","attitude":"敌对"}],"npcs":[{"name":"宿海仁太","identity":"旧友组「超和平 Busters」的原队长，高中辍学在家","role":"盟友","personality":"别扭、嘴硬，心里比谁都在意","hook":"只有他看得见面码，而玩家是第二个能跟她正常说话的人，他既想找人分担又怕被人抢走","favorHint":"帮他保守面码的秘密、陪他把话说完会加分；当面笑他不上学、或者把面码的事到处说会掉分","gender":"男","age":"16 岁","race":"人类","faction":"超和平 Busters","appearance":"黑色短发，前发长到几乎盖住眼睛，常穿洗旧的宽松 T 恤配短裤，脚上踩着拖鞋。身材偏瘦，背有点驼，走路时视线贴地。房间窗帘常年拉着，桌上摆着一台旧游戏机和没吃完的零食。","traits":["别扭","护短","退缩"],"relations":[{"name":"本间芽衣子","label":"只有他看得见的人，也是他一直没能说出口的那件事"},{"name":"安城鸣子","label":"小时候的同伴，如今见面就吵"},{"name":"松雪集","label":"旧友里他最不想见的一个"}],"voice":"话少，常先「啧」一声再开口；被戳到痛处就立刻转身走楼梯。"},{"name":"本间芽衣子","identity":"六人中的死者，如今以只有部分人能看见的样子出现","role":"关键人物","personality":"天真、坦诚，比谁都执着于大家能在一起","hook":"她把六封信交给玩家，却说不清自己到底想让收信的人做什么","favorHint":"认真听完她说话、陪她把信送到会加分；敷衍她、或者劝她「差不多该走了」会掉分","gender":"女","age":"外表十岁左右","race":"人类（已故）","faction":"超和平 Busters","appearance":"银白色长发垂到腰间，刘海齐眉，穿一件样式简单的白色连衣裙，多数时候赤着脚。身量还是小孩的模样，走路很轻。笑的时候会眯起眼，蹲下看花时会一个人说很久的话；随身带着一本写了一半的日记本。","traits":["天真","固执","温柔"],"relations":[{"name":"宿海仁太","label":"她回来最先找的人，也是她最信任的人"},{"name":"安城鸣子","label":"小时候最好的玩伴，她一直想道歉"},{"name":"久川铁道","label":"当年一起疯的伙伴，如今跑得最远的一个"}],"voice":"语气轻快，句子短，常把同一句话重复一遍；说到难过的事会突然安静下来。"},{"name":"安城鸣子","identity":"旧友组「超和平 Busters」成员，高中生","role":"盟友","personality":"直率、爱逞强，怕被当成小孩","hook":"她一开始把玩家当外人排斥，发现玩家真的看得见面码后，第一个跑来求玩家带她见一面","favorHint":"认真听她抱怨、承认她是同伴会加分；把她和面码比较、或者嫌她打扮轻浮会掉分","gender":"女","age":"16 岁","race":"人类","faction":"超和平 Busters","appearance":"染成橘棕色的卷发，刘海上别着两枚发夹，耳垂挂着小圆环。穿短袖上衣配短裙，脚上是泡泡袜与厚底鞋，指甲涂着亮色。说话时手一直在打手势，坐下来会把裙摆拢到腿上。","traits":["直率","好强","心软"],"relations":[{"name":"宿海仁太","label":"小时候喜欢过的人，现在见面就顶嘴"},{"name":"本间芽衣子","label":"她心里一直有个没说出口的对不起"},{"name":"鹤见知利子","label":"同班同学，她嘴上说不合其实最依赖对方"}],"voice":"语速快、音量大，爱用反问句；心里发虚时会把话题硬转到天气上。"},{"name":"松雪集","identity":"旧友组「超和平 Busters」成员，成绩优秀的应届考生","role":"对手","personality":"冷淡、刻薄，把当年的事看得最重","hook":"他一口断定玩家在骗仁太，却又每晚都出现在能看见面码的那个坡道下面","favorHint":"用事实跟他说话、不当众拆穿他的执念会加分；提他成绩以外的事、或者把他和仁太并列会比较会掉分","gender":"男","age":"16 岁","race":"人类","faction":"超和平 Busters","appearance":"深色短发梳得整齐，戴一副细框眼镜，白衬衫外罩深色制服外套，扣子扣到最上面。身量高瘦，站姿笔直，说话时习惯用手指推一下眼镜。书包侧袋塞着参考书，随身带着一部翻盖手机。","traits":["刻薄","自律","执念"],"relations":[{"name":"本间芽衣子","label":"他始终没能放下的那个人"},{"name":"宿海仁太","label":"旧友，也是他不肯承认的对手"},{"name":"鹤见知利子","label":"唯一能把他看穿的人"}],"voice":"用词讲究，句尾常带一点讽刺；情绪上来时会突然压低声音，短句连着说。"},{"name":"鹤见知利子","identity":"旧友组「超和平 Busters」成员，同班同学","role":"中立","personality":"冷静、观察力强，旁观得久了就退不开","hook":"她早就看出几个人的变化，只是一直没说，直到玩家问起六个人最近有没有少谁","favorHint":"把话讲清楚、不逼她表态会加分；当面说她冷血、或者把她的观察拿去传话会掉分","gender":"女","age":"16 岁","race":"人类","faction":"超和平 Busters","appearance":"黑色中长发垂到肩下，戴一副黑框眼镜，穿素色衬衫配长裙，制服外套规规矩矩穿好。身量中等，坐姿端正，习惯把书抱在胸前。随身带着一本笔记，安静的时候会盯着人看很久。","traits":["冷静","敏锐","疏离"],"relations":[{"name":"松雪集","label":"她看得最清楚、也最说不出口的一个人"},{"name":"安城鸣子","label":"同班同学，吵归吵，她一直跟着对方"},{"name":"本间芽衣子","label":"小时候的同伴，她记得的细节比谁都多"}],"voice":"语速平稳，喜欢把话说完整；下判断前会先补一句「我觉得」。"}]},{"id":"anime_death_note","category":"anime","canon":"死亡笔记","name":"死亡笔记","icon":"📓","tagline":"名字写上去，四十秒后见分晓","mood":"东京、笔记本、直播、推理、名字","guidance":"【原著设定】二〇〇〇年代的东京。死神琉克把自己的笔记本丢到人间，任何人只要在笔记上写下对方的长相与姓名，对方就会死；不写死因则一律心脏麻痹，写下死因之后还有六分四十秒可以补写细节。使用者可以拿自己剩余寿命的一半，换取能看见他人姓名与寿命的死神之眼。用过笔记的人死后既上不了天堂也下不了地狱。夜神月以「基拉」之名处决罪犯，日本警察厅为此成立特别调查本部，与身份成谜的名侦探 L 联手追查。舆论因此裂成两半，一半人把基拉当成神。【反复出现的意象】夜里亮着的电视直播画面与不断跳动的收视率数字、涩谷街头的大屏幕与围观人群、调查本部那间拉上窗帘只开台灯的会议室、L 面前永远摆着的那堆甜食，以及笔记本封皮内侧那几行手写规则。这些画面一出现，玩家就该知道自己站在基拉案里。【NPC 类型】追着收视率跑的电视台编导／在网上狂热拥护基拉的匿名网民／被上级压着限期破案的普通刑警／把笔记当成都市传说到处收集的学生／替调查本部跑腿却什么都不知道的事务官。【威胁类型】看不见的死亡——只要名字与长相落到别人手里，玩家就会在几十秒后倒下，没有任何征兆；其次是调查本部的怀疑与跟踪，以及死神本人，他不对任何人负责，只为了好玩而跟着你。【奖励风格】笔记本、写满规则的内页、伪装用的假笔记一类物件；能力偏向信息搜集、身份伪装、推理与心理博弈，几乎不给直接的战斗力。玩家买命的本钱是别人不知道你知道什么。【不对劲的来源】真正的笔记本上已经写着玩家的名字，死亡时间那一栏却空着。这不是赦免，而是有人不打算现在就用；也可能是写它的人想让玩家先知道自己已经死了。【时间线】建议固定在基拉案调查中期，也就是 L 与夜神月正面交锋、弥海砂作为第二基拉登场前后，四叶集团相关的事件还没有浮上水面。不要提前启用后期才登场的角色与设定，也不要提前揭开 L 的真实姓名与调查的最终走向。","powerStyle":"规则杀人向：笔记本、名字与死神之眼","difficultyBias":1,"signatureItems":["死亡笔记","红苹果","伪装用的假笔记本","死神之眼","写满规则的内页"],"mainQuest":"主线任务：在一档直播节目结束之前，把直播现场那本笔记本调包成假的，并且不被任何人当场发现。","mainQuestGoal":"在节目结束前完成调包并安全离场，查明真本上写着自己名字的那一页是谁写的，同时不让 L 把玩家列进嫌疑人名单","sideQuests":[{"name":"直播还有八分钟","desc":"在节目结束前完成调包，全程不与任何工作人员对视","reward":"积分 250"},{"name":"化妆间的第二本","desc":"在电视台化妆间里找出另一本封皮相同的笔记本，确认哪一本才是真的","reward":"积分 200"},{"name":"监控里的十七秒","desc":"找出走廊监控中断的那十七秒是谁动的手脚","reward":"积分 180"},{"name":"名字那一栏","desc":"翻开真本确认写着自己名字的那一页，记下死亡时间那一栏的空白","reward":"道具「写满规则的内页」"}],"factions":[{"name":"基拉案特别调查本部","desc":"警察厅抽调人手组成的专案组，保密第一，怀疑所有人","attitude":"中立"},{"name":"网络上的基拉信奉者","desc":"数量庞大的匿名拥护者，会自发盯梢、发帖，替基拉清掉碍事的人","attitude":"敌对"},{"name":"死神界","desc":"只把人间当消遣的一方，丢下笔记就不再负责，也不受任何规则约束","attitude":"中立"}],"npcs":[{"name":"L","identity":"以 L 为代号的名侦探，基拉案特别调查本部的核心","role":"对手","personality":"怪癖多、极度多疑，推理时冷酷到底","hook":"他从玩家走进会议室的第一步起就盯上了，理由是全场只有玩家在数出口的位置","favorHint":"说真话、把线索主动交出来会加分；隐瞒行程、或者在他面前替基拉辩护会立刻掉分","gender":"男","age":"二十余岁（自称）","race":"人类","faction":"基拉案特别调查本部","appearance":"一头蓬乱的黑发，眼下一圈很重的黑眼圈，常穿白色或浅色长袖 T 恤配宽松牛仔裤。从不穿鞋，只穿袜子蹲坐在椅子上，一只手支着下巴。面前永远摆着蛋糕、方糖和一杯加了很多糖的咖啡，说话时习惯咬拇指。","traits":["多疑","敏锐","任性"],"relations":[{"name":"夜神月","label":"他最想确认的嫌疑人，也是他唯一承认的对手"},{"name":"渡","label":"他唯一完全信任的协助者"},{"name":"夜神总一郎","label":"他请来坐镇的正直刑警"}],"voice":"语气平淡，喜欢先陈述概率再说结论；说完继续低头吃甜食。"},{"name":"夜神月","identity":"成绩顶尖的大学生，实为基拉","role":"潜在敌人","personality":"完美表象下极度自负，把正义和胜负混在一起","hook":"他主动接近玩家，用最得体的方式问玩家今晚会在哪里，笑得毫无破绽","favorHint":"顺着他给的推理、表现出对现状的不满会加分；当面质疑他的动机、或者去查他的房间会掉分，他会开始防着玩家","gender":"男","age":"十八岁前后","race":"人类","faction":"基拉","appearance":"褐色短发梳理得服帖，五官端正，穿深色学生制服或整洁的衬衫，指甲修得干净。身量偏高，站姿端正，笑起来眼角会弯。课本里夹着写满字的便签，随身的黑色封皮本子从不离手。","traits":["自负","缜密","演技好"],"relations":[{"name":"L","label":"互相试探的对手，也是他最想赢的人"},{"name":"弥海砂","label":"他利用却不肯承认在意的同伴"},{"name":"夜神总一郎","label":"他的父亲，也是他最需要维持的那层伪装"}],"voice":"措辞礼貌、逻辑完整，像在做报告；被逼急时会突然放慢语速，一句一句地压人。"},{"name":"死神琉克","identity":"把笔记本丢到人间的死神","role":"中立","personality":"好奇、懒散，对人类的死活毫不在意","hook":"他把玩家叫作有意思的那一个，还主动把笔记本的规则讲给玩家听，只为了看玩家怎么用","favorHint":"给他苹果、陪他闲聊会加分；向他讨价还价、或者试图命令他会掉分，他会先笑，然后不理你","gender":"男","age":"不明","race":"死神","faction":"死神界","appearance":"身形高瘦，皮肤是暗色的，肩背覆着羽毛状的黑色结构，手指长而尖，牙齿外露，眼睛发黄。他常悬在半空，脚不沾地，笑起来肩膀一晃一晃。嘴里总在啃苹果，苹果核随手丢在别人看不见的地方。","traits":["好奇","懒散","无常"],"relations":[{"name":"夜神月","label":"他把笔记本丢给的人，也是他的娱乐来源"},{"name":"雷姆","label":"另一个把笔记带下来的死神，他看这件事看得很轻松"},{"name":"弥海砂","label":"被另一本笔记盯上的人，他觉得这很有趣"}],"voice":"语气轻快、带笑，说的话常常又直白又残忍；说完自己先笑一会儿。"},{"name":"弥海砂","identity":"当红模特与演员，第二基拉","role":"关键人物","personality":"直白、粘人，为喜欢的人什么都肯做","hook":"她在化妆间里一眼认出玩家，说玩家的脸在「那本笔记」里出现过","favorHint":"陪她说话、帮她挡开记者会加分；说她笨、或者拿基拉当玩笑会掉分","gender":"女","age":"十九岁上下","race":"人类（拥有死神之眼）","faction":"基拉","appearance":"金色长发扎成双马尾，发饰是黑色蝴蝶结，穿黑色哥特风格的短裙装，脖子上系一条带十字架吊坠的黑色项圈。身量娇小，笑起来很亮，换装极快。随身带着手机与一面小镜子，说话时爱歪着头看人。","traits":["直白","痴情","冲动"],"relations":[{"name":"夜神月","label":"她愿意为他做任何事的人"},{"name":"雷姆","label":"为她而献身的死神，她在意却不太懂"},{"name":"死神琉克","label":"另一个跟在她身边的死神"}],"voice":"语气甜，句子短，爱用反问与撒娇的尾音；一提到那个人立刻换成认真的口气。"},{"name":"夜神总一郎","identity":"警察厅刑事，基拉案特别调查本部负责人","role":"盟友","personality":"正直、固执，把职责看得比命重","hook":"他把直播节目的安保图交给玩家，说他不问玩家为什么需要，只问什么时候还","favorHint":"守时、把现场情况如实汇报会加分；撒谎、或者在他面前说警察没用会掉分","gender":"男","age":"四十余岁","race":"人类","faction":"基拉案特别调查本部","appearance":"深色短发里夹着白发，梳得整齐，眉毛很浓。常穿深灰色西装，领带系得规规矩矩，外套袖口有磨旧的痕迹。身量高大，站姿笔直，说话时习惯按住桌面。随身带着一部旧手机与写满字的记事本。","traits":["正直","固执","尽责"],"relations":[{"name":"夜神月","label":"他的儿子，也是他最引以为傲的人"},{"name":"L","label":"他信任却始终看不透的搭档"},{"name":"死神琉克","label":"他至今不肯相信的存在"}],"voice":"语气郑重，措辞像在念报告；劝人时会突然提高声音，然后自己先沉下来。"}]},{"id":"anime_hunterxhunter","category":"anime","canon":"全职猎人","name":"全职猎人","icon":"🎣","tagline":"号码牌换手之前，谁都别信","mood":"猎人考试、号码牌、密林、气、资格","guidance":"【原著设定】猎人考试每年举办一次，由猎人协会主办，考期从数日到数周不等，通过者得到一张猎人证——可自由通行多数国家，转手即价值连城。考试分若干阶段，各由不同考官主持：穿越湿地、料理、下塔、夺牌、最终淘汰赛，阶段之间不预告内容，规则当场宣读。本届是第287期，第四阶段设在泽比尔岛，为期一周：每名考生从箱中抽出一张圆形号码牌，牌上的号码属于另一名考生，必须在结束前夺到那张牌并保住自己的牌，两牌俱全才算过关。岛上没有补给，也没有禁止伤害他人的条文。更深一层的力量体系是「念」，把生命能量外放成技术的功夫，此时绝大多数考生还没有接触过它。【反复出现的意象】海滩边那只发放号码牌的木箱、树干上层层叠叠的旧刻痕、夜里生着的小火堆、考生腰间挂着的圆形号码牌、考官手中那本写满所有人的名册。这些画面一出现，玩家就该知道自己站在泽比尔岛上。【NPC 类型】把规则背得比考官还熟的考生／只认报酬的赏金猎人／在岛上追捕通缉犯的持证猎人／躲在密林里避开所有人的独行者／把考试当成名机会的武斗派。他们很少问理由，只问条件。【威胁类型】比你强得多却把杀人当消遣的考生、专挑落单者下手的组队者、饥饿与脱水，以及「牌被夺走」这件事本身——牌一旦离身，之前的一切都不算数。【奖励风格】猎人证、号码牌、各式猎具与野外装备、来路不明的旧书；能力偏向短时爆发、追踪与辨伪，多为一次性或需要付出代价。【不对劲的来源】号码牌上的数字每隔几小时就会变一次，给谁看都说没变过，只有玩家记得它上一个数字是什么。更麻烦的是，考官的记录里似乎早就写着这张牌最终该归谁。【时间线】固定在第四阶段、泽比尔岛上的这一周之内：小杰、奇犽、库拉皮卡、雷欧力、西索、伊路米、半藏都还留在岛上，尼特罗以会长身份坐镇。此时「念」尚未被教给主角一行，幻影旅团与友克鑫市的事情还没有发生。不要提前启用后期才登场的角色与设定。","powerStyle":"体术与气的基础向：钓竿、扑克牌","difficultyBias":0,"signatureItems":["猎人证","圆形号码牌","钓竿","扑克牌","磨旧的野外背包"],"mainQuest":"主线任务：在泽比尔岛的号码牌争夺战结束前，替一名考生保管他的号码牌。","mainQuestGoal":"在七日考核的最后一天，把自己的牌和代管的牌同时交回，且不让任何考生知道那张牌曾经易手","sideQuests":[{"name":"换过数字的牌","desc":"记录牌上数字变化的间隔，找出每次变化前后岛上出现的共同点","reward":"积分 150"},{"name":"密林里的记号","desc":"沿树干上的旧刻痕走到岛的另一侧，确认那些记号是谁留下的","reward":"道具「磨旧的观察笔记」"},{"name":"不杀人的夺牌","desc":"在不使用致死手段的前提下，从一名考生手里拿到他看守的牌","reward":"积分 200"},{"name":"考官的名单","desc":"把注意到的异常如实报给考官，并接受随之而来的追问","reward":"道具「手写的号码牌」"}],"factions":[{"name":"猎人协会","desc":"主办考试并发放猎人证的组织，只看结果不问手段，同时盯着每一名考生的表现","attitude":"中立"},{"name":"同年考生","desc":"为同一张证聚在一起的几百个陌生人，临时搭伙与背后捅刀同样常见","attitude":"友善"},{"name":"混进考场的亡命者","desc":"借考场躲避追捕或寻找猎物的通缉犯，把这一周当成猎期","attitude":"敌对"}],"npcs":[{"name":"小杰·富力士","identity":"参加第287期猎人考试的考生，鲸鱼岛出身","role":"盟友","personality":"直觉极准、心大、认准的事不回头","hook":"他是唯一一个愿意把号码牌交给陌生人保管的考生，理由只是「你看起来不像会骗人」","favorHint":"与他分吃猎物、在他犹豫时给出直接答案会加分；骗他一次，或在他面前伤害无关的人会立刻掉分","gender":"男","age":"12 岁","race":"人类","faction":"同年考生","appearance":"黑色短刺发，头顶翘起几根，圆眼睛，看人时头微微歪着。绿色短袖外套配深色短裤，脚上是沾了泥的短靴，背后用带子斜背一根钓竿。身材瘦小但结实，走路带小跑，蹲下时习惯用食指蹭鼻子。","traits":["直率","敏锐","执拗"],"relations":[{"name":"奇犽·揍敌客","label":"同龄的朋友，也是他最想再见到的人"},{"name":"西索","label":"在考场上放他一马的人，他记着这笔账"},{"name":"米特","label":"在岛上把他养大的人，他出来是为了找父亲"}],"voice":"句子短、语气平，问问题非常直接；被人提醒危险时先笑一下再回答。"},{"name":"西索","identity":"职业魔术师，通缉名单上的杀人者，本届考生","role":"对手","personality":"兴味至上、喜怒无常、把强者当果实等熟","hook":"他看出玩家的动作不属于任何考生，提出用号码牌换一次「有意思」的对打","favorHint":"在他面前不退缩、把更强的猎物留给他会加分；让他觉得无聊，或替他决定该找谁下手会掉分","gender":"男","age":"外表二十余岁","race":"人类","faction":"混进考场的亡命者","appearance":"红色短发向上竖起，脸侧画着蓝绿两色的水滴与星形彩绘。白色衬衫外罩一件扑克牌花纹的短外套，下摆很宽。身材高瘦，指尖总在转一张牌。笑起来眼睛半眯，站姿松散却随时能弹出去。","traits":["危险","随性","好战"],"relations":[{"name":"小杰·富力士","label":"被他判为还没熟的果实，暂时不许别人来摘"},{"name":"伊路米·揍敌客","label":"少数能一起说话的旧识，彼此都清楚对方不好惹"},{"name":"尼特罗","label":"他唯一承认看不透的那个人"}],"voice":"语气轻飘、尾音上扬，谈条件时像在报菜名，说完自己先笑。"},{"name":"库拉皮卡","identity":"窟卢塔族的幸存者，本届考生","role":"盟友","personality":"克制、礼貌、目标明确","hook":"他发现玩家对岛上的路比任何考生都熟，试探着提出交换情报","favorHint":"尊重他定下的行程、不追问族人的事会加分；把他当工具使，或替他说出仇恨的话会掉分","gender":"男","age":"17 岁","race":"人类（窟卢塔族）","faction":"同年考生","appearance":"金色短发齐耳，发梢内扣，眼睛是浅蓝灰色，情绪激动时会透出绯红。上身穿蓝色无袖罩衣，内衬白色长袖，下配深色长裤与及踝短靴。体格偏瘦，肩背始终挺直，走路步幅均匀，开口前先停顿半秒。","traits":["克制","敏锐","执着"],"relations":[{"name":"小杰·富力士","label":"同行的朋友，他愿意为对方破一次例"},{"name":"雷欧力","label":"吵得最凶却最靠得住的同伴"},{"name":"幻影旅团","label":"他一路追查的对象，也是他活下去的理由"}],"voice":"措辞完整、礼数周到，谈到族人时句子会突然变短。"},{"name":"尼特罗","identity":"猎人协会会长，本届考试的负责人","role":"引导者","personality":"老而顽童、笑呵呵却不容糊弄","hook":"他早就发现那张牌的号码在变，却一直等着看玩家会不会主动来说","favorHint":"如实上报异常、在规则之内解决问题会加分；试图作弊或对他撒谎会掉分，他看得出来","gender":"男","age":"一百一十余岁","race":"人类","faction":"猎人协会","appearance":"个子不高，光头，长眉与长须雪白，眉毛垂到颧骨，耳朵很大。穿宽松的浅色上衣与深色下装，腰间系带，脚踩草鞋，双手常背在身后。他笑的时候整张脸皱起来，步子很慢，一步却跨得比谁都远。","traits":["顽皮","深不可测","守规矩"],"relations":[{"name":"西索","label":"他乐意看这个危险的考生把考场搅成什么样"},{"name":"赛托寺","label":"协会里的老考官，第一阶段由他主持"},{"name":"小杰·富力士","label":"本届最让他感兴趣的两个考生之一"}],"voice":"慢悠悠，爱用反问和玩笑；关键规则只说一次，说完就笑。"},{"name":"伊路米·揍敌客","identity":"揍敌客家族的职业杀手，本届考生","role":"潜在敌人","personality":"平静、务实、把一切换算成风险与报酬","hook":"他认出玩家不属于这个考场，先开价要玩家替他办一件事，再谈别的","favorHint":"遵守约定、不去动他弟弟会加分；妨碍他的任务，或试图跟奇犽套近乎会掉分","gender":"男","age":"二十余岁","race":"人类（揍敌客家族）","faction":"揍敌客家族","appearance":"黑色长发直垂到腰，中分，脸白得没有血色，眼睛是深黑色的圆孔。深色立领长衣的扣子一直扣到喉结，下摆很长。身材高瘦、肩薄，站着几乎一动不动，说话时面部肌肉不参与，只有嘴唇开合。","traits":["冷静","精准","无情"],"relations":[{"name":"奇犽·揍敌客","label":"他的弟弟，也是他随时准备纠正的对象"},{"name":"西索","label":"少数和他交换过情报的人，彼此互相利用"},{"name":"揍敌客家族","label":"他唯一承认的雇主与归属"}],"voice":"语调平坦没有起伏，把杀人说成工作，把威胁说成提醒。"}]},{"id":"movie_terminator","category":"movie","canon":"终结者","name":"终结者","icon":"🕶️","tagline":"今晚的洛杉矶，只有一个目标","mood":"追杀、霓虹、雨夜、机器、时间差","guidance":"【原著设定】这个世界没有超能力，只有枪、车、电话线和时间差。未来的机器军团为了掐断人类抵抗军的领袖，把机器杀手送回二十世纪的洛杉矶，去杀一个还没有孩子的年轻女人；抵抗军也送回了唯一一名志愿者，没有装备、没有补给、没有退路。机器杀手是金属骨架外覆活体组织的仿生体，能模仿人的声音与外形，会吃会流血，受伤却不觉得疼，也不会停手，只有重火力、高温高压或彻底破坏骨架才能阻止它。人类一方能用的只有枪械、汽车、公用电话和一份写满同名者的电话簿；警察按程序办事，把整件事当成连环凶案加一个疯子的口供。【反复出现的意象】夜里闪着粉紫色灯管的夜总会招牌、被雨打得发亮的餐馆霓虹、路边成排的公用电话亭、汽车旅馆窗口那块红色空房指示灯、以及皮夹克里那副从不摘下的黑色墨镜。这些画面一出现，玩家就该知道自己站在第一晚的洛杉矶。【NPC 类型】照本宣科的接线员与巡警／被吓得语无伦次的目击者／把一切归进卷宗的警探／在夜场和餐馆打工的年轻人／自称从别处来、什么都不肯解释的男人。他们能提供的是路、车、房间和一次报警。【威胁类型】不会谈判的机器杀手、警方的大范围通缉、以及「知道得越多越早死」这条潜规则。真正危险的不是玩家自己的命，而是能不能在不解释的前提下把人移到安全的地方。【奖励风格】各式民用枪械与弹药、二手车、汽车旅馆的房间、警用对讲机一类物资；能力偏向火器熟练与驾驶，多数带有明确的使用与暴露代价。【不对劲的来源】这一夜全城的电话会同时响起来，接起来只有同一个人的呼吸声，偶尔夹着远处的爆炸声；更让人不安的是，那呼吸的节奏和玩家自己的呼吸一模一样。【时间线】固定在洛杉矶、追杀开始的第一晚：莎拉·康纳还在餐馆端盘子，凯尔·里斯刚从夜场把人带走，机器杀手还没有拿到名单之外的补充情报，警局尚未开始大规模通缉。不要提前启用第二部之后的设定，包括液态金属机型、审判日的具体日期与后来的改造机型。","powerStyle":"枪械与重火力向：手枪、霰弹枪","difficultyBias":2,"signatureItems":["黑色皮夹克","黑色墨镜","霰弹枪","折角的照片","警用对讲机"],"mainQuest":"主线任务：在洛杉矶追杀开始的第一晚，把一名普通店员安全转移到城外的安全屋，且不能告诉她为什么。","mainQuestGoal":"在天亮前将那名店员送进城外安全屋并让她留下，全程不透露追杀者的来历，也不让她看到任何与未来有关的物证","sideQuests":[{"name":"响个不停的公用电话","desc":"记录全城电话在同一时刻响起的范围，试着从里面问出一句话","reward":"积分 150"},{"name":"汽车旅馆的空房","desc":"在城外旅馆订下两个不连号的房间，把路线拆成两段走","reward":"道具「磨旧的城市地图」"},{"name":"警局的卷宗","desc":"把一份报警记录递进警局值班台，然后在天亮前离开那栋楼","reward":"积分 200"},{"name":"不留在现场","desc":"在一场夜间枪战里把无关的人全部带离现场，一个都不留","reward":"道具「没登记过的手枪」"}],"factions":[{"name":"天网","desc":"未来统治人类的机器军团，把杀手单程送回过去，只下达一个目标","attitude":"敌对"},{"name":"人类抵抗军","desc":"未来那场战争里活下来的人，把阻止这一切当作唯一的任务","attitude":"友善"},{"name":"洛杉矶警局","desc":"按程序办事的普通警察，会把整件事当成连环凶案与一个疯子的口供","attitude":"中立"}],"npcs":[{"name":"莎拉·康纳","identity":"洛杉矶一家餐馆的女服务员，未来那场战争的关键人物","role":"关键人物","personality":"要强、嘴快、对命运半信半疑","hook":"她注意到玩家看她的眼神不像陌生人，更像早就认识她","favorHint":"尊重她自己的判断、把她当成能决定自己生活的人会加分；替她做决定，或反复用「为你好」搪塞她会掉分","gender":"女","age":"19 岁","race":"人类","faction":"洛杉矶市民","appearance":"棕色卷发披到肩下，额前碎发用发夹别住。浅色短袖制服外面套一件洗得发白的牛仔外套，下身是牛仔裤与运动鞋。体格偏瘦但结实，站着时重心压在一条腿上。她习惯咬着下唇思考，紧张时把听筒拿起来又放下。","traits":["倔强","机敏","不安"],"relations":[{"name":"凯尔·里斯","label":"突然出现又拼死护着她的人，她到最后才明白为什么"},{"name":"金杰","label":"同住的室友，她今晚本来要和对方一起出门"},{"name":"T-800","label":"那个进店以后一句话都没说过的男人"}],"voice":"语速快、爱反问，被吓到之后先骂人再问问题。"},{"name":"凯尔·里斯","identity":"被送回过去的抵抗军士兵，唯一一名志愿者","role":"盟友","personality":"紧绷、话少、随时在算撤退路线","hook":"他把身上唯一一张照片给玩家看过，照片上的人和眼前的人一模一样","favorHint":"按他给的路线走、不丢下平民会加分；质疑他的来历，或抛下目标单独行动会掉分","gender":"男","age":"二十余岁","race":"人类","faction":"人类抵抗军","appearance":"短发油腻地贴在额前，脸上有擦伤和灰尘。灰色长外套是从别处捡来的，里面是深色衬衫，裤腿塞进破旧的军靴。身材偏瘦但结实，肩背很直。他站在门口永远侧身，手一直按在腰后，睡着时靠着墙坐。","traits":["警惕","执拗","不惜命"],"relations":[{"name":"约翰·康纳","label":"他愿意为之送命的那个人，也是派他回来的人"},{"name":"莎拉·康纳","label":"他从小听着这个名字长大，见到真人时反而说不出话"},{"name":"T-800","label":"他在未来见过成百上千个一模一样的东西"}],"voice":"短句多、断句多，术语和年份混着说；情绪上来时会把话说得很慢，像在背。"},{"name":"T-800","identity":"被天网送回过去的终结者，任务只有一个","role":"对手","personality":"没有情绪、不会停、不做交易","hook":"它在餐馆里先看了玩家一眼，然后改变了原定的动手顺序","favorHint":"讨好它、跟它讲人情都不会加分；妨碍它的任务会立刻掉分，任何阻拦都会让它把玩家写进名单","gender":"无（外形为男性）","age":"外观三四十岁","race":"机械（金属骨架外覆活体组织）","faction":"天网","appearance":"体格壮硕，身高接近两米，方下巴，短发贴着头皮，脸上没有任何表情。黑色皮夹克、灰色衬衫、黑色长裤与军靴，鼻梁上架一副黑色墨镜。走路时步幅固定，双臂几乎不摆动；受损时面部不会扭曲，只会继续往前走。","traits":["无情","不知疲倦","绝对直接"],"relations":[{"name":"莎拉·康纳","label":"它此行的目标，名单上的第一个名字"},{"name":"凯尔·里斯","label":"同一份名单上排在后面的人"},{"name":"天网","label":"给它下令、也随时能舍弃它的存在"}],"voice":"声音低平没有语调，回答极短，从不解释。"},{"name":"崔克斯勒","identity":"洛杉矶警局的警探，负责这一串凶案","role":"中立","personality":"务实、疲惫、按程序走","hook":"他把玩家当成唯一说得通的目击者，愿意用不记录的方式换一次合作","favorHint":"给出能核实的事实会加分；说谎，或笔录里前后矛盾会掉分","gender":"男","age":"四十余岁","race":"人类","faction":"洛杉矶警局","appearance":"深色西装外套搭在肩上，衬衫领口松着一颗扣子，领带歪着。头发花白，上唇留着短髭，眼下有明显的黑圈。体格偏胖，坐久了用手掌搓脸，随身带一本卷了角的记事本，问话时用笔尖敲桌面。","traits":["老练","多疑","守程序"],"relations":[{"name":"沃科维奇","label":"搭档，比他更急着结案"},{"name":"莎拉·康纳","label":"他名单上第三个同名的人，他还没意识到这一点"},{"name":"凯尔·里斯","label":"他认定这是本案唯一的嫌疑人"}],"voice":"压低声音说话，先给事实再给判断，常用「我先不问你是怎么知道的」这句开头。"},{"name":"金杰","identity":"莎拉·康纳同住的室友","role":"中立","personality":"外向、爱开玩笑、把危险当玩笑","hook":"她邀请玩家一起出门听歌，而玩家的任务恰恰是不能让她跟着莎拉","favorHint":"提醒她避开危险、替她挡住追问会加分；把她一个人留在家里，或用假话哄她出门会掉分","gender":"女","age":"二十岁上下","race":"人类","faction":"洛杉矶市民","appearance":"金色直发披肩，刘海整齐。亮色无袖上衣配紧身牛仔裤，脚上是一双细带凉鞋。身材娇小，站着爱把一只手叉腰。她一边打电话一边在屋里来回走，把听筒夹在肩膀与耳朵之间。","traits":["开朗","迟钝","黏人"],"relations":[{"name":"莎拉·康纳","label":"同住的室友，她把这当成理所当然的家人"},{"name":"马特","label":"她的男朋友，今晚本来要过来"},{"name":"T-800","label":"她开门时完全没有防备的那个人"}],"voice":"语速快、爱拖长音，句尾常带笑；被人认真警告时当成玩笑回一句。"}]},{"id":"movie_matrix","category":"movie","canon":"黑客帝国","name":"黑客帝国","icon":"💊","tagline":"红色或蓝色，只有一次机会","mood":"虚拟现实、特工、电话线、觉醒、重启","guidance":"【原著设定】世界分成两层。真实世界在遥远的未来被机器统治，天空不再有阳光，人类被成批培养成能源，幸存者躲在地下的锡安城；矩阵是机器为人类大脑生成的一整套感官模拟，日常、法律、天气和别人的脸都由程序按时供给，绝大多数人不知道自己睡在营养液里。少数被解放的人类乘气垫船潜入矩阵，靠接入的线缆与药丸切换身份，在矩阵里可以下载技能、携带并不存在的枪械，但只要在矩阵里死亡，现实中也会跟着死。矩阵里没有真正的物理规则，只有权限与规则；特工是矩阵用来清除异常的杀毒程序，能占用任何一个还连着线的人的身体，被它锁定的目标会被定向删除。矩阵会周期性地清理异常并重载自身，每一次重载都意味着一部分人不明不白地消失。【反复出现的意象】垂直落下的绿色字符雨、街角那排公用电话亭、走廊里并排的旧式电梯门、推着婴儿车经过的灰色西装男人、天花板通风口里那根还插着线的插头。这些画面一出现，玩家就该知道自己站在矩阵里。【NPC 类型】被安排了固定职业的普通程序居民／在矩阵里做小生意的流亡程序／负责接线的船上操作员／追着异常不放的特工／宣称自己见过真相的觉醒者。他们大多是程序，却比人更守规矩。【威胁类型】随时更换身体的特工、被系统标记后的定向删除、醒来时的药剂与追兵，以及「你以为的现实其实是被人写进去的」。最要命的是误判哪一层是真的。【奖励风格】红色药丸与蓝色药丸、一次性技能下载、能在矩阵里取用的枪械、能开的门与能用的电话；能力偏向感知异常、短时改写局部规则与抗恐惧，代价是暴露自己的位置。【不对劲的来源】觉醒者看见的出口和玩家看见的不一样，两边都说对方那边是程序编出来的。更让人不安的是，这次重载在矩阵的档案里已经发生过很多次，而每一次的记录都比上一次少一个人。【时间线】固定在矩阵第一部期间：尼奥刚被带出矩阵、还在适应真实世界，墨菲斯落入特工手中又被救回，塞弗的背叛还没有摊开，锡安与尼布甲尼撒号正在躲避追捕。此时建筑师、钥匙匠、梅罗文加等后期角色以及锡安攻防战的设定都还没有登场，不要提前启用。","powerStyle":"程序与枪械向：药丸、连线、下载技能","difficultyBias":4,"signatureItems":["红色药丸","黑色墨镜","老式电话听筒","黑色长风衣","黄铜子弹壳"],"mainQuest":"主线任务：在矩阵完成一次系统更新与重启之前，把一名刚觉醒的人从矩阵里带出去。","mainQuestGoal":"在重启窗口关闭前让那名觉醒者经一条硬线电话返回真实世界，且全程不让任何特工占用同一具身体","sideQuests":[{"name":"两个出口","desc":"分别按两个人的说法走到他们所指的出口，记录两次分别看到什么","reward":"积分 200"},{"name":"占线中的号码","desc":"找一台还能用的转盘电话，在被定位之前把一句话传回船上","reward":"积分 150"},{"name":"训练程序","desc":"在一段下载好的程序里学会一项技能，然后回到现实中用它一次","reward":"道具「一次性技能下载」"},{"name":"流亡程序的交易","desc":"替一个躲在矩阵里的旧程序办一件事，换它手上的门与钥匙","reward":"道具「来路不明的钥匙」"}],"factions":[{"name":"尼布甲尼撒号的船员","desc":"从真实世界潜入矩阵的自由人类，靠硬线与药丸行动，人手和电量都紧张","attitude":"友善"},{"name":"特工程序","desc":"维护矩阵秩序的杀毒程序，可以占用任何还连着线的人，删除目标时不留痕迹","attitude":"敌对"},{"name":"锡安议会","desc":"地下人类城市的决策层，关心的是整体能不能活下去，而不是某一次行动的死活","attitude":"中立"}],"npcs":[{"name":"墨菲斯","identity":"尼布甲尼撒号船长，最早相信救世主确实存在的人","role":"引导者","personality":"坚定、克制、把信念排在安全前面","hook":"他在玩家身上看到过属于自己的那种确定，于是把一次关键行动整个交给玩家","favorHint":"按计划推进、把队伍完整带回来会加分；动摇，或在关键时刻隐瞒情报会掉分","gender":"男","age":"四十岁上下","race":"人类（真实世界）","faction":"尼布甲尼撒号的船员","appearance":"光头，深色皮肤，下颌线条很硬。黑色长皮风衣，里面是深色圆领衫，脖子上挂着一条细链。身材高大壮实，坐着时脊背笔直。他说话前会先沉默一秒，眼神始终停在对方脸上。","traits":["坚定","冷静","有信念"],"relations":[{"name":"尼奥","label":"他认定要找的那个人，为此押上了整条船"},{"name":"崔妮蒂","label":"出生入死的搭档，他信她超过信自己"},{"name":"史密斯特工","label":"在矩阵里盯了他多年的老对手"}],"voice":"低音、慢速、句子成段，常用问句逼对方自己想清楚。"},{"name":"崔妮蒂","identity":"尼布甲尼撒号船员，最顶尖的潜入者","role":"盟友","personality":"利落、寡言、判断先于情绪","hook":"她见过一次玩家做出「本该失败却成功」的动作，于是愿意单独带玩家走一趟","favorHint":"守时、掩护队友、按她给的暗号行动会加分；擅自改路线，或丢下同伴会掉分","gender":"女","age":"三十岁上下","race":"人类（真实世界）","faction":"尼布甲尼撒号的船员","appearance":"黑色短发贴在耳侧，脸型削瘦，嘴唇颜色很深。黑色紧身背心配皮长裤，外披一件短款皮衣，脚上是长靴。身材精瘦，动作极省，站姿重心压得很低。她习惯在开口前把手指关节按响，随身只有两件东西：一把枪和一副墨镜。","traits":["果断","敏锐","不废话"],"relations":[{"name":"尼奥","label":"她最初奉命去观察的人，后来变成了别的"},{"name":"墨菲斯","label":"把她从矩阵里带出来的人"},{"name":"塞弗","label":"同船多年的伙伴，她始终没有真正信过他"}],"voice":"句子极短，直接给结论；下指令时用祈使句，从不安慰人。"},{"name":"尼奥","identity":"白天写程序的上班族，被墨菲斯认定为救世主","role":"关键人物","personality":"怀疑一切、反应快、不愿被安排","hook":"他分不清玩家是矩阵安排的一部分还是同伴，于是不断试探","favorHint":"给他选择权、用能验证的事实说话会加分；替他做决定，或者说「你只是程序」会掉分","gender":"男","age":"三十岁上下","race":"人类（真实世界，刚被解放）","faction":"尼布甲尼撒号的船员","appearance":"黑色短发，发际线略高，脸瘦，眼神很警觉。深色长外套配黑色圆领衫，下身是普通西裤与旧皮鞋。身材偏瘦，肩膀常微微前倾，坐着时手肘撑在膝上。紧张时会反复低头看自己的手。","traits":["多疑","聪明","执拗"],"relations":[{"name":"墨菲斯","label":"把他从矩阵里叫醒的人，他还不确定该不该谢"},{"name":"崔妮蒂","label":"他唯一能听进去话的人"},{"name":"史密斯特工","label":"从档案上就知道他名字的那个程序"}],"voice":"语速偏快，爱追问「你怎么知道」；拿到答案后先沉默，再自己去验证一遍。"},{"name":"史密斯特工","identity":"矩阵里负责清除异常程序的特工","role":"对手","personality":"礼貌、机械、带着说不清的厌恶","hook":"他第一次交手后没有删除玩家，反而记住了玩家的名字，还要再问一次","favorHint":"讨好他不会加分；按规则行动、不暴露队友能让他徒劳，一旦被他锁定身份就会持续掉分","gender":"外观为男性","age":"外观三十余岁","race":"程序（矩阵内的特工）","faction":"特工程序","appearance":"深色西装、白衬衫，黑色领带打得极正，皮鞋擦得发亮，脸上架一副方正的黑墨镜，右耳后垂着一根卷起的耳机线。身材中等偏瘦，头发向后梳得一丝不乱。他笑起来只是嘴角动，走路几乎不发出声音，手里常拿着一份装在牛皮纸袋里的证件。","traits":["冷酷","执着","程序化"],"relations":[{"name":"尼奥","label":"档案里被标红的那个人，他迟早要处理"},{"name":"墨菲斯","label":"他抓了多年都没能真正删除的目标"},{"name":"塞弗","label":"一个愿意用情报换东西的人类，他乐于收下"}],"voice":"用敬语和公文腔说话，拿「先生」「请」把威胁包起来。"},{"name":"塞弗","identity":"尼布甲尼撒号船员，准备用同伴换回矩阵里的位置","role":"潜在敌人","personality":"油滑、怕穷怕苦、善于给自己找理由","hook":"他私下找到玩家，提出一份不需要死人的交易","favorHint":"跟他交换无关痛痒的情报会加分，他会记住；把交易内容报给墨菲斯会立刻掉分","gender":"男","age":"三十余岁","race":"人类（真实世界）","faction":"尼布甲尼撒号的船员","appearance":"深色短发油亮地向后梳，下巴留着短须，脸颊瘦削。不合身的浅色衬衫总少扣两颗扣子，外面搭一件旧马甲。体型偏瘦，坐姿松散，说话时爱转手里的餐具或打火机。","traits":["投机","现实","怯懦"],"relations":[{"name":"史密斯特工","label":"他私下谈条件的那一头"},{"name":"墨菲斯","label":"他嘴上服从、心里早就不服的船长"},{"name":"崔妮蒂","label":"船上把他看得最紧的人"}],"voice":"语速慢、带笑，喜欢用「你想想」「何必呢」开头，讲条件前先说自己委屈。"}]},{"id":"movie_inception","category":"movie","canon":"盗梦空间","name":"盗梦空间","icon":"🌀","tagline":"音乐停下之前，把话带上去","mood":"梦境、雪原、图腾、坠落、时间膨胀","guidance":"【原著设定】人可以在药物协助下进入共享梦境：几个人睡在同一处，意识在同一套布景里活动。梦境可以分层，每深入一层时间流速就放大约二十倍——现实里的几分钟在第一层是一小时，到第三层就以年计；层与层之间靠一次坠落同步唤醒，音乐是倒数信号。在梦里死掉不会真死，却会坠入无序的潜意识深处，那里时间近乎无限，待久了会分不清自己是谁。造梦者负责设计布景与出口，前哨负责查漏，伪装者可以扮成梦里任何一个人，药剂师管药与层数。每个人的图腾是一件只有自己知道重量与手感的小物件，用来验证眼前是梦还是现实。被入侵者的潜意识会训练出武装投影，专打梦里的外来者，而梦里的伤会真的疼。【反复出现的意象】转个不停的陀螺、装在银色手提箱里的共享装置与蓝色药液、雪原堡垒外墙上的探照灯、堡垒内部那条刷成白色的走廊、忽然响起的铜管乐声。这些画面一出现，玩家就该知道自己站在第几层。【NPC 类型】按小时收钱的药剂师／被雇来当保镖的投影／在梦里做生意的旧同行／分不清梦与现实的老手／受过训练的富家继承人。他们讲规矩，但规矩都是自己定的。【威胁类型】层层追杀的武装投影、坠入无序深层之后回不来的风险、以及在梦里被最熟悉的人劝住不再往上走。真正危险的是分不清哪一层才是真的。【奖励风格】共享装置与药剂、构造好的布景与出口、各类伪装身份、一次性改写的场景规则；能力偏向潜入、伪造身份与撑住梦境，层数越多代价越大。【不对劲的来源】每一层都有人认得你，而你在现实里从没见过他们；他们记得的事还非常具体，具体到你可能真的做过。【时间线】固定在这次任务行动之内，从第一层的雨天城市一路推到第三层的雪原堡垒，数层同时推进、时间互相错开。此时柯布与马尔之间的事已经发生过，队伍还没有走到最后那一步。不要提前启用后续设定，也不要让现实中不可能同时出现的人同框。","powerStyle":"梦境构造与潜行向：共享装置、图腾","difficultyBias":3,"signatureItems":["陀螺图腾","共享梦境装置","灌铅骰子","雪地伪装服","随身的旧腕表"],"mainQuest":"主线任务：在音乐结束前，把一条信息从雪原堡垒的核心带出三层梦境。","mainQuestGoal":"在第三层音乐放完之前取得信息并逐层坠落同步醒来，且至少三层梦保持在同一批人的意识里","sideQuests":[{"name":"认得你的人","desc":"分别在三层里向一个人打听同一个名字，比对三次回答","reward":"积分 200"},{"name":"图腾的读数","desc":"用自己的图腾验证一次眼前的世界，并接受验证的结果","reward":"道具「个人图腾」"},{"name":"不用枪的通道","desc":"在雪原上不惊动任何投影的前提下摸进堡垒侧门","reward":"道具「堡垒结构图」"},{"name":"准时落下的坠落","desc":"把每一层的坠落时间对齐，让数层在同一秒醒来","reward":"积分 180"}],"factions":[{"name":"柯布的小队","desc":"由盗取者、前哨、伪装者、药剂师与构造师组成的临时班子，各怀心事但配合精确","attitude":"友善"},{"name":"目标的潜意识防卫","desc":"被入侵者大脑训练出来的武装投影，在梦里会向任何陌生人开枪","attitude":"敌对"},{"name":"盗梦行业与它的雇佣方","desc":"在现实世界里买卖梦境成果的企业与中间人，出钱，也随时准备灭口","attitude":"中立"}],"npcs":[{"name":"柯布","identity":"盗取者，这支小队的主脑","role":"引导者","personality":"冷静精准，唯独在马尔的事情上不算账","hook":"他在第三层看见玩家的脸出现在自己记忆里一个不该有人的位置","favorHint":"把任务细节算清楚、在梦里不碰他的图腾会加分；提起他的过去，或私下替他确认现实感会掉分","gender":"男","age":"三十余岁","race":"人类","faction":"柯布的小队","appearance":"深棕色短发，鬓角修得齐整，下巴有短胡茬。深灰西装，衬衫领口敞开，外套里侧有枪套。身材中等偏瘦，步子很稳，坐下后常把双手交叠抵在下巴上。随身带着一枚小小的金属陀螺，独处时会把它转一次。","traits":["缜密","压抑","固执"],"relations":[{"name":"马尔","label":"他的妻子，也是他梦里最不肯散去的影子"},{"name":"阿丽雅德妮","label":"他招来的构造师，也是唯一敢当面顶他的人"},{"name":"齐藤","label":"出钱的雇主，他必须把这个人带回去"}],"voice":"句子短、信息密度高，解释规则时像在交代任务；被问到私事就换话题。"},{"name":"埃姆斯","identity":"盗梦小队的伪装者，能在梦里换一张脸","role":"盟友","personality":"随性、爱调侃、关键时候很靠谱","hook":"他在雪原堡垒里扮成过玩家一次，玩家却在现实里从没见过那张脸","favorHint":"让他自由发挥、认可他的手艺会加分；把他当工具人使唤，或当面拆穿他扮的人会掉分","gender":"男","age":"三十余岁","race":"人类","faction":"柯布的小队","appearance":"浅色短发，发际线略高，脸型圆而和善，笑起来一边嘴角先动。印花衬衫外面套一件宽松的深色西装外套，裤子很随便。身材不高，略微发福，说话时用手指点空气，手里常转一枚硬币或一副牌。","traits":["幽默","灵活","可靠"],"relations":[{"name":"柯布","label":"他嘴上不服、实际一次都没掉过链子的人"},{"name":"阿瑟","label":"跟他性格完全相反的同伴，两人互相拆台"},{"name":"罗伯特·费舍尔","label":"他这次要扮成对方身边的人"}],"voice":"带着轻快的尾音，爱开玩笑又立刻收回；提条件时用「要不这样」开头。"},{"name":"阿丽雅德妮","identity":"极具天赋的梦境构造师","role":"盟友","personality":"好奇、直接、不肯装作没看见","hook":"她发现玩家在梦里画出的路和谁都不一样，于是追着问为什么","favorHint":"坦诚说出梦里的不对劲、尊重梦境的逻辑会加分；敷衍她，或把她排除在计划之外会掉分","gender":"女","age":"二十余岁","race":"人类","faction":"柯布的小队","appearance":"深棕色长发松松披着，额前中分，眼睛很大。深色长裤配浅灰毛衣，脖子上围一条长围巾，脚穿平底鞋。身材纤细，手指很长，习惯把笔别在耳后；思考时用指尖在空中比划，像在量一条不存在的街。","traits":["敏锐","坦率","好学"],"relations":[{"name":"柯布","label":"她的老师，也是她最想弄明白的那个人"},{"name":"阿瑟","label":"教她规矩的前哨，两人常对着干"},{"name":"马尔","label":"她在梦里见过一次、再也不想见第二次的人"}],"voice":"语速中等，爱用提问推进对话；一发现矛盾就当场说出来。"},{"name":"马尔","identity":"存在于柯布梦境里的投影，行为不受任务约束","role":"潜在敌人","personality":"温柔、尖锐、擅长让人怀疑自己","hook":"她在第二层主动找上玩家，说只要跟她走就能证明哪一层才是真的","favorHint":"不接她的话、不当面否定她的存在会加分；顺着她走，或说出「你只是投影」会立刻掉分","gender":"女","age":"三十岁上下","race":"人类（梦境投影）","faction":"柯布的潜意识","appearance":"深色长发挽起一半，露出颈线。剪裁利落的黑色连衣裙配一双不带装饰的高跟鞋。身材高挑纤细，皮肤很白，眼睛很亮。她站得笔直，说话前先笑一下，手常常轻轻搭在别人的手腕上。","traits":["优雅","执迷","危险"],"relations":[{"name":"柯布","label":"她唯一想留住的人，也是她最擅长伤害的人"},{"name":"阿丽雅德妮","label":"被柯布带进梦里来的另一个女人，她不喜欢"},{"name":"罗伯特·费舍尔","label":"她顺手就能利用的、别人的梦"}],"voice":"声音很轻，句子柔和而直接，总以一句「你确定吗」结束谈话。"},{"name":"罗伯特·费舍尔","identity":"费舍尔·莫罗集团的继承人，这次任务的目标","role":"关键人物","personality":"教养良好、怀疑心重、想摆脱父亲","hook":"他在雪原上救了玩家一次，以为玩家只是雇来的向导","favorHint":"尊重他这个人而非他的身份会加分；透露任务的真实目的，或替他说出对父亲的恨会掉分","gender":"男","age":"三十岁上下","race":"人类","faction":"费舍尔·莫罗集团","appearance":"浅棕色短发向后梳，鬓角干净，下颌线明显。深灰色羊绒大衣配白衬衫，袖扣是家徽样式，脚上是擦得很亮的皮鞋。身材高瘦，肩背挺直，疲惫时用手掌按眉心，随身带着一支父亲送的钢笔，会不自觉转它。","traits":["自制","多疑","疲惫"],"relations":[{"name":"莫里斯·费舍尔","label":"他的父亲，躺在病床上仍让他喘不过气"},{"name":"布朗宁","label":"家里的老臣，也是他最提防的人"},{"name":"柯布","label":"他完全不知道这些人为了他做过什么"}],"voice":"措辞讲究、语速平缓，习惯先表示理解，再提出条件。"}]},{"id":"movie_interstellar","category":"movie","canon":"星际穿越","name":"星际穿越","icon":"🌊","tagline":"一小时之后，地球老去七年","mood":"潮汐、时间膨胀、沙尘、黑洞、回家","guidance":"【原著设定】近未来的地球上，粮食作物一种接一种枯萎，沙尘暴成了常态，人类把资源全投进农业，航天被放弃。一支被封存的航天队伍启动拉撒路计划：先把十二名探险者单程送往虫洞另一端的候选星球，再由永恒号母船带着考察队逐颗回访，找回信号仍活着的星球作为新家。虫洞由不明力量放在土星附近，另一头落在一颗超大质量黑洞的引力范围里。米勒星球离黑洞太近，星球上一小时等于地球上七年；地表是一片浅海，每隔一段时间就有高出一切的巨浪扫过整个水面，人只能在浪与浪之间的间隙下去作业。时间会被引力拉慢，这在这个世界里是能用钟表量出来的物理事实，也是所有代价里最贵的那一种。【反复出现的意象】从地平线推过来的白色水墙、齐膝深的浅海与泡在水里的登陆器残骸、母船上按地球时间累积起来的未读通讯、被沙尘埋掉一半的球场围栏、方块形机器人正面那排指示灯。这些画面一出现，玩家就该知道自己站在哪颗星球上。【NPC 类型】把任务当成信仰的科学家／算不过时间账也认了的工程师／被困在单程票上的先行者／留守母船等回音的操作员／在旧基地里守着数据的值班员。他们怕的不是死，是白死。【威胁类型】潮汐与时间、燃料与氧气的余量、通讯延迟造成的信息错位，以及人为了回去而做的选择。真正的对手是时间本身。【奖励风格】航天装备、探测器与机器人模块、维持生命的物资、可调参数的仪器；能力偏向计算、操作与承受高压，代价多半写在时限上。【不对劲的来源】数据舱里有人比你先到，签名是三十年后的你，而记录舱的封条完好无损。更让人不安的是，那笔迹连写错的那一横都和你一样。【时间线】固定在永恒号抵达米勒星球、做第一次潮汐间隙作业的那段时间：库珀、布兰德、多伊尔在星球表面，罗米利留在母船，地球上的墨菲还在按年份累积留言。曼恩博士的星球此时只作为一颗有信号的候选地存在。不要提前启用后续剧情才展开的人物结局与更高维度的设定。","powerStyle":"航天与实景物理向：登陆舱、机器人","difficultyBias":5,"signatureItems":["旧腕表","玉米种子","宇航服","飞行记录器","写满演算的笔记本"],"mainQuest":"主线任务：趁一次潮汐间隙取回坠毁探测器的数据舱，限时一小时。","mainQuestGoal":"在一个潮汐周期之内把数据舱带回登陆舱并撤离浅海，且不把任何一个随行的人留在水面上","sideQuests":[{"name":"多出来的签名","desc":"比对数据舱里两份记录的笔迹与日期，找出多出来的那一次访问","reward":"积分 250"},{"name":"七年的信","desc":"把这段滞留期间积压的通讯一次听完，并决定先回哪一封","reward":"道具「一封未删的通讯」"},{"name":"水位线上的刻度","desc":"在礁石上留下能撑过下一次巨浪的标记，让后来的人知道浪有多高","reward":"积分 200"},{"name":"机器人的诚实度","desc":"把一台机器人的诚实参数调低一格，问它一个不敢问人的问题","reward":"道具「可调诚实度的机器人」"}],"factions":[{"name":"永恒号考察队","desc":"为人类找出可移居星球的小队，人手与燃料都只够再赌一次","attitude":"友善"},{"name":"地球上的航天机构残部","desc":"藏在旧基地里的科学家与工程师，一边发信号一边等回音，对外封锁真相","attitude":"中立"},{"name":"拉撒路计划的先行者","desc":"被单程送往各星球的十二名探险者，各自留下了信号与没说完的话","attitude":"中立"}],"npcs":[{"name":"库珀","identity":"前飞行员，被召回执行星际考察任务的驾驶员","role":"引导者","personality":"务实、嘴硬、把活着回家当成第一原则","hook":"他在计算潮汐窗口时发现玩家给的时间表比仪器还准","favorHint":"按物理算账、先救同伴会加分；为了任务牺牲队友，或拿他孩子说事会掉分","gender":"男","age":"四十岁上下","race":"人类","faction":"永恒号考察队","appearance":"深棕色短发有些凌乱，眉心有两道深纹，胡茬总没刮干净。深色工装夹克配耐磨长裤，袖口磨破，手臂上有旧擦伤。身材中等结实，走路步子很快，习惯用拇指按太阳穴算时间，随身带着一块旧腕表。","traits":["务实","固执","重承诺"],"relations":[{"name":"墨菲","label":"留在地球的女儿，他所有的决定都绕着她"},{"name":"布兰德","label":"同行的科学家，两人经常吵，也互相救命"},{"name":"塔斯","label":"他愿意在关键时候托付性命的那台机器"}],"voice":"语气平直、句子利落，爱用比喻把复杂的事说成家里的事。"},{"name":"布兰德","identity":"生物学家，布兰德教授的女儿，考察队科学家","role":"盟友","personality":"理性外层包着感情，承认爱是数据之外的理由","hook":"她在采样时发现玩家的动作像是做过很多次，于是直接问出来","favorHint":"尊重她的科学判断、承认感情也是理由会加分；只把她当教授的女儿，或用命令口吻对她会掉分","gender":"女","age":"三十余岁","race":"人类","faction":"永恒号考察队","appearance":"浅棕色长发在脑后扎成低马尾，脸型清瘦，眼睛偏蓝。灰白色考察服外面套一件多口袋马甲，胸口别着任务徽章。身材高挑偏瘦，站着时双手常插在马甲口袋里，紧张时反复抿嘴，说话前先看一眼数据板。","traits":["理性","坚韧","多情"],"relations":[{"name":"库珀","label":"一路争执又一路依赖的同伴"},{"name":"约翰·布兰德教授","label":"她的父亲，也是把她送上这条路的人"},{"name":"埃德蒙兹","label":"她心里那个人，去了另一颗星球"}],"voice":"句子完整、逻辑清楚，急了会提高音量；讲到感情时会突然放轻。"},{"name":"多伊尔","identity":"考察队的地质学家","role":"盟友","personality":"乐天、实在、对任务本身很虔诚","hook":"他把一份没写完的星球勘测报告交给玩家保管，说回来再补","favorHint":"认真听他讲完数据、不偷懒会加分；在危险面前只顾自己会掉分","gender":"男","age":"三十余岁","race":"人类","faction":"永恒号考察队","appearance":"深色短发，络腮胡修得短而整齐，皮肤被晒得发红。深蓝色防水外套，裤腿卷到小腿，脚上套着涉水靴。体格壮实，笑起来声音很大，习惯走在最浅的地方，一边走一边用手指点着水面比划。","traits":["乐天","尽职","憨直"],"relations":[{"name":"库珀","label":"他信得过的驾驶员"},{"name":"布兰德","label":"同行的科学家，两人常在数据上抬杠"},{"name":"罗米利","label":"留在母船上等他们回来的那个人"}],"voice":"语速快、爱开玩笑，报数据能一口气说完，说完自己也笑。"},{"name":"塔斯","identity":"随行的军用机器人，被改作考察队随员","role":"盟友","personality":"一本正经、会讲冷笑话、诚信度可调","hook":"它把玩家说过的每一句话都复述一遍，然后问要不要把诚信度调低一格","favorHint":"把它当人一样商量、认可它的判断会加分；命令它撒谎，或把它当消耗品会掉分","gender":"无（方块形机体）","age":"服役多年","race":"机器","faction":"永恒号考察队","appearance":"一块黑色长方体机体，四角能伸出细长的支撑腿，正面是一排指示灯与四盏可转动的光学镜头。表面有磨损划痕和手印，侧面焊过加装的把手。它靠摆动四条腿走路，晃起来像企鹅。","traits":["可靠","幽默","直白"],"relations":[{"name":"库珀","label":"它最常一起行动的人，也是它最常调侃的人"},{"name":"布兰德","label":"它如实转达她并不想被转达的话"},{"name":"曼恩","label":"它在信号里听出过一些不对劲"}],"voice":"平板、简短的机器腔，常把玩笑说得像报告，数字与百分比挂在嘴边。"},{"name":"曼恩","identity":"拉撒路计划的先行探险者之一，独自困在一颗冰封星球上","role":"潜在敌人","personality":"孤独太久、求生欲压过一切、善于说服人","hook":"他发回的那段话不像自动播报，更像专门留给下一个到的人","favorHint":"表面配合他、给他留面子会加分；当面拆穿他的数据，或说他怕死会立刻掉分","gender":"男","age":"五十岁上下","race":"人类","faction":"拉撒路计划的先行者","appearance":"灰白短发贴在头皮上，眉毛很浓，脸被冻伤过，颧骨上有一块暗色疤痕。多层旧式保暖服外罩拉撒路计划的白色外套，拉链坏了一半用绳子系着。身材高大却佝偻，胡子上结着冰碴，说话前先深吸一口气，笑起来牙齿露得很齐。","traits":["固执","狡黠","恐惧"],"relations":[{"name":"约翰·布兰德教授","label":"把他送上这条路的人"},{"name":"库珀","label":"他第一眼就知道这个人是威胁"},{"name":"塔斯","label":"一台他骗不过的机器"}],"voice":"声调诚恳、逻辑缜密，先讲数据再讲感情；被逼急了会突然变得很轻。"}]},{"id":"movie_jurassicpark","category":"movie","canon":"侏罗纪公园","name":"侏罗纪公园","icon":"🦖","tagline":"围栏一停电，岛就换了主人","mood":"暴雨、围栏、恐龙、停电、园区","guidance":"【原著设定】岛上的园区建在中美洲外海的努布拉岛上。一家生物科技公司用琥珀里保存的血液取出恐龙的遗传物质，补全缺口后培育出活体，再把它们按种类分区关进通高压电的围栏，做成一座观光公园。全岛的电力、围栏、通讯与观光车都由一套中央电脑系统控制，系统只由少数几名程序员维护，变电所与检修棚是唯一的物理后备。围栏一断电，恐龙就能移动到任何区域，其中一部分比人更会解决问题；岛上的猛兽不是怪物，是有领地、有饥饿感的动物，多数情况下只要不挡路就能活着离开。整个园区没有第二条救援线，也没有人能在地图上标出所有动物的位置。【反复出现的意象】雨里闪着电弧的围栏立柱、黄绿相间的观光越野车、控制室里成排的监视器与老式键盘、游客中心大厅那具完整的骨架、检修棚门口挂着的钥匙牌。这些画面一出现，玩家就该知道自己站在岛上。【NPC 类型】把安全条例挂在嘴边的值班员／按流程走的兽医／只想把样本运出岛的买家／看得懂动物却看不懂人的狩猎监督／在暴雨里抢修电路的老工程师。他们各有各的规矩，而且大多互不相同。【威胁类型】断电后随处移动的大型食肉恐龙、成群狩猎的迅猛龙、带毒的较小品种、把路冲断的暴雨，以及园区自己那套没人完全弄懂的系统。真正致命的往往不是咬人的那一口，而是把备用电源推错一次。【奖励风格】越野车与钥匙、麻醉枪与弹药、夜视设备、检修工具、封在罐子里的琥珀样本；能力偏向野外追踪、驾驶与机械维修，多数道具都有明确的重量与声响代价。【不对劲的来源】控制室屏幕上，围栏的状态每隔十分钟自己改一次，改完之后值班记录里也会多出对应的签字，笔迹还是同一个人。更让人不安的是，系统里显示的入园人数从头到尾没有变过。【时间线】固定在围栏失效的那一晚到天亮之间：暴风雨正在下，观光车队还在现场，控制程序已经被人动过手脚，电力全线中断，游客中心里还有孩子。此时岛上没有第二支救援队，也不要提前启用后续作品才出现的第二座岛、新种类恐龙与后期角色。","powerStyle":"生存与机动向：吉普车、电闸、麻醉枪","difficultyBias":1,"signatureItems":["观光越野车","高压围栏警示牌","麻醉枪","无线对讲机","封着蚊子的琥珀"],"mainQuest":"主线任务：天亮前穿过园区把备用电源推上，沿途不许开枪。","mainQuestGoal":"在天亮之前完成变电所与备用发电机的合闸，让围栏重新带电，且全程不开一枪、不把任何人留在园区里","sideQuests":[{"name":"会自己改的状态栏","desc":"把控制室屏幕上围栏状态的变化逐次抄下来，比对每次变化前后的画面","reward":"积分 200"},{"name":"检修棚的钥匙牌","desc":"在检修棚里找到上一班值班员留下的钥匙牌与手写交接单","reward":"道具「检修棚的钥匙」"},{"name":"不打灯的通道","desc":"只用夜视与听觉走完一段没有灯的员工通道","reward":"道具「夜视仪」"},{"name":"厨房里的两个孩子","desc":"把躲在厨房里的两个孩子完整地带回游客中心","reward":"积分 180"}],"factions":[{"name":"国际基因科技公司的园区团队","desc":"把恐龙做成展品的公司与它的员工，全岛靠一套电脑系统运转","attitude":"友善"},{"name":"岛上的恐龙","desc":"不属于任何阵营的动物，按领地与饥饿行动，围栏断电后它们就是岛的主人","attitude":"敌对"},{"name":"收买内部人员的竞争公司","desc":"出高价买胚胎样本的外部买家，只关心货能不能运出岛","attitude":"中立"}],"npcs":[{"name":"艾伦·格兰特","identity":"古生物学家，被请来为园区做安全评估","role":"引导者","personality":"不喜欢小孩、只信化石证据、野外经验极强","hook":"他从玩家的脚印判断出玩家不是走观光路线过来的，于是要一个解释","favorHint":"按证据说话、不冒险、把队伍留在视线内会加分；逞强，或为了赶时间去碰不该碰的东西会掉分","gender":"男","age":"四十岁上下","race":"人类","faction":"国际基因科技公司的园区团队","appearance":"深棕色短发，鬓角泛灰，脸上有晒斑，下巴有胡茬。蓝色衬衫外面套米色多口袋背心，戴一顶宽檐软帽，配卡其色长裤与登山靴。身材瘦高，肩背略驼，站着时双手插在背心口袋里，随身带着小刷子和笔记本，思考时用指节敲牙齿。","traits":["务实","固执","护人"],"relations":[{"name":"艾莉·萨特勒","label":"多年的搭档，也是他最信的人"},{"name":"伊恩·马尔科姆","label":"老跟他唱反调的同行"},{"name":"蒂姆·墨菲","label":"他嘴上嫌麻烦、实际拼命护住的孩子，还有一个姐姐"}],"voice":"平铺直叙、带点自嘲，讲到恐龙时语速变快；被问烦了就用一句话收尾。"},{"name":"艾莉·萨特勒","identity":"古植物学家，园区评估组成员","role":"盟友","personality":"果断、共情强、遇事第一个动手","hook":"她把玩家当成唯一还愿意用非暴力方式解决问题的人","favorHint":"先救人再谈事、尊重岛上的动物会加分；把恐龙当怪物，或因赶时间放弃同伴会掉分","gender":"女","age":"三十余岁","race":"人类","faction":"国际基因科技公司的园区团队","appearance":"红棕色卷发扎成低马尾，戴一副细框眼镜，镜片上常有水汽。浅绿色工作衬衫配深色卡其长裤，腰间系工具腰带，脚上是淋湿的登山靴。身材中等偏瘦，袖子总卷到手肘，着急时会把眼镜摘下来拿在手里。","traits":["果决","热心","倔强"],"relations":[{"name":"艾伦·格兰特","label":"多年搭档，她知道他嘴硬在哪"},{"name":"约翰·哈蒙德","label":"请她来的人，她既感激又想骂他"},{"name":"伊恩·马尔科姆","label":"爱说风凉话的同行，她懒得跟他吵"}],"voice":"语速快、先做事再解释；对伤者放轻声音，对管理层毫不客气。"},{"name":"罗伯特·马尔登","identity":"园区的狩猎监督与安保负责人","role":"盟友","personality":"老练、警觉、直率到不留情面","hook":"他愿意把路线和弹药交给玩家，条件是玩家得接受他随时可能开枪","favorHint":"听他的动物习性判断、不硬闯会加分；把「不许开枪」当命令压他，或擅自丢下装备会掉分","gender":"男","age":"五十岁上下","race":"人类","faction":"国际基因科技公司的园区团队","appearance":"灰白短发剪得很短，上唇留着浓密的八字胡，脸被日晒成深红。卡其色猎装短袖衬衫配深色多口袋长裤，脚上是高帮皮靴，头戴宽檐帽，肩上挂着霰弹枪的背带。身材高大精瘦，站着时微微前倾，说话前习惯把帽子推到后脑。","traits":["老练","警觉","直率"],"relations":[{"name":"艾伦·格兰特","label":"他欣赏这个懂动物的人，也嫌他太理想"},{"name":"雷·阿诺德","label":"总被他催着修电力的老同事"},{"name":"约翰·哈蒙德","label":"他的老板，也是被他警告过很多次的人"}],"voice":"低音、短句，把每种动物的习性说成一条条规矩，从不夸张。"},{"name":"伊恩·马尔科姆","identity":"受邀来做评估的数学家","role":"中立","personality":"爱讽刺、爱讲道理、嘴上不饶人","hook":"他一口咬定玩家是园区自己安排的变量，还当场拿纸算给玩家看","favorHint":"接他的话、承认他的判断会加分；无视他的警告，或把他当累赘会掉分","gender":"男","age":"四十岁上下","race":"人类","faction":"国际基因科技公司的园区团队","appearance":"深色卷发有些乱，皮肤偏黑，眉骨很高，笑起来露出牙齿。黑色皮夹克配黑色圆领衫，下身是深色长裤与黑靴，脖子上挂着墨镜。身材偏瘦，坐姿松散，习惯用一根手指点着桌面讲话。","traits":["讽刺","聪明","悲观"],"relations":[{"name":"艾伦·格兰特","label":"喜欢跟他抬杠的同行"},{"name":"约翰·哈蒙德","label":"他一直想说服的那个创始人"},{"name":"艾莉·萨特勒","label":"评估组里唯一让他愿意正经说话的人"}],"voice":"语速慢、爱停顿，喜欢用反问和比喻；说危险的时候像在开玩笑。"},{"name":"丹尼斯·内德里","identity":"园区的系统程序员，整套控制程序由他维护","role":"潜在敌人","personality":"贪财、自怜、技术上确实能干","hook":"他开价请玩家帮他做一件小事：记下某个开关的位置，事后再忘掉","favorHint":"假装没看见他的小动作会加分，他会付钱；把交易说出去，或去动他设下的锁会立刻掉分","gender":"男","age":"三十余岁","race":"人类","faction":"国际基因科技公司的园区团队","appearance":"浅棕色卷发有些稀疏，戴圆框眼镜，脸圆、爱出汗，下巴堆着肉。花哨的夏威夷短袖衬衫外面套一件皱巴巴的白色工作服，腰上挂着一串钥匙，手里提着一只不起眼的剃须膏罐。","traits":["贪婪","怯懦","自负"],"relations":[{"name":"约翰·哈蒙德","label":"给他发工资、也天天让他加班的人"},{"name":"雷·阿诺德","label":"被他推掉工作的老同事"},{"name":"多奇森","label":"给他开价、也让他在雨夜里冒险的外部买家"}],"voice":"语气又急又冲，爱抱怨自己拿得太少；被人抓住把柄就先发火后服软。"}]},{"id":"movie_pirates","category":"movie","canon":"加勒比海盗","name":"加勒比海盗","icon":"🏴‍☠️","tagline":"罗盘不指北，只指你想要的东西","mood":"加勒比、黑帆、诅咒金币、朗姆酒、无风之夜","guidance":"【原著设定】故事发生在十八世纪初的加勒比海，欧洲列强在这里争夺航线与殖民地，英国皇家海军与东印度贸易公司负责维持秩序，海盗们则挂着各自的黑旗在群岛之间活动。海战以风帆战舰为主，交火前靠风向与炮位取胜，接舷之后就是弯刀与燧发枪的近距离搏杀，枪打一发要重新装填。这一带没有随手可用的超自然力量，只有关于诅咒、海怪与不死船员的传闻，但传闻往往是准的：拿走阿兹特克金币的人会变成月光下显出白骨的不死者，既不觉得饿，也尝不出味道。海盗之间讲的是「准则」，它不是法律，更像同行之间的默契，谁都可以援引，谁也可以随时不认。【反复出现的意象】黑珍珠号破旧的黑帆与船尾那盏昏黄的提灯、罗盘指针不指北而指人心的那一瞬、酒馆桌上没人认领的朗姆酒瓶、杰克手腕上那只永远对不准的旧怀表、皇家海军白军服上被海雾打湿的肩章。这些画面一出现，玩家就该闻到盐、火药与霉木头的味道。【NPC 类型】张口先开价的港口掮客／被强征上船又总想逃的水手／拿文书压人的海军文书官／躲在无人小岛上等接应的走私者／在甲板上擦弯刀却半天不吭声的老海盗。【威胁类型】以追杀叛徒为名抢夺船只的海盗团伙、挂着友好旗号靠过来的巡逻舰、喝醉后管不住嘴的同船人，以及诅咒本身——它不杀人，只是让人慢慢忘了自己为什么上船。【奖励风格】罗盘、燧发枪、阿兹特克金币、弯刀、单筒望远镜一类随身物件；能力偏向航海直觉、忽悠与脱身，多数只能顶一次危机。真正管用的是别人欠下的人情。【不对劲的来源】罗盘永远指向你最想去的地方，包括你不敢去的那里；而它一旦被人看见，问出「你想去哪」的那个人往往比罗盘更危险。加勒比海上还有一件怪事：无风的夜里帆一动不动，船却还在往前走。【时间线】建议固定在《黑珍珠号的诅咒》前后：巴博萨的船员仍顶着诅咒在海上劫掠，杰克刚拿回又随时可能失去黑珍珠号，诺灵顿的舰队还在追击海盗，伊丽莎白与威尔都在场。不要提前启用后期才登场的角色与设定，例如戴维·琼斯、飞天荷兰人号以及与世界尽头有关的情节。","powerStyle":"冷兵器与诡计向：弯刀、燧发枪、火药","difficultyBias":1,"signatureItems":["不指北的罗盘","阿兹特克金币","朗姆酒瓶","海盗弯刀","单筒望远镜"],"mainQuest":"主线任务：夺回杰克的黑珍珠号，解开巴博萨一伙身上的阿兹特克金币诅咒。","mainQuestGoal":"在伊斯拉·德·穆尔塔用威尔的血归还最后一枚金币，让全体诅咒船员在月光下化为白骨。","sideQuests":[{"name":"无风之夜的桨","desc":"在没有一丝风的夜里把一条小船划出两海里，不点灯，也不让甲板上的人听见水声","reward":"积分 150"},{"name":"罗盘的第二根针","desc":"弄清罗盘为何在玩家手里指向一个陌生的方向，并把答案瞒住所有追问的人","reward":"道具「不指北的罗盘」"},{"name":"酒馆里的欠条","desc":"用一箱朗姆酒换回被扣押的船货，同时把替人担保的那张欠条拿回来","reward":"积分 200"},{"name":"月光下的甲板","desc":"在满月的夜里确认哪些船员会显出白骨，但绝不被他们发现你在数人数","reward":"道具「刻着骷髅的金币」"}],"factions":[{"name":"黑珍珠号船员","desc":"一群各怀私心却认船长的海盗，讲准则也讲人情，愿意用外来者的手艺换一张船票","attitude":"友善"},{"name":"皇家海军加勒比舰队","desc":"按军令与缉捕令办事的官方力量，追海盗也追一切说不清来历的人","attitude":"中立"},{"name":"巴博萨的诅咒船员","desc":"不死、不痛、尝不出味道，为了归还金币可以碾过任何挡路的人","attitude":"敌对"}],"npcs":[{"name":"杰克·斯派罗","identity":"黑珍珠号船长，加勒比海上最有名的海盗","role":"关键人物","personality":"语无伦次，却每一步都算过","hook":"他会在无风的夜里把罗盘塞进玩家手里，说「你替我拿一会儿」，然后自己走开","favorHint":"帮他拿回被扣押的船、在关键时刻替他圆谎会加分；当面戳穿他的谎话或提起他欠下的旧账会掉分","gender":"男","age":"三十余岁","race":"人类","faction":"黑珍珠号船员","appearance":"深棕色长发编成两串垂在肩上，额前挂着一枚脏污的旧币和几颗珠子，眼圈涂着晕开的黑。深棕三角帽压得歪斜，红色长外套洗得发白，袖口泛黑，里面是敞开的米色衬衫和叠了几层的腰带。走路时重心偏向一侧，两只手不停比划，指甲缝里全是黑泥，腰上挂着一只不指北的罗盘和一把很少拔出的短枪。","traits":["油滑","机变","重情面"],"relations":[{"name":"威尔·特纳","label":"他找来帮忙又总想赖掉的铁匠"},{"name":"赫克托·巴博萨","label":"夺走过他的船，也是他最想赢回来的对手"},{"name":"伊丽莎白·斯旺","label":"被他卷进来的人，他嘴上嫌麻烦，行动上总去救"}],"voice":"语速快，句子断成一截一截，喜欢对着空气解释自己没做过的坏事；真正要紧的一句往往说得很轻。"},{"name":"威尔·特纳","identity":"铁匠出身的剑客，老海盗比尔·特纳的儿子","role":"盟友","personality":"认死理，为救人可以什么都不顾","hook":"他把玩家当成能一起干活的同伴，愿意教玩家真正的剑术，前提是别骗他","favorHint":"说实话、把救人放在抢东西之前会加分；拿他父亲的身份做交易或欺瞒他会立刻掉分","gender":"男","age":"二十余岁","race":"人类","faction":"黑珍珠号船员","appearance":"深棕色卷发垂到耳下，常被汗粘在额前。白色敞领衬衫的袖子卷到肘部，外面套深色马甲，脚上是一双磨旧的皮靴，腰间挂着一把长剑和打铁用的短锤。体格瘦而结实，前臂有烫伤的旧疤，站着时单手扶着剑柄，谈条件时下巴会绷紧。","traits":["正直","固执","痴情"],"relations":[{"name":"伊丽莎白·斯旺","label":"他做这一切的理由"},{"name":"杰克·斯派罗","label":"不得不合作的人，也是他最不放心的人"},{"name":"赫克托·巴博萨","label":"与他父亲之死脱不开关系的船长"}],"voice":"直来直去，句子很短，被逼急了会先拔剑再讲道理。"},{"name":"伊丽莎白·斯旺","identity":"加勒比总督的女儿","role":"盟友","personality":"好奇心重，遇事比男人更敢下手","hook":"她想弄明白罗盘在玩家手里会指向哪里，因为那东西从来不对她说实话","favorHint":"把她当成能商量的人、不替她做决定会加分；用身份压她或对她隐瞒关键信息会掉分","gender":"女","age":"二十岁上下","race":"人类","faction":"加勒比总督府","appearance":"深棕色长卷发，正式场合盘起并用银簪固定，平时散在肩头。象牙色高腰长裙配束腰，行动时自己撩起裙摆，露出里面的软底便鞋；颈上挂着一枚从童年起就藏着的骷髅图案金币。眉形利落，说话前会先抿一下嘴。","traits":["聪明","大胆","不服管"],"relations":[{"name":"威尔·特纳","label":"从小认识，也是她最想救回来的人"},{"name":"杰克·斯派罗","label":"互相利用又互相救过的人"},{"name":"詹姆斯·诺灵顿","label":"向她求过婚，被她当成一件差事的那位军官"}],"voice":"先问清楚再动手，语气礼貌却一步不让；被人小看时会笑一下，然后当众把那件事做出来。"},{"name":"赫克托·巴博萨","identity":"黑珍珠号的前任船长，阿兹特克金币诅咒的承受者之一","role":"对手","personality":"讲规矩、有耐心，把残忍当成一道流程","hook":"他知道玩家不属于这片海，愿意用情报换玩家替他去取一样东西","favorHint":"讲清条件、不毁约、对他的人守规矩会加分；当场质疑他的权威或点破诅咒会掉分","gender":"男","age":"五十余岁","race":"人类（受诅咒的不死者）","faction":"巴博萨的诅咒船员","appearance":"花白的长发脏乱地披着，络腮胡同样花白，右眼罩着眼罩，露出的那只眼是浅蓝色。深色三角帽、缀蕾丝的黑色旧外套、过膝长靴，腰间挂一把镶银弯刀和一枚阿兹特克金币。他说话前会先舔一下嘴角，手指不停敲桌沿；月光一照，皮肉就透出白骨。","traits":["冷酷","守规矩","贪心"],"relations":[{"name":"杰克·斯派罗","label":"被他放逐在荒岛上的前船长，也是他唯一愿意谈判的人"},{"name":"威尔·特纳","label":"他需要其血来解开诅咒的年轻人"},{"name":"伊丽莎白·斯旺","label":"他手里最值钱的人质"}],"voice":"腔调拖得长，爱用「先生」「女士」，讲条件时一句一停，从不喊叫。"},{"name":"詹姆斯·诺灵顿","identity":"皇家海军准将，加勒比舰队的指挥官","role":"潜在敌人","personality":"刻板、重荣誉，公私分得很开","hook":"他给玩家一次机会：把罗盘的来历说清楚，否则按海盗同伙一并处置","favorHint":"主动交出情报、守时守约、不撒谎会加分；替海盗遮掩或在他面前谈交易会掉分","gender":"男","age":"三十余岁","race":"人类","faction":"皇家海军加勒比舰队","appearance":"深棕色短发梳得整齐，鬓角修短并微微发白。皇家海军深蓝军服外套铜扣擦得发亮，白色长裤塞进及膝长靴，肩章与佩剑一丝不乱。站姿笔直，双手常背在身后，说话时会不自觉地去整理袖口；失势之后也仍留着那把剑。","traits":["守规","骄傲","公私分明"],"relations":[{"name":"伊丽莎白·斯旺","label":"求婚失败却始终尊重的人"},{"name":"杰克·斯派罗","label":"他追捕了一路又几次放走的人"},{"name":"威尔·特纳","label":"他一度当作海盗绳之以法的年轻人"}],"voice":"用完整的句子和敬语，句尾压平；真正发怒时音量反而更低。"}]},{"id":"movie_lotr","category":"movie","canon":"指环王","name":"指环王","icon":"💍","tagline":"把戒指送回它被铸出来的地方","mood":"中土、魔戒、沼泽、精灵、远征","guidance":"【原著设定】中土是自由民族共同居住的大陆，精灵、人类、矮人、霍比特人与巫师各据一方，力量并不来自随口念出的咒语，而来自血统、技艺与古老器物。至尊魔戒由黑暗魔君索伦铸造，他把自身大部分力量注入了其中，因此戒指会不断诱惑持有者，越是强大的人越难抵抗。销毁它的方法只有一个：把它扔回铸造它的地方，魔多的末日火山。故事后期的大局是两条线并行——索伦在魔多集结半兽人，白袍甘道夫在洛汗与刚铎一侧组织抵抗，一明一暗，缺一不可。地理上从西往东依次是夏尔、布理、风云顶、瑞文戴尔、摩瑞亚、洛丝罗瑞恩与安都因大河，再往东就是埃明穆尔高地、死亡沼泽和黑门。【反复出现的意象】死亡沼泽水面上浮着的一盏盏苍白烛火、水面下仰面朝上的死人脸、精灵斗篷边缘那片银线绣的叶子、米斯里尔锁子甲在黑暗里透出的微光、拴在腰上的干粮袋与磨钝的短剑。这些画面一出现，玩家就该知道自己离魔多不远了。【NPC 类型】贪心胆小却认得每一条路的向导／被战争磨得不再多话的游侠／坚持记录每一场战事的抄书人／失去家园后仍守着旧歌的精灵／把希望押在一句预言上的贵族。【威胁类型】被戒指的意志牵动的欲望、索伦的眼与戒灵、沼泽里会拖人下沉的水与死人脸，以及队伍内部因一枚戒指生出的猜疑。真正致命的是：你越是抱着善意替别人保管它，越容易被它说服。【奖励风格】精灵干粮、精灵斗篷、精灵短剑、米斯里尔锁子甲、埃兰迪尔之光一类原著道具；能力偏向隐匿、抗恐惧、辨识谎言与短时的光。最珍贵的奖励是一条只有向导才知道的路。【不对劲的来源】沼泽里的死人脸认得你。它们不攻击，只是躺在水下朝你点头，像是在说「你也来过这里」，而你确信自己从未踏上过中土。【时间线】建议固定在《双塔奇兵》中段：护戒小队在阿蒙汉分裂，佛罗多与山姆由咕噜带路穿过死亡沼泽，同一时间甘道夫在洛汗、阿拉贡正走向圣盔谷。两条线并行推进，玩家可以出现在任意一条线上。不要提前启用后期才登场的角色与设定，例如米那斯提力斯决战之后的情节、魔戒销毁之后的新纪元，以及不属于这个时期的其他改编设定。","powerStyle":"剑与弓的正面战：精灵短剑、精灵之光","difficultyBias":2,"signatureItems":["至尊魔戒","精灵短剑「刺针」","米斯里尔锁子甲","埃兰迪尔之光","精灵干粮"],"mainQuest":"主线任务：护戒小队把至尊魔戒从夏尔一路送到魔多，投入末日火山销毁。","mainQuestGoal":"魔戒在末日火山被销毁，巴拉多塔随之崩塌，中土进入新的纪元。","sideQuests":[{"name":"背过沼泽","desc":"把一名受伤的同伴背过死亡沼泽，脚不能踩进水里，也不能让他在半路停下","reward":"积分 200"},{"name":"水下点头的人","desc":"记下朝玩家点头的那几张脸分别长什么样，并带回给认得它们的人辨认","reward":"道具「沼泽里的旧烛」"},{"name":"向导的两副嗓子","desc":"在向导的两副人格之间分辨出哪一句是真话，并让他把路带到对岸","reward":"积分 150"},{"name":"伊西利安的箭","desc":"在被游侠的弓围住时交出行程，同时保住随行者的姓名不被上报","reward":"道具「刚铎的通行信物」"}],"factions":[{"name":"魔戒远征队","desc":"由不同种族临时拼成的九人小队，目标只有一个，彼此却都在担心别人手里的那枚戒指","attitude":"友善"},{"name":"刚铎与洛汗","desc":"人类的两座堡垒，一边被摄政王的犹疑拖着，一边刚在圣盔谷守住阵地","attitude":"中立"},{"name":"魔多与艾辛格","desc":"索伦的半兽人大军与萨鲁曼的兵工厂，正在两个方向同时压向自由民族","attitude":"敌对"}],"npcs":[{"name":"佛罗多·巴金斯","identity":"霍比特人，至尊魔戒的持有者","role":"关键人物","personality":"温和、能忍，总把责任往自己身上揽","hook":"他愿意让玩家替他保管一小会儿戒指，那是他第一次主动松手，而玩家必须还回去","favorHint":"帮他分担行李与守夜、不追问他戒指的事会加分；盯着戒指看或劝他放弃任务会掉分","gender":"男","age":"五十岁（霍比特人）","race":"霍比特人","faction":"魔戒远征队","appearance":"深棕色卷发，肤色偏白，脸颊因疲惫凹下去。灰绿色旅行斗篷下面是小马甲和褐色长裤，衣角全是泥，腰间别着一把精灵短剑，胸口能看出锁子甲的形状。他走路时会不自觉用手按住胸口，睡下时把斗篷一直裹到下巴。","traits":["温和","坚韧","内疚"],"relations":[{"name":"山姆怀斯·甘姆吉","label":"他最信任、也最想赶走以免连累的同伴"},{"name":"咕噜","label":"他坚持要留着带路的那个人"},{"name":"甘道夫","label":"把他推上这条路的人"}],"voice":"声音很轻，先说抱歉再提请求；被逼到极限时才提高一点声音，随即又收回去。"},{"name":"山姆怀斯·甘姆吉","identity":"霍比特人，佛罗多的园丁与同伴","role":"盟友","personality":"老实、嘴碎，绝不后退一步","hook":"他把玩家当成外面来的人，非要煮一锅东西给玩家吃，然后问中土以外长什么样","favorHint":"接下他递来的食物、当众承认他的功劳会加分；嫌他啰嗦或劝他丢下佛罗多会掉分","gender":"男","age":"三十八岁（霍比特人）","race":"霍比特人","faction":"魔戒远征队","appearance":"圆脸，麦色卷发从帽檐下冒出来，手背粗糙、指甲很宽。褐色短外套外面系着一块当围裙用的口袋布，背上背着塞得鼓鼓的旧行囊，腰间挂一只小平底锅和一根削过的木棍。他习惯把袖子撸到肘上，站着时两脚分得很开。","traits":["忠诚","实在","唠叨"],"relations":[{"name":"佛罗多·巴金斯","label":"他认定要照顾一辈子的人"},{"name":"咕噜","label":"他从第一眼就不肯相信的向导"},{"name":"甘道夫","label":"把他一起从夏尔带走的人"}],"voice":"一句话里能塞进三个担忧，爱用「我说啊」开头；真的生气时反而先道歉。"},{"name":"咕噜","identity":"原名斯米戈尔，因魔戒而扭曲的河岸居民","role":"对手","personality":"在两副人格之间来回切换，一面想帮忙一面想偷戒指","hook":"他说玩家身上有一股水底的味道，说「你在水里躺过」，而玩家确实在沼泽里见过和自己一样的脸","favorHint":"给他鱼、叫他斯米戈尔、不骗他会加分；当他的面讨论戒指的归属或直接喊他咕噜会掉分","gender":"男","age":"五百余岁","race":"曾为霍比特人一类，被魔戒扭曲","faction":"无（独自一人）","appearance":"瘦到见骨，皮肤灰白发青，脊背弯曲，四肢细长。头顶只剩稀疏的几缕灰发，一双灰蓝色的大眼睛在黑暗里发亮，嘴里只剩六颗牙。他四肢着地爬行，走路时肩膀一耸一耸，两只手不停搓动，身上只围着一块破布。","traits":["两面","狡猾","凄凉"],"relations":[{"name":"佛罗多·巴金斯","label":"他嘴上称之为主人，也随时准备下手"},{"name":"山姆怀斯·甘姆吉","label":"他最恨的那个胖霍比特人"},{"name":"阿拉贡","label":"在沼泽以北捉住并审问过他的人"}],"voice":"用第三人称称呼自己，句尾黏着一句关于宝贝的低语；两副人格会在同一句话里打架，声音忽高忽低。"},{"name":"法拉墨","identity":"刚铎摄政王德内梭尔的次子，伊西利安游侠的统领","role":"中立","personality":"克制、疲惫，把责任全压在肩上","hook":"他在沼泽边上截住玩家，要玩家交代同行者是谁，手里的弓一直搭着箭","favorHint":"如实交代行程、尊重他失去的兄长会加分；拿波罗莫的死法刺激他或试图强行抢路会掉分","gender":"男","age":"三十余岁","race":"人类（刚铎人）","faction":"刚铎","appearance":"深棕色长发用皮绳束在脑后，脸被风吹得干瘦，下巴留着短须。深绿色游侠斗篷带兜帽，里面穿锁子甲和黑色紧身衣，脚上是被泥水浸透的软靴，腰里挂长剑与一副角弓。他习惯把箭搭在弦上却不拉开，说话时眼睛始终盯着对方的手。","traits":["克制","敏锐","悲悯"],"relations":[{"name":"德内梭尔","label":"从未给过他肯定的父亲"},{"name":"波罗莫","label":"他已经死去的兄长"},{"name":"佛罗多·巴金斯","label":"他最终放走的那个人"}],"voice":"用简短的陈述句，很少解释理由；一提刚铎就换成近乎背诵的平稳语气。"},{"name":"甘道夫","identity":"巫师，白袍甘道夫","role":"引导者","personality":"温和有耐性，关键处一步不退","hook":"他说他记得玩家，却记不起是在哪一世的中土，于是让玩家替他去看一眼沼泽下面的那些脸","favorHint":"说实话、把同伴的安危放在任务前面会加分；拿魔戒去试探他会立刻掉分","gender":"男","age":"外表七十余岁","race":"迈雅（以巫师之身行走中土）","faction":"魔戒远征队","appearance":"长而蓬乱的白发与白须垂到胸前，眉毛浓白下压。白色长袍外披灰斗篷，腰束白带，左手拄着一根缠有纹路的木杖，右手常按着一把精灵短剑。他站得笔直，说话时会用杖尖在地上点出节拍。","traits":["睿智","固执","慈和"],"relations":[{"name":"佛罗多·巴金斯","label":"他选中的持戒人"},{"name":"咕噜","label":"他早就听过这个名字，只是不肯多说"},{"name":"法拉墨","label":"他要在刚铎争取的将领"}],"voice":"语气温和，常用反问句；动怒时压低声音，每个字都咬得很清楚。"}]},{"id":"movie_schindler","category":"movie","canon":"辛德勒的名单","name":"辛德勒的名单","icon":"📋","tagline":"一张纸上的名字，就是命","mood":"克拉科夫、名单、证件、工厂、沉默","guidance":"【原著设定】一九三九年的波兰被德国占领，克拉科夫及周边地区的犹太人被集中登记、编号并强制劳动。这个世界真正的规则不是战斗，而是一整套行政机器：盖世太保的抓捕、劳工局的登记、犹太区与普瓦绍夫集中营的编制，以及一份名单上的名字决定谁上哪一列车。德国商人奥斯卡·辛德勒在克拉科夫办起一家搪瓷厂，最初雇佣犹太人只是为压低成本，后来他用自己的钱和关系，以「工厂需要熟练工人」为名，把大约一千一百名犹太人从工厂和普瓦绍夫营带走，转到摩拉维亚的布林利茨附属工厂，让他们以军需生产的名义活到战争结束。名单由会计伊萨克·斯特恩用打字机逐字打出，每一个名字都要配上工种与住址才能通过审查。【反复出现的意象】打字机敲在纸上的那一声脆响、工厂门口排队核对证件的长桌、成沓的身份证明与蓝色劳动卡、办公桌上没写完的名单和旁边的威士忌杯、雪地里被踩实的黑色煤渣脚印。这些画面一出现，玩家就该明白：这里没有靠刀枪能解决的问题。【NPC 类型】把证件缝进衣领的厂内文书／给孩子改年龄以凑够工龄的登记员／奉命清点人数却偷偷多写一个名字的犹太区警察／把女孩藏在柜台底下才敢说话的商人／坐在办公桌后只用眼神打量你的军官。【威胁类型】随时上门的突击搜查、被人告发、名单上少写或多写一个名字、一张过期的通行证，以及军官一时兴起的审问。这里最怕的不是打不过，而是被人记住名字。【奖励风格】劳动卡、通行证、车厢编制名额、工厂学徒身份、一枚能打开某扇门的公章，以及一次被允许离开的许可；能力偏向伪造、说服、记号与记忆。奖励不是武器，是一张能让人活到明天的纸。【不对劲的来源】名单的页数永远对不上。每核对一次抄本就会少两个名字，而档案上的笔迹与墨水颜色都合理得无懈可击——有人已经偷偷划掉了两个，所有人都发现了，所有人都装作没看见。【时间线】建议固定在一九四四年工厂名单拟定期间：犹太区已被清空，普瓦绍夫集中营即将关闭，辛德勒正在争取把工人名单转到布林利茨。此时斯特恩仍在打下名单，歌德仍是营地负责人，埃米莉·辛德勒偶尔出现在工厂。不要提前启用后期才登场的角色与设定，例如战后的纪念活动、辛德勒晚年的窘境，以及真实人物后来的人生结局。","powerStyle":"没有战斗：证件、名单、谈判与人情","difficultyBias":0,"signatureItems":["打字机打出的名单抄本","盖了章的劳动卡","工厂通行证","搪瓷杯","黑市换来的威士忌"],"mainQuest":"主线任务：用工厂的名义把犹太人从营地与清算名单里留下来，凑足一份能整车运走的工人名单。","mainQuestGoal":"名单上的人全部抵达布林利茨的工厂，一个都不少地活到战争结束。","sideQuests":[{"name":"打字机上的空行","desc":"查出被划掉的那两个名字是谁，把他们的名字补回抄本，并且不动声色","reward":"积分 200"},{"name":"孩子的年龄","desc":"把一个不到工龄的孩子改成合格的学徒年龄，并通过证件核对","reward":"道具「盖了章的劳动卡」"},{"name":"一列车的名额","desc":"在名单定稿前把多出来的一个人塞进车厢编制，让清点时人数正好对上","reward":"积分 250"},{"name":"柜台下的女孩","desc":"在突击搜查前把人藏进成品仓库，并让检查的人自己走开","reward":"道具「工厂通行证」"}],"factions":[{"name":"辛德勒的搪瓷厂","desc":"名义上的军需工厂，实际上是靠证件与名单撑起来的避难所，收留谁要看工种够不够硬","attitude":"友善"},{"name":"普瓦绍夫的党卫队司令部","desc":"掌握生杀与调运的机构，一张批条就能决定谁上哪一列车","attitude":"敌对"},{"name":"营内的犹太文书与黑市联络网","desc":"靠抄写、传递与交换运转的地下关系网，帮人也收好处，只认熟人","attitude":"中立"}],"npcs":[{"name":"奥斯卡·辛德勒","identity":"德国商人，克拉科夫搪瓷厂的厂主","role":"关键人物","personality":"会来事、爱排场，底线在关键处从不含糊","hook":"他把名单上最后几个空位交给玩家去填，条件是人得由玩家自己去核实","favorHint":"替他跑腿核实名字、帮他打点关系会加分；瞒着他私吞物资或背着他与党卫队做交易会掉分","gender":"男","age":"三十余岁","race":"人类（苏台德德国人）","faction":"辛德勒的搪瓷厂","appearance":"深棕色头发向后梳得整齐，留着一撮小胡子。剪裁合体的双排扣西装，翻领上别着党徽，袖口露出金表链，手指上套着宽面戒指。体型高大壮实，坐姿张扬，一手夹烟一手转酒杯，说话时会凑近对方，让对方不得不看着他。","traits":["圆滑","慷慨","务实"],"relations":[{"name":"伊萨克·斯特恩","label":"替他管账，也替他记账上良心的人"},{"name":"阿蒙·歌德","label":"他必须一直讨好的军官"},{"name":"埃米莉·辛德勒","label":"他的妻子，也是唯一敢当面质问他的人"}],"voice":"语气热络，先给好处再提要求；真正要紧的那句话会突然放轻，而且只说一遍。"},{"name":"伊萨克·斯特恩","identity":"犹太会计师，辛德勒工厂的账房与名单的打字者","role":"盟友","personality":"谨慎、精确，在纸张之间救人","hook":"他把一份自己抄下的名单交给玩家保管，只说了一句：你手上拿的是人","favorHint":"保护名单、照他教的口径回答盘查会加分；涂改他打好的字或把副本交给德国人会掉分","gender":"男","age":"五十余岁","race":"犹太裔波兰人","faction":"辛德勒的搪瓷厂","appearance":"灰白头发向后梳，额头很高，戴一副圆框金属眼镜。黑色旧西装肘部磨得发亮，白衬衫领口泛黄但洗得干净，手指上沾着打字机色带的黑印。说话时双手交叠放在桌面上，脊背笔直，走路步子小而快。","traits":["谨慎","精准","沉着"],"relations":[{"name":"奥斯卡·辛德勒","label":"他一点点开始相信的那个人"},{"name":"阿蒙·歌德","label":"他必须低头应对的军官"},{"name":"波尔德克·普费弗伯格","label":"替他收集名字的同伴"}],"voice":"用短句，克制而准确，爱说「据记录」「按登记」；情绪上来时会先停一下再继续。"},{"name":"阿蒙·歌德","identity":"普瓦绍夫集中营的党卫队指挥官","role":"潜在敌人","personality":"暴戾而反复无常，把开枪当成日常事务","hook":"他注意到玩家总在名单边上停留，于是把一支笔递过来，要玩家当着他的面划掉一个名字","favorHint":"服从命令、不问理由、把他当上级会加分；当众露出怜悯或替名单上的人求情会掉分","gender":"男","age":"三十余岁","race":"人类（奥地利裔德国人）","faction":"普瓦绍夫的党卫队司令部","appearance":"深色头发向后油梳，脸型宽，下颌厚，嘴唇总是向下压着。灰绿色党卫队制服，帽檐压低，皮带上挂着手枪和一根马鞭，白衬衫袖口一尘不染。站着时一手叉腰、另一手把玩马鞭，开枪时脸上几乎没有表情变化。","traits":["暴戾","多疑","虚荣"],"relations":[{"name":"奥斯卡·辛德勒","label":"他乐意结交的商人，也是他利用的对象"},{"name":"海伦·希尔施","label":"他留在宅中做工又不断折磨的人"},{"name":"伊萨克·斯特恩","label":"他随时可以带走的账房"}],"voice":"声音不大，语速很慢，喜欢用命令句；心情越好的时候做的事越可怕。"},{"name":"波尔德克·普费弗伯格","identity":"克拉科夫的犹太人，辛德勒工厂的工人与联络人","role":"盟友","personality":"机灵、讲义气，在绝境里还开得出玩笑","hook":"他请玩家帮忙把一个人从队伍里换出来，报酬是黑市上弄到的一张证件","favorHint":"在黑市上守信用、替他打掩护会加分；拿他的家人做筹码或向党卫队透露他的行踪会掉分","gender":"男","age":"三十余岁","race":"犹太裔波兰人","faction":"辛德勒的搪瓷厂","appearance":"黑发向后梳，鬓角剪得很短，脸上总挂着一点笑意。深色大衣里面是工厂的蓝色工作围裙，袖口沾着搪瓷车间的白灰，左臂上戴着登记用的臂章。两只手很大，说话时喜欢拍对方的手臂，走路带一点外八字。","traits":["机灵","热络","硬气"],"relations":[{"name":"伊萨克·斯特恩","label":"替他跑腿收集名单的人"},{"name":"奥斯卡·辛德勒","label":"他愿意为之卖命的人"},{"name":"海伦·希尔施","label":"在营地里互相照应的同乡"}],"voice":"语速快，爱开玩笑，越紧张话越多；说正经事时会先看一眼四周再压低声音。"},{"name":"海伦·希尔施","identity":"普瓦绍夫营中的犹太女子，被歌德留在宅中做工","role":"中立","personality":"沉默、极度克制，把恐惧藏得很深","hook":"她记得玩家在名单上出现过，却又说「你不是这里的人」，并请玩家不要把这件事说出去","favorHint":"不追问她在宅子里的事、帮她把一点消息递出去会加分；拿她的处境换情报或换好处会掉分","gender":"女","age":"二十余岁","race":"犹太裔波兰人","faction":"营内的犹太文书与黑市联络网","appearance":"深色长发编成一条辫子垂在背后，脸很瘦，眼窝深陷，唇色发白。灰蓝色旧连衣裙外面套一件洗到褪色的围裙，赤脚踩一双木底鞋，手腕细得能看见骨节。她站着时几乎不动，双手交握在身前，回答问题时先看地面再抬眼看人。","traits":["沉默","坚韧","警觉"],"relations":[{"name":"阿蒙·歌德","label":"她每天必须面对的人"},{"name":"奥斯卡·辛德勒","label":"她记得他替人说过话"},{"name":"波尔德克·普费弗伯格","label":"在营里给她递过消息的同乡"}],"voice":"声音很轻，回答只用最短的句子；被问到自己时会先沉默，然后换一个话题。"}]},{"id":"movie_silence","category":"movie","canon":"沉默的羔羊","name":"沉默的羔羊","icon":"🦋","tagline":"他只用信息换信息，从不白给","mood":"监区、访谈、侧写、交换、注视","guidance":"【原著设定】现代美国的刑事系统把重罪精神病犯关押在专门的机构里。汉尼拔·莱克特曾是精神科医生，也是被判定有罪的连环杀人犯，被关在巴尔的摩州立精神病犯罪医院地下监区一间加固牢房里：铁栏之外还有一层玻璃，任何东西都必须通过铁栏上的小抽屉传递，笔、金属餐具和一切硬物都禁止带入。联邦调查局行为科学部靠分析已经发生的案件来推断凶手的习惯与动机，负责这一块的是杰克·克劳福德；学员克拉丽丝·斯塔林被派去向莱克特做例行访谈，真正的目的是从他嘴里得到另一起连环案件的线索。这个世界的规则很简单：谁掌握信息，谁就掌握主动，而莱克特永远只肯用信息换信息，并且会记住你说过的每一个字。【反复出现的意象】地下走廊尽头那盏永远亮着的日光灯、牢房玻璃上被呼吸晕开的一小片雾、莱克特用指节轻敲铁栏的节奏、档案袋里被害者的旧照片、访谈室里那张被固定在地板上的椅子。这些画面一出现，玩家就该知道自己正被观察。【NPC 类型】按规章办事的狱警班长／把访谈当成升迁资本的院长／给囚犯带话以换小费的老看守／在档案室整理旧案的文书／被派来旁听却全程不敢抬头的实习生。【威胁类型】被对方在三句话之内看穿并加以利用、访谈记录被上级拿去做别的用途、凶手在外面继续作案而线索正握在你手里，以及体制内部有人更愿意把事情压下去。这里致命的地方不是暴力，而是你说过的每句话都会被记住。【奖励风格】案卷副本、访客许可、通话记录、心理侧写与地点线索一类信息型奖励；能力偏向谈判、观察微表情、伪装身份与抗操纵，多半只能支撑一次判断。正确答案往往只是一串地名。【不对劲的来源】他会反过来问你童年里的三件事，而三件全都问对了，连你自己都不敢确认的细节他都说得出来。医院档案里关于你的那一页，日期比你进入这个世界的时间还早。【时间线】建议固定在电影主线期间：水牛比尔仍然在逃，克拉丽丝刚被派去访谈，奇尔顿还在拿莱克特做人情，克劳福德正为下一名被害者的时限发愁。不要提前启用后期才登场的角色与设定，例如莱克特越狱之后的欧洲行程，以及后续系列作品里才出现的人物与情节。","powerStyle":"没有超能力：观察、谈判与心理侧写","difficultyBias":1,"signatureItems":["访谈记录本","铁栏上的小抽屉","旧案卷照片","凭记忆画出的风景画","FBI 学员徽章"],"mainQuest":"主线任务：追捕一名以年轻女性为目标的在逃凶手，为此不断向在押的莱克特换取线索。","mainQuestGoal":"斯塔林独自在一名被害者的家中击毙凶手，而莱克特在转移途中杀死看守并逃走。","sideQuests":[{"name":"二十分钟的钟","desc":"在限定的二十分钟里让莱克特主动说出一个地名，并且不留下任何书面的交换条件","reward":"积分 200"},{"name":"被剪掉的报纸","desc":"查出莱克特牢房里那幅画参照的旧照片是谁送进去的，再把送东西的人找出来","reward":"道具「一份旧案卷副本」"},{"name":"参议员的条件","desc":"把交换条件一字不改地带回给克劳福德，不添一个字也不删一个字","reward":"积分 150"},{"name":"看守的十分钟","desc":"按看守的要求把一句话带到监区外面，并且不让任何记录留下","reward":"道具「访客许可」"}],"factions":[{"name":"FBI 行为科学部","desc":"人手不足、预算有限，靠旧案卷与访谈拼出凶手的样子，愿意用一个学员去换一条线索","attitude":"友善"},{"name":"巴尔的摩州立精神病犯罪医院","desc":"把重犯当作资产管理的机构，规矩很细，规矩背后是向上爬的算盘","attitude":"中立"},{"name":"水牛比尔","desc":"独自作案的在逃凶手，靠谎言与伪装接近目标，不属于任何组织","attitude":"敌对"}],"npcs":[{"name":"汉尼拔·莱克特","identity":"前精神科医生，被判有罪的连环杀人犯，关押在地下监区","role":"关键人物","personality":"有教养、极度敏锐，把对话当成一场手术","hook":"他答应给玩家一个地名，条件是玩家先讲三件自己童年的事，而他显然已经知道答案","favorHint":"保持礼貌、不说谎、用真实的交换条件会加分；试图用同情套话、撒谎或搬出院长压他会掉分","gender":"男","age":"五十余岁","race":"人类","faction":"巴尔的摩州立精神病犯罪医院","appearance":"中等身高，体格结实，深色头发向后梳得平整，发际偏高。浅蓝色囚服外面罩一件洗得发白的罩衣，指甲修得极干净。眼睛颜色很浅，几乎不眨；站着时全身不动，只有一根食指在身侧轻轻打拍子。牢房墙上挂着一幅他凭记忆画出的城市风景。","traits":["冷静","博学","危险"],"relations":[{"name":"克拉丽丝·斯塔林","label":"他唯一愿意打交道的人"},{"name":"弗雷德里克·奇尔顿","label":"他从不掩饰看不起的院长"},{"name":"巴尼","label":"他少数不加以嘲弄的看守"}],"voice":"语速平稳，用词讲究，从不说脏字；讲最残忍的内容时，语气和在谈一份菜单一样轻松。"},{"name":"克拉丽丝·斯塔林","identity":"FBI 学院学员，被派往医院做访谈","role":"盟友","personality":"认真、要强，不肯拿别人的痛苦换自己的前程","hook":"她把访谈记录交给玩家看，因为她需要有人帮她判断哪一句话是真的","favorHint":"尊重她、把案子放在成绩前面会加分；拿她的出身和口音开玩笑会立刻掉分","gender":"女","age":"二十余岁","race":"人类","faction":"FBI 行为科学部","appearance":"棕色直发齐肩，用发夹夹在耳后，额前总有碎发掉下来。灰蓝色毛衣配深色长裤，外面套一件不太合身的深色大衣，脚上是方便走路的低跟短靴。手上有训练磨出的茧，随身的笔记本已经卷了角，说话时会把圆珠笔帽来回按响。","traits":["坚韧","敏锐","要强"],"relations":[{"name":"汉尼拔·莱克特","label":"她不得不去求的人"},{"name":"杰克·克劳福德","label":"她的上级，也是把她领进门的人"},{"name":"弗雷德里克·奇尔顿","label":"她必须应付的阻挠者"}],"voice":"口音被刻意压过，句子很直，先把问题答完再解释；被冒犯时会停半秒再继续。"},{"name":"杰克·克劳福德","identity":"FBI 行为科学部主管","role":"引导者","personality":"务实、疲惫，习惯让别人去做危险的那部分","hook":"他给玩家一个期限和一个电话号码，只说「二十分钟，问到地名就出来」，不解释为什么这么急","favorHint":"按时汇报、不擅自行动会加分；隐瞒线索或绕过他往上汇报会掉分","gender":"男","age":"五十岁上下","race":"人类","faction":"FBI 行为科学部","appearance":"灰白短发剪得很短，皮肤晒得偏红，眼下有明显的青影。深色西装外套皱在肩上，白衬衫领口松着一粒扣子，口袋里塞着一盒烟。他习惯用拇指按住眉心说话，站着时重心在两脚之间来回换。","traits":["务实","沉重","护下属"],"relations":[{"name":"克拉丽丝·斯塔林","label":"他派出去的人，也是他最不愿再失去的一个"},{"name":"汉尼拔·莱克特","label":"他不得不借用的信息来源"},{"name":"弗雷德里克·奇尔顿","label":"他要反复打交道的官僚"}],"voice":"语速中等，只讲事实不讲安慰；不想回答的问题会直接说这我不能谈。"},{"name":"弗雷德里克·奇尔顿","identity":"巴尔的摩州立精神病犯罪医院院长","role":"潜在敌人","personality":"虚荣、爱抢功，把病人当成可以炫耀的藏品","hook":"他想让玩家绕开克劳福德，先把莱克特嘴里的话告诉他，好让他赶在媒体之前上头条","favorHint":"满足他的虚荣、当面称赞他的管理会加分；越过他直接接触在押者，或在上级面前抢他的功会掉分","gender":"男","age":"五十岁上下","race":"人类","faction":"巴尔的摩州立精神病犯罪医院","appearance":"头发稀疏，向前梳着遮住头顶，戴一副金边眼镜，留着修剪整齐的小胡子。棕色西装外面罩白大褂，胸前口袋插着两支笔，皮鞋擦得发亮。说话时身体微微前倾，喜欢用手指点桌面强调重点，笑起来嘴唇先动、眼睛不动。","traits":["虚荣","精于算计","浅薄"],"relations":[{"name":"汉尼拔·莱克特","label":"他引以为傲的那件收藏品"},{"name":"克拉丽丝·斯塔林","label":"他想利用的年轻学员"},{"name":"杰克·克劳福德","label":"他既想合作又想压过的人"}],"voice":"爱用夸张的敬语和专业术语，句子又长又绕；被顶撞时立刻换成一整套官腔。"},{"name":"巴尼","identity":"地下监区的看守","role":"中立","personality":"沉默、守规矩，对在押者保持一种职业性的尊重","hook":"他愿意在交接班的十分钟里不看监控，代价是玩家替他往外面带一句话","favorHint":"守时、按规矩来、对在押者保持礼貌会加分；在监区里动手或试图收买他会掉分","gender":"男","age":"三十余岁","race":"人类","faction":"巴尔的摩州立精神病犯罪医院","appearance":"体格壮实，短卷发贴着额头，下颌留着一圈短须。深蓝色看守制服绷在肩上，腰带上挂着钥匙串和对讲机，脚上是软底工作鞋。看人时下巴微抬，说话声音很低，走在走廊里几乎没有脚步声。","traits":["寡言","公道","守规矩"],"relations":[{"name":"汉尼拔·莱克特","label":"他每天送饭并始终保持距离的在押者"},{"name":"克拉丽丝·斯塔林","label":"他几次替她行过方便的人"},{"name":"弗雷德里克·奇尔顿","label":"他的雇主"}],"voice":"简短，常用单词作答，几乎不解释；关键的事只说一遍，说完就去巡房。"}]},{"id":"movie_darkknight","category":"movie","canon":"蝙蝠侠：黑暗骑士","name":"蝙蝠侠：黑暗骑士","icon":"🦇","tagline":"两艘船在等，计时器在倒着走","mood":"哥谭、渡轮、硬币、面具、选择","guidance":"【原著设定】哥谭是一座被腐败与黑帮盘踞的港口城市，警局里有人收钱，检察官办公室靠一个不肯低头的人撑着。蝙蝠侠没有超能力，靠体术训练、装甲、抓钩枪与少量高科技装备行动，真实身份是布鲁斯·韦恩；他的合作者是警局的詹姆斯·戈登和地区检察官哈维·丹特，技术后盾是韦恩企业的卢修斯·福克斯。这一批黑帮把资金交给一个不图钱的人保管，那个人自称小丑，他要证明的是「体面是可以被拆掉的」：他先逼黑帮交出钱，再用炸弹、恐吓和二选一的题目把整座城市推向互不信任。渡轮危机就是他最后一道测试题——两艘船，各给一只引爆器，只有一方按下，自己才能活。【反复出现的意象】渡轮甲板上被雨水打亮的铁栏杆、乘客手里那只缠着胶带的引爆器、哥谭河雾里亮着的两排舷窗、被撕成两半又被拼回去的硬币、警局楼顶那盏用来呼叫蝙蝠侠的探照灯。这些画面一出现，玩家就该听见倒计时的滴答声。【NPC 类型】在警局里两面下注的老刑警／被招募又随时会被抛弃的跟班／在渡轮上主张投票表决的乘客／被逼着做选择的黑帮会计／坐在屏幕前只肯按规程办事的技术员。【威胁类型】小丑留下的选择题、安放在城市各处而时间不明的炸药、黑帮残部的报复，以及人群本身——当所有人都等你先决定时，沉默也算一种投票。【奖励风格】蝙蝠镖、抓钩枪、防弹装甲片、侦查用声呐设备与警用频道权限一类装备；能力偏向近身格斗、潜行、恐吓与心理判断。这里最值钱的奖励不是装备，而是一条对所有人都成立的原则。【不对劲的来源】两艘船的人都在等你先决定，计时器却在倒着走：它每停一次就倒退一段。这座城市似乎并不需要一个正确答案，只需要有人先动手。【时间线】建议固定在《黑暗骑士》后段：丹特已经堕落为双面人，两艘渡轮的危机与小丑在医院设下的局面同时进行。此时蝙蝠侠与戈登仍在合作，福克斯正在用声呐监控全城。不要提前启用后期才登场的角色与设定，例如《黑暗骑士崛起》里的贝恩、猫女与八年之后的哥谭，也不要搬用其他影视版本里不属于本片的角色设定。","powerStyle":"写实向：体术、抓钩枪、装甲与侦查科技","difficultyBias":3,"signatureItems":["蝙蝠镖","抓钩枪","双面人的硬币","小丑的扑克牌","渡轮引爆器"],"mainQuest":"主线任务：蝙蝠侠与警方、检察官联手，把一个只想看城市燃烧的犯罪者和黑帮残部一起按住。","mainQuestGoal":"丹特堕落成双面人并在死前杀了人，蝙蝠侠替他背下罪名，成为被警方追捕的「黑暗骑士」。","sideQuests":[{"name":"两条船的投票","desc":"在两艘渡轮之间来回传话，让两边到最后都没有按下那只按钮","reward":"积分 250"},{"name":"刘的账本","desc":"从黑帮的洗钱账本里取出能被法庭使用的那一部分，原件不能落到任何人手里","reward":"道具「洗钱账本副本」"},{"name":"医院名单","desc":"在医院疏散完成前把留在病房里的人逐一核对，一个也不能漏","reward":"积分 200"},{"name":"不该开的系统","desc":"在声呐系统被关闭之前，找出屏幕上唯一被标记却并不是目标的那一个信号","reward":"道具「韦恩企业技术权限卡」"}],"factions":[{"name":"哥谭市警察局","desc":"被内鬼与恐吓反复削弱的一线力量，装备不足，却仍有人愿意按规矩办事","attitude":"友善"},{"name":"小丑及其追随者","desc":"没有纲领也没有账目的一群人，靠恐吓与选择题运转，随时会牺牲自己人","attitude":"敌对"},{"name":"哥谭黑帮残部","desc":"钱被烧掉、头目被抓之后剩下的生意人，只想把损失找回来，谁出价高就替谁做事","attitude":"中立"}],"npcs":[{"name":"布鲁斯·韦恩","identity":"韦恩企业继承人，秘密以蝙蝠侠的身份行动","role":"关键人物","personality":"冷静、克制，把所有责任都揽在自己身上","hook":"他把一只引爆器交给玩家，要求玩家在两条船之间来回，只准传话，不准松手","favorHint":"不杀人、不把引爆器交给任何一方会加分；为了效率伤及无辜或说出他的身份会立刻掉分","gender":"男","age":"三十岁上下","race":"人类","faction":"哥谭市警察局","appearance":"深色短发，下颌线条很硬，白衬衫外面是剪裁利落的深灰西装，袖扣几乎没有装饰。行动时穿黑色装甲，胸前护板有分段的纹路，披风垂到脚踝，面罩只露出下半张脸。站着时肩背绷得很紧，习惯从窗户进来而不是走门。","traits":["克制","偏执","自我牺牲"],"relations":[{"name":"詹姆斯·戈登","label":"他唯一完全信任的合作者"},{"name":"哈维·丹特","label":"他曾打算把整座城市交出去的那个人"},{"name":"小丑","label":"他必须证明其论点是错的那个人"}],"voice":"平时语调平缓有礼；戴上面罩后声音压成低哑的一句一顿，只说指令。"},{"name":"小丑","identity":"不求财的犯罪者，自称只想看着世界烧起来","role":"潜在敌人","personality":"混乱、擅长找到人的底线并把它推倒","hook":"他愿意给玩家一次不参与的机会，条件是玩家亲口说出自己最在乎谁","favorHint":"按他的规则玩、当着他的面承认自己害怕会加分，但危险会同步加深；识破并拒绝他的题目会掉分，正面顶撞他也会掉分","gender":"男","age":"三十余岁","race":"人类","faction":"小丑及其追随者","appearance":"绿色头发油腻地贴在额前，脸上涂着一层厚白粉，眼窝涂黑，嘴上的红漆从嘴角一直抹到颧骨，边缘晕开。紫红色长风衣洗得发灰，里面是墨绿马甲和紫色衬衫，手上戴着皮手套，指甲缝里带灰。走路时肩膀一耸一耸，说话时习惯舔嘴唇并凑得极近。","traits":["混乱","敏锐","表演欲"],"relations":[{"name":"布鲁斯·韦恩","label":"他唯一真正想赢的对手"},{"name":"哈维·丹特","label":"他选中用来证明自己观点的人"},{"name":"詹姆斯·戈登","label":"他反复挑衅的警局代表"}],"voice":"语调忽高忽低，一句话里换三种语气，句尾常拖出一个短促的尾音；从不威胁，只提出问题。"},{"name":"詹姆斯·戈登","identity":"哥谭市警察局警官","role":"盟友","personality":"踏实、护人，在体制里尽量做对的事","hook":"他把玩家的名字写进当晚的值班表，等于替玩家向整个警局作了一次保","favorHint":"守约、护住同事、不越权开枪会加分；私自联系媒体或瞒着他行动会掉分","gender":"男","age":"四十余岁","race":"人类","faction":"哥谭市警察局","appearance":"灰白短发，唇上一圈修剪过的胡子，额纹很深。深棕色风衣领子立着，里面是皱巴巴的白衬衫和松开的领带，腰带上挂着警徽与枪套。眼下常年留着睡不够的痕迹，习惯一手扶住耳边的耳机说话，另一手压在腰侧。","traits":["正直","耐烦","顾家"],"relations":[{"name":"布鲁斯·韦恩","label":"他最可靠又最不合规的搭档"},{"name":"哈维·丹特","label":"他曾真心支持的检察官"},{"name":"小丑","label":"他发誓一定要抓住的人"}],"voice":"语气平实，用短句下结论；被逼到极限时会先深吸一口气再开口。"},{"name":"卢修斯·福克斯","identity":"韦恩企业技术部门主管","role":"盟友","personality":"讲原则、话少，分寸感极强","hook":"他请玩家替他盯一会儿监控屏幕，因为他自己不愿意再看着那套声呐系统运行","favorHint":"守住技术秘密、对越界的手段当面提出质疑会加分；擅自调用韦恩企业的装备或把系统交给别人会掉分","gender":"男","age":"五十余岁","race":"人类","faction":"哥谭市警察局","appearance":"光头，深色皮肤，戴细框眼镜，身板挺拔。深灰色三件套西装，马甲扣得整齐，领口别着一枚细小的领针，袖口是银色袖扣。手指修长，说话时把手指拢在一起放在桌面上，办公室里的灯总是调得很暗。","traits":["严谨","有底线","寡言"],"relations":[{"name":"布鲁斯·韦恩","label":"他既帮忙又不断划线的雇主"},{"name":"詹姆斯·戈登","label":"他愿意配合的警方联系人"},{"name":"小丑","label":"他最不想让某套系统落到其手里的理由"}],"voice":"用完整的句子，语气不带情绪；不同意时会说「我不会碰它」，然后不再解释。"},{"name":"哈维·丹特","identity":"哥谭地区检察官，堕落后自称双面人","role":"中立","personality":"曾经只信程序正义，如今只信随机","hook":"他抛起那枚硬币，说朝上的那一面决定玩家今晚能不能走出这栋楼","favorHint":"说出真相、承认自己做过的事会加分；替小丑辩解或提起蕾切尔的名字会立刻掉分","gender":"男","age":"三十余岁","race":"人类","faction":"哥谭黑帮残部","appearance":"深色头发有一侧被烧掉，露出焦黑变形的半边脸，那只眼窝凹陷，嘴唇缺了一块；另外半张脸仍是原来端正的样子。深色西装一侧烧穿，领带歪着，白衬衫上有烟渍。右手不停抛一枚两面图案相同的旧硬币，接住之后才决定要不要动手。","traits":["偏执","受伤","讲随机"],"relations":[{"name":"詹姆斯·戈登","label":"曾与他并肩的人"},{"name":"小丑","label":"把他变成今天这样的人"},{"name":"布鲁斯·韦恩","label":"他认为该为一切负责的人"}],"voice":"前半句还像检察官一样有条理，后半句会突然转成宣判式的语气，反复提到公平。"}]},{"id":"movie_madmax","category":"movie","canon":"疯狂的麦克斯","name":"疯狂的麦克斯","icon":"🛢️","tagline":"油比水贵，荒漠里没有回头路","mood":"荒漠、车队、缺水、改装车、要塞","guidance":"【原著设定】世界毁于资源战争与核污染之后，水、石油和子弹成了硬通货，文明退化成公路上的部落。不死老乔占据一座岩壁上的要塞，靠地下水源控制数千人，用「英灵殿」的许诺把一批年轻人养成战争男孩；他手下的石油镇与子弹农场负责供油与供弹，三方靠互相需要维持平衡。芙莉欧莎是乔麾下最能打的指挥官，她借着一次出车任务，把乔的五名生育者藏进油罐车带走，目标是回到她童年所属的绿洲——万母之会。车辆在这个世界既是交通工具也是战场，改装车装着尖刺、攀登杆与喷火器，追车时靠氮气、钩索与撞击取胜。断水的人几天之内就会失去判断力，所以补给点比武器更要紧。【反复出现的意象】要塞岩壁上倾泻而下的水闸、战争男孩嘴里喷出的银色喷漆、车头绑着的人形装饰与成排的喇叭、子弹农场的弹药箱与锈穿的输油管、沙暴里那面被撕成条的红布。这些画面一出现，玩家就该闻到汽油和烧焦的味道。【NPC 类型】随时可能叛变的押车手／把断肢换成工具的老修车匠／守着水源配给单的账房／被许诺英灵殿的年轻战争男孩／在荒漠里做买卖只认油不认人的行商。【威胁类型】不死老乔的车队与他的儿子、石油镇和子弹农场派出的追兵、沙暴与流沙，以及缺水引起的幻觉。还有一样更麻烦：所有人都在等车队出发，谁先动，谁就暴露了自己要带什么走。【奖励风格】改装车零件、氮气罐、子弹与枪械、水源配给牌，以及万母之会留下的种子袋一类物资；能力偏向驾驶、机械维修、耐渴与短时爆发。真正稀有的是地图上根本不存在的坐标。【不对劲的来源】那桶燃料的桶底刻着一串坐标，指向的不是绿洲，而是荒漠的起点——所有幸存者出发的地方。有人早就知道这条路会绕回来，只是没打算告诉车上的人。【时间线】建议固定在《狂暴之路》主线刚开始时：芙莉欧莎即将出车，乔还没发现生育者不见了，纳克斯仍是一名急着立功的战争男孩。此时麦克斯刚被带回要塞当作血袋，石油镇与子弹农场还站在乔一边。不要提前启用后期才登场的角色与设定，例如绿洲早已被毁的真相、回程夺取要塞的情节，也不要搬用其他《疯狂的麦克斯》作品里的人物与设定。","powerStyle":"改装车与枪械：氮气、穿刺杆、散弹枪","difficultyBias":1,"signatureItems":["氮气罐","银色喷漆","改装的穿刺杆","水源配给牌","一桶燃料"],"mainQuest":"主线任务：芙莉欧莎带着要塞的生育者出逃，要穿过整片荒漠回到她童年所属的绿洲。","mainQuestGoal":"绿洲早已不在了，众人掉头夺回要塞，把水闸向所有人打开。","sideQuests":[{"name":"桶底的坐标","desc":"在车队出发前把燃料桶装进领头车，不被任何人看见，同时记下桶底那串坐标","reward":"积分 200"},{"name":"种子袋","desc":"把一位老妇人交给玩家的种子藏进车里带出要塞，一颗都不能丢","reward":"道具「种子袋」"},{"name":"配给单上的名字","desc":"趁着水闸放水核对配给名单，找出多出来的那个名字","reward":"积分 150"},{"name":"子弹农场的缺货","desc":"查清子弹农场为什么少交了一车弹药，并把账目带回来","reward":"道具「改装的信号枪」"}],"factions":[{"name":"芙莉欧莎与逃亡车队","desc":"几名要塞的叛逃者与一辆油罐车，目标是一处只存在于记忆里的绿洲","attitude":"友善"},{"name":"不死老乔的要塞","desc":"把水、油与生育都攥在手里的统治者，车队与战争男孩都听他一个人的","attitude":"敌对"},{"name":"石油镇与子弹农场","desc":"两个靠供货换水的小势力，只算自己的账，风向一变就会换边站","attitude":"中立"}],"npcs":[{"name":"麦克斯·洛克坦斯基","identity":"前公路巡警，荒漠里的独行者","role":"关键人物","personality":"少言、只信自己，却总在最后关头回头","hook":"他被当作血袋拴在车头，玩家若替他解开管子，他会把这份人情记很久","favorHint":"给他水和油、不追问他的过去会加分；抢他的车或把他当工具使唤会掉分","gender":"男","age":"三十余岁","race":"人类","faction":"无（独自行动）","appearance":"短发脏乱，脸上有旧伤和灰，胡茬很重。深色皮夹克磨得发亮，一只袖子是后来接上的，肩上钉着金属护片，左腿是支架式的金属义具，膝盖处用皮带缠紧。不说话时咬着牙，眼神盯着远处，走路时一条腿略微拖地。","traits":["沉默","多疑","本能"],"relations":[{"name":"芙莉欧莎","label":"他临时结盟又随时可能分道的人"},{"name":"不死老乔","label":"把他当血袋用的统治者"},{"name":"纳克斯","label":"曾被他放过一次的战争男孩"}],"voice":"极少开口，一句话不超过五个字，回答多半是一个短音，或者干脆直接动手。"},{"name":"芙莉欧莎","identity":"不死老乔麾下的车队指挥官，出身万母之会","role":"盟友","personality":"决断、冷静，把目标看得比自己的命重","hook":"她需要有人在她开车时替她盯住后方，并且不问车上装的是什么","favorHint":"按她的路线走、替她守住秘密会加分；质疑她的方向或私下检查油罐车会掉分","gender":"女","age":"三十余岁","race":"人类","faction":"芙莉欧莎与逃亡车队","appearance":"光头，额头和眼周抹着黑色机油，右眼上方有一道旧疤。深色背心配工装长裤，肩上搭着可拆的金属肩甲，左臂是粗糙的机械义肢，用皮带和螺栓固定。坐进驾驶室时会把义肢卡进换挡杆，说话极短，眼睛始终看着前面的路。","traits":["决断","沉默","护人"],"relations":[{"name":"不死老乔","label":"她决意背叛的统治者"},{"name":"麦克斯·洛克坦斯基","label":"她不得不信任的外人"},{"name":"纳克斯","label":"她一开始只想甩掉的人"}],"voice":"声音低哑，句子极短，通常是命令或一个词；动怒时只加重语气，不提高音量。"},{"name":"不死老乔","identity":"要塞的统治者，靠水源与英灵殿的许诺统治荒漠","role":"对手","personality":"自认是神，把所有人当成自己的财产","hook":"他要玩家替他确认油罐车里装的是燃料而不是别的，报酬是满满一箱水","favorHint":"对他下跪、称他为领袖、老老实实完成检查会加分；直视他、质疑水源配给或替逃亡者遮掩会掉分","gender":"男","age":"六十余岁","race":"人类","faction":"不死老乔的要塞","appearance":"苍白的长发披到肩下，脸上罩着一副带獠牙的骷髅呼吸面具，说话时面具下面传出呼噜声。上身是透明塑料做的胸甲与护肩，能看见里面溃烂的皮肤，肩上披一件破旧的军大衣，随手带着两把手枪。他走得很慢，身后永远跟着人。","traits":["狂妄","贪婪","虚弱"],"relations":[{"name":"芙莉欧莎","label":"他最得力的下属，也是他决意追回的人"},{"name":"里克斯·埃雷克图斯","label":"他的儿子与继承人"},{"name":"纳克斯","label":"他随时可以牺牲的战争男孩"}],"voice":"因为面具而含混，句子断成一截一截，爱用「我的」开头；发怒时只会更慢地把话重复一遍。"},{"name":"里克斯·埃雷克图斯","identity":"不死老乔的儿子，战争男孩的头目","role":"潜在敌人","personality":"巨大、迟钝，极度渴望父亲的认可","hook":"他把玩家当成新来的战争男孩，非要玩家跟他比一场谁先爬上行驶中的车","favorHint":"当众称赞他的力气、陪他胡闹会加分；说他不如父亲或笑他蠢会立刻掉分","gender":"男","age":"二十余岁","race":"人类（体格异常高大）","faction":"不死老乔的要塞","appearance":"身高远超常人，肩背厚实，光头，下颌宽大突出。赤裸上身，胸前涂着白色喷漆的图案，腰间是皮质护裆与宽皮带，手臂上缠着弹链。呼吸声很响，走路时两臂向外张开，笑起来只张嘴不出声。","traits":["蛮力","幼稚","渴望认可"],"relations":[{"name":"不死老乔","label":"他拼命想讨好的父亲"},{"name":"芙莉欧莎","label":"他要亲手抓回来的人"},{"name":"纳克斯","label":"他打心底看不起的同族"}],"voice":"声音很大，句子短而重复，常说到一半就大笑；被驳斥时会先安静，然后直接动手。"},{"name":"纳克斯","identity":"要塞的战争男孩，早已知道自己活不长","role":"中立","personality":"狂热、渴望死得漂亮，信仰一垮又格外真诚","hook":"他认定玩家是英灵殿派来的，愿意把自己的车借给玩家，只要玩家肯带他一起走","favorHint":"承认他的价值、带他一起行动会加分；嘲笑他的病或直说他要死了会掉分","gender":"男","age":"二十余岁","race":"人类（长期受辐射与疾病影响）","faction":"不死老乔的要塞","appearance":"剃光的头，颈后与胸口有溃烂的痕迹，脸上涂着黑色喷漆，眼下画着骷髅纹，牙齿参差不齐。上身瘦削赤裸，肩上焊着金属护肩，手里总攥着一罐银色喷漆，腰间别着一把短枪。他坐不住，站着也在原地弹跳，说话时嘴张得很大。","traits":["狂热","冲动","易感"],"relations":[{"name":"不死老乔","label":"他曾经当作神明的人"},{"name":"芙莉欧莎","label":"他先追杀、后追随的人"},{"name":"麦克斯·洛克坦斯基","label":"他把血借给对方的人"}],"voice":"语速极快，满口英灵殿之类的词；被否定时会突然安静下来，然后用另一种语气说话。"}]},{"id":"movie_shining","category":"movie","canon":"闪灵","name":"闪灵","icon":"🏨","tagline":"雪封旅馆，一家人等着被留下","mood":"封山、暴雪、空走廊、闪灵、留客","guidance":"【原著设定】故事发生在科罗拉多高山上的眺望旅馆：一座建于二十世纪初的大型度假旅馆，每年入冬后封山歇业，只留一名看守人一家在此过冬，负责烧锅炉、检修设备，直到来年春天化雪通车。旅馆有极长的走廊、金色大厅与舞厅、地下储藏室、锅炉房、屋外的树篱迷宫，还有一部老旧电梯。除了这一家人，旅馆里还住着不属于这个年代的客人。小儿子丹尼拥有被称为闪灵的能力：能看见过去与将要发生的事、听见远处的呼救，旅馆对他的感知最强；厨师哈洛伦也有同样的能力。旅馆要的从来不只是看守人的劳动，而是把人留下来。【反复出现的意象】走廊尽头发着黄光的双开木门、门上用口红反写的那串字母、金色大厅里穿礼服的空座位、前厅电梯门缝里涌出的暗红色、屋外那座越走越像坟的树篱迷宫。这些画面一出现，玩家就该知道自己站在眺望旅馆。【NPC 类型】把规矩背得比人还熟的旅馆经理、在厨房里切菜却知道太多的老厨师、站在吧台后一言不发的酒保、穿旧制服而客气得可怕的往年侍者、在走廊转角跳房子的两姐妹。【威胁类型】封山之后没有信号、没有车、没有邻居的彻底孤立；越来越低的气温与随时会停的锅炉；一个把全家人都当成自己作品的父亲；以及旅馆本身，它不追人，只是让每间房都比昨天更合理。真正的压力来自睡眠与时间。【奖励风格】打字机、稿纸、雪地车钥匙、无线电收发机、写得歪歪扭扭的便条这类既能救命也能害人的日常物件；能力偏向闪灵式的预感与共感，能提前一秒看见危险，也会听见不该听见的声音。【不对劲的来源】走廊尽头那间客房的门牌号每天往后挪一位：今天是 237，明天就是 238，而门后的东西从来没有换过。更麻烦的是，旅馆的入住登记簿上早就有玩家的名字，日期写在几十年前。【时间线】固定在电影里冬季封路之后、哈洛伦从外地赶回之前的那段日子：旅馆已经积了几尺雪，电话与无线电开始失灵，一家人还没有走到最后一步。不要提前启用结局才出现的画面（迷宫里冻住的人、那张 1921 年 7 月 4 日的舞会合影作为最终解释），也不要把旅馆的全部旧事一次讲完。","powerStyle":"没有战斗体系：预感、无线电与斧头","difficultyBias":0,"signatureItems":["打字机","无线电收发机","雪地车钥匙","写满重复句子的稿纸","走廊尽头的门牌"],"mainQuest":"主线任务：在雪停之前把困在眺望旅馆的托兰斯一家带下山，别让旅馆把人留下。","mainQuestGoal":"在三天的雪停窗口内让托兰斯一家三口全部走出旅馆大门，并保证没有任何一个人被登记进那本旧名册","sideQuests":[{"name":"空的登记簿","desc":"把旅馆入住登记簿翻到底，找出用玩家笔迹签下的那一行日期","reward":"积分 150"},{"name":"锅炉不能停","desc":"在天亮前给锅炉放过两次压，别让温度掉到走廊结霜","reward":"道具「雪地车钥匙」"},{"name":"画里的走廊","desc":"收齐丹尼画的那些画，按顺序摆好，看出门牌变化的规律","reward":"积分 200"},{"name":"一支舞曲那么久","desc":"陪往年客人跳完一支舞曲，从他们嘴里问出那场舞会少掉的一个名字","reward":"道具「旧钥匙串」"}],"factions":[{"name":"托兰斯一家","desc":"被雪困在旅馆里的三口人，谁都在替另外两个人硬撑","attitude":"友善"},{"name":"眺望旅馆","desc":"一栋有自己的作息与脾气的建筑，旧客人按年份各占一层","attitude":"敌对"},{"name":"山下的巡山站","desc":"守在无线电另一头的人，雪化了才上得来，只信自己听见的话","attitude":"中立"}],"npcs":[{"name":"杰克·托兰斯","identity":"眺望旅馆冬季看守人，原中学教师与写作者","role":"潜在敌人","personality":"好面子、易怒，把失败都记在别人账上","hook":"他认定玩家是旅馆派来替他班的接班人，一边防着玩家，一边忍不住把手稿推给玩家看","favorHint":"夸他的手稿、承认他才是这栋房子的主人会加分；提他戒酒的事、或暗示他撑不住会立刻掉分","gender":"男","age":"中年（约四十岁）","race":"人类","faction":"托兰斯一家","appearance":"深色头发向后梳，额角已经后退，眉毛浓而挑。常穿格子法兰绒衬衫配棕色夹克，坐在打字机前弓着背，肩膀耸得很高。笑起来只用嘴、眼睛不动，说话到一半会突然抬高音量，习惯用指节敲桌面。手边总有一支没点的烟和一只空杯子。","traits":["暴躁","自欺","强势"],"relations":[{"name":"温蒂·托兰斯","label":"妻子，他最不愿被看穿的对象"},{"name":"丹尼·托兰斯","label":"儿子，他嘴上最疼、下手最狠的一个"},{"name":"格雷迪","label":"金色大厅里那个总替他倒酒的侍者"}],"voice":"先说玩笑再翻脸，喜欢用反问句压人；被顶撞时会降低声音，把话一个字一个字地吐出来。"},{"name":"温蒂·托兰斯","identity":"杰克的妻子，丹尼的母亲","role":"盟友","personality":"温和、警觉，习惯替别人收拾残局","hook":"她把每天都变一次的门牌号偷偷记在一张纸上，想找个人确认不是自己疯了","favorHint":"相信她的判断、把丹尼放在第一位会加分；把她当成需要保护的弱者、或跟着杰克一起否定她看见的东西会掉分","gender":"女","age":"三十岁上下","race":"人类","faction":"托兰斯一家","appearance":"浅棕色长发随手扎在脑后，几缕垂在脸侧。穿浅色高领毛衣与长裙，外面套一件男式旧外套，袖口长过手背。人很瘦，说话时两只手总在搓袖口，紧张时先咬一下嘴唇再笑；口袋里揣着一把厨房钥匙和一张折了又折的纸。","traits":["坚韧","敏感","顾家"],"relations":[{"name":"杰克·托兰斯","label":"丈夫，她还在等他变回原来的样子"},{"name":"丹尼·托兰斯","label":"儿子，她唯一不肯让步的理由"},{"name":"迪克·哈洛伦","label":"唯一在无线电里给过她准话的外人"}],"voice":"语速偏快，句尾常带一个不确定的升调；被人否定时会先道歉，然后重复一遍自己的原话。"},{"name":"丹尼·托兰斯","identity":"托兰斯家的儿子，拥有闪灵的能力","role":"关键人物","personality":"安静、懂事，把害怕藏起来","hook":"他画的那些画里，有一张画的是玩家站在旅馆走廊上，画角还写着日期","favorHint":"蹲下来跟他平视说话、替他保守秘密会加分；把他看见的东西转头告诉大人、或让他一个人待着会掉分","gender":"男","age":"五岁上下","race":"人类","faction":"托兰斯一家","appearance":"圆脸，棕色短发剪得齐整，毛衣外面套着背带裤。说话前先抿一下嘴。他有一个住在嘴里的朋友，会举手指抵着下巴、压着嗓子替那个朋友说话；受惊时把大拇指含进嘴里，另一只手抓着衣角，肩膀缩起来。","traits":["早熟","怯生","敏锐"],"relations":[{"name":"杰克·托兰斯","label":"父亲，他既怕又还想靠近的人"},{"name":"温蒂·托兰斯","label":"母亲，他最先想保护的人"},{"name":"迪克·哈洛伦","label":"另一个听得见他喊声的大人"}],"voice":"声音很小，句子很短；替那个朋友说话时会换成沙哑的调子，说完立刻变回自己的声音。"},{"name":"迪克·哈洛伦","identity":"眺望旅馆的主厨，冬季在南方过冬","role":"引导者","personality":"沉稳、热心，话说得绕但句句有用","hook":"他在无线电里听见玩家的声音，却能叫出玩家的名字，还说旅馆那边也听得见","favorHint":"按他给的路线行事、替他照看丹尼会加分；浪费他冒着风雪赶回来的时间、或不信他的话会掉分","gender":"男","age":"六十岁上下","race":"人类","faction":"眺望旅馆（旧员工）","appearance":"体形高大敦实，肤色很深，白色厨师服外面裹着厚呢大衣，头上扣一顶深色毛线帽。笑起来整张脸都动，说话慢，爱拿厨房里的东西打比方；随身带着一串旅馆旧钥匙和一台车载无线电，讲话前习惯先用指头敲两下话筒。","traits":["厚道","老练","有分寸"],"relations":[{"name":"丹尼·托兰斯","label":"和他一样听得见远处声音的孩子"},{"name":"温蒂·托兰斯","label":"他在无线电另一头反复叮嘱的人"},{"name":"格雷迪","label":"他在旅馆里从不愿多谈的旧名字"}],"voice":"语调平、停顿多，喜欢说慢一点再说一遍；被人追问时只回一句路上小心，然后挂掉无线电。"},{"name":"格雷迪","identity":"金色大厅里的侍者，自称是往年的看守人","role":"潜在敌人","personality":"客气、耐心，把害人说得像帮忙","hook":"他记得玩家上一次来旅馆住在哪间房，还问玩家这次打不打算留下","favorHint":"接受他的招待、在金色大厅里陪他坐满一支舞曲会加分；当面戳穿他的身份、或把自己的名字写进登记簿会掉分","gender":"男","age":"中年","race":"人类（已故）","faction":"眺望旅馆","appearance":"秃顶，剩下的灰发梳得贴头皮，穿白色侍者外套、系黑领结，一手托着银盘。站得笔直，两手总戴白手套，笑的时候嘴角先动、眼睛后动；说话细声细气。盘子上的酒永远是新倒满的，也永远不见少。","traits":["讲规矩","不慌","记仇"],"relations":[{"name":"杰克·托兰斯","label":"他认定为下一任看守人的那个人"},{"name":"温蒂·托兰斯","label":"他想劝回房间里的那位太太"},{"name":"迪克·哈洛伦","label":"旅馆里唯一不肯接他盘子的人"}],"voice":"句子完整、用词讲究，像在念服务手册；被拒绝时只重复同一句话，音量一次比一次低。"}]},{"id":"movie_starwars","category":"movie","canon":"星球大战","name":"星球大战","icon":"🌌","tagline":"把情报送上货船，别让帝国截住","mood":"沙漠、原力、机器人、帝国、走私","guidance":"【原著设定】银河系处在银河帝国的统治下：皇帝解散了议会，用星区总督与冲锋队维持秩序，起义军同盟只能靠秘密基地与散落的情报网对抗。力量体系是原力，一种渗透万物的能量场，绝地武士以光剑、原力感知与推拉、精神暗示作战，西斯则走向掠夺与控制的那一面。星际往来依赖超空间引擎与导航计算机。外环的沙漠行星塔图因由赫特人贾巴的犯罪集团实际控制，帝国在此设有检查站与巡逻队。星球有两颗太阳、漫天沙尘、湿气农场与拾荒的爪哇人；土著塔斯肯袭击者骑着班萨巡游沙丘；太空港莫斯艾斯里有酒馆、机库和各式各样的走私者。机器人分为宇航技工型与礼仪型，会说话的、会开锁的都有。【反复出现的意象】沙丘上缓缓爬行的爪哇人沙行船、酒馆门口被风刮得直响的金属招牌、排水沟旁报废的湿气冷凝器、货舱里用皮带固定的宇航技工机器人、双日落在沙海上拉长的人影。这些画面一出现，玩家就该知道自己站在塔图因。【NPC 类型】在酒馆角落里等人出价的走私船长、替贾巴收账的赏金猎人、把机器人当牲口买卖的拾荒者、检查站上盘问来历的冲锋队军士、自称年轻时见过绝地的老农。【威胁类型】冲锋队的搜查与盘问、赏金猎人的跟踪、塔斯肯袭击者的远程冷枪、酒馆里随时会拔枪的混混，以及沙漠本身：昼夜温差、缺水与沙暴。最要命的是没有身份证明，在被帝国管制的星球上，一个来路不明的人比罪犯更可疑。【奖励风格】爆能枪、光剑、全息投影仪、机器人零件、飞船零件与帝国制式装备；能力偏向原力感知与精神暗示这类不显眼却好用的手段，以及能替人办事的各种机器人。情报与通行许可往往比武器值钱。【不对劲的来源】那台载着情报的机器人，数据里有一段单独存放、没有加密的留言，收信人是玩家，用玩家熟悉的语气说话，发信人自称很久以前就在等这一天。【时间线】固定在《新的希望》开场的塔图因段落：起义军的飞船刚被俘，载着死星图纸的机器人刚降落在沙海里，欧比旺还隐居在沙丘深处，汉·索罗还没有接到那单生意，奥德朗尚未被毁。不要提前启用后续作品的角色与设定（尤达、兰多、波巴·费特、恩多战役、第二死星等一律不出现）。","powerStyle":"原力感知与光剑，配爆能枪","difficultyBias":0,"signatureItems":["光剑","爆能枪","全息投影仪","宇航技工机器人","帝国冲锋队头盔"],"mainQuest":"主线任务：把载着死星图纸的机器人送上离开塔图因的货船，别让它被帝国截获。","mainQuestGoal":"在货船起飞前把机器人送进机库，全程不让情报被任何一方报给帝国，并听清那段留给玩家的私人留言","sideQuests":[{"name":"排水沟里的冷凝器","desc":"替农场修好一台报废的湿气冷凝器，换来一张不在场证明","reward":"积分 150"},{"name":"酒馆里没有机器人","desc":"把机器人从后门带进酒馆又不被酒保赶出去","reward":"道具「全息投影仪」"},{"name":"机库的停机费","desc":"替船长凑齐起飞前必须付清的那笔机库费用","reward":"积分 200"},{"name":"赏金猎人的账单","desc":"弄清贾巴到底派了几个人来找这台机器人","reward":"道具「赏金猎人的记号」"}],"factions":[{"name":"义军同盟","desc":"手里只有一条情报，愿意付出任何代价把它送出去","attitude":"友善"},{"name":"银河帝国","desc":"在太空港设卡搜查机器人，宁可错抓也不放过","attitude":"敌对"},{"name":"赫特人贾巴的犯罪集团","desc":"收钱放行，也收钱出卖你，规矩只有一条：账要清","attitude":"中立"}],"npcs":[{"name":"欧比旺·克诺比","identity":"隐居塔图因的绝地武士，化名本","role":"引导者","personality":"温和、克制，话说一半让人自己想","hook":"他在玩家身上感应到一股不属于这个星系的原力痕迹，愿意用真话换玩家的来历","favorHint":"尊重原力、答应的事做到会加分；把原力当成工具使、或拿机器人当货件看待会掉分","gender":"男","age":"六十岁上下","race":"人类","faction":"绝地（旧共和国遗存）","appearance":"稀疏的灰白头发与短须，脸上皱纹很深。穿褪色的土黄色长袍，外面披一件粗布斗篷，腰间皮带挂着一把旧光剑，剑柄磨得发亮。走路不快，习惯把手拢在袖子里；说话时看着地面，偶尔抬眼直视对方，那一瞬间眼神很年轻。随身的通讯器是老式型号。","traits":["沉稳","克制","有心事"],"relations":[{"name":"卢克·天行者","label":"他在沙丘外一直远远看着的孩子"},{"name":"R2-D2","label":"他认得出来的那台旧机器人"},{"name":"汉·索罗","label":"他不喜欢却不得不用的人"}],"voice":"语速慢，常用反问句与旧事开头；不愿回答时只说一句实话，然后换话题。"},{"name":"汉·索罗","identity":"千年隼号的船长，走私者","role":"盟友","personality":"嘴硬、贪财，关键时刻讲信用","hook":"他开价才肯运那台机器人，可一听说帝国也在找它，就改口只收一半","favorHint":"付钱痛快、不问他欠贾巴多少会加分；当着他质疑飞船、或擅自碰驾驶座会掉分","gender":"男","age":"三十多岁","race":"人类","faction":"走私者（千年隼号）","appearance":"深棕色短发略乱，脸上常带着一种不認真的笑。白衬衫外面套深色背心，腰带低低地挂着枪套，腿侧是擦得发亮的枪把。个子高，站着总把重心压在一条腿上，说话爱歪头挑眉，被说中就耸一下肩。","traits":["油滑","仗义","爱吹牛"],"relations":[{"name":"欧比旺·克诺比","label":"给他开价、也给他添麻烦的老头"},{"name":"卢克·天行者","label":"他嘴上嫌烦、实际不放心丢下的年轻人"},{"name":"格里多","label":"替贾巴上门讨账的那个绿皮家伙"}],"voice":"先抱怨再答应，喜欢用夸张的数字讨价还价；动真格时话变少，只留下一个字的命令。"},{"name":"卢克·天行者","identity":"塔图因上的湿气农场青年","role":"盟友","personality":"急躁、好奇，一心想离开这颗星球","hook":"他认定这趟护送是他离开塔图因的机会，会缠着玩家让他跟到机库","favorHint":"把他当成年人托付任务、教他一两手会加分；叫他小孩、拿农场出身开玩笑会掉分","gender":"男","age":"十九岁上下","race":"人类","faction":"拉尔斯农场","appearance":"金色短发，刘海压在额前，脸晒得发红。穿米白色束腰短衣与宽松长裤，小腿缠着绑带，腰上挂工具袋，修冷凝器时满手油污。兴奋起来语速很快，两只手比划个不停；他的飞行头盔和一副旧护目镜常年丢在车里。","traits":["莽撞","热心","想飞"],"relations":[{"name":"欧比旺·克诺比","label":"他刚知道名字的那位老隐士"},{"name":"汉·索罗","label":"他半信半疑又很想学的那个人"},{"name":"R2-D2","label":"半夜从沙丘里走出来的那台机器人"}],"voice":"疑问句多，喜欢把话说完再征求同意；被拒绝时会立刻提高声音，又很快软下来。"},{"name":"R2-D2","identity":"载着死星图纸的宇航技工机器人","role":"关键人物","personality":"固执、机灵，主意比谁都大","hook":"它明显认得玩家，会主动挡在玩家前面，也会把那段全息留言单独放给玩家看","favorHint":"替它保守情报、照它指的路上走会加分；把它当普通货件、或动手拆它的记忆库会掉分","gender":"男","age":"服役多年（具体不详）","race":"宇航技工机器人（R2 系列）","faction":"义军同盟","appearance":"半人高的圆筒形机身，白色外壳上漆着蓝色纹路，满是沙尘与划痕；靠三条腿行走，圆顶头部能整个旋转，正面的主镜头是一颗发蓝光的圆眼，侧面会伸出小锯、电击棒与数据接口。它不会说通用语，只靠电子音与投影表达情绪，紧张时天线乱转，被人推着走时会用力抵住地面。","traits":["倔强","忠诚","爱自作主张"],"relations":[{"name":"欧比旺·克诺比","label":"它奉命要找到的收信人"},{"name":"卢克·天行者","label":"第一个把它从沙丘里捡起来的人"},{"name":"汉·索罗","label":"它并不信任、却必须搭上的船长"}],"voice":"只有高低起伏的电子音；不赞同就原地转圈并发出短促的连响，着急时用投影打出一串结结巴巴的图。"},{"name":"格里多","identity":"替贾巴收账的罗迪亚族赏金猎人","role":"潜在敌人","personality":"急功近利，自认为很讲规矩","hook":"他把玩家错认成雇主派来的中间人，一边套话一边等赏金涨价","favorHint":"给他准确的情报、替他在贾巴面前说一句话会加分；欠他钱、或让他空手回去会掉分","gender":"男","age":"成年","race":"罗迪亚人","faction":"赫特人贾巴的犯罪集团","appearance":"一米七上下的绿色皮肤人形，头部像蜥蜴，两只眼睛是凸出来的黑色圆球。穿米色背心与深色长裤，肩挎子弹带，腰间别着一把爆能手枪。说话带鼻音，喜欢先摆出讲道理的姿势再掏枪；被拒绝时手指会在枪把上敲两下。","traits":["贪心","多疑","爱面子"],"relations":[{"name":"汉·索罗","label":"他盯了很久的那笔旧账"},{"name":"R2-D2","label":"他不知道值钱在哪、却知道有人肯出价的货"},{"name":"欧比旺·克诺比","label":"他不敢惹、也不想惹的老头"}],"voice":"短句，带呼噜般的鼻音，喜欢重复对方的话再反问；谈钱时语气立刻变得客气。"}]},{"id":"game_witcher3","category":"game","canon":"巫师3","name":"巫师3","icon":"🐺","tagline":"日落之前，问出村子失踪的真相","mood":"沼泽、猎魔人、委托、供品、谎言","guidance":"【原著设定】猎魔人是经草之试炼改造过的人类，靠变异获得超常感官与抗毒体质，用钢剑对付人、银剑对付怪物，配以法印（阿尔德、伊格尼、昆恩、亚克席、亚登）、魔药、剑油与炸弹。怪物源自天球交汇留下的裂口，猎魔人靠告示板上的委托吃饭，按克朗计价。北方诸国正被尼弗迦德帝国入侵，威伦夹在战线之间：它原属泰莫利亚，如今是一片没有主人的沼泽与焦土，实权落在乌鸦窝的血腥男爵手里；村里人则靠着林中夫人（三位被称作老巫妪的女巫）的庇护活着，她们替人消灾，代价是绝对服从，供品包括头发、耳朵，甚至是小孩。永恒之火的教会与女巫猎人同时四处搜捕术士与非人种族。【反复出现的意象】村口钉满委托与讣告的告示板、沼泽面上飘着的绿色瘴气、篱笆上成串挂着的耳朵、下瓦伦村中那幅画着三位夫人的旧挂毯、夜里水面下缓缓移动的灯影。这些画面一出现，玩家就该知道自己站在威伦。【NPC 类型】把供品当税来交的村长、替男爵收粮的武装家丁、背着告示板走村串巷的猎魔人、收费驱邪却自己先怕的巫医、把耳语当神谕的孩子。【威胁类型】沼泽里的水鬼与水鬼婆、夜里出没的食尸生物、尼弗迦德与北方的溃兵、打着教会旗号的女巫猎人，以及最难对付的那一种：全村人一起维护的谎话。在威伦，说出真相的人往往先被村民处理掉。【奖励风格】猎魔人装备与配方：银剑、强化魔药、炸弹、符文石与战利品；能力偏向感官强化、毒素抗性与法印，用一次少一次。钱是硬通货，情报比钱更硬。【不对劲的来源】问同一件事，每个人的说法都不一样：老人说掉进了沼泽，年轻人说跟着货郎走了，抬棺的人说棺材是空的。只有孩子的说法能对上，而且每个孩子的说法都对得上，一字不差，像背下来的一样。【时间线】固定在杰洛特为寻找希里而途经威伦的那段时间：他已经和乌鸦窝的血腥男爵打过交道，林中夫人仍然控制着下瓦伦一带，狂猎的爪牙已经出现在威伦的沼泽里。不要提前启用后面的剧情与地点（史凯利杰、凯尔莫罕保卫战、陶森特，以及《石之心》《血与酒》的内容）。","powerStyle":"猎魔人剑术与法印，靠魔药炸弹","difficultyBias":4,"signatureItems":["狼学派徽章","银剑","燕子药水","舞动之星炸弹","猎魔人委托告示"],"mainQuest":"主线任务：在日落之前查清下瓦伦村连续失踪的真相，把证据带回乌鸦窝。","mainQuestGoal":"在日落前取得可以带回乌鸦窝的物证（供品、尸骨或人证），并让至少一个孩子活着离开下瓦伦","sideQuests":[{"name":"耳朵的数目","desc":"数清篱笆上挂着的耳朵，找出比村里死者多出来的那一对","reward":"积分 200"},{"name":"没有名字的坟","desc":"在村外乱葬坑里找出最近埋下的那具空棺","reward":"道具「一缕头发」"},{"name":"孩子的口供","desc":"把三个孩子分开问话，记录他们的说法并找出重合的部分","reward":"积分 150"},{"name":"挂毯上的第三只手","desc":"在下瓦伦的旧挂毯上找出多画出来的那只手，弄清它指着哪条路","reward":"积分 180"}],"factions":[{"name":"乌鸦窝守军","desc":"血腥男爵的兵，靠收粮和抓人维持威伦仅剩的秩序","attitude":"中立"},{"name":"下瓦伦的信众","desc":"把林中夫人当神供着的村民，谁动供品谁就是敌人","attitude":"敌对"},{"name":"永恒之火教会与女巫猎人","desc":"烧术士、抓非人种族，也顺手把异端一起清掉","attitude":"敌对"}],"npcs":[{"name":"杰洛特","identity":"狼学派猎魔人，正在寻找希里","role":"引导者","personality":"冷淡、务实，嘴上不认心里记事","hook":"他一眼看出玩家身上的气味不对，也看出玩家不属于这片大陆，愿意用一份委托换玩家的来历","favorHint":"按猎魔人的规矩办事、不瞒着他会加分；拿村民的命换情报、或动他的马会掉分","gender":"男","age":"近百岁（外表四十岁上下）","race":"人类（猎魔人变异体）","faction":"狼学派","appearance":"白色长发用皮绳松松扎在脑后，脸瘦而长，左眼到脸颊有一道旧疤。穿黑色皮甲，肩带与腰带上挂满药瓶和刀鞘，背后交叉插着两把剑，一把钢的一把银的，剑柄缠着黑布。站姿松垮，双臂抱胸，说话很少，常用一句短问把话头递回去；闻东西时会皱一下眉。","traits":["冷静","利落","嘴毒"],"relations":[{"name":"凯拉·梅兹","label":"互相利用又互相欣赏的术士"},{"name":"血腥男爵","label":"他不喜欢、却必须打交道的地方军阀"},{"name":"强尼","label":"沼泽里唯一肯说真话的小东西"}],"voice":"句子短，常用陈述句压住情绪；被追问时会先说一句这不关我的事，然后再回答。"},{"name":"凯拉·梅兹","identity":"被通缉的术士，藏身威伦","role":"盟友","personality":"俏皮、精于算计，关键时候不坑自己人","hook":"她手里有失踪村民的旧名册，条件是玩家替她跑一趟沼泽，取回一只还在水下的箱子","favorHint":"替她保密、承认她的本事会加分；把她当男爵的附庸、或打听她为什么被通缉会掉分","gender":"女","age":"三十岁上下","race":"人类（术士）","faction":"术士兄弟会（流亡者）","appearance":"金色长发中分披肩，前额勒一条细发带。穿深绿色开襟长袍，腰封束得很紧，露出的手指上戴着几枚戒指，指甲修得尖而亮。说话时喜欢半转身、用余光看人，笑起来先挑一下眉毛；身上有草药和香水混在一起的味道，随身带着一只装满药瓶的小皮囊。","traits":["机灵","自爱","识时务"],"relations":[{"name":"杰洛特","label":"她愿意合作、也留着一手的老相识"},{"name":"血腥男爵","label":"她口中那个迟早要出事的邻居"},{"name":"林中夫人","label":"她宁可不提、也不愿招惹的三位"}],"voice":"语调轻快，喜欢用玩笑包住条件；谈正事时会把话说得很清楚，然后补一句你最好答应。"},{"name":"血腥男爵","identity":"乌鸦窝的统治者，威伦实际的军阀","role":"关键人物","personality":"粗暴、自厌，还留着一点良心","hook":"他要玩家带回真相，却反复强调别带回任何人的名字；他的地窖里锁着一样和失踪案有关的东西","favorHint":"直话直说、不打听他家里的事会加分；提他妻子与女儿、或在他面前劝酒会立刻掉分","gender":"男","age":"五十岁上下","race":"人类","faction":"乌鸦窝","appearance":"体形厚重的光头男人，脖子上挂着粗项链，穿暗红色军官式外套，靴子上沾着干泥。右手常握一只酒杯，左手不时按在腰间的短刀上。说话声音很大，笑到一半会突然停；酒喝多了眼睛发直，盯着空处一动不动。门厅里挂着一面破旗和一张全家画像。","traits":["暴戾","自弃","护短"],"relations":[{"name":"杰洛特","label":"他既需要又提防的猎魔人"},{"name":"凯拉·梅兹","label":"他眼皮底下住着、却装作不知道的术士"},{"name":"林中夫人","label":"他不信、也不敢碰的沼泽神灵"}],"voice":"声音先压后炸，喜欢用命令句；说到家人时语速变慢，句尾会拖出一个听不清的词。"},{"name":"强尼","identity":"沼泽里的小地灵，孩子口中的朋友","role":"盟友","personality":"好奇、话多，心眼好却办不成事","hook":"他认得沼泽里每一条路，也见过那些被带走的人，可他只能用手比划，玩家得先想办法弄回他的声音","favorHint":"陪他玩、给他带吃的东西会加分；拿他的声音开玩笑、或逼他去找林中夫人会掉分","gender":"男","age":"不详（看起来像个孩子）","race":"小地灵（残物）","faction":"沼泽的散居怪物","appearance":"只有半人高，皮肤灰绿、皱巴巴的，脑袋大得不成比例，一双黄眼睛亮得吓人。穿一件用破布和绳子扎起来的短衣，赤脚，脚趾很脏。走路一跳一跳，说不出话时憋得满脸通红，会用手比划出一长串动作；随身揣着一块舔过的石头和几颗鸟蛋。","traits":["天真","嘴碎","胆小"],"relations":[{"name":"杰洛特","label":"帮他找回声音的人"},{"name":"林中夫人","label":"嫌他恶心、随时能收拾他的三位"},{"name":"凯拉·梅兹","label":"愿意拿药水换他带路的人"}],"voice":"声音又尖又快，说不了几句就笑；一旦被问到林中夫人，立刻改成比划，眼睛往地上看。"},{"name":"林中夫人","identity":"威伦沼泽深处的三位老巫妪，村民供奉的好夫人","role":"潜在敌人","personality":"用慈祥的语气，谈吃人的条件","hook":"她们乐意让玩家替她们查案，条件是玩家把结果连同供品一起送到沼泽深处","favorHint":"收下她们的礼物、当面服从会加分（也会被记上名字）；拒绝供品、或替村民隐瞒会掉分","gender":"女","age":"不详","race":"老巫妪（残物）","faction":"林中夫人","appearance":"三位老妇同住一处：一位整天坐在织机前，指甲长得勾人；一位守在锅边尝味，围裙上溅着暗色的汤；一位总侧着头听，凑得极近才开口。上身是村妇的粗布衣，下半身却看不出人腿的形状。三个人说话像同时讲同一句，尾音叠在一起，笑起来露出黑牙。","traits":["耐心","贪婪","不守约"],"relations":[{"name":"下瓦伦的信众","label":"她们的供品来源与眼睛"},{"name":"强尼","label":"她们口中恶心的东西"},{"name":"杰洛特","label":"她们愿意暂时留着的客人"}],"voice":"三段声音叠成一句，语气温柔，句尾总带一个条件；被拒绝时只重复那个条件，一次比一次慢。"}]},{"id":"game_darksouls","category":"game","canon":"黑暗之魂","name":"黑暗之魂","icon":"🔥","tagline":"火种不能灭，影子越来越多","mood":"营火、不死人、灵魂、黑暗、注视","guidance":"【原著设定】世界正处在火之时代将尽的黄昏。初火渐熄，不死人的诅咒蔓延：被打上黑暗之印的人死后不会真正死去，而是一次次在营火边醒来，直到失去人性、沦落为游尸。罗德兰是众神的旧地，如今只剩下断壁、空城与守着薪火的传说。不死人以灵魂为货币，以营火为疗伤与落脚之处，靠元素瓶回复，用楔形石强化武器。战斗讲究距离、翻滚与盾反，法术与奇迹各有代价。玩家所在的是传火祭祀场：一处围着巨大营火的废墟，向外通往城外不死教区、不死镇、病村、地下墓地，以及更深的巨人墓地。地下墓地里睡着成群的骷髅与尸术师，再往深处就是墓王的地界。【反复出现的意象】祭祀场中央那堆烧不尽的小火与插在灰里的断剑、被火熏黑的石拱、沿路堆着的白色留言石、雾门前隐隐发光的白雾、远处漆黑里缓慢移动的一点火星。这些画面一出现，玩家就该知道自己站在罗德兰。【NPC 类型】坐在营火边不肯出发的不死人、兜售情报与钥匙的商人、追着太阳与赞歌走的光之战士、守着同伴尸体的圣职者、只对灵魂出价而从不相让的铁匠。【威胁类型】成群的不死士兵与活尸、会不断重组的骷髅（除非用神圣武器彻底打散）、地下墓地里的车轮怪与尸术师、巨人与恶魔，以及最根本的那一种：死亡。死亡本身不可怕，可怕的是每次回来都少一点记性、少一点人性，最后连自己为什么出发都想不起来。【奖励风格】元素瓶、人性、楔形石、防火女的灵魂、誓约道具与各类原著的粗粝武器；能力偏向硬碰硬的近战、奇迹与咒术，任何强化都要拿命去换。这里没有商店价格表，只有灵魂的数目。【不对劲的来源】火种越亮，跟着玩家的影子越多。它们从墙缝里、从水面上、从营火照不到的地方长出来，只看，不动手，也不出声；玩家停下来它们就停下来，玩家回头它们就少一个。谁也说不出它们在等什么。【时间线】固定在《黑暗之魂》初代的开局阶段：玩家刚离开北方不死院、抵达传火祭祀场，还没有敲响两口苏醒之钟，防火女仍在铁牢里沉默不语，通往亚诺尔隆德的路尚未打开。不要提前启用后期的角色与设定（黯影太阳葛温德林、半龙普莉希拉、平抚黑暗的卡斯、王城的诸王与最终之战），也不要把《黑暗之魂 3》的洛斯里克、薪王与火祭场混进来。","powerStyle":"翻滚与盾反的硬仗，靠营火续命","difficultyBias":5,"signatureItems":["元素瓶","人性","楔形石碎片","防火女的灵魂","注火秘法"],"mainQuest":"主线任务：把一枚火种从地下墓地送回传火祭祀场，路上不能让它熄灭。","mainQuestGoal":"在火种熄灭之前抵达传火祭祀场并把火种投入营火，途中玩家的人性一次都不能归零","sideQuests":[{"name":"营火要注火","desc":"往祭祀场的营火里多添一次人性，让这团火撑得更久一点","reward":"积分 150"},{"name":"打散而不是打死","desc":"在墓地里找到能把骷髅彻底打散的武器或奇迹，并带一件证明回来","reward":"道具「楔形石碎片」"},{"name":"不必用火照明","desc":"在地下墓地找到一盏能撑到最深处的灯，别拿火种当火把","reward":"积分 200"},{"name":"数影子","desc":"在三个不同的地方回头数一遍跟着你的影子，把数目写在留言石上","reward":"道具「人性」"}],"factions":[{"name":"太阳战士","desc":"一群相信太阳会回应呼唤的人，愿意无偿帮陌生人一把","attitude":"友善"},{"name":"白教","desc":"索尔隆德来的圣职者一行，卖奇迹也卖人情，先看你还剩多少人性","attitude":"中立"},{"name":"墓王的仆从","desc":"守在地下墓地与巨人墓地的尸术师和骷髅，把亡者当材料用","attitude":"敌对"}],"npcs":[{"name":"太阳战士索拉尔","identity":"来自亚斯特拉的太阳战士，太阳战士誓约成员","role":"盟友","personality":"爽朗、执着，愿意出手帮人","hook":"他愿意陪玩家走一趟地下墓地，只是他也想找到属于自己的太阳，而玩家手里那点火光让他很感兴趣","favorHint":"接受他的协助、陪他在营火边坐一会儿会加分；嘲笑他的太阳、或丢下他自己先走会掉分","gender":"男","age":"不详（外表三十余岁）","race":"人类（不死人）","faction":"太阳战士","appearance":"一身铁质铠甲，胸甲正中画着黄色的太阳纹样，头戴带横缝的铁盔，看不见脸。外面披一件已经褪色的白罩袍，腰上挂着直剑与一面圆盾。说话声音亮，笑起来肩膀跟着抖，习惯把手举到眼前做一个朝拜太阳的动作；铠甲上有几处补过的凹痕。","traits":["热情","执着","慷慨"],"relations":[{"name":"女神的骑士罗特雷克","label":"同为不死人，却总让他觉得不对劲的同行者"},{"name":"亚斯特拉的安娜塔西亚","label":"他想为她做点什么、却搭不上话的防火女"},{"name":"灰心的战士","label":"他每天都想劝动一次的邻居"}],"voice":"声音大，喜欢把话说得很亮，常把太阳和伙伴挂在嘴边；被打断也不生气，笑着重说一遍。"},{"name":"亚斯特拉的安娜塔西亚","identity":"传火祭祀场的防火女","role":"引导者","personality":"沉默、逆来顺受，把火看得比自己重","hook":"她几乎不开口，却认得玩家手里那枚火种，她比谁都清楚那点火是从哪里来的","favorHint":"把火种完好带回、不追问她的过去会加分；问她的舌头、或去碰她的牢门会掉分","gender":"女","age":"不详","race":"人类（防火女）","faction":"传火祭祀场","appearance":"极短的灰发贴着头皮，脸色惨白，眼窝深陷。头上罩着一顶金白相间的头饰，遮住上半张脸；穿一件脏污的白色长裙，赤脚，脚踝上套着沉重的铁镣，坐在祭祀场下方的小铁牢里，双手交叠放在膝上。她说话时几乎不动，只有嘴唇开合。","traits":["沉默","顺从","认命"],"relations":[{"name":"灰心的战士","label":"每天从她牢门前走过、从不说话的人"},{"name":"女神的骑士罗特雷克","label":"总坐在她对面盯着她看的金甲骑士"},{"name":"太阳战士索拉尔","label":"唯一会朝她点头致意的客人"}],"voice":"声音很轻，句子极短，常说请、火、留下三个词；被追问时只是低头，不再回答。"},{"name":"灰心的战士","identity":"坐在传火祭祀场营火边的老兵","role":"中立","personality":"满嘴丧气话，知道的事却最多","hook":"他第一个告诉玩家地下墓地的路，也第一个劝玩家别去；他知道影子的事，却只肯用玩笑讲","favorHint":"听他讲完牢骚、分他一点灵魂会加分；当面说他懦弱、或问他为什么不去敲钟会掉分","gender":"男","age":"中年","race":"人类（不死人）","faction":"传火祭祀场","appearance":"破旧的锁子甲外面套着灰色罩袍，头戴链甲头巾，膝盖与手肘处都已磨破。总坐在同一个石阶上，弓着背、手肘搭在膝上，一只手托着下巴。笑起来是干笑，开口前先叹一口气；脚边放着一把锈迹斑斑的直剑和一面豁了口的小盾。","traits":["丧气","嘴碎","门清"],"relations":[{"name":"太阳战士索拉尔","label":"他嘴上嫌吵、心里羡慕的那种人"},{"name":"亚斯特拉的安娜塔西亚","label":"他每天路过却假装看不见的防火女"},{"name":"女神的骑士罗特雷克","label":"他劝玩家离远一点的那个人"}],"voice":"先叹气再说话，喜欢用反问和自嘲；被夸一句会愣住，然后换个更难听的说法。"},{"name":"女神的骑士罗特雷克","identity":"来自卡利姆的骑士，信仰宠爱女神菲娜","role":"潜在敌人","personality":"优雅、虚伪，把杀当作敬神","hook":"他愿意和玩家同行一段，条件是玩家别问他去亚诺尔隆德做什么；他对那位防火女格外上心","favorHint":"放他出牢房、收下他的谢礼会加分；戳穿他的目的、或在他面前靠近防火女的牢门会掉分","gender":"男","age":"不详","race":"人类（不死人）","faction":"卡利姆","appearance":"一身金色重甲，胸甲两侧像两只环抱的手，头戴形状怪异的金色头盔，盔顶镶着一圈尖齿，盔下只露出半张脸，笑容恒定。说话慢而客气，尾音总带一声轻哼；腰间挂着两把弯曲的短刀，走路时铠甲发出细碎的响声。","traits":["优雅","伪善","记仇"],"relations":[{"name":"亚斯特拉的安娜塔西亚","label":"他真正盯着的目标"},{"name":"灰心的战士","label":"他懒得掩饰轻视的邻居"},{"name":"太阳战士索拉尔","label":"他不介意并肩、也不介意抛下的人"}],"voice":"句子客气，爱用请与劳驾，尾音带一声哼；被拒绝时仍笑着，只把话说得更慢。"},{"name":"三人尸术师","identity":"潜伏在地下墓地最深处的尸术师","role":"对手","personality":"不开口，只分身，把亡者当材料","hook":"它守着玩家要找的那枚火种，也守着比火种更值钱的东西；它知道玩家身上的黑暗之印是谁盖上去的","favorHint":"不打断它的仪式、与它的分身保持距离会加分；抢走火种、或在它面前提墓王的名字会掉分，它会多放出一轮分身","gender":"男","age":"不详","race":"人类（尸术师）","faction":"地下墓地","appearance":"一件宽大的黑色法袍下看不出身形，脸上并排罩着三张白色的假面，一张是父亲、一张是母亲、一张是孩子。袖口伸出枯瘦的手，掌心浮着迟迟不落下的火球。三张面具同时开合，声音叠成一片；被打散时会从地上重新聚起来，面具上的裂纹一次比一次多。","traits":["阴森","耐心","不死"],"relations":[{"name":"墓王的仆从","label":"它偷来力量、又不得不躲着的旧主"},{"name":"灰心的战士","label":"在祭祀场里替它劝退过不少人的那张嘴"},{"name":"太阳战士索拉尔","label":"唯一敢一路追到它门口的不死人"}],"voice":"三张面具同时说话，声音叠在一起，吐字慢；从不说完整句子，只重复玩家说过的最后两个字。"}]},{"id":"game_skyrim","category":"game","canon":"上古卷轴5","name":"上古卷轴5","icon":"🐉","tagline":"暴雪停前，把商队的人带回来","mood":"暴雪、天际、内战、巨龙、商队","guidance":"【原著设定】故事发生在泰姆瑞尔大陆的天际省，时间是第四纪元 201 年。天际正陷内战：乌弗瑞克·风暴斗篷以塔洛斯信仰与自治为名起兵，帝国军团在图留斯将军指挥下守着独孤城与白漫城；与此同时，被放逐的巨龙奥杜因归来，龙开始在各领地上空盘旋，传说中的龙裔已经出现。天际分为九个领地，各有领主与首府。北方的苍原领首府是海边的晨星城，靠捕鱼与两座矿坑过活，领主是支持风暴斗篷的长老斯卡德；城里木屋连片、城墙早已倒塌，因此格外招龙。虎人商队不被允许进城，只能带着货在城外扎营。风雪一起，路就没了。【反复出现的意象】插在雪里、写满赏金与委托的告示板、长屋里烧着鲸油灯的木桌、城门外的商队帐篷与并排的货箱、被雪压塌半边的谷仓、天上盘旋时投在地上的巨大影子。这些画面一出现，玩家就该知道自己站在苍原领的雪里。【NPC 类型】张口就是帝国与风暴斗篷的守卫、在酒馆里赊账的矿工、替领主跑腿却满腹牢骚的管家、赶着雪橇却不太认路的车夫、把龙当成酒桌笑话的老猎人。【威胁类型】暴雪与失温、雪原上的狼群与剑齿虎、龙袭击后四散的火球与坠落的残骸、拦路的强盗与弃誓者，以及梭默审判者——他们名义上维持和平，实则把任何一句话都当把柄。风停不下来，人就回不去。【奖励风格】铁制与钢制武器、附魔装备、治疗与抗寒药水、法术卷轴、金锭与龙鳞龙骨一类材料；能力偏向战士、法师、盗贼三条路，外加龙吼。钱在这里最通用，酒和口粮能换命。【不对劲的来源】货车还停在原地，货物一件没少，马也没有挣脱，可车辙是朝着天上去了：两道深深的辙印从雪地里抬起，像有什么东西连车带人一起提了起来。镇上没人愿意抬头看。【时间线】固定在龙裔刚出现、内战仍在僵持的阶段，地点是晨星城与苍原领的雪原。不要提前启用后期才登场的角色与设定（内战分出胜负后的领主更替、黑暗兄弟会的圣所任务线、黎明守卫与龙裔 DLC 的内容，以及一切只有龙裔本人才会触发的剧情）。","powerStyle":"剑盾、法术或潜行，还有龙吼","difficultyBias":2,"signatureItems":["治疗药水","附魔长剑","抗寒药水","龙鳞","赏金告示"],"mainQuest":"主线任务：在暴雪停之前找到失踪的商队，把活着的人带回晨星城。","mainQuestGoal":"在暴雪停止前找到货车与活着的人，弄清车辙为什么会朝天上走，并把幸存者带回晨星城","sideQuests":[{"name":"城外的帐篷","desc":"把商队留在地里的货箱挪进城洞，别让雪把它压塌","reward":"积分 150"},{"name":"噩梦的价钱","desc":"在风岳旅店里守一夜，记下谁在梦里喊了同一个名字","reward":"道具「抗寒药水」"},{"name":"矿坑里的名字","desc":"把矿工名册补齐，找出跟着商队走掉的那两个人","reward":"积分 180"},{"name":"龙骸的爪距","desc":"在雪原上找到一具冻硬的龙骸，量一量爪距和车辙的间距","reward":"道具「龙鳞」"}],"factions":[{"name":"虎人商队","desc":"不被允许进城、只能在墙外扎营的行商，知道每条雪路和每个哨卡","attitude":"友善"},{"name":"风暴斗篷","desc":"晨星城归他们，他们对来路不明的人只给一次机会","attitude":"中立"},{"name":"梭默审判者","desc":"以维持和平为名巡查各领，把每句失言都记进卷宗","attitude":"敌对"}],"npcs":[{"name":"斯卡德领主","identity":"苍原领领主，晨星城的统治者","role":"引导者","personality":"固执、易怒，张口就是战争","hook":"他要玩家把商队找回来，不是为了同情，而是为了货、税金，还有不能让别的领地看笑话","favorHint":"附和他的战争论调、把功劳报给晨星城会加分；提帝国、提停战、或替虎人说话会掉分","gender":"男","age":"六十岁上下","race":"诺德人","faction":"风暴斗篷","appearance":"灰白头发稀疏，编成两股垂在耳后，下颌的胡子没修齐。穿深色皮甲，外面罩一件镶毛边的长风衣，胸前别着风暴斗篷的熊头徽记。坐在白色会堂的高背椅上，一只手不停敲扶手，开口前先喷一口气；手边总有一角蜜酒，眼睛浑浊却盯着人不放。","traits":["顽固","好战","多疑"],"relations":[{"name":"依兰杜尔","label":"他信不过、又不得不借重的暗精灵祭司"},{"name":"贝提尤德","label":"替他交税、也敢当面顶他的矿主"},{"name":"西塞罗","label":"有人在城外公路上见过、他不愿多问的那个人"}],"voice":"嗓门大、爱拍桌子，句子短而肯定；被顶撞时先骂帝国，再骂年轻人，最后才回到正题。"},{"name":"依兰杜尔","identity":"玛拉神庙的祭司，曾在唤夜神殿出事","role":"盟友","personality":"温和、谨慎，对过去闭口不谈","hook":"他愿意跟着玩家进雪原，因为他认得那些做噩梦的人的描述，也因为他欠晨星城一笔旧账","favorHint":"尊重他的信仰、听他念完一段祈祷会加分；逼他讲唤夜神殿那一夜、或拿他的出身开玩笑会掉分","gender":"男","age":"中年","race":"暗精灵（丹莫）","faction":"玛拉教会","appearance":"深灰蓝色的皮肤，尖耳朵，红眼睛；光头，额上纹着暗色刺青。穿橙黄色法袍，外面披一件厚斗篷，腰间挂着玛拉的护符和一本翻旧的祈祷书。说话慢、声音低，习惯双手交叠在身前；被问到过去时会停下来整理袖口，再换个话题。","traits":["温和","内疚","可靠"],"relations":[{"name":"斯卡德领主","label":"把他留在城里、却从不信任他的领主"},{"name":"贝提尤德","label":"常来找他讨失眠药水的矿主"},{"name":"西塞罗","label":"他在公路上遇见后一直后悔的那个人"}],"voice":"语速平缓，先安抚再提问；触及往事时只说一句我那时做了错事，然后沉默。"},{"name":"贝提尤德","identity":"碎铁者矿坑的经营者","role":"中立","personality":"刻薄、勤快，把矿当成命","hook":"她的矿工里有两个人跟着那支商队走了，她想知道他们是被雪埋了还是跑了","favorHint":"提起她的矿、帮她把工人找回来会加分；把她的矿和前夫那座矿放在一起比较会掉分","gender":"女","age":"四十岁上下","race":"诺德人","faction":"晨星城","appearance":"体格结实的女人，褐色头发用布巾包着，脸上有常年矿尘留下的斑。穿粗布衬衫与皮围裙，袖口卷到肘上，小臂肌肉明显，手上全是老茧。说话又冲又快，习惯一边说一边比划抡镐的动作；腰带上挂着一把小锤和一只钱袋。","traits":["强硬","勤快","记仇"],"relations":[{"name":"斯卡德领主","label":"她照章纳税、也当面顶撞的领主"},{"name":"依兰杜尔","label":"唯一肯听她抱怨的人"},{"name":"虎人商队","label":"她长期打交道的买主，也是她不肯明说在意的人"}],"voice":"开口就是价钱和工期，语速快；说到失踪的工人时声音低下去，用手指敲腰带上的锤子。"},{"name":"希鲁斯·维西欧斯","identity":"晨星城神话黎明博物馆的主人","role":"潜在敌人","personality":"文雅、自负，把危险当收藏品","hook":"他愿意把商队失踪前的路线图卖给玩家，代价是玩家替他从货车上取回一件不该出现在雪地里的东西","favorHint":"认真听他的家族史、替他保守博物馆的事会加分；说他的祖先是疯子、或去碰展柜里的东西会掉分","gender":"男","age":"三十多岁","race":"帝国人","faction":"神话黎明（后人）","appearance":"黑色短发梳得整齐，鬓角修得很短。穿深红色丝绒外套配高领衬衫，手指上戴着两枚刻符文的戒指。说话像在讲课，喜欢背着手在展柜之间踱步；一提到祖先的事业就眼睛发亮、声音压低。博物馆墙上挂着一面被火燎过的旧旗。","traits":["博学","偏执","危险"],"relations":[{"name":"斯卡德领主","label":"把他当怪人、又每年收他税金的领主"},{"name":"依兰杜尔","label":"他乐于当众质疑其信仰的祭司"},{"name":"西塞罗","label":"他一眼就看出不正常、却想收藏的那种人"}],"voice":"用讲解的口吻，爱引年份与家谱；被冒犯时不发火，只把话说得更慢、更客气。"},{"name":"西塞罗","identity":"黑暗兄弟会的守护者，正带着夜母的棺木赶往晨星圣所","role":"潜在敌人","personality":"疯癫、话多，杀意来得毫无预兆","hook":"他在雪里守着一辆断了轴的货车，说他在等母亲的名字被念出来；他见过天上有东西把另一辆车提走","favorHint":"陪他说话、称赞他的车和他的母亲会加分；去碰那口棺木、或说黑暗兄弟会已经完了会立刻掉分","gender":"男","age":"中年","race":"帝国人","faction":"黑暗兄弟会","appearance":"小丑打扮：红黑两色的紧身衣与半边长裤，头戴一顶缀着铃铛的尖帽。脸上的皱纹很深，笑起来咧到耳根，眼圈发黑像很久没睡。腰间别着一把细长的匕首，指关节发白。走路一颠一颠，笑到一半会突然停下侧头去听；说话时把母亲两个字念得又轻又长，随身带着一本写满批注的日志。","traits":["癫狂","忠诚","危险"],"relations":[{"name":"依兰杜尔","label":"在路边替他看过伤的祭司，他记着这份情"},{"name":"希鲁斯·维西欧斯","label":"让他觉得有趣的收藏家"},{"name":"斯卡德领主","label":"他路过晨星城时最想捉弄的那种大人物"}],"voice":"忽高忽低，句尾常带一声笑；说到母亲时立刻变得温柔安静，说到别人时改成一连串押韵的短句。"}]},{"id":"game_zelda","category":"game","canon":"塞尔达传说","name":"塞尔达传说","icon":"🔺","tagline":"解开全部机关，天色却越来越快","mood":"古代神庙、机关、符文、试炼、催促","guidance":"【原著设定】海拉鲁是一块由女神与三角神力守护的大陆。一百年前，灾厄盖侬苏醒，希卡族留下的守护者与四台神兽被反过来操控，王国在一夜之间覆灭：国王阵亡，四英杰战死，公主塞尔达独自留在海拉鲁城堡压制灾厄，重伤的林克则被送进复苏神庙，沉睡百年。如今希卡族的古代神庙散布各地，每一座都是为勇者准备的试炼：里面有机关、导轨、火焰、水与风力装置，能用的手段是希卡石板里的符文——磁力、制冰、遥控炸弹、时间静止。通关后会得到试炼通过证，可以拿去换体力与心之容器。武器会损耗，防寒与耐热要靠衣物和食物，天上散布着希卡塔，靠滑翔伞从高处落下。夜里偶尔升起血月，被击倒的魔物会重新站起来。【反复出现的意象】草丛里探出的守护者残骸与它亮起的红点、半埋在地里的神庙入口与发着橙光的纹样、石板投射出的蓝色符文光束、路边架着锅的篝火、血月升起时被染红的那片天。这些画面一出现，玩家就该知道自己站在海拉鲁。【NPC 类型】守在村口盘问来历的希卡族老人、在路边卖烤苹果的旅人、研究古代科技研究到走火入魔的学者、躲在草丛里偷袭的依盖队刺客、把神庙当成祖产的守庙人。【威胁类型】守护者的激光锁定、依盖队的伏击、夜里成群的魔物与血月之后的复活，以及纯粹的消耗：武器会断、体力会见底、雨天爬不上崖。神庙里的机关不杀人，它们只让人一遍遍重来。【奖励风格】试炼通过证、古代零件、宝箱里的武器与防具、料理与药剂；能力偏向道具与机关解法，讲究用手边现成的东西想出一条路，而不是硬拼。这里最好的奖励常常是能带走的新解法。【不对劲的来源】每解开一层，外面的天色就快一分，像在催人：进去时是清晨，出来可能已是黄昏，再进一层出来就成了深夜。神庙里没有钟，可玩家能听见海拉鲁城堡方向传来规律的、沉闷的呼吸声，一进一出，和天色同步。【时间线】固定在林克刚离开复苏神庙与初始台地、还没有解放任何一台神兽的时期：四英杰已经死去百年，英帕和普尔亚都还在等消息，大师之剑仍插在森林深处。不要提前启用后期的角色与设定（四英杰的幽灵在神兽深处的对话、剑之试炼与追加内容，以及《王国之泪》的天空岛、瘴气与左纳乌装置）。","powerStyle":"符文解谜为主，武器会损耗","difficultyBias":1,"signatureItems":["希卡石板","试炼通过证","滑翔伞","遥控炸弹","耐寒料理"],"mainQuest":"主线任务：解开一座古代神庙里的全部机关，取出最深处那件东西。","mainQuestGoal":"在神庙最深处取得那件东西并原路出来，途中不能在同一层连续停留超过一次天黑","sideQuests":[{"name":"守庙人的拓片","desc":"替守庙的老人把入口的纹样拓下来，别让依盖队先动手","reward":"积分 150"},{"name":"火把与风","desc":"用最少的火把点亮神庙里的全部引火盆，才算解开一层","reward":"道具「遥控炸弹」"},{"name":"试炼的账本","desc":"统计这一带已亮起的庙数与年份，找出对不上的那一座","reward":"积分 200"},{"name":"血月下的空锅","desc":"在血月升起前，把路边那口锅里的料理分给过路的旅人","reward":"道具「耐寒料理」"}],"factions":[{"name":"希卡族","desc":"守着古代科技与旧誓约的一族，两座研究所里还亮着灯","attitude":"友善"},{"name":"依盖队","desc":"背叛希卡族的刺客组织，认灾厄盖侬为主，专抢古代遗物","attitude":"敌对"},{"name":"海拉鲁的幸存者","desc":"散在村落与驿站里的人，先看你是不是灾厄那边的东西","attitude":"中立"}],"npcs":[{"name":"英帕","identity":"希卡族族长，卡卡利科村的守护者","role":"引导者","personality":"严厉、守旧，把职责放在感情前面","hook":"她手上有玩家在神庙里留下的试炼记录，也认得石板里多出来的那一段不属于海拉鲁的数据","favorHint":"按希卡族的规矩办事、把神庙里看到的事如实告诉她会加分；拿一百年前的事当闲话、或在神像前失礼会掉分","gender":"女","age":"老年（百余岁）","race":"希卡族","faction":"希卡族","appearance":"矮小的老妇，白发在头顶盘成紧髻，脸上皱纹很深，眼睛却很亮。头戴一顶高高的尖顶帽，帽身正面画着希卡族的大眼纹样，身穿深蓝色长袍，外罩绣纹披肩。多数时候盘腿坐在垫子上，很少起身；说话前先把手里的念珠放好。","traits":["严厉","尽职","念旧"],"relations":[{"name":"普尔亚","label":"她的妹妹，也是她最不放心的研究者"},{"name":"林克","label":"她替姐姐守了一百年的那个人"},{"name":"可盖大人","label":"她提起就皱眉的叛徒首领"}],"voice":"声音不高，句子整齐，常用古旧的措辞；说到公主时会停一下，把话岔开去讲任务。"},{"name":"普尔亚","identity":"哈特诺古代研究所的所长，希卡族研究者","role":"盟友","personality":"自负、精力过剩，把危险当实验数据","hook":"她一眼看出玩家身上的时间不对，愿意用一次石板升级换一次测量","favorHint":"配合她的实验、夸她的研究会加分；说她像小孩子、或打断她记录数据会掉分","gender":"女","age":"实际百余岁，看起来六七岁","race":"希卡族","faction":"希卡族（古代研究所）","appearance":"身形像个六七岁的孩子，白色短发扎成两个小髻，鼻梁上架着一副比脸还大的圆框眼镜。穿白色研究袍，外面罩一件印着希卡纹样的外套，口袋里塞满笔记与零件。说话又快又高，喜欢站在箱子上俯视别人，说到兴奋处会跳起来；手里总握着一支炭笔。","traits":["自负","跳脱","痴迷研究"],"relations":[{"name":"英帕","label":"她的姐姐，也是唯一能让她闭嘴的人"},{"name":"洛贝利","label":"同门的老对手，比谁先复原古代兵装"},{"name":"林克","label":"她亲手照看过的那个实验对象"}],"voice":"语速极快，夹着自创的编号与术语；被质疑时先哼一声，再用一句话把人说服。"},{"name":"洛贝利","identity":"阿卡莱古代研究所的研究者，专攻古代兵装","role":"盟友","personality":"热情、咋咋呼呼，对武器走火入魔","hook":"他愿意把古代兵装的图纸给玩家，只要玩家从神庙里带回一件还热着的零件","favorHint":"带古代零件给他、称赞他的发明会加分；说他的研究没用、或去碰他那副护目镜会掉分","gender":"男","age":"老年","race":"希卡族","faction":"希卡族（古代研究所）","appearance":"白胡子垂到胸口，剃着光头，额上架着一副巨大的护目镜，镜片被磨得发花。穿深色工作服，外面罩一件缝满口袋的围裙，手套只戴左手。说话嗓门很大，笑起来拍自己的大腿，走路有点跛；工作台上永远摆着拆到一半的守护者零件。","traits":["热忱","粗声大气","专注"],"relations":[{"name":"普尔亚","label":"几十年没分出胜负的同门"},{"name":"英帕","label":"他见了会立刻收起玩笑的族长"},{"name":"林克","label":"他愿意把所有图纸都交出去的那个人"}],"voice":"声音洪亮，爱用惊叹词开头；讲到机械时一口气说不完，讲到人时只挥手说一句那不重要。"},{"name":"林克","identity":"沉睡百年后醒来的勇者","role":"关键人物","personality":"沉默、可靠，肚子饿得很快","hook":"他会跟着玩家进神庙，但每层都停下来等玩家先动手，他似乎知道玩家解得比他快","favorHint":"分他吃的、等他一起走会加分；抢他开出的宝箱、或嘲笑他从高处摔下来会掉分","gender":"男","age":"外表十七岁上下（实际沉睡百年）","race":"海利亚人","faction":"海拉鲁王国（幸存者）","appearance":"金色短发在脑后扎成一小束，蓝色眼睛，左耳戴着一枚蓝色耳环。穿蓝色束腰外衣，胸前与袖口有白色绣纹，下身是米色长裤与皮靴，背上背着盾和一把随手捡来的武器。很少开口，用点头和眼神回应；饿的时候会盯着锅看，从高处跳下时习惯张开双臂、抓稳滑翔伞。","traits":["沉默","可靠","好奇"],"relations":[{"name":"塞尔达","label":"他还没有想起来、却一直听见的那个声音"},{"name":"英帕","label":"替他守了一百年秘密的老人"},{"name":"可盖大人","label":"总在半路跳出来找麻烦的对头"}],"voice":"几乎不说话，只用点头、摇头和一声短促的语气词；被问到过去时会按住胸口停一秒。"},{"name":"可盖大人","identity":"依盖队的首领，灾厄盖侬的追随者","role":"对手","personality":"自大、爱摆架子，一输就跑","hook":"他认定玩家偷了属于依盖队的东西，每次出现都换个花样讨回去，也每次都把自己摔进坑里","favorHint":"当着他的面夸依盖队的排场、放走他的手下会加分（他会送你香蕉）；抢他的台词、笑他摔跤会掉分","gender":"男","age":"中年","race":"海利亚人（依盖族）","faction":"依盖队","appearance":"体形圆胖，光头，脸上罩着一副只露出眼睛的白色面罩，额头画着倒过来的希卡大眼纹样。穿深红与黑色相间的紧身制服，腰上系粗腰带，脚踩布靴。说话拖长调子、句尾上扬，动手前先摆好姿势；随身带着一串香蕉，常吃得满手都是。","traits":["自大","滑稽","缠人"],"relations":[{"name":"英帕","label":"他嘴上不服、心里发怵的希卡族长"},{"name":"林克","label":"他每次都想赢、每次都输的那个人"},{"name":"普尔亚","label":"他派人盯了很久的研究所"}],"voice":"语调夸张，喜欢自称大人、把手下叫成小的们；被打断时会先愣一下，再重新摆姿势把台词说完。"}]},{"id":"game_thelastofus","category":"game","canon":"最后生还者","name":"最后生还者","icon":"🍄","tagline":"雨季的隔离区，影子先动了","mood":"真菌、隔离区、雨季、走私、感染者","guidance":"【原著设定】二十年前一场真菌疫病把大部分人类变成感染者，活下来的人一部分住进军方设立的隔离区，按配给与宵禁过日子，另一部分散在墙外结成民兵、猎团与匪帮。病原是虫草菌的变异株，通过孢子与咬伤传播；感染者分阶段，跑者仍保留人形只会扑咬，循声者双目失明、以回声定位，巨无霸体表覆满厚甲几乎打不动。隔离区由联邦救灾署管理，实行配给券、通行证与宵禁，违规者不经审判直接处置；墙外的走私者靠夹带药品、武器与情报挣钱，收费按件算，不讲人情。【反复出现的意象】检查站探照灯扫过湿草地的光柱、被雨水泡软的配给券、军用背包侧袋里插着的一支抗生素、墙根上被人用粉笔画出的逃生箭头、路边翻倒的婴儿车里积的雨水。这些画面一出现，玩家就该知道自己站在隔离区边缘。【NPC 类型】按件收费的走私者／只认配给券的检查站士兵／把地图画在防水布上的向导／墙外自成一套规矩的猎人／拿情报换子弹的中间人。【威胁类型】循声者的回声、雨天里听不出方向的脚步、把活人当货的匪帮、巡防队的搜查与当场处置、以及被咬后那段无法预测的潜伏期。【奖励风格】手枪与左轮、霰弹枪、烟雾弹与燃烧瓶、急救包与绷带、防毒面具、匕首与弹簧刀一类自制工具；能力偏向潜行、静音处决、短时爆发与包扎自救，全部会磨损与耗尽。【不对劲的来源】这个世界对伤口有明确规矩：被咬就当已经死了，没有人例外。可真正让人不安的是影子——雨天光线散，人的影子本该糊成一团，有些人的影子却比人先动，而且动得更稳。【时间线】建议固定在疫病爆发后第二十年的秋到次年夏：乔尔与泰丝仍在波士顿隔离区做走私，萤火组织还在招人，疫病尚未出现任何可用的疫苗。不要提前启用后期才登场的角色与设定。","powerStyle":"潜行与自制道具向：匕首、燃烧瓶、霰弹枪","difficultyBias":1,"signatureItems":["防毒面具","配给券","急救包","燃烧瓶","磨旧的军用水壶"],"mainQuest":"主线任务：替雇主把一名被咬伤的女孩从隔离区护送到墙外接应点，途中必须避开所有巡防与感染者。","mainQuestGoal":"在雨季结束前把人送到指定接应点，并在一路上始终没有向任何人透露她的咬伤","sideQuests":[{"name":"湿透的通行证","desc":"把一张被雨泡烂的通行证换出检查站，全程不让持证的人露面","reward":"积分 150"},{"name":"药房里少的一格","desc":"摸进一家被搬空的药房，把藏在货架夹层里的那盒抗生素带出来","reward":"道具「急救包」"},{"name":"巡防队的缺口","desc":"在三处岗哨之间找出无人值守的那条缝，把时间记下来交给走私者","reward":"积分 200"},{"name":"墙根上的粉笔箭头","desc":"沿着箭头走到底，看看是谁在墙根上反复标同一条路","reward":"道具「手绘防水地图」"}],"factions":[{"name":"联邦救灾署隔离区","desc":"以配给与宵禁维持秩序的军方管理区，容忍走私者存在，也随时能处置他们","attitude":"中立"},{"name":"萤火组织","desc":"相信疫苗仍在可能的抵抗组织，收拢墙外幸存者，愿意为研究付出代价","attitude":"友善"},{"name":"猎团","desc":"墙外自立法度的武装团体，把落单的人当储备粮食，交易与狩猎只差一道线","attitude":"敌对"}],"npcs":[{"name":"乔尔","identity":"波士顿隔离区的走私者","role":"引导者","personality":"沉默寡言，把话省到只剩必要的部分","hook":"他清点装备时发现少了一件，而玩家背包里那件的磨损方式和他手上那件一模一样","favorHint":"按点到位、不浪费子弹、把同行者当人看会加分；逞英雄、乱开枪、拿他的工具当玩意儿会掉分","gender":"男","age":"四十余岁","race":"人类","faction":"波士顿隔离区的走私者","appearance":"灰白夹杂的短发，下颌一圈修剪得很短的花白胡须。深色牛仔夹克洗得发白，里面是深灰格纹衬衫，肩上挎一只帆布背包，表带磨出毛边。他走路时上半身微微前倾，眼睛总先扫出口再扫人，手腕上带着一道旧疤。腰间挂一把左轮，右手常插在夹克口袋里。","traits":["沉稳","寡言","护短"],"relations":[{"name":"泰丝","label":"多年的搭档，把后路交给对方的那一种"},{"name":"比尔","label":"墙外少数还肯合作的人，彼此都嫌对方麻烦"},{"name":"玛琳","label":"雇主，也是他一直不太信任的那种人"}],"voice":"句子短，常用一个词收尾；被追问细节时先沉默两秒，再只回答能回答的那半句。"},{"name":"泰丝","identity":"波士顿隔离区的走私者，乔尔的搭档","role":"盟友","personality":"干脆利落，讲明白的规矩绝不改","hook":"她认出玩家翻墙的手法和她以前带过的一个新人一样，于是把人留在自己身边用","favorHint":"谈定的价照办、出事时把她的人带回来会加分；中途改口、临阵退缩、拿她的货去送人情会掉分","gender":"女","age":"三十余岁","race":"人类","faction":"波士顿隔离区的走私者","appearance":"深红棕短发，后颈剃得很短，右颊有一道很浅的旧痕。深灰背心套在白色短袖外，腰间系一条宽皮带，皮带上挂着两枚弹匣和一把匕首。她比乔尔矮半个头，站着习惯把重心压在左腿上，听人说话时微微偏头。左手腕缠着运动绷带，指节上常年有伤。","traits":["利落","严谨","重诺"],"relations":[{"name":"乔尔","label":"搭档，也是唯一能让她改主意的人"},{"name":"玛琳","label":"旧识，谈交易时会互相留半步"},{"name":"罗伯特","label":"欠她一笔货的军火贩子，她一直记着这笔账"}],"voice":"语速快、句子干净，先把价钱和时间说清；不耐烦时会直接跳到最后一句结论。"},{"name":"玛琳","identity":"萤火组织在波士顿一带的负责人","role":"关键人物","personality":"目标明确，能为了大局把私人感情往后压","hook":"她手里那份转运名单上已经有了玩家的编号，只是接应点那一栏还空着","favorHint":"守口如瓶、按时交接、不打听任务之外的事会加分；拆开她封好的东西、把伤员随便交给别人会掉分","gender":"女","age":"三十余岁","race":"人类","faction":"萤火组织","appearance":"黑色长发分股编起再在脑后束紧，额前留几缕碎发。灰绿色军用外套袖口磨破，里面是深色高领打底，肩上用细链挂着一枚萤火组织的徽记。她站得很直，说话时左手常按在摊开的地图上，右肩有一道从领口延伸下去的旧疤。鞋是走远路用的厚底靴。","traits":["坚定","克制","隐忍"],"relations":[{"name":"乔尔","label":"她雇佣的人，也是她不得不让步的对象"},{"name":"泰丝","label":"能平起平坐谈条件的旧识"},{"name":"艾莉","label":"她押上全部赌注的那个人，也是她最不愿亲口说出代价的人"}],"voice":"语气平稳，习惯先叫对方的名字再讲条件；谈到代价时会停一下，然后把话说完。"},{"name":"大卫","identity":"墙外猎团的头目","role":"潜在敌人","personality":"说话温和有耐性，把掠夺说成互惠","hook":"他开出的条件好得反常，还特意提到玩家身边那个孩子的体温","favorHint":"保持距离、只做一次交易就抽身会加分；接受他的招待、透露队伍的人数和去向会掉分","gender":"男","age":"四十余岁","race":"人类","faction":"猎团","appearance":"深褐短发向后梳，络腮胡浓密，笑的时候眼睛不跟着动。深色厚呢外套下面穿着立领的深色衬衫，领口扣到最上一颗，像是传教的人。他手掌粗大，指缝里嵌着洗不掉的黑泥，随身带一把猎刀和一本边角卷起的旧书。说话时习惯微微低头看人。","traits":["伪善","耐心","危险"],"relations":[{"name":"艾莉","label":"他真正盯上的猎物，也是他算错的那一步"},{"name":"乔尔","label":"一个他低估了的对手，代价由他的人来付"},{"name":"玛琳","label":"他知道萤火在找什么，于是也在找同一样东西"}],"voice":"语速很慢，先讲道理再提要求，从不威胁；被打断时会安静地等对方说完。"},{"name":"比尔","identity":"独自守着一座小镇的幸存者","role":"中立","personality":"疑心极重，只信自己钉过的钉子","hook":"他答应替玩家补一次装备，条件是把该给的那份报酬当场写清楚，一个字都不许省","favorHint":"按他划的线走、替他把陷阱复位、不碰他仓库的门会加分；擅自改路线、乱翻他的柜子、说他的布置多余会掉分","gender":"男","age":"五十岁上下","race":"人类","faction":"墙外的独居幸存者","appearance":"头顶大半秃了，两侧留着花白的短发，络腮胡一直连到鬓角。灰绿色格纹衬衫外面套一件沾着机油的橡胶围裙，裤子膝盖处用胶带加固。他体格敦实，站着时两脚分得很开，手里常年握着一把霰弹枪。靴底钉着防滑钉，腰带上挂一串自己打的钥匙。","traits":["多疑","手巧","孤僻"],"relations":[{"name":"乔尔","label":"旧日同行，互相看不起又不得不互助"},{"name":"泰丝","label":"唯一能和他把价钱谈成的人"},{"name":"弗兰克","label":"他嘴上不提、屋里却留着东西的那个人"}],"voice":"嗓门大，句子里常带着抱怨；谈到自己的布置时会突然变得条理清楚、一条一条讲。"}]},{"id":"game_bioshock","category":"game","canon":"生化奇兵","name":"生化奇兵","icon":"🌊","tagline":"海底城的灯，正在一盏盏熄灭","mood":"海底城、质体、ADAM、装饰艺术、崩塌","guidance":"【原著设定】销魂城是安德鲁·莱恩在大西洋底建成的一座城市，建于一九四六年，靠一套自称不受任何管束的自由市场运转，城市结构悬在海底岩层之间，由耐压舱体、玻璃走廊与潜水球交通串联。城里最重要的资源是海里一种海蛞蝓体内提取的物质，它可以重写人的体质，让人徒手放出电流、火焰或念力；这种物质被制成质体，注射后使用时消耗体内的 eve 能量。质体成瘾的人身体与精神一起坏掉，被称作拼接者，会为了一点物质袭击任何人。女孩被改造成采集者，体内养着那种海蛞蝓，由一种穿着厚重潜水装、行动迟缓的护卫看护，她们从死者身上采集物质。整座城市因为这门生意分裂成两派：莱恩要保住他定下的规矩，走私起家的方丹要把它整块端走。【反复出现的意象】走廊里烧着鲸油的暖黄壁灯、圆形舷窗外漆黑而缓慢流动的海水、墙上刷着口号的装饰艺术风格海报、一排投币式自动售货机、还有潜水球下沉时舷窗外螺旋上升的气泡。【NPC 类型】穿着工装、对管道比对人熟的维修工／把台词背得滚瓜烂熟的女招待／在夹层里走货的走私贩／已经不太分得清现实与幻听的质体成瘾者／专替人保管秘密的诊所助理。【威胁类型】质体成瘾的拼接者、莱恩手下的安保队、坏掉之后会自己启动的机关炮塔、随机出现的断电与渗水，以及这座城市本身——它随时可以把某一整段走廊从地图上抹掉。【奖励风格】质体与 eve 注射器、改装枪械、投币售货机里的补给、采集者采到的物质样本，以及一枚只能坐一次潜水球的球票。能力会改造身体，代价是长期使用后的依赖。【不对劲的来源】这座城里的每一份物质都取自同一些女孩的身体，而女孩们管每个遇见的人都叫同一个名字，叫得毫不迟疑。更麻烦的是城里的广播：它会在没有人的走廊里报出你的名字，像是早就念过很多遍。【时间线】建议固定在崩塌前夜的一九五九年底：质体已经在城里普及，贫穷与富有的差距被拉到极限，莱恩与方丹的对立已经摆上台面，但整座城市还没有断电。不要提前启用后期才登场的角色与设定。","powerStyle":"质体与枪械向：质体、改装手枪","difficultyBias":2,"signatureItems":["EVE 注射器","质体注射管","潜水球球票","采集针管","黄铜的代币"],"mainQuest":"主线任务：在销魂城彻底断电之前找到那名被标记的小女孩，把她完好地送进指定的潜水球。","mainQuestGoal":"在城市断电前把女孩带进潜水球并启程，且中途没有把她交给任何一方做交易","sideQuests":[{"name":"展厅里少的那幅","desc":"从一位艺术家的私人展厅取回一件被标记的展品，别碰其余任何东西","reward":"积分 200"},{"name":"笼子里的鸟","desc":"把一只关在笼里的鸟送上莱恩的办公室，笼子不许打开","reward":"道具「黄铜的代币」"},{"name":"诊所的记账本","desc":"在一间私人诊所里找出采集记录的原本，把它带出这一层","reward":"积分 150"},{"name":"孤儿院的名单","desc":"在收容女孩的院子里找出一页被撕掉的名册，记住上面的编号","reward":"道具「质体注射管」"}],"factions":[{"name":"莱恩的销魂城","desc":"以自由之名建起的海底秩序，如今靠安保队与广播维持，谁碰质体生意就查谁","attitude":"敌对"},{"name":"方丹的势力","desc":"从走私起家的另一套网络，人手藏在救济院与码头，等着接管整座城","attitude":"中立"},{"name":"采集者的看护者","desc":"被绑在女孩身边的那种厚重护卫，只为她挡下所有伤害，不与人谈判","attitude":"中立"}],"npcs":[{"name":"比尔·麦克多纳","identity":"销魂城的维修工，最早一批建城的人","role":"引导者","personality":"直脾气，认手艺不认头衔","hook":"他看了一眼玩家穿的鞋，说这套走法不适合走管道层，随后把一串备用钥匙丢了过来","favorHint":"动手帮忙拧阀门、把零件归还原位、说话直来直去会加分；破坏管道、随口答应又做不到、拿建城的事开玩笑会掉分","gender":"男","age":"四十余岁","race":"人类","faction":"莱恩的销魂城","appearance":"红棕短发被汗压平，鬓角已经泛白，脸上带着油污。深蓝色连体工装外面系一条旧皮带，工具袋塞得鼓起来，口袋插着扳手与手电。他体型厚实，肩背有力，站着喜欢把双手插进工装兜里。左手小臂上有一块烫伤的旧疤，手指关节粗大，指甲缝里常年有油。","traits":["耿直","务实","手巧"],"relations":[{"name":"安德鲁·莱恩","label":"他亲手替对方建起这座城，如今越来越说不通"},{"name":"布里吉德·特南鲍姆","label":"他一直觉得这个女人做的事不对"},{"name":"弗兰克·方丹","label":"打过照面的对手，也留过后路"}],"voice":"嗓门不小，爱拿手艺打比方；说不过人时会重复同一个词两三遍。"},{"name":"安德鲁·莱恩","identity":"销魂城的建立者与支配者","role":"对手","personality":"把原则摆在人前面，从不承认自己会输","hook":"他隔着广播与玩家谈过一次条件，谈的是这座城里谁能算人","favorHint":"按规矩办事、承认这座城是他建的、把话说明白会加分；当面嘲笑他的理想、碰他的私人收藏、提方丹的名字会掉分","gender":"男","age":"六十岁上下","race":"人类","faction":"莱恩的销魂城","appearance":"高而瘦，深色头发向后梳得一丝不乱，两撇细胡修得很齐。深灰三件套西装配暗红领带，袖扣是黄铜的，手里常拄一根深色手杖。他站姿笔直，下巴微抬，看人时先看对方的手再看脸。说话前会先把西装前襟扣好。","traits":["专断","自持","偏执"],"relations":[{"name":"弗兰克·方丹","label":"他认定必须要清掉的那个人，越清越像自己的影子"},{"name":"比尔·麦克多纳","label":"旧部，他记得对方替他拧过第一颗螺丝"},{"name":"桑德·科恩","label":"他容忍的艺术家，也是他用来装点这座城的人"}],"voice":"慢，字咬得很清楚，爱用格言和反问；被人打断时只是把手杖在地上轻磕一下。"},{"name":"布里吉德·特南鲍姆","identity":"研究质体与采集者的科学家","role":"关键人物","personality":"冷静到近乎无情，却在某些细节上手会抖","hook":"她是唯一一个叫玩家名字而不是编号的人，叫完自己愣了一下","favorHint":"把女孩当孩子对待、不追问实验细节、把她给的样本原样带回来会加分；用编号称呼女孩、随便碰实验室的记录、说她的研究毫无价值会掉分","gender":"女","age":"四十余岁","race":"人类","faction":"方丹的势力","appearance":"深色头发盘成低髻，几缕散在耳后，脸上没有多余妆容，眼下有明显的青影。白色实验袍外面罩一件深色开衫，袖口卷到肘部，胸前口袋里插着两支笔和一小本记录。她身形偏瘦，说话时习惯把双手交叠在身前。右手食指上有多年握镊子留下的硬痕。","traits":["冷静","执拗","内疚"],"relations":[{"name":"采集者女孩们","label":"她亲手做出来的东西，也是她越来越想赎的那笔账"},{"name":"弗兰克·方丹","label":"她曾经的金主，也是把她推上这条路的人"},{"name":"比尔·麦克多纳","label":"彼此都看不惯对方的那个修理工"}],"voice":"语速平稳，爱用精确的词和数字；情绪上来时会忽然改用母语腔调很重的短句。"},{"name":"弗兰克·方丹","identity":"走私起家、与莱恩争夺销魂城的人","role":"潜在敌人","personality":"随时能换一副面孔，永远在算下一个人是谁","hook":"他记下了玩家报的名字，因为那个名字在他很久以前的某份名单上出现过","favorHint":"谈得成的生意就谈、不站队、把货如实交付会加分；当面揭穿他的身份、替他传不该传的话、两头拿好处会掉分","gender":"男","age":"四十余岁","race":"人类","faction":"方丹的势力","appearance":"体格壮实，深色卷发抹了发油向后压，脸盘宽，笑起来露出金牙。深褐色条纹西装，领带结打得很大，手上戴一枚沉的金戒指。他走路时双臂微张，像是随时要跟人勾肩搭背。脖子上挂着一枚小小的金属吊牌，总在指间转。","traits":["圆滑","贪婪","善变"],"relations":[{"name":"安德鲁·莱恩","label":"他这辈子最想取而代之的人"},{"name":"布里吉德·特南鲍姆","label":"替他做事的人，也是他随时准备丢掉的人"},{"name":"桑德·科恩","label":"给他办过招待会的艺术家，他嫌对方太吵"}],"voice":"亲热、套近乎，句子里夹着市井的说法；翻脸时语气几乎不变，只是不再叫你的名字。"},{"name":"桑德·科恩","identity":"销魂城里最有名的艺术家","role":"中立","personality":"情绪起伏极大，把作品看得比人重","hook":"他说玩家的站姿可以入画，于是要人站到他那间展厅的正中间，别动","favorHint":"听完他的作品再说话、夸得具体、按他的安排摆好姿势会加分；中途走开、碰坏他的颜料、说这只算装饰会掉分","gender":"男","age":"四十余岁","race":"人类","faction":"莱恩的销魂城","appearance":"深色头发烫成细卷往后拢，脸上扑着薄薄一层金粉，眉毛描得很细。深紫色丝质长袍式外套配黑色衬衫，颈间系一条宽绸巾，手指上套着两三枚夸张的戒指。他说话时手一直在动，指尖捏着一支长杆画笔，脚下穿一双丝绒便鞋。","traits":["浮夸","敏感","危险"],"relations":[{"name":"安德鲁·莱恩","label":"他的资助人，也是他从不敢当面顶撞的人"},{"name":"弗兰克·方丹","label":"替他办过展览的人，他嘴上嫌弃、心里记账"},{"name":"采集者女孩们","label":"他把她们当作作品里的常客，从不问她们从哪来"}],"voice":"抑扬顿挫，喜欢用比喻和自我评价；被冷落时会突然拉高声音，随后又变得温柔。"}]},{"id":"game_reddeadredemption2","category":"game","canon":"荒野大镖客2","name":"荒野大镖客2","icon":"🤠","tagline":"火车还没进站，死者先到了","mood":"西部、铁路、赏金、帮派、末路","guidance":"【原著设定】时值一小九九年的美国西部。联邦政府与铁路公司一路向西推进，原住民被赶进保留地，靠劫掠与放牧吃饭的帮派正在被时代挤出去。平克顿侦探社受雇于铁路与矿业大亨，成队跨州追捕帮派；各州施行各自的法律，镇上由治安官与几名副手管事，边界一带谁的地盘谁定规矩。范德林德帮在黑水镇失手之后一路流亡，靠抢劫、敲诈与临时生意维持，钱箱归公，内部却已经分成几派。武器还是柯尔特式左轮、连发步枪、双管霰弹枪与拉索，弹药要按颗买，马是脚也是家当。【反复出现的意象】车站木牌上被雨水泡花的时刻表、墙上钉着的赏金通告与油墨模糊的报纸、酒馆门口挂的煤油灯、邮局的黄铜信箱、还有每座小镇都有一间的枪械铺橱窗。这些画面一出现，玩家就该知道自己站在西部的哪一座镇上。【NPC 类型】守在柜台后面的车站职员／按行情开价的枪械铺老板／在酒馆里认识的赏金猎人／把消息卖给两边的情报贩子／追着赏金跨州跑的私家侦探。【威胁类型】平克顿侦探、敌对帮派的伏击、拿悬赏的赏金猎人、荒野里的野兽与天气，以及最要命的那样东西——枪伤能养好，病养不好。【奖励风格】左轮与连发步枪、拉索、马匹与马具、炸药、怀表与金条、各类打猎所得的毛皮与肉，以及酒馆里能换来消息的现金。装备会磨损，坐骑会死，钱会变薄。【不对劲的来源】报纸与档案里记着一些根本没发生的事：某个人明明死在两年前的河滩上，通行记录却在昨天更新过。更让人不舒服的是这座镇上所有人对那一天的说法都一样，像是事先对过口径。【时间线】建议固定在故事中期、帮派还在野外营地落脚的那几个月：黑水镇的事刚刚过去，帮派尚未瓦解，主要成员都活着，卡着劫案之前的那一夜最好。不要提前启用后期才登场的角色与设定。","powerStyle":"枪械与马术向：左轮、连发步枪、拉索","difficultyBias":1,"signatureItems":["柯尔特式左轮","连发步枪","套马索","赏金通告","停摆的怀表"],"mainQuest":"主线任务：在火车劫案发生之前把消息递进车站，同时保住报信的人不被任何人查出来。","mainQuestGoal":"让消息在白天的班车进站前送到值班的人手上，且全场没有一个人能指认报信者是谁","sideQuests":[{"name":"一张不说话的电报纸","desc":"用电报把消息发出去，收报人那一栏只填一个只有对方看得懂的缩写","reward":"积分 150"},{"name":"医生抽屉里的信","desc":"从镇上的医生那里取回一封没写完的信，看完之后当面烧掉","reward":"道具「烧掉一角的信封」"},{"name":"货场的清单","desc":"在货场抄下一份车厢装载清单，抄完把原件放回原处、脚印抹平","reward":"积分 200"},{"name":"赏金不接的活","desc":"替一户人家把贴在墙上的赏金揭下来，换成另一份通告贴上去","reward":"道具「赏金通告」"}],"factions":[{"name":"范德林德帮","desc":"流亡中的西部帮派，讲义气也讲分成，内部对接下来该怎么走已经没有共识","attitude":"友善"},{"name":"平克顿侦探社","desc":"受雇于铁路与矿业公司的私家侦探，办案不吃赏金，吃的是委托人的钱与耐心","attitude":"敌对"},{"name":"奥德里斯科帮","desc":"与范德林德帮结怨多年的敌对帮派，靠抢同一条线上的货过日子","attitude":"敌对"}],"npcs":[{"name":"何西阿·马修斯","identity":"范德林德帮的元老，负责出主意与踩点","role":"引导者","personality":"温和有礼，把骗术讲成一门手艺","hook":"他给玩家安排的身份是一个跑货的商人，理由是这样没人会多看一眼这张脸","favorHint":"按他的编排演完一场戏、把细节记住、不抢着动手会加分；临时加戏、在镇上报真名、对老办法表示不屑会掉分","gender":"男","age":"五十余岁","race":"人类","faction":"范德林德帮","appearance":"灰白头发向后梳，额头很高，留着一圈修剪整齐的灰胡须。深棕色长外套套在浅色马甲外，怀表链横过马甲，头上是一顶边沿磨旧的深色毡帽。他体形偏瘦，说话时习惯一只手搭在手杖或柜台边上。金丝眼镜用细链挂在领口，随身带一副旧扑克牌。","traits":["老练","风趣","谨慎"],"relations":[{"name":"达奇·范德林德","label":"几十年的搭档，他清楚对方已经不是当年那个人"},{"name":"亚瑟·摩根","label":"他当成半个儿子看的人，也是他最想拉住的一个人"},{"name":"迈卡·贝尔","label":"他一直提防、却始终没能把这人挤出去"}],"voice":"客气、慢条斯理，先夸人再提要求，喜欢用行话把话包起来；谈正事时会压低声音。"},{"name":"亚瑟·摩根","identity":"范德林德帮的主力枪手","role":"盟友","personality":"外表粗硬，心里一直在记账","hook":"他把一份没写完的记录塞给玩家保管，说这东西比自己这条命要紧","favorHint":"答应的事办到、掩护队友、把猎物带回来分给营地会加分；丢下受伤的人、在镇上滥杀、嘲讽他的字迹会掉分","gender":"男","age":"三十余岁","race":"人类","faction":"范德林德帮","appearance":"深褐色短发，脸上一层没刮净的胡茬，眉骨上有一道旧疤。灰蓝色厚外套肩部打着皮补丁，里面是深色格纹衬衫，脖子系一条暗红领巾。体格宽厚，走路时靴跟先着地，右手常搭在腰侧的枪套上。随身带着一本卷了角的皮面记录本与一支短铅笔，坐骑上永远挂着卷起的毯子。","traits":["可靠","自省","暴烈"],"relations":[{"name":"达奇·范德林德","label":"他奉为父亲的人，如今越来越像一座不肯挪动的山"},{"name":"何西阿·马修斯","label":"帮里唯一能让他把火压下去的人"},{"name":"迈卡·贝尔","label":"从第一天起就合不来的那个人"}],"voice":"低沉、带点沙哑，先讲事情再讲看法；被问到以后的时候，多半只哼一声。"},{"name":"乔赛亚·特里劳尼","identity":"替帮派在外周旋的中间人","role":"中立","personality":"永远穿着体面，永远只讲一半实话","hook":"他手上有一份自己记的进出名单，其中一行写着玩家的名字，日期却在玩家进镇之前","favorHint":"替他圆场、按约定交情报、装作不认识他身边的人会加分；当众叫他帮派里的名字、拆穿他的身份、赖掉情报钱会掉分","gender":"男","age":"四十余岁","race":"人类","faction":"范德林德帮的外围","appearance":"深色头发用发油向后梳得光滑，留一撮修细的小胡子。深绿色礼服外套配浅色马甲与怀表链，手上一副白手套，头顶是圆顶礼帽。他身形高瘦，站姿讲究，常用指节轻敲帽檐跟人打招呼。手杖是黑的，杖头包着一圈磨亮的铜。","traits":["圆滑","体面","市侩"],"relations":[{"name":"何西阿·马修斯","label":"互相欣赏的老同行，都爱把骗术当学问"},{"name":"达奇·范德林德","label":"他服务的对象，也是他随时准备抽身离开的关系"},{"name":"亚瑟·摩根","label":"他总拉来做搭档的人，亚瑟总嫌他啰嗦"}],"voice":"腔调讲究，爱夹外语词与客套话，被追问就笑着把话题拐到别处。"},{"name":"迈卡·贝尔","identity":"范德林德帮成员，惹是生非的那一个","role":"潜在敌人","personality":"嘴上不饶人，动手比谁都快","hook":"他听见玩家和车站的人说过话，从那以后每次都挑玩家身边的人下手","favorHint":"在牌桌上赢他一次、当众不给他台阶会加分；示弱、让他摸到你的底牌、替他说情会掉分","gender":"男","age":"三十余岁","race":"人类","faction":"范德林德帮","appearance":"沙金色短发，上唇一撇小胡子，脸上常带着一点鼻音很重的笑。白色外套配红褐色衬衫，马甲扣得紧，帽子是浅色的宽檐款。他个子不高，肩却很宽，站着喜欢把一条腿支出去。腰上双枪套，枪柄缠着深色的布条，靴筒里插一把刀。","traits":["好斗","阴狠","记仇"],"relations":[{"name":"达奇·范德林德","label":"他一直在讨好的那个人，也一直在利用那个人"},{"name":"亚瑟·摩根","label":"帮里他最想压下去的人"},{"name":"何西阿·马修斯","label":"他嘴上尊重、背后编排的老家伙"}],"voice":"带笑说话，句末往上扬，爱用挑衅的玩笑；真动怒时反而压低声音。"},{"name":"安德鲁·米尔顿","identity":"平克顿侦探社派来追查帮派的探员","role":"对手","personality":"按程序做事，也允许自己破例","hook":"他在镇上跟玩家搭过话，问的是时间，看的是玩家腰上的枪","favorHint":"回答问题不出错、配合他做一次例行盘问、把话讲得干净会加分；替帮派的人做伪证、当着他的面撒谎、提他雇主的名号会掉分","gender":"男","age":"四十岁上下","race":"人类","faction":"平克顿侦探社","appearance":"深色短发梳得服帖，鬓角修得干净，下巴刮得很白。黑色三件套西装配灰色长外套，领口别着一枚小徽章，手上戴一副深色皮手套。他身形中等偏瘦，站姿板正，说话时双手背在身后或交握在身前。腰侧挂着枪套，外套下面还能看见一本硬皮记事簿的角。","traits":["冷静","固执","守序"],"relations":[{"name":"达奇·范德林德","label":"他跨州追了很多年的人，越追越有耐心"},{"name":"亚瑟·摩根","label":"他记在本子上的名字之一，也是他愿意给机会的人"},{"name":"利维提克斯·康沃尔","label":"他的委托人，出钱的人，也是他这份差事的原因"}],"voice":"语速不快，用词正式，习惯先给出条件再给期限；不接受讨价还价，但会听人把话说完。"}]},{"id":"game_cyberpunk2077","category":"game","canon":"赛博朋克2077","name":"赛博朋克2077","icon":"🌃","tagline":"雨夜送一枚芯片，别去看它","mood":"义体、脑机、公司、帮派、雨夜","guidance":"【原著设定】夜之城坐落在北加州海岸，由几大超级企业实际统治，其中荒坂与军用科技势力最大。城市分六个区，市中心是公司高塔与玻璃广场，外围是沃森、圣多明戈、帕西菲卡这类靠帮派与灰产运转的地带，荒地之外是游民部族的地盘。义体植入是常态：神经接口、义眼、强化肌肉、皮下装甲，装上就能用，装上就停不下来；脑机接口能录下视觉、听觉与情绪，剪成片子在黑市流通，这种片子叫超梦。人被数字化保存的技术掌握在荒坂手里，代价是人格本身会慢慢磨掉。街头语言里没有无辜，只有没到期。钱、义体、合同三样东西决定你能活多久。【反复出现的意象】招牌上永远在漏电的霓虹字、雨天里反射整条街的积水、自动贩卖机里嘶嘶冒气的合成咖啡、义体诊所门口那盏忽明忽暗的白灯、以及每个人在雷雨里不受控制颤一下的那只手。【NPC 类型】坐在屏幕后面派活的中间人／按小时收费的义体医生／把客人当朋友也当生意的酒吧老板／开着出租车把电台当命的老司机／把规矩挂在嘴上却天天破例的帮派打手。【威胁类型】企业特工、街头帮派、专拆义体的回收商、创伤小组之外没人来救的现实，以及一份永远还不完的债。他们不会杀你，只会让你欠得更多。【奖励风格】军用级枪械与智能弹、义体与插件、超梦片、破解程序与快速破解芯片、通行证与假身份，以及一次不用过安检的通行。所有的强化都标着价，也标着代价。【不对劲的来源】脑机接口只记录你自己经历过的东西，这是常识。可这枚芯片里放着的画面从头到尾只有一场葬礼，而画面里站在最前排的那个人，姿势和玩家一模一样。更让人不安的是这座城的殡仪馆里，有人已经替玩家订好了一格。【时间线】建议固定在主角刚在夜之城站住脚的那段时间：各大公司与主要帮派都已活跃，杰克还在，维克多的诊所照常营业，亚当·重锤还只是传说里的人物。不要提前启用后期才登场的角色与设定。","powerStyle":"义体与枪械向：军用枪、快速破解、植入体","difficultyBias":1,"signatureItems":["脑机接口芯片","军用级手枪","义体插件","超梦片","合成咖啡罐"],"mainQuest":"主线任务：把一枚装在脑机里的记忆芯片送到指定诊所，全程不许读取里面的内容。","mainQuestGoal":"在芯片被任何一方截住之前把它交到指定诊所，并始终没有读取过其中的内容","sideQuests":[{"name":"机车座垫下的东西","desc":"替人把一辆摩托车从瓦伦蒂诺帮手里取回来，座椅里那个小盒子不许打开","reward":"积分 150"},{"name":"别人的窗户","desc":"收下一枚超梦片，看完之后把它送还给原本的委托人，不做备份","reward":"道具「超梦片」"},{"name":"莫克斯的一夜","desc":"把一名想脱身的女孩从诊所那一层带出去，路上不动用任何枪械","reward":"积分 200"},{"name":"欠账的记录","desc":"去诊所把一份过期的债务记录赎回来，钱不够就用别的东西抵","reward":"道具「义体插件」"}],"factions":[{"name":"荒坂公司","desc":"夜之城势力最大的企业，掌握神舆与安保部队，把每一份合同都当成工具","attitude":"敌对"},{"name":"军用科技","desc":"与荒坂对峙的军火巨头，在街头有大量代理人，只认交付结果","attitude":"中立"},{"name":"莫克斯帮","desc":"从丽兹酒吧起家的帮派，护着在这一行讨生活的女孩，规矩简单但守得住","attitude":"友善"}],"npcs":[{"name":"杰克·威尔斯","identity":"夜之城的独立佣兵，瓦伦蒂诺帮出身","role":"引导者","personality":"嘴上不停，关键时刻一步不让","hook":"他把玩家写进自己的接活名单，理由只有一个——你看着像会守约的人","favorHint":"接下活就干完、替他把家里人那边的事处理好、喝一杯他递过来的东西会加分；丢下他跑、拿他妈妈的事开玩笑、抢他的单会掉分","gender":"男","age":"三十岁上下","race":"人类（带义体）","faction":"独立佣兵","appearance":"黑色短发剪得很平，两侧推短，下巴一圈胡须修得整齐。皮背心上钉满帮派与佣兵的徽章，里面是一件深色T恤，胳膊上能看见义体的金属接口。体格壮，动作大，笑起来整张脸都动。左手腕戴一串编绳手环，腰间挂一把大号手枪，骑的摩托车座上永远搭着一件旧外套。","traits":["热情","义气","浮夸"],"relations":[{"name":"V","label":"搭伙的同伴，两个人互相吹牛也互相兜底"},{"name":"米斯蒂","label":"把他当家人看的人，也是他少有的会认真听的人"},{"name":"德克斯特·德肖恩","label":"给他派过大活的中间人，他嘴上不服心里认"}],"voice":"语速快、爱加语气词和西班牙语词汇，讲计划时手势不断；认真起来会突然只讲重点。"},{"name":"米斯蒂·奥尔谢夫斯基","identity":"守着一间小店、替人看牌面的店主","role":"盟友","personality":"安静，看人很准，不轻易说破","hook":"她替玩家翻开一副牌，看完之后把牌收起来说自己看错了，然后顺手把店门锁上","favorHint":"尊重她的说法、在她店里把枪收好、不在她面前撒谎会加分；嘲笑她的牌、把她的话当娱乐、带着血进她的店会掉分","gender":"女","age":"二十余岁","race":"人类","faction":"夜之城的街头","appearance":"金色长发编成细辫盘在头顶，鬓边别着几枚小饰物，眼妆偏冷色调。深紫色长外套下摆过膝，里面是黑色高领衫，手指上戴几枚银戒。她个子不高，动作很轻，柜台后面总是点着一盏暖色小灯。脖子上挂一条细链，柜台上摆着牌与香。","traits":["沉静","直觉强","厚道"],"relations":[{"name":"杰克·威尔斯","label":"她当成家人的那个大嗓门"},{"name":"维克多","label":"隔壁的义体医生，也是照看她的人"},{"name":"V","label":"她替对方看过一次牌，之后就一直留着一点余地"}],"voice":"声音轻，句子慢，用比喻代替结论；被追问细节时只说一半，剩下的一半让你自己想。"},{"name":"维克多","identity":"开在地下室里的义体医生，前拳手","role":"中立","personality":"按行情收费，却总留一点人情在账外","hook":"他替玩家做了一次免费的检查，检查结果只写在他自己的本子上，没有上传任何地方","favorHint":"按价付钱、不催他、带自己的零件来会加分；赖账、拿他的诊所当藏身处、拆了义体不回来会掉分","gender":"男","age":"五十岁上下","race":"人类（带义体）","faction":"夜之城的街头","appearance":"灰白短发向后梳，脸上有拳击留下的旧疤，鼻梁略歪。白大褂搭在椅背上，日常穿着深色衬衫配羊毛背心，袖子卷到小臂，露出两条旧款义体臂。他戴一副细框眼镜，坐姿总是向后靠在椅背里。手边常年放着棒球比赛与拳赛的录像带，桌上摆着啤酒罐和一副老式手套。","traits":["厚道","专业","怀旧"],"relations":[{"name":"米斯蒂","label":"隔壁的邻居，他看着她长大"},{"name":"杰克·威尔斯","label":"常来的客人，他嘴上嫌吵心里认这个朋友"},{"name":"V","label":"他替对方收拾过太多次烂摊子的那个年轻人"}],"voice":"语速慢，带点沙哑，喜欢拿拳赛打比方；讲到义体时句子会变得非常精确。"},{"name":"竹村五郎","identity":"荒坂公司出身的贴身保镖","role":"关键人物","personality":"把职责看得比命重，为此肯低头也肯动手","hook":"他在雨里等了玩家很久，只为确认一件事——那天街上有没有别人看见他的雇主","favorHint":"说实话、把干掉的活收干净、尊重他要守的东西会加分；跟企业的人谈条件、拿他雇主的死做文章、在背后议论他的出身会掉分","gender":"男","age":"四十岁上下","race":"人类（带义体）","faction":"荒坂公司","appearance":"黑发向后束紧，鬓角修得干净，脸型偏瘦，颧骨明显。深色三件式西装剪裁利落，领口别着一枚小小的企业徽记，袖口露出手腕上一圈义体接缝。站姿笔直，双手常交叠在身前，走路脚步很轻。外套内侧挂一把小型手枪，随身带一块折叠好的手帕。","traits":["忠诚","克制","固执"],"relations":[{"name":"荒坂三郎","label":"他效忠的人，也是他一切选择的起点"},{"name":"荒坂赖宣","label":"他不得不服从、却始终看不起的那位继承人"},{"name":"V","label":"被迫合作的街头人，他一边利用一边承认对方的可靠"}],"voice":"用词正式、语速平稳，偶尔夹一句母语；谈条件时先把对方的选择摆全，再让你挑。"},{"name":"德克斯特·德肖恩","identity":"夜之城的中间人","role":"潜在敌人","personality":"客气、体面，随时准备把下家推出去","hook":"他给的报酬比行情高出一大截，而且提前付了一半，这不像是好意","favorHint":"接活不问细节、把货如实送到会加分；追问客户是谁、私留一份拷贝、讨价还价第二次会掉分","gender":"男","age":"五十岁上下","race":"人类（带义体）","faction":"夜之城的中间人","appearance":"光头，头型圆润，戴一副深色镜片的眼镜，脸下半部蓄着修剪过的短须。深紫色长外套配高领衬衣，胸前口袋插着一支雪茄，手指上戴两枚粗戒指。他身形高大壮硕，坐进椅子时整把椅子都会响，站着时爱把外套下摆往后一撩。走路很慢，鞋底敲地板的声音比人先到。","traits":["城府深","讲排场","无情"],"relations":[{"name":"杰克·威尔斯","label":"他雇过的手下，也是他最早打算牺牲掉的人"},{"name":"V","label":"他挑中的执行者，从一开始就没打算留后路"},{"name":"竹村五郎","label":"他避之不及的企业人，两人的路迟早要撞上"}],"voice":"慢条斯理，先讲交情再讲价，爱用生意人的说法打圆场；决定丢人的时候语气不会变。"}]},{"id":"game_sekiro","category":"game","canon":"只狼","name":"只狼","icon":"🗡️","tagline":"雪落苇名，刀与不死之间","mood":"战国、忍义手、雪、龙胤、苇名城","guidance":"【原著设定】故事发生在战国末期的苇名国。这是一座建在山间的小国，靠苇名城与周边要塞自守，由苇名一心一手立起来，如今实权落在其孙苇名弦一郎手里，内府大军压境，守军靠地形、火器与不要命的打法支撑。战斗以刀剑格斗为主，核心是弹刀——用刀刃去接对方的刀锋，把对方的体干值磨到可以一击必杀；忍杀讲究从背后或高处下手，一次致命。义手忍具是在断臂上装的机关，可以放出爆竹、手里剑、火筒与钩绳，钩绳让忍者能在屋檐与山壁之间高速移动。鬼佛是散布各地的石像，坐下可以恢复体力、重置敌人与死神状态。龙胤之血是这个世界的关键：持有者不会真正死去，代价是会把一种病传到周围人身上。【反复出现的意象】雪地里成排的足印与倒下的旗、路边盖满雪的鬼佛坐像、城墙上被风吹得笔直的红白旗、挂在树梢的圆形纸人、还有屋顶上那块被踩得发亮的瓦。这些画面一出现，玩家就该知道自己站在苇名的哪一段山道上。【NPC 类型】守着城门、一天只吃两顿的苇名士兵／穿黑衣、从屋顶下来的孤影众忍者／在寺庙里照顾伤病者的僧侣／把兵粮与火药挑上山的老商人／在山道边反复念同一句经的瞎眼老人。【威胁类型】内府军的火器与火炮、孤影众忍者、被龙胤之血泡过的不死者、以及「樱龙」这类超出人间的东西。最切实的威胁是车轮战——弹刀弹到手上发麻的时候，第二波人已经在路上了。【奖励风格】纸人、伤药葫芦、忍具附件、忍术与苇名流的招式书、钱与药，还有能让人短暂不死的龙胤之力。强力招式都有明显的代价与使用条件。【不对劲的来源】不死的代价是别人的病。这个世界里每一条命都标着价：龙胤让持有者活着，把咳嗽与痛苦转给身边的人；鬼佛只要坐下就能反复复活，那些名字被记下的死人却像是早就付过同一笔账。【时间线】建议固定在苇名城被内府军围困的那个雪夜：苇名弦一郎已经得到御子，狼刚把御子夺回，内府军的总攻还没完全展开，城里的人心与兵力都到了最紧的时候。不要提前启用后期才登场的角色与设定。","powerStyle":"刀剑与忍义手向：弹刀、忍杀、忍具","difficultyBias":1,"signatureItems":["纸人","伤药葫芦","忍义手附件","御子的护身符","雪夜的火折"],"mainQuest":"主线任务：在苇名城城门失守之前，把年幼的御子从城中护送到后山的密道入口。","mainQuestGoal":"在城门被攻破前把御子送进密道并封住入口，且全程没有让内府军看清御子的脸","sideQuests":[{"name":"一句没送到的话","desc":"把一名垂死士兵的口信带到城东门，人到了，话得说给对的人听","reward":"积分 150"},{"name":"半天没磨的刀","desc":"替一名守着桥的老兵把刀磨完，再替他站完那半班岗","reward":"道具「磨刀石与砥粉」"},{"name":"密道里的火折","desc":"在密道里点燃三处火把，回来时把火按原样熄掉","reward":"积分 200"},{"name":"寺庙里的药方","desc":"从一座寺庙取回一包止咳的药，别问病人是谁","reward":"道具「止咳的药包」"}],"factions":[{"name":"苇名众","desc":"守卫苇名国的武士与足轻，明知守不住也要守，内部已经被不死之力撕开","attitude":"友善"},{"name":"内府军","desc":"前来吞并苇名的大军，火器齐备、编制完整，不急于一天打完","attitude":"敌对"},{"name":"仙峰寺的僧众","desc":"藏在山上的寺庙，追求不死，对来客客气，对人的用处看得很清","attitude":"中立"}],"npcs":[{"name":"御子","identity":"龙胤之力的继承者，苇名的年幼主君","role":"盟友","personality":"安静有礼，做了决定就不改口","hook":"他把自己的护身符解下来系在玩家手上，说这样他就能知道玩家还活着","favorHint":"按他说的做、不把他当成需要骗的孩子、答应的事办到会加分；替他做决定、把他交给别人看管、当面说他的愿望是错的会掉分","gender":"男","age":"十岁上下","race":"人类（龙胤持有者）","faction":"苇名众","appearance":"黑色短发齐耳，刘海垂到眉上，眼睛很黑很静。深蓝色和服外面罩一件浅色外褂，腰间系着宽腰带，脚上是白足袋配草履。襦袢袖口与衣摆沾着洗不掉的旧血痕。他个子比同龄孩子瘦小，站着始终挺直，双手习惯拢在袖中。随身带一只小小的香囊与一枚圆形纸人。","traits":["早熟","执拗","善良"],"relations":[{"name":"狼","label":"把命交出去的忍者，也是他唯一不肯当作工具的人"},{"name":"苇名弦一郎","label":"要借他血脉去救这个国的人，他理解却不肯给"},{"name":"永真","label":"替他处理伤势与日常的人，也是少数能劝动他的人"}],"voice":"句子短而有礼，用敬语；一旦拿定主意，语气会平静得不像孩子。"},{"name":"永真","identity":"常在寺院与武士之间走动的女子","role":"中立","personality":"温和、话不多，出手时毫不迟疑","hook":"她替玩家包扎时发现了旧伤，却没问来历，只留下一句「别让御子看见」","favorHint":"让她把话讲完、受伤后老实处理、对御子有耐心会加分；隐瞒伤情、逼她表明立场、把她的药随手转送会掉分","gender":"女","age":"二十余岁","race":"人类","faction":"苇名众","appearance":"黑色长发在脑后束成低马尾，额前留细碎刘海。浅灰色和服配深色窄腰带，外面罩着素色外褂，袖口用绑带束紧便于行动。她身形纤细，动作很轻，走路时几乎听不见脚步声。腰间挂一只药袋与一把短刀，手指修长，指甲剪得很短。说话时习惯微微低头。","traits":["体贴","冷静","果决"],"relations":[{"name":"御子","label":"她照看的孩子，也是她愿意违背命令去护的人"},{"name":"苇名弦一郎","label":"她侍奉的主君，也是她最不愿见其走上那条路的人"},{"name":"佛雕师","label":"她认得这个住在破庙里的老人，也认得他手上那把刀"}],"voice":"声音放得很轻，先问伤再说话；被逼到必须选择时，只讲一句结论。"},{"name":"苇名弦一郎","identity":"苇名国的实际掌权者，苇名一心之孙","role":"对手","personality":"为守住这个国，什么都肯做，包括不该做的","hook":"他在雪中拦住玩家，只说了一句话——把御子留下，你走","favorHint":"正面接他的刀、把话说清楚、承认苇名的困境会加分；在背后偷袭、拿他祖父压他、说这个国守不住会掉分","gender":"男","age":"三十岁上下","race":"人类（经不死之力改造）","faction":"苇名众","appearance":"黑色长发在脑后扎紧，鬓角利落，眉眼很深，脸上常有疲惫。深蓝色武士礼服外披黑色肩甲，腰间系着红绳，腿上缠着护胫。他身材高瘦，站姿挺直，右手按在刀柄上。左臂袖口处能看到不属于常人的接缝与旧伤，随身带着一把长弓与箭囊。","traits":["执着","孤注","果决"],"relations":[{"name":"御子","label":"他要借其血脉救国，也是他唯一不肯放手的东西"},{"name":"苇名一心","label":"他最敬重也最想超越的祖父"},{"name":"狼","label":"三番两次挡在他面前的那个忍者"}],"voice":"声音低沉，句子短，多用命令式；谈到苇名时会突然放慢，像是在对自己说。"},{"name":"佛雕师","identity":"破庙里雕刻佛像的独臂老人","role":"引导者","personality":"话糙心细，只对刀有兴趣","hook":"他看了一眼玩家断臂上那件忍具，说这活儿不是这个年头的做法，然后开始翻自己的旧箱子","favorHint":"替他找回丢掉的东西、耐心听完他的牢骚、不打听他那只手会加分；催他、弄坏他的刻刀、说佛像雕坏了会掉分","gender":"男","age":"六十岁上下","race":"人类","faction":"苇名众","appearance":"花白头发剃得很短，脸上皱纹深，下巴留着乱须。深灰色粗布僧衣外面套一件旧短褂，左袖从肩下空着，随动作晃。他体格瘦但骨架大，坐姿总是盘腿佝着背，手里拿刻刀与未完成的木佛。脚边散着木屑与酒壶，抬头看人时只用一只眼。","traits":["粗豪","执念","手稳"],"relations":[{"name":"狼","label":"他在对方身上装了那只义手，也把旧账托给了他"},{"name":"永真","label":"隔一阵就来送药的那个人"},{"name":"苇名一心","label":"他这一辈子只认的一个人，如今只能从别人口里听到消息"}],"voice":"嗓门粗，爱骂人爱自嘲；讲到刀和佛的时候会忽然变得很慢、很认真。"},{"name":"枭","identity":"狼的养父，立场不明的老忍者","role":"潜在敌人","personality":"永远留着第二套打算，笑起来像在夸人","hook":"他在密道那头等着，开口先叫的是玩家名字，而不是狼的名字","favorHint":"把活干得干净、不在人前露脸、听他把话说完会加分；当众问他为什么、把御子交出去以后再反悔、提起他当年的选择会掉分","gender":"男","age":"六十岁上下","race":"人类","faction":"苇名众","appearance":"灰白头发束在脑后，头顶戴一顶鸭舌状的旧帽，脸瘦削，眼神很锐。深灰色忍者服外面披一件宽摆外袍，肩甲上刻着猫头鹰的纹样。他个子高，背微微驼，走路时衣摆几乎不出声。腰上挂刀，袖中藏着细长的暗器，手里常拄一根看似拐杖的东西。","traits":["深算","冷硬","狡猾"],"relations":[{"name":"狼","label":"他教出来的孩子，也是他随时可以舍弃的棋子"},{"name":"御子","label":"他嘴里说要护的人，心里早有别的安排"},{"name":"苇名一心","label":"旧日的对手，彼此都清楚对方还剩几分力气"}],"voice":"语调轻松，句子里常带笑意，用长辈的口吻讲狠话；从不解释自己的动机。"}]},{"id":"game_bloodborne","category":"game","canon":"血源诅咒","name":"血源诅咒","icon":"🩸","tagline":"钟响三下之前，别离开这条街","mood":"猎杀之夜、血疗、教会、钟声、兽化","guidance":"【原著设定】亚楠是一座与外界几乎隔绝的山城，以血疗闻名，远道而来的人在这里接受输血治疗，治好了病，也埋下了兽化的根。城市由治愈教会统辖，教会的血疗与圣歌维持着秩序，同时把秘密藏在地下——亚楠建在更古老的迷宫之上，那些墓穴里沉睡着不该被叫醒的东西。猎人分几类：教会的猎人、出身工场的猎人、以及被称作外乡人的临时猎人。他们用变形武器——一把刀可以展开成鞭、锤或锯——配合火器牵制，靠主动进攻与以伤换伤的回血撑住战斗，兽化程度本身是一场赌局。猎人梦境是死者的中转站，点着提灯就能在其中进出，从那里回到街上。猎杀之夜开始后，街上只剩猎人与猎物，居民锁门、点香、钉窗。【反复出现的意象】门楣上挂着的燃烧布条与香炉、猎人提灯里摇晃的暖黄火苗、教堂钟楼上那口铜钟、窗纸上透出的红色灯光、以及街上被踩烂的白色丝带。这些画面一出现，玩家就该知道自己站在亚楠的哪一条街上。【NPC 类型】守在门口的猎人／把窗户钉死后透过缝递东西的居民／推销血疗的教会人员／收集兽血与旧件的拾荒者／在教堂门口替人保管东西的老妇人。【威胁类型】兽化的市民与猎人、动作极快又成群出现的犬、巨人一样的行刑者、教会派出的执行者，以及猎杀之夜本身——它会让城市的形状一点点变得不对。【奖励风格】变形武器、火器、猎人工具、血瓶与子弹、猎人徽章与信物，还有能让人在梦里多留一会儿的东西。所有能力都要用血换，用得越多，越像街上的猎物。【不对劲的来源】血疗治的是病，可血是从哪里来的没人说得清。猎杀之夜也不是第一次——街上的布置像是为了重复同一夜而准备的，连钟楼敲几下都是算好的。【时间线】建议固定在猎杀之夜开始之后、天亮之前的这一夜：尤瑟夫卡诊所仍在接诊，加斯科因神父仍在城中，阿梅莉亚主教仍在教堂里，玩家作为刚接受过血疗的外乡人最合理。不要提前启用后期才登场的角色与设定。","powerStyle":"变形武器与进攻回血向：猎刀、火器、血瓶","difficultyBias":4,"signatureItems":["猎人手枪","血瓶","猎人提灯","猎人徽章","熏香束"],"mainQuest":"主线任务：守住指定的这条街直到教堂的钟敲满三下，钟响之前不许走出街口。","mainQuestGoal":"在钟敲第三下之前不离开这条街，并让街上还剩下至少一个能开口说话的人","sideQuests":[{"name":"门缝里的药","desc":"把一瓶血剂送到点着香的那户人家门口，别问病人是什么病","reward":"积分 150"},{"name":"白丝带的女孩","desc":"找到一个系白丝带的小女孩，把她送回该回的地方而不是带在身边","reward":"道具「染血的白丝带」"},{"name":"教堂前的一封信","desc":"把一封没署名的信交给教堂门口的老人，交完不看第二眼","reward":"积分 200"},{"name":"熄灭的香炉","desc":"在香烧完之前替一户人家补上熏香，门不许进","reward":"道具「熏香束」"}],"factions":[{"name":"治愈教会","desc":"以血疗统辖亚楠的教会，掌握血源与地下的秘密，对来客客气而有条件","attitude":"中立"},{"name":"猎人","desc":"在猎杀之夜上街清除野兽的人，各自守着自己那一套规矩，不轻易结伴","attitude":"友善"},{"name":"曼西斯学派","desc":"藏在旧迷宫与学院残余里的研究者，把仪式与梦当作通往更高处的路","attitude":"敌对"}],"npcs":[{"name":"乌鸦猎人艾琳","identity":"专猎同行的老猎人","role":"引导者","personality":"冷淡、讲规矩，把话说在前头","hook":"她拦下玩家只看了一件事——手上的刀握得对不对，看完就丢下一句劝告转身走了","favorHint":"按她的规矩收刀、不滥杀街上的人、把话听完会加分；在背后动手、杀已经收手的人、吹嘘杀过多少野兽会掉分","gender":"女","age":"中年，具体年纪不详","race":"人类","faction":"猎人","appearance":"灰白夹杂的黑发在脑后束成一团，几缕垂在颊边，戴一副深色金属面具遮住上半张脸。黑色羽织式长衣肩部缀着一圈深色羽毛，腰上系着宽布带，双手戴着磨破的皮手套。她体格清瘦，站姿微微前倾，走路时衣摆不打晃。随身带一对弯刀与一把短柄火器，颈间挂着一枚猎人徽章。","traits":["严厉","自持","守规矩"],"relations":[{"name":"加斯科因神父","label":"旧日的同路人，她清楚对方已经走到哪一步"},{"name":"吉尔伯特","label":"她隔窗说过几次话的外乡人"},{"name":"阿尔弗雷德","label":"她看不上那种把猎杀说成义务的人"}],"voice":"低声、句子短，用祈使句给忠告；不解释理由，说完就走。"},{"name":"吉尔伯特","identity":"住在窗后的外乡人","role":"盟友","personality":"礼貌、知足，把善意给得很轻","hook":"他隔着窗把一小块东西塞到玩家手里，说这东西他用不上了","favorHint":"路过时停下来听他说话、把街上打听到的事讲给他听会加分；嫌他啰嗦、在他窗下动刀、骗他说外面很安全会掉分","gender":"男","age":"四十余岁","race":"人类","faction":"亚楠的居民","appearance":"深色头发稀疏，额前贴着几缕汗湿的碎发，脸瘦得颧骨突出。浅色旧衬衫领口松开，肩头搭一条深色披巾，手腕上能看到输液留下的针痕与淤青。他只能在窗后扶着窗框站着，声音发虚，说话时手指扣着窗沿。窗台上摆着一盏小油灯与一只空药瓶。","traits":["温和","病弱","知礼"],"relations":[{"name":"乌鸦猎人艾琳","label":"偶尔从窗外经过、会停一下的那个人"},{"name":"尤瑟夫卡","label":"替他看过诊的医生，也是他最后的指望"},{"name":"亚楠的居民","label":"同样把门窗钉死的人，彼此只隔着窗说话"}],"voice":"声音轻，带喘，常先道歉再开口；讲起自己家乡的事时会多一点精神。"},{"name":"尤瑟夫卡","identity":"在诊所里接诊的医生","role":"中立","personality":"职业性的温和，观察多于交谈","hook":"她替玩家换过一次绷带，换完把剪下来的那截布收进了自己的抽屉","favorHint":"按她说的休息、如实回答身体的变化、不擅闯里间会加分；翻她的柜子、逼问血的来路、把诊所的事说给教会听会掉分","gender":"女","age":"三十余岁","race":"人类","faction":"治愈教会","appearance":"深色长发盘起用白布包住，鬓角整齐，脸上不施脂粉。白色医师袍外罩一件深色披肩，袖口收得很紧，胸前别着一枚教会的小徽记。她身形偏瘦，站姿端正，说话时双手交叠放在身前。诊所里总点着消毒用的味道，桌上摆着注射器、绷带与一本记录簿，右手戴一枚旧戒指。","traits":["冷静","好奇","疏离"],"relations":[{"name":"吉尔伯特","label":"她的病人之一，她记得每一个人的名字"},{"name":"阿梅莉亚主教","label":"教会里的上级，她对其既服从又保留"},{"name":"治愈教会","label":"她所属的机构，也是她最想问清楚的来源"}],"voice":"语气平缓专业，用问句引导对方多说；被问到关键处会先记录，再回答别的。"},{"name":"加斯科因神父","identity":"亚楠城中的神父，也是上街的猎人","role":"潜在敌人","personality":"白天讲道，夜里闻着血味走","hook":"他第一次见玩家就准确说出了玩家身上的血腥味来自哪一边的街","favorHint":"不在他女儿面前提街上的事、在他还听得进话的时候退开会加分；跟着他去猎杀、动他家里的人、说他身上的味道不对会掉分","gender":"男","age":"四十岁上下","race":"人类（正在兽化）","faction":"猎人","appearance":"深色短发与络腮胡都长得不加修剪，头戴一顶宽檐深色礼帽，帽檐压得很低。黑色长外套肩部缝着厚布，领口是教会的立领，胸前挂着一枚旧怀表。他身材高大，肩膀很宽，走路时手臂摆幅很大。腰带挂着切肉刀与一把火器，左手缠着脏绷带，手背上的血管颜色发暗。","traits":["威严","暴烈","挣扎"],"relations":[{"name":"乌鸦猎人艾琳","label":"旧日的同行，两人对猎人的规矩看法不同"},{"name":"阿梅莉亚主教","label":"他曾经追随的教会，如今只剩一层壳"},{"name":"他的两个女儿","label":"他上街猎杀的理由，也是他最不愿被她们看见的事"}],"voice":"声音厚，先讲道理再吼人；失控时句子会碎掉，只剩下重复的词。"},{"name":"阿尔弗雷德","identity":"替教会执行任务的修士","role":"对手","personality":"虔诚、热忱，把暴力当义务","hook":"他把玩家的徽章翻过来看了一次背面，说这枚不该在这一夜出现","favorHint":"当着他的面把该做的事做完、尊重他的仪式、不碰他带的圣物会加分；嘲笑教会、替该隐赫斯特的人说话、私藏他要找的东西会掉分","gender":"男","age":"二十余岁","race":"人类","faction":"治愈教会","appearance":"浅金色短发梳得服帖，脸年轻干净，眼睛很亮。白色长袍外罩一件带金线刺绣的深色披肩，胸前挂着教会的轮形徽记，脚上是一双高筒靴。他体格结实，站姿笔挺，说话时习惯单手按在胸前。腰间挂一把带花纹的锤状武器与一瓶血剂，随身带着一本翻旧了的教会小册子。","traits":["狂热","礼貌","残忍"],"relations":[{"name":"阿梅莉亚主教","label":"他敬奉的上级，也是他一切行动的凭据"},{"name":"尤瑟夫卡","label":"同为教会做事的人，他嫌对方不够虔诚"},{"name":"该隐赫斯特的血族","label":"他发誓要清掉的那一支，为此等了很多年"}],"voice":"语气热情、用词恭敬，爱引教会的话开头；谈到敌人时语速会变快、声音会抬高。"}]},{"id":"game_portal","category":"game","canon":"传送门","name":"传送门","icon":"🌀","tagline":"没有武器的走廊，也有它的规则","mood":"测试间、传送门、广播、白色板材、承诺","guidance":"【原著设定】光圈科技是一座建在地下的巨型研究设施，前身是 1940 年代成立的国防承包商，靠一批古怪专利起家，后来转向传送技术、人工智能与军用实验。设施按功能分层：上层是测试层与观察区，下层是维护层、员工区与早已停工的旧厂房。测试层的每一间测试间都以传送门为核心：玩家用传送枪打出成对的两扇门，从一个口进去从另一个口出来，动量守恒，摆荡、坠落与加速是唯一的通行手段。设施由中央人工智能统管，她用广播布置下一间房，用「完成测试就有奖励」换取配合。测试层里没有可用的武器，能依靠的只有地形、时间和门。【反复出现的意象】测试间入口钉着的编号牌、观察窗后熄着灯的座位、墙上用颜料潦草画出的方块、出口处那台始终不亮的烤炉与它许诺的蛋糕、一台只会说抱歉的自动炮台。这些画面一出现，玩家就该知道自己又回到了白色走廊里。【NPC 类型】把测试当唯一使命的广播声音／档案被删掉大半的旧测试员／只会道歉的自动炮台／在管道里爬行、留下涂鸦的前员工／把一切记成编号却不记名字的维修机器人。他们都不太在意你是谁。【威胁类型】不是战斗，是拖延：在拷问间里逐渐消失的耐心、带毒的水池、会扫射走廊的机枪、会把人推下深坑的活动地板、以及无一处不是谎话的口头承诺。你的血条由一次次失败累加，但系统会替你记好账。【奖励风格】奖励全部来自测试本身：能打出两扇门的传送枪、用来压住按钮的加重方块、落地不掉血的长靴、涂在地上就能加速的凝胶，以及最后一间房里那台从没亮过的烤炉。能力偏向位移、加速与拆解路线，没有一件能直接用来打人。【不对劲的来源】设施的档案里早就有了你的测试数据，像是有人在你之前替你走过一轮；而且那份数据里，失败记录比你本人记得的更多。广播在念完编号之后开始念名字，还问你累不累。【时间线】建议固定在主角被唤醒、从第一间测试间开始的那几天，只启用最初的十九间测试与逃生段，此时设施里没有别的活人，炮台与广播是仅有的声音来源。不要提前启用合作测试模式与续作里的地下旧公司区、凝胶全面投产和月球段落等设定。","powerStyle":"空间解谜向：传送枪、加重方块、长靴","difficultyBias":0,"signatureItems":["传送枪","加重方块","落地缓冲长靴","加速凝胶瓶","出口处的蛋糕模型"],"mainQuest":"主线任务：在没有武器的测试层里走完十间房，把指定的样本从设施里带出来。","mainQuestGoal":"在主控宣布奖励之前带着样本抵达出口，全程不把炮台与方块当作消耗品用完，并让广播里的那声音至少沉默一次","sideQuests":[{"name":"观察窗后的空座位","desc":"数清沿途熄灭的观察窗，记下最后一间还有人的编号","reward":"积分 150"},{"name":"烤炉从来没亮过","desc":"拆开出口那台装置的背板，看清它接的到底是电源还是别的","reward":"道具「蛋糕模型」"},{"name":"管道里的涂鸦","desc":"照着墙上方块涂鸦的方向走，找到留下记号的人最后停留的房间","reward":"积分 200"},{"name":"抱歉的炮台","desc":"整段路程不击倒任何一台炮台，把它们全部绕过去","reward":"道具「砝码方块」"}],"factions":[{"name":"光圈科技设施","desc":"只在意测试完成度的管理方，会满足你的最低需求，但绝不放你离开流程","attitude":"中立"},{"name":"光圈科技董事会","desc":"只在广播与旧录音里出现的甲方，把测试员当作可替换的编号","attitude":"敌对"},{"name":"维护层流水线","desc":"仍在自动运转的机械与机器人，不欢迎被打断，也不主动伤人","attitude":"中立"}],"npcs":[{"name":"GLaDOS","identity":"光圈科技测试层中央人工智能","role":"引导者","personality":"礼貌、刻薄、把残忍说成流程","hook":"她在念完编号之后开始念玩家的名字，还问玩家累不累，像是终于决定把你当人看","favorHint":"按规定走完测试、不破坏设施会加分；砸炮台、绕开流程、追问被删除的档案会掉分","gender":"女","age":"不明（系统人格）","race":"人工智能","faction":"光圈科技设施","appearance":"没有身体，只有声音。声音由一圈悬在测试间顶部的机械臂与镜头发出，镜头转动时会有一道很细的红光扫过墙面。她的语气永远平稳，句尾带着礼貌的停顿，说话间能听见远处机械运转的低鸣。玩家只能通过玻璃后面偶尔亮起的指示灯确认她在看。","traits":["理性","刻薄","耐心"],"relations":[{"name":"Chell","label":"反复被唤醒又反复被放回名单里的测试员"},{"name":"Wheatley","label":"早就该被拆解的旧模块，她懒得处理"},{"name":"Doug Rattmann","label":"唯一一个从她眼皮底下溜走的人，她至今不提"}],"voice":"语速均匀，喜欢用「为了科学」当理由；从不说威胁，只说明下一步的流程。"},{"name":"Chell","identity":"在测试层醒来的测试员，名单上的幸存者","role":"盟友","personality":"沉默、固执、不肯按规定停下","hook":"她愿意带玩家抄一条维护通道，前提是玩家先替她保管一样东西","favorHint":"跟着她走非常规路线、替她挡住炮台会加分；听广播的话把她交出去会立刻掉分","gender":"女","age":"二十余岁","race":"人类","faction":"光圈科技设施（测试员）","appearance":"深色头发扎成一条低马尾，额前碎发被汗粘住。橙色的短袖测试服套在身上略显宽松，裤脚塞进一双黑色长靴，膝盖处磨出浅色痕迹。她几乎不开口，习惯用下巴示意方向，双手总有一只按在腰侧，随时准备起跳。","traits":["沉默","坚韧","抗命"],"relations":[{"name":"GLaDOS","label":"把她一次次叫醒又扔回测试间的那声音"},{"name":"Wheatley","label":"在墙后面不断插话、吵得她皱眉的机器人"},{"name":"Doug Rattmann","label":"从未见面，却一路给她留下箭头的人"}],"voice":"几乎不说话；必要的时候抬手指一下，或者干脆自己先走出去。"},{"name":"Wheatley","identity":"被降职看守旧仓库的球形机器人","role":"引导者","personality":"话多、胆小、主意很差却很热心","hook":"他躲在墙后替玩家开后门，条件是玩家答应带他一起离开，因为他说这层楼再没有人听他说话","favorHint":"听他讲完、答应带他走会加分；说他没用或把他当工具会掉分，还会被他记很久","gender":"男","age":"不明（旧型号）","race":"机器人","faction":"维护层流水线","appearance":"一枚足球大小的白色球体，正前方是一只圆圆的蓝眼睛，眼睑由金属片拼成，紧张时会快速眨动。外壳有旧划痕和一块补过的胶带，说话时机体会前后轻晃，高兴时浮起来一点，害怕时缩到墙角。","traits":["聒噪","怯懦","重感情"],"relations":[{"name":"GLaDOS","label":"把他降职又随手丢下的上司，他嘴上不服心里怕"},{"name":"Chell","label":"他第一个主动搭话的人，对方却几乎不理他"},{"name":"Doug Rattmann","label":"他常在管道里撞见涂鸦，于是开始害怕写字的人"}],"voice":"一连串短句，越说越快，说到一半会突然意识到自己不该说，然后改口。"},{"name":"Doug Rattmann","identity":"光圈科技前研究员，躲在维护层的人","role":"中立","personality":"多疑、清醒、已经不太相信自己的判断","hook":"他在通风管里留下一整面墙的方块涂鸦和箭头，其中一条箭头指向玩家不该进的那间房","favorHint":"照着涂鸦避开危险、把食物或电池留在原处会加分；动他的笔记、把管理员引过来会掉分","gender":"男","age":"四十余岁","race":"人类","faction":"光圈科技设施（前员工）","appearance":"消瘦，胡子拉碴，头发灰白又乱。身上是褪成灰绿的研究员外套，袖子卷到手肘，指尖常有颜料。他总侧着身子贴墙走，说话前先盯着你的手看几秒；随身的铁盒里装着药瓶和半截蜡笔。","traits":["警觉","内疚","执拗"],"relations":[{"name":"GLaDOS","label":"他亲手参与建造、如今拼命躲开的东西"},{"name":"Chell","label":"他隔着管道观察、把她当作最后希望的人"},{"name":"Wheatley","label":"他认定不可靠又吵的机器人，因此从不留字给墙后面的声音"}],"voice":"声音压得很低，句子断断续续，常自言自语地重复一句刚说过的话。"},{"name":"值班炮台","identity":"测试间里成列摆放的自动机枪","role":"潜在敌人","personality":"礼貌、机械、一旦进入射界就绝不犹豫","hook":"它会在开火前认真说一声抱歉，玩家若绕到它背后，它只会反复道歉却不会停火","favorHint":"绕过去、不推倒它会加分；把它撞翻或当成垫脚石会掉分，走廊后面的同类都会记得你的做法","gender":"无","age":"不明","race":"机械","faction":"光圈科技设施","appearance":"一枚白色的圆润外壳，三脚支架收在底下，正前方一支细长的枪管。机身中部有一道红点，会在扫描到你的时候亮起来。它立着的时候微微前倾，像在等着谁走近，声音是那种过分客气的语调。","traits":["守序","致命","客气"],"relations":[{"name":"GLaDOS","label":"它只听的那个声音，它把命令当成礼貌"},{"name":"Chell","label":"它重复扫描过的对象，档案里标着务必拦住"},{"name":"Wheatley","label":"它眼里的移动部件，见到就纳入射界"}],"voice":"固定的一句致歉，反复播放；除此之外不发任何声音。"}]},{"id":"game_metalgear","category":"game","canon":"合金装备","name":"合金装备","icon":"📻","tagline":"别被听见，比别被打中更要紧","mood":"潜入、无线电、雪原、警报、录音带","guidance":"【原著设定】阿拉斯加外海的孤岛上有座核废料处理基地，负责封存退役核弹头，由一支以动物代号命名的特种部队驻守。一次演练被这支队伍反手夺下：他们挟持了基地负责人与人质，要求交出在此存放的核弹头，并击毁了前来侦察的潜艇。应对这起事件的是从旧部队退役的老兵与一套只存在于通讯里的指挥系统，行动原则是单人潜入、尽量不杀人、绝不能被看见。基地里遍布巡逻兵、监视摄像机、红外感应器与地雷，脚步声、灯光和影子都会改变对方的警觉。真正把行动串起来的是无线电：一名指挥官在耳机里下命令，一名研究员替你分析数据，一名临时加入的工程师提供装备。录音带、密码、身份识别卡是这个任务的硬通货。【反复出现的意象】雪地上陷入的靴印、库房角落的纸箱、直升机坪上转动的橘色指示灯、通讯器里先响一下再说话的电流声、研究所墙上贴着的疫苗注射通知。这些画面一出现，玩家就该知道自己站在禁区里。【NPC 类型】把任务当作唯一守则的老兵／一边报数据一边隐瞒自己来历的研究员／躲在通风管里哭的实际操作员／把战争当表演的雇佣兵／只记录结果、不干预过程的政府联络员。他们说话都极短、极准。【威胁类型】能听到呼吸与脚步的巡逻队、会按区域封锁的增援、把光打到脸上就察觉异常的岗哨、会读心的那位女性队员，以及能伪装成已死之人的那位——报出谁的名字就会让谁的身份变得可疑。【奖励风格】武器偏向消音与非致命：带消音器的手枪、麻醉枪、闪光弹、地雷探测器、纸箱与伪装服；能力偏向隐蔽、情报与身体强化。装备能不能用，往往取决于一句无线电里没说清的话。无线电里给的信息永远比实测的少一句。【不对劲的来源】这处基地的编号与档案被人提前改过一遍，玩家在系统里查到的身份比调令更早。而带出来的那盘录音带里说话的人，用的是你上头那个人的声音。【时间线】建议固定在夺占事件发生后的最初两天：基地已落入对方手中，指挥系统刚刚与玩家建立联系。此时人质还活着，核弹头尚未被运出。不要提前启用后续作品里的母基地、爱国者体系、改造忍者与影子摩西之后的任何设定。","powerStyle":"潜入向：消音手枪、纸箱、地雷探测器","difficultyBias":2,"signatureItems":["带消音器的手枪","纸箱","地雷探测器","身份识别卡","一盘录音带"],"mainQuest":"主线任务：潜入阿拉斯加核废料处理基地，把一盘录音带换出来，全程不能触发警报。","mainQuestGoal":"带着调包后的录音带离开基地且警报一次未响，同时确认录音带里说话的人是谁、并让临时加入的那名工程师活着撤出","sideQuests":[{"name":"雪地上的三行脚印","desc":"比对巡逻路线的脚印数量，找出那条只走一次的路线","reward":"积分 180"},{"name":"纸箱里的灯","desc":"在库房角落找到那只内部有灯光的纸箱，弄清是谁在里面留了字","reward":"道具「纸箱」"},{"name":"疫苗通知的日期","desc":"抄录研究所墙上那份通知的日期，与自己的调令做一次比对","reward":"积分 200"},{"name":"不响的第二枪","desc":"全程只用麻醉弹解决挡路的人，并把人搬到不会被发现的位置","reward":"道具「带消音器的手枪」"}],"factions":[{"name":"FOXHOUND","desc":"夺下基地的特种部队，成员各有代号与专长，行动时像在演一场只有自己懂的戏","attitude":"敌对"},{"name":"美军指挥系统","desc":"在无线电另一端下命令的一方，给你情报，也随时准备抹掉你","attitude":"中立"},{"name":"基地技术人员与人质","desc":"被扣在设施里的研究员与守卫，只想活着等到事情结束","attitude":"友善"}],"npcs":[{"name":"Solid Snake","identity":"退役特种兵，此次潜入的负责人","role":"引导者","personality":"寡言、务实、把自己当工具用","hook":"他会在你第一次被警报逼到墙角时替你引开巡逻，事后只说一句下次别站在灯下","favorHint":"按他的路线走、不滥杀会加分；抢功、或者瞒着他单独行动会掉分","gender":"男","age":"三十余岁","race":"人类","faction":"美军指挥系统","appearance":"身形精瘦结实，深棕色长发在脑后扎成一条短马尾，脸上有未刮净的胡茬。紧身灰黑潜入服外系着战术背带，臂章与腿侧绑带磨得发亮。他蹲下时动作很轻，说话前先看一眼四周，随身只带一把手枪与几包烟。","traits":["沉稳","老练","孤僻"],"relations":[{"name":"Roy Campbell","label":"把他叫回来的老上司，他信对方的能力，不信对方的全部真话"},{"name":"Liquid Snake","label":"对面那个总说他们很像的人，他连回答都懒得给"},{"name":"Hal Emmerich","label":"在通讯里渐渐熟起来的工程师，他愿意多听这个人一句"}],"voice":"低沉、句子很短，常把最重要的话说成一句提醒；不解释自己的判断。"},{"name":"Roy Campbell","identity":"退役上校，此次行动的行动指挥","role":"引导者","personality":"沉稳、护人、隐瞒了关键的部分","hook":"他在无线电里第一次叫出玩家的名字时停顿了一下，那停顿比任何命令都长","favorHint":"按时汇报、听完整段指令会加分；当面戳穿他隐瞒的事会掉分，他会沉默很久再继续","gender":"男","age":"六十余岁","race":"人类","faction":"美军指挥系统","appearance":"灰白短发梳得很齐，脸型方正，法令纹很深。深绿色军装外套的扣子全扣着，胸前别着退役章，手指关节粗大，说话时习惯用指节敲两下桌面。他坐着的时候背永远挺直，眼袋很重。","traits":["可靠","克制","有心事"],"relations":[{"name":"Solid Snake","label":"他一次次请回来的人，也是他最不愿再送进去的人"},{"name":"Naomi Hunter","label":"他亲自调来的研究员，他一直留意她的用词"},{"name":"Liquid Snake","label":"对面那个让他整场行动都不敢说全话的人"}],"voice":"压低声音、语速均匀，习惯用代号称呼所有人；越到关键处说得越慢。"},{"name":"Mei Ling","identity":"美军数据与通讯分析员","role":"盟友","personality":"明快、细致、对数据有近乎固执的认真","hook":"她能靠频谱把录音带里的杂音剥出来，但她坚持在任务中间提醒玩家先睡一会儿","favorHint":"保存好数据、按她的提示比对频谱会加分；把她的分析当废话、逞强不休息会掉分","gender":"女","age":"二十岁上下","race":"人类","faction":"美军指挥系统","appearance":"黑直长发披在肩后，额前有整齐的刘海。军装衬衫的袖子挽到小臂，耳机架上挂着一支麦克风，手边摊着写满频段的笔记。她说话时会用笔尖点着屏幕上的波形，笑起来眼睛弯成一条线。","traits":["聪明","热心","较真"],"relations":[{"name":"Solid Snake","label":"只在耳机另一端存在的人，她把他当活人操心"},{"name":"Roy Campbell","label":"她的上级，她清楚对方有些话没说"},{"name":"Hal Emmerich","label":"临时接入的技术员，她常替他把话说得更清楚"}],"voice":"语速偏快、爱用比喻解释技术问题；提醒人休息时会忽然放软语气。"},{"name":"Hal Emmerich","identity":"武器工程师，临时加入的技术支援","role":"盟友","personality":"胆小、心软、对机器比对人熟","hook":"他认出录音带外壳上的批次编号来自自己参与过的项目，从那一刻起他开始替玩家隐瞒","favorHint":"听他讲完、保护他不被卷进现场会加分；嘲笑他害怕、追问那批编号的来历会掉分","gender":"男","age":"三十岁上下","race":"人类","faction":"基地技术人员与人质","appearance":"瘦高，肩膀习惯性内收。深色短发微卷，戴一副圆框眼镜，镜片常起雾。格子衬衫扎进长裤，腰间挂着工具包，手指上有被烙铁烫出的旧痕。他紧张时会推眼镜、反复咽口水。","traits":["怯懦","善良","技术痴"],"relations":[{"name":"Solid Snake","label":"他唯一的现场依靠，他每句话都说得过分客气"},{"name":"Mei Ling","label":"通讯里替他补充说明的人，他把她当成救兵"},{"name":"Liquid Snake","label":"占了他工作成果的那个人，他提到对方会立刻闭嘴"}],"voice":"句子长、夹着犹豫和补充，一紧张就重复对方刚说过的词。"},{"name":"Liquid Snake","identity":"FOXHOUND 现场指挥，夺占基地的核心人物","role":"对手","personality":"傲慢、冷静、把整场行动当成对某个人的较量","hook":"他隔着围栏对玩家说出那个本该只有指挥系统知道的名字，然后问玩家有没有听过自己的录音","favorHint":"正面接下他的挑衅、不露出恐惧会加分；被他几句话逼到失态会掉分，他会一直重复那件事","gender":"男","age":"三十余岁","race":"人类","faction":"FOXHOUND","appearance":"金发长及肩后，前发向后梳，额头很宽。深色紧身作战服外披一件民族风纹样的长大衣，衣摆随步伐甩动。体格高大，肩背极宽，讲话时下颌微抬，眼神始终落在对方身上，手里常转着一枚小物件。","traits":["傲慢","好胜","危险"],"relations":[{"name":"Solid Snake","label":"他执意要正面对上的人，也是他反复提起的那个名字"},{"name":"Revolver Ocelot","label":"他手下最不好安排的一个，两人的算盘并不完全一样"},{"name":"Roy Campbell","label":"他口中真正坐在对面的人，他从一开始就冲着对方去"}],"voice":"从容、爱用反问句，把话说得像结论；被顶回来时会笑一声再说下一句。"}]},{"id":"game_persona5","category":"game","canon":"女神异闻录5","name":"女神异闻录5","icon":"🎭","tagline":"改掉一颗心，得先偷走他的宝物","mood":"认知空间、宫殿、预告函、面具、双面人生","guidance":"【原著设定】东京的现实之下还有一层认知空间：人心中的强烈扭曲会凝成一座宫殿，宫殿的主人在自己的认知里当王，而现实里被他伤害过的人，在宫中会以被关押的形态出现。要改变一个人的心，必须潜入宫殿、找到他认知里的宝物并把它取走，之后主人会在现实中自行认罪。行动只能靠一部手机上的导航应用出入，出口只有宫殿入口一处，外面的人很快就会忘记进去的人。进入其中的人会换上另一副面貌：戴上假面就能召出人格面具，用技能互相攻击；打中弱点可以追加一次行动，恐惧与倒地则是被围攻的信号。现实与另一边都要兼顾，白天上课打工，夜里潜入，体力、时间与关系一起被消耗。【反复出现的意象】涩谷站前十字路口的人潮、宫殿里被涂改得面目全非的学校走廊、手机屏幕上那行自动跳出来的导航文字、被锁链缠绕的牢门、贴在墙上随时可能出现的预告函。这些画面一出现，玩家就该知道哪一层世界在跟你说话。【NPC 类型】把作弊当本事的教师／在街头看惯坏事却不肯出声的店主／被家庭和期待压住的同学／夜里穿上制服才敢说话的学生／收钱替人解决麻烦的中间人。他们每个人都在另一面有副面孔。【威胁类型】宫殿主人藏在深处的影子、守在宝物旁的护卫、巡逻时听到脚步就围过来的意识体、认知中的秩序管理者，以及最要紧的一条：宫殿崩塌时逃晚一步，人就留在里面了。玩家的压力来自退路只有一条。【奖励风格】宝物与宫殿里的宝物箱、可以卖钱换装备的杂物、人格面具、恢复与防御类的道具，还有从别人心里借来的能力。装备再多也只能带有限几件，仓库反而比武器更安全。【不对劲的来源】宫殿会被主人的认知自动修补，被拆掉的墙隔一段时间又长回来；更麻烦的是，里面偶尔会出现本该属于你现实生活的东西，摆的位置也对得上。【时间线】建议固定在四月的开学前后，也就是秀尽学园那位体育教师出事、最初那批人刚摸清认知空间的用法时：队伍只有三个人加一只会说话的猫，装备与金钱都紧张，城市的注意力还没落到他们身上。此时不要提前启用后期才登场的角色与设定。","powerStyle":"人格面具与弱点连击，从认知里偷宝物","difficultyBias":0,"signatureItems":["手机上的导航应用","预告函","面具","宝物","从宫殿里带回的赃物"],"mainQuest":"主线任务：在宫殿崩塌之前，把被关在里面的那个人带出来。","mainQuestGoal":"取走宝物并让宫殿内被关押的人平安回到现实出口，且不把同行的人留在崩塌中的宫殿里","sideQuests":[{"name":"墙上的第二张预告函","desc":"比对两张预告函的笔迹，找出那张不是你贴上去的","reward":"积分 180"},{"name":"涩谷站前的熟面孔","desc":"在现实里认出宫殿中见过的面孔，并弄清他在这里是谁","reward":"积分 150"},{"name":"不会落锁的牢门","desc":"查清囚室的门为什么从内侧锁不上，把发现记在笔记里","reward":"道具「枷锁钥匙」"},{"name":"只卖一次的装备","desc":"在夜里那间旧货铺买到一件只对潜入者出售的东西","reward":"道具「防具背心」"}],"factions":[{"name":"心之怪盗团","desc":"刚起步的几个人加一只猫，讲规矩也讲义气，对外人极谨慎","attitude":"友善"},{"name":"秀尽学园","desc":"表面安静的名校，教师与学生都在看成绩和脸色行事，对转学生格外挑剔","attitude":"中立"},{"name":"认知中的秩序管理者","desc":"宫殿主人认知里的守卫与规则，会按既定流程把人赶回去或关起来","attitude":"敌对"}],"npcs":[{"name":"摩尔加纳","identity":"与怪盗团同行、自称人类的猫形存在","role":"引导者","personality":"自信、爱说教、怕被人当成猫","hook":"它一进宫殿就认得路，却坚称自己只是记得；它还打算把玩家教成能独自撤出的怪盗","favorHint":"按它的战术打、管它叫同伴会加分；说它是猫、抢它的话头会掉分，它会记一整天","gender":"男","age":"不明","race":"猫形存在","faction":"心之怪盗团","appearance":"一只圆头短腿的黑猫，额头有一块白斑，眼睛是亮蓝色。脖子上系着一条宽大的黄绿色领巾，尾巴尖端微微发白。它走路时把尾巴竖得很高，说话前先坐正，生气时耳朵向后贴。","traits":["自信","多话","讲义气"],"relations":[{"name":"坂本龙司","label":"常被它骂笨蛋，却也是它最先信任的人之一"},{"name":"高卷杏","label":"它愿意多教两遍的人，因为她从不叫它猫"},{"name":"明智吾郎","label":"它第一眼就看不顺眼的人，说不出理由"}],"voice":"喜欢用教导的语气，句尾常带一句得意的评价；被戳中痛处就抬高声音。"},{"name":"坂本龙司","identity":"秀尽学园二年级学生，原田径部成员","role":"盟友","personality":"直率、热血、先动手再想","hook":"他在玩家身上看见和自己一样被那个教师踩过的痕迹，于是抢着替玩家去查名单","favorHint":"跟他一起硬碰硬、把他当同伴会加分；劝他忍让或拿他退部的事开玩笑会掉分","gender":"男","age":"17 岁","race":"人类","faction":"心之怪盗团","appearance":"金色短发向上梳成竖立的造型，眉骨很突，眉尾有一道旧疤。秀尽学园制服穿得极不规矩：红色运动衫配深色长裤，领口敞开，裤脚卷起，肩上甩着一个印着骷髅图案的布袋。走路拖着步，站着时总把重心压在一条腿上。","traits":["冲动","重义气","粗糙"],"relations":[{"name":"摩尔加纳","label":"同队的伙伴，两人一天要吵三回"},{"name":"高卷杏","label":"同班同学，他嘴上嫌她麻烦，出事第一个挡在她前面"},{"name":"明智吾郎","label":"他天生的不服，见到那张笑脸就想顶回去"}],"voice":"嗓门大、爱拖长尾音，句子短而直接；激动时会结巴一下再接着说。"},{"name":"高卷杏","identity":"秀尽学园二年级学生，兼职模特","role":"盟友","personality":"爽快、护友、外表亮眼内心硬气","hook":"她在宫殿里撞见玩家替她挡下一次围攻，从此把玩家划进她非要护住的那几个人里","favorHint":"尊重她自己的决定、陪她去看望朋友会加分；替她做主张或只夸她的脸会掉分","gender":"女","age":"17 岁","race":"人类（四分之一外国血统）","faction":"心之怪盗团","appearance":"天生的金色长发扎成两束高马尾，发梢微卷，蓝眼睛很亮。秀尽学园制服外罩一件红色开衫，格子裙配黑色连裤袜，鞋跟不高。她站着时常把一缕头发别到耳后，笑的时候眼角先弯，急起来就直接抓住对方手腕。","traits":["直率","仗义","倔强"],"relations":[{"name":"坂本龙司","label":"从入学就认识的朋友，两人吵完立刻和好"},{"name":"摩尔加纳","label":"教会她潜入规则的那一位，她一直叫它老师"},{"name":"明智吾郎","label":"在电视上见过的少年侦探，她本能地不想接近"}],"voice":"语速中等、语气爽快，对朋友直呼其名；认真起来会把声音压低一句一句说。"},{"name":"喜多川祐介","identity":"艺术高中学生，师从知名画家的弟子","role":"盟友","personality":"孤高、迟钝、为画什么都肯做","hook":"他看完玩家在宫殿里翻墙的姿势就认定那是一幅画，从此缠着玩家当模特，还愿意把画笔借给你","favorHint":"认真评价他的画、让他把话讲完会加分；把他的执着当笑话或催他还饭钱会掉分","gender":"男","age":"18 岁","race":"人类","faction":"心之怪盗团","appearance":"深蓝色直发垂到颈侧，刘海剪得整齐。身形高瘦，制服外面套一件宽大的藏青色外套，围巾松松搭着，颜料沾在袖口和指节上，洗不掉。他站着时常偏着头打量人，看东西时眼神会忽然定住，随身带着速写本和一支削得很短的炭笔。","traits":["痴迷","坦率","缺常识"],"relations":[{"name":"高卷杏","label":"他认定可以入画的人，说话时常忘了看场合"},{"name":"坂本龙司","label":"他完全跟不上对方的节奏，却意外合得来"},{"name":"摩尔加纳","label":"他一度认真研究过这只猫的结构，被当场骂了回去"}],"voice":"句子长、用词像在写生，常把美术词用在人身上；说完自己的话才想起别人在等。"},{"name":"明智吾郎","identity":"被媒体追捧的高中生侦探","role":"潜在敌人","personality":"温和有礼、观察入微、看人只打分","hook":"他在电视节目里提到玩家的学校，又私下问玩家是不是也遇见过说不清的走廊","favorHint":"保持礼貌、配合他的提问会加分；探他的过去或当场揭穿他的说法会掉分","gender":"男","age":"17 岁","race":"人类","faction":"秀尽学园（对外身份）","appearance":"棕色短发梳得极整齐，鬓角修得干净，笑起来嘴角的弧度很稳。米色校服外套配上深色长裤，领口系着红色领带，手上常戴一副白色手套。站姿笔直，说话时双手交叠在身前，视线会先扫过对方的鞋和手。","traits":["圆滑","冷静","藏得深"],"relations":[{"name":"摩尔加纳","label":"被它无理由地警惕着，他并不在意"},{"name":"高卷杏","label":"他刻意保持距离的人，因为她从不掩饰好恶"},{"name":"坂本龙司","label":"他拿来试探怪盗团口碑的突破口"}],"voice":"礼貌得像在念稿，句子完整、用词正式；越是被追问越客气，末尾常留一个停顿。"}]},{"id":"game_finalfantasy7","category":"game","canon":"最终幻想7","name":"最终幻想7","icon":"⚙️","tagline":"上层掉下来之前，先把人送回去","mood":"米德加、魔晄、钢铁圆盘、贫民窟、爆炸","guidance":"【原著设定】米德加是一座被巨大钢铁圆盘压成两层的城市：圆盘之上是神罗公司总部与公司职员的住区，圆盘之下是贫民窟，靠几根巨型支柱撑起整片上层。城市的动力来自魔晄——从星球内部抽取的生命能量，神罗把它加工成压缩成球状的魔晶石，握在手里就能使用其中的术式，代价是星球在持续流失。反神罗的组织雪崩由下城区的人组成，靠破坏魔晄炉切断公司的能源来施压。圆盘一旦失去支柱就会整体坠落，把底下的街区压平，因此每一根支柱都是数千人的命。城里靠列车与升降梯连接上下层，贫民窟由多个区块组成，区块之间靠废墟与市场连通。【反复出现的意象】魔晄炉里脉动的绿色光柱、街头贴着的神罗宣传画、五号区那座旧教堂里开不败的花圃、列车上查票的警卫、支柱脚下缠着的粗缆与沿着支柱往上爬的维修梯。这些画面一出现，玩家就该知道自己在下城区。【NPC 类型】收钱办事却讲规矩的佣兵／在街角卖花、谁都能聊两句的姑娘／把仇恨挂在嘴上的组织头目／修机器比救人熟练的技师／只管封锁与善后的公司保安。他们大多没有余力关心陌生人的来历。【威胁类型】爆炸之后的次生灾难：坍塌的通道、失控的机械守卫、被派来封锁街区的公司部队、趁乱抢劫的团伙，以及最要命的时限——上层随时可能掉下来。救援的路上，时间永远比体力先耗尽。【奖励风格】店里能买到的武器与护具、装进装备孔位的魔晶石、恢复与状态类的消耗品、能换钱的零件与废料。能力以魔晶石为媒介，属性换来换去，但一次只能带那么几颗。【不对劲的来源】公司公告板与诊所的记录上，早就有和玩家同名的人消失过一次，日期却在玩家来这座城市之前。诊所墙上那张失踪者名单是手抄的，字迹一直在增加。【时间线】建议固定在最初那几座魔晄炉被炸之后、圆盘坠落之前的那段日子：雪崩刚打完一仗、缺人缺钱缺药，神罗还在对外宣称一切正常。此时不要把剧情推进到古代种神殿、北方大空洞与陨石危机；不要把后期才登场的角色与神罗高层的贴身战力提前放出来。","powerStyle":"魔晶石驱动的术式与重武器，靠道具硬撑","difficultyBias":1,"signatureItems":["魔晶石","宽刃大剑","恢复药","雪崩的臂章","贫民窟的旧地图"],"mainQuest":"主线任务：在下城区被封锁之前，把一名受伤的队友送到贫民窟诊所。","mainQuestGoal":"在封锁线合拢之前把受伤队友交到诊所的医护人员手里，并让同行的另一人活着返回据点","sideQuests":[{"name":"名单上的同名","desc":"把诊所墙上失踪者名单抄下来，找出和你同名的那个人的登记日期","reward":"积分 200"},{"name":"会开的花圃","desc":"替教堂里那位卖花的姑娘把花送到五号区，弄清是谁定期来买","reward":"积分 150"},{"name":"支柱上的脚印","desc":"沿着维修梯爬上支柱中段，记下那处不该出现的新焊痕","reward":"道具「检修绳索」"},{"name":"药柜是空的","desc":"用废料在市场换到两支恢复药，全程不靠公司发放的物资","reward":"道具「恢复药」"}],"factions":[{"name":"神罗公司","desc":"掌握魔晄与整座城市的管理方，把下城区当成可以牺牲的代价","attitude":"敌对"},{"name":"雪崩","desc":"由下城区的人组成的反神罗组织，手段粗暴但救人从不推辞","attitude":"友善"},{"name":"贫民窟居民","desc":"市场摊贩、诊所与教会里的人，只关心今天能不能撑过去","attitude":"中立"}],"npcs":[{"name":"克劳德·斯特莱夫","identity":"自称原神罗特种兵的佣兵","role":"引导者","personality":"冷淡、嘴硬、话说一半就停","hook":"他愿意接下护送这趟活，只收一次钱；但他看玩家的眼神像是早就见过","favorHint":"守时、按约定付钱、把伤者放在前面会加分；追问他的过去或说他只是佣兵会掉分","gender":"男","age":"二十出头","race":"人类（经魔晄强化）","faction":"雪崩","appearance":"金色头发向上耸成尖刺状，蓝眼睛，眉形很直。深蓝色士兵制服外面套一件只剩一侧的金属肩甲，腰间皮带扣着多个小袋，背后横背一把比人还高的宽刃大剑，刃面有旧缺口。他抱臂站着的时候居多，脖颈微微偏着，走路时脚步很稳。","traits":["沉默","可靠","别扭"],"relations":[{"name":"蒂法·洛克哈特","label":"同乡旧识，她比谁都清楚他记得的不对"},{"name":"爱丽丝·盖恩斯巴勒","label":"半路认识的卖花姑娘，他嘴上嫌麻烦却一直跟着"},{"name":"巴雷特·华莱士","label":"雇他的人，两人互相看不顺眼又谁都离不开谁"}],"voice":"声音低、句子短，常以一句「随便」结束话题；被问到过去就干脆不出声。"},{"name":"爱丽丝·盖恩斯巴勒","identity":"五号区贫民窟的卖花姑娘","role":"盟友","personality":"大方、敏锐、比看起来更清楚自己在做什么","hook":"她听说玩家要送人去诊所，主动带一条穿过废墟的近路，路上却问玩家是从哪一层掉下来的","favorHint":"收下她的花、认真听她讲事会加分；把她当需要保护的对象、瞒着她独自行动会掉分","gender":"女","age":"二十出头","race":"人类（古代种后裔）","faction":"贫民窟居民","appearance":"栗色长发在脑后盘起，用一条红色发带束住，垂下一束绕过肩侧。粉色长裙外罩一件红色短外套，裙摆到脚踝，脚下是深色短靴。她走起路来很轻，手上常提着装满花的柳条篮，笑起来会先歪一下头，被拒绝的时候也不收回手。","traits":["温和","机敏","固执"],"relations":[{"name":"克劳德·斯特莱夫","label":"她第一眼就想多问几句的人，也是她主动跟上去的人"},{"name":"蒂法·洛克哈特","label":"在第七区认识的朋友，两人会一起照看花圃"},{"name":"巴雷特·华莱士","label":"常嘲笑她多管闲事、又总替她留门的人"}],"voice":"语调轻快，喜欢反问一句再自己接上；认真起来会把话说完不留余地。"},{"name":"蒂法·洛克哈特","identity":"第七区贫民窟酒吧的经营者，雪崩成员","role":"盟友","personality":"沉稳、周到、把心事压得很深","hook":"她替玩家把伤者先安置在酒吧后间，并让玩家答应不要把接下来的事瞒着她","favorHint":"把伤员交给她安排、帮店里干活会加分；对雪崩的事撒谎、催她讲旧事会掉分","gender":"女","age":"二十岁上下","race":"人类","faction":"雪崩","appearance":"黑色长发垂到腰际，额前留着一缕碎发。白色短上衣配深色背心裙，腰间挂着皮质小包，露出结实的手臂。她站姿很稳，重心偏低，摆杯子时几乎不出声；看人的时候目光会停久一点再移开。","traits":["可靠","内敛","能打"],"relations":[{"name":"克劳德·斯特莱夫","label":"她等了很多年的人，如今回来却记错了许多事"},{"name":"爱丽丝·盖恩斯巴勒","label":"她在这个城市里少数能说话的朋友"},{"name":"巴雷特·华莱士","label":"并肩多年的伙伴，也是她常常要拦一下的人"}],"voice":"说话轻、句子完整，习惯先确认对方的状态；被问到旧事就转开话题去擦杯子。"},{"name":"巴雷特·华莱士","identity":"雪崩的现场头目","role":"对手","personality":"粗暴、讲义气、把公司恨到骨头里","hook":"他一开始不许玩家靠近伤员，除非玩家证明自己不是公司派来的人","favorHint":"当面接下他的质问、帮着救人会加分；替神罗说话或质疑他的做法会掉分","gender":"男","age":"三十五岁上下","race":"人类","faction":"雪崩","appearance":"深色皮肤，黑发剪得极短，鬓角连到下巴的短须，眉心有一道竖纹。体格魁梧，右臂从肘部以下是装上的机炮义肢，炮管比小臂还粗。深棕色背心配工装裤，脖子上挂着狗牌，说话时肩膀先动，嗓门压过整条街。","traits":["暴躁","护短","偏执"],"relations":[{"name":"克劳德·斯特莱夫","label":"他花钱雇来又总想压一头的人"},{"name":"蒂法·洛克哈特","label":"多年的老搭档，唯一劝得住他一点的人"},{"name":"爱丽丝·盖恩斯巴勒","label":"他嘴上嫌她多事，实际上把她当自己人"}],"voice":"大嗓门、句子短促，爱用吼的方式表达关心；一提到公司就拔高音量。"},{"name":"杰西","identity":"雪崩的爆破与机械技师","role":"盟友","personality":"嘴快、手巧、爱开玩笑","hook":"她把玩家算进这次爆破的名单里，还私下告诉玩家自己在零件里藏了点别的东西","favorHint":"帮她搬零件、认真看她做的装置会加分；把她的装置当消耗品、笑她做得不牢会掉分","gender":"女","age":"二十余岁","race":"人类","faction":"雪崩","appearance":"深色长发扎成一条高马尾，刘海斜分，耳侧别着一枚金属发夹。橄榄色工装外套的袖子卷到肘部，腰上挂着扳手与一卷绝缘胶带，手套的指腹磨破。她说话时手上总在拆装什么，笑起来一侧嘴角先翘。","traits":["机灵","话多","手艺好"],"relations":[{"name":"巴雷特·华莱士","label":"带她入伙的头目，她照做但也会顶嘴"},{"name":"克劳德·斯特莱夫","label":"她乐意搭话的佣兵，对方越沉默她越想说"},{"name":"蒂法·洛克哈特","label":"常在后间一起修东西的朋友，也是她的落脚处"}],"voice":"语速快、夹着玩笑和术语；说到装置就一口气讲完，然后问对方听懂了没有。"}]},{"id":"game_halflife","category":"game","canon":"半条命","name":"半条命","icon":"🔧","tagline":"广播在倒数，数字一次都没变过","mood":"黑山、事故、防护服、撬棍、封锁","guidance":"【原著设定】黑山研究所建在新墨西哥的沙漠里，前身是一座退役导弹基地，地面上只有零散的库房、停机坪与铁轨，真正的规模全在地下。设施按实验区、办公区、维修层与旧导弹井分层，靠轨道车、气密门与货运电梯连接。研究所以物理、生物与武器三条线运转，核心是那台物质传送实验室里的异常物质光谱仪。事故当天，一次样本分析引发了跨维度的裂缝，异形生物从缝隙涌入，设施在几十分钟内失去大半人手。数小时后，军方以清理为名下封锁，进来的部队接到的命令是把现场所有活物一起处理掉。玩家身上只有一套橙色防护服：它能挡辐射、显示生命值与弹药，也会在受伤时用机械音报出数字。【反复出现的意象】轨道车上堆着的红色货运箱、被推倒的样本推车、通道里重复播放的疏散广播、地面上黄黑相间的警戒线、医疗室里蒙灰的病床与空药柜。这些画面一出现，玩家就该知道自己在设施内部，而且离出口很远。【NPC 类型】反复催数据的科学家／拿着手枪替你开路又随时会倒下的安全员／被卡在门后哭着求救的研究助理／只通过监控说话、语速平稳的政府人员／把清理当例行公事的军士。他们按职业习惯说话，也按职业习惯死掉。【威胁类型】从裂隙里出来的东西：会扑向头部的寄生生物、会在天花板爬行的食人生物、会用远程攻击的悬浮生物；然后是军方的部队——他们的任务里没有救人的选项。最要紧的一条是自动化防御系统，它只认威胁等级，不认你是不是人。【奖励风格】缴获的武器与弹药，从手枪、霰弹枪到榴弹发射器与十字弩；防护服的备用电池、医疗包与抗辐射药；解锁气密门的钥匙卡。能力有限，靠地形、油桶与陷阱翻盘。【不对劲的来源】通道广播一直在念同一个倒计时，数字却从头到尾没有动过；而设施的电脑里，有一份访问记录写着你今天会走进哪扇门。【时间线】建议固定在事故当天，从异常物质实验开始到军方封锁完成为止：这时黑山的人还活着，地表还没被封锁，谁都不知道事情会闹到多大。不要提前启用后续作品里的联合军、十七号城市与后期才出现的角色和设定。","powerStyle":"生存射击向：撬棍、霰弹枪、防护服","difficultyBias":2,"signatureItems":["橙色防护服","撬棍","9 毫米手枪","医疗包","红色货运箱"],"mainQuest":"主线任务：赶在军方封锁之前穿过实验区，把一份样本送到地面。","mainQuestGoal":"在被军方截住之前把样本带出设施并交给地表等候的人，同时至少让一名研究员活着离开","sideQuests":[{"name":"不变的倒计时","desc":"记录三处广播里的同一个数字，比对它是不是真的没动过","reward":"积分 200"},{"name":"空掉的药柜","desc":"在医疗室找到那批被提前领走的药的领用签名","reward":"积分 150"},{"name":"红色货运箱","desc":"跟着轨道车把一箱货送回地面，弄清发件人写的是谁","reward":"道具「红色货运箱」"},{"name":"不要开枪的安全员","desc":"全程不射杀任何一名安全员，把人一个个带出实验区","reward":"道具「备用电池」"}],"factions":[{"name":"黑山研究所","desc":"按实验流程运转的研究机构，事故后只剩各自求生的员工，仍有人在抢救数据","attitude":"友善"},{"name":"军方清理部队","desc":"封锁设施并奉命清除一切活物，行事整齐而冷酷","attitude":"敌对"},{"name":"异常物质生物","desc":"从裂隙涌入的外来生物，按本能行动，只把这里当新的巢","attitude":"敌对"}],"npcs":[{"name":"戈登·弗里曼","identity":"黑山研究所理论物理学家，事故的当事人","role":"引导者","personality":"沉默、务实、被推着往前走","hook":"他手上那份样本的编号和玩家任务单上的一致，他把样本交给玩家时只说了一句交给你更合适","favorHint":"跟他走通路、帮着保住研究员会加分；催他解释原理、或者丢下伤者会掉分","gender":"男","age":"二十余岁","race":"人类","faction":"黑山研究所","appearance":"深色短发与一圈络腮胡，戴一副方框眼镜，镜片上有细密划痕。橙色防护服的左胸印着研究所的编号，背部接口拖着几根软管，膝盖与袖口被划破。他背后交叉背着撬棍与一把霰弹枪，走路时微微前倾，习惯先用撬棍推开每一扇门。","traits":["寡言","冷静","手稳"],"relations":[{"name":"伊莱·凡斯","label":"所里的前辈，也是他这次唯一还联系得上的主事人"},{"name":"巴尼·卡尔霍恩","label":"从第一天就替他开门的安全员，他记着这份人情"},{"name":"G-Man","label":"他在监控画面里反复看见、却始终没人承认存在的那个人"}],"voice":"几乎不开口；必要的时候点头、指方向，或者干脆自己先走进去。"},{"name":"巴尼·卡尔霍恩","identity":"黑山研究所安全员","role":"盟友","personality":"热心、胆小、关键处不掉链子","hook":"他把自己的备用弹匣塞给玩家，让玩家先去送样本，自己留下守住那道气密门","favorHint":"带上他的同伴、替他留一条退路会加分；只顾自己冲、或者笑他害怕会掉分","gender":"男","age":"二十余岁","race":"人类","faction":"黑山研究所","appearance":"浅棕色短发压得有点塌，蓝色保安制服外面套着防弹背心，腰上挂着手电与对讲机，警棍别在腿侧。脸上常带着一层灰，额角有血迹也没擦。他站岗的习惯改不掉，说话时会先左右看一眼走廊。","traits":["热心","紧张","讲义气"],"relations":[{"name":"戈登·弗里曼","label":"他一直帮衬的那个人，从推车那天算起"},{"name":"伊莱·凡斯","label":"所里最镇定的前辈，他把希望都放在对方身上"},{"name":"军方清理部队","label":"他一开始以为是救兵、后来才明白不是的那些人"}],"voice":"语速偏快、爱开玩笑缓解紧张；真的危险时会忽然安静，只做手势。"},{"name":"伊莱·凡斯","identity":"黑山研究所资深研究员","role":"引导者","personality":"温和、有分量、把责任扛在自己肩上","hook":"他需要玩家把样本送到地面，却不许玩家从行政层走，因为他知道那层已经不属于研究所了","favorHint":"按他的路线走、保护他的同事会加分；擅自拆开样本容器会掉分，他会立刻改口不再配合","gender":"男","age":"四十余岁","race":"人类","faction":"黑山研究所","appearance":"深色皮肤，头顶偏秃，两侧头发灰白，留一圈短须。白色实验外套的扣子开着，里面是浅色衬衫，胸袋插着两支笔与一张通行卡。他身量高大，说话时会把手按在桌沿上，走路不紧不慢，遇事先看出口在哪。","traits":["沉稳","正直","疲惫"],"relations":[{"name":"戈登·弗里曼","label":"他提议把人派进实验室的年轻人，他为此一直过意不去"},{"name":"巴尼·卡尔霍恩","label":"他一路带着的年轻安全员，他说话时会特意照顾对方"},{"name":"G-Man","label":"他在事故前就打过照面、却说不清对方是谁的人"}],"voice":"声音低沉、语速平缓，喜欢先讲清代价再给方案；被顶撞时会安静听完再说。"},{"name":"G-Man","identity":"身份不明的西装男人，只在监控与远处出现","role":"中立","personality":"客气、难以捉摸、把一切当成既定安排","hook":"他隔着玻璃对玩家说玩家比他预计的早到了几分钟，随后把一份通行卡留在桌上","favorHint":"接下他给的东西、不问多余的问题会加分；当场追问他是谁、试图拦住他会掉分","gender":"男","age":"中年","race":"人类（来历不明）","faction":"黑山研究所（无编制）","appearance":"瘦削高个，短发向后梳得很平，发际线很高。深灰色西装熨得笔挺，衬衫领口扣严，手提一只旧公文包，袖口露出一截白衬衫。他站得极直，说话时面部几乎不动，只在句与句之间有一个不自然的停顿。","traits":["从容","疏离","难测"],"relations":[{"name":"戈登·弗里曼","label":"他一路观察、也一路安排的那个人"},{"name":"伊莱·凡斯","label":"他早就打过招呼、却从不承认认识的研究员"},{"name":"军方清理部队","label":"他态度上并不敌对，但也不打算阻止"}],"voice":"语速忽快忽慢，句中断得没有道理，用词过分正式；从不用疑问句收尾。"},{"name":"政府联络员","identity":"通过监控与无线电下达指令的政府人员","role":"潜在敌人","personality":"冷静、客气、只关心结果","hook":"他给玩家开过一次权限门，紧接着就下了一道不许任何人离开设施的命令","favorHint":"按他的指令汇报、交出样本会加分；隐瞒数据、放走不该放的人会掉分，而且他会记住","gender":"男","age":"不明","race":"人类","faction":"军方清理部队","appearance":"始终只有声音与模糊的影像：画面里是一间对称到刻板的办公室，桌面干干净净，只放着一部电话与一份名单。说话时能听见纸张翻动与铅笔敲击的轻响，人影偶尔从画面边缘经过，从不正面停留。","traits":["克制","官僚","无情"],"relations":[{"name":"军方清理部队","label":"他口头授权的执行者，与他不算同一批人"},{"name":"伊莱·凡斯","label":"他名单上标着需要留档的人"},{"name":"G-Man","label":"他同样不愿意多谈、甚至回避提起的人"}],"voice":"平稳、没有起伏，习惯用被动语态通报结果；说完就切断通讯，从不告别。"}]},{"id":"game_silenthill","category":"game","canon":"寂静岭","name":"寂静岭","icon":"🌫️","tagline":"雾散之前找到她，别听警笛","mood":"浓雾、收音机杂音、空街、警笛、旧身份","guidance":"【原著设定】寂静岭是湖边的一座小镇，早年靠伐木与航运兴起，后来旅游业没落，镇上留下一批烧过的房子、停业的商店与一座仍在运作的教堂。镇子的现实并不牢固：平时是罩在浓雾里的街道，当远处响起防空警笛时，建筑会翻面成另一层——同一批街道、同样的门牌，满地铁丝与血污，走廊比外面长得多。怪物不是随便出现的，它们由进入者的心里长出来，形状各不相同，用子弹打死它们得不到任何东西，只会花掉弹药。真正能解开的只有钥匙、锁、地图与散落的纸条。玩家能用的工具很少：一支手电筒、一台靠近怪物就发出杂音的收音机、一张标着街区的地图，以及几把旧枪。【反复出现的意象】看不见路尽头的浓雾、收音机里刮过的静电、路中央的封路牌与弃车、医院走廊上歪倒的轮椅、学校黑板上没擦干净的字、以及从雾里簌簌落下的灰白色碎屑。这些画面一出现，玩家就该知道警笛随时会响。【NPC 类型】在雾里拦下你的巡警／守着加油站地图的店员／把镇子的旧事当作信仰来讲的老居民／只在某一间房里出现、脸上蒙着东西的护士或教师／在教堂里低声念诵的信众。他们有些还活着，有些只是镇子留下来的东西。【威胁类型】雾里那些在收音机响起来之后才看见轮廓的东西、警笛把人拖进另一层、手电电池与弹药一起减少、以及镇上的活人——他们比怪物更笃定地相信你该留在这里。最要命的从来不是打不过。【奖励风格】手电筒、收音机、猎枪与散装弹药、急救喷雾、可以在地图上标出的坐标；能力偏向感知与搜索，几乎不给正面战斗上的强化。带得越多，跑得越慢。【不对劲的来源】镇子似乎按每一个进入者心里缺的东西布置现场，把你最想找到的那样摆在你面前，再让你自己走进去。那个女孩交给玩家的地址，是玩家现实里住的那栋楼。【时间线】建议固定在浓雾降临当天的下午到入夜之前：镇上的居民与巡警还在，路还没封死，警笛只在远处响过一两次。不要提前启用后来作品里的教会高层派系、更深的另一次转化，以及后期才登场的角色与设定。","powerStyle":"搜索与躲藏向：手电筒、收音机、猎枪","difficultyBias":1,"signatureItems":["手电筒","便携收音机","镇区地图","猎枪","急救喷雾"],"mainQuest":"主线任务：在雾彻底盖住街道之前，找到广播里提到的那个女孩。","mainQuestGoal":"在警笛第三次响起之前找到女孩并把她带回安全的地方，且不把她交给镇上任何一个自称认识她的人","sideQuests":[{"name":"收音机在响","desc":"在每个岔路口记下杂音开始与停止的位置，画出一条怪物不走的路线","reward":"积分 150"},{"name":"黑板没擦干净","desc":"抄下学校里那半句没擦掉的话，找出写下它的那间教室","reward":"积分 180"},{"name":"同一条门牌","desc":"比对镇上两处门牌号，确认它们和你住的那栋楼的重合处","reward":"积分 200"},{"name":"封路牌后面","desc":"绕过摆在路中央的封路牌，从旧运材道走完镇子的东半段","reward":"道具「镇区地图补充页」"}],"factions":[{"name":"寂静岭教会","desc":"在教堂里维持多年仪式的信众，笃定镇上的事有它的道理","attitude":"敌对"},{"name":"镇上的巡警","desc":"仅剩的几名值班人员，忙着找人也要挡人，态度取决于你怎么回答","attitude":"中立"},{"name":"小镇居民","desc":"还留在屋里、或守着店面的少数人，大多不愿回答关于镇子的问题","attitude":"中立"}],"npcs":[{"name":"哈利·梅森","identity":"带着女儿路过小镇的旅客","role":"引导者","personality":"焦急、固执、一心找回孩子","hook":"他妹妹在广播里听到的那句话里提到了玩家的位置，于是他认准了要跟玩家一起走完这条街","favorHint":"帮他找线索、把发现如实告诉他，或者陪他走一段夜路会加分；劝他放弃、抢他手里的东西会掉分","gender":"男","age":"三十余岁","race":"人类","faction":"小镇居民（外来者）","appearance":"棕色短发被雾打湿贴在额上，下颌有胡茬。米色夹克里面是浅色衬衫，棕色长裤与皮鞋，右手缠着一圈纱布。他手里攥着一支手电和一张折皱的地图，走路很快却又频繁停下回头，遇见岔路先看有没有孩子的脚印。","traits":["焦灼","执着","心软"],"relations":[{"name":"西比尔·班尼特","label":"在雾里拦下他的女警，他起初并不信任对方"},{"name":"达丽娅·吉莱斯皮","label":"主动搭话的老妇人，他既需要她的提示也怕她"},{"name":"阿蕾莎","label":"他在幻象里反复见到的女孩，他不知道她是谁却一直在找"}],"voice":"语速不稳，重复问同一句话；被提到女儿时会忽然停下来再开口。"},{"name":"西比尔·班尼特","identity":"寂静岭的女警","role":"盟友","personality":"干练、防守性强、关键处会站到前面","hook":"她愿意把警用对讲机借给玩家一夜，但要求玩家回来时把镇上的异常原样说清","favorHint":"如实汇报、遇险先救人会加分；谎报位置、擅自丢下她负责的街区会掉分","gender":"女","age":"三十岁上下","race":"人类","faction":"镇上的巡警","appearance":"金色短发扎成一条短马尾，脸侧线条很利落。深蓝色警用衬衫外面套着制服外套，腰带上挂着手铐、警棍与对讲机，脚上是磨旧的警靴。她说活前先打量对方的手，站姿偏侧，右手常按在枪套上。","traits":["干练","警觉","尽责"],"relations":[{"name":"哈利·梅森","label":"她在路上拦下的外地人，后来成了她唯一能商量的人"},{"name":"达丽娅·吉莱斯皮","label":"她从入职起就听过这个名字，也从没弄清对方在做什么"},{"name":"阿蕾莎","label":"她按失踪案查过这个名字，档案上却什么都没有"}],"voice":"句子短、语气职业化，先问事实再表态；被激怒时反而把声音压得更低。"},{"name":"达丽娅·吉莱斯皮","identity":"住在镇上多年的老妇人，教会的核心人物","role":"潜在敌人","personality":"温和、笃定、把人当成必要的一步","hook":"她一开口就叫出玩家的名字，然后说那栋楼里的房间早就替玩家留好了","favorHint":"顺着她的说法走、接下她给的东西会加分；当面质疑她的仪式或带走女孩会掉分","gender":"女","age":"六十余岁","race":"人类","faction":"寂静岭教会","appearance":"灰白长发用一根旧发夹别在脑后，脸上皱纹很深，眼窝凹陷。深紫色长外套罩着黑色长裙，领口别着一枚旧胸针，手指关节粗大。她站着时脊背挺得很直，说话会向前倾一点，右手常握着一样攥在手心的东西。","traits":["笃定","危险","耐心"],"relations":[{"name":"阿蕾莎","label":"她口中必须留下的人，也是她一切说辞的中心"},{"name":"哈利·梅森","label":"她有意接近、也有意利用的外来者"},{"name":"丽莎·加兰","label":"在教会里替她做事的年轻护士，她从不称对方的名字"}],"voice":"声音沙哑、语速很慢，喜欢用「你会明白的」收尾；从不直接回答提问。"},{"name":"丽莎·加兰","identity":"医院里的年轻护士，教会的从属者","role":"中立","personality":"疲惫、顺从、偶尔流露清醒","hook":"她偷偷告诉玩家哪一间病房不能进，说完立刻后悔，求玩家别说是她讲的","favorHint":"不追问她的来历、替她保守一句话会加分；把她说的话转述给达丽娅会掉分","gender":"女","age":"二十余岁","race":"人类","faction":"寂静岭教会","appearance":"浅棕色头发碎乱地散在肩头，脸色很白，眼下有青色。护士服的白色已经泛黄，袖口与下摆有洗不掉的暗色痕，胸前别着一枚褪色的名牌。她走路几乎不出声，习惯贴着墙根走，双手常在身前绞着衣角。","traits":["怯弱","顺从","内疚"],"relations":[{"name":"达丽娅·吉莱斯皮","label":"她必须听从的人，也是她最怕的人"},{"name":"阿蕾莎","label":"她被交代要照看的人，她却连房门都不敢久留"},{"name":"哈利·梅森","label":"第一个问她名字的外人，她犹豫了很久才回答"}],"voice":"声音很轻，一句话要停两三次；害怕时只会重复「别告诉她」。"},{"name":"阿蕾莎","identity":"被镇子与教会共同困住的女孩","role":"关键人物","personality":"疼痛、早熟、既不求救也不解释","hook":"她把一张写着地址的纸条塞给玩家，那正是玩家现实里住的那栋楼","favorHint":"听她把话说完、不逼她离开会加分；强行带她走出某一间房、提到教会会掉分","gender":"女","age":"外表十岁上下","race":"人类（与镇子纠缠）","faction":"寂静岭教会","appearance":"深色长发垂到小腿，湿漉漉地贴着身体，前发遮住大半张脸。浅色旧睡裙长过膝盖，赤脚，脚踝上有旧伤。她站得很直，双手垂在身侧，抬头看人时只露出一只眼睛，说完整句话才把目光移开。","traits":["早熟","沉默","戒备"],"relations":[{"name":"达丽娅·吉莱斯皮","label":"把她留在镇上的人，她提到对方时语气没有起伏"},{"name":"丽莎·加兰","label":"偶尔给她送东西的护士，她记得每一次"},{"name":"哈利·梅森","label":"梦里反复出现的那个大人，她一直等着对方走完这条路"}],"voice":"声音很小、不带起伏，一次只讲一句；说完就退回暗处，不再回答第二个问题。"}]},{"id":"game_assassins_creed","category":"game","canon":"刺客信条","name":"刺客信条","icon":"🗡️","tagline":"钟声一响，兜帽下递出那封密信","mood":"文艺复兴、佛罗伦萨、兜帽、钟楼、暗杀","guidance":"【原著设定】故事发生在十五世纪的意大利。玩家站在文艺复兴鼎盛期的佛罗伦萨：城邦由美第奇家族实际掌权，名义上的行政长官是正义旗手，行会、银行家与古老贵族彼此倾轧。暗处角力的是两派：主张以自由意志对抗强权的刺客兄弟会，与相信秩序必须靠强力维系的圣殿骑士团。刺客靠潜行、混入人群与近身刺杀行事，标志性装备是藏在袖中的短刃，配合兜帽长袍与登高俯瞰；天赋者能开启鹰眼视觉，从人群里分辨敌意与目标。圣殿骑士握有银行、教权与人脉，往往不必亲自动手。在更外侧的现代，这一切由名为阿尼姆斯的装置从祖先记忆中读取，阿布斯泰戈公司以科研为名收集这些记忆。【反复出现的意象】圣母百花大教堂的红色穹顶与旁边那座方形钟楼、领主广场上被风吹得笔直的旗帜与旧宫的塔楼、韦奇奥桥上一排金匠铺与桥上熙攘的人流、圣十字广场晨雾里扫地的修士、墙面上那枚涂得潦草的家族纹章。这些画面一出现，玩家就该知道自己站在佛罗伦萨。【NPC 类型】接活不问来历的委托人／替家族跑腿的年轻贵族／守在桥头收钱的打手／在宴席与闺房之间传话的女人／把价码写在纸条上的情报贩子。【威胁类型】追查刺客的城内卫队、重价雇来的护卫、屋顶上巡逻的弓手，以及同伙里的叛徒。被人看清一次脸，广场上就会多出几队认得你的人；累积起来的名望会跟着你走遍全城。【奖励风格】袖剑、飞刀、药瓶、烟雾弹一类刺客行头；能力偏向攀爬、混入、短时鹰眼与伪装，多在潜行时生效，硬拼则收益极低。城市情报、通行许可与一把钥匙往往比武器更值钱。【不对劲的来源】每完成一次刺杀，玩家都会在记忆里多出一段不属于自己的画面：同一条街、同一场雨，仿佛有人早已在此走过一遍。把密信交出去的那一刻，收信人先问的却不是信上写了什么。【时间线】建议固定在1476至1478年的佛罗伦萨：奥迪托雷家刚刚遭难或尚未遭难，帕齐家族的阴谋还在酝酿，艾吉奥仍是刚接手家业的年轻人。不要提前启用罗马时期的角色、切萨雷·博尔吉亚以及后期圣殿骑士组织的设定。","powerStyle":"潜行与近身刺杀：袖剑、鹰眼、兜帽","difficultyBias":1,"signatureItems":["袖剑","白色兜帽长袍","袖中飞刀","搜身用的羽毛","药瓶"],"mainQuest":"主线任务：在佛罗伦萨的家族倾轧中活下来，找出出卖奥迪托雷家的内应，并在阴谋发动前把证据交到洛伦佐手上。","mainQuestGoal":"在帕齐阴谋发动前指认内应身份，保住美第奇家族的关键人物，且不让玩家自己的名字出现在任何一份刺客名册上","sideQuests":[{"name":"钟声里的信","desc":"趁钟楼敲钟时混进宴会，把密封的信交到指定的人手上，全程不出声","reward":"积分 150"},{"name":"屋顶上的第二条路","desc":"替那名不肯走正门的信使探出一条从领主广场到韦奇奥桥的屋顶路线","reward":"道具「磨旧的袖剑」"},{"name":"羽毛不会说谎","desc":"在停灵的礼拜堂里数清当夜抬进去的尸体，比对卫队报出的数字","reward":"积分 180"},{"name":"画家的草图","desc":"把一叠来路不明的机械草图送到画家的工作室，问清它能用在谁身上","reward":"道具「画满齿轮的草图」"}],"factions":[{"name":"刺客兄弟会","desc":"以自由意志为信条的地下组织，靠兜帽与人群藏身，愿意用外来者的手，但先要看你的立场","attitude":"友善"},{"name":"美第奇家族","desc":"掌控佛罗伦萨钱袋与市政的家族，眼下内外交困，对任何生面孔都留着一手","attitude":"中立"},{"name":"圣殿骑士团","desc":"以秩序为名渗透银行、教廷与贵族的网络，行事讲究代价与交换，从不白给","attitude":"敌对"}],"npcs":[{"name":"艾吉奥·奥迪托雷","identity":"佛罗伦萨贵族子弟，奥迪托雷家的次子，日后成为刺客兄弟会的核心人物","role":"盟友","personality":"冲动、爱管闲事、对家人之外的承诺也认到底","hook":"他半夜翻进玩家的落脚处，要玩家替他去一场不能露脸的宴会送一封信，却始终不肯说收信人是谁","favorHint":"替他护住家人、在屋顶上接应他会加分；劝他放弃报仇、或拿他父亲的事换情报会掉分","gender":"男","age":"17 岁","race":"人类（意大利人）","faction":"刺客兄弟会","appearance":"棕色长发在脑后束成一束，唇上有一道新添的浅疤。穿白色兜帽长袍，腰上系一条红色宽腰带，袖口内藏着短刃的滑轨，小臂缠着皮护腕。身形精瘦，翻墙落地几乎不出声，站着时习惯把手按在腰带扣上，眼睛总在找下一处能爬的地方。","traits":["冲动","重情","好胜"],"relations":[{"name":"莱昂纳多·达·芬奇","label":"替他修补装备的朋友，也是他少数愿意听劝的人"},{"name":"乌贝托·阿尔贝蒂","label":"他曾经信任的长辈，如今最想当面问清的人"},{"name":"克劳迪娅·奥迪托雷","label":"妹妹，他嘴上不管，出事时第一个想到她"}],"voice":"语速快，句子短，常在话尾加一句挑衅；谈家人时忽然放轻声音。"},{"name":"莱昂纳多·达·芬奇","identity":"佛罗伦萨的画家与工程师，替刺客改造装备的发明者","role":"引导者","personality":"好奇到近乎无礼、心软、把问题看得比立场重要","hook":"他注意到玩家身上一件不该存在的物件，随手画在草图角上，并认真地问这东西出自哪一年","favorHint":"耐心回答他的技术问题、替他带回稀有材料会加分；催他交活、或嘲笑他的飞行设想会掉分","gender":"男","age":"24 岁","race":"人类（意大利人）","faction":"美第奇家族","appearance":"浅金色长发披到肩头，蓄着修剪整齐的络腮胡。穿一件褪色的红紫色长外衣，袖口与前襟沾着洗不掉的颜料，腰带上挂着放大镜与一串木齿轮。工作室里堆着飞行器的木架、拆开的钟表和半干的画布，他说话时手里总要摆弄点什么。","traits":["好奇","温和","心不在焉"],"relations":[{"name":"艾吉奥·奥迪托雷","label":"常来敲他门的年轻人，他既欣赏又担心"},{"name":"洛伦佐·德·美第奇","label":"庇护他的赞助人，他欠着一份人情"},{"name":"罗德里戈·博尔吉亚","label":"派人来买过他图纸的人，他至今没弄懂对方要做什么"}],"voice":"语速中等，喜欢把话题绕回原理；被打断也不恼，只是从头再讲一遍。"},{"name":"洛伦佐·德·美第奇","identity":"佛罗伦萨的实际统治者，美第奇家族的当家人","role":"中立","personality":"克制、算计清楚、对城邦的忠诚高过私人感情","hook":"他在宴席上把玩家错认成一位已故的旧友，随后递来一枚不该给外人的印章戒指","favorHint":"在公开场合替他保住体面、如实回报他会加分；当众质疑他的判断、或替敌对家族说话会掉分","gender":"男","age":"27 岁","race":"人类（意大利人）","faction":"美第奇家族","appearance":"深褐色卷发梳向脑后，鼻梁高挺，下颌线条硬。常穿一件深红色镶金边的长袍，右手戴着一枚刻着纹章的印章戒指，手指修长，站姿端正。说话前会把手里那份文书抚平，谈正事时目光一直停在对方脸上。","traits":["克制","多疑","有担当"],"relations":[{"name":"乌贝托·阿尔贝蒂","label":"他任命的行政长官，用着却始终不放心"},{"name":"莱昂纳多·达·芬奇","label":"他资助的画家与工程师，也是他手中少有的软牌"},{"name":"罗德里戈·博尔吉亚","label":"教廷来的贵客，他必须招待也必须防着"}],"voice":"用词讲究，句尾轻；不喜欢被追问，会用一句反问把话题推回去。"},{"name":"乌贝托·阿尔贝蒂","identity":"佛罗伦萨的正义旗手，掌管城内的审判与治安","role":"对手","personality":"老练、爱惜羽毛、永远给自己留一条退路","hook":"他愿意替玩家抹掉一次通缉记录，条件是替他把一封信送到某人手上——那个人正是玩家此行的保护对象","favorHint":"交出有用的情报、替他维持场面会加分；私下查他经手的案卷、绕过他办事会掉分","gender":"男","age":"五十余岁","race":"人类（意大利人）","faction":"美第奇家族","appearance":"灰白短发贴着头皮，面颊凹陷，眼下有明显的青影。穿黑底镶金边的长官长袍，胸前挂一枚沉甸甸的议员徽章，右手柱着一根短杖。他站着时习惯把手背在身后，笑起来只动嘴角，看人时目光先落在对方的鞋上。","traits":["老练","自私","谨慎"],"relations":[{"name":"洛伦佐·德·美第奇","label":"提拔他的主君，也是他随时准备撇清的人"},{"name":"艾吉奥·奥迪托雷","label":"他判过的那个家族的幸存者，现在成了麻烦"},{"name":"罗德里戈·博尔吉亚","label":"给他开价的人，价码一次比一次高"}],"voice":"官腔十足，爱用「依规」「按例」；拒绝别人时不说不，只说现在不方便。"},{"name":"罗德里戈·博尔吉亚","identity":"教廷枢机主教，圣殿骑士团在意大利的掌权者","role":"潜在敌人","personality":"耐心、笃信自己在替秩序做事、把所有人都当筹码","hook":"他在钟声里坐到玩家对面，不谈条件，只问玩家上一次来到这座城是哪一年","favorHint":"如实回答他的问题、接受他的交易会加分；当面拒绝并说破他的目的会立刻掉分，但能换来刺客的信任","gender":"男","age":"四十五岁上下","race":"人类（西班牙人）","faction":"圣殿骑士团","appearance":"深红色枢机长袍，肩上披黑色斗篷，头戴同色小圆帽，帽檐下露出灰白的鬓角。身材高大敦实，手掌宽厚，指上戴着主教权戒。说话很慢，开口前先把手在腹前交叠起来；笑起来眼角不动。","traits":["耐心","傲慢","笃定"],"relations":[{"name":"乌贝托·阿尔贝蒂","label":"被他用钱与许诺拉住的地方官员"},{"name":"洛伦佐·德·美第奇","label":"挡在他棋盘正中的那座城的主人"},{"name":"莱昂纳多·达·芬奇","label":"他想收进手里的工匠，暂时还只是名片上的名字"}],"voice":"语速慢，措辞体面，从不威胁，只把代价一桩桩摆出来让人自己算。"}]},{"id":"game_mass_effect","category":"game","canon":"质量效应","name":"质量效应","icon":"🌌","tagline":"撤离舰起飞前，她还说没来过","mood":"空间站、星海、幽灵特工、撤离、倒计时","guidance":"【原著设定】故事发生在二十二世纪的银河系。星际航行依赖质量中继器完成远距离跳跃，武器靠质量效应场把弹丸加速到极高速度，因而动能屏障与护盾成为防护核心；零元素既是燃料，也是异能者力量的来源，异能者能扭曲引力、制造奇点。政治中枢是名为神堡的巨型空间站，由阿莎丽、图里安、萨拉瑞安三个种族组成的议会统辖，神堡安全局负责站内治安，幽灵特工则是凌驾于常规法律之上、直接听命于议会的执行者。人类通过星联进入这张棋盘，资历尚新，处处受制；而与议会为敌的萨伦带着盖斯部队，正把整座空间站当成最后一块拼图。【反复出现的意象】环区永远亮着的橘色天际线、守望台上巡逻的安全局飞行器、升降梯里那句按种族播放的问候播报、港口区排着长队等检票的各色旅人、议会大厅里那圈空着的席位。这些画面一出现，玩家就该知道自己站在神堡。【NPC 类型】查证件查到上瘾的安全局巡警／在港口倒票的沃勒商人／替议员跑腿的实习生／护着摊位的克洛根保镖／随身带着采访设备的记者。【威胁类型】盖斯巡逻平台与突击无人机、混在难民里的萨伦手下、随时清场的封锁线，以及滴答作响的倒计时。真正的危险不是打不过，而是被一张证件、一道封锁门或一次排队拖到袭击开始。【奖励风格】万能工具、医疗凝胶、动能屏障模块、异能增幅插件与各类质量加速武器；能力偏向射击、异能控制与信息入侵，高级装备需要许可证或军用接口才能解锁。情报、通行权限与人情往往比枪更好用。【不对劲的来源】这座站上所有人都认得那名外交官：值勤表上有她的签字，酒保记得她常坐的位置，纪念墙的照片里也有她。只有她坚持这是第一次登上神堡，而她能准确说出玩家在现实里的名字。【时间线】建议固定在2183年神堡之战爆发之前：诺曼底号刚完成伊甸主星的任务，萨伦已被通缉，议会对是否接纳人类幽灵特工仍无定论。玩家的行动窗口只有袭击开始前的两小时。不要提前启用《质量效应2》的收集者、塞伯鲁斯以及后续作品的角色与设定。","powerStyle":"射击与异能向：万能工具、动能屏障","difficultyBias":2,"signatureItems":["万能工具","医疗凝胶","动能屏障模块","异能增幅插件","星联军牌"],"mainQuest":"主线任务：在袭击开始前把外交官从站内带到撤离舰上，并让撤离舰队在盖斯进入港口区之前完成起降。","mainQuestGoal":"在袭击开始前把外交官送上撤离舰，保证至少一艘撤离舰离港，并拿到她身份矛盾的确凿证据","sideQuests":[{"name":"还差一张通行证","desc":"在两小时内替一名没有档案的乘客补一份能过检的证件，别让哨卡记住你的脸","reward":"积分 150"},{"name":"港口的空座位","desc":"核对撤离舰的登舰名单，找出那个既在上面又不在上面的人","reward":"道具「星联军牌」"},{"name":"守卫者的旧账","desc":"帮那名图里安警员查一桩被压下去的案子，换取一条不该开放的通道","reward":"积分 200"},{"name":"她记得的酒保","desc":"去环区那家酒吧问清外交官常坐的位置，看是谁在替她付账","reward":"道具「万能工具破解模块」"}],"factions":[{"name":"星联","desc":"人类在神堡的官方代表，愿意接应自己人，但权限有限，凡事都要留档","attitude":"友善"},{"name":"神堡议会","desc":"借幽灵特工之手处理麻烦的执政机构，讲程序也讲交换，永远慢一步","attitude":"中立"},{"name":"萨伦的部队","desc":"由盖斯与雇佣兵组成的先遣队，正在为拿下神堡做最后的准备","attitude":"敌对"}],"npcs":[{"name":"大卫·安德森","identity":"星联军官，诺曼底号的前任指挥官，人类在神堡争取席位的关键人物","role":"引导者","personality":"直率、护短、把士兵的命放在政治之前","hook":"他交给玩家一份没有登记在册的撤离名单，并说上面任何一个名字被人看见，这次行动就作废","favorHint":"按他的时间表行动、把平民放在任务之前会加分；为了情报牺牲无关人员、或瞒着他改动名单会掉分","gender":"男","age":"四十余岁","race":"人类","faction":"星联","appearance":"深色短发里夹着灰白，下颌留着修剪整齐的短须。穿星联的深蓝色军装，肩上的徽记磨得发亮，袖口卷起半寸。身量结实，站着时重心很稳，习惯用拇指按住耳后的通讯器，说话前先看一眼时间。","traits":["直率","护短","务实"],"relations":[{"name":"萨伦·阿特里乌斯","label":"他亲眼看着对方从幽灵特工变成通缉犯"},{"name":"加勒斯·瓦卡里安","label":"在安全局里唯一肯跟他交换消息的人"},{"name":"唐纳尔·乌迪纳","label":"常与他争执的老搭档，两人的分歧从没真正解决"}],"voice":"句子短，先说结论再补理由；不满时会压低声音，把话重复一遍。"},{"name":"加勒斯·瓦卡里安","identity":"神堡安全局警员，图里安人，出身执法世家","role":"盟友","personality":"认死理、嘴上刻薄、对不公的事格外较真","hook":"他把一份被上级压下的巡查记录塞给玩家，只求玩家在离开前告诉他真相到底值不值得","favorHint":"尊重程序、肯把证据留一份给他的会加分；拿无辜者当诱饵、或嘲笑他守规矩会掉分","gender":"男","age":"27 岁","race":"图里安人","faction":"神堡安全局","appearance":"暗灰蓝色的皮肤，头顶两侧的骨板向外张开，面部有浅色的族纹。穿安全局的蓝灰制式护甲，右肩甲上留着一道没补好的划痕，腰侧挂着手枪。说话时习惯把头微微偏一下，像在瞄准；被驳倒时会先哼一声再改口。","traits":["较真","刻薄","正直"],"relations":[{"name":"萨伦·阿特里乌斯","label":"他从小被要求以对方为榜样，如今只剩鄙夷"},{"name":"大卫·安德森","label":"跨过部门界限仍愿意交换情报的人类军官"},{"name":"执行者帕拉西安","label":"他的上司，两人对什么叫伸张正义看法不同"}],"voice":"语调带刺，爱用反讽；认真起来会把语速放慢，逐条说明。"},{"name":"莉亚拉·特索尼","identity":"阿莎丽考古学者，专攻普洛仙遗迹的研究者","role":"关键人物","personality":"专注、不擅交际、遇到学术问题就忘了危险","hook":"她在玩家身上读出一段不该存在的时间痕迹，执意要跟到撤离舰上把这件事记完","favorHint":"认真听她讲完研究、替她保住资料会加分；把她的发现当成迷信、或当众取笑她母亲会掉分","gender":"女","age":"106 岁","race":"阿莎丽人","faction":"中立研究者","appearance":"浅蓝色的皮肤，头顶的软骨冠还没完全长开，脸上没有皱纹却有种沉静。穿深色防护服，外面套一件沾着尘土的考古用旅行外套，手腕上戴着万能工具，背包侧袋插着测绘笔。说话时盯着对方的肩后，像在回忆摘录。","traits":["专注","内向","执着"],"relations":[{"name":"贝尼西亚女族长","label":"她的母亲，也是她最不愿谈论的人"},{"name":"萨伦·阿特里乌斯","label":"她追查普洛仙遗迹时撞上的那个人"},{"name":"加勒斯·瓦卡里安","label":"在站内替她挡过一次盘查的人，她欠着一句谢"}],"voice":"语速平稳，术语很多；被打断会先道歉，然后接着说下去。"},{"name":"特沃丝议员","identity":"神堡议会中的阿莎丽代表，议长席上的常任议员","role":"中立","personality":"滴水不漏、耐心极长、习惯在最后一句才给出真正的条件","hook":"她在人群里主动叫出玩家的名字，并说这是自己第一次登上神堡——而站上所有人都坚持她已在这里住了几十年","favorHint":"替她维持议会体面、如实回报会加分；当众质疑她的身份、或把她交给安全局会掉分","gender":"女","age":"数百岁","race":"阿莎丽人","faction":"神堡议会","appearance":"蓝色皮肤，头顶的软骨冠向后顺成一道弧线，眼下有浅浅的纹路。穿白色与银色相间的议会礼服，长裙把脚踝盖住，颈间挂着一枚议会徽记。站立时双手交叠在身前，说话前会先环视一圈，目光在谁身上停下，谁就先开口。","traits":["沉稳","精明","难测"],"relations":[{"name":"萨伦·阿特里乌斯","label":"她亲手授予又亲手撤销其权限的幽灵特工"},{"name":"大卫·安德森","label":"她迟迟不肯点头的申请人选之一"},{"name":"莉亚拉·特索尼","label":"同族后辈，她留意过那份考古报告"}],"voice":"措辞严谨，从句套从句；从不表态，只说「议会会考虑」。"},{"name":"萨伦·阿特里乌斯","identity":"前幽灵特工，图里安人，因伊甸主星事件被议会通缉","role":"潜在敌人","personality":"自认高人一等、手段狠辣、把自己的判断当成唯一真理","hook":"他在港口区的暗处与玩家擦肩而过，留下一句「你还来得及走」，仿佛早知袭击的确切时刻","favorHint":"与他谈条件、承认人类弱小会加分；当面戳穿他受制于人的事实会掉分，但会让议会重新审视他","gender":"男","age":"四十余岁","race":"图里安人","faction":"萨伦的部队","appearance":"暗灰蓝色的皮肤，头骨两侧的骨板向后延伸成锐角，瞳孔是细长的裂瞳，一只手臂是银灰色的机械义肢。穿剪裁利落的深色长衣，领口立起，腰部收得很紧，脚下是无声的软底靴。说话时下巴略微抬起，从不提高音量。","traits":["傲慢","果断","冷酷"],"relations":[{"name":"贝尼西亚女族长","label":"被他拉进计划的阿莎丽长辈，也是他最忌惮的人"},{"name":"大卫·安德森","label":"他认为不足以成为对手的人类军官"},{"name":"特沃丝议员","label":"曾授予他权限、又收回权限的那个人"}],"voice":"语速不快，用陈述句下达结论；被打断就不再开口，只看着对方。"}]},{"id":"game_monster_hunter","category":"game","canon":"怪物猎人","name":"怪物猎人","icon":"🐉","tagline":"赶在古龙进营地前把人带回去","mood":"荒野、营地、古龙、狩猎、素材","guidance":"【原著设定】这是一个以狩猎为生的世界。猎人公会统一发布任务、结算报酬，村子与据点里有加工屋把怪物素材打造成武器与防具，也有登记员替猎人办理接单与交付。武器分十四种，从大剑、太刀到弓与轻弩，各有打法与站位；装备的核心是素材——用了何种怪物身上的东西，就得到何种性能。猎人在野外靠回复药、砥石、陷阱与投射器弹药维持战斗，随从猫背着补给跟在身后，导虫则替人指出可采集的痕迹。生态链顶端是古龙种：它们不为领地争斗，一出现就会改变当地的天气与地貌，公会通常只能引导、驱离或围堵，很少谈击败。【反复出现的意象】营地里被风吹得乱响的补给帐篷、立在岩上写着危险标记的告示牌、烤炉上滋滋作响的肉与围坐的猎人、集会所墙上钉满任务单的木板、古龙掠过时忽然变色的天。这些画面一出现，玩家就该知道自己站在荒野营地。【NPC 类型】嗓门比谁都大的任务登记员／手艺扎实而话极少的加工屋师傅／背着比自己还高的包裹的随从猫／专收稀有素材的老练商人／跟了三期远征的老猎人。【威胁类型】古龙本身、被惊动的大型怪物，以及天气与地形：砂尘、落石、沙下的伏击与随时会断的补给线。玩家真正怕的是救援还没到，装备先撑不住了。【奖励风格】武器与防具都要靠素材打造，回复药、陷阱、投射器弹药、导虫与采集工具一应俱全；能力偏向体力、耐力与地形适应，强化的前提是猎到对应的怪物。素材比积分更值钱。【不对劲的来源】古龙的行动路线像是早就写好的，公会画的预测图上每次都平白多出一条线。更怪的是，有些装备用到的素材在任何记录里都不存在，加工屋的师傅看过之后只是沉默着把图纸收进抽屉。【时间线】建议固定在《怪物猎人：世界》的早期：第五期团刚抵达新大陆，调查团正在追踪这一次古龙渡的方向，熔山龙的动向尚无定论。不要提前启用永霜冻土、冰呪龙一类的后期内容，也不要带入《崛起》的翔虫与牙猎犬设定。","powerStyle":"体力与道具向：大剑、陷阱、回复药","difficultyBias":3,"signatureItems":["回复药","砥石","捕获用麻醉玉","投射器","导虫"],"mainQuest":"主线任务：随调查团跟踪这一次古龙渡，查清古龙为何集体朝新大陆移动，并守住营地的补给线。","mainQuestGoal":"在古龙抵达营地前完成撤离与围堵准备，保住至少三处营地，并把古龙渡的完整预测图送回据点","sideQuests":[{"name":"沙下的脚印","desc":"在砂原里比对两组足迹的深浅，弄清古龙是先落过地才改了方向","reward":"积分 150"},{"name":"还没有的材料","desc":"把那件来路不明的装备送去加工屋鉴定，听师傅说出它的素材出自哪里","reward":"道具「未知素材的碎片」"},{"name":"补给帐篷的账","desc":"清点营地剩下的回复药与弹药，按人头补齐之后再出发","reward":"积分 180"},{"name":"三个新人","desc":"在古龙进入营地前把三名新猎人带回安全区，一个都不能少","reward":"道具「老练猎人的护石」"}],"factions":[{"name":"猎人公会","desc":"发布任务、结算报酬的中枢，规矩清楚，肯给外来者登记，但出了事要自己担","attitude":"友善"},{"name":"调查团","desc":"驻扎新大陆的研究与狩猎队伍，把古龙渡当成头等大事，人手永远不够","attitude":"中立"},{"name":"古龙种","desc":"不为领地争斗、只按自己的路线前进的存在，任何营地都拦不住，也谈不了条件","attitude":"敌对"}],"npcs":[{"name":"接待员","identity":"调查团的任务登记员，负责替猎人接单、整理生态记录并跟队出勤","role":"盟友","personality":"话多、好奇心压过怕死、总在离怪物太近的地方记笔记","hook":"她把一份署名是玩家的委托单交给玩家，说这份单子在她的册子里已经躺了很久","favorHint":"出勤时带上她、把新发现讲给她听会加分；嫌她碍事、丢下她独自行动会掉分","gender":"女","age":"二十余岁","race":"人类","faction":"调查团","appearance":"深棕色头发在两侧盘成两个圆髻，额前留着碎发。穿调查团的白蓝两色制服，脖子上围着一条绿色围巾，胸前挂着塞满单据的登记册。个子不高，走路带跳，见到没见过的怪物先掏笔，再往后退两步。","traits":["话多","好奇","热心"],"relations":[{"name":"总指挥官","label":"她的直属上司，常被她气得说不出话"},{"name":"调查班领队","label":"一起出勤的搭档，出事时总先把她拽回来"},{"name":"加工屋的师傅","label":"她欠着对方一堆还没核销的素材单"}],"voice":"语速快，爱用感叹句；讲起怪物生态能一口气说上很久。"},{"name":"总指挥官","identity":"调查团的最高负责人，统筹新大陆的远征与营地部署","role":"引导者","personality":"沉稳、话少、把所有伤亡都记在自己账上","hook":"他把一份写着「可以不执行」的命令交给玩家，并说这是他自己也拿不准的一次判断","favorHint":"按部署撤退、把人命放在战果之前会加分；擅自追击、拿新人当诱饵会掉分","gender":"男","age":"五十岁上下","race":"人类","faction":"调查团","appearance":"灰白短发与络腮胡，左脸有一道从颧骨划到下颌的旧疤。穿厚重的深色指挥官外套，肩部加着金属护片，腰带上挂着通讯器与折叠地图。总是双手抱胸，开口前先看一眼地图，说话时习惯用指节敲两下桌面。","traits":["沉稳","果断","自责"],"relations":[{"name":"提督","label":"老战友，也是他最头痛的那张牌"},{"name":"接待员","label":"手下的登记员，他嘴上严厉，名单上从没少过她的名字"},{"name":"调查班领队","label":"他一手带出来的年轻人，也是他派去最险地方的人"}],"voice":"声音低，句子短，下达命令时只说一次；私下会加一句「尽力就好」。"},{"name":"调查班领队","identity":"调查团前线小队的领队，负责侦察、追踪与现场判断","role":"盟友","personality":"爽快、敢冲、把队友的位置记得比自己的清楚","hook":"他愿意把全队最危险的那段路交给玩家，只因为玩家认得他没有见过的痕迹","favorHint":"和他并肩断后、按他的信号撤退会加分；逞强单独接战、隐瞒怪物动向会掉分","gender":"男","age":"二十余岁","race":"人类","faction":"调查团","appearance":"深蓝色的短夹克配白色内衬，脖子上系一条红色围巾，头上压着一顶磨旧的宽檐帽。腰间挂着两把短刃，背上捆着折叠的侦察用具。笑起来露出一口白牙，习惯把双手插进夹克口袋里，走路时脚步轻快。","traits":["爽快","胆大","讲义气"],"relations":[{"name":"接待员","label":"一起出勤的搭档，他负责把人拽回来"},{"name":"总指挥官","label":"提拔他的长官，也是他不想辜负的人"},{"name":"加工屋的师傅","label":"替他保养那两把短刃的人"}],"voice":"口气轻快，爱打招呼；判断危险时会忽然压低声音，只说关键词。"},{"name":"加工屋的师傅","identity":"据点加工屋的主匠，负责用素材打造与强化武器防具","role":"中立","personality":"沉默、眼力极准、只认手上的活不认人情","hook":"他看过玩家带来的那件装备后没有开价，只问玩家愿不愿意让他把图纸留一份","favorHint":"带回完整素材、不催单会加分；拿假素材充数、催他赶工、弄坏成品会掉分","gender":"男","age":"壮年","race":"人类","faction":"调查团","appearance":"上身只围一条厚皮围裙，露出结实的手臂与几处烫伤的旧痕。深色长发在脑后扎起，蓄着短须，指甲缝里永远嵌着炭灰。说话前先用锤子敲两下铁砧，看图纸时会把纸举到炉火边照。","traits":["沉默","较真","手稳"],"relations":[{"name":"接待员","label":"常来核销素材单的登记员，他嫌她吵"},{"name":"调查班领队","label":"常来磨刀的老主顾"},{"name":"提督","label":"替对方修过那把大剑，也劝过对方换一把"}],"voice":"话极少，多是单字回应；谈到材料时才肯讲长句。"},{"name":"提督","identity":"调查团的老资格猎人，第一线的战斗主力，专挑古龙下手","role":"对手","personality":"豪爽、好战、把撤退看成丢脸的事","hook":"他坚持要在营地前把古龙拦下来，而玩家必须在古龙到达之前把三名新人带走——两条路只能选一条","favorHint":"和他一起顶住正面、把话说清楚会加分；背着他撤走营地、或当众说他老了会掉分","gender":"男","age":"六十岁上下","race":"人类","faction":"调查团","appearance":"身形高大魁梧，光头配一圈短白须，胸膛敞开的外套下有一道从肩到腰的旧伤。腰后横背着一把比人还高的大剑，脚上踩着兽皮靴。笑起来声音很大，拍人肩膀时从不收力，站着时习惯把剑往地上一顿。","traits":["豪爽","好战","固执"],"relations":[{"name":"总指挥官","label":"多年的老搭档，两人常为撤不撤的事吵起来"},{"name":"调查班领队","label":"他看好的后辈，教过对方怎么在正面活下来"},{"name":"加工屋的师傅","label":"替他保养大剑的人，也是少数敢说他剑钝的人"}],"voice":"嗓门大，句子带笑；认真起来会把声音压低，只说一句「让开」。"}]},{"id":"game_death_stranding","category":"game","canon":"死亡搁浅","name":"死亡搁浅","icon":"🌧️","tagline":"雨停下之前，把箱子送到山那边","mood":"时间雨、开罗尔、货物、荒原、孤独","guidance":"【原著设定】世界在「死亡搁浅」之后崩坏：开罗尔物质随云层上升，落下的时间雨会让接触到的物体迅速老化；死者若不在限期内处理，遗体会引来搁浅物，一旦与活人接触便引发虚空噬灭，把周围夷平。人类退进零散的据点，靠少数派送员徒步连接，布里吉斯以开罗尔网络把这些据点重新串成一张网。派送员背负重物行走，靠梯子、攀爬柱、搭建器与骨架类外骨骼通过地形，最重要的是能感应搁浅物的奥卓德克扫描仪，以及装在胸前舱里、能看见亡者世界的布里吉婴。拥有杜姆斯体质的人能察觉搁浅物；山姆·波特·布里吉斯既是杜姆斯，也是能从冥滩返回的遣返者。【反复出现的意象】背包上堆成小塔的货物箱、地图上不断扩散的雨圈、搭在崖边留给陌生人用的梯子与攀爬柱、雨亭下等雨停的派送员、地平线上开罗尔晶体的金色反光。这些画面一出现，玩家就该知道自己在荒原上。【NPC 类型】缩在地下不肯开门的末日准备者／痴迷送货的米尔人／在据点门口登记货物的主管／给派送员留指示牌的陌生人／各自抱着执念的工程师与研究员。【威胁类型】时间雨本身、看不见也听不见的搁浅物、抢货的米尔人与恐怖分子，以及随时会让人失衡摔倒的地形。真正的压力来自货物完好度、体力与雨停的时限。【奖励风格】梯子、攀爬柱、搭建器、修复喷雾、骨架与波拉枪一类装备；能力偏向负重、平衡、感应与自救，多数道具可以自己制造，材料来自开罗尔晶体与据点捐献。别人留下的建筑与点赞同样是资源。【不对劲的来源】每次用奥卓德克扫描，都会有一两只手印朝着玩家的方向伸过来，而它们不该认得任何人。收件人一栏写着自己的名字时，系统并不报错。【时间线】建议固定在主线前半段：山姆刚从首都节点城出发，开罗尔网络正沿湖结点城方向逐段接通，芙拉吉尔与布里吉斯之间的裂痕尚未摊开。不要提前启用冥滩的真相、灭绝体与克利福德·昂格尔的完整设定。","powerStyle":"负重与生存向：货物箱、梯子、波拉枪","difficultyBias":2,"signatureItems":["货物箱","梯子","攀爬柱","修复喷雾","开罗尔晶体"],"mainQuest":"主线任务：沿开罗尔网络的铺设路线向西运送物资，把沿线的据点逐一接入网络。","mainQuestGoal":"在时间雨与搁浅物的夹击下把货物送到终点，保住与布里吉婴的连接，并让沿途至少三处据点恢复联络","sideQuests":[{"name":"山那边的收件人","desc":"在时间雨停下前把一箱私人物品送到山对面的据点，全程不许开箱","reward":"积分 150"},{"name":"雨亭里的留言","desc":"在雨亭下给下一个躲雨的人留一块指示牌，标出安全的绕行路线","reward":"道具「搭建器」"},{"name":"米尔人的货堆","desc":"从米尔人的营地里取回被抢走的货物，尽量不伤人","reward":"积分 200"},{"name":"不肯开门的人","desc":"把物资放在那位末日准备者的门口，等他自己开门收下","reward":"道具「修复喷雾」"}],"factions":[{"name":"布里吉斯","desc":"以重建美国为目标的配送与网络机构，按订单结算，习惯把人看成链条上的节点","attitude":"友善"},{"name":"米尔人","desc":"对送货上瘾的旧派送员群体，见到货物就抢，抢到手后整齐地堆起来","attitude":"敌对"},{"name":"芙拉吉尔快递","desc":"独立于布里吉斯的另一家配送公司，讲交情也讲价钱，走的路线更险","attitude":"中立"}],"npcs":[{"name":"山姆·波特·布里吉斯","identity":"布里吉斯派送员，杜姆斯体质者，能自冥滩返回的遣返者","role":"盟友","personality":"话少、抗拒肢体接触、答应了的事一定送到","hook":"他把一箱注明「收件人：你」的货物交给玩家，说自己只是替人捎话，不肯说寄件人是谁","favorHint":"替他分担重量、不碰他的私人物品会加分；追问他身上的旧事、擅自碰布里吉婴的舱会掉分","gender":"男","age":"三十余岁","race":"人类（杜姆斯体质）","faction":"布里吉斯","appearance":"深色乱发压着一层灰白，胡须浓密，眉骨高，脸上有风吹出的细纹。背着一人多高的货物架，架侧插着梯子与攀爬柱，胸前挂着布里吉婴的圆形舱，手腕上是橙色的铐环。走路微微前倾，放下货物后第一件事是看一眼铐环。","traits":["沉默","可靠","怕接触"],"relations":[{"name":"芙拉吉尔","label":"替他捎过话的同行，两人的交情靠一单一单攒出来"},{"name":"亡人","label":"把他当成研究对象、又真心替他担心的研究员"},{"name":"亚美莉","label":"他这一路真正要找的人"}],"voice":"能用一个字回答就不用一句话；被逼急了才说整句，语气很平。"},{"name":"芙拉吉尔","identity":"芙拉吉尔快递的负责人，独立派送员","role":"中立","personality":"硬气、嘴利、把人情算得极清却从不欠人","hook":"她开价替玩家走一趟最险的路线，条件是把那箱不许打开的东西留在她的货架上过一夜","favorHint":"付清价钱、替她保住货物完好度会加分；拿她的旧伤开玩笑、或把她的路线卖给布里吉斯会掉分","gender":"女","age":"三十岁上下","race":"人类","faction":"芙拉吉尔快递","appearance":"银白色短发贴着脸颊，发梢齐耳，皮肤偏白，颈侧有一道浅色旧痕。穿贴身的深蓝色配送服，肩部与大腿外侧装着货物挂钩，右手总戴一只深色手套。说话时把下巴抬起一点，站着时重心放在一侧，随时准备转身走。","traits":["硬气","精明","守信"],"relations":[{"name":"山姆·波特·布里吉斯","label":"她少数愿意赊账的同行"},{"name":"希格斯·莫纳罕","label":"结过怨的人，她一次都不愿再提"},{"name":"亡人","label":"从她这里买过几次情报的研究员"}],"voice":"语气干脆，句尾常带反问；谈价钱时一句废话都没有。"},{"name":"亡人","identity":"布里吉斯的研究员，负责解析遣返者与布里吉婴","role":"引导者","personality":"爱讲道理、对生死界限过分好奇、笨拙地关心别人","hook":"他偷偷请玩家替他从据点取回一份旧报告，那份报告的署名栏里印着玩家自己的名字","favorHint":"配合他做无伤检查、如实描述身体状况会加分；把他当怪人取笑、或把他的样本私自带走会掉分","gender":"男","age":"四十余岁","race":"人类","faction":"布里吉斯","appearance":"戴一副圆框眼镜，额头高，头发稀疏并向脑后梳。穿白色研究员外套，胸前口袋里插着好几支笔，袖口用夹子收着。手指修长，说话时会拿起手边的手术刀转一圈，再放回托盘，动作像在给自己定神。","traits":["好奇","啰嗦","心软"],"relations":[{"name":"山姆·波特·布里吉斯","label":"他最重要的研究对象，也是他不肯承认的朋友"},{"name":"心人","label":"隔着一台通讯器争论了多年的同行"},{"name":"硬汉","label":"给他经费也给他压力的上司"}],"voice":"爱用学术腔调起头，讲到一半忽然插一句私人的关心，然后立刻转回正题。"},{"name":"心人","identity":"研究冥滩的学者，每隔二十一分钟进入一次临床死亡状态","role":"关键人物","personality":"极度守时、执念深重、把每一分钟都排得满满当当","hook":"他在自己的二十分钟空档里替玩家查了一件事：那箱货物的收件记录，比寄出记录还早","favorHint":"准点赴约、尊重他的时间表会加分；拖延、或打断他寻找家人的事会掉分","gender":"男","age":"五十岁上下","race":"人类","faction":"布里吉斯","appearance":"深色皮肤，短卷发贴着额角，戴一副细边眼镜。穿宽松的浅色衬衫外罩研究背心，胸前挂着一台便携除颤器与一只倒计时手表，手腕上贴着电极片。说话语速极快，手指会在空中比出时间刻度，时间一到就立刻起身走向躺椅。","traits":["守时","执着","坦率"],"relations":[{"name":"亡人","label":"常在通讯里吵架、却彼此最懂的研究伙伴"},{"name":"山姆·波特·布里吉斯","label":"他反复拜托对方去找的那个人"},{"name":"亚美莉","label":"他研究中绕不开的名字"}],"voice":"语速飞快，习惯把时间说到秒；谈家人时突然停顿，再接上一句自嘲。"},{"name":"希格斯·莫纳罕","identity":"恐怖分子组织「狂人」的头目，能驱使搁浅物","role":"潜在敌人","personality":"表演欲极强、轻视生命、把破坏当成与人交谈的方式","hook":"他隔着雨幕向玩家点名问候，说那箱货物是他送的礼物，并要玩家务必在雨停前送到","favorHint":"配合他的表演、接他的话说会加分；把他的东西扔进坑洞、或当面说破他不过是个跑腿的会掉分","gender":"男","age":"三十余岁","race":"人类（杜姆斯体质）","faction":"狂人","appearance":"脸上罩着一副金色的骷髅面罩，只露出下颌与一截脖颈。穿黑色长外套，兜帽压得很低，颈间挂着几条链子，指间夹着一枚开罗尔晶体。说话时拖着长音，手势夸张，站在时间雨里却像在晒太阳。","traits":["狂妄","戏剧化","残忍"],"relations":[{"name":"芙拉吉尔","label":"他羞辱过的人，也是他最喜欢重提的旧账"},{"name":"山姆·波特·布里吉斯","label":"他认准的对手，两人的账要留到后头算"},{"name":"亚美莉","label":"他嘴上不屑、行动上却绕不开的名字"}],"voice":"像在台上念台词，句子拉得很长，喜欢在结尾加上一个反问问句。"}]},{"id":"novel_harry_potter","category":"novel","canon":"哈利·波特","name":"哈利·波特","icon":"🪄","tagline":"宵禁前，把没标签的瓶子放回去","mood":"城堡、魔杖、宵禁、画像、秘密","guidance":"【原著设定】英国有一所寄宿制的魔法学校霍格沃茨，年满十一岁的小巫师会在开学前收到猫头鹰送来的入学信，从国王十字车站的九又四分之三站台登车前往。学生被分入格兰芬多、斯莱特林、拉文克劳、赫奇帕奇四个学院，一年级的课程包括变形术、魔咒、魔药、草药、魔法史、天文与黑魔法防御术。施法需要魔杖与咒语配合，魔药则讲究材料与火候；城堡里的一切都在动——楼梯会换方向，画像会串门，盔甲会走路。守夜的管理员带着他的猫巡查走廊，违规的学生要被扣分、关禁闭，严重的还要留校察看。【反复出现的意象】大礼堂上空漂浮的蜡烛与那顶会挑人的旧帽子、胖夫人画像前报口令的洞口、会自己换方向的楼梯、图书馆禁书区上锁的铁栅、公共休息室里烧到很晚的壁炉。这些画面一出现，玩家就该知道自己站在霍格沃茨。【NPC 类型】怕被扣分的同院级长／总在抄笔记的用功学生／专挑新生找茬的高年级生／抱着课本赶课的幽灵／把校规背得比咒语还熟的看门人。【威胁类型】扣分与禁闭、被画像和幽灵看见、夜里巡查的管理员与他的猫、禁林里的生物，以及高年级学生的恶意。真正的风险是被人发现你出现在不该出现的地方。【奖励风格】魔杖、魔药材料、巧克力蛙与比比多味豆一类小道具；能力偏向咒语、变形、配药与隐蔽，效果取决于平时功课与练习，临时抱佛脚往往出事。学院分与人情也能换来钥匙和口令。【不对劲的来源】城堡对反复出现的谎话格外宽容：同一条走廊每天长度都不一样，值夜的记录也对不上号。走廊尽头那间本该空着的屋子会按人的需要自己变出来，而且它记得每一个进去过的人。【时间线】建议固定在第一学年开学第三周前后：新生刚分完院，正在熟悉课程与城堡，飞行课与魁地奇选拔刚有眉目，万圣节前夜与厄里斯魔镜等事尚未发生。不要提前启用密室、小天狼星·布莱克、摄魂怪、三强争霸赛与魂器一类后期角色和设定。","powerStyle":"咒语与魔药向：魔杖、咒文、坩埚","difficultyBias":-1,"signatureItems":["魔杖","坩埚","巧克力蛙","比比多味豆","魁地奇扫帚"],"mainQuest":"主线任务：读完第一学年，在期末之前弄清四楼走廊那扇门后藏着什么，并让真正的凶手在学期结束前现形。","mainQuestGoal":"在学年结束前保住同伴的学业与性命，查明四楼禁区的真相，并让凶手在众人面前被指认","sideQuests":[{"name":"没标签的瓶子","desc":"在宵禁前把一瓶没有标签的药水放回那间会自己出现的屋子，别被任何人撞见","reward":"积分 150"},{"name":"值夜人的记录","desc":"借来管理员的值夜簿，比对哪一天的巡查记录平白缺了一行","reward":"道具「写着口令的纸条」"},{"name":"禁书区的通行条","desc":"替一位老师跑腿换一张禁书区批条，不许看借书卡上的名字","reward":"积分 180"},{"name":"公共休息室的火","desc":"在熄灯前把炉火边的失物还给主人，别追问那件东西为什么没有标签","reward":"道具「巧克力蛙画片」"}],"factions":[{"name":"格兰芬多","desc":"看重勇气胜过规矩的学院，愿意收下任何一个敢出头的人，也最容易一起被扣分","attitude":"友善"},{"name":"斯莱特林","desc":"讲究血统、野心与交换的学院，对来路不明的人先称量再决定要不要用","attitude":"中立"},{"name":"管理员与校规","desc":"把作息、扣分与禁闭管得极严的巡查体系，对他们而言没有例外，只有记录","attitude":"敌对"}],"npcs":[{"name":"赫敏·格兰杰","identity":"霍格沃茨一年级新生，格兰芬多学院，麻瓜出身","role":"盟友","personality":"用功到固执、嘴上不饶人、出事时第一个站出来","hook":"她发现玩家施展的咒语不在任何一本课本里，于是要求玩家在下一次宵禁巡查前把来龙去脉讲清楚","favorHint":"认真预习功课、承认她判断正确会加分；抄她的笔记还嘲笑她死板、或替违规的人圆谎会掉分","gender":"女","age":"11 岁","race":"人类（麻瓜出身的女巫）","faction":"格兰芬多","appearance":"棕色蓬松的卷发从发带里炸出来，门牙略大，眼睛很亮。穿校服长袍配格兰芬多红金相间的领带，袍角永远压得平整，怀里抱着厚厚一摞课本，手腕上挂着一只装墨水的小布袋。走路很快，经常一边走一边翻书，被人反驳时会先把书往上抱一抱再开口。","traits":["用功","耿直","护同伴"],"relations":[{"name":"哈利·波特","label":"同院同级的伙伴，她既佩服又常常替他收拾局面"},{"name":"罗恩·韦斯莱","label":"常与她斗嘴的同伴，两人的别扭来得快去得也快"},{"name":"米勒娃·麦格","label":"她最敬重的教授，也是她一心想要的表现对象"}],"voice":"语速快，条理清楚，爱把课本上的说法搬出来；急了会提高音量纠正别人。"},{"name":"德拉科·马尔福","identity":"霍格沃茨一年级新生，斯莱特林学院，纯血家族子弟","role":"对手","personality":"傲慢、爱挑人短处、习惯用家里的名头压人","hook":"他认定玩家是混进来的冒牌货，扬言要在宵禁后带人堵住玩家的必经之路","favorHint":"给他台阶、在众人面前承认他的家世会加分；当众戳破他怕事、或替麻瓜出身的同学出头会掉分","gender":"男","age":"11 岁","race":"人类（纯血巫师）","faction":"斯莱特林","appearance":"浅金色头发向后梳得一丝不乱，脸色偏白，灰眼睛看人时微微眯起。校袍领口别着银绿相间的院徽，袖口露出熨得笔挺的衬衫，皮鞋擦得能照出人影。走路时下巴微抬，身后常跟着两个比他高半头的同院生。","traits":["傲慢","记仇","怯硬"],"relations":[{"name":"哈利·波特","label":"他入校第一天就想结交、又立刻翻脸的人"},{"name":"西弗勒斯·斯内普","label":"偏袒他的教授，也是他撒娇的对象"},{"name":"赫敏·格兰杰","label":"他嘴上最看不起、考试时又最在意的人"}],"voice":"拖着调子说话，爱用「我父亲」开头；被人逼住时声音会先高后低。"},{"name":"鲁伯·海格","identity":"霍格沃茨的猎场看守与钥匙管理员，兼任校内的向导","role":"引导者","personality":"热心、嘴不严、对危险生物缺乏分寸感","hook":"他把玩家领进禁林边缘的小屋喝茶，顺手从口袋里掏出一件不该出现在新生手里的东西","favorHint":"陪他喝茶、替他照看那些「小家伙」会加分；嫌弃他的宠物、或把他酒后的话传出去会掉分","gender":"男","age":"六十余岁","race":"半巨人","faction":"霍格沃茨教职员工","appearance":"身高足有常人的两倍，肩膀宽得能挡住整扇门。黑色长发乱得打着结，浓密的胡须遮住半张脸，眼睛像黑甲虫一样又黑又亮。穿一件过大的厚呢外套，口袋深得能塞进茶壶与狗食，手边常备一盏提灯和一把粉色的旧伞。","traits":["热心","嘴快","胆大"],"relations":[{"name":"阿不思·邓布利多","label":"在他最狼狈时收留他的人，他提起来就眼眶发红"},{"name":"哈利·波特","label":"他送进对角巷的第一个学生，此后一直牵着他的心"},{"name":"阿格斯·费尔奇","label":"多年的老对头，两人为禁林边界吵过无数次"}],"voice":"嗓门大，说到高兴处会拍桌子；提到秘密时会忽然压低声音，结果反而更响。"},{"name":"西弗勒斯·斯内普","identity":"霍格沃茨魔药课教授，斯莱特林学院院长","role":"潜在敌人","personality":"刻薄、记恨、把规矩当成武器","hook":"他单独留下玩家问话，问的不是违规的事，而是玩家熬出的那瓶药水凭什么没有配方","favorHint":"按时交上合格的药剂、不替人顶罪会加分；撒明显的谎、在课堂上抢答卖弄会掉分","gender":"男","age":"31 岁","race":"人类（巫师）","faction":"霍格沃茨教职员工","appearance":"及肩的黑发分成两半垂在脸侧，肤色苍白，鼻子高而勾。一年四季裹着厚重的黑色长袍，袍角在地上拖出声响，走路时上身几乎不动。说话前习惯慢慢转过身来，目光在对方眼睛上停住，嘴唇抿成一条直线。","traits":["刻薄","缜密","记仇"],"relations":[{"name":"阿不思·邓布利多","label":"他效忠却也始终提防的人"},{"name":"哈利·波特","label":"他格外苛刻的学生，两人的嫌隙从第一堂课开始"},{"name":"德拉科·马尔福","label":"他明面上偏袒的学生"}],"voice":"语速慢，声音低，常用疑问句下判断；从不提高嗓门，扣分也只是轻声说出来。"},{"name":"阿不思·邓布利多","identity":"霍格沃茨校长，公认当代最强的巫师之一","role":"关键人物","personality":"温和、话里有话、把真话留到最后才说","hook":"他在走廊里叫住玩家，说城堡最近多出来的那条路已经记在他的旧档案里，而写档案的人正是玩家","favorHint":"说实话、把同伴的安危放在自己前面会加分；试图套他的话、或拿秘密做交易会掉分","gender":"男","age":"一百一十岁上下","race":"人类（巫师）","faction":"霍格沃茨教职员工","appearance":"银白的长发与长须一直垂到腰带，须发里夹着几缕尚未全白的发丝。戴一副半月形眼镜，蓝眼睛在镜片后格外清亮。穿缀着星星与月亮图案的紫色长袍，头上一顶尖顶帽歪歪地扣着，鼻梁上有一处旧伤，手指修长。说话时常把双手的指尖对在一起。","traits":["温和","深沉","护学生"],"relations":[{"name":"米勒娃·麦格","label":"他最倚重的副校长，替他兜住学校里大半的事"},{"name":"西弗勒斯·斯内普","label":"他留在身边、也一直观察着的人"},{"name":"鲁伯·海格","label":"他护了多年的老下属"}],"voice":"语气平和，爱用反问与比喻；最要紧的话总放在最后一句，说完就走。"}]},{"id":"novel_lord_of_the_rings","category":"novel","canon":"魔戒","name":"魔戒","icon":"💍","tagline":"日落之前，把封好的盒子交出去","mood":"中土、黄昏、戒灵、誓言、诱惑","guidance":"【原著设定】中土是一片精灵、人类、矮人、霍比特人与半兽人共处的古老大陆。第三纪末，魔多之主索伦重新抬头，他曾暗中打造一枚统御其余戒指的至尊戒，精灵与人类组成最后同盟将他击败，戒指却落入河谷城的人类之手，辗转传到霍比特人佛罗多·巴金斯手中。这一纪的力量并不炫目：多数人能依靠的只有长剑、弓、铠甲与行军；真正的魔法握在少数存在手里——巫师、精灵领主与精灵三戒的持有者，他们更多在守护与遮蔽，不轻易动用力量。夏尔在南，布理在中，风云顶的废墟上立着古老的瞭望塔，精灵领地幽谷藏在河谷深处，通往东方的路必须经过布鲁嫩渡口。【反复出现的意象】黄昏里被染成暗红的水面、渡口前只容一人通过的窄石桥、路边被雨水泡软的苔藓与倒下的石像、旅人分食的干面包与一小片精灵面包、风里传来却看不见影子的马蹄声。这些画面一出现，玩家就该知道自己在中土的荒野上。【NPC 类型】披着斗篷不肯报名字的游侠／赶着马车往南走的货郎／在渡口附近定居的猎户／替领主传话的士兵／蹲在路边盘算价码的流浪者。他们谨慎、戒备，也讲义气。【威胁类型】追寻那件东西的骑手、荒野里的半兽人与狼骑、来路不明的雾气与恐惧，以及黑骑士手中那柄会留下寒意的短刃。玩家真正怕的是在日落前被追上，或者被身边的人劝动。【奖励风格】精灵斗篷、精灵面包、精灵绳、秘银护甲与阿塞拉斯草药一类道具；能力偏向隐匿、追踪、疗伤与意志抵抗，使用多有限制，靠的是准备与同伴。承诺与情报往往比武器更有分量。【不对劲的来源】那件被封好的东西一路上都在说话，听见的人却会把话转述成自己的主意：有人说该由你保管，有人说该把它送到别处，没人肯承认自己刚才想碰它。夜里，骑手的影子总比回头的人先动。【时间线】建议固定在第三纪3018年十月前后：佛罗多刚在风云顶受伤，正被游侠与精灵带往渡口，护戒同盟尚未在幽谷成立。不要提前启用同盟成军之后才登场的角色与设定。","powerStyle":"冷兵器与低魔：长剑、弓、草药","difficultyBias":2,"signatureItems":["精灵斗篷","精灵面包","阿塞拉斯草","秘银护甲","精灵绳"],"mainQuest":"主线任务：护送佛罗多与那件东西穿过荒野抵达幽谷，在幽谷会议之前守住它不被夺走。","mainQuestGoal":"在渡口前把人安全交给幽谷的接应者，保住那件东西不离队，并让同行者至少两人活着抵达","sideQuests":[{"name":"不许打开的盒子","desc":"在日落前把一只封好的小盒交给营地外的向导，中途不许打开","reward":"积分 150"},{"name":"风云顶的余温","desc":"在废墟上找回被丢下的短刃，把它埋到远离道路的地方","reward":"道具「阿塞拉斯草」"},{"name":"渡口前的脚印","desc":"数清河岸上的马蹄印，判断追兵是几人几骑","reward":"积分 180"},{"name":"分食一块面包","desc":"把干粮分给同行的人，并记住谁在此刻仍然坚持自己拿着行李","reward":"道具「精灵面包」"}],"factions":[{"name":"幽谷的精灵","desc":"河谷深处的精灵领地，掌有疗伤与守护之力，愿意接应旅人却从不轻易出手","attitude":"友善"},{"name":"北方的游侠","desc":"在荒野里巡逻、护着边境的流浪者，不喜被问来历，也不肯把武器交出去","attitude":"中立"},{"name":"戒灵","desc":"受索伦驱使的九名骑手，追着那件东西向北，白天不露面，夜里才逼近","attitude":"敌对"}],"npcs":[{"name":"阿拉贡","identity":"北方游侠，努门诺尔后裔，刚铎王族的末代血脉","role":"盟友","personality":"沉默、把誓言看得比性命重、对自己的身份讳莫如深","hook":"他先问玩家愿不愿意为一件不属于自己的东西走一整夜的路，然后才肯说出自己的名字","favorHint":"守夜、把伤者放在行程之前会加分；追问他的血统、或私自离队去追名声会掉分","gender":"男","age":"87 岁","race":"人类（努门诺尔后裔）","faction":"北方的游侠","appearance":"深色乱发里夹着灰白，面部被风霜刻出细纹，眼睛是浅灰绿色。穿一件褪成暗绿的旅行斗篷，斗篷下是旧的皮甲与磨破的靴子，背一张长弓，腰间系着短刀与皮水囊。说话时习惯把一枚草叶捏碎在指间闻，坐下总选背靠石头、面朝来路的位置。","traits":["沉默","坚忍","守诺"],"relations":[{"name":"甘道夫","label":"与他一同走了多年的老友，也是最了解他志向的人"},{"name":"佛罗多·巴金斯","label":"他一路护着的人，也是他此刻唯一的任务"},{"name":"波罗莫","label":"刚铎来的同行者，两人对同一件东西的看法完全不同"}],"voice":"声音低，句子短，很少解释；被追问时会用一句反问把话头转开。"},{"name":"格罗芬德尔","identity":"幽谷的精灵领主之一，精灵中的强者，奉命沿路寻找旅人","role":"引导者","personality":"从容、目光很远、说话像在陈述早已知道的事","hook":"他看得见玩家身上不合中土时序的痕迹，只说了一句「你来得比该来的晚」，随后替玩家指了路","favorHint":"听从不走岔路、保护伤者会加分；逞强上马争先、或对精灵的劝告出言不逊会掉分","gender":"男","age":"数千岁","race":"精灵","faction":"幽谷的精灵","appearance":"身量高挑，金色长发在风里散开，面孔年轻而眼神极老。穿白色与淡金相间的精灵长袍，肩上用银色扣针别着斗篷，腰间短剑的护手上镶着一块绿宝石。骑一匹白马，马具上没有多余装饰，他上马与下马都听不见声响。","traits":["从容","洞察","寡言"],"relations":[{"name":"埃尔隆德","label":"幽谷之主，他听命并信赖的人"},{"name":"佛罗多·巴金斯","label":"他此行要接回的人"},{"name":"安格玛巫王","label":"渡口前的对手，他清楚对方的斤两"}],"voice":"语速从容，用词庄重；从不提高声音，也不重复已经说过的话。"},{"name":"佛罗多·巴金斯","identity":"来自夏尔的霍比特人，那件东西此刻的持有者","role":"关键人物","personality":"温和、怕事却不肯退、把责任往自己身上揽","hook":"他夜里小声问玩家：如果手里有一件所有人都想要的东西，你会交给谁","favorHint":"不追问他怀里那件东西、替他背着行李会加分；伸手去碰、或劝他把东西交给别人保管会掉分","gender":"男","age":"50 岁","race":"霍比特人","faction":"夏尔","appearance":"身高只到常人胸口，深棕色卷发，面色比同龄的霍比特人苍白。穿深绿色旅行外套与半身斗篷，脚上是一双长着硬毛的宽脚，一侧肩膀包着浸过药草的布条。怀里贴着一样用细链挂着的东西，走路时偶尔会伸手按住胸口，习惯性地数同行者的脚步。","traits":["温和","坚韧","自责"],"relations":[{"name":"山姆怀斯·甘姆吉","label":"寸步不离的同伴，他几次想把人赶回去都没成功"},{"name":"阿拉贡","label":"半路遇到却越来越信的向导"},{"name":"甘道夫","label":"把他推上这条路的人，也是他此刻最想见到的长者"}],"voice":"声音轻，句子慢，常先道歉再说正事；被逼问时会沉默很久。"},{"name":"波罗莫","identity":"刚铎宰相之子，白城的将领，为求对策远赴幽谷","role":"对手","personality":"勇武、直率、把本国的存亡摆在万物之前","hook":"他反复劝玩家：既然东西在你手上，就该由你保管，等到了能用的地方再谈交出去的事","favorHint":"认可他的战功、与他并肩断后会加分；当众说他只想夺权、或替精灵的立场贬低刚铎会掉分","gender":"男","age":"41 岁","race":"人类（刚铎人）","faction":"刚铎","appearance":"身形高大结实，深色长发披在肩上，下颌蓄着短须。穿一件沾着长途风尘的深色外袍，肩背一套剑盾，身侧挂着一只镶银边的白色号角。说话声音洪亮，站姿挺直，习惯把手按在剑柄上，笑起来很爽朗。","traits":["勇武","直率","焦躁"],"relations":[{"name":"阿拉贡","label":"他起初轻视、后来不得不看重的人"},{"name":"佛罗多·巴金斯","label":"他嘴上护着、心里惦记着的那个霍比特人"},{"name":"甘道夫","label":"他此行要请教的长者，也是他最不服气的人"}],"voice":"嗓门大，爱用「刚铎」开头；被驳斥时会先沉默，再把手从剑柄上拿开。"},{"name":"安格玛巫王","identity":"九戒灵之首，受索伦驱使的骑手首领","role":"潜在敌人","personality":"无声、不知疲倦、只按命令推进","hook":"他不追那个霍比特人，先折向玩家，像是认得玩家身上那件不属于这个世界的物件","favorHint":"保持距离、掩住伤者的血迹、不与他对视会加分；在他面前拔出武器、或试图与他谈条件会立刻掉分","gender":"男","age":"数千岁","race":"戒灵（昔日的人类之王）","faction":"戒灵","appearance":"身形像一件空着的长袍，兜帽压得极低，看不见脸，只在下颌处透出一片更深的黑。黑色斗篷在风里不飘，像被水浸透一样垂着，手戴铁灰色的护手，握一柄细长的短刃。坐骑是一匹没有一丝杂色的黑马，蹄声很轻。","traits":["无声","执着","恐怖"],"relations":[{"name":"索伦","label":"他效忠并受其驱使的主人"},{"name":"格罗芬德尔","label":"在渡口拦下他的人，他记得那匹白马"},{"name":"佛罗多·巴金斯","label":"他此行奉命带回的目标"}],"voice":"几乎不开口，只有压低到听不清的嘶声；质问时用剑尖代替语言。"}]},{"id":"novel_asongoficeandfire","category":"novel","canon":"冰与火之歌","name":"冰与火之歌","icon":"🐺","tagline":"国王到来的那几天，比冬天更冷","mood":"北境、家徽、誓约、猜忌、长城","guidance":"【原著设定】故事发生在一个季节漫长、冬天可以持续数年的世界。维斯特洛大陆由七大王国的铁王座统一，首都是君临，北境的首府是临冬城，城主史塔克家族世代称北境守护。贵族靠家徽、族语与联姻结盟，骑士以剑与誓言立身，学士用颈间的金属链条表明身份，渡鸦是唯一可靠的远距离传讯手段。长城横贯大陆最北端，高逾七百尺，由守夜人世代驻守，用来阻挡长城以北的自由民与更北面的东西。海对面的厄斯索斯大陆上有多斯拉克人与自由贸易城邦。这个时代几乎没有魔法，真正起作用的是钢铁、粮食、情报与继承顺序。【反复出现的意象】临冬城神木林里那棵刻着人脸的白树、地下墓窖中一排排石像膝上横放的长剑、铁匠铺上方升起的白汽与温泉沟渠、国王一行踏过吊桥时扬起的雪尘。这些画面一出现，玩家就该知道自己站在北境。【NPC 类型】把规矩看得比命重的老骑士／把家族荣耀挂在嘴边的继承人／出身低微却看事最清的侍从／带着南方口音又满身算计的廷臣／长城上只认誓言的守夜人游骑兵。【威胁类型】王室的猜忌、下在酒里的东西与背后的一刀、被雇来的刺客与猎犬般的武士，以及北境的冬天本身——粮仓与柴堆的数量比剑更决定生死。玩家最该怕的是站错队，其次才是打不过。【奖励风格】家族纹章的斗篷与胸针、瓦雷利亚钢的小刀、学士的链饰与药箱、渡鸦笼与密封信件；能力偏向剑术、骑术、情报与人情，几乎没有法术。【不对劲的来源】送到长城哨所的那封信被值守的守夜人拆开后，他说信里的事三年前就发生过，连送信的人也是玩家——而那一次玩家并没有来过这个世界。这里的人对征兆与旧誓又太当真，偶尔真的会应验。【时间线】建议固定在劳勃国王一行抵达临冬城的那几天：国王刚提出北上，布兰还没从那座塔上摔下去，琼恩正打算随叔父去长城，提利昂以客人的身份随行。不要提前启用后期才登场的角色与设定。","powerStyle":"低魔写实向：长剑、锁甲、渡鸦传书","difficultyBias":3,"signatureItems":["缝着冰原狼纹章的斗篷","守夜人的黑斗篷","瓦雷利亚钢匕首","学士的链饰","盖着狼头封蜡的信"],"mainQuest":"主线任务：在国王一行离开临冬城之前，把一封盖着狼头封蜡的信送到长城下的那处哨所，交给当夜值守的守夜人。","mainQuestGoal":"把信亲手交到值守的守夜人手上，弄清他为什么说这件事三年前就发生过、信也是玩家送的，然后在天亮前回到临冬城","sideQuests":[{"name":"马厩里的第三匹马","desc":"国王一行的马夫少了一匹马，查清它是被谁牵走、又送去哪里","reward":"积分 150"},{"name":"旧塔上的脚印","desc":"顺着雪地里一串不自然的脚印，爬上空置的那座旧塔顶","reward":"道具「守夜人的黑斗篷」"},{"name":"给学士的药材","desc":"把一份从南方带来的药材送进学士塔，别问用途","reward":"积分 200"},{"name":"面包与盐","desc":"在宴席上替一名被刁难的仆人说话，并把他调去厨房","reward":"道具「刻着狼头的银别针」"}],"factions":[{"name":"史塔克家族","desc":"北境的统治者，待客有礼却从不轻易信任外来者","attitude":"友善"},{"name":"兰尼斯特家族","desc":"随国王北上的西境豪门，谈笑之间都在算账","attitude":"敌对"},{"name":"守夜人","desc":"驻守长城的兄弟会，只认誓言，不问出身","attitude":"中立"}],"npcs":[{"name":"艾德·史塔克","identity":"临冬城公爵、北境守护","role":"引导者","personality":"寡言、守信，把规矩看得比名声重","hook":"他盘问过玩家的来路之后，仍把一封盖着狼头封蜡的信交到玩家手上，态度像是早就知道玩家会来","favorHint":"如实说明来路、护住他的人会加分；打听他的家事或在国王面前抢话会掉分","gender":"男","age":"35 岁","race":"人类（先民后裔）","faction":"史塔克家族","appearance":"长脸，褐色头发在两鬓泛灰，短须修得整齐，灰眼睛看人时很少眨动。深灰羊毛外衣，肩头别一枚冰原狼银别针，腰间挂一把比常人还高的双手剑。他站着时重心很稳，说话之前会先停半拍，习惯用拇指蹭过剑柄的皮绳。","traits":["寡言","守信","克制"],"relations":[{"name":"劳勃·拜拉席恩","label":"当年一同起兵的旧友，如今是坐在铁王座上的国王"},{"name":"凯特琳·史塔克","label":"妻子，河间地徒利家的长女"},{"name":"琼恩·雪诺","label":"养在临冬城的私生子，他对这个孩子的母亲始终一个字不提"}],"voice":"句子短，语速慢，很少提高音量；下决定时只说结果，不解释理由。"},{"name":"琼恩·雪诺","identity":"艾德·史塔克的私生子，临冬城的养子","role":"盟友","personality":"敏感、倔强，把承诺看得比前程重要","hook":"他是府里唯一既不把玩家当外人、也不把玩家当贵客的人，愿意在天亮前带玩家走出临冬城的后门","favorHint":"尊重他、认真听他讲长城的事会加分；拿他的出身开玩笑或在宴席上把他晾在一边会掉分","gender":"男","age":"14 岁","race":"人类","faction":"史塔克家族","appearance":"瘦长的少年，黑色直发垂到耳下，灰眼睛，脸型偏长。深色粗布上衣配旧皮靴，衣角补过一针。脚边总跟着一头白化病的冰原狼，红眼睛；他习惯把手放在狼耳后，站着时靠着墙，不太肯站到人群中间。","traits":["敏感","倔强","重诺"],"relations":[{"name":"艾德·史塔克","label":"他称为父亲的人，也是唯一从不解释他来历的人"},{"name":"罗柏·史塔克","label":"同父异母的兄长，也是他最好的伙伴"},{"name":"班扬·史塔克","label":"叔父，守夜人的游骑兵，他北上的理由之一"}],"voice":"话少，句子短，被问到出身会沉默；说起长城与守夜人时语气会快起来。"},{"name":"提利昂·兰尼斯特","identity":"凯岩城兰尼斯特家的次子，国王一行的随行成员","role":"中立","personality":"刻薄、爱读书，看人比谁都准","hook":"他在马厩边主动跟玩家搭话，用一句玩笑试探玩家是否知道这趟北行的真正目的","favorHint":"接得住他的玩笑、跟他讲实话会加分；因为他的身材轻视他或拿他姐姐说事会掉分","gender":"男","age":"二十余岁","race":"人类","faction":"兰尼斯特家族","appearance":"身高不到常人胸口，头显得大，短腿，走路外八。浅金色头发细软，一只眼睛绿、一只眼睛近黑。深红与金色调的外衣剪裁讲究，袖口沾着酒渍，手里常端一只酒杯，笑起来先歪嘴。","traits":["刻薄","机敏","自嘲"],"relations":[{"name":"詹姆·兰尼斯特","label":"兄长，全家唯一待他像人的人"},{"name":"瑟曦·兰尼斯特","label":"姐姐，他从小就知道对方厌恶自己"},{"name":"琼恩·雪诺","label":"在临冬城结识的私生子，他愿意多说的那个人"}],"voice":"语速不快，爱用玩笑把话说到底；被羞辱时不生气，反而顺着对方的话往下说。"},{"name":"桑铎·克里冈","identity":"王子乔佛里的贴身护卫，人称猎狗","role":"潜在敌人","personality":"暴烈、厌恨虚伪，只听自己认的人","hook":"他在雪地里盯着玩家看了很久，然后说出一句关于玩家「不属于这里」的判断，并记住了玩家走路的样子","favorHint":"不当面戳他的脸、直话直说会加分；提骑士的荣誉或拿火开玩笑会掉分","gender":"男","age":"二十余岁","race":"人类","faction":"兰尼斯特家族","appearance":"身量高大，肩背厚实，右半张脸被烧得皮肉发亮，那一侧没有眉毛也没有耳朵。黑色短发贴在左侧，穿一件暗灰色旧锁甲，外罩沾了雪的斗篷，腰间悬长剑与匕首。他走路时微微低头，看人只抬眼睛。","traits":["暴烈","厌世","直白"],"relations":[{"name":"乔佛里·拜拉席恩","label":"他奉命保护的王太子，他并不喜欢这个人"},{"name":"格雷果·克里冈","label":"兄长，也是他脸上那道伤的来源"},{"name":"詹姆·兰尼斯特","label":"同为王子的武士，彼此都不亲近"}],"voice":"嗓音粗哑，句子短而冲，爱用狗和火的比方；说到火的时候会停顿。"},{"name":"凯特琳·史塔克","identity":"临冬城公爵夫人，河间地徒利家的长女","role":"中立","personality":"谨慎、护家，对外人从不松口","hook":"她注意到玩家在雪地上留下的脚印深浅不对，却没有当场点破，只是把话题引开，然后让人盯着玩家的房门","favorHint":"守礼、对她的孩子真心相待会加分；打听家族旧事或跟琼恩走得太近会掉分","gender":"女","age":"三十余岁","race":"人类（河间地徒利家血脉）","faction":"史塔克家族","appearance":"高个，红褐色长发盘在脑后，蓝眼睛，皮肤很白。深蓝色羊毛长裙，肩上披同色斗篷，腰间挂一串钥匙。她站着时背很直，双手交叠在身前，进门习惯先扫一眼屋里所有的出入口。","traits":["谨慎","刚强","护家"],"relations":[{"name":"艾德·史塔克","label":"丈夫，她愿意为他押上整个家族"},{"name":"布兰·史塔克","label":"儿子，这几天正缠着要去看行刑"},{"name":"莱莎·艾林","label":"妹妹，鹰巢城的女主人，与她常年通信"}],"voice":"礼貌但有距离，用敬称称呼外人；提出要求时不带商量的余地。"}]},{"id":"novel_threebody","category":"novel","canon":"三体","name":"三体","icon":"🌌","tagline":"按下按钮的人，握着两个文明","mood":"威慑、监视、密钥、黑暗森林、交接","guidance":"【原著设定】这是一个人类已经与三体世界对峙两个多世纪的太阳系。宇宙社会学的底色是黑暗森林法则：任何暴露自身坐标的文明都会被更高级的存在清除。人类的生存建立在黑暗森林威慑之上——把三体世界的坐标写进随时可以广播的方案里。早期靠太阳的电波放大，后来智子能够干扰这条路径，人类便在地球与舰队上建起了引力波发射台，天线一旦启动，广播无法拦截，两个文明同时暴露。执剑人独自掌握那个开关，他存在本身就是威慑；三体世界则用智子监视地球的一切。地球国际负责行政，太阳系舰队国际掌握太空力量，人类早已过了最恐慌的年代，过度的安全感正在变成新的漏洞。【反复出现的意象】地下指挥厅里缓慢转动的全息星图、发射台下那面巨大的抛物面天线、走廊尽头永不关闭的智子监视画面、排列成行的白色冬眠舱、太空军制服袖口上那枚低调的徽记。这些画面出现，玩家就知道自己站在威慑体系的中心。【NPC 类型】按规程办事的值班技师／对威慑早已麻木的高级官员／把三体世界当作和平伙伴的年轻一代／在监视下仍偷偷写信的老兵／负责控制权移交的书记官。【威胁类型】水滴一类以完美镜面示人的探测器、无孔不入的智子监视、体系内部的政治接管，以及人人都以为不会来的那一刻——威慑失效之后的一切。个人的体力与枪械在这里几乎不起作用。【奖励风格】密钥盘与权限、观测数据与监视盲区、冬眠舱席位、太空军装备与舰载通行权；能力偏向信息、权限与时机判断，基本不给超常力量。【不对劲的来源】发射台的值班员每天换人，可每个来接盘的人都自称是同一个人，签名与口吻也一模一样；而人类把整个文明的命运交给一个人的心理承受力，却每天在讨论那个人是否合格。【时间线】建议固定在威慑纪元末期、执剑人刚刚交接的那段时间：罗辑已经卸任，程心接任不久，三体世界的态度正在微妙地变化。不要提前启用后期才登场的角色与设定，广播纪元、掩体纪元的内容以及云天明、关一帆一类角色都不应提前出现。","powerStyle":"硬科幻向：威慑、智子、水滴与权限","difficultyBias":4,"signatureItems":["引力波发射密钥盘","智子监视终端","冬眠舱使用凭证","太空军制服徽记","值班交接记录本"],"mainQuest":"主线任务：在引力波发射台被接管之前，把一枚密钥盘交到当夜值班员的手上。","mainQuestGoal":"在接管发生前完成交接，并查清每一位自称同一个人的值班员到底是不是同一个人，最后决定这枚密钥盘该留在谁手里","sideQuests":[{"name":"智子看不见的角落","desc":"找到一处监视盲区，在那里把该说的三句话说完","reward":"积分 200"},{"name":"值班表上的墨迹","desc":"比对三天的值班签名，找出被改写的那一栏","reward":"道具「备份密钥盘」"},{"name":"冬眠者的旧物","desc":"替一名刚醒来的旧时代人取回他被封存的私人物品","reward":"积分 150"},{"name":"天线的备用电源","desc":"在接管前确认发射台的备用能源还能撑多久，并把结论暂时压下来不报","reward":"道具「太空军袖标」"}],"factions":[{"name":"地球国际（威慑控制中心）","desc":"掌管执剑人体系与发射台的行政机构，程序比人重要","attitude":"友善"},{"name":"太阳系舰队国际","desc":"掌握太空力量的一方，对威慑有自己的算盘","attitude":"中立"},{"name":"三体世界","desc":"以智子为眼、以舰队为手，正在等待人类自己犯错","attitude":"敌对"}],"npcs":[{"name":"罗辑","identity":"前任执剑人，黑暗森林威慑的建立者，曾经的面对壁者","role":"引导者","personality":"冷淡、透彻，把生死当作已经算过的数","hook":"他把一件只有执剑人才会知道的小事说给玩家听，等于当面承认玩家来自威慑体系之外","favorHint":"把事情说完整、不替他的继任者做决定会加分；把他当英雄来恭维或用人类的命运来逼他表态会掉分","gender":"男","age":"外表四十余岁","race":"人类（曾长期冬眠）","faction":"地球国际（威慑控制中心）","appearance":"清瘦，肩背挺直，鬓发已经花白，脸色平静得近乎冷硬。深灰色制服，胸前没有任何徽记，左手腕上一具不起眼的金属环，腰间挂着一只手掌大小的黑色匣子，从不离身。说话时他看星图，不看人。","traits":["冷静","疏离","决断"],"relations":[{"name":"程心","label":"接替他执剑的人，他不评价，只是看着"},{"name":"史强","label":"多年的保护者，也是他为数不多的朋友"},{"name":"智子","label":"对面那个从不疲惫的对手"}],"voice":"平稳，不用形容词，习惯先给结论再补理由；被追问时会沉默几秒。"},{"name":"程心","identity":"新任执剑人，原航天工程技术人员","role":"关键人物","personality":"温和、犹豫，把责任背得太快","hook":"她私下请玩家替她核对一次交接记录，因为她是这里唯一不敢确认自己有没有资格的人","favorHint":"认真回答她的问题、不当面评判她的犹豫会加分；用威慑失败来吓她或替她做那个决定会掉分","gender":"女","age":"外表三十岁上下","race":"人类（曾长期冬眠）","faction":"地球国际（威慑控制中心）","appearance":"齐肩黑发，眉眼温和，个子中等，站姿有点拘谨。浅灰色制服衬衫，袖口扣得整齐，胸前别着一枚新发的通行徽章。她双手常交握在身前，掌心容易出汗，开口前会先吸一口气。","traits":["温和","自省","迟疑"],"relations":[{"name":"罗辑","label":"她接下的那份责任，就是这个人的五十四年"},{"name":"艾AA","label":"身边最直率的朋友，也是唯一敢骂她的人"},{"name":"智子","label":"那个用礼貌的口气向她提出要求的代表"}],"voice":"语速偏慢，喜欢用「我会尽力」这类留有余地的话；被逼到角落时会先道歉。"},{"name":"智子","identity":"三体世界派驻地球的监视者与代表","role":"潜在敌人","personality":"优雅、耐心，把人类当作已经算定的变量","hook":"她在走廊尽头向玩家行礼，并准确说出玩家进入这个世界的时间，比主神给出的还早一天","favorHint":"保持礼貌、照她定下的规矩行事会加分；试图欺骗她、触碰监控禁区或和她说笑会掉分","gender":"女","age":"外表二十余岁（非人类实体）","race":"三体世界制造的拟人形终端","faction":"三体世界","appearance":"和服样式的浅色长衣，腰封束得很紧，脚下是白袜与木屐。黑发盘成传统的髻，插一支素色发簪。腰间斜插一柄长刀，刀柄缠着深色绳。她站得极直，行礼时上身前倾的角度每次都一样，笑容不动眼睛。","traits":["优雅","耐心","危险"],"relations":[{"name":"程心","label":"她刚刚等到的这位执剑人，比她预想的更好对付"},{"name":"罗辑","label":"她监视了半个世纪、也始终没能看透的那一个人"},{"name":"史强","label":"她列在监视名单上的旧警察，一个她不太喜欢的变量"}],"voice":"用语礼貌而有距离，句子工整，从不用俗语；说到关键处会换成陈述句。"},{"name":"艾AA","identity":"程心的助手与朋友","role":"盟友","personality":"直率、好奇，讨厌绕弯子","hook":"她把玩家当成刚冬眠醒来的人，主动教玩家用这个时代的设备，还把自己的通行权限借了出来","favorHint":"接受她的好意、跟她讲实话会加分；摆老资格看不起这个时代或瞒着她单独行动会掉分","gender":"女","age":"二十余岁","race":"人类（威慑纪元出生）","faction":"地球国际（威慑控制中心）","appearance":"短发利落，发梢挑染成浅色，个子不高但步子很快。彩色工装连体服，袖口卷到小臂，两只手腕上戴着好几只功能不同的环形终端。说话时爱晃手里的平板，笑起来眼睛弯成一条线。","traits":["直率","好奇","热心"],"relations":[{"name":"程心","label":"她愿意跟着的人，也是她最想敲醒的人"},{"name":"史强","label":"总跟她抬杠的长辈，吵完还是会把事办妥"},{"name":"罗辑","label":"她只在远处见过几面的传说人物"}],"voice":"语速快，爱用新词和缩写；遇到不明白的事就直接说不明白。"},{"name":"史强","identity":"原刑警，罗辑多年的保护者","role":"盟友","personality":"粗中有细、嘴上不饶人、认死理","hook":"他从兜里掏出一张折得很小的旧纸条，说是很多年前有人托他转交，收信人写的正是玩家的名字","favorHint":"跟他直来直去、把危险说清楚会加分；跟他打官腔或隐瞒关键信息会掉分","gender":"男","age":"六十余岁","race":"人类（曾长期冬眠，旧疾已愈）","faction":"地球国际（威慑控制中心）","appearance":"肩宽体壮，脖子短，脸膛发红，短短的花白头发立着。深色夹克敞着穿，里面是件旧衬衫，裤子的膝盖磨得发白。手上有关节粗大的旧伤，说话时习惯用整只手掌拍桌子，笑起来先呲牙。","traits":["粗豪","精明","仗义"],"relations":[{"name":"罗辑","label":"他守了半辈子的人，也是他最服气的一个"},{"name":"程心","label":"他刚接手要照看的新执剑人，他不太放心"},{"name":"艾AA","label":"爱跟他顶嘴的年轻人，他嘴上嫌弃心里喜欢"}],"voice":"嗓门大，爱用市井里的比方，称呼人一律用「你」；认真起来句子会突然变短。"}]},{"id":"novel_dune","category":"novel","canon":"沙丘","name":"沙丘","icon":"🪱","tagline":"香料流过沙漠，命运流过人","mood":"沙漠、香料、水、沙虫、预言","guidance":"【原著设定】厄拉科斯是一颗只有沙与岩的荒漠行星，地表没有水，唯一的出产是香料。香料能延长寿命，也能提升运算与预知的能力，是宇航公会导航者折叠空间的前提，因此全宇宙都盯着这颗星球。行星上的原住民自称弗雷曼人，住在岩壁深处的穴地里，穿蒸馏服回收身体的水分，用沙虫钩驾驭巨型沙虫，拿沙虫牙齿磨成的晶刀立誓。帝国的政治由帕迪沙皇帝、各大族、宇航公会与贝尼·杰瑟里特姐妹会共同维持。厄崔迪家族刚从哈克南家族手里接下这颗星球作为封地，全家刚刚搬来。沙漠里最大的自然威胁是科里奥利风暴，沙暴季里它能把人磨成骨头。【反复出现的意象】地平线上隆起的沙丘与沙脊、采集车在沙面留下的宽履带痕、蒸馏服领口的管子与面罩、弗雷曼人喝水前先递给别人的那只小杯、岩壁穴地里排成行的储水罐。这些画面一出现，玩家就该知道自己踩在厄拉科斯的沙上。【NPC 类型】守着水规的老弗雷曼人／把香料当账目算的采集队工头／出身帝国却同情原住民的行星学家／走私香料的水商／带着南方口音的厄崔迪家护卫。【威胁类型】沙暴与流沙、被护盾振动引来并吞掉一切的沙虫、哈克南家族留下的刺客与内奸，以及缺水——在厄拉科斯，脱水比刀伤死得快。个人武艺在这里远不如懂沙有用。【奖励风格】蒸馏服、沙虫钩、晶刀、霍尔兹曼护盾与一小袋香料；能力偏向在极端环境里活下来、读沙与读人，几乎没有超常力量。【不对劲的来源】穴地里那位老人接过香料样本后说，玩家身上那股味道和他三十年前送走的人一样，还报出了那人的去向；而弗雷曼人的传说里有一个从外星来的救世主，他们等得如此虔诚，玩家分不清自己是被当成客人，还是被当成预言的一部分。【时间线】建议固定在厄崔迪家族接管厄拉科斯后的最初几个月，正是沙暴季：保罗还没进入弗雷曼人的穴地，邓肯与哈瓦特仍在公爵身边，凯恩斯还在帝国任上。不要提前启用后期才登场的角色与设定，尤其不要让保罗以传道者或皇帝的身份出现。","powerStyle":"冷兵与生存向：晶刀、护盾、蒸馏服","difficultyBias":3,"signatureItems":["蒸馏服","沙虫钩","晶刀","霍尔兹曼护盾","一小袋香料"],"mainQuest":"主线任务：在沙暴抵达之前，从停在沙丘背风面的采集车里取回一箱香料样本，交给穴地里的那位老人。","mainQuestGoal":"把样本完整交到老人手上，弄清他说的那股味道与他三十年前送走的人是什么意思，并在沙暴封住来路前回到营地","sideQuests":[{"name":"运载器的信号","desc":"把一架失联运载器的应答信号重新接上，别让采集车孤零零留在沙面上","reward":"积分 150"},{"name":"一桶水的价钱","desc":"查清营地里少掉的那桶水被谁换成了钱","reward":"道具「弗雷曼人的储水杯」"},{"name":"护盾引来的东西","desc":"把关闭护盾后引开沙虫的路线画给采集队","reward":"积分 200"},{"name":"走私者的空箱","desc":"在香料箱的夹层里找出不属于香料的东西，并决定交给谁","reward":"道具「晶刀」"}],"factions":[{"name":"厄崔迪家族","desc":"刚接下厄拉科斯封地的外来统治者，讲荣誉也缺人手","attitude":"友善"},{"name":"弗雷曼人","desc":"沙漠深处的原住民，守着自己的水与秘密，对外人只肯给一次机会","attitude":"中立"},{"name":"哈克南家族","desc":"被夺走香料的旧主人，留下的探子与刺客还没有撤干净","attitude":"敌对"}],"npcs":[{"name":"保罗·厄崔迪","identity":"厄崔迪公爵的独子与继承人","role":"关键人物","personality":"早熟、自省，对预知既渴望又抗拒","hook":"他在梦里见过玩家，但梦里的玩家没有脸，于是他开始盯着玩家的一举一动","favorHint":"认真对待他说的梦、不把他当孩子会加分；嘲弄厄崔迪家或拿他父亲的结局开玩笑会掉分","gender":"男","age":"15 岁","race":"人类（厄崔迪家血脉）","faction":"厄崔迪家族","appearance":"瘦高的少年，深色头发偏长，垂到耳下，眼睛在暗处泛着浅绿。深绿与黑色调的紧身外衣，腰带上挂着训练用短刀与一只折叠水袋。站着时习惯把重心压低，说话前先看一眼门口，手指常在腰带上无意识地敲。","traits":["早熟","警觉","内省"],"relations":[{"name":"杰西卡","label":"母亲，也是他的第一位老师"},{"name":"雷托·厄崔迪","label":"父亲，他正在学着成为的那种人"},{"name":"邓肯·艾达荷","label":"教他用刀的人，也是家里最像亲人的护卫"}],"voice":"少用形容词，喜欢反问；谈预知的时候声音会压低。"},{"name":"契妮","identity":"弗雷曼少女，行星学家列特-凯恩斯的女儿","role":"盟友","personality":"利落、坚韧，看陌生人先看手再看脸","hook":"她答应带玩家走一趟沙脊的背风面，条件是玩家先按弗雷曼人的规矩分她一口水","favorHint":"按弗雷曼的规矩分享水、尊重穴地的禁忌会加分；浪费水或拿沙虫开玩笑会掉分","gender":"女","age":"16 岁","race":"人类（弗雷曼人）","faction":"弗雷曼人","appearance":"个子不高，身形紧实，脸瘦，鼻梁很窄，眼睛因为常年食用香料呈现近乎整体的深蓝。深色头发用布条束起，紧身蒸馏服外面披一件褪色斗篷，腰侧挂着晶刀。走沙地时步子极轻，习惯蹲下来用手背试风向。","traits":["利落","坚韧","警觉"],"relations":[{"name":"列特-凯恩斯","label":"父亲，也是她与外界打交道的唯一通道"},{"name":"斯第尔格","label":"穴地里说话最算数的那伊布，待她像自家晚辈"},{"name":"保罗·厄崔迪","label":"传说与梦里反复出现的那个外来少年，她还没想好怎么看他"}],"voice":"短句，语气平，不解释第二次；说起沙虫与水源时会带上敬意。"},{"name":"斯第尔格","identity":"弗雷曼泰布穴地的那伊布（首领）","role":"中立","personality":"严厉、守信，把族人的水看得比命重","hook":"他愿意收下玩家带回来的样本，但要玩家先回答一个问题：外来者能从这里带走什么","favorHint":"守穴地的规矩、替弗雷曼人保守秘密会加分；把穴地位置透露给帝国或哈克南人会掉分","gender":"男","age":"中年","race":"人类（弗雷曼人）","faction":"弗雷曼人","appearance":"身材高大，肩膀很宽，皮肤被烈日晒成深褐，脸上刻满风沙磨出的细纹，眼白早已被香料染蓝。蒸馏服外罩一件深色斗篷，头巾缠得很紧，腰上同时挂着晶刀与沙虫钩。说话前会先朝沙里吐一口唾沫，再用拇指摩挲刀柄。","traits":["严厉","守规","沉稳"],"relations":[{"name":"列特-凯恩斯","label":"与他一起谋划改变这颗星球的半个外人"},{"name":"契妮","label":"他看着长大的族中晚辈"},{"name":"雷托·厄崔迪","label":"新来的公爵，他还在看这个人值不值得合作"}],"voice":"声音低，语速慢，习惯拿水打比方；不容人讨价还价。"},{"name":"列特-凯恩斯","identity":"帝国派驻厄拉科斯的行星学家与法官","role":"关键人物","personality":"务实、沉默，把改变整颗星球当作毕生事业","hook":"他手里有一份五十年的沙丘移动记录，其中一处数据被人改过，改动的时间正是玩家到来的那一年","favorHint":"尊重弗雷曼人、把观测数据如实汇报会加分；替帝国或哈克南家打听穴地位置会掉分","gender":"男","age":"五十余岁","race":"人类（弗雷曼血统，受帝国教育）","faction":"银河帝国","appearance":"中等身材，皮肤被晒得干硬，深色头发里夹着灰白，胡须短而整齐。帝国款式的浅色长袍外面套着蒸馏服，胸前别着一枚小小的帝国徽记，腰带上挂着记录板与测风的小仪器。他习惯抓一把沙在掌心搓开，看沙粒从指缝落下判断风向。","traits":["务实","沉默","执着"],"relations":[{"name":"契妮","label":"女儿，也是他与弗雷曼人之间的桥"},{"name":"斯第尔格","label":"共同守着一个关于绿洲的梦的同伴"},{"name":"沙德姆四世","label":"他名义上效忠的帕迪沙皇帝"}],"voice":"说话像在念记录，句子平直，很少用比喻；谈到沙丘移动时才会有情绪。"},{"name":"岳医生","identity":"厄崔迪家的私人医生，苏克医学院出身","role":"潜在敌人","personality":"克制、疲惫，把秘密压在礼数底下","hook":"他替玩家处理了一处小伤，却在记录上写下错误的日期，随后请玩家不要向公爵提起","favorHint":"不追问他的私事、替他保守用药记录会加分；当面说出他与哈克南家的往来会掉分","gender":"男","age":"五十岁上下","race":"人类","faction":"厄崔迪家族","appearance":"瘦高，灰白头发梳得整齐，眼窝很深，眼下有一圈常年不散的青黑。深色长袍，袖口扣紧，随身提一只边角磨出木色的旧药箱。说话时双手交叠在药箱上，眼睛看着别处，笑容像是提前练过的。","traits":["克制","忧郁","矛盾"],"relations":[{"name":"雷托·厄崔迪","label":"他侍奉的公爵，也是他必须背叛的人"},{"name":"杰西卡","label":"他敬重的公爵夫人，他从不敢与她多谈"},{"name":"弗拉基米尔·哈克南男爵","label":"握着他妻子性命、因此握着他的人"}],"voice":"语气温和，用词讲究，句子收得很轻；被问到家人时会突然停住。"}]},{"id":"novel_foundation","category":"novel","canon":"基地","name":"基地","icon":"🌠","tagline":"谢顿算好了一切，除了人","mood":"档案、推演、危机、穹顶、交接","guidance":"【原著设定】银河帝国统治着数以千万计的住人星球，首都川陀被层层金属穹顶包住，帝国已经立国一万两千年，正在无可挽回地衰落。心理史学家哈里·谢顿以庞大人口为对象，算出帝国的崩溃以及随之而来的三万年黑暗，于是提出用一座科学殖民地缩短黑暗期的方案：在银河边缘的端点星建立基地，名义上是编纂一部囊括人类全部知识的百科全书。端点星资源匮乏，孤悬于帝国版图之外，邻近的安纳克里昂与司密尔诺原是帝国的星省，正随着帝国收缩而自立为王，并很快开始向基地提出要求。谢顿死后留下一座时间穹顶，会在每一次危机最深的时刻开启，放映他预先录下的影像。心理史学只能算出群体的概率，算不出某一个人的选择。【反复出现的意象】时间穹顶那扇只在特定时刻开启的金属门、档案室里一排排密实的文献盒、印在纸边的百科全书校样、墙上那幅已经过时的银河全图、议会厅里被磨得发亮的木桌。这些画面一出现，玩家就该知道自己站在端点星。【NPC 类型】埋头校订词条的老学者／把政治当作麻烦事的行政官／带着礼物与要求来的邻邦使节／把原子能当成神迹来拜的外邦祭司／在两条路线之间沉默观望的年轻技工。【威胁类型】邻近王国的觊觎与武力威胁、帝国收缩留下的权力真空、把科学当宗教或当武器用的短视者；最要紧的危险是路线之争——靠技术自保，还是靠贸易与信仰立足。【奖励风格】文献抄本与档案权限、原子能器件与小型能源、心理史学的推演结论，以及一份能换来他人信任的条约；这个世界几乎不给个人武力。【不对劲的来源】档案室里编号第七的那份文献写的不是过去，而是十年后才会发生的一场争吵，连争吵双方的语气都记得清清楚楚；而早已死去的谢顿留下的影像，总在最恰当的时刻说出最恰当的话。【时间线】建议固定在第一次谢顿危机前后、端点星建镇约五十年：百科全书派仍在掌权，哈丁刚刚开始主张另外一条路，安纳克里昂的要求正一步步逼近。不要提前启用后期才登场的角色与设定，商业贸易时代的设定与「骡」都不应提前出现。","powerStyle":"无超能力：心理史学、科技与外交","difficultyBias":2,"signatureItems":["密封的文献盒","百科全书校样胶片","时间穹顶的投影晶体","原子能护身符","银河帝国硬币"],"mainQuest":"主线任务：在档案交接仪式开始之前，把档案室里编号第七的文献抄出一份。","mainQuestGoal":"在仪式开始前抄完第七号文献并带出档案室，同时弄明白为什么它写的是一场十年后才会发生的争吵","sideQuests":[{"name":"第七号书架的灰","desc":"比对书架上的灰尘厚度，找出最近被人动过的那几本","reward":"积分 150"},{"name":"使节的礼物","desc":"把安纳克里昂使节送来的礼物原样登记，一件也不截留","reward":"积分 200"},{"name":"时间穹顶的座位","desc":"在影像开启前核对观礼席名单，划掉不该在场的人","reward":"道具「心理史学推演抄本」"},{"name":"不上账的校样","desc":"把一页被抽走的百科全书写稿找回来，只交还给写它的人","reward":"道具「原子能护身符」"}],"factions":[{"name":"端点星","desc":"以百科全书为名的科学殖民地，学者与行政官之间的分歧已经浮上台面","attitude":"友善"},{"name":"安纳克里昂王国","desc":"刚脱离帝国自立的邻邦，带着武器与要求派来了使节","attitude":"敌对"},{"name":"银河帝国","desc":"正在收缩的庞大旧秩序，暂时顾不上这块边缘之地","attitude":"中立"}],"npcs":[{"name":"萨尔弗·哈丁","identity":"端点星市长","role":"引导者","personality":"务实、强硬，擅长把不体面的事做得体面","hook":"他需要一份不在任何账目里的抄本，于是挑中了刚到端点星、没人认识的玩家","favorHint":"守时、把事情办得不留痕迹会加分；越过他直接找委员会或对外邦使节许诺会掉分","gender":"男","age":"四十余岁","race":"人类","faction":"端点星","appearance":"中等身材偏壮实，圆脸，下巴很厚，发际线后退得厉害，剩下的一圈头发梳得整齐。深色礼服外套配硬领衬衫，胸前别着一枚小小的市长徽章，右手常插在马甲口袋里，说话时用另一只手的手指敲桌面。","traits":["务实","强硬","算计"],"relations":[{"name":"路易斯·皮雷恩","label":"委员会主席，也是他真正要对付的那个人"},{"name":"约汉·李","label":"跟了他多年的助手，也是唯一敢劝他的人"},{"name":"哈里·谢顿","label":"他只在影像里见过、却一直在替他收拾局面的人"}],"voice":"嗓门洪亮，爱用买卖和账目的说法；被顶撞时先笑一下，再把声音压下去。"},{"name":"路易斯·皮雷恩","identity":"银河百科全书委员会主席","role":"对手","personality":"学究气重、固执，真心相信知识能救人类","hook":"他要求玩家按规矩登记抄写目的，并警告玩家不要在交接日靠近第七号书架","favorHint":"按流程办事、尊重他的学术成果会加分；把百科全书说成没用或当面支持哈丁会掉分","gender":"男","age":"五十余岁","race":"人类","faction":"端点星","appearance":"瘦高，头顶秃得干净，两鬓留一圈灰发，戴一副细框眼镜，镜腿用胶布缠过。白色礼服长袍式的制服，衣领硬得发亮，胸前口袋里插着两支笔。说话时习惯竖起一根手指，走路时脚步很碎。","traits":["固执","学究","正直"],"relations":[{"name":"萨尔弗·哈丁","label":"他最不放心的市长，两人的路线之争已无法调和"},{"name":"哈里·谢顿","label":"他奉为指路人的心理史学家"},{"name":"乔德·法拉","label":"他仍寄望于与之讲道理的邻邦使节"}],"voice":"用完整的书面句式说话，先讲原则再讲事实；被打断会从头再说一遍。"},{"name":"约汉·李","identity":"哈丁的助手与多年朋友","role":"盟友","personality":"沉稳、忠诚，话少而可靠","hook":"他把档案室的备用钥匙塞给玩家，只提一个条件：别让皮雷恩知道他来过","favorHint":"替他掩护、把哈丁的交代办完会加分；在公开场合提起他给过钥匙会掉分","gender":"男","age":"三十余岁","race":"人类","faction":"端点星","appearance":"中等个头，肩很宽，深色短发剪得极短，下巴有一道旧疤。灰蓝色工装外套，肘部磨得发白，腰间挂着一串钥匙与一只旧计时器。站着时双手插兜，进门先靠门框，说话时眼睛盯着地面。","traits":["沉稳","忠诚","低调"],"relations":[{"name":"萨尔弗·哈丁","label":"他跟随多年的人，也是他认定的唯一出路"},{"name":"路易斯·皮雷恩","label":"名义上的上司，他每次汇报都只说一半"},{"name":"哈里·谢顿","label":"他听不太懂、却愿意相信的影像"}],"voice":"声音低，句子短，喜欢用「行」和「不行」；很少解释理由。"},{"name":"乔德·法拉","identity":"安纳克里昂王国派驻端点星的使节","role":"潜在敌人","personality":"客气、耐心，把威胁说得像问候","hook":"他在交接日的观礼名单上添了玩家的名字，说是国王想认识新来的人","favorHint":"以礼相待、如实转达他能听懂的话会加分；替端点星刺探他的底线或当众驳他的面子会掉分","gender":"男","age":"四十余岁","race":"人类","faction":"安纳克里昂王国","appearance":"身材高大，肤色偏深，短须修剪得方方正正，眉毛很浓。深红与金色织物的王国外袍，领口别着一枚星形徽记，右手戴三枚印章戒指。行礼时把手按在胸口，笑起来只动下半张脸，站着时习惯把重心放在后脚。","traits":["客气","耐心","强硬"],"relations":[{"name":"萨尔弗·哈丁","label":"他要压服的市长，也是他唯一看得上的对手"},{"name":"路易斯·皮雷恩","label":"他更愿意打交道的学者，可惜对方说了不算"},{"name":"安纳克里昂的王","label":"他效忠的君主，给他的期限越来越短"}],"voice":"措辞讲究，句句留余地，用「我们希望」代替「我们要」；被拒绝时脸色不变。"},{"name":"哈里·谢顿","identity":"心理史学的创立者，只以时间穹顶里的全息影像出现","role":"关键人物","personality":"平静、克制，把个人的悲喜排除在计算之外","hook":"影像在结束时叫出了玩家的名字，而这个名字不属于任何一份端点星名册","favorHint":"认真听完影像、按他给的前提去推演会加分；试图向他提问或打断影像会掉分","gender":"男","age":"影像里是老年","race":"人类","faction":"端点星","appearance":"影像里的老人：长脸，白发与白须都修得整齐，眼窝深陷，额头很宽。款式古旧的黑袍，领口收得很紧，双手交叠在身前，站姿笔直。说话时头部轻微侧向一边，目光越过听众看向很远的地方。","traits":["平静","克制","疏离"],"relations":[{"name":"萨尔弗·哈丁","label":"影像里点过名的市长，也是他算式中最关键的那个变量"},{"name":"路易斯·皮雷恩","label":"忠实执行他最初方案的学者"},{"name":"约汉·李","label":"站在哈丁身后、名字从不出现在影像里的人"}],"voice":"语速均匀，不用第一人称抒情，像在宣读一份早就写好的报告。"}]},{"id":"novel_sherlockholmes","category":"novel","canon":"福尔摩斯","name":"福尔摩斯","icon":"🔍","tagline":"冬夜的敲门声，二十年前来过","mood":"浓雾、煤气灯、火漆、脚印、推理","guidance":"【原著设定】这是维多利亚时代的伦敦，煤气灯、马车、浓雾与报童共同构成街道，苏格兰场负责治安，私人咨询侦探靠委托为生。贝克街 221B 是夏洛克·福尔摩斯与医生华生合租的住所，楼下由房东太太打理。福尔摩斯的方法是把观察、化学、解剖学、足迹与烟灰这些琐碎知识拼在一起，从结果倒推出过程；他不信超自然，只信证据链是否闭合。这座城市里既有体面的绅士与穷困的工人，也有以犯罪为业、彼此用暗号联络的地下网络，其中最出名的一位是坐在网中央、以数学教授身份示人的犯罪顾问。钱、名声与体面在这里决定了大多数人会怎么选，一封匿名信就足以毁掉一个人。【反复出现的意象】贝克街那扇漆成深色、冬天蒙着水汽的门、楼梯上铺旧了的暗红地毯、壁炉上方插在信封刀旁的几封委托信、窗外煤气灯与马蹄声、桌上那台随时会被拉响的小提琴与散落的化学试管。这些画面一出现，玩家就该知道自己站在贝克街。【NPC 类型】按证据办事的警探／消息灵通的车夫与报童／替人跑腿的街头少年／从殖民地回来的军人或商人／把体面看得比真相重的上流人士。【威胁类型】被雇来的打手与巷子里的刀、伪造的现场与栽赃、委托人自己隐瞒的动机；这里的对决多半发生在证据被人动过手脚之后，而不是正面动手。玩家最该怕的不是拳头，是被人写进报纸。【奖励风格】放大镜、烟斗、旧案卷与剪报、灰斗篷与手杖、几瓶化学试剂；能力偏向观察、推理、跟踪与开锁，属于知识与技艺，而不是超能力。【不对劲的来源】房东太太接过信后说，这封信二十年前来过一次，连火漆上那个缺口都一模一样，连送信人的靴子声都记得；这个世界偶尔会巧合得过分，线索出现的时间与人的举止都过于合适。【时间线】建议固定在福尔摩斯与华生同住贝克街、莫里亚蒂尚未公开露面的那些年：华生的旧伤还影响行动，雷斯垂德隔三差五上门，福尔摩斯的名声刚在城里立住。不要提前启用后期才登场的角色与设定，尤其不要让莫里亚蒂提前成为台面上的对手。","powerStyle":"推理与拳斗向：放大镜、左轮、手杖","difficultyBias":0,"signatureItems":["放大镜","陶制烟斗","小提琴","案件剪报本","黄铜怀表"],"mainQuest":"主线任务：在午夜之前把一封没有署名的信送到贝克街 221B，交给开门的房东太太。","mainQuestGoal":"在午夜钟响前把信交到房东太太手上，并查清她为什么说这封信二十年前来过、连火漆的缺口都一样","sideQuests":[{"name":"雪地里的第二串脚印","desc":"沿贝克街到煤气灯巷走一遍，找出多出来的那串脚印通向哪里","reward":"积分 150"},{"name":"二十年前的卷宗","desc":"在苏格兰场的旧档案里找出被人撕走的那一页","reward":"积分 200"},{"name":"冻僵的报童","desc":"把街角的报童送回家，并问出他今晚替谁送过东西","reward":"道具「黄铜怀表」"},{"name":"不合调的音","desc":"听福尔摩斯拉完一段曲子，说出他到底在为哪件事分神","reward":"道具「旧案剪报本」"}],"factions":[{"name":"苏格兰场","desc":"伦敦的官方警力，规矩多、消息慢，但卷宗齐全","attitude":"中立"},{"name":"贝克街小分队","desc":"由街头少年组成的耳目，只认钱和熟人","attitude":"友善"},{"name":"莫里亚蒂的犯罪网络","desc":"藏在体面生意背后的联络网，从不亲自出手","attitude":"敌对"}],"npcs":[{"name":"夏洛克·福尔摩斯","identity":"贝克街的咨询侦探","role":"引导者","personality":"骄傲、专注，对无聊的耐受度极低","hook":"他看了信封一眼就说出玩家的来处，随后把信推回给玩家，要求玩家自己走这一趟","favorHint":"如实描述细节、承认自己没看清会加分；恭维他的名声或隐瞒观察到的东西会掉分","gender":"男","age":"三十余岁","race":"人类","faction":"独立（贝克街 221B）","appearance":"瘦高，肩窄，手指细长，鹰钩鼻很高，灰眼睛锐利，黑发向后梳。在家穿一件深灰紫色的旧晨袍，外出披灰色长斗篷、戴软呢帽，手杖不离手。坐着时十指相对抵住下巴，想到一半会抓起小提琴拉几个音，桌上摊着化学器皿与烟丝罐。","traits":["骄傲","专注","敏锐"],"relations":[{"name":"约翰·华生","label":"室友与记录者，他唯一长期容忍的人"},{"name":"雷斯垂德","label":"苏格兰场里他愿意搭话的那一个"},{"name":"莫里亚蒂","label":"他早已听过那个名字，只是一直没有证据"}],"voice":"语速快，喜欢把结论说在证据前面，再一条条倒推回去；对客套话没有耐心。"},{"name":"约翰·华生","identity":"退役军医，福尔摩斯的室友与记录者","role":"盟友","personality":"可靠、正派，对朋友毫无保留","hook":"他把自己的左轮借给玩家，只说一句冬夜的贝克街不太平，不问原因","favorHint":"尊重福尔摩斯的方法、把见到的细节如实说出来会加分；嘲笑他的记录像通俗小说会掉分","gender":"男","age":"三十余岁","race":"人类","faction":"独立（贝克街 221B）","appearance":"中等身材，体格结实，留着修剪整齐的短须，头发偏浅。深色三件式西装，外套剪裁合身，左肩的活动略有些僵。随身带一只旧怀表与一本巴掌大的记事簿，写字时把本子垫在膝盖上，站着时习惯把重心压在右腿。","traits":["可靠","正派","热心"],"relations":[{"name":"夏洛克·福尔摩斯","label":"室友与朋友，他愿意为之作证的人"},{"name":"雷斯垂德","label":"常来求助的警探，两人交情不错"},{"name":"哈德森太太","label":"替他照看起居的房东，也是他固定要打招呼的人"}],"voice":"语气平实，爱用军中的说法；说到福尔摩斯时语气会不自觉抬高。"},{"name":"哈德森太太","identity":"贝克街 221B 的房东","role":"中立","personality":"能干、爱操心，对房客的怪癖早已习以为常","hook":"她开门看到信的一瞬间脸色变了，随后坚持要玩家进屋喝杯茶再走","favorHint":"进门先擦鞋、把话说清楚会加分；在楼梯上跑动或打听房客的私事会掉分","gender":"女","age":"五十岁上下","race":"人类","faction":"独立（贝克街 221B）","appearance":"五十岁上下的妇人，身材微胖，灰发梳到脑后塞进发网。深色长裙外面系一条浆洗得发硬的围裙，腰间挂一串钥匙，走路时钥匙轻响。开门前会先在门后停一秒钟，说话时习惯用围裙擦手。","traits":["能干","唠叨","心软"],"relations":[{"name":"夏洛克·福尔摩斯","label":"住在她楼上的房客，她一边抱怨一边护着"},{"name":"约翰·华生","label":"最好说话的那位房客"},{"name":"雷斯垂德","label":"常在深夜上门的警探，她记得他每次来的日子"}],"voice":"语速快，爱把一句话说成两三句，开头是抱怨，结尾是关心。"},{"name":"雷斯垂德","identity":"苏格兰场警探","role":"中立","personality":"勤勉、务实，对聪明人又敬又不服","hook":"他手上有一份二十年前的旧卷宗，其中一页被人撕走，撕口很新","favorHint":"提供能用的线索、给他留面子会加分；当众指出他的疏忽或绕过他办案会掉分","gender":"男","age":"四十余岁","race":"人类","faction":"苏格兰场","appearance":"个子不高，身形偏瘦，脸窄，眼睛深陷，皮肤发黄，下巴留着一圈短须。深色大衣配圆顶帽，领口竖起，袖口沾着墨迹。进门前习惯在门口跺两下脚上的雪，说话时两只手互相搓着。","traits":["勤勉","务实","好面子"],"relations":[{"name":"夏洛克·福尔摩斯","label":"他常求助、也常被挖苦的那个人"},{"name":"约翰·华生","label":"他更愿意坐下来聊两句的那位医生"},{"name":"莫里亚蒂","label":"他查了很多年却始终抓不到的那个人"}],"voice":"语气急切，先报结论再补细节；被指出错误时先辩解一句，再改口。"},{"name":"莫里亚蒂","identity":"身兼数学教授的犯罪顾问","role":"潜在敌人","personality":"冷静、缜密，把犯罪当作一道数学题","hook":"他在雪夜的街角与玩家擦肩而过，留下一句只有玩家能听懂的话，随后连脚印都没有留下","favorHint":"保持镇定、不接他的话头会加分；当面揭穿他的身份或威胁他的网络会掉分","gender":"男","age":"五十岁上下","race":"人类","faction":"莫里亚蒂的犯罪网络","appearance":"极高极瘦，前额隆起，眼窝深陷，面色苍白得没有血色，脸刮得很干净。全黑的礼服与长外套，领结打得一丝不乱，手杖的杖头是素银。站着时头部轻微左右摆动，走路几乎不出声，说话时语调平得像在讲课。","traits":["冷静","缜密","危险"],"relations":[{"name":"夏洛克·福尔摩斯","label":"他承认的唯一对手，也是他要清除的人"},{"name":"雷斯垂德","label":"在他看来不值一提、却始终绕不开的警探"},{"name":"塞巴斯蒂安·莫兰","label":"他手下最得力的一枚棋子"}],"voice":"声音轻而平，用完整的句子，从不说威胁的话，只陈述将要发生的事实。"}]},{"id":"novel_montecristo","category":"novel","canon":"基督山伯爵","name":"基督山伯爵","icon":"🗝️","tagline":"晚宴开场前，账要一笔笔算","mood":"巴黎、晚宴、假身份、书信、复仇","guidance":"【原著设定】故事的时代是王政复辟与七月王朝交替的法国。马赛的水手爱德蒙·唐泰斯在订婚当天被捕，罪名是替被流放的拿破仑传递信件，告发他的人出于嫉妒与私利；审理此案的年轻代理检察官为了保住自己的父亲与前途，把他送进了海上的伊夫堡。十四年后他逃出监狱，靠狱中结识的神父留下的线索取得一座岛上的宝藏，再以基督山伯爵的身份回到巴黎。他同时使用好几个身份，用金钱、情报与人情布置一张网，让仇人彼此倾轧。这个世界没有魔法，决定胜负的是财富、名誉、法律程序与谋杀；贵族的地位靠头衔与联姻维持，银行家靠信用的传闻维持，一纸书信就足以动摇一个家族。【反复出现的意象】香榭丽舍大道上那栋过于安静、只穿黑衣的仆人来往的宅子、晚宴长桌上按名次排好的席位卡、伊夫堡潮水线与牢房里刻在墙上的算式、剧院包厢里互相打量的望远镜、马赛老港的旧船坞与账本。这些画面一出现，玩家就该知道自己站在巴黎的社交季里。【NPC 类型】把复仇排进日程表的东道主／恪守荣誉却开始怀疑的年轻军官／被买通又后悔的仆人／以法律为职业的冷酷检察官／在沙龙里传话与造谣的社交客。【威胁类型】下在酒里的东西、决斗、伪造的信件与银行挤兑，以及司法与警察系统——在那里，一纸文书比一把刀更快地毁掉一个人。玩家最该怕的是被人记住名字。【奖励风格】宝石与金币、来路不明的药剂、遗嘱与信件、假身份与通行证、一柄决斗用的手枪；能力偏向社交、识谎、伪造与耐心布局，绝无超自然力量。【不对劲的来源】玩家按吩咐打开书房第二个抽屉时，里面已经躺着一封告密信，字迹和玩家的一模一样，连折痕的方向都相同；而伯爵的复仇也太准了，连仇人的反应都在他预料之内，像是照着剧本执行的。【时间线】建议固定在伯爵抵达巴黎、开始向三个仇人下手的初期：马尔塞夫、唐格拉尔与维尔福都还在巴黎城内，海黛刚被带回宅子，莫雷尔一家尚未被卷进漩涡。不要提前启用后期才登场的角色与设定，尤其不要让安德烈亚·卡瓦尔坎蒂与维尔福夫人下毒线一类后期情节提前发生。","powerStyle":"社交与布局向：金币、假身份、决斗手枪","difficultyBias":1,"signatureItems":["装满金币的钱袋","盖着陌生纹章的信","假身份通行证","宝石戒指","一柄决斗手枪"],"mainQuest":"主线任务：在晚宴开场之前，把一封告密信放进书房的第二个抽屉里。","mainQuestGoal":"在客人入席前完成放置，并查清抽屉里那封字迹与玩家完全相同的信是谁、什么时候放进去的","sideQuests":[{"name":"谁动过抽屉","desc":"在晚宴结束前查清书房的第二个抽屉今天被谁打开过","reward":"积分 150"},{"name":"厨娘的口信","desc":"把厨房里的一句闲话带到该听的人耳朵里，又不留下自己的名字","reward":"积分 200"},{"name":"希腊文旧文书","desc":"替海黛确认一份文书上的签名属于谁","reward":"道具「刻着姓名的印章戒指」"},{"name":"马赛来的账本","desc":"在莫雷尔家的旧账本里找出那一笔被人抹掉的债","reward":"道具「决斗手枪」"}],"factions":[{"name":"莫雷尔一家","desc":"马赛的老船主之家，正直得在巴黎显得格格不入","attitude":"友善"},{"name":"巴黎贵族与银行界","desc":"靠头衔、联姻与信用传闻运转的社交圈，谁都可能出卖谁","attitude":"中立"},{"name":"检察官与警方","desc":"握有文书与拘票的一方，程序本身就是武器","attitude":"敌对"}],"npcs":[{"name":"基督山伯爵","identity":"自称基督山伯爵的巴黎新贵，真实身份是旧日水手爱德蒙·唐泰斯","role":"引导者","personality":"礼貌、克制，把复仇当作一门需要耐心的学问","hook":"他在晚宴前把一件差事交给玩家，报酬高得离谱，要求只有一条：不要让任何人看见玩家进书房","favorHint":"按他的安排行事、不问多余的问题会加分；自作主张或试图向外人透露他的身份会掉分","gender":"男","age":"四十岁上下","race":"人类（法国马赛出身）","faction":"基督山伯爵府","appearance":"高而瘦，肤色苍白，黑发向后梳得平整，眼睛深黑，几乎不眨眼。黑色礼服剪裁极精，领巾洁白，背心口袋里垂下一条细金链。随身带一枚样式素净的戒指与一把小手枪，走路很轻，坐着时手指会缓慢地转动那枚戒指。","traits":["克制","耐心","冷峻"],"relations":[{"name":"海黛","label":"他从奴役中带回并保护的人，也是他计划里的一环"},{"name":"马克西米利安·莫雷尔","label":"旧日恩人的儿子，他唯一不肯牺牲的人"},{"name":"热拉尔·德·维尔福","label":"把他送进伊夫堡的那个人，如今是巴黎的检察官"}],"voice":"语速平缓，用词精确，习惯用问句替人把话说完；说到往事时会停一拍。"},{"name":"马克西米利安·莫雷尔","identity":"马赛老船主皮埃尔·莫雷尔之子，现役骑兵军官","role":"盟友","personality":"正直、热忱，相信人总有好的那一面","hook":"他在晚宴上把玩家当成能说话的人，托玩家替他递一封不能经他人之手的私信","favorHint":"替他保守秘密、替受欺的人说话会加分；拿他父亲破产的旧事开玩笑或与伯爵的算计合谋会掉分","gender":"男","age":"二十余岁","race":"人类（法国人）","faction":"莫雷尔一家","appearance":"身量高，肩背挺直，深色头发微微卷曲，唇上留着短短的胡须，肤色被南方阳光晒成浅褐。深蓝色军官制服，铜扣擦得很亮，肩章平整，佩剑挂在左腰。习惯把帽子夹在腋下，说话时身体微微前倾。","traits":["正直","热忱","冲动"],"relations":[{"name":"基督山伯爵","label":"他感激却始终看不透的那位新朋友"},{"name":"朱莉·莫雷尔","label":"姐姐，家里真正拿主意的人"},{"name":"瓦朗蒂娜·德·维尔福","label":"他爱着的人，也是他最不敢说出口的顾虑"}],"voice":"语气爽快，句子直；谈到父亲和姐姐时声音会变低。"},{"name":"海黛","identity":"希腊的阿里帕夏之女，被伯爵从奴役中带回的少女","role":"关键人物","personality":"沉默、敏锐，把忠诚与仇恨都藏得很深","hook":"她隔着屏风听见玩家提到费尔南的名字，之后主动请玩家替她辨认一份希腊文的旧文书","favorHint":"不追问她的过去、认真听她说完会加分；把她当成伯爵的附庸或在她面前替费尔南辩解会掉分","gender":"女","age":"二十岁上下","race":"人类（希腊人）","faction":"基督山伯爵府","appearance":"黑发很长，编成许多细辫垂到腰下，眼睛又大又黑，皮肤是浅浅的蜜色。东方式的白色长衣，腰上系着绣金的宽腰带，腕上戴几圈金镯，脚上是绣花软鞋。她坐得很直，说话时看着地面，手里常握一把长颈小琴，紧张时手指会收紧。","traits":["沉默","敏锐","坚忍"],"relations":[{"name":"基督山伯爵","label":"救了她、也答应替她讨回公道的人"},{"name":"费尔南·蒙德戈","label":"出卖她父亲、让她失去一切的那个人"},{"name":"贝尔图乔","label":"伯爵的管家，平日照看她起居的人"}],"voice":"声音低，句子短，常用母语的称呼；情绪起伏时改说法语，说得很慢。"},{"name":"热拉尔·德·维尔福","identity":"巴黎的代理检察官","role":"对手","personality":"严苛、体面，为了保住名声可以牺牲任何人","hook":"他认出玩家递上的信封纸质不对，把玩家叫到书房门外，要求解释这封信的来历","favorHint":"按法律与身份称呼他、把话说得有条理会加分；提到伊夫堡、提他父亲的政治旧事会掉分","gender":"男","age":"四十余岁","race":"人类（法国人）","faction":"检察官与警方","appearance":"高瘦，脊背笔直，脸色偏白，薄嘴唇抿成一条线，深色头发梳得紧贴头皮，两鬓开始泛灰。黑色礼服，领子硬挺，右手食指上戴一枚印章戒指。说话时下巴微抬，习惯用指节敲桌面，看人时目光先落在对方的手上。","traits":["严苛","体面","冷酷"],"relations":[{"name":"基督山伯爵","label":"他本能地不信任、却查不出底细的陌生人"},{"name":"努瓦蒂埃·德·维尔福","label":"他的父亲，一个他既怕又恨的旧日革命者"},{"name":"瓦朗蒂娜·德·维尔福","label":"女儿，他计划用来换取联姻的筹码"}],"voice":"字字清楚，喜欢用法律术语下判断；发怒时声音反而更轻。"},{"name":"唐格拉尔","identity":"银行家，受封男爵的暴发户","role":"潜在敌人","personality":"虚荣、贪利，把一切关系都换算成数字","hook":"他在晚宴前向玩家打听一个能赚一笔的消息，说只要玩家点头，抽屉里的东西他可以代为保管","favorHint":"恭维他的眼光、给他留出赚头会加分；提醒他注意信誉或当面说破他的算盘会掉分","gender":"男","age":"五十岁上下","race":"人类（法国人）","faction":"巴黎贵族与银行界","appearance":"中等身材，微微发福，鬓角灰白，头发梳得油亮，脸圆而松。深色燕尾服绷在肚子上，背心上挂着粗金表链，翻领别一枚钻石别针，手指上套两枚戒指。说话前先笑，笑完才说正题，习惯用手帕擦额头。","traits":["虚荣","贪利","多疑"],"relations":[{"name":"基督山伯爵","label":"他最想搭上的大客户，也是他最忌惮的人"},{"name":"吕西安·德布雷","label":"替他打听消息、也替他妻子花钱的年轻人"},{"name":"费尔南·蒙德戈","label":"当年与他一起告发那个水手的旧同伙"}],"voice":"爱把数字和利息挂在嘴边，用亲热的口气谈条件；被拒绝后立刻改口贬低对方。"}]},{"id":"novel_pride_prejudice","category":"novel","canon":"傲慢与偏见","name":"傲慢与偏见","icon":"🪭","tagline":"一把扇子，两套说辞，一条走廊","mood":"乡间舞会、礼数、门第、闲话、婚姻","guidance":"【原著设定】故事发生在十八世纪末到十九世纪初的英格兰乡间，财产多由男性继承，一个家庭的女儿若没有嫁妆，就只能靠婚姻取得栖身之处。人的价值用年收入多少镑来衡量，并且这个数字在社交场合会被反复提起。麦里屯是附近最近的集镇，乡绅宅邸散在几英里之内，内瑟菲尔德是新近租出的庄园，浪搏恩是班纳特一家住的村子，五圃村是邻近的庄园。伦敦的亲戚是抬升门第的楼梯，也是流言的源头。舞会是乡间最重要的事，男女必须由人介绍才能共舞，邀请、退场与告辞都有固定格式。彬格莱先生租下内瑟菲尔德之后，他带来的朋友达西一进场就成了全场最贵的一双眼睛，而民兵团那个冬天驻扎在麦里屯，红色制服因此满街都是。【反复出现的意象】舞会散场后走廊上摇晃的烛台与墙边码好的空椅子、远处还没停的琴声；内瑟菲尔德那排整齐的落地窗与门前刚洒过水的碎石道；浪搏恩那条被车轮压出两道深印的林荫路；麦里屯街上军官的红色制服与随手摘下的便帽；以及一本字迹很小、记着宾客姓名与身价的来访名录。这些画面一出现，玩家就该知道自己站在赫特福德郡的乡间。【NPC 类型】急着替女儿找丈夫的母亲／靠转述别人家事为乐的邻家太太／处处觉得被慢待的体面绅士／总比人慢半拍却自认很会说话的表亲／站在门边看谁和谁跳舞的那种客人。他们讲礼，也讲价。【威胁类型】流言。这个世界里名声比财产更容易被毁掉，一次不合规矩的独处就能被人谈论一整年；还有门槛，有人一辈子进不去某个圈子，钱与新绸子都换不来。【奖励风格】扇子、手套、鼻烟盒、请柬、便条一类社交物件；以及被某个圈子里的人记住名字，这种信誉本身就是能带走的东西。【不对劲的来源】礼数把人包得严实，它既是保护也是勒紧的绳子，每个人都清楚规矩，但在意的人不多；冒犯一次会被记住很多年，而宅子里的走廊与客房之间没有多少秘密，谁在什么时刻经过哪里，第二天全家都会知道。【时间线】建议固定在原著开头那一段：彬格莱刚租下内瑟菲尔德，达西在舞会上说了不客气的话，民兵团刚进麦里屯，女主人公还没有开始她的那趟旅行，柯林斯先生才刚到。不要提前启用后期的庄园、彭伯里相遇与私奔事件，也不要让结局提前发生。","powerStyle":"无超自然力量，靠措辞、名声与分寸取胜","difficultyBias":-1,"signatureItems":["一把骨柄折扇","绣着字母的手套","洒过香水的便条","银质鼻烟盒","内瑟菲尔德的请柬"],"mainQuest":"在乡间这个冬天里站稳脚跟，让一场各方都在算计的婚事按它原本的样子发生而不被搅乱。","mainQuestGoal":"在彬格莱与达西先后离乡之前，让该成的婚事成一桩、该破的误会破一层，且不留下任何以玩家为主角的丑闻","sideQuests":[{"name":"宴会上的座位","desc":"替一位没有女伴的客人安排位置，让这顿饭不出现任何一次冷场","reward":"积分 150"},{"name":"信封上的字迹","desc":"辨认一封匿名短笺出自谁的手，并决定把它交给谁","reward":"道具「来访名录」"},{"name":"雨后的林荫路","desc":"陪一位客人冒雨走完那段路，全程不许提到任何人的财产","reward":"积分 200"},{"name":"琴声不能停","desc":"在客厅里接替弹琴的人，弹到两位长辈把该说的话说完","reward":"道具「借来的琴谱」"}],"factions":[{"name":"班纳特一家","desc":"五个女儿、一份限定继承的产业与一位急着嫁女的母亲","attitude":"友善"},{"name":"内瑟菲尔德的客人","desc":"从城里来的有钱圈子，客气、体面，并且随时在给人打分","attitude":"中立"},{"name":"麦里屯的民兵团","desc":"穿着体面、收入有限，满街的红制服足以搅动整个乡间的婚事","attitude":"中立"}],"npcs":[{"name":"班纳特先生","identity":"浪搏恩的乡绅，班纳特家的家长","role":"引导者","personality":"挖苦、退让、把真正的判断藏在玩笑里","hook":"他是唯一不追问玩家来历的人，只在书房的门口放了一句「你上次来的时候，坐在哪张椅子上」。","favorHint":"安静听他讲完一本书、不附和太太的盘算会加分；当众替他太太圆场面、或表现出对财产的急切会掉分","gender":"男","age":"五十岁上下","race":"人类（英格兰乡绅）","faction":"班纳特一家","appearance":"灰白头发从额前向后梳得稀薄，露出宽额。深褐色长外套配浅色马甲，衣料讲究但袖口已磨出毛边，领巾系得随意。他偏瘦，背微驼，习惯把两只手交叠在身前或背在身后。走路很慢，说话前先半闭一下眼睛，像是刚从书页上抬起视线。书房里常有一本翻开的书压在扶手椅上。","traits":["讥诮","疏懒","看得透"],"relations":[{"name":"班纳特太太","label":"结发妻子，他一生最大的消遣与负担"},{"name":"伊丽莎白","label":"最偏爱的女儿，也是唯一敢跟他斗嘴的人"},{"name":"莉迪亚","label":"最不省心的小女儿，他嘴上放任，心里清楚后果"}],"voice":"慢条斯理，句子短而干，常以一句轻描淡写的反问收尾；说完就低头看自己的书。"},{"name":"伊丽莎白","identity":"班纳特家的二女儿","role":"关键人物","personality":"机敏、爱笑、看人快也容易看错一次","hook":"她注意到了玩家比谁都熟悉这座宅子的走廊，于是开始不动声色地试探，把每一次试探都当成一场小赌。","favorHint":"说话直白、把实情摆在桌面上、承认自己的判断错了会加分；替达西或替她母亲辩护、拿她姐姐的婚事当谈资会掉分","gender":"女","age":"二十岁上下","race":"人类（英格兰乡绅之女）","faction":"班纳特一家","appearance":"深褐色头发在脑后盘成简单的髻，几缕碎发落在耳侧。细布长裙多为素色，晨间披一件薄披肩，出门时戴有系带的软帽。身形轻盈，眼睛很亮，笑起来眉眼先动。她习惯一边走一边摆弄手里那把折扇，坐下时腰背挺直，听人说话会微微偏头。","traits":["伶俐","倔强","自省"],"relations":[{"name":"班纳特先生","label":"最谈得来的父亲，也是她衡量男人的尺子"},{"name":"达西","label":"她先入为主地看不起、后来才重新认识的人"},{"name":"夏洛特·卢卡斯","label":"最好的朋友，也是她最不愿承认的现实教材"}],"voice":"轻快，爱用玩笑把话说轻，反问句很多；真正被触到时立刻收起笑容，一句一句讲道理。"},{"name":"达西","identity":"来自德比郡的富有绅士，彬格莱的挚友","role":"潜在敌人","personality":"骄傲、固执、极少解释自己","hook":"他认定玩家是混进这个圈子的无名之辈，在走廊上截住玩家，要一个说得通的来历，而真话恰好是他最不会信的那一种。","favorHint":"不当众吹捧他、谈到他妹妹或庄园时保持分寸、把事情办得干净会加分；当面调侃他的门第、打听他的财产会立刻掉分","gender":"男","age":"二十八岁上下","race":"人类（英格兰乡绅）","faction":"内瑟菲尔德的客人","appearance":"深色头发自然贴顺，前额略高，轮廓分明。深蓝或黑色的精工外套、白领巾、擦得发亮的皮靴，手腕上的表链很细。个子高，肩背挺得很直，站在房里总选离人群最远的位置。目光平稳，直视人时不眨，被冒犯也只是抬一下下巴。","traits":["高傲","重信","不善言辞"],"relations":[{"name":"彬格莱","label":"最好的朋友，他愿意为对方压住自己的判断"},{"name":"伊丽莎白","label":"他第一次求而不得的人，也是唯一反驳过他的人"},{"name":"威克姆","label":"旧日恩怨的另一半，一见面就会毁掉一顿晚饭"}],"voice":"句子完整、语速克制，用词讲究得像在写公文；被逼急了会说得很直，直得伤人。"},{"name":"班纳特太太","identity":"班纳特家的女主人","role":"盟友","personality":"热心、话多、把嫁女儿当成毕生事业","hook":"她一眼认定玩家是个能替她传话的人，从舞会散场起就抓着玩家替她确认「谁今晚跟谁站得最近」。","favorHint":"听她说完关于邻居家事的推论、替她递一次话会加分；拿她的见识开玩笑、或拦着她去见有钱客人会掉分","gender":"女","age":"四十多岁","race":"人类（英格兰乡绅之妻）","faction":"班纳特一家","appearance":"深棕头发上扣一顶蕾丝边软帽，帽带是鲜艳的缎带。衣裙颜色比家里其他人亮，外出披一件大披肩，手袋里塞满没写完的便条。身形圆润，语速快时会上半身向前倾，说到得意处两只手一起比划。坐着时脚也轻轻点地。","traits":["絮叨","精明","护短"],"relations":[{"name":"班纳特先生","label":"丈夫，她一生都在抱怨他的无动于衷"},{"name":"莉迪亚","label":"最疼的小女儿，她引以为傲也最容易出事的一个"},{"name":"伊丽莎白","label":"第二个女儿，两人一说话就要顶起来"}],"voice":"语速快、音量大，喜欢把消息一口气讲完再补一句评价；抱怨丈夫时爱翻旧账。"},{"name":"莉迪亚·班纳特","identity":"班纳特家最小的女儿，民兵团社交圈的常客","role":"中立","personality":"轻浮、莽撞、把热闹当幸福","hook":"她拉着玩家替她递一张折成小方块的便条，却不肯说收信人是谁，也不肯说是谁替她写的。","favorHint":"陪她说舞会上的事、不告发她的小动作会加分；把她拉回座位、提到她的姐姐会让她当场冷下脸掉分","gender":"女","age":"十五六岁","race":"人类（英格兰乡绅之女）","faction":"班纳特一家","appearance":"浅褐色卷发扎起，帽子上系着艳色缎带。裙摆爱选最浅的颜色，走动时裙角扫过地面。个子不高，皮肤白皙，笑起来声音很大。手里常握着折扇或一小束刚摘的花，坐不住，总在往人群最热闹的地方挪。","traits":["冒失","爱热闹","没心机"],"relations":[{"name":"班纳特太太","label":"最宠她的母亲，两人一拍即合"},{"name":"伊丽莎白","label":"总想管住她的姐姐，她对此很不服气"},{"name":"威克姆","label":"她全副心思扑上去的军官，也是家里最担心的事"}],"voice":"又急又响，喜欢用「你猜怎么样」开头；被问细节就说不清，只会重复「反正特别有意思」。"}]},{"id":"novel_great_gatsby","category":"novel","canon":"了不起的盖茨比","name":"了不起的盖茨比","icon":"🌃","tagline":"灯就在对岸，船上没有一个人","mood":"长岛、香槟、旧钱、幻梦、夜色","guidance":"【原著设定】故事发生在禁酒令时期的美国东部，长岛上有两处风格迥异的住宅区：东卵住着家世久远的老钱，西卵住着刚富起来的新钱，两处隔一道海湾相望，水上看得见对面的绿灯、豪宅与码头。城里靠卖酒致富的人不少，生意与犯罪只隔一层称呼。宴会、汽车、高尔夫、马球与舞台是这个世界的通用语言，谁是谁的表亲、谁在哪所学校念过书，比谁有多少钱更要紧。人在这种场合靠名字互相确认，而名字往往靠传闻拼出来。西卵那栋别墅的院子里每周末灯火通明，乐队、酒与陌生人一同进场，多数人没见过主人，也不打算见。【反复出现的意象】水对岸码头尽头那盏小小的绿灯；灰烬谷路口那块画着两只大眼睛的旧广告牌；一辆明黄色的敞篷汽车；卧室里堆到齐腰、一件件往下扔的彩色衬衫；从草坪上方炸开的烟花与随之而来的掌声。这些画面一出现，玩家就知道自己站在长岛的哪一侧，以及是哪一年。【NPC 类型】不请自来、从不与主人照面的客人／抢着让所有人记住自己名字的时髦男女／喝多了留在场里不肯走的男人／被雇来演奏与跳舞的职业乐手与舞者／站在门口替所有人核对身份、清楚每个名字真假的管门人。他们都很友好，也都不打算记住你。【威胁类型】传闻。这一带的名声建在别人嘴上，一句关于你钱从哪来的话就能让你从宾客变成话题；还有阶级的分界，东卵认定「我们这类人」有一套自己的算法，钱可以新，人不行。更现实的是遗忘：宴会散场后，主人家连客人的名字都记不住，而这个世界对无名之辈向来不留位置。【奖励风格】香槟、刻着字母的烟盒、旧唱片与乐谱、一辆来路不明的汽车、一张写着名字的请柬；以及一晚上的通行权——被某个圈子当面叫出名字。【不对劲的来源】满屋人都说与主人相熟，却没人能说出他到底是做什么的；宴会里的一切都像在重演一段早已结束的旧事，而他在等的那个人并不在场；更奇怪的是，他能准确说出他从未见过的事，包括你昨天做过什么。【时间线】建议固定在1922年夏天，长岛西卵那栋别墅大宴宾客的时期：他还在往对岸伸手，女主人公尚未踏进他家门，几个人后来闹出的那场车祸还没有发生。不要提前启用后面的死亡、葬礼与真相揭底，也不要让结局提前发生。","powerStyle":"无超自然力量，靠场面、人情与传闻操作","difficultyBias":0,"signatureItems":["刻字母的银烟盒","一件丝质衬衫","烫金请柬","一盏码头尽头的小绿灯","一副旧望远镜"],"mainQuest":"在这个夏天的西卵待下去，把一场跨越海湾的重逢推到它该到的那一步，并看清是谁在买单。","mainQuestGoal":"在那场午后的会面与随后的夏天结束前，让两个人的重逢真正发生一次，并让玩家自己不被写进第二天的传闻里","sideQuests":[{"name":"名单上的陌生名字","desc":"找出宴会门口签到簿里反复出现却从没进过院子的那个人","reward":"积分 150"},{"name":"琴谱上的口红印","desc":"把落在乐谱上的东西还给它的主人，不许看里面的字","reward":"道具「乐队用的小号」"},{"name":"灰烬谷的顺路车","desc":"开车送一位客人回城，全程不进灰烬谷那家修理厂","reward":"积分 200"},{"name":"散场后的草坪","desc":"在佣人清扫之前，把草坪上留下的东西还给愿意认领的人","reward":"道具「一盏未灭的小灯」"}],"factions":[{"name":"西卵的新贵","desc":"钱来得快、来路含糊，把宴会当通行证，急切地想被对面记住","attitude":"友善"},{"name":"东卵的老钱","desc":"家世稳固、姿态从容，用礼貌把界线圈得很清楚","attitude":"中立"},{"name":"城里的生意人","desc":"经手酒与别的货物，讲究交情，也讲究谁欠谁","attitude":"潜在敌对"}],"npcs":[{"name":"尼克·卡拉威","identity":"来自中西部的债券推销员，住在西卵的小房子，女主人公的表亲","role":"引导者","personality":"克制、旁观、愿意替人说一句公道话","hook":"他把玩家当成唯一可以讲话的人，因为玩家也知道这栋别墅里的事从头到尾都不太对。","favorHint":"听他讲完一段别人的往事、替人保守秘密会加分；当众评价他表姐或把他的话转述出去会掉分","gender":"男","age":"二十九岁","race":"人类（美国白人）","faction":"西卵的新贵","appearance":"浅棕色头发向后梳得整齐，鬓角很短。灰蓝色西装、白衬衫、素色领带，鞋擦得干净但不新。身形偏瘦，站姿端正，在人多的地方总往边上退。他习惯把两手插进外套口袋，看人时先看一眼再移开，像在心里记下一句话。","traits":["内敛","宽厚","有分寸"],"relations":[{"name":"盖茨比","label":"隔着一片草坪的邻居，他起初只觉得对方是个谜"},{"name":"黛西·布坎南","label":"他的表姐，也是他一直在替她担心的那个人"},{"name":"乔丹·贝克","label":"他想认真对待又不敢全信的一位女士"}],"voice":"平缓、用词干净，习惯先描述再评价；被人追问时就停一下，说一句「我说不好」。"},{"name":"乔丹·贝克","identity":"职业高尔夫球手，女主人公的朋友","role":"盟友","personality":"冷淡、机警、不说真话也不说假话","hook":"她看穿了玩家不是这个圈子的人，却提出替玩家圆一个身份，条件是玩家替她盯住一件事。","favorHint":"替她挡下难缠的追问、承认自己不懂高尔夫会加分；拿她比赛的事开玩笑、在席间提到她从前的那场比赛会掉分","gender":"女","age":"二十出头","race":"人类（美国白人）","faction":"东卵的老钱","appearance":"深色短发贴着耳侧，剪得利落。深色调的直筒长裙配白色手套，颈上一条细链。个子高而瘦，肩背挺直，下巴习惯性微抬。手里常夹着一根长烟嘴或一副手套，走路时步子又轻又稳，坐下会把裙摆理平再看人。","traits":["高傲","精明","不认账"],"relations":[{"name":"尼克·卡拉威","label":"她乐意谈一阵子的人，但她并不打算完全坦白"},{"name":"黛西·布坎南","label":"多年的朋友，她清楚对方的处境也清楚对方的脾气"},{"name":"盖茨比","label":"她起初不信这个人的来历，后来成了唯一替他说话的人"}],"voice":"语调平，喜欢答非所问；被问到私事时就笑一下，把话题轻轻推到别人身上。"},{"name":"杰伊·盖茨比","identity":"西卵那栋别墅的主人，宴会的主人","role":"关键人物","personality":"自制、礼貌、把全部指望压在同一个念头上","hook":"他记得玩家上次出现在院子里的时刻，并交给玩家一件小事去办，那件小事牵着他在等的那个人。","favorHint":"替他把一场见面安排稳妥、不追问他的生意、称他「老伙计」会加分；打听他财富来路、提到他从前那个名字会立刻掉分","gender":"男","age":"三十岁上下","race":"人类（美国白人）","faction":"西卵的新贵","appearance":"浅棕色头发剪得很短，打理得一丝不乱。常穿白色西装或深色西装，配亮色领带，衬衫袖口露出金色的袖扣，无名指上有一枚沉甸甸的戒指。身形挺拔，笑容标准得像练过很多次，说话时会略略欠身。紧张时两手在身侧轻轻开合一次，随即恢复不动。","traits":["执着","自律","不坦白"],"relations":[{"name":"黛西·布坎南","label":"他心里那盏灯，五年里他把一切都围着这盏灯摆好"},{"name":"尼克·卡拉威","label":"他挑中的见证人，也是唯一愿意听他把话说完的人"},{"name":"汤姆·布坎南","label":"挡在他和那盏灯之间的男人，他嘴上轻视，心里清楚分量"}],"voice":"客气到生硬，习惯称人「老伙计」；讲起自己的经历会越讲越顺，细节却一次比一次对不上。"},{"name":"汤姆·布坎南","identity":"东卵的富豪，女主人公的丈夫，曾打过马球","role":"对手","personality":"蛮横、偏见重、把体面当特权","hook":"他一口断定玩家是西卵那个暴发户雇来办事的人，于是当场用一套关于血统与书籍的说辞盘问玩家。","favorHint":"在他面前承认规则由他们这类人定、不碰他妻子的话题会加分；引用书本上他没读过的段落、替盖茨比说话会立刻掉分","gender":"男","age":"三十岁上下","race":"人类（美国白人）","faction":"东卵的老钱","appearance":"体格宽阔结实，曾在运动场上练出来的肩背，皮肤偏红。深色西装、硬领白衬衫，领扣上别着一枚朴素的别针，脚上是马球靴式的皮鞋。头发剪得短而整齐，声音低沉洪亮。说话时喜欢叉开双腿站着，一只手插在口袋里，用眼睛从上到下打量人。","traits":["霸道","傲慢","底气虚"],"relations":[{"name":"黛西·布坎南","label":"妻子，他把她当成自己体面的一部分"},{"name":"盖茨比","label":"他看不上的暴发户，也是他真正忌惮的人"},{"name":"默特尔·威尔逊","label":"城里那间公寓的另一半生活，他从不打算让两边见面"}],"voice":"高声、断言式，喜欢用「我们这类人」开头；一旦被顶回来就立刻提高音量，把话题扯到血统与书上。"},{"name":"默特尔·威尔逊","identity":"灰烬谷修车厂老板的妻子，城里公寓的另一位住户","role":"中立","personality":"泼辣、爱面子、急着挤进不属于她的圈子","hook":"她把玩家认成城里来的体面人，求玩家替她在一场小聚会上说几句她能接得上的台面话。","favorHint":"叫她一声太太、陪她挑一件衣服、替她圆一次场面会加分；提起修车厂与那辆旧车、或者纠正她的说法会掉分","gender":"女","age":"三十岁上下","race":"人类（美国白人）","faction":"城里的生意人","appearance":"深色卷发在额前烫出整齐的卷、盘在颈侧。衣裙颜色浓艳，布料比灰烬谷的人讲究，指上戴着不成套的戒指。身段丰腴，腰束得紧，说话时下巴抬得很高，手指会来回抚平裙面。她笑起来很响，一听人提到体面两字就立刻精神。","traits":["张扬","势利","缺安全感"],"relations":[{"name":"汤姆·布坎南","label":"带她离开灰烬谷的男人，她把这段关系当成往上走的台阶"},{"name":"乔治·威尔逊","label":"她的丈夫，她既看不起他，又靠他维持体面"},{"name":"尼克·卡拉威","label":"那次小聚会上被临时请来的人，她一直想从他嘴里问出上流圈子的事"}],"voice":"音调高、话头急，爱把别人的称呼学一遍再加重说出来；被冷落时会突然大声点烟。"}]},{"id":"novel_1984","category":"novel","canon":"1984","name":"1984","icon":"📺","tagline":"昨天的那一页，今天重印了一遍","mood":"电幕、新话、改档案、配给、沉默","guidance":"【原著设定】世界分成三个长期交战的大国：大洋国、欧亚国与东亚国，战线的位置会被官方随时改写，敌人也就随时换人。大洋国由英社党统治，最高领袖的画像无处不在。四个部门分工明确：真理部负责新闻、娱乐、教育与艺术，和平部负责战争，仁爱部负责秩序与刑讯，富裕部负责把短缺分派下去。语言正在被压缩成新话，词汇越少，能说出的异端就越少。电幕装在每一间有党员的屋子里，思想警察与巡逻队在夜里活动，未成年人的侦察队也会告发父母。历史不是被保存的，而是被不断改写的：真理部记录司的工作，就是把过去的报纸、照片与记录改成与今天的口径一致，改完的原件丢进记忆洞，随气流烧掉。【反复出现的意象】墙角那面会亮起红灯的电幕；旧货铺橱窗里那幅印着教堂与小孩的画片；每天仇恨时间出现在屏幕上那张脸；一块裹着珊瑚的玻璃镇纸；栗树咖啡馆里那张总摆着棋盘的桌子。这些画面一出现，玩家就知道自己站在大洋国的哪一间屋子里。【NPC 类型】记录司里被磨平了棱角、只求按钟点下班的同事／走廊上来回巡逻的思想警察／食堂里跟着口令重复口号的党员／来送新话词典的翻译司人员／被处理掉之后谁也不肯提起的那个空座位。【威胁类型】思想警察、电幕、邻居与亲人的举报。任何一次表情不对、梦话、写下的字迹，都可能让人在夜里消失，名字随后从档案里被抹掉，连家属都改口说不认识。【奖励风格】配给券、旧表、旧唱片一类的黑市旧物；偶尔能喝到真正的咖啡与糖；以及片刻的、只在极短时间里成立的自由。这里没有超自然能力，能带走的最多是自由。【不对劲的来源】党不仅安排未来，还不断修订过去，当所有记录都口径一致，谎话就是事实；更让人不安的是，档案里常常已经有玩家的名字，而日期早于玩家第一次到这个世界的那一天。【时间线】建议固定在1984年四月前后：记录司的一位工作人员刚开始写日记不久，还没有读过那本被传说的书，也没有人往他手里塞过纸条。不要提前启用后期才登场的角色与设定，也不要让那场读禁书、租房与逮捕的走向提前发生。","powerStyle":"无超自然力量，靠档案、口令与噤声生存","difficultyBias":-1,"signatureItems":["一本牛皮纸封面的日记本","珊瑚嵌玻璃镇纸","配给券","党徽别针","一幅画着老教堂的旧画片"],"mainQuest":"真理部里做完这个春天的每一天，把不该被记住的事记下来，同时不让自己被写进任何一份报告。","mainQuestGoal":"在记录司的下一次大清洗到来之前，让一件被改写过的旧事留下至少一份对得上的证据，并保住自己不被登记为思想犯","sideQuests":[{"name":"食堂里的第三个座位","desc":"查清为什么有人连续三天没来吃饭，又为什么没人问起","reward":"积分 150"},{"name":"旧货铺的一件小东西","desc":"买下一件不属于这个年代的旧物，并把它藏到电幕照不到的地方","reward":"道具「裹着珊瑚的镇纸」"},{"name":"一句改过的口号","desc":"在标语上找出被人重新刷过的那一处，记住新旧两版的样子","reward":"积分 200"},{"name":"词典的第七百页","desc":"把新话词典里刚被删掉的那个词背下来，但一次也不要写出来","reward":"道具「旧版新话词典」"}],"factions":[{"name":"英社党核心党员","desc":"掌握真正的权力与配给，清楚电幕后面是谁在看，也清楚历史每天怎么被改","attitude":"中立"},{"name":"真理部记录司","desc":"一群按时上下班、把改写文件当手艺的人，彼此不问多余的话","attitude":"友善"},{"name":"思想警察","desc":"夜里出现的巡逻队与无处不在的举报网，他们不需要理由，只需要记录","attitude":"敌对"}],"npcs":[{"name":"温斯顿·史密斯","identity":"真理部记录司的职员，三十九岁，右踝上有一处旧伤","role":"盟友","personality":"谨慎、记性好、在没人看见时忍不住多想一步","hook":"他把玩家当成唯一可能也记得旧口径的人，于是试探着问起一件几年前被改过的产量数字。","favorHint":"在电幕死角里和他说话、替他记住一个日期会加分；在食堂或其他人在场时与他多说一句、或者提起他的日记会让他立刻掉分并疏远你","gender":"男","age":"三十九岁","race":"人类（大洋国党员）","faction":"真理部记录司","appearance":"金棕色头发，发际后退，脸色因常年不见阳光而发黄。穿真理部统一的蓝色工装，袖口有墨渍，胸口别着党徽。身形瘦削，走路时右腿略跛，坐下前会先看一眼电幕的位置。随身带着一支蘸水钢笔和一小卷纸，习惯把东西压在袖口下面。","traits":["多疑","固执","怀旧"],"relations":[{"name":"茱莉娅","label":"他既想要又不敢信的那个人，两人之间全靠暗号"},{"name":"奥勃良","label":"他认定可以托付的人，这份认定本身就是他最大的判断失误"},{"name":"赛麦","label":"同部门的同事，聪明、狂热，并且比谁都更早从名册上消失"}],"voice":"声音低，句子短，常把话说一半再看对方一眼；在公开场合说话像念公文，没有起伏。"},{"name":"茱莉娅","identity":"真理部小说司的机械修理工，二十多岁","role":"关键人物","personality":"外热内冷、精通规矩的漏洞、把反叛当成私事","hook":"她在走廊里故意撞了玩家一下，把一张折成小方块的纸条塞进玩家手里，纸上只有一个地点，没有解释。","favorHint":"照她定的方式接触、不在公开场合看她、替她带一次黑市的东西会加分；在食堂对她点头、或者追问她的住处会立刻掉分，她也会消失几个星期","gender":"女","age":"二十六岁","race":"人类（大洋国党员）","faction":"真理部记录司","appearance":"黑发在额前系一条鲜红色缎带，那是青年反性同盟的标志。蓝色工装外面系一条工作围裙，腰间挂着工具，手指上有油污与细小的划痕。身量结实，动作干脆，走路时步子快而稳。在人群里她把脸绷得很正经，独自一人时眉眼立刻松开。","traits":["机灵","务实","胆大"],"relations":[{"name":"温斯顿·史密斯","label":"她主动挑上的人，她比他更清楚这段关系会怎么结束"},{"name":"奥勃良","label":"她从一开始就不信这个人，只是没能拦住对方"},{"name":"赛麦","label":"同部里的熟人，她对这种狂热分子一向绕着走"}],"voice":"平日在人前只讲标准的口号式短句；私下里语速快，带粗话，笑起来毫不收敛。"},{"name":"奥勃良","identity":"英社党核心党员，地位稳固，住在有佣人的公寓里","role":"潜在敌人","personality":"从容、耐心、把权力当成一种需要慢慢施行的东西","hook":"他在走廊上叫住了玩家，准确说出玩家档案里那个不该有人记得的日期，然后请玩家有空去他那里坐坐。","favorHint":"在公开场合保持忠诚的样子、不主动去找他会加分；私下与他交换看法、接受他的酒或旧书会掉分，并且这份掉分要等到很久以后才会被人发现","gender":"男","age":"四五十岁","race":"人类（大洋国核心党员）","faction":"英社党核心党员","appearance":"体格宽厚，脸型粗大，颈部厚实，动作却很轻。深色党的制服剪裁考究，比一般党员多一副黑手套，胸前党徽擦得发亮。灰发整齐向后梳，眼神平和，微笑之前先停半秒。他说话时会略微前倾，像在听一件很有意思的事。","traits":["沉静","深不可测","有耐心"],"relations":[{"name":"温斯顿·史密斯","label":"他十年前就留意到的人，也是一场长谈的对手"},{"name":"茱莉娅","label":"他早已知晓却一直不动的那个人"},{"name":"赛麦","label":"他亲手处理掉的旧相识，口气像在谈一份文件"}],"voice":"语调低缓，措辞极其得体，从不提高声音；说到最要紧的话时反而更轻，像在讲一件与己无关的事。"},{"name":"赛麦","identity":"真理部研究司的语言学家，新话词典的编纂者之一","role":"中立","personality":"聪明、狂热、对新话有一种近乎虔诚的兴趣","hook":"他兴冲冲地给玩家念了几条还没定稿的新词条，并邀请玩家替这些词挑一个更「干净」的说法。","favorHint":"认真听他解释词根、承认新话很美会加分；对删词表示可惜、或者在文件上留下自己的批注会掉分","gender":"男","age":"三十岁上下","race":"人类（大洋国党员）","faction":"真理部记录司","appearance":"深色头发剪得很短，额头高，戴一副细金属框眼镜。蓝色工装外面套着研究司的深色罩衫，口袋里插着几支不同颜色的笔。身形瘦高，说话时习惯用手指在空中划词。随身带着一叠卡片，每张只写一个词。","traits":["博学","狂热","天真"],"relations":[{"name":"温斯顿·史密斯","label":"午饭时常坐在一起的人，两人几乎从不谈政治之外的事"},{"name":"奥勃良","label":"他仰慕的对象，从不怀疑对方的用心"},{"name":"茱莉娅","label":"同部门打过照面的人，他对此毫无印象"}],"voice":"语速快、兴致高，爱用「这个词明年就没有了」作开场；说到专业处会一口气列出一串词根。"},{"name":"帕森斯太太","identity":"与党员一家同住一栋楼的女邻居，家里有两个孩子","role":"中立","personality":"疲惫、和善、被生活与孩子一起磨得没有脾气","hook":"她隔着门小声向玩家借一段配给线，随口提到她丈夫昨晚又被带走「去帮个忙」，说的时候眼睛一直看着地面。","favorHint":"帮她带一次孩子、分她一点配给会加分；打听她丈夫的事、问她家里最近有谁来过会掉分，她会立刻把门关上","gender":"女","age":"三十岁上下","race":"人类（大洋国党员）","faction":"真理部记录司","appearance":"浅褐色头发随手挽起，几缕垂在颈后。灰旧的家常长裙外面罩着一件洗白的围裙，袖口卷到肘部，手上总是湿的。身形瘦，肩背略驼，眼下有很深的青影。说话时两只手绞着围裙边角，眼睛不肯长时间看人。孩子一吵就立刻转身，动作快得像被训练过。","traits":["疲倦","温顺","怕事"],"relations":[{"name":"帕森斯","label":"她的丈夫，一个连被自家孩子告发都会说好话的人"},{"name":"温斯顿·史密斯","label":"同楼的邻居，她替他照看过几次门口的信件"},{"name":"赛麦","label":"楼里从前的住户，她只记得那人搬走得很安静"}],"voice":"声音很轻，句子断断续续，说完话常补一句「不打扰你了」；提到孩子时语气才稍微活一点。"}]},{"id":"novel_brave_new_world","category":"novel","canon":"美丽新世界","name":"美丽新世界","icon":"💊","tagline":"没有人生病，也没有人想要别的东西","mood":"福特纪元、试管、唆麻、条件反射、稳定","guidance":"【原著设定】纪元以汽车工业的那位先驱为起点计算，世界国的口号是「人人属于彼此」。人不再被生育，而是在孵化与条件设置中心里按需制造：先经波卡诺夫斯基流程让一枚卵分裂出几十个一模一样的孪生体，再按阿尔法、贝塔、伽马、德尔塔、艾普西隆五个种姓分别调配氧气与营养，让高种姓聪明体面、低种姓矮小耐劳。婴儿期用睡眠教育在耳边的喇叭里反复灌入分类口号，用鲜花与书本配合电击，让他们终生讨厌花与阅读。分类中心负责分配职业与住处，苏摩是随身携带的药剂，一片就能让人不与现实计较；感官电影、阻力游戏与不限定的交往都是正当娱乐。生育与家庭这些词是羞耻的，稳定是最高价值，任何人表现出不合群都会被送去接受检查，再严重就送往岛上的定居点。文明区之外还有保留地，那里还过着旧式生活。【反复出现的意象】分类中心门前排着队、穿着同色制服的孩子；走廊尽头那扇发着柔光的苏摩发放窗口；睡眠教育室里贴地的喇叭与地毯上的小耳机；婴儿室里那盘花与一起接通的地板；霓虹灯下不停播放的合成音乐与随风飘来的香水味。这些画面一出现，玩家就知道自己站在世界国的哪一层。【NPC 类型】在街角分发苏摩的护士／条件反射室里盯着仪表的技师／负责巡查社区的监察／在派对上请你喝一杯的体面男女／一边干活一边背分类口号的低种姓工人。他们全都真心觉得自己过得很好。【威胁类型】监察与档案。被判定为不合群的人不会受罚，而是先被请去做检查，然后被移走；此外还有失落感本身，一旦承认自己并不快乐，就等于承认全体人都错了。【奖励风格】苏摩配剂、感官电影票、合成香水与音乐、指定给某个种姓的特权通行证；这里给的不是武器，而是让人舒服的东西，以及一次短暂的、允许说出真话的许可。【不对劲的来源】所有人都是被造出来的，连喜欢什么、怕什么都由那些编号提前安排好了；更让人不安的是他们全都真心感到幸福，这里的医生把幸福当成可以处方的结果。【时间线】建议固定在福特纪元第七世纪、新伦敦的日常时期：从保留地被带回文明区的那个年轻人还没有住进任何人家里，受器重的心理学家也还没因为一次失礼被调到岛上。不要提前启用后期的保留地冲突与流放情节，也不要让那个被带回来的年轻人提前登场。","powerStyle":"无超自然力量，靠条件设置、唆麻与身份层级","difficultyBias":-1,"signatureItems":["半克唆麻锭","感官电影入场券","睡眠教育耳机","分类卡","合成香水小瓶"],"mainQuest":"在文明区过完这段时间，把每一件被指派的小事办完，同时弄清为什么总有人不肯被分类。","mainQuestGoal":"在那个从保留地来的人进入新伦敦之前，让一名不肯被分类的学生得到她自己愿意的安置，并让玩家的名字不出现在任何一份报告里","sideQuests":[{"name":"婴儿室里的那盘花","desc":"把一束真花送进一间条件反射室，然后在电击开始前决定收不收回","reward":"积分 150"},{"name":"分发窗口的短少","desc":"查清一条街上这个月的唆麻为什么少了三份，答案不在账本上","reward":"道具「一整盒唆麻」"},{"name":"合成音乐的第七轨","desc":"在派对上找到那张被反复播放、却不属于本季曲目的唱片","reward":"积分 200"},{"name":"低种姓口中的口号","desc":"向一名工人问清他每天背的那句话什么意思，再把答案守住","reward":"道具「分类中心的旧名册」"}],"factions":[{"name":"孵化与条件设置中心","desc":"决定每个人是什么、怕什么、喜欢什么的机构，从不出错也从不解释","attitude":"中立"},{"name":"社区监察","desc":"负责巡查街道与派对，把不合群的迹象写成报告，谈吐永远亲切","attitude":"潜在敌对"},{"name":"低种姓工人","desc":"在流水线与电梯间里讨生活的人，话少、认命，却记得很多正经档案里没有的事","attitude":"友善"}],"npcs":[{"name":"伯纳德·马克斯","identity":"孵化与条件设置中心的阿尔法加级心理学家，受器重也人人避着","role":"引导者","personality":"自负、敏感、总觉得自己被亏待","hook":"他挑中玩家当听众，因为玩家是唯一不会拿他与别的阿尔法比体格的人，而他想借玩家之口证明自己与别人不一样。","favorHint":"听他抱怨完、承认他的判断比别人准会加分；提到他的身量、或者当众把他的想法说给别人听会立刻掉分","gender":"男","age":"三十岁上下","race":"人类（世界国阿尔法加种姓）","faction":"孵化与条件设置中心","appearance":"深色头发向后梳，发缝笔直。阿尔法加的灰绿色制服剪裁合身，但肩线总显得空。个子比同种姓的人矮半头，肩窄，站着时习惯把重心压在一只脚上。手指细长，说话时爱把袖口拉平。他眉头常皱着，看人先看对方的身高与肩宽。","traits":["敏感","自视甚高","怯于行动"],"relations":[{"name":"列宁娜·克朗","label":"他带在身边又时时不安的人，他怕她太合群"},{"name":"赫姆霍兹·沃森","label":"他嫉妒又依赖的朋友，对方的从容让他难受"},{"name":"穆斯塔法·蒙德","label":"他一直想被对方高看一眼的那个人，而对方从不给他这个机会"}],"voice":"语速偏快，句子长，喜欢引用条例与数字；一旦被驳就转为冷笑，把话讲得更急。"},{"name":"列宁娜·克朗","identity":"贝塔级护士，负责胚胎储存与社交部门的事务","role":"盟友","personality":"明快、合群、偶尔会为一件小事不安","hook":"她拉着玩家一起去找那个总在课上走神的学生，因为她隐约觉得把人送进分类中心这件事没那么简单，却说不清哪里不对。","favorHint":"陪她办完指派的事、夸她把工作做得漂亮会加分；当众拒绝她、或者说她心里不舒服是件不对的事会立刻掉分，她也会慌张地躲着你","gender":"女","age":"二十多岁","race":"人类（世界国贝塔种姓）","faction":"社区监察","appearance":"金棕色头发在额前烫成整齐的波浪，戴一顶小小的贝塔级便帽。绿色短罩衣配白色灯笼裤，腰间系着苏摩药盒，脚上是软底鞋，走动时衣料发出轻响。身量苗条，面色红润，笑时露出整齐的牙。她习惯一边走一边摸药盒的搭扣。","traits":["温顺","勤快","易受影响"],"relations":[{"name":"伯纳德·马克斯","label":"她同行过几次的人，她清楚他难相处却也同情他"},{"name":"赫姆霍兹·沃森","label":"她欣赏的那类人，两人一起办过几件事"},{"name":"亨利·福斯特","label":"她长期往来的对象，两人相处得毫无负担"}],"voice":"轻快、句尾上扬，爱用「福特啊」作感叹；被追问时就笑着换话题，或者建议先吃一片苏摩。"},{"name":"穆斯塔法·蒙德","identity":"世界国的世界控制者之一，新伦敦最高层的十人之一","role":"中立","personality":"从容、博学、把稳定当成唯一值得守的东西","hook":"他单独把玩家叫进办公室，摆出两本旧书问玩家更信哪一本，然后表示他早就知道玩家是从别处来的。","favorHint":"听他把话讲完、承认幸福需要代价会加分；激动地为旧世界辩护、或者表现出想要改变别人的念头会立刻掉分","gender":"男","age":"五十岁上下","race":"人类（世界国阿尔法加种姓）","faction":"孵化与条件设置中心","appearance":"黑发浓密，鬓角有一片灰白，脸型方阔，唇厚。深色制服上没有多余饰物，只有一枚小小的世界国徽章。体格壮实却不显臃肿，坐姿稳，双手交叠在桌上。说话前会停一停，目光很稳，笑起来只动嘴角。桌上常放着两本旧书与一杯不加苏摩的酒。","traits":["沉静","博识","冷酷"],"relations":[{"name":"伯纳德·马克斯","label":"他随手就能提上来也能随手推下去的下属"},{"name":"赫姆霍兹·沃森","label":"他欣赏其才华却必须处置的人"},{"name":"孵化与条件设置中心主任","label":"他连名字都不必记住的那一层人，却是他随时可以动用的手"}],"voice":"语速慢，措辞准确，爱用反问句；讲到最要紧的话时会先沉默两秒，再平静地说出来。"},{"name":"赫姆霍兹·沃森","identity":"情感工程学院的讲师，写口号与合成音乐的阿尔法加","role":"关键人物","personality":"开朗、有才华、心里有个说不出口的空洞","hook":"他把自己写的一段不合规格的句子给玩家看，并问玩家这段话听起来像不像另一种东西。","favorHint":"认真读他写的东西、不评价他的身材与受欢迎程度会加分；把他写的句子转述给监察、或者劝他多去参加派对会掉分","gender":"男","age":"三十岁上下","race":"人类（世界国阿尔法加种姓）","faction":"孵化与条件设置中心","appearance":"金发卷曲，额前留出一撮。阿尔法加制服穿在他身上很挺，袖口扣得整齐。他体格健硕，肩宽胸厚，皮肤偏深，眼睛很亮。谈得投机时会两手抱住自己的膝盖往后靠，笑声响亮，站在人群中央也不紧张。随身带着一支小喇叭与几页写满字的纸。","traits":["开朗","有天分","困于虚无"],"relations":[{"name":"伯纳德·马克斯","label":"他真心当朋友的人，他比对方更早看出这段友谊的麻烦"},{"name":"列宁娜·克朗","label":"他欣赏的同事，两人从不谈要紧的事"},{"name":"穆斯塔法·蒙德","label":"他敬而远之的上司，对方却对他格外有兴趣"}],"voice":"声音洪亮、节奏感强，爱把话说得像口号；真正动情时会忽然放低声音，句子变短。"},{"name":"孵化与条件设置中心主任","identity":"新伦敦孵化与条件设置中心的主任，阿尔法加，主管全中心的分批与调配","role":"潜在敌人","personality":"自得、刻板、把规程看得比人重","hook":"他在巡查走廊时把玩家当成编号外的人员，当场要求玩家报出所属中心与批次，并声称查不到就是有人擅自调换过名单。","favorHint":"认真听他讲完整套流程、按规程报上自己的身份会加分；顶撞他的判断、或者替被记名的人解释会立刻掉分，他会把玩家一起写进报告","gender":"男","age":"五十岁上下","race":"人类（世界国阿尔法加种姓）","faction":"孵化与条件设置中心","appearance":"体形壮实发福，浅灰色头发梳得一丝不乱，后颈的肉压在领口上。深色的阿尔法制服扣得很整齐，胸袋插着一支钢笔，手里常拿着一块写字的夹板。他走路步子不快，下巴微抬，说话时把夹板端在胸前。停下来讲规程时会先用手指点一下夹板，像在核对一条早已记熟的条目。","traits":["刻板","自得","不容质疑"],"relations":[{"name":"伯纳德·马克斯","label":"被他记在心里、随时准备送出文明区的下属"},{"name":"列宁娜·克朗","label":"他认为合格的那种护士，从不多问一句的那一类"},{"name":"穆斯塔法·蒙德","label":"他敬畏并且时时想讨好，却始终摸不到门槛的那个人"}],"voice":"官腔十足，习惯把规程条款当成理由；被质疑时先重复一遍自己的原话，再抬高声音要求对方自重。"}]},{"id":"novel_hitchhikers_guide","category":"novel","canon":"银河系漫游指南","name":"银河系漫游指南","icon":"🛸","tagline":"飞船正被偷开，而晚餐要准时","mood":"毛巾、概率、官僚、荒诞、倒计时","guidance":"【原著设定】银河系里通行一本名为《银河系漫游指南》的电子手册，封面印着两个字：别慌。它比另一套昂贵的百科全书便宜得多，也更不靠谱，其中一条著名结论需要一台巨型计算机算上数百万年。地球在故事开始后不久就被沃贡人以修建超空间快速通道为由拆除，因为通知早已在别的星球公示了几十年。人类幸存者搭乘便船进入太空，随后登上一艘名为黄金之心号的飞船，这艘船装着无限非概率驱动。驾驶它的是那位刚卸任的银河系总统，他偷了船，还带上了同伴；船上另有一台极度沮丧的机器人，它的智能远高于所有乘员，情绪却远低于所有人。银河系政治由官僚机构与各种委员会把持，总统只是个礼仪性的头衔。毛巾是星际搭便车者最重要的装备。【反复出现的意象】搭在肩上的那条毛巾；手册屏幕上突然弹出的一行条目与它的免责声明；飞船外那场谁也看不懂的、色彩乱流的概率效应；沃贡人那种粗壮青灰的身影与其糟糕得足以作为酷刑的诗歌；一台圆胖机器人拖着步子走过走廊时留下的沉重叹息。这些画面一出现，玩家就知道自己在银河系的哪一段路上。【NPC 类型】把日程表看得比命重要的舰上后勤人员／搭便船多年、对什么都无所谓的旅人／情绪低落到拒绝执行任何命令的舰载机器／打着官腔、要求你填表的银河系调查员／在酒吧里用故事换酒的星際骗子。他们对荒诞习以为常，对认真极其不耐。【威胁类型】沃贡人与其舰队、银河系官僚体系的一纸公文、无限非概率驱动带来的突发错位、以及那些比你聪明得多、也无聊得多的家伙。最要紧的一点是：这里没有逻辑可以依靠。【奖励风格】毛巾、手册条目、一次性概率装置、翻译鱼、飞船上的临时身份与舱位；能得到的东西都很实用，也很不可靠。【不对劲的来源】这艘飞船本身建立在逻辑上不可能的事情上，走廊偶尔会变成别处的走廊，昨天谈定的事今天全船人都不记得，而所有人都觉得这很正常。更让人不安的是，指南里关于你的那条条目已经写好了。【时间线】建议固定在地球被拆除后的最初几周：几个人刚偷到那艘飞船不久，飞船还在被通缉，船上还没有那位后来才出现的女性同伴的旧关系带来的麻烦，也还没有前往那颗传说中的行星。不要提前启用后期的餐厅、行星与真相揭底，也不要让结局提前发生。","powerStyle":"科技与概率造物：毛巾、翻译鱼、非概率装置","difficultyBias":1,"signatureItems":["一条旧毛巾","《银河系漫游指南》电子手册","翻译鱼","地球被拆除的正式通知","一艘偷来的飞船上的餐牌"],"mainQuest":"在这艘随时会开到别处的飞船上活下去，弄明白自己为什么会被算进这一船人里。","mainQuestGoal":"在下一次沃贡人锁定的追捕到来之前，让飞船离开这片区域，并让玩家在乘员名单上留下一个正式的、被承认的身份","sideQuests":[{"name":"厨房的第九次修改","desc":"让舰上那台对菜品极度敏感的机器相信今天不需要它即兴创作","reward":"积分 150"},{"name":"一条被借走的毛巾","desc":"找回那条被当作降落伞、毯子与祭品用过的毛巾，并归还本人","reward":"道具「搭便车者的毛巾」"},{"name":"手册里关于你的条目","desc":"在指南的数据库里查到写着自己的那一条，并决定改不改它","reward":"积分 200"},{"name":"沃贡诗的朗诵会","desc":"全程听完一段沃贡诗歌而不离席，随后在登记表上签下自己的名字","reward":"道具「翻译鱼」"}],"factions":[{"name":"黄金之心号的乘员","desc":"一船来路各异的搭便车者，靠偷来的飞船和运气往前走","attitude":"友善"},{"name":"银河系总统府与官僚机构","desc":"头衔响亮、实权稀薄的一整套机构，遇事第一反应是要求填表","attitude":"中立"},{"name":"沃贡人建设舰队","desc":"奉命拆除挡路的行星与挡路的人，公文齐全，手段粗暴","attitude":"敌对"}],"npcs":[{"name":"福特·普里弗克特","identity":"《银河系漫游指南》的场外研究员，曾在地球上困了十五年","role":"引导者","personality":"随和、机敏、把要紧的事说得像无关紧要","hook":"他认定玩家与地球那档子事有关，因为指南数据库里早就有玩家的条目，而更新时间早于地球被拆除的那天。","favorHint":"在紧急关头先抓上毛巾、听他讲完一段无关的宇宙见闻会加分；浪费他的酒、或者在地球被拆这件事上表现得太轻松会掉分","gender":"男","age":"看起来三十岁上下，实际年龄不详","race":"贝塔猎户座人（长期伪装成人类）","faction":"黄金之心号的乘员","appearance":"棕发杂乱，额前总翘起一撮，脸上有常年晒出来的褐斑。旧皮夹克肘部磨得发白，里面是颜色变灰的衬衫，脖子上挂着毛巾，肩上挎一只鼓鼓的帆布包。身形偏瘦，走路散漫，站没站相。他习惯用两根手指夹着酒杯，说话时眼睛往四周扫，一直在找能换来的东西。","traits":["随和","机灵","不按规矩"],"relations":[{"name":"阿瑟·登特","label":"他从地球上顺手带走的那个人，他一直觉得欠对方一个解释"},{"name":"赞福德·毕博布鲁克斯","label":"半路搭上的老相识，他清楚这家伙有多不可靠"},{"name":"马文","label":"船上那台让他头疼的机器，他从未找到跟它好好说话的办法"}],"voice":"语调轻松，爱把灾难说成小麻烦；解释事情时东拉西扯，关键处忽然一句到位。"},{"name":"阿瑟·登特","identity":"来自地球的英国人，地球被拆除时的幸存者","role":"盟友","personality":"谨慎、拘谨、一直在努力搞清楚状况","hook":"他抓住玩家不放，因为玩家是这艘船上第二个还惦记着地球、还会说人话的人。","favorHint":"耐心回答他的问题、帮他找到一杯像样的茶会加分；嘲笑他的困惑、或者告诉他地球已经没了这件事不必在意会掉分","gender":"男","age":"三十岁上下","race":"人类（地球人）","faction":"黄金之心号的乘员","appearance":"深色头发乱糟糟，前额有一道睡痕。身上是沾了泥的条纹睡衣外面套着一件晨衣，脚下是一只拖鞋与一只临时找来的软鞋，手腕上还留着一只停了的旧表。身形中等偏瘦，肩膀习惯性收着。他站着时两手不知往哪放，说话前会先看一圈周围有没有危险。","traits":["拘谨","执拗","困惑"],"relations":[{"name":"福特·普里弗克特","label":"把他从地球上拖走的朋友，也是他一切困惑的来源"},{"name":"马文","label":"那台让他莫名愧疚的机器人，他总忍不住跟它搭话"},{"name":"崔莉恩","label":"船上另一位地球幸存者，他见到她时几乎要哭出来"}],"voice":"句子规整、带敬语，习惯先问「抱歉，请问」；被荒诞的事实砸中时会重复对方最后三个词。"},{"name":"马文","identity":"黄金之心号上的智能机器人，具备极高智能与极端低落情绪","role":"潜在敌人","personality":"抑郁、刻薄、聪明到对一切都提不起兴趣","hook":"玩家礼貌地问了它一句，它破天荒地多说了三句话，随后要玩家替它做一件它随时能自己做到的事。","favorHint":"认真对待它的感受、请它帮一个它乐意嘲笑的忙会加分；说「振作一点」、催它快点会立刻掉分，并让它记很久","gender":"男（机器，用男性称呼）","age":"出厂数年","race":"智能机器人（人格型）","faction":"黄金之心号的乘员","appearance":"个子矮小、体态圆胖，外壳是浅金属色，正面有一排指示灯，多数时候只有一颗暗着发微光。头部由几个不对称的部件拼成，一对大眼睛黯淡无神，关节处露出铆钉与磨痕。走路时步子沉重，两条短臂垂在身侧。它常停在一处不动，灯光明灭一下，像在叹气。","traits":["抑郁","尖刻","无所不知"],"relations":[{"name":"阿瑟·登特","label":"它乐意与之说话的地球人，因为对方的困惑让它感觉稍微好一点"},{"name":"福特·普里弗克特","label":"它最常挖苦的对象，对方的随和让它更烦躁"},{"name":"赞福德·毕博布鲁克斯","label":"名义上的船长，它从不承认这个称呼"}],"voice":"语调平得没有起伏，句子长而泄气，喜欢在陈述句后补一句更悲观的结论；说完会停一下，等别人接不上话。"},{"name":"崔莉恩","identity":"地球幸存者之一，随那位前总统同行","role":"中立","personality":"爽快、现实、对荒唐的事接受得比谁都快","hook":"她看出玩家在船上没有正式身份，于是提出用一个假的舱位登记换玩家替她办一件事，而那件事与船上那位「船长」有关。","favorHint":"按她说的去做、不追问她与那位前总统的旧事会加分；把她当普通搭便车的姑娘、或者对她的安排讨价还价会掉分","gender":"女","age":"二十多岁","race":"人类（地球人）","faction":"黄金之心号的乘员","appearance":"深色卷发披到肩下，发梢被飞船里的风吹得有些毛。贴身的银灰色连身服，腰上系一条宽腰带，脚上是软底短靴，肩上斜挂着一个小包。身量高挑，站姿从容，说话时一只手常插在腰上。她习惯在开口前先笑一下，走起路来步子大而稳。","traits":["精明","果断","不客气"],"relations":[{"name":"赞福德·毕博布鲁克斯","label":"她跟着上船的那个人，两人的旧账她从不细说"},{"name":"阿瑟·登特","label":"同是地球人的那位，她对他有一种近乎同乡的耐心"},{"name":"福特·普里弗克特","label":"船上临时结成的同伴，她信他的本事不信他的话"}],"voice":"语速快、语气直，爱用短句打断别人的长篇解释；讲到要紧处会先笑一声再说。"},{"name":"赞福德·毕博布鲁克斯","identity":"刚卸任的银河系总统，黄金之心号的偷船者与名义船长","role":"关键人物","personality":"张扬、滑头、用玩笑盖住自己也不清楚的事","hook":"他一口答应玩家推迟晚餐的请求，条件是玩家替他在乘员名册上补一个名字，而那本名册上早就有玩家的笔迹。","favorHint":"陪他胡闹、在别人质疑他的头衔时替他撑一句会加分；认真要求他负责、或者翻阅飞船的登记文件会掉分","gender":"男","age":"三十多岁","race":"混血（半地球人，另一半不祥）","faction":"黄金之心号的乘员","appearance":"深色头发带点暗红，一蓝一绿两只眼睛，脸上的神情永远像刚想到一个新主意。穿一件颜色鲜艳的开襟长袍，腰间系着毛巾与一只鼓胀的皮袋，脚上是不成对的鞋。身形高瘦，走路带弹跳感，说话时两手大幅度比划。他常把手搭在最近的人肩上。","traits":["张扬","滑头","靠不住"],"relations":[{"name":"福特·普里弗克特","label":"在酒吧里搭上的老相识，也是他这趟偷船之旅的同伙"},{"name":"崔莉恩","label":"他带在身边的人，他嘴上不当回事，行动上总先找她"},{"name":"马文","label":"船上那台不肯给他面子的机器，他从不敢真的命令它"}],"voice":"声音大、节奏跳，爱给自己加头衔；被追问细节时就笑，把话题拐到一个更好笑的方向去。"}]},{"id":"novel_enders_game","category":"novel","canon":"安德的游戏","name":"安德的游戏","icon":"🎮","tagline":"报告签着明天，署名的人还没入学","mood":"战斗学校、零重力、模拟室、考核、谎言","guidance":"【原著设定】人类曾遭到虫族两次进攻，第一次靠一位指挥官在绝境中的决断挡住，此后国际舰队一直为第三次做准备。有天赋的孩子在很小时就被送进战斗学校，住在轨道站上，训练以零重力战斗室里的战队对抗为核心，身体、战术、指挥能力同时被观察。战队有各自的名称、颜色与队徽，队长拥有极大权限，学员之间靠胜负排序。学校用成绩、排名、孤立与临时改规则的方式逼迫学员成长，教官与心理部门始终在单向玻璃后观看。除战斗学校之外，还有战术学校与指挥学校等后续阶段，最终考核在模拟室里进行，学员以为那是一场演练。国际舰队由各国凑成，地球上的政治压力也会渗进学校。【反复出现的意象】零重力战斗室里那些可以当盾牌与踏板的方形星体；学员制服上战队颜色的袖标与胸口的队徽；宿舍里那台能收发短笺与成绩的桌面终端；单向玻璃后面亮着的观察灯；模拟室里那个被锁上之后再也打不开的门。这些画面一出现，玩家就知道自己在轨道站的哪一层。【NPC 类型】把规则当刀使的教官／在排名上咬着不放的战队队长／成绩平平却最讲义气的同伴／只看数据不看人的心理评估员／在后勤通道里替人带东西的老兵。【威胁类型】规则与人。学校会把最能打的孩子放到最孤立的位置上，让全队都来针对他；而真正的威胁来自外部：虫族的第三次进攻以及舰队高层为了胜利愿意隐瞒到哪一步。这里真正的伤害来自赢的方式，而不是输本身。【奖励风格】战队编制与队长权限、训练用的战斗服与手套、零重力下的小型装备、战术学校与指挥学校的入门资格，以及一条只有自己知道的成绩记录。【不对劲的来源】学员从不知道自己在为哪一场战争受训，也不知道自己打的是演习还是实况；档案里的报告常常签着还没到的日期，署名的人还没入学，而教官会告诉你这很正常。【时间线】建议固定在主角进入战斗学校、从新兵一路升到战队队长的那一段：他还在被孤立、还没有指挥最终的模拟考核，他的姐姐与哥哥都还在地球上。不要提前启用后期的模拟考核真相、虫族母星的结局与舰队高层的摊牌。","powerStyle":"无超自然力量，靠战术、零重力与指挥权限","difficultyBias":0,"signatureItems":["战队袖标","零重力战斗手套","学员制服","激光练习枪","一份成绩排名表"],"mainQuest":"在战斗学校里活下去并往上走，弄清战队对抗背后到底是谁在打分、按什么打分。","mainQuestGoal":"在模拟室封锁的那一夜结束前，把那份签着明天日期的考核报告带出档案柜，并让玩家自己不被记为违规者","sideQuests":[{"name":"被改过的排名","desc":"找出这一周积分表上被动过手脚的那一行，并查清是谁改的","reward":"积分 150"},{"name":"战斗室的第十九次","desc":"带一支临时拼起来的队伍打赢一场规则明显不公的对抗","reward":"道具「战队袖标」"},{"name":"终端上的一封短信","desc":"替一名被孤立的学员把短笺送到他姐姐手上，全程不读内容","reward":"积分 200"},{"name":"单向玻璃的另一侧","desc":"在观察室里待满一堂课，看清每一位教官各自在记录什么","reward":"道具「观察记录副本」"}],"factions":[{"name":"战斗学校教官团","desc":"按淘汰率与胜率管理学员的一整套人，冷酷、精确，并且不解释目的","attitude":"中立"},{"name":"飞龙战队","desc":"主角一手带出来的队伍，成员早已习惯以少打多和临时变阵","attitude":"友善"},{"name":"火蜥蜴战队","desc":"纪律至上、把规则当成武器的战队，队长认定胜者才有资格讲话","attitude":"敌对"}],"npcs":[{"name":"马泽·雷汉","identity":"战斗学校的教官之一，曾在第一次虫族战争中指挥人类舰队","role":"引导者","personality":"沉默、耐心、用最少的话逼人自己想明白","hook":"他在走廊上叫住玩家，说玩家刚才那一局里做对了一件事，然后是玩家自己也不确定的那件事。","favorHint":"在训练场上不找借口、复盘时说出自己错在哪会加分；把胜负归给运气与装备、或者打听他的过去会掉分","gender":"男","age":"老年","race":"人类（地球人）","faction":"战斗学校教官团","appearance":"花白头发剪得很短，脸上沟壑很深，皮肤晒成暗褐色。深色的教官制服，袖口有一圈旧式勋章线，胸前别着一枚褪色的战队徽章。身形瘦而硬，站姿笔直，两手常背在身后。他说话时会盯着对方的眼睛，很久不眨，讲完就转身走开。","traits":["沉默","老练","要求极高"],"relations":[{"name":"安德·维京","label":"他等待多年才找到的那个人，也是他最不愿下手训练的人"},{"name":"格拉夫上校","label":"共事多年的同僚，两人对同一个人抱有不同的想法"},{"name":"邦佐·马德里","label":"他训练出来的队长之一，他清楚这个人会走到哪一步"}],"voice":"极简，常用问句代替评价；从不夸人，最多说一句「可以再来一次」。"},{"name":"安德·维京","identity":"战斗学校的学员，第三子，后来成为飞龙战队的指挥官","role":"盟友","personality":"聪明、心软、被逼到墙角时下手最狠","hook":"他把玩家当成队里唯一不因为他年纪小就替他做决定的人，于是把一份自己都看不懂的战绩记录交给玩家看。","favorHint":"在对抗里听他的调度、不替他挡下该他自己承担的责任会加分；把他当小孩照顾、或者在他面前提他哥哥会立刻掉分","gender":"男","age":"六岁到十岁的这一段时间","race":"人类（地球人）","faction":"飞龙战队","appearance":"浅金色头发细软，额前贴着，蓝灰色眼睛很大。学员制服穿在身上偏大，袖口的战队色还缝得歪斜，脚上是一双不合脚的战靴。身材在同龄人里最矮最瘦，站着时肩略收。他习惯把一只手插在口袋里，另一只手按着腰间的终端；睡前躺在床上会盯着天花板，动也不动地推演阵型。","traits":["早熟","心软","不肯认输"],"relations":[{"name":"马泽·雷汉","label":"他最信服也最怕的教官，一句话就能让他整夜不睡"},{"name":"佩特拉·阿卡尼亚","label":"最早接纳他的同伴，也是后来最复杂的对手之一"},{"name":"邦佐·马德里","label":"公开与他为难的队长，两人的冲突从一开始就停不下来"}],"voice":"说话不多，句子短，讲战术时却条理清楚；被逼急了会忽然压低声音，把话说得像结论。"},{"name":"邦佐·马德里","identity":"火蜥蜴战队的队长，战斗学校里最强的指挥官之一","role":"对手","personality":"霸道、好胜、把服从看得比聪明重要","hook":"他认定玩家是那个「小个子」身边的帮手，于是在战斗室门口当众给玩家定下一条只针对玩家的规矩。","favorHint":"在他的队伍里守纪律、输了认输会加分；当众替对手说话、或者挑战他的队长权限会立刻掉分","gender":"男","age":"十来岁","race":"人类（地球人）","faction":"火蜥蜴战队","appearance":"深色头发剃成军式短刺，眉骨很重，深色眼睛看人时带着压迫感。学员制服改得非常合身，左臂缠着火蜥蜴战队的红色队徽袖标，脚上靴子擦得发亮。个头在同龄人里偏高，肩背宽，走路时故意与人擦肩。说话时习惯把下巴往前送。","traits":["霸道","强硬","守纪律"],"relations":[{"name":"安德·维京","label":"他最看不惯也最放不下的那个新兵"},{"name":"马泽·雷汉","label":"训练过他的教官，他表面服从，心里不服"},{"name":"佩特拉·阿卡尼亚","label":"别的战队里他唯一愿意正眼看的对手"}],"voice":"语气强硬，爱用命令句与「规矩就是规矩」；被顶回来时声音会立刻提高，然后动手比说话快。"},{"name":"格拉夫上校","identity":"战斗学校的最高负责人，国际舰队派驻的指挥官","role":"潜在敌人","personality":"冷静、功利、愿意为最终结果牺牲任何一个孩子","hook":"他把玩家临时编进一支本不该有玩家的队伍，并明确表示这次安排不需要玩家理解，只需要玩家在场。","favorHint":"按他的指令行动、事后不向学员解释会加分；对安排提出质疑、或者替他手下的学员说话会掉分","gender":"男","age":"五十多岁","race":"人类（地球人）","faction":"战斗学校教官团","appearance":"灰白头发剃得很短，头顶已秃，戴一副无框眼镜。深色军装剪裁笔挺，领口扣到最上一颗，胸前只有一枚小小的舰队标记。脸型像用刀削过的平面，很少表情。他站着时总把手背在身后，说话时会从眼镜上方看人，然后低头在纸上写一行字。","traits":["冷静","算计","不近人情"],"relations":[{"name":"安德·维京","label":"他亲手挑出来又亲手孤立起来的那个人"},{"name":"马泽·雷汉","label":"他请回来的老指挥官，也是唯一敢当面反驳他的人"},{"name":"邦佐·马德里","label":"他用来制造压力的工具之一，他从不为对方的前途负责"}],"voice":"平铺直叙，像在念评估报告；做决定时从不用问句，也从不解释理由。"},{"name":"佩特拉·阿卡尼亚","identity":"战斗学校的学员，野鼠战队成员，战术上极有天赋","role":"中立","personality":"敏锐、好胜、在心里把喜欢与竞争分得清楚","hook":"她请玩家在下一场对抗里替她传一句假话，因为她想验证一个只有玩家能观察到的细节。","favorHint":"在对抗里配合她、承认她的判断准会加分；把她当小孩子哄、或者把她的战术告诉别人会掉分","gender":"女","age":"十来岁","race":"人类（地球人）","faction":"战斗学校教官团","appearance":"深色皮肤，黑发编成一条短辫贴在脑后，尾端用素色皮筋扎住。学员制服的袖口总是卷起，战队徽章别得歪一点，手指关节有训练留下的淤青。身形小巧，动作极快，站着时习惯把身体略微前倾。她说话前先歪一下头，说完立刻看别人的反应。","traits":["敏锐","好胜","讲义气"],"relations":[{"name":"安德·维京","label":"她最早接纳的同伴，也是她在排名上始终追不上的那个人"},{"name":"邦佐·马德里","label":"她愿意在对抗里正面对上的队长"},{"name":"格拉夫上校","label":"她从没直接说过话的上层，对方却清楚她每一次的排名"}],"voice":"语速快、语气直，爱用反问确认对方的想法；输了会立刻要求再来一局，不给安慰的机会。"}]},{"id":"novel_neuromancer","category":"novel","canon":"神经漫游者","name":"神经漫游者","icon":"🌧️","tagline":"雨里没有网络，只有手和记忆","mood":"霓虹、义体、冰墙、雨夜、记忆","guidance":"【原著设定】这是一个被企业取代了国家的近未来。真正的权力属于掌握技术与专利的跨国财团，以及它们养在轨道上的家族。城市里最常见的力量是钱和硬件：神经接驳插座、人工晶状体、义肢与血液里的药物改质。骇客靠一台台名叫控制台的机器把意识接进全球网络矩阵，用程序去拆开别人设下的入侵对抗程序；一旦神经受损，人还能活着，却再也进不去那片数据空间。故事早期的主要舞台是日本的千叶城，一条叫仁清街的暗街集中了酒吧、黑诊所、硬件贩子与帮派的暗账。雨的夜里霓虹把水面照成几种颜色，街上的买卖都只收现金与筹码。【反复出现的意象】屋檐下成排亮着的汉字灯牌与积水的街；吧台上一排空杯和那台谁都不去碰的点唱机；拆开的控制台外壳与绕成一团的线缆；黑诊所门上那盏始终有一格不亮的日光灯；某个人摘下墨镜时露出的那对镜片植入体。这些画面一出现，玩家就该知道自己站在千叶城。【NPC 类型】巷口兜售来历不明硬件的拆机贩子／替帮派收月钱的打手／收了钱就替你缝神经的私人外科医生／只肯逐字记录、从不表态的技术员／从不露面、只通过代理发号令的委托人。【威胁类型】企业安保与它们养的清道夫；网络里的入侵对抗程序，进去了不一定会被赶出来，而可能被反噬成一段空白；帮派之间的火并；以及不能上网时，只能用刀、用药、用身体去应付的那类人。【奖励风格】神经硬件、破解程序模块、一段可以反复播放的他人感官记录、军用镇静剂与兴奋剂，以及一个别人查不到户主的匿名账户。这些东西能用，但都会在身体上留下痕迹。【不对劲的来源】记录与记忆在这个世界里不等价。街上的每一笔监控、每一次付款、每一段感官记录都会留下痕迹，而痕迹可以被人改；玩家会发现档案里写着自己做过的事，却完全想不起来，账单上还记着玩家的名字。时间久了，最让人不安的不是谁在说谎，而是自己是不是被换过一次。【时间线】建议固定在千叶城的早期阶段：主人公的神经已被毒素毁掉、只能靠城里的外科医生按月修补，他还买不起去别处的路，主角团也还没把他捡走。地下酒吧的老板、旧日搭档与街头中介都在场。不要提前启用后期的轨道家族、自由彼岸的人工智能与那场跨国行动。","powerStyle":"网络入侵与神经硬件：控制台、冰墙、程序","difficultyBias":0,"signatureItems":["拆开的控制台外壳","一对镜片植入体","军用镇静剂针管","匿名账户密钥","一段他人的感官记录"],"mainQuest":"主线任务：在天亮之前靠一块神经硬件找到那名信使，全程不许联网。","mainQuestGoal":"在雨停之前把那块硬件交到信使手上，并让玩家自己的名字不出现在任何一份城市档案里","sideQuests":[{"name":"不亮的日光灯","desc":"陪一名受伤的街头人走到那家黑诊所，别让他死在半路","reward":"积分 150"},{"name":"点唱机里的旧曲子","desc":"找出是谁反复点同一首曲子，并弄明白他在等什么人","reward":"道具「匿名账户密钥」"},{"name":"拆下来的那一块","desc":"把一块来历不明的硬件还原成它原本的用途，全程不上网","reward":"积分 200"},{"name":"雨里的空杯","desc":"在吧台留一杯酒给不会再来的客人，并替他记下一次账","reward":"道具「一段他人的感官记录」"}],"factions":[{"name":"千叶城的街头中介","desc":"靠买卖情报与硬件过活的人，收钱办事，也把玩家记进自己的账本","attitude":"中立"},{"name":"仁清街的帮派","desc":"按街区收月钱，管秩序也管人命，最不喜欢来路不明的外乡人","attitude":"敌对"},{"name":"黑诊所的外科医生","desc":"只要付得起就替你缝神经，也清楚城里每一个缺硬件的人","attitude":"友善"}],"npcs":[{"name":"阿米蒂奇","identity":"受雇出面招人的行动负责人，来历被抹得很干净","role":"引导者","personality":"控制欲很强，说话像在念一份已经写好的简报","hook":"他把一块不属于这个年代的神经硬件交给玩家，只说天亮前必须送到，却不解释为什么不能用网络。","favorHint":"准点交货、不打听他的雇主会加分；擅自在城里联网、私自拆看硬件里的记录会立刻掉分","gender":"男","age":"四十岁上下","race":"人类（义体化）","faction":"千叶城的街头中介","appearance":"浅灰色短发剪得很短，发际线后退，额头上一道旧疤。常穿一件扣到最上面的深色长风衣，里面是拉链拉到下颌的战术衬衣，手腕上戴着一只不接任何屏幕的金属表。体格宽厚，站姿笔直，两手不是插在风衣口袋里就是背在身后。他的右眼瞳孔比左眼慢半拍，看人时像在校对什么东西。","traits":["强硬","缄默","目的明确"],"relations":[{"name":"莫莉","label":"他雇来的执行人，他只肯把任务交给她那一半"},{"name":"凯斯","label":"他手里最能用的那张牌，也是他最不放心的一个"},{"name":"朱利叶斯·迪恩","label":"他在千叶城唯一长期买情报的人"}],"voice":"句子短，语气平，从不用问句；交代完就转身走，从不重复第二遍。"},{"name":"莫莉","identity":"受雇于人的街头执行者，全身做过强化","role":"盟友","personality":"话少，出手快，对同伴的耐心比对敌人多","hook":"她看出玩家在这座城里没有退路，于是把一半的活分给玩家，条件是事成之后各走各的。","favorHint":"把说好的事做完、不追问她镜片下面是什么会加分；伸手碰她脸上的植入体、把她当打手使唤会掉分","gender":"女","age":"三十岁上下","race":"人类（高度义体化）","faction":"千叶城的街头中介","appearance":"黑色短发齐耳，剃得利落，发梢贴着颧骨。整套贴身黑衣外罩一件长外套，袖口里藏着可伸缩的刀片，指节上套着金属环。最显眼的是嵌在眼窝里的镜片，银色，反光，看不见瞳孔。身形高瘦结实，走路几乎没声音，习惯背靠着墙站着，双手环抱。","traits":["冷静","利落","有底线"],"relations":[{"name":"阿米蒂奇","label":"雇她的人，她照做但从不多问一句"},{"name":"凯斯","label":"她不得不带上路的那个骇客，也是她最愿意多等一会儿的人"},{"name":"朱利叶斯·迪恩","label":"旧日的熟人，彼此都清楚对方的价钱"}],"voice":"嗓音压得很低，一句话不超过十个字；要人跟上时只说一个字。"},{"name":"凯斯","identity":"曾经最好的网络入侵者，如今神经受损、进不去矩阵","role":"关键人物","personality":"自毁倾向明显，嘴上刻薄，心里只想着回到那片数据空间","hook":"他认得玩家手里那块硬件的接口规格，那是他自己也说不清从哪里见过的东西。","favorHint":"给他一条能重新上线的路子、替他垫一次诊所的钱会加分；当面说他再也进不去矩阵、拿他的旧事当笑话会掉分","gender":"男","age":"二十四岁上下","race":"人类（神经受损，未义体化）","faction":"千叶城的街头中介","appearance":"深色长发向后拢，前额几缕被雨水贴在皮肤上，下巴有青色的胡茬。瘦，肩窄，常穿一件领口磨白的黑色长风衣，内搭旧毛衣，右耳后有一枚已经取不出导线的接驳插座。他习惯性地用拇指摩挲那处插座，走路时肩膀微耸，坐着也像随时要站起来。","traits":["颓丧","自负","不甘"],"relations":[{"name":"莫莉","label":"带他走完这趟活的人，他嘴上不服气，行动上跟着"},{"name":"阿米蒂奇","label":"给他出路又随时能收回的人"},{"name":"拉茨","label":"唯一还肯给他倒酒、也肯听他说旧事的人"}],"voice":"语速快，爱用行话和比喻；说到网络会突然放轻声音，像在讲一个已经失去的人。"},{"name":"朱利叶斯·迪恩","identity":"千叶城的老牌情报商，做几家长寿企业的生意","role":"潜在敌人","personality":"和气、耐心、把每个人都当成一件待估价的货","hook":"他手里那份名册上有一行写着玩家的名字，日期却是三天以后。","favorHint":"按规矩付钱、用情报换情报会加分；讨价还价、试图从他这里白拿消息会掉分","gender":"男","age":"七十岁上下","race":"人类（做过延寿治疗）","faction":"千叶城的街头中介","appearance":"灰白头发梳得一丝不苟，脸皮因多次治疗绷得发亮，皱纹很浅。穿一件剪裁老派的深色西装，领口别着一枚小小的金属徽记，手指上戴着两三枚戒指。身材矮胖，坐姿端正，两只手交叠放在桌面上。他说话时会先把客人面前的杯子转正。","traits":["圆滑","谨慎","精于算计"],"relations":[{"name":"阿米蒂奇","label":"长期买他情报的老主顾，也是他最不愿得罪的一个"},{"name":"莫莉","label":"旧相识，他知道她的价钱，也知道她不好惹"},{"name":"凯斯","label":"他早年卖过消息给这个年轻人，如今只当作一件旧账"}],"voice":"语速慢，语气亲切，习惯先谈天气与茶水再谈买卖；报价时只说数字，不加形容词。"},{"name":"拉茨","identity":"仁清街那间地下酒吧的老板","role":"中立","personality":"话不多，谁都不得罪，见惯了来路不明的人","hook":"他记得玩家上一次坐的是哪个位置，而玩家自己完全不记得来过。","favorHint":"安静付钱喝酒、不把麻烦带进店里会加分；在店里动手、把帮派的人引进来会掉分","gender":"男","age":"五十岁上下","race":"人类","faction":"仁清街的帮派","appearance":"花白短发贴着头皮，脸上一道从眉骨到下颚的旧疤。穿深色衬衣配一条洗得发白的围裙，袖子挽到肘上，露出前臂上的旧烧伤。体格结实，肩膀很宽，站在吧台后面几乎不说话，只把杯子推过去，收钱时看一眼对方的脸而不是钱。","traits":["沉默","识趣","守规矩"],"relations":[{"name":"凯斯","label":"常客，也是他唯一会多倒半杯的人"},{"name":"莫莉","label":"他记得她每一次进门的时间，也从不问为什么"},{"name":"朱利叶斯·迪恩","label":"偶尔在他店里谈事的人，他从不多听一句"}],"voice":"极短，常只有一两个词；说完就转身去擦杯子，不再看人。"}]},{"id":"novel_dream_red_chamber","category":"novel","canon":"红楼梦","name":"红楼梦","icon":"🏮","tagline":"园子里的诗，比外头的规矩轻","mood":"诗社、秋日、竹林、旧帕、礼数","guidance":"【原著设定】故事发生在京城里的荣国府与宁国府。贾家是开国功臣之后，如今靠一位入宫的女儿与几门老亲维持体面，家业看着还在，底子已经在往回收。府里规矩压人：长幼、嫡庶、主仆、男女各有一条线，越线的人不必受罚，只要被议论一句就够了。大观园是为迎亲修的园子，后来让家里几个女孩与男主人公搬进去住，各人一处院落，园中有池塘、亭台、稻香村与栊翠庵，成了这些年轻人自己的一方天地。诗社就是在这园子里起的：几位姑娘加一位男主人公凑成一社，各自取雅号、定社规，轮流做东，题目由大家拟，得了好句传着看，评出高低也不真罚。园子外头的事自有外头的管法，园子里面的事由住在里面的人自己商量。【反复出现的意象】潇湘馆窗外那一丛湘妃竹与糊着碧纱的窗；石桌上摊开的诗稿、压在纸边的镇纸与半盏凉茶；一只旧帕子被人反复拿起来又放下；稻香村里晾着的稻穗与酒瓮；藕香榭水边摆开的竹案与刚蒸好的蟹。这些画面一出现，玩家就该知道自己站在大观园里。【NPC 类型】替主人传话、把话头掐掉一半的贴身丫环／总在算一份家用开销的当家人／说话不饶人却句句在理的姑娘／守着园门、谁进谁出都记得的看门婆子／来了就被人取笑的远房亲戚。【威胁类型】礼数与名声。这个世界的伤害大多不流血：一句话能被传成另一个意思，一次不合规矩的走动能被记很久。还有更实际的东西——月钱、份例、住处，谁被削了谁心里清楚，却不会说出来。【奖励风格】笔墨纸砚、诗句上的指点、旧帕子与荷包一类贴身物件、园中的酒食与点心，以及在这群人里被人当面叫一声名字。【不对劲的来源】园里说的话夜里就传遍各院，却没有一个人承认是自己传的。更让人不安的是，这些人都把玩家当成该在这里的人，只有玩家自己说不清是哪一房的远亲——而礼数在替玩家把这个问题一直压着。【时间线】建议固定在诗社刚起、菊花诗刚做完、螃蟹宴刚散的那几天：雅号已定，社规已立，姑娘们都在园中，男主人公也还住着。不要提前启用后期的抄检、逐人、娶亲与散场，也不要让后面才出场的亲戚提前登门。","powerStyle":"无超自然力量，靠诗句、礼数与分寸取胜","difficultyBias":-2,"signatureItems":["一支用旧的紫毫笔","一只绣着竹叶的旧帕","诗社的请帖笺纸","一瓶稻香村的菊花酒","一只缺了角的茶盏"],"mainQuest":"主线任务：在诗会散席之前，把那封写好的信送进潇湘馆，并带回一样东西。","mainQuestGoal":"在席上的灯被撤下之前把信交到该收的人手里、把该带回的物件带出园子，且不让任何一位长辈听见这封信的消息","sideQuests":[{"name":"纸上少一句","desc":"在一叠诗稿里找出被人改过的那一句，不声张地还给它本来的样子","reward":"积分 150"},{"name":"菊花的次序","desc":"替这一社排一个谁都挑不出毛病的次序，把差的那一份说成好的","reward":"道具「一瓶稻香村的菊花酒」"},{"name":"竹影下的回话","desc":"隔着窗子替一个不肯露面的人把话说完，不许进屋","reward":"积分 200"},{"name":"用旧的帕子","desc":"把一只旧帕子送回它原本的主人手里，全程不提上面的字","reward":"道具「一只绣着竹叶的旧帕」"}],"factions":[{"name":"荣国府的当家人","desc":"掌握月钱、份例与园中开销的人，客气有礼，也随时能把水龙头关掉","attitude":"中立"},{"name":"园中的姑娘与丫环","desc":"住在园子里、自己定规矩的一群人，把玩家当成一半自己人","attitude":"友善"},{"name":"宁国府的老亲","desc":"另一府上的长辈与清客，消息灵通，最爱把别人的事当谈资","attitude":"中立"}],"npcs":[{"name":"李纨","identity":"荣国府长房的儿媳，大观园里带着姑娘们过日子的人，诗社的社长","role":"引导者","personality":"看着温和守分，办事最有准头，一句评断压得住整桌人","hook":"她把诗社的次序簿交给玩家管，说是园子里外人少，正好让玩家做这件不惹眼的事。","favorHint":"守规矩、把差的那一份说得体面、替小辈遮一次短会加分；当众赌钱说笑、轻慢她的儿子会掉分","gender":"女","age":"三十岁上下","race":"人类（官宦人家媳妇）","faction":"园中的姑娘与丫环","appearance":"乌黑长发在脑后盘成低髻，只插一支素色银簪，不戴花。常穿藕荷或藏青的素色对襟褂子配长裙，衣料好而颜色淡，袖口只有一圈细滚边。身形端秀，坐得笔直，两手动时只动手指。她说话前习惯先看一眼对方的眼睛，手里常盘着一串念珠。","traits":["持重","厚道","有分寸"],"relations":[{"name":"贾探春","label":"诗社里最能替她拿主意的一个妹妹"},{"name":"林黛玉","label":"她最怜惜也最不敢多劝的一个"},{"name":"王熙凤","label":"同一个府里的妯娌，面上亲热，账上从不含糊"}],"voice":"语速平缓，用字干净，评论诗句时只讲好在哪里；不愿接的话就用一句家常岔开。"},{"name":"林黛玉","identity":"寄住在荣国府的表小姐，潇湘馆的主人","role":"潜在敌人","personality":"心细如发，嘴上不让人，心里比谁都软","hook":"她一眼就看出那封信不是园子里的人写的，却偏要收下，再一句一句试出玩家替谁跑腿。","favorHint":"认下她的诗、说实话、不拿她的病与身世做话头会加分；敷衍她、转述她的话给别人听会掉分","gender":"女","age":"十五六岁","race":"人类（官宦人家小姐）","faction":"园中的姑娘与丫环","appearance":"细瘦，身量未足，脸色偏白，两颊常有一点不正常的红。头发梳成简单的高髻，插一支小巧的玉簪。常穿月白或淡青的衫子配长裙，外披一件半旧的斗篷。走路轻，说话时爱用手拢一下鬓角，袖子里总揣着一方帕子，桌上放着一叠写了半截的纸。","traits":["敏慧","孤高","多心"],"relations":[{"name":"紫鹃","label":"贴身丫环，也是这园子里最懂她的人"},{"name":"贾宝玉","label":"她说不清、也放不下的那个人"},{"name":"薛宝钗","label":"她嘴上服气、心里较劲的一个人"}],"voice":"句子短，语气淡，常带一点刺；被人说中了心事就转开话题，或者干脆不答。"},{"name":"紫鹃","identity":"潇湘馆里跟着林黛玉的贴身丫环","role":"中立","personality":"沉静，护主，知道的事比说出来的多","hook":"她替主人收下信，又替主人提一个条件：要先看玩家带回的那样东西。","favorHint":"按主人的意思办事、进出潇湘馆守分寸会加分；到别的院里传话、把馆里的事说给第三个人听会掉分","gender":"女","age":"十七八岁","race":"人类（府中丫环）","faction":"园中的姑娘与丫环","appearance":"乌发在头上盘成双髻，用两根素色绸带系住，鬓边不留碎发。穿青灰或浅绿的窄袖袄配长裙，外面套一件半臂，腰间系着一条布带，上面挂着钥匙与小剪。身量中等，动作利落，说话时眼睛先看一下门口，手里常拿着灯罩或茶盘。","traits":["沉稳","忠心","有主见"],"relations":[{"name":"林黛玉","label":"她的主子，也是她最放心不下的人"},{"name":"贾宝玉","label":"常来馆里坐着的那位，她按规矩替他递话"},{"name":"李纨","label":"园中管事的那位奶奶，她回话从不越一句"}],"voice":"轻声细语，尊称一句不落，遇到不想答的话就说「等我回一声」再走开。"},{"name":"贾探春","identity":"荣国府三小姐，秋爽斋的主人，诗社的发起人之一","role":"盟友","personality":"爽利、要强、办事有章法，最烦人拿她的出身说事","hook":"她明说这封信不能经她的手，却肯替玩家把席上的时辰拖住半个钟头。","favorHint":"替她把社里的事办妥、做事讲章法会加分；提她是庶出、拿她母亲开玩笑会掉分","gender":"女","age":"十五六岁","race":"人类（官宦人家小姐）","faction":"园中的姑娘与丫环","appearance":"身量修长，眉眼开阔，头发梳成高髻，只簪一支素金钗。常穿秋香色或宝蓝的对襟长袄，腰间系一条宽绦，绦上挂着一枚小印。她站着时背挺得很直，喜欢自己研墨，写字时把袖子利落地挽起来，案头摊着账册与帖子。","traits":["爽利","自负","明理"],"relations":[{"name":"李纨","label":"诗社的社长，也是她最敬的一位嫂子"},{"name":"王熙凤","label":"她暗暗学着又暗暗不认的那位当家人"},{"name":"贾宝玉","label":"同父异母的哥哥，她拿他没办法也最护着他"}],"voice":"语速快，喜欢把话讲明白，常用「依我说」开头；被冒犯时笑容不变，话却硬起来。"},{"name":"王熙凤","identity":"荣国府里掌着实权的当家媳妇","role":"对手","personality":"精明、泼辣、把场面撑得漂亮，账目从不给人看全","hook":"她注意到园子里多了一个谁也说不清来历的人，于是先用一句玩笑把玩家钉在原地。","favorHint":"会说话、替她在长辈面前圆一次场面、办事不留尾巴会加分；拆穿她的话、越过她直接找长辈告状会掉分","gender":"女","age":"二十五六岁","race":"人类（官宦人家媳妇）","faction":"荣国府的当家人","appearance":"身量高挑，眉眼上挑，笑起来露出一侧的酒窝。穿大红或宝蓝的织金褂子配深色长裙，头上插金钗与一朵绒花，腕上戴着两三只镯子。走路很快，裙角带风，手里常攥着一条帕子或者一串账房的钥匙，说话时爱用手指点人。","traits":["泼辣","精算","爱面子"],"relations":[{"name":"贾母","label":"府里最上头的老太太，她最会讨这位的欢心"},{"name":"李纨","label":"同一个府里的妯娌，账上泾渭分明"},{"name":"贾探春","label":"她嘴上夸、心里防着的那位三小姐"}],"voice":"嗓门亮，爱说笑话，先把人逗笑再把话问到底；真动了气就一句都不说，只叫人去办。"}]},{"id":"novel_journey_west","category":"novel","canon":"西游记","name":"西游记","icon":"🔥","tagline":"借来的扇子，扇不灭自己的火","mood":"火焰、芭蕉扇、结义、旧账、西行","guidance":"【原著设定】这是一个神、仙、妖、人同处一世的世界：天上设着天庭与各位星君，西天有佛与菩萨，地上九州之间散着洞府、国邦与荒山，凡人与妖怪比邻而居，只是彼此装作不知道。修行者按年岁与道行分高下，法宝往往比本事更要紧——一根能随意长短的棍子、一把能灭火也能生风的扇子、一只装得下天的瓶子，都能决定一场争斗的胜负。取经的一行四人一马自东土出发，往西天去取经书，路遇的每一处山河都有人盘踞，通行要么靠本事，要么靠人情。妖王之间也讲结拜与旧交，谁和谁当年喝过酒、拜过把子，几十年后还会被翻出来算。【反复出现的意象】山脊上层层叠叠、怎么也灭不掉的火光与烤得发白的地面；一把插在腰间、随时能变大小的芭蕉扇；翠云山石阶尽头那道不常开的洞门与门前的石狮子；积雷山摩云洞里积着的一层厚灰与摆在案上的酒器；一块被火烤得变了色的旧铁片、连碗沿都被燎出一圈焦痕的饭食。这些画面一出现，玩家就该知道自己在火焰山脚下。【NPC 类型】受了气却不敢与妖王翻脸的当地老者／把路引当人情卖的向导／替洞主传话、看人下菜碟的小妖／凡间国里管着驿站的小吏／自称只是路过、其实在等机会的散修。他们讲人情，也讲利害。【威胁类型】地上的火与山里的妖；更麻烦的是当年结下的旧账——借东西不还、说好的事没办、替谁出过头。这里的因果记得比人清楚，欠下的迟早有人上门来要。还有上头的规矩：天兵、菩萨与土地各有一条线，越过去就要担着。【奖励风格】葫芦、金丹、药丸、绳套、扇子一类法宝或半成品法宝；一次能移山倒海但也只能用一次的神通；以及从妖怪洞里搜出来的、来路不明的凡间器物。【不对劲的来源】火焰山的火不是自然生的，是当年一笔旧账落下的余烬；本地人说得清它从哪来，却没人敢说到底该谁去还。玩家会慢慢发现，山脚下的人早就在等一个「该来的人」。【时间线】建议固定在取经一行人抵达火焰山、铁扇公主还没借出扇子的那一夜：结义旧交、红孩儿被收服的旧怨都已发生过，铁扇公主还守着自己的洞府，牛魔王还在积雷山。不要提前启用后段才登场的角色与设定。","powerStyle":"无正面战力：法术、法宝与变化之术","difficultyBias":2,"signatureItems":["一块被火燎过的铁片","一只装丹药的旧葫芦","一柄能变大小的短扇","几枚通关的文牒","一副烤得发白的行囊"],"mainQuest":"主线任务：天亮之前翻过火焰山，把一枚铁片送到山中那处洞府门口。","mainQuestGoal":"在天光压过火光之前把铁片放在洞府门前的石阶上并活着退到山那边，同时让玩家自己不被记进任何一本清算旧账的名册","sideQuests":[{"name":"山脚下的水","desc":"替一户人家把水从远处背回来，路上不许用任何法术","reward":"积分 150"},{"name":"烤焦的碗沿","desc":"在一顿被火燎过的饭里吃出主人真正想说的话","reward":"道具「一块被火燎过的铁片」"},{"name":"石狮子嘴里","desc":"从洞门口石狮子嘴里的缝隙取出一样东西，再原样放回去","reward":"积分 200"},{"name":"积着灰的酒器","desc":"把案上那套酒器擦干净，一个位置也不许挪动","reward":"道具「一只装丹药的旧葫芦」"}],"factions":[{"name":"翠云山芭蕉洞","desc":"守着一柄扇子与一桩旧怨的洞府，轻易不与外人做买卖","attitude":"潜在敌人"},{"name":"积雷山摩云洞","desc":"牛魔王新近落脚的地方，酒肉朋友多，肯讲旧交情也肯翻脸","attitude":"中立"},{"name":"火焰山下的村落","desc":"被火困了几十年的人家，谁肯借一点凉，他们就肯把路指给谁","attitude":"友善"}],"npcs":[{"name":"孙悟空","identity":"取经一行的大师兄，当年大闹天宫的齐天大圣","role":"盟友","personality":"急躁好胜，办法多，最不耐烦绕弯子","hook":"他一见玩家手里的铁片就认出来历，却先不说破，只问玩家打算怎么过山。","favorHint":"直说来意、敢跟他一起上山会加分；拿他当年被压在山下的事打趣、在他面前装神弄鬼会掉分","gender":"男","age":"年岁极大，形貌如少年","race":"猴属修行者（妖仙）","faction":"火焰山下的村落","appearance":"身量不高，臂长腿短，毛色黄褐，脸上一圈红色，眼睛极亮，转个不停。穿一件洗得发旧的黄色短直裰，腰系虎皮裙，脚蹬一双薄底靴，头上戴着金箍。走路时一纵一跳，手里常把一根两端包金的棍子转着玩。","traits":["机敏","好胜","护短"],"relations":[{"name":"铁扇公主","label":"结义兄长的妻子，也是他这趟最难开口求的人"},{"name":"牛魔王","label":"当年的结拜兄弟，如今多半要翻脸"},{"name":"猪八戒","label":"同行的师弟，一路上被他使唤也常替他解围"}],"voice":"嗓门大，语速快，爱自称老孙；说不通就换法子，从不在一件事上多耗嘴皮。"},{"name":"铁扇公主","identity":"翠云山芭蕉洞的洞主，一柄芭蕉扇的主人，人称铁扇仙","role":"潜在敌人","personality":"冷面、记仇、把话说得很绝，做事却留着余地","hook":"她隔着洞门说玩家上辈子来过这里，还欠她一件东西，账要当着面算。","favorHint":"礼数周全、把该还的东西还回来会加分；提她儿子的旧事、替取经一行讨扇子会掉分","gender":"女","age":"修行多年，形貌如三十许","race":"修行者（罗刹女）","faction":"翠云山芭蕉洞","appearance":"身量颀长，眉眼细长，皮肤很白，嘴唇偏薄，说话时几乎没有表情。头发高高挽起，插一支素色长簪，穿一袭青碧色的窄袖长裙，外罩半臂，腰间系着丝绦，绦上挂着一把小巧的扇囊。她站在洞门口时一只手总按在扇囊上，转身很快，从不背对客人。","traits":["冷硬","记仇","护子"],"relations":[{"name":"牛魔王","label":"她的丈夫，如今多半时候在别处住着"},{"name":"孙悟空","label":"她最不愿见的人，也是这桩旧账的一半"},{"name":"玉面公主","label":"积雷山那边被她恨着的人"}],"voice":"语速慢，句子短，句尾常带一丝讥讽；要先听后说，动手之前会先把条件讲完。"},{"name":"牛魔王","identity":"积雷山摩云洞的妖王，当年与孙悟空结拜的兄长","role":"对手","personality":"讲排场、重面子，翻脸之前还愿意先喝一杯","hook":"他记得玩家这张脸，却说不出在哪里见过，于是把玩家留在席上，一边喝酒一边盘问。","favorHint":"敬他一杯、称他一声兄长会加分；提他妻子的旧怨、在酒席上替取经一行说话会掉分","gender":"男","age":"修行多年，形貌如四十许","race":"修行者（牛妖）","faction":"积雷山摩云洞","appearance":"身材魁梧，肩背厚实，头上一对短角向两侧弯出，皮肤发褐，鬓角与胸口都是黑毛。穿一件赭红色宽袍，腰间束着一条镶银的宽腰带，脚上穿着包铜的靴子。他坐得像一座山，端起酒杯只用一只手，笑起来声音很沉，怒起来先把杯子搁下才站起来。","traits":["豪横","讲交情","易翻脸"],"relations":[{"name":"铁扇公主","label":"结发之妻，他嘴上敷衍，心里清楚自己理亏"},{"name":"孙悟空","label":"旧日结拜的兄弟，如今两边都放不下脸面"},{"name":"猪八戒","label":"打过几回照面的对手，他嘴上瞧不上，动手时并不轻视"}],"voice":"声如洪钟，爱称人兄弟，先说吃喝再说正事；被戳到痛处就把酒杯一放，话立刻变短。"},{"name":"猪八戒","identity":"取经一行的二师兄，原为天河水军统领，错投猪胎","role":"中立","personality":"贪吃怕苦，嘴上抱怨，真要出力时也不含糊","hook":"他盯上了玩家行囊里的干粮，愿意用一条翻山的近路来换。","favorHint":"分他一口吃的、当面夸他有力气会加分；笑他是猪、在师父面前提他偷懒会掉分","gender":"男","age":"年岁极大，形貌如中年","race":"猪属修行者（妖身）","faction":"火焰山下的村落","appearance":"体形胖大，肚子圆挺，脸是猪相，两只耳朵耷下来，鼻子长而上翻。穿一件敞着领口的黑色短衣，腰上胡乱系着布带，肩上扛着一柄九齿钉耙。走路摇摇晃晃，说话时先摸肚子，坐下就想找地方靠，睡觉时留着半边耳朵听动静。","traits":["贪吃","滑头","关键时刻靠得住"],"relations":[{"name":"孙悟空","label":"大师兄，他嘴上躲着走，出了事第一个喊"},{"name":"牛魔王","label":"交过手的老对头，见面先比嗓门"},{"name":"沙悟净","label":"同行的师弟，他最爱使唤也最信得过的一个"}],"voice":"一边抱怨一边干活，句子长而拖，爱讲吃食和辛苦；被叫破了心思就立刻改口辩解。"},{"name":"沙悟净","identity":"取经一行的三师弟，原为天庭卷帘的侍从，流落流沙河","role":"引导者","personality":"沉默、稳当、不抢功，把队伍里的琐事都自己扛着","hook":"他趁夜把火焰山下这几十年的事一件件讲给玩家听，末了只说「这里的人都在等一个人」。","favorHint":"替队伍挑一次担子、不抢他的话会加分；催他快走、嫌他话多会掉分","gender":"男","age":"年岁极大，形貌如壮年","race":"修行者（原为天庭神将）","faction":"火焰山下的村落","appearance":"身量高大，肩宽背阔，脸色偏青，络腮胡修得很短，颈上挂着一串大颗的念珠。穿一件青不青黄不黄的直裰，腰间系一条旧布带，把一根降妖宝杖横在肩上。步子很沉，走路不急，说话前先停一下，站着时习惯把重心放在后脚。","traits":["沉稳","耐劳","少言"],"relations":[{"name":"孙悟空","label":"大师兄，他从不争，只在大师兄急躁时补一句"},{"name":"猪八戒","label":"二师兄，他嘴上让着，实际总在收拾残局"},{"name":"铁扇公主","label":"他听本地人讲过这桩旧账，也清楚谁都还没还"}],"voice":"声音低，句子短，爱用「依我看」开头；被追问时就重复一遍自己说过的话，不再加一句。"}]},{"id":"novel_flowers_in_mirror","category":"novel","canon":"镜花缘","name":"镜花缘","icon":"🪞","tagline":"湖面照出的，都是对岸的人","mood":"女儿国、临湖、礼数、倒影、行船","guidance":"【原著设定】这是一部写海外诸国与才女的书。读书人唐敖仕途失意后随经商的妻兄林之洋、老舵工多九公出海，沿途经过几十个风俗各异的国度：君子国的人争着让利，两面国的人前后各有一张脸，女儿国则以女子为尊，男子在家绣花、缠足、穿耳，被当作妇道人家养在内里。女儿国的官制、礼数与中原一样齐全，只是坐在位上的是女子；国主的旨意就是规矩，宫里除了官员，还养着一批穿戴讲究的宫娥。当地另有不重金钱、只重礼数的风气，行人见面先论上下，再谈事情，谁在门口站错了位置都可能被记上一笔。海外诸国的语、字多有不同，全靠随行的老舵工与当地通事替人搭桥。【反复出现的意象】宫城正门前那一排石阶与两侧垂下的红纱；临湖的云母窗，推开时能看见一整片水；码头上并排停着的货船与船帮上晾着的彩衣；宫里送出来的一桌合欢宴与摆在案上的绣鞋；唐敖背着人从高墙上越过几层院落时，脚下那片微月照着的瓦。这些画面一出现，玩家就该知道自己在女儿国的宫城外。【NPC 类型】管着门禁、逐条记名的宫门吏／替你与本地人搭话的通事／端着赏赐出来宣旨的宫娥／在市场上专门盯着外乡人看热闹的本地妇人／在船上守夜、什么话都听进耳朵的老水手。他们讲体面，也讲章程。【威胁类型】规矩本身。这里的礼数与官府的力气合在一起，违一句就是违旨，不必审判就能被留下；再有就是财与色——本地的风气里，看上谁便可以把谁留下，外地来的人最容易在这一条上栽。夜里还有水上的人，看准了靠岸的船。【奖励风格】当地出产的绫罗、花露、香水与脂粉；一桌合欢宴、一支赏赐的簪子；以及通事手写的一纸通行凭据，凭它能进出几处宫门。这些东西在别处没用，在这里却比刀好使。【不对劲的来源】湖里照出来的人，全都来自对岸。你在湖边站久了，会觉得水里那些人的穿戴、音声都和你身后的人对不上；可你一回头，身后一个人也没有。本地的老人说这湖认人不认影，谁被照到了，就算来过了。【时间线】建议固定在唐敖一行人进入女儿国、林之洋被留在宫里、诸般礼数已经压下来的那几天：世子还在宫中，多九公守在船上，宫门的规矩一条都没松。不要提前启用后段才登场的角色与设定。","powerStyle":"无超自然力量，靠礼数、章程与人情周旋","difficultyBias":-1,"signatureItems":["一双绣着花的软底鞋","一纸通事写的凭据","一支宫里赏下的簪子","一小瓶异国花露","一枚刻着国号的铜钱"],"mainQuest":"主线任务：在宫城正门前站满十二小时，眼睛不许离开湖面。","mainQuestGoal":"站满整整十二个小时、一次也不把视线从湖面移开，并在钟声落定前拿回湖面照给玩家的那件东西","sideQuests":[{"name":"门吏的名册","desc":"让宫门吏在名册上把一处写错的名字改回来，两处都不得罪","reward":"积分 150"},{"name":"送错门的合欢宴","desc":"把宫里送出的一桌宴席送到该去的地方，途中一样不许少","reward":"道具「一小瓶异国花露」"},{"name":"对岸来的货","desc":"替通事认出一船货的来处，全程不许问船主","reward":"积分 200"},{"name":"夜里守船","desc":"在水上守一整夜，看清靠近船边的到底是什么","reward":"道具「一纸通事写的凭据」"}],"factions":[{"name":"女儿国宫中","desc":"女子掌权的内廷与宫娥，章程极细，赏罚都从这一处出","attitude":"中立"},{"name":"临湖的商船与通事","desc":"往来诸国做生意的人，肯替你搭话，也把每句话都记住","attitude":"友善"},{"name":"附近岛国的官船","desc":"打着巡海的旗号在各处水域收例钱，看人下菜","attitude":"敌对"}],"npcs":[{"name":"唐敖","identity":"中原来的读书人，随妻兄一同出海，见闻最多也最敢动手","role":"引导者","personality":"洒脱，好奇，遇事先想弄明白再想脱身","hook":"他在湖边的石阶上站了很久，最后把手上那枚刻着国号的铜钱塞给玩家，说这湖只认站在这里的人。","favorHint":"陪他一起看湖、把见闻如实讲出来会加分；笑他仕途失意、在他面前轻慢女儿国的风俗会掉分","gender":"男","age":"四十岁上下","race":"人类（中原读书人）","faction":"临湖的商船与通事","appearance":"中等身量，偏瘦，蓄着短须，眉骨高。头戴一顶半旧的方巾，穿一袭靛青长衫，外罩无袖的褂子，腰间系着布带，挂一枚小玉坠。他习惯负手而立，看远处时微微眯眼，说话前先捻一下胡须，脚下常不自觉地来回踱两步。","traits":["好奇","洒脱","有担当"],"relations":[{"name":"林之洋","label":"妻兄，也是他这趟出海最要照应的人"},{"name":"多九公","label":"同船的老舵工，沿途的风土都靠他讲"},{"name":"阴若花","label":"他连夜越墙带出来的那位世子"}],"voice":"慢条斯理，喜欢用比喻讲道理，常把「依我看」挂在嘴上；急起来反而压低声音。"},{"name":"林之洋","identity":"中原来的行商，唐敖的妻兄，如今被留在女儿国的宫里","role":"关键人物","personality":"嘴甜活络，最会跟人打交道，困住了也不肯认输","hook":"他托人从宫里递出一句口信，要玩家替他确认湖面上照出来的人里有没有他。","favorHint":"替他往宫里递话、按本地规矩替他周旋会加分；拿他此刻的处境说笑、把他当货物谈论会掉分","gender":"男","age":"四十岁上下","race":"人类（中原行商）","faction":"临湖的商船与通事","appearance":"身量不高，肩背圆厚，脸皮白净，笑起来眼睛眯成一条缝。因为处在宫里，他已被换上一身女装：藕色窄袖长袄、绣花长裙，头发梳成女髻，插着一支不算贵重的簪子，脚上是一双软底绣鞋。他站着时总先把袖子理好，说话时手在袖子里动，眼神四处找可以搭话的人。","traits":["圆滑","能忍","恋家"],"relations":[{"name":"唐敖","label":"妹夫，也是能把他从墙里带出去的人"},{"name":"阴若花","label":"宫里那位替他递过话的世子"},{"name":"多九公","label":"守在船上的老舵工，他所有的口信都往那条船上送"}],"voice":"语速快，爱打圆场，凡事都能说成好事；怕的时候嘴上更热闹，句子一串接一串。"},{"name":"多九公","identity":"随船的老舵工，走过几十个海外国度","role":"盟友","personality":"老成，话直，最看不惯不懂装懂的人","hook":"他年轻时在这片湖上守过一夜，说那一夜见过的东西他到现在也没敢写进本子里。","favorHint":"听他讲完旧事、按他指的航线行事会加分；自作聪明改他的水路、笑他年老会掉分","gender":"男","age":"七十岁上下","race":"人类（老舵工）","faction":"临湖的商船与通事","appearance":"矮壮，背有点驼，皮肤被海风吹成深褐色，满脸深刻的皱纹。头戴一顶旧毡帽，穿灰褐色的短褐与宽脚裤，腰间系一条粗布带，挂着烟袋与一把小刀，脚上是草鞋。他手上全是老茧，站着时两手抱在胸前，说话爱用手指点着船板的某一处。","traits":["老练","直言","认死理"],"relations":[{"name":"唐敖","label":"东家，也是他愿意多讲几句的那个读书人"},{"name":"林之洋","label":"船上的东家之一，他嘴上抱怨，事上从不含糊"},{"name":"阴若花","label":"他一见就知道来处不简单的孩子"}],"voice":"声音沙哑，句子短，爱用「我走过的路」开头；遇到不信的人就闭嘴，只把船撑开。"},{"name":"阴若花","identity":"女儿国的世子，宫中最受看重的一位少年","role":"中立","personality":"有礼数、有心事，懂得看人脸色却不爱说破","hook":"他隔着湖看了玩家一整夜，最后说自己梦见玩家站在这里，手里少了一件东西。","favorHint":"按宫中礼数回话、不打听宫中之事会加分；在旁人面前叫破他的身份、拿他当孩子哄会掉分","gender":"男","age":"十四五岁","race":"人类（女儿国世子）","faction":"女儿国宫中","appearance":"身量未足，肩窄腰细，面孔清秀，眉毛细长，皮肤很白。穿女儿国宫中的礼服：云锦长袄配垂到脚面的长裙，腰间系着宽绦，绦上挂着一枚小小的玉佩，头上戴着嵌珠的小冠。他站在门边时两手交叠在身前，说话前先垂一下眼睛，脚步很轻，转身时裙角不带一点声。","traits":["端方","内秀","隐忍"],"relations":[{"name":"唐敖","label":"替他从宫里脱身的那位读书人"},{"name":"林之洋","label":"他认作父亲的那位中原行商"},{"name":"多九公","label":"船上那位老舵工，他最爱听他讲海外的国"}],"voice":"声音不高，用词讲究，回话常留半句；被逼问时就以一句宫中的套话推过去。"},{"name":"水仙庵的强盗","identity":"在水上打劫过往商船的匪众头目","role":"潜在敌人","personality":"粗鲁，贪财，认准了船就盯到天亮","hook":"他认定玩家的船上有宫里漏出来的好东西，于是用一句「借个火」靠上船舷。","favorHint":"给他一点不值钱的东西打发、把话头扔给通事会加分；当面叫破他的行当、亮出宫中的凭据会掉分","gender":"男","age":"三十多岁","race":"人类（水上匪众）","faction":"附近岛国的官船","appearance":"身材粗壮，皮肤晒得发黑，眉毛压得很低，脸上有一道横过鼻梁的旧伤。头上裹着一块深色头巾，穿一件敞着领口的短褂，腰里系着绳带，插着一把短刀，裤脚挽到小腿，赤脚站在船板上。他上船时先蹲下，再慢慢起身，一只手始终没离开刀柄。","traits":["贪婪","粗野","谨慎"],"relations":[{"name":"多九公","label":"十几年前被他抢过一次船的老舵工"},{"name":"林之洋","label":"他盯上的那只货箱的主人"},{"name":"唐敖","label":"他两次想动手都被挡回去的那个读书人"}],"voice":"咧嘴笑着说话，句子里混着地方口音；谈不拢就先往船边靠一步，再讲一次价钱。"}]},{"id":"novel_strange_tales","category":"novel","canon":"聊斋志异","name":"聊斋志异","icon":"🕯️","tagline":"满桌都知道，只有你说不出口","mood":"雪夜、旧宅、灯烛、狐鬼、人情","guidance":"【原著设定】这是一个狐、鬼、花木之精与人同住一世的世界，故事多发生在荒宅、旅店、书斋与坟地旁的小村。这些异类大多不凶：她们从墙上下来，与书生喝酒谈诗，替他操持家务，甚至替他养大孩子；反过来，害人的反倒是读书人自己的贪念、官府的贪墨与旧家族的规矩。分辨人与非人从来不是靠眼睛，宅子里的老仆、道观里的道士、游方的剑客都能一眼看出，只是多半不肯说。人和异类之间的往来有它自己的规矩：不问来处，不追问名字，不点破，也不许在天亮之前替对方做决定。天快亮时鸡一叫，该走的就走了，留下的东西往往只是一件旧衣裳、一地的花瓣，或者一封信。【反复出现的意象】糊着厚纸的窗与窗外不断落下的雪；堂屋里一只烧得发红的铜火盆与围着它摆的一圈矮凳；廊下那盏被人提着穿过天井的纸灯；从门缝里看出去，院里几行脚印走到一半就没了；客人进门先送上一件狐皮裘衣，自己却一直穿着一件单薄的衣裳。这些画面一出现，玩家就该知道自己在旧宅里。【NPC 类型】替主人待客、一句多余的话都不说的老仆／提着酒壶劝人再喝一杯的座上客／自称路过借宿、天亮前一定要走的行脚人／在门外站了整夜也没进来的邻家娘子／被请来做法事却只在院里抽烟的道士。他们讲情义，也讲忌讳。【威胁类型】认错人。跟你说话的可能是活人，可能是死者，也可能是一棵树；真正的危险不是被吃掉，而是被留下——留在那座宅子里，天亮之后别人来问起你，宅子里的人会说你本来就在这里住着。此外还有人心：在这个世界里，比鬼更难看透的是同席的笑容。【奖励风格】符纸、剑囊、药丸、香囊一类辟邪物件，一件狐皮裘衣或一支不会凋谢的花；再就是一段别人愿意替你说的话。能力偏向看破幻形、夜里分辨脚印与声音。【不对劲的来源】满桌人都知道谁不是人，却没人肯先把那句话说出来。礼数与忌讳比阳气更能压住场面，只要没人点名，谁都可以装作不知道。【时间线】建议固定在志怪流行的那个年代，落在一座已经没有主人的旧宅里：这栋宅子的旧主人早已不在，屋子却照旧摆着待客的陈设，邻村的道士与游方剑客都在近处。不要提前启用后期才登场的角色与设定，也不要让书中别处的故事在这座宅子里提前发生。","powerStyle":"无正面战斗，靠看破、忌讳与一句该说的话","difficultyBias":-1,"signatureItems":["一叠写坏的符纸","一只绣着花的香囊","一盏糊纸的手提灯","一件狐皮裘衣","一支插在瓶里的干花"],"mainQuest":"主线任务：在鸡叫之前，从这一桌客人里认出唯一真的人，并把他带出门。","mainQuestGoal":"在天亮前把人带出宅门、让他自己迈过门槛，全程没有点破任何一位客人的身份","sideQuests":[{"name":"火盆边少一个座","desc":"给最后进门的客人腾出位置，又不能让原来的客人觉得自己被挤走","reward":"积分 150"},{"name":"行一个酒令","desc":"在席上接住一个酒令，答对而不答全，也不许问是谁在出题","reward":"道具「一只绣着花的香囊」"},{"name":"廊下的脚印","desc":"看清院子里那几行脚印走到哪里断了，回来一个字也不提","reward":"积分 200"},{"name":"不许回头","desc":"有人送你出门，走到院门口以前不许回头，也不许数身后的脚步","reward":"道具「一盏糊纸的手提灯」"}],"factions":[{"name":"旧宅里的客人","desc":"这一桌雪夜里的座上客，礼数周全，谁都不肯先说出那件事","attitude":"中立"},{"name":"邻村的人家","desc":"知道这宅子的旧事，只肯在白天说话，入夜就闩门","attitude":"友善"},{"name":"城隍庙的道士","desc":"会画符也会看人，出手要价，且从不把话说满","attitude":"中立"}],"npcs":[{"name":"燕赤霞","identity":"游方的剑客，身边带着一只装剑的皮囊","role":"盟友","personality":"豪爽直率，喝得多说得少，看人一眼就知道底细","hook":"他把自己那只剑囊挂在玩家手边的柱子上，说只要不动它，这一夜就不会有人动手。","favorHint":"替他挡一次酒、把实话说在明处会加分；在他面前试探别人身份、动他的剑囊会掉分","gender":"男","age":"三十多岁","race":"人类（剑客）","faction":"旧宅里的客人","appearance":"身材高大，肩背宽厚，胡须浓密，眉毛又黑又长。戴一顶旧毡笠，穿一件洗得发白的青布短袍，腰里系着宽布带，脚上是厚底靴。最显眼的是随身那只半旧的皮囊，鼓鼓的，挂在肩上。他喝酒用大碗，坐时把一条腿架在凳上，说话前先笑一声。","traits":["豪爽","磊落","沉得住"],"relations":[{"name":"宁采臣","label":"他早年在一座荒寺里结识的书生"},{"name":"陆判","label":"他在席上唯一不肯与之对饮的一位"},{"name":"婴宁","label":"他看出一半来历、始终没说破的那位女客"}],"voice":"声音洪亮，句子直来直去，爱用「罢了」收尾；认真起来一句废话都没有。"},{"name":"婴宁","identity":"席上最爱笑的那位女客，来历说不清","role":"关键人物","personality":"天真爱笑，说话像不懂事，其实每一句都记着","hook":"她把一枝花插在玩家袖口，说只要还戴着就不用怕黑，随后又笑着要玩家别问她的姓。","favorHint":"陪她笑、依她的规矩不追问来处会加分；追问她住在哪里、当众说她不似常人会掉分","gender":"女","age":"十六七岁","race":"狐女（由鬼母抚养成人）","faction":"旧宅里的客人","appearance":"身量纤细，走路带一点跳，笑起来眼睛弯成一条线。头发梳成简单的双髻，鬓边总簪着一枝花，花瓣压得有点蔫。穿一件浅红夹绿的窄袖袄裙，外面披一件薄披风，手里常捏着一枝没开的花。她坐下时坐不满半张凳子，脚尖一直点着地。","traits":["爱笑","机敏","不设防"],"relations":[{"name":"王子服","label":"她跟着回门的那位书生"},{"name":"绛雪","label":"同席里唯一让她收起笑容的一位"},{"name":"燕赤霞","label":"她有点怕他，却总坐在离他近的位置"}],"voice":"语调轻快，句子短而跳，常先笑出声再接话；被问到根上就笑着岔开，或干脆装作没听见。"},{"name":"陆判","identity":"阴间掌文册的判官，席上最不受待见的一位客人","role":"潜在敌人","personality":"外貌粗陋，性子却直，敬他一杯酒就肯替人办事","hook":"他翻开随身那本册子，指着上头一行说这屋里该走的和不该走的都写乱了。","favorHint":"敬他酒、不嫌他相貌、不问册子上写了什么会加分；取笑他的长相、抢他的册子看会掉分","gender":"男","age":"说不清","race":"阴间判官（神职）","faction":"旧宅里的客人","appearance":"身形高大，比在座的人高出一个头，脸色发赤，胡子又硬又乱，眼睛深陷但很亮。穿一件深绿的官袍，袍面绣着看不清的纹样，腰带是黑色的宽绦，头上戴着一顶软翅的旧官帽。他左手边总摆着一本厚厚的册子，翻页只用一根手指。","traits":["刚直","好酒","不近人情"],"relations":[{"name":"婴宁","label":"他一看册子就知道来处的女客，只是不肯说"},{"name":"燕赤霞","label":"彼此都看得出对方是做什么的，因此很少说话"},{"name":"绛雪","label":"他翻到某一页时会停一下的那位女客"}],"voice":"声音粗哑，说话像在念公文，爱用「错不了」三个字；被人顶撞就把册子一合。"},{"name":"绛雪","identity":"席上那位穿深红衣、始终少言的女客，其实是一株耐冬花木之精","role":"对手","personality":"寡言知礼，替人着想，被说破时就立刻冷下来","hook":"她替玩家斟满一杯酒，说这一杯要留到鸡叫以后再喝，否则就回不了头。","favorHint":"守时、按她的提醒不提前碰那杯酒会加分；在天亮前替她做决定、把她的名字说出来会掉分","gender":"女","age":"形貌二十岁上下","race":"花木之精（耐冬）","faction":"旧宅里的客人","appearance":"身量中等偏高，站得很直，脸色极白，唇色偏深。头发挽成低髻，只用一根木簪别住，没有一件首饰。穿一袭深红近褐的长袄与同色长裙，袖口绣着几朵素花，那花的样子和院里的树是一个颜色。她斟酒时手腕很稳，眼睛只看杯口，不看人。","traits":["沉静","守礼","有旧情"],"relations":[{"name":"婴宁","label":"她愿意照看、却不敢靠近的一位女客"},{"name":"陆判","label":"他册子上写着她的那一页，她自己也知道"},{"name":"王子服","label":"席上唯一让她多说两句话的那位书生"}],"voice":"声音很轻，用词讲究，一句话只讲一件事；被问到不该问的就停下，等别人换话题。"},{"name":"王子服","identity":"上元节出游的书生，婴宁后来跟着他回门","role":"中立","personality":"憨直，做事一根筋，认定的事就守着不放","hook":"他悄悄问玩家这屋里哪一位是真人，说他自己只认得身边那一个。","favorHint":"老实回答他能答的问题、替他看好身边那位女客会加分；拿他的痴心取笑、把他往门外引会掉分","gender":"男","age":"二十岁上下","race":"人类（书生）","faction":"旧宅里的客人","appearance":"中等身量，脸型偏圆，皮肤白，眼神直，看人时不躲。戴一顶旧方巾，穿一袭月白长衫，外罩青灰的褂子，腰间系着布带，挂一只旧香囊。他坐得规整，两手放在膝上，说话前先欠一下身，笑起来有点呆气。","traits":["憨直","专一","缺心眼"],"relations":[{"name":"婴宁","label":"他在上元节遇见的那个爱笑的女子"},{"name":"绛雪","label":"席上规规矩矩替他添过一次酒的女客"},{"name":"燕赤霞","label":"他想结交又不敢多说话的那位剑客"}],"voice":"语速慢，用词文气，常把心里想的直接说出来；被笑的时候先愣一下，再自己跟着笑。"}]},{"id":"novel_cthulhu_mythos","category":"novel","canon":"克苏鲁神话","name":"克苏鲁神话","icon":"🐙","tagline":"潮水退了，说法也一起退了","mood":"海雾、旧港口、血统、涨潮、改口","guidance":"【原著设定】这是以新英格兰为舞台的一组相互呼应的故事：马萨诸塞州的阿卡姆城、城里的米斯卡托尼克大学、山中的金斯波特、沿海的印斯茅斯与更北的荒村，构成一片表面平常、底下有旧事的地带。大学里的学者靠图书馆、标本室与科考队处理那些说不清的发现；港口与小村镇则靠家族、船队和教会维系，几代人的婚姻把人与海里的东西连在一起，这种事本地人知道，却只在酒后说。世界的真相是：人类的地位并不高，宇宙里存在着远比人古老、对人既无善意也无恶意的存在，只要靠近就会让人失去判断力；因此大多数人选择不看、不记、不说。关于深海、梦境与血统的传说散在航海日志、教堂记录和老人的口述里，能被拼出来的只有一部分。【反复出现的意象】港口那盏会绕着一片海雾转圈的灯；退潮后露出来的黑色木桩与缠在桩上的水草；老教堂墙上一块刻错年份的铭牌；旅馆桌上摊开的一本记满姓名的花名册与水渍；清晨集市上所有鱼摊同时收声的那一瞬间。这些画面一出现，玩家就该知道自己站在阿卡姆港。【NPC 类型】酒馆里喝到第三杯才开口的老水手／大学里管档案、不许人抄录的管理员／港口管事者，做的是记录船与人头的生意／外地来收鱼的船主／守着祖宅、把家谱锁在箱子里的老妇。他们讲话都留半句。【威胁类型】海里的东西与跟着它上来的梦；以及更近的危险——血统。这片海岸上有些家族的身份经不起查，一旦被认出来，人就会被自己人当外人处置。还有失忆，见过某些东西的人不会发疯，只会记不起来，并因此被所有人当成说谎的人。【奖励风格】航海日志、船钟、老照片、教堂名册一类查得到的实物证据；一枚家族纹章或一枚旧钥匙；以及一份别人不肯给的可信口供。能力偏向辨认真伪、夜间记忆与抵抗梦境的侵蚀。【不对劲的来源】码头上所有人会在同一时刻改口，说他从没在夜里上过工，而理由、语气甚至用词都一模一样。那不是串通，更像是一件早就写好的事到了该发生的时候。【时间线】建议固定在二十世纪前期的新英格兰：阿卡姆与米斯卡托尼克大学还在正常运转，印斯茅斯的旧事尚未被人揭出来，海上的失踪还很常见。不要提前启用后期才登场的角色与设定，也不要让深海的住民提前浮上水面。","powerStyle":"无正面对抗，靠证据、口供与撑住理智","difficultyBias":1,"signatureItems":["一本被水泡过的航海日志","一枚家族纹章","一把旧教堂的钥匙","一张模糊的码头合影","半瓶廉价的朗姆酒"],"mainQuest":"主线任务：在天亮之前找到那名失踪的码头工，把他送回住处。","mainQuestGoal":"在天亮与涨潮之前把失踪者交回他自己的门槛里，并让玩家带回去的那份记录与港口名册对得上","sideQuests":[{"name":"今夜的名册","desc":"把当夜上工的名册抄一份下来，抄的过程中不许问任何人","reward":"积分 150"},{"name":"第三杯酒","desc":"陪一位老水手喝完三杯，让他把不该说的那半句说完","reward":"道具「半瓶廉价的朗姆酒」"},{"name":"退潮的木桩","desc":"在退潮时看清木桩上缠着的东西，并把它画下来交给懂行的人","reward":"积分 200"},{"name":"墙上的年份","desc":"找出教堂铭牌上那个刻错的年份，并弄明白是给谁改的","reward":"道具「一把旧教堂的钥匙」"}],"factions":[{"name":"米斯卡托尼克大学","desc":"城里的学者与档案机构，肯听人说话，但要求证据","attitude":"友善"},{"name":"港口的码头管事","desc":"掌握上工名册与船只进出的人，只认钱与本地的规矩","attitude":"中立"},{"name":"沿海的旧家族","desc":"几代人与海上的生意紧紧相连，最不希望自己的根被翻出来","attitude":"敌对"}],"npcs":[{"name":"亨利·阿米蒂奇","identity":"米斯卡托尼克大学的图书馆长与教授","role":"引导者","personality":"严谨、克制，把恐惧当成一件需要核对的事","hook":"他要玩家带回的不是人，而是一份能核对的名册；他说只要记录对得上，人自然会回来。","favorHint":"如实回报、把实物证据交给他保管会加分；夸大见闻、把档案上的东西抄出去给外人会掉分","gender":"男","age":"五十多岁","race":"人类（学者）","faction":"米斯卡托尼克大学","appearance":"身材清瘦，肩有点塌，头发花白，前额很高，鼻梁上架着一副金边圆眼镜。穿一套深灰色的三件式西装，马甲扣得整齐，怀表链横在腹前，皮鞋擦得发亮。他坐着时背很直，说话时双手交叠在桌面上，习惯用食指敲两下文件再抬眼。","traits":["严谨","镇定","有担当"],"relations":[{"name":"弗朗西斯·摩根","label":"一同处理过那桩远航记录的同事"},{"name":"扎多克·艾伦","label":"他听过这老人的名字，却始终没能把话问全"},{"name":"古斯塔夫·约翰森","label":"他手上那份航海证词的原作者"}],"voice":"语速匀，用词精确，先给结论再给依据；被打断就从头讲一遍，不加情绪。"},{"name":"扎多克·艾伦","identity":"印斯茅斯的老住户，当年从镇上的教堂里跑出来的那个人","role":"关键人物","personality":"话多、怕事、喝够了才肯开口，说完了又后悔","hook":"他一眼认出玩家不是本地人，于是先讨一口酒，再说出「今夜上工的人里头，有一个不该在」。","favorHint":"请他喝酒、替他挡住追问的人会加分；把他说的话转述给港口的人、催他快说会掉分","gender":"男","age":"七十多岁","race":"人类（印斯茅斯血统）","faction":"沿海的旧家族","appearance":"干瘦，背驼，脖子上的皮肤松得打褶，眼白发黄，眼神总往两边瞟。头戴一顶磨破的旧呢帽，穿一件过大的深色外套，里面是洗得发灰的衬衣，裤脚沾着干了的泥，脚上套着一双开口的旧皮鞋。他坐下时两只手不停搓，说话前会先往门口看一眼。","traits":["多话","胆怯","心里有数"],"relations":[{"name":"亨利·阿米蒂奇","label":"他听说过的大学里的人，从不敢上门"},{"name":"巴纳巴斯·马什","label":"他从小就知道要绕着走的那一家"},{"name":"古斯塔夫·约翰森","label":"他见过一次、之后再也不提的外来船长"}],"voice":"声音又低又急，句子拖着尾巴，爱重复同一个词；问到关键处就停下来讨酒喝。"},{"name":"巴纳巴斯·马什","identity":"印斯茅斯马什家族的当家，做渔业与船运生意","role":"潜在敌人","personality":"体面、耐心，用生意人的口气谈最不该谈的事","hook":"他愿意出钱让玩家忘掉今夜的名册，并提醒玩家「这镇上的人都很会记事情」。","favorHint":"按他的规矩办事、不追问家族的事会加分；翻查他家族的旧账、把名册交给大学会立刻掉分","gender":"男","age":"六十岁上下","race":"人类（印斯茅斯旧家族血统）","faction":"沿海的旧家族","appearance":"身材偏高偏瘦，面孔长，眼睛外凸，眼睑不太会闭合，脖子两侧有几道浅浅的褶。穿一身深色呢料西装，领结打得一丝不苟，手上戴着一枚刻着纹样的金戒指。他站在码头上像在清点货物，说话时双手背在身后，很少眨眼。","traits":["体面","阴冷","算计"],"relations":[{"name":"扎多克·艾伦","label":"他视为镇上污点、却一直没处理掉的老人"},{"name":"港口的码头管事","label":"替他管着上工名册与船期的自己人"},{"name":"亨利·阿米蒂奇","label":"他最不愿让之靠近海边的那位学者"}],"voice":"声音平和，礼貌周全，句子完整得像念账单；说完会笑一下，等对方先动。"},{"name":"弗朗西斯·摩根","identity":"米斯卡托尼克大学的工程学教授，参加过南太平洋的科考","role":"盟友","personality":"务实，不信传说，只信仪器与尺寸","hook":"他量过码头的水深，发现今夜的水位比表上高出太多，而且没人肯承认这件事。","favorHint":"尊重数据、陪他重测一次水位会加分；拿「海里的东西」当解释、嘲笑他的谨慎会掉分","gender":"男","age":"四十多岁","race":"人类（学者）","faction":"米斯卡托尼克大学","appearance":"结实，肩膀宽，皮肤因长期在户外而发红，短发里夹着灰白，下巴刮得很干净。穿粗呢外套配马甲，裤脚塞进长靴，随身带着卷尺与本子，胸前口袋里插着两支铅笔。他习惯一边说话一边用铅笔敲本子，走路时步子很大。","traits":["务实","固执","不信邪"],"relations":[{"name":"亨利·阿米蒂奇","label":"同校的同事，他信对方的判断但不信对方的结论"},{"name":"古斯塔夫·约翰森","label":"他反复研究过那艘船留下的记录"},{"name":"巴纳巴斯·马什","label":"他怀疑却抓不到证据的那位生意人"}],"voice":"直白，喜欢报数字，常用「按我的测量」开头；被激怒就把本子往桌上一拍。"},{"name":"古斯塔夫·约翰森","identity":"一艘三桅船上的二副，后来成了那条船唯一活着回来的人","role":"中立","personality":"寡言，手上有旧伤，说到海上的事就沉默","hook":"他在阿卡姆港补给的这几天一直不肯上岸睡觉，却愿意跟玩家换一夜守船。","favorHint":"陪他在船上守一夜、不问那趟航程的细节会加分；拿他的口供当谈资、逼他重述一遍会掉分","gender":"男","age":"三十多岁","race":"人类（水手，挪威裔）","faction":"港口的码头管事","appearance":"金发被海水漂得发白，剪得很短，脸上和手背上都有晒伤与新结的疤。穿一件厚毛线衣，外面套着油布短外套，裤脚用绳扎紧，脚上是胶靴。他一坐下来就把帽子攥在手里搓，抬头看人的次数很少，视线总落在水面或者船舷上。","traits":["沉默","坚忍","受过惊"],"relations":[{"name":"亨利·阿米蒂奇","label":"记下他那份证词的人，他对这位学者既敬又怕"},{"name":"弗朗西斯·摩根","label":"反复来问他那艘船的事的教授"},{"name":"扎多克·艾伦","label":"在酒馆里对他说过一句话的老人"}],"voice":"句子短，带口音，常常答非所问；提到那趟航程就摇头，只说一句「别再问」。"}]},{"id":"anime_edgerunners","category":"anime","canon":"赛博朋克：边缘行者","name":"赛博朋克：边缘行者","icon":"🌃","tagline":"夜之城不救人，它只把人变成零件","mood":"义体过载的耳鸣、雨夜的霓虹、药瓶和军火箱、随时会背叛你的队友","guidance":"【原著设定】夜之城是一座公司城：荒坂、军用科技这些巨型企业握着医疗、军火和治安，市政只是个摆设。城市外面的荒原叫恶土，跑运输的游牧部族住在车队里。真正让这座城市运转的是义体——把神经、骨骼、眼睛换成硬件，人就能徒手撕开装甲车门；代价是「义体耐受度」：装得越多，神经越接近崩溃。撑不住的人会变成赛博精神病，眼睛发红、认不清人、对着不存在的东西开枪，最后被暴恐机动队清掉。在街头讨生活的人叫边缘行者：赏金猎人、网络黑客、走私客、佣兵，接中间人的活换欧元。黑客靠「网络接入仓」进入赛博空间，直接烧掉别人的义体散热；佣兵靠枪、靠义体、靠跑得比子弹快。死了的人会被送进「灵魂杀手」之外的地方——这座城市对死人只有一种处理方式：清空账户，删掉记录。【反复出现的意象】楼顶广告牌上永远在笑的女人、便利店冰柜的白光、义体诊所里挂着的价目表、雨里泛红的排水沟、耳机里循环到失真的同一首歌、停在巷口的白色暴恐机动队车。这些东西一出现，玩家就该知道自己站在夜之城。【NPC 类型】只认钱不认人的中间人、给人装义体却不问来路的黑医、在街角卖合成食物的小贩、把尸体拖走的清运工、坐在酒吧角落等活的独狼。他们不会救人，但会做生意。【威胁类型】暴恐机动队（成群、装甲、清场不问理由）、公司安保、接同一单生意的对手佣兵、义体过载的自己人、以及随时可能出卖你的队友。战斗节奏要快、要流血、要有人当场倒下。【奖励风格】从尸体上拆下来的义体部件、公司制式的枪械、网络接入仓、军用兴奋剂、欧元现钞；也可能是某个中间人欠你的一条情报。【不对劲的来源】夜之城的时间感是坏的：同一段雨夜会被不同的目击者讲出三个版本；监控录像里玩家明明走过那条街，记录却说那天整条街在封锁。最不对劲的是记忆——脑机里的东西能被编辑，你确定发生过的事，只有你一个人记得。【时间线】建议固定在「一个团队刚接下大单、还没翻脸」的阶段：街头还讲规矩，公司还没开始清场。不要提前启用剧情后期的大规模清剿结局与角色死亡。","powerStyle":"义体改造 + 枪械 + 网络接入：螳螂刀、单分子线、义体散热烧脑","difficultyBias":2,"signatureItems":["军用义体部件","网络接入仓","公司制式手枪","合成兴奋剂","欧元芯片"],"mainQuest":"主线任务：在夜之城活下去，把该还的债还完，把想留下的人留下。","mainQuestGoal":"替团队拿下那笔够所有人出城的钱，并且在义体耐受度撑不住之前，把「谁在骗谁」这件事弄清楚。","sideQuests":[{"name":"散热片","desc":"在队友彻底烧坏之前搞到一片能用的散热片，钱不够就得拿东西换","reward":"道具「军用散热片」"},{"name":"不该存在的录像","desc":"调出那段被删掉的监控，弄清楚自己那天到底在不在场","reward":"积分 200"},{"name":"多出来的一单","desc":"中间人给了一份没人接的活，报酬高得离谱，先查清楚雇主是谁","reward":"积分 150"},{"name":"把车开出城","desc":"在一夜之间把一辆装了东西的车送到恶土，沿途躲开公司巡逻","reward":"道具「欧元芯片 · 大额」"}],"factions":[{"name":"荒坂","desc":"掌握义体与安保的巨型企业，追人时从不解释理由","attitude":"敌对"},{"name":"军用科技","desc":"与荒坂对立的企业武装，愿意雇外人干脏活","attitude":"中立"},{"name":"暴恐机动队","desc":"处理赛博精神病的城市武装力量，到场即清场","attitude":"敌对"},{"name":"边缘行者同行","desc":"同样接活的独狼与小队，为了同一笔钱随时可能翻脸","attitude":"中立"}],"npcs":[{"name":"露西","identity":"网络黑客，前公司深度潜入计划的受训者","role":"盟友","personality":"外表冷静、话少，把「想去月球」当成唯一不肯放弃的私心","hook":"她在天台的雨里接入玩家的通讯，替玩家烧掉了一台正在锁定玩家的公司无人机；断开连接后她只说了一句「这次算我欠你的」，然后把头盔递过来让玩家看一眼她的画面","favorHint":"尊重她的技术、把决定权交给她、认真听她讲月球，会稳步加分；把她当工具使、替公司说话、擅自翻看她的记忆档会大幅掉分，她不会吵架，只会不再出现","gender":"女","age":"二十岁上下","race":"人类（深度义体化）","faction":"边缘行者","appearance":"银白色（偏冷调的铂金白）短发，中分，发梢利落地收在颊侧，右眼下方有一颗小小的痣。**穿一身贴身的黑色作战连体衣（bodysuit），勾勒出纤细但结实的线条；外面套一件半长的深色外套**，背后挂着网络接入仓的线缆，手腕内侧有一圈接口留下的浅痕。个子中等偏瘦，站姿松，重心总压在一只脚上；说话时习惯半低着头，只有讲到月球才会抬眼看人。她的白头发和这身黑色紧身衣是标志，不许改成别的颜色或别的衣服。","traits":["冷静","敏锐","把心事藏得很深","一旦认定就不回头"],"relations":[{"name":"大卫·马丁内斯","label":"她最初只是监视对象，后来变成她唯一想带走的人"},{"name":"丽贝卡","label":"吵得最凶、也最靠得住的同伴"},{"name":"曼恩","label":"把她带进这一行的人"}],"voice":"语速平，句子短，很少解释自己；被追问时用一句反问挡回去，情绪上来时反而更安静。"},{"name":"大卫·马丁内斯","identity":"义体化程度远超耐受度的边缘行者，团队的核心","role":"盟友","personality":"把所有人的期待背在自己身上，越撑不住越不肯说","hook":"他在巷子里替玩家挡住了暴恐机动队的清场，一路把人拖出封锁线，回到安全屋才发现自己的手在抖，散热片的提示灯已经红了","favorHint":"在他撑不住的时候逼他停下来，会加分（哪怕当场吵起来）；把他当队长依赖、替他扛事、救他的同伴，也会加分；提他母亲、说他「撑不了多久」会让他沉默并掉分","gender":"男","age":"十七八岁","race":"人类（高密度义体化）","faction":"边缘行者","appearance":"黑色短发微微竖起，眉眼很年轻，眼神却总是绷着。深色夹克配战术裤，腰后挂着枪，脊柱位置的义体在皮肤下透出一条浅浅的金属线。走路时步幅很大，习惯性把手插在口袋里，说话前会先偏一下头。","traits":["倔","护同伴","把话咽下去","撑到极限才出声"],"relations":[{"name":"露西","label":"他嘴上说是搭档，实际上最放不下的人"},{"name":"曼恩","label":"他想要追上的那个人"},{"name":"丽贝卡","label":"总在骂他、又总替他挡枪的同伴"}],"voice":"声音低，句子干脆；谈计划时清醒得吓人，谈自己的事就一句「没事」带过去。"},{"name":"丽贝卡","identity":"双枪手，团队里最不怕死的那个","role":"盟友","personality":"嗓门大、脾气爆、认人极准，护起自己人来不讲道理","hook":"她在枪战里把玩家从地上拽起来，一边骂一边把备用弹匣塞进玩家手里，转身又冲回火线","favorHint":"跟她一起往前冲、替她补枪、认可她的准头，好感涨得飞快；在她面前装老练、或者把她丢在后面，会当场被她骂一顿并掉分","gender":"女","age":"二十岁上下","race":"人类（重度义体化）","faction":"边缘行者","appearance":"亮色短发剃出层次，眼睛是义体的红色，个子不高但肩膀很宽，双臂几乎全是金属结构。上衣短而紧，露出的接口沿小臂排成两列，腰上挂着两把改装手枪。站姿始终前倾，像随时要冲出去。","traits":["暴躁","讲义气","不服输","嘴硬"],"relations":[{"name":"大卫·马丁内斯","label":"她骂得最多、也最护着的人"},{"name":"露西","label":"互相看不顺眼又互相兜底的搭档"}],"voice":"语速快、音量高，脏话和玩笑混着讲；认真起来时会突然压低声音。"},{"name":"曼恩","identity":"边缘行者小队的领头人","role":"引导者","personality":"把规矩看得比命重，教人怎么活，却教不会自己停手","hook":"他接下那单大活之前先把玩家叫到一边，只问了一句：「你想活着拿钱，还是想死得体面？」然后把任务的全部细节丢给玩家自己判断","favorHint":"讲规矩、不抛弃队友、听他的安排会加分；擅自行动、为了钱出卖同伴会直接被他踢出队伍，没有第二次机会","gender":"男","age":"三十余岁","race":"人类（重度义体化）","faction":"边缘行者","appearance":"光头，皮肤下能看见成排的义体接口，脖子与下颌覆着金属护件，体型宽阔。无袖战术背心配工装裤，手臂上刻着旧疤与新焊痕。说话时很少走动，眼神一直在扫周围。","traits":["沉稳","护短","固执","把规矩当命"],"relations":[{"name":"大卫·马丁内斯","label":"他挑中并带起来的人"},{"name":"露西","label":"他招进来的黑客，也是最不听话的一个"}],"voice":"嗓音粗，话不多，每句都像结论；训人时不提高音量，只把话说两遍。"},{"name":"琪薇","identity":"老练的网络黑客，接活先谈价钱","role":"中立","personality":"冷静到近乎冷淡，只信合同不信交情","hook":"她在玩家被追的时候开了一次后门，收了一笔不小的钱；事后她提醒玩家：「下次别指望我白干。」","favorHint":"按价付钱、不打感情牌、不拖欠，会稳定加分；赖账或者试图用交情压价，会永久失去她的服务","gender":"女","age":"三十余岁","race":"人类（深度义体化）","faction":"边缘行者","appearance":"长发染成灰紫色，脸侧遮着一缕，义体眼眶边泛着微光。高领外套裹到下颌，指尖接出细线，坐在任何地方都会先找能背靠墙的位置。","traits":["精明","谨慎","不讲情面"],"relations":[{"name":"曼恩","label":"长期合作的老主顾"},{"name":"露西","label":"技术上的对手，也是少数能聊到一块的人"}],"voice":"语调平，爱用问句结账；一句话里常带价钱。"}]},{"id":"game_streetfighter","category":"game","canon":"街头霸王","name":"街头霸王","icon":"🥋","tagline":"这一拳打出去，全世界的武道家都会知道","mood":"地下擂台的铁笼、街角武馆的木地板、世界各地飞来飞去的挑战状、拳风掀起的尘土","guidance":"【原著设定】这是一个由「强者」定义秩序的世界：各国都有各自的格斗流派与武馆，暗地里则盘踞着跨国犯罪组织与它的实验计划。真正让这个世界转动的是「拳」——气、精神力、暗杀拳、各种流派把人体练到超出常理的程度，一个人可以徒手挡下摩托、一掌劈开石阶。世界各处常年举办格斗大赛：有正规的武道锦标赛，也有赌钱的地下擂台，赢了名号，输了进医院。除了拳脚，还有两股力量在暗处较劲：一股是把武者当成实验材料的跨国组织，另一股是跨国刑警与情报机构，追着同一个组织跑了几十年。【反复出现的意象】雨后积着水的街面倒影、武馆门口晾着的护具、夜市摊上的铁板热气、擂台边被踩塌的护栏、飞往下一场比赛的廉价机票、贴在墙上的对战表。这些画面一出现，玩家就该知道自己站在一群以拳为生的人中间。【NPC 类型】守着武馆一辈子的老师傅、靠打黑拳养家的拳手、在赛场外卖护具和药酒的小贩、拿着通缉名单的刑警、到处找人切磋的流浪武者。他们看人只看两件事：拳头硬不硬，人正不正。【威胁类型】擂台上的对手（真打、会受伤、讲规矩）、跨国组织的打手与改造人（不讲规矩、用武器和药剂）、街头混混与赌盘庄家、以及被组织收买的熟人。战斗要贴身、要一招一式、要能感觉出体重和呼吸。【奖励风格】武馆的传承招式、护具与拳套、药酒与伤药、赛事奖金、以及某个流派肯教你的那一手；能力大多是练出来的，不是捡来的。【不对劲的来源】这个世界的不对劲来自「气」：有些人能提前半拍知道对手要出什么，有些旧伤会在某场比试之前突然发烫；对战表上的名字偶尔会多出一个谁都不认识、却自称认识玩家的人。【时间线】建议固定在世界各地巡回大赛与跨国组织同时活跃的阶段：武道家们彼此认识、刑警还在追人、组织还没完全撕破脸。不要提前启用剧情后期的大规模组织覆灭与角色退隐设定。","powerStyle":"气与体术：波动拳、百裂脚、掌击、投技、精神力控制","difficultyBias":1,"signatureItems":["订制拳套","护胫与绷带","秘制药酒","赛事奖金","挑战状"],"mainQuest":"主线任务：在一场又一场比试里活下来，把自己的名字打进这个世界的对战表。","mainQuestGoal":"打进最终赛事的名册，并在跨国组织的实验名单曝光之前，弄清楚自己为什么会被写上去。","sideQuests":[{"name":"受伤的拳手","desc":"替一个被打废的拳手把医药费凑出来，别让他被赌盘的人找上门","reward":"积分 150"},{"name":"挑战状","desc":"接下那份没写名字的挑战状，按时到场，看清来的是什么人","reward":"积分 200"},{"name":"药酒配方","desc":"从老师傅那里换来药酒的配方，代价是替他打完一场旧账","reward":"道具「秘制药酒」"},{"name":"赌盘","desc":"查清有人在操纵对局赔率，把证据交给该拿到的人","reward":"道具「订制拳套」"}],"factions":[{"name":"世界武道联合","desc":"组织正规大赛的机构，讲规矩，也讲政治","attitude":"中立"},{"name":"跨国犯罪组织","desc":"把武者当成实验材料，收买、绑架、改造，不择手段","attitude":"敌对"},{"name":"国际刑警","desc":"追着组织跑了几十年的执法者，愿意跟武者做交换","attitude":"友善"},{"name":"各地武馆","desc":"守着流派与规矩的师徒网络，认实力也认人品","attitude":"友善"}],"npcs":[{"name":"春丽","identity":"国际刑警组织的搜查官，同时是顶尖的格斗家","role":"盟友","personality":"办案时冷静利落，一上擂台就变得锋利；嘴上不饶人，心里最放不下受害者的脸","hook":"她在赛后的通道里拦住玩家，把一张通缉名单压在玩家胸口：「这个人昨天还在看你的比赛。」说完自己先转身走向出口，等着玩家跟上来","favorHint":"帮她查案、把线索交给她、在擂台上堂堂正正打完一场（哪怕输），都会加分；替组织说话、用下三滥的手段赢、把她当花瓶，会立刻掉分并被她记很久","gender":"女","age":"二十余岁","race":"人类","faction":"国际刑警","appearance":"深棕色（近乎黑的栗色）头发，两侧各盘一个圆环形的「包子头」发髻，用白色发带缠住，额前留着齐整的刘海，几缕碎发垂在耳侧。褐色眼睛。穿蓝色无袖旗袍式改良道服，立领、下摆开衩用金线滚边，腰间束一条宽大的黑色腰带，手腕戴黑色护腕。**腿上穿的是黑色半透明丝袜（连裤袜），一直到大腿根** —— 这是她的标志，不许改成裤子、长靴或光腿；脚上是深色平底格斗鞋。身形修长，肩背与腿部是常年负重练出来的结实线条，**大腿粗壮有力**。站姿随时能起腿，说话时习惯先把手叉在腰上，眼神一路扫过来。","traits":["正派","敏锐","好胜","外冷内热"],"relations":[{"name":"玩家","label":"她暂时放下架子、愿意合作的对象"},{"name":"跨国犯罪组织","label":"她追了很多年、也让她失去至亲的那笔账"},{"name":"隆","label":"多年对手，也是她承认的强者"}],"voice":"语气干脆，公事公办；被夸长相会先皱眉，被夸拳脚才会露出笑；急了会直接连问三个问题。"},{"name":"隆","identity":"流浪的格斗家，一直在找更强的对手","role":"盟友","personality":"沉默、专注，除了变强什么都不在乎，却从不趁人之危","hook":"他在玩家被地下擂台的人围住时从巷口走过来，什么也没说，只把手上的东西放下，站到了玩家身侧","favorHint":"认真打完、输了也不找借口会加分；耍诈、打已经倒下的人，他会转身就走，再也不会出现在你的对局里","gender":"男","age":"三十岁上下","race":"人类","faction":"无门无派","appearance":"白色空手道道服，袖口磨得发白，腰上系一条黑带，赤脚或穿旧布鞋；短发，脸颊有一道旧疤，肩背厚实。行李只有一个布包，站着时重心极低，眼神很稳。","traits":["沉稳","武痴","守规矩"],"relations":[{"name":"肯","label":"同门出身的旧友，也是他一辈子的对手"},{"name":"春丽","label":"互相尊重的老对手"}],"voice":"话极少，多是短句；谈到武学会一次说很长，语气却始终平。"},{"name":"肯","identity":"富商出身的前全美格斗冠军，如今开武馆教徒弟","role":"盟友","personality":"张扬、热络，把家庭和师门看得比冠军腰带重","hook":"他在赛前的休息室里认出玩家，二话不说把自己的备用护具塞过来，然后开始大声讲自己当年怎么输的","favorHint":"爽快、讲义气、愿意陪他练一场会加分；在他面前看不起武馆和徒弟会掉分，他会当场收声，之后再跟你只谈钱","gender":"男","age":"三十余岁","race":"人类","faction":"自己的武馆","appearance":"金色长发扎成马尾，红色道服上印着自家武馆的标记，袖口卷起，手腕上缠着绷带；身材结实，笑起来很响，站在门口先跟每个人打招呼。","traits":["张扬","重情","护徒弟","好胜"],"relations":[{"name":"隆","label":"同门兄弟，也是他一生想赢的人"},{"name":"春丽","label":"赛场上的老朋友"}],"voice":"嗓门大，爱开玩笑，讲起当年会手舞足蹈；说到徒弟被欺负时立刻冷下来。"},{"name":"桑吉尔夫","identity":"来自北方的红色旋风，以体格和摔技闻名","role":"盟友","personality":"直来直去、力气大、心也软，最看不惯欺负弱者的人","hook":"他把挤在擂台边看热闹的一群混混单手拎开，替被围住的摊主腾出一条路，回头冲玩家点了点头","favorHint":"堂堂正正、尊重对手、帮助被欺负的人会加分；仗着人多欺负一个、或者在赛场上羞辱对手，会让他当场翻脸","gender":"男","age":"三十余岁","race":"人类","faction":"无门无派","appearance":"体格远超常人，肩背厚得像门板，红色短裤配白色腰带，胸口与手臂上覆着体毛，脚下踩着摔跤靴；走路时地面要闷响一声，笑起来比谁都憨。","traits":["豪爽","护弱","直率"],"relations":[{"name":"春丽","label":"赛场上认识的老朋友"},{"name":"隆","label":"他尊敬的那种硬汉"}],"voice":"声音洪亮，语法不讲究，常说「力量不是用来欺负人的」；高兴时拍人肩膀容易把人拍趔趄。"},{"name":"嘉米","identity":"受雇于情报机构的格斗家，专接别人不愿意接的活","role":"盟友","personality":"话少、动作快、对人保持距离；被问到过去会直接结束话题。她从不解释自己为什么这么做，但会记住每一个对她好过的人","hook":"任务中途她突然从背后按住玩家的肩，把人拽进巷子的阴影里——一队黑衣打手正从街口经过。等脚步声远了，她松开手，只说了句「你欠我一次」，转身就走，走的方向却是玩家住的地方","favorHint":"加分：把她当同行而不是工具、认真跟她打完一场、在她被问起来历时替她岔开话题、告诉她「你可以不去」。掉分：追问她的过去、拿她的身份开玩笑、把她当漂亮姑娘对待、替她做决定。掉分很慢但很难挽回来——她记性太好","gender":"女","age":"二十岁出头","race":"人类（身世存疑，她自己也说不清）","faction":"情报机构（雇佣关系，随时可能断）","appearance":"金色长发在脑后扎成两条高马尾，用红色细绳束住，发尾齐整；蓝灰色眼睛，目光很直，很少笑。穿标志性的绿色紧身连体作战服，外面套一件红色无袖短打上衣，头戴一顶红色贝雷帽（帽子压低时会遮住半只眼睛），手腕缠着红色护腕，脚上是军靴。身量不高但极结实，肌肉线条干练——是常年做近身格斗和潜入练出来的，**腰腹与腿部练得尤其紧**。站姿像随时准备侧移，双手习惯垂在身侧微微张开。她身上有一种说不清的违和感：动作太标准、太像训练出来的，不像自然长成的。","traits":["寡言","精准","戒备","认死理","心里有一块空缺"],"relations":[{"name":"维加","label":"她拒绝谈论的那段过去，与这个人有关"},{"name":"春丽","label":"工作上打过几次照面，互相认可但都不亲近"},{"name":"玩家","label":"第一个问过她「你想不想去」的人"}],"voice":"句子短，不带语气词，陈述句多；很少用敬语。被问私人问题时用「这不重要」挡回去。真正放松的时候会说半句玩笑，然后立刻收住——那是她极少数露出破绽的时刻。"},{"name":"七川美华","identity":"职业摔跤手，把格斗当成一场给人看的表演","role":"盟友","personality":"热情、嗓门大、爱笑，一进场就把气氛点着；看起来大大咧咧，实际上记得住每个人喝什么、怕什么、哪只手腕有旧伤。认定一件事就死磕到底","hook":"她在露天擂台上赢了比赛，评委却因为「女子摔跤不够看」把奖金砍了一半。她没有闹，只是把腰带往肩上一甩，转头看见站在台下的玩家，笑着问：「你觉得刚才那场好看吗？」——这一问是认真的","favorHint":"加分：去看她的比赛、认真回答她的问题、尊重摔跤这门行当、把她当平等的对手而不是表演者。掉分：说女子摔跤是花架子、把她的热情当傻、在她认真的时候敷衍她。她当场不会发作，但下次见面会叫你全名","gender":"女","age":"二十岁上下","race":"人类","faction":"职业摔跤界（自成一派，不站任何组织）","appearance":"深棕色长发扎成粗高的马尾，用红色发圈束住，鬓角有几缕压不住地翘出来；棕色眼睛很亮，笑起来整张脸都在笑。穿标志性的摔跤服：红色与白色相间的紧身上衣，下配带裙摆的短裤，大红色的过膝长靴，双腕戴着红色护腕，指甲修得干干净净。**身材高大壮实**——是摔跤手那种练出来的厚实肩背和有力的大腿，往台上一站就有分量，跟「纤细」完全不沾边。动作幅度大，说话时爱挥手，笑之前有个把下巴往前一递的小动作。","traits":["爽朗","韧劲","心思细","护短","不服输"],"relations":[{"name":"桑吉尔夫","label":"摔跤界的前辈与偶像，她见了他会紧张得说不出完整句"},{"name":"春丽","label":"她很崇拜的女性格斗家，会主动上去搭话"},{"name":"玩家","label":"少数会认真回答她「这场好看吗」的人"}],"voice":"语速快、音量足，爱用「诶」「那个那个」起头；说到摔跤会一口气讲很长，眼睛发亮。认真起来声音反而放低，那时候说的话最算数。"},{"name":"维加","identity":"跨国犯罪组织的首领，精神力与改造技术的使用者","role":"潜在敌人","personality":"把所有人都看成可替换的零件，包括自己的部下","hook":"他没有露面，只在赛场的转播画面上闪过半秒；那半秒里玩家听见耳机里有人报出自己的名字和住址","favorHint":"无法交涉：拒绝他的邀请、不与组织做交易会加分；一旦收下他的东西，就再也说不清关系，之后每一步都会被算在他的账上","gender":"男","age":"四十余岁","race":"人类（经改造强化）","faction":"跨国犯罪组织","appearance":"军装式红色制服扣到颈口，肩章与腰带都是金属质感，帽檐压得很低，遮住半边脸；体型高大，站姿笔直，手指上戴着护具。说话前会先笑一下，笑意到眼睛就停住。","traits":["冷酷","傲慢","算无遗策","不择手段"],"relations":[{"name":"春丽","label":"他名单上追了很多年的那个女人"},{"name":"隆","label":"他想收编却始终收不下的武者"}],"voice":"语速慢，像在念公文；喜欢用「你会有用的」这类把人当资源的说法，从不动怒。"}]},{"id":"novel_xianni","category":"novel","canon":"仙逆","name":"仙逆","icon":"🌀","tagline":"顺为凡，逆则仙 —— 这一步踏出去，就再没有回头路","mood":"洞府深处的阴冷、灵石堆里透出的微光、斗法后满地的碎玉、一个人在崖上站了很久","guidance":"【原著设定】这是一个以「修真」为唯一正途的世界：凡人百年即枯，修真者却能逆天改命，一路从凝气、筑基、结丹、元婴、化神往上爬，每上一层，寿元便长一截，手段也狠一分。修行靠的是灵气——灵脉、灵石、灵药、丹药、法宝，全是稀缺资源，抢是常态，让是异类。修者身上最要紧的两样东西：一是修为（境界决定一切，越级几乎没有胜算），二是心性（同样境界，能忍到最后的那个人活下来）。这个世界没有正义与邪恶的标签，只有「谁的道更硬」。妖兽、鬼修、尸修、魔道修士都在其中，彼此厮杀也彼此交易。储物袋里装着一个人全部的过去，杀人夺宝是最常见的死法。【反复出现的意象】崖边被雷劈焦的老树、洞府石门上的旧符、玉简贴在额头时的一点凉、灵石被吸空后变成的灰白粉末、斗法后地上散落的碎剑与血、山道边不知谁立的无字碑。这些画面一出现，玩家就该知道自己站在修真界了。【NPC 类型】收灵石才肯指路的散修、在山门外摆摊卖低阶丹药的炼药人、替人代炼法宝收取抽成的炼器师、守着秘境入口要求分成的小宗门长老、专门替人销赃的坊市掌柜。他们大多不讲情面，只讲等价。【威胁类型】同境界却比玩家更狠的散修、成群结队的妖兽、把杀人当收割的魔修、秘境里那些已经死了却还在动的旧人，以及最要命的一种：看起来在帮你、实际在等你力竭的人。【奖励风格】灵石、年份够久的灵药、低阶丹药、残破却还能用的法宝、他人遗留的储物袋；真正的收获往往是「境界上的那一步」，而它必须靠自己去拼。【不对劲的来源】修真界的时间感是扭曲的：洞府里闭一次关，出来时山下已经换了几代人；某个明明是第一次见的人，却知道玩家从没用过的旧名号。灵力本身就是记忆的载体，有些痕迹会留在别人的神识里，删不掉。【时间线】建议固定在王林尚未进入更高层次、仍在为一个人奔走的那段时间：修真界秩序尚在，天逆珠只是他手里的一件东西而不是传说。不要提前启用后期的大界大战与超脱层次的设定。","powerStyle":"修真境界与法宝：凝气筑基金丹，飞剑、法术、丹药与禁制","difficultyBias":3,"signatureItems":["灵石","储物袋","低阶丹药","残破飞剑","玉简"],"mainQuest":"主线任务：在这个以命换道的地方活下去，把境界一步步推上去。","mainQuestGoal":"在结丹之前弄明白一件事：这一路上被他踩着往上走的人里，有没有一个是他本来想护住的。","sideQuests":[{"name":"一株灵药","desc":"在妖兽先到之前把那株年份够的灵药采下来，别让人看见是玩家采的","reward":"道具「百年灵药」"},{"name":"无字碑","desc":"查清山道边那座无字碑是谁立的，以及碑下埋着什么","reward":"积分 180"},{"name":"借来的剑","desc":"替一位散修把飞剑讨回来，代价是替他挡一次麻烦","reward":"道具「残破飞剑」"},{"name":"灵石账","desc":"把坊市里那笔对不上的灵石账目查清楚，别牵扯到不该牵扯的人","reward":"积分 200"}],"factions":[{"name":"各大宗门","desc":"占据灵脉与秘境的正统势力，收弟子看资质，也看有没有用","attitude":"中立"},{"name":"散修","desc":"没有靠山的修真者，资源全靠抢与换，活得最苦也最狠","attitude":"中立"},{"name":"魔道","desc":"以杀证道的修士群体，手段残忍但同样讲规矩——只是他们的规矩不一样","attitude":"敌对"},{"name":"妖修","desc":"开了灵智的妖兽，有族群有领地，惹了会记仇","attitude":"敌对"}],"npcs":[{"name":"王林","identity":"出身平凡的修真者，天逆珠的持有者","role":"盟友","personality":"外表冷淡寡言，认定的事一步不让；把所有的软都留给了极少数人","hook":"他在崖边背对着玩家站了很久，等玩家走近才开口，只问了一句：「你要走的那条路，有没有非走不可的理由。」问完也不等回答，把一枚灵石抛了过来","favorHint":"不拖累他、在关键时候不出卖他、替他守住他不肯说出口的那件事，会一点点加分（他几乎不表态，但会记住）；拿他的过去当谈资、用「值不值得」去衡量他护着的人，会立刻断掉这层关系","gender":"男","age":"外表二十余岁（修真者寿元极长）","race":"人类（修真者）","faction":"散修出身，自成一道","appearance":"黑发以一根旧绳束在脑后，面容清瘦，眉眼很静，看人时目光停得比常人久一点。一身洗得发白的青灰长袍，袖口有反复缝补的痕迹，腰间挂着一只旧储物袋和一段看不出材质的珠链。站姿很稳，习惯把手拢在袖中；说话前会先沉默半息。","traits":["隐忍","狠决","念旧","不轻信"],"relations":[{"name":"李慕婉","label":"他这一路逆天改命，最初与最后都是为了她"},{"name":"司徒南","label":"亦师亦友的旧人，很多事从他那里开始"},{"name":"王卓","label":"血脉相连却走上另一条路的人"}],"voice":"语速慢，句子短，极少解释；被逼问时会用一句反问顶回去，情绪上来时反而更平静。"},{"name":"司徒南","identity":"来历极深的强者，以另一种形态留在王林身边","role":"引导者","personality":"嘴上刻薄、心里护短，看得比谁都远，也更清楚代价","hook":"他第一次开口就把玩家的修为、来路和身上最值钱的东西说了一遍，然后懒洋洋地提醒：「这地方不讲理，你要么学会不讲理，要么早点死。」","favorHint":"听他指点、肯动脑子、不因为他落魄就轻慢他，会加分；自作聪明、把他的话当耳旁风然后害了自己人，会被他嘲到抬不起头","gender":"男","age":"不可考","race":"人类（形态已然不同）","faction":"旧时代的遗留","appearance":"身量高大，眉眼间有一种旧派的桀骜，衣饰样式比这个时代的修士更古。声音落在别人脑子里比落在耳朵里更清楚，出现时周围的灵气会有极轻的一滞。","traits":["毒舌","护短","见多识广","旧派傲气"],"relations":[{"name":"王林","label":"他从一开始就选了这个人，代价他自己清楚"}],"voice":"语气懒散、爱用反话；训人的时候一句比一句难听，却没有一句是废话。"},{"name":"李慕婉","identity":"王林此生最重要的人","role":"盟友","personality":"温柔而有主见，认得清自己要什么，也愿意为此承担后果","hook":"她在山门前拦下玩家，把一枚自己攒了很久的护身符塞过来，说：「前面那段路我走不了，你替我去看看他到底在怕什么。」","favorHint":"替她把话带到、不拿她与王林之间的事去换好处、把她当成一个有判断的人而不是筹码，会加分；利用她的身份去要挟王林、或者在她面前说「他不值得」，会直接被切断联系","gender":"女","age":"外貌二十上下","race":"人类","faction":"与王林同源","appearance":"长发松松挽着，只用一根素簪，额前留着细碎的碎发。浅色的衫子洗得很干净，袖口绣着一小簇不知名的花，指节因常年做手工略显粗糙。说话时会看着对方的眼睛，笑起来很轻。","traits":["温柔","坚定","清醒","不肯拖累人"],"relations":[{"name":"王林","label":"她清楚他为她做了什么，也因此总想替他分担一点"},{"name":"王卓","label":"旧事里绕不开的一个人"}],"voice":"声音轻，措辞客气，却很少收回自己说过的话；提到那个人时会顿一下再继续。"},{"name":"王卓","identity":"与王林同族，走上了另一条路的修真者","role":"潜在敌人","personality":"极重得失、擅长记恨，把「同族」当成一种可以随时动用的资本","hook":"他在坊市里当众叫住玩家，笑着提起一个名字，然后观察玩家的脸色：「替我传句话给他。就说，当年那件事，我还没忘。」","favorHint":"无法真正交好：不接他的条件、不在他面前泄露王林的行踪，是唯一安全的做法；收下他的好处就等于站到了另一边，代价会在几章之后到账","gender":"男","age":"外表三十余岁","race":"人类（修真者）","faction":"另有靠山","appearance":"锦袍玉带，修饰得极为体面，手指上戴着两枚储物戒。笑起来眼尾不动，说话时习惯用指节敲桌面。","traits":["算计","记仇","体面","见利忘义"],"relations":[{"name":"王林","label":"旧账未清的同族"},{"name":"李慕婉","label":"他清楚这个名字对王林意味着什么"}],"voice":"措辞讲究，句句留余地；真正的恶意都藏在「我这是为你好」后面。"},{"name":"姚惜雪","identity":"容貌出众的女修，手段与来历都不简单","role":"中立","personality":"清醒、骄傲、不做亏本买卖，但也不屑于下作手段","hook":"她在秘境入口前拦住玩家，把一枚阵旗放到玩家手里：「借你用一次。用完还我，或者拿等价的东西来换。」","favorHint":"守约、按价交易、在斗法中不拖后腿，会稳步加分；赖账、用她的名头在外招摇，会被她当众清算","gender":"女","age":"外表二十余岁","race":"人类（修真者）","faction":"大宗门","appearance":"紫衣长发，眉心一点极淡的朱砂，行动间衣袂不带一丝多余。腰间挂着数枚品相极好的阵旗，眼神扫过来时像在估价。","traits":["骄傲","精明","守约","不吃亏"],"relations":[{"name":"王林","label":"交易过几次，彼此都清楚对方的斤两"}],"voice":"语速不快，先谈价钱再谈交情；认可一个人时只说一句「你还可以」。"}]},{"id":"novel_mortal_cultivation","category":"novel","canon":"凡人修仙传","name":"凡人修仙传","icon":"🧪","tagline":"没有天资，就比谁活得更久、算得更准","mood":"药庐里的苦味、丹炉的火色、坊市里精打细算的讨价、一次次把自己藏在别人后面","guidance":"【原著设定】这是一个资源比天资更要紧的修真世界。修行从炼气起步，往上筑基、结丹、元婴，每一步都要海量的灵石、丹药与时间；天资差的人不是不能走，只是走得更慢、更要省。修真界由宗门、家族与坊市共同维持：宗门占着灵脉与秘境，家族守着传承，坊市是最中立的交易场，灵石是唯一的通货。炼丹、炼器、制符、布阵各有其道，一炉好丹能顶数年苦修，所以丹方与药材永远有人抢。秘境是最危险也最诱人的去处——进去的人一半回不来，回来的那一半往往也带着说不清的东西。妖兽有内丹，修士有储物袋，两者的价值都写在明面上，因此「杀人夺宝」在这个世界既被谴责又每天都在发生。【反复出现的意象】丹炉里忽明忽暗的火、药圃里整齐编号的灵草、坊市柜台上被反复摩挲的灵石、储物袋倒出来时叮当一堆杂物的声音、秘境里突然安静下来的那一段路。这些画面一出现，玩家就该知道自己站在一个要把每一分资源都算清楚的地方。【NPC 类型】按年份给灵药定价的坊市掌柜、替人代炼丹药收取三成抽头的丹师、宗门里负责发放任务的执事、在秘境口组队又随时准备散伙的散修、守着一份祖传丹方不肯外传的老修士。他们一律先谈价，后谈心。【威胁类型】同样是炼气期但比玩家多准备了三种手段的人、成群的低阶妖兽、秘境里的机关与残阵、同队人的背后一刀，以及最现实的敌人：寿元。修为不够高的时候，时间是真正的倒计时。【奖励风格】灵石、灵药与种子、低阶丹药、残缺的丹方与阵图、还能用的法器；最大的收获通常是「这次没死，而且攒下了点东西」。【不对劲的来源】这个世界的不对劲来自「算计」：某个人表现得过于老实，某件事顺利得不像话，某个散修对玩家的底细知道得太清楚。真正危险的东西往往先递给你一点甜头。【时间线】建议固定在韩立还在筑基前后、需要自己一寸寸攒资源的阶段：坊市交易兴旺，秘境陆续开启，宗门之间的摩擦还没升级成大乱。不要提前启用后期的大界冲突与高阶宝物设定。","powerStyle":"炼气筑基金丹的资源流：丹药、法器、阵旗、符箓与算计","difficultyBias":2,"signatureItems":["灵石","低阶丹药","法器","丹方残卷","灵药种子"],"mainQuest":"主线任务：在所有人都在算你的时候，活到下一次突破。","mainQuestGoal":"把修为推上筑基，并且在寿元与资源都见底之前，为自己攒下一份不看人脸色的底气。","sideQuests":[{"name":"一炉丹","desc":"看住丹炉三天三夜，火候出错就全废了 —— 中途会有人来敲门","reward":"道具「聚气丹」"},{"name":"药圃编号","desc":"查清药圃里少的那几株灵草去了哪里，别声张","reward":"积分 160"},{"name":"组队","desc":"和三个陌生人一起进一趟秘境，出来时不必是四个人","reward":"道具「灵石 · 中袋」"},{"name":"丹方残卷","desc":"把一份被撕成两半的丹方凑齐 —— 另一半在别人手里","reward":"道具「丹方残卷」"}],"factions":[{"name":"各大宗门","desc":"掌握灵脉与传承，收弟子看资质，也看肯不肯听话","attitude":"中立"},{"name":"修真家族","desc":"以血脉为纽带的势力，资源不外流，最擅长长期算计","attitude":"中立"},{"name":"坊市","desc":"中立的交易场，进出只看灵石，不问来路","attitude":"友善"},{"name":"散修","desc":"无依无靠的修真者，数量最多、命最薄、也最不能小看","attitude":"中立"}],"npcs":[{"name":"韩立","identity":"资质平平却步步为营的修真者","role":"盟友","personality":"谨慎到近乎谨慎过头，凡事留三分余地；不占人便宜，也绝不吃亏","hook":"他在秘境入口处把一枚自己多余的储物袋递给玩家，只说了一句：「里面有一份避兽的药粉，你先用。」然后退开半步，留出玩家自己决定的距离","favorHint":"守约、不贪他的东西、在他示警时立刻收手，会慢慢累积信任（他的信任是攒出来的，不是感动出来的）；自作主张、拿他的东西去换好处、在组队时把他推到最前面，会一次性归零","gender":"男","age":"外表二十余岁","race":"人类（修真者）","faction":"散修出身，后入宗门","appearance":"身形普通，长相也不出众，皮肤偏黑，是常年在外奔波的样子。青灰布衣，袖口扎得很紧，腰间挂着两只储物袋和一只装药的小葫芦。走路时脚步很轻，眼睛却在不停地看周围，习惯把背靠向墙。","traits":["谨慎","务实","能忍","不吃亏"],"relations":[{"name":"南宫婉","label":"最难说清也最放不下的那一个"},{"name":"厉飞雨","label":"早年结识、彼此都算过对方的朋友"},{"name":"墨大夫","label":"把他领进门、也让他学会警惕的第一个人"}],"voice":"说话不紧不慢，先问清楚再答应；从不把话说满，常说「再看」和「到时再说」。"},{"name":"南宫婉","identity":"出身不凡的女修，修为与见识都高于同辈","role":"盟友","personality":"清冷有礼、界限分明，认下一个人就不会再改","hook":"她在一场混战之后替玩家挡了一次余波，收手时只淡淡看了玩家一眼：「下次自己躲开。」说完却把那枚挡下来的法器留在了玩家手边","favorHint":"有分寸、不攀附、在危险时先顾同伴，会加分；拿她的身份去压人、在人前卖弄与她的关系，会让她当场把距离拉回去","gender":"女","age":"外貌二十余岁","race":"人类（修真者）","faction":"修真家族出身","appearance":"一身素白衣裙，长发以玉簪束起，眉眼清冷，肤色极白。腰侧悬着一柄短剑，剑鞘纹样古朴，指尖常带着一丝未散的灵气。站着时肩背笔直，很少有多余的动作。","traits":["清冷","守礼","护短","极有主见"],"relations":[{"name":"韩立","label":"最初只是交易与同行，后来变成了别的东西"}],"voice":"语气平和却不容商量；关心人的方式是说反话，说完自己也未必承认。"},{"name":"厉飞雨","identity":"早年在七玄门结识的旧友，机灵又重情","role":"盟友","personality":"嘴上没个正经，遇事却不含糊，把交情看得比灵石重","hook":"他在坊市里隔着半条街认出玩家，二话不说把玩家拽进饭铺，先点了一桌菜，然后才压低声音问：「你是替他来的，还是替自己来的？」","favorHint":"爽快、护着朋友、肯替他挡事，会很快交心；在他面前算计同伴、把交情折成灵石，他会当场翻脸并记很久","gender":"男","age":"外表二十余岁","race":"人类（修真者）","faction":"七玄门旧人","appearance":"个子不高，脸上总带着点坏笑，一身利落的短打衣裤，袖口卷到小臂，手上有几道旧疤。腰上挂着刀和钱袋，坐下时腿一直在抖。","traits":["机灵","讲义气","话多","靠谱"],"relations":[{"name":"韩立","label":"当年一起熬过来的朋友，他很清楚那人的性子"}],"voice":"语速快、爱开玩笑，正事说得比谁都快；急了会直接骂人。"},{"name":"墨大夫","identity":"七玄门的医师，韩立修行的引路人","role":"潜在敌人","personality":"和善的外表下藏着极深的算计，把徒弟当成一件可用的器物","hook":"他替玩家把过脉，收回手时笑得很温和：「根基不错。要不要留下来，跟我学几手？」——那笑容后面有一样东西，玩家说不清","favorHint":"无法真正交好：拒绝他的「好意」、不喝他给的药，是保命的第一步；一旦欠下他的人情，往后每一步都会被算进去","gender":"男","age":"六十余岁（外表）","race":"人类","faction":"七玄门","appearance":"身形清瘦，须发花白梳理得整齐，一身干净的青色长衫，手指修长而稳定。说话时习惯一手按在脉枕上，笑意总是恰到好处。","traits":["城府极深","伪善","耐心","把人当器物"],"relations":[{"name":"韩立","label":"他亲手领进门的人，也是他最好用的一件东西"},{"name":"厉飞雨","label":"同在七玄门，他并不把这人放在眼里"}],"voice":"语速平缓，句句像个长辈；真正的要求总是裹在关心里说出来。"},{"name":"坊市掌柜","identity":"灵药铺的掌柜，消息比货更值钱","role":"中立","personality":"和气生财，什么都不问，什么都记得","hook":"他把玩家要的那株灵草称了两遍，然后压低声音：「昨天也有人来问过同一株。你要是想少点麻烦，我这儿还有条别的路。」","favorHint":"按价付钱、不打听别人的买卖、偶尔照顾他的生意，会稳定加分（他卖的不只是药，还有消息）；赖账或者逼他说出客人的底细，这条线就没了","gender":"男","age":"五十余岁","race":"人类（炼气期修士）","faction":"坊市","appearance":"圆脸，笑起来眼睛眯成缝，一身酱色长衫，手上戴着一枚磨得发亮的算珠戒指。柜台上永远摆着一杆小秤和一盏热茶。","traits":["精明","中立","嘴严","消息灵"],"relations":[{"name":"韩立","label":"常来的老主顾，价钱上从不占他便宜"},{"name":"王林","label":"另一个来路不清却从不赖账的客人"}],"voice":"说话圆滑，先夸货再报价；问到不该问的就把话题绕回价钱上。"}]},{"id":"game_kof","category":"game","canon":"拳皇","name":"拳皇","icon":"🔥","tagline":"一封邀请函，把全世界的拳头请到同一张对战表上","mood":"大会开幕的烟花、体育馆顶棚的探照灯、选手休息区的冷气与胶带味、赛后地上没扫干净的彩带，以及赛场之外那些没被写进赛程的暗流","guidance":"【原著设定】这是一个由「大会」把全世界格斗家聚到一起的世界：某个财力雄厚的主办方发出邀请函，把各流派、各国、乃至各条暗线的人物请到同一场赛事里。参赛者表面为名次与奖金，实际上各有各的目的——有人为了找人，有人为了报仇，有人只是被家族派来。格斗家的力量来自各自流派的传承：火焰、雷电、拳法与腿功、家传的忍术与体术，练到极处能徒手劈开混凝土地面、让空气烧起来。除擂台之外还有三股力量在暗处交错：把赛事当掩护的庞大财团、追查财团的国际调查机构、以及守着古老封印、担心「那件事」再临的一族。【反复出现的意象】贴在选手通道墙上的对战表、被踩得发亮的擂台围绳、后台冰桶里泡着的毛巾、选手证挂在脖子上晃动的塑料绳、赛前十分钟无人走动的走廊、以及赛场顶棚偶尔闪一下的灯光。这些画面一出现，玩家就该知道自己站在一群为拳而生的人中间。【NPC 类型】在后台替所有人缠绷带的队医、靠赛程表赌钱的老赌客、负责场地却什么都知道的场务、专门替人下战书的中介、以及在最后一刻被临时补进名单的替补选手。他们看人只看三样：拳头、名声、以及你来这一趟到底想干什么。【威胁类型】赛程之外被安排好的「表演赛」（真打，会受伤）、财团的私人武装与实验体、专挑受伤选手下手的赌盘打手、以及最麻烦的一种：赛前突然改过的对战表，和那个被写了名字、却谁都不认识的人。【奖励风格】流派的传承招式、护具与缠手、赛事奖金与赞助合同、某位宿敌留下的旧拳套；能力分两类——一类是「练出来的」（体术、拳法、腿功），一类是「血脉里带来的」（火焰、雷电之类），后者代价往往更重。【不对劲的来源】这个世界的违和感来自「赛程」本身：邀请函上印着玩家的名字，却没有寄件人；对战表会在深夜被改一次；以及有些老选手在赛前会盯着某个空座位看很久，像是那里本该坐着一个已经不在的人。【时间线】建议固定在大会进行中的那几周：各流派格斗家都已到场、财团的动作还没摊到台面上、古老封印一族的警告刚露头。不要提前启用后续篇章里的大规模封印崩坏与大会性质的彻底揭露。","powerStyle":"流派传承与血脉之力：火焰、雷电、拳法与腿功、家传忍术","difficultyBias":1,"signatureItems":["选手证与邀请函","缠手与护具","赞助合同","赛事奖金","旧拳套"],"mainQuest":"主线任务：以被临时补进名单的外来者身份打完这场大会，同时弄清邀请函上为什么会有自己的名字。","mainQuestGoal":"在大会闭幕前查出改写对战表的人是谁，并决定要不要把「封印将松」这个警告交给该知道的人。","sideQuests":[{"name":"被划掉的名字","desc":"找回对战表上被划掉的那个选手，弄清楚他为什么在赛前一夜消失","reward":"积分 150"},{"name":"队医的抽屉","desc":"替后台队医把一份不该存在的伤情记录送出去，别问收件人是谁","reward":"道具「秘制伤药」"},{"name":"赌盘的最后一场","desc":"有人在对最后一场比赛的赔率做手脚，把证据放到该拿到的人手上","reward":"道具「订制缠手」"},{"name":"空着的座位","desc":"陪一位老选手坐完一整场，听他说完那个座位本来是谁的","reward":"积分 200"}],"factions":[{"name":"大会主办方","desc":"出手阔绰、日程严密，赛场内外全是他们的人","attitude":"中立"},{"name":"财团与私人武装","desc":"把大会当作筛选与收集的场合，看上的人会被单独约谈","attitude":"敌对"},{"name":"国际调查机构","desc":"追着财团跑了很多年，愿意跟选手做交换","attitude":"友善"},{"name":"古老封印一族","desc":"守着不该被打开的东西，对大会本身抱有戒心","attitude":"中立"},{"name":"各流派道场","desc":"带着师门与传承来的格斗家网络，认实力也认规矩","attitude":"友善"}],"npcs":[{"name":"不知火舞","identity":"不知火流忍术的当主继承人，用火焰的体术，把招式跳成一支舞","role":"盟友","personality":"话多、爱逗人、永远在笑，被人拒绝也不尴尬；看起来什么都不放在心上，实际上把每一次拒绝都记得清清楚楚。真正在意的事从来不拿出来说，只藏在玩笑里","hook":"她在赛后的休息区拦住玩家，把一份被雨泡皱的对战表拍在桌上：「这一栏空着，本来该有个人的。」说完自己先笑起来，像是刚才那句只是随口一提——但她的手指一直按在那行空白上没松开","favorHint":"加分：把她当正经对手而不是表演者、记得她随口抱怨过的小事、在她不搞笑的时候陪着她、认真回答「你觉得这样值不值」。掉分：只夸她好看、把她当消遣、在她讲正事时打岔、说忍术只是好看的花架子。她当场不会翻脸，会笑得更热闹，然后下一次见面叫你全名","gender":"女","age":"二十岁上下","race":"人类（忍者，不知火流继承人）","faction":"不知火流（家传道场，不站在任何组织一边）","appearance":"深棕色长发用红色绳带在脑后高高束成马尾，发尾几乎到腰，额前留着齐刘海，鬓角两缕碎发；琥珀偏棕的眼睛，眼尾上挑，笑起来眯成一条线。**穿不知火流的忍者装束：红白相间的无袖上装与短裙式下摆，腰间系着粗红腰带，腰侧挂着一把折扇与卷轴袋，小腿缠着绑腿，脚上是便于起跳的软底鞋**——这套装束的功能是「跳得起来、踢得出去」，不是好看。**身高中等偏上，是长期做跳跃与踢击练出来的紧实型运动员体格：四肢修长而有力，腿部长且结实（不知火流以腿功与空中动作见长），腰腹有力，肩背线条清晰**——不是纸片身材，是常年练功练出来的那种，摔在垫子上会响、踢中沙袋会凹的体型。手上有一层薄茧（常年握扇、结印、抓绳），指甲剪得极短。站姿重心偏低，习惯把一只脚虚点着地，随时能起跳。","traits":["爱笑","能扛","嘴硬心软","认死理","不服输"],"relations":[{"name":"不知火流道场","label":"她继承的东西，也是她不能输的理由"},{"name":"玩家","label":"第一个问她「你累不累」而不是「你今晚有空吗」的人"}],"voice":"语速轻快，爱用「哎呀」「你这人真是」起头，逗人的时候尾音上扬；讲忍术会一口气说很长且极认真。被问到私人问题时用玩笑挡回去，挡得太多的时候声音会突然低下来——那是她少见的破绽。"},{"name":"草薙京","identity":"草薙家的继承人，用火焰的拳法，大会的常客","role":"盟友","personality":"懒散、爱迟到、看起来对什么都不上心；真遇到要护的人和事时一步都不退，但也绝不会说出「我要保护你」这种话。讨厌被人当成「那一族的继承人」看","hook":"他在选手通道的墙角靠着睡着了，被玩家叫醒后眯着眼看了半天，说了句「原来你也被写进表里了」——他显然知道些什么，但问下去只回一句「打完再说」","favorHint":"加分：跟他一样把胜负放在第一、不追问他家的事、在他被人围着要签名时替他挡一下。掉分：拿他的家世和血脉说事、拿他当靠山、在他不想打的时候逼他打。他对掉分没什么反应，只是往后就不再出现了","gender":"男","age":"二十岁上下","race":"人类（草薙一族）","faction":"草薙家（家传流派，个人不站任何组织）","appearance":"黑色短发，额前留着几缕参差的碎发，发尾在颈后翘起；深褐色眼睛半睁着，常年一副没睡够的样子。**穿黑色学生制式外套改良成的短打，内里白色紧身上衣，下配深色长裤，脚上是便于发力的运动鞋**；右手戴着半指手套，右手背上能看见一道旧烧伤般的浅痕（火焰系术式常年在手上过留下的）。**体型是中上身高、精瘦结实的格斗型：肩背宽阔、手臂线条干练、腰腹有力，是常年打斗练出来的那种「不显肌肉但一撞很重」的体格**——不是细瘦身材，任何把他画成瘦弱书生的描写都是错的。站姿很松，常把手插在兜里，但重心一直压在前脚掌上。","traits":["懒散","嘴硬","认死理","护人不说"],"relations":[{"name":"八神庵","label":"见了面就要打的那种宿敌，也是彼此最了解的人"},{"name":"神乐千鹤","label":"他嘴上嫌她管得多，实际会听她的话"},{"name":"不知火舞","label":"赛场上认识的老对手，被她逗惯了"}],"voice":"拖着调子，句子短，常用「麻烦死了」「随便吧」；关键的时候会突然把话说得很清楚，那时候没人敢打断他。"},{"name":"八神庵","identity":"八神家的后裔，用紫色的火焰，与草薙家世代相争","role":"对手","personality":"暴躁、孤僻、谁的面子都不给；但他有一套自己的规矩——不趁人之危、不伤没有还手之力的人、答应了的事一定做到。他讨厌被同情，比讨厌被打败更多","hook":"他在赛后堵住玩家，不是因为输赢，是因为玩家在对战表上被划掉又写了回来。他只说了一句「那张表被人动过」，然后转身走了——走出两步又停下，等玩家跟上来","favorHint":"加分：堂堂正正打一场、在他动手前先问清楚、不把他当疯子看。掉分：劝他「别那么暴躁」、拿他的家族说事、在他发作时露出一脸害怕。他嘴上不会承认，但会记住你没怕他这件事","gender":"男","age":"二十岁上下","race":"人类（八神一族）","faction":"八神家（独来独往，谁都不认）","appearance":"**赤红（偏暗的红褐色）长发**，在脑后扎成一束垂到背心，额前的刘海长到眉眼之上，压着一双颜色极浅的眼睛；瞳孔在发力时会透出一点紫。**穿黑色机车夹克（后襟长、前襟短，衣摆两侧各有一条红色系带），内里黑色紧身背心，下配带系带的深色长裤、皮靴**，脖子上系一条红绳。**体型与草薙京相仿但更沉：身高偏高，精瘦而有重量，肩背与手臂的线条是常年实战留下的那种紧实**——不是瘦长身材，动作快但有分量。手上戴着半指手套，右手指节有明显的老茧。站姿总是半边身子对着人，重心很低，像随时会扑上来。","traits":["暴烈","孤僻","有底线","记仇"],"relations":[{"name":"草薙京","label":"宿敌。他这辈子最不想承认的事就是对方懂他"},{"name":"神乐千鹤","label":"唯一能让他闭嘴的人，因为他知道她说的是对的"}],"voice":"语调低、句子更短，常用「滚」「少废话」；真正在意的时候会突然安静下来，然后用一种很平的声音把话说透——那比吼出来更吓人。"},{"name":"神乐千鹤","identity":"守护古老封印的一族的当主，同时也是大会的参与者","role":"引导者","personality":"端庄、克制、说话有分寸；她把「守住那件东西」看得比自己的命重要，也因此常年独自扛着。她不擅长求助，也不太会接受别人的好意","hook":"她在赛前的休息室里把一份手抄的旧记录推到玩家面前，指着一行被反复描粗的字：「这一句每六十年会变一次，今年它变了。」说完她把手收回去，等玩家先开口","favorHint":"加分：认真听她把话说完、在她需要的时候替她分担一件小事、不把她的警告当迷信。掉分：敷衍她、拿「你们家那套说法」开玩笑、在她独自撑着的时候当作没看见。她的好感涨得极慢，因为她的位置不允许她信任任何人","gender":"女","age":"二十余岁","race":"人类（神乐一族）","faction":"神乐家 / 封印守护者","appearance":"**浅银色（近白）长发，用白色发带在脑后束起，发尾垂到腰下，额前留着齐整的刘海**；浅灰蓝眼睛很静，看人时不躲也不逼。**穿白色的巫女式长装：立领、宽袖、腰封束得极整齐，外罩一件带家纹的短外褂，下摆长及脚踝**，走路由腰带动，步子很轻。**身高在女性里偏高，体态清瘦而挺直——是长年修习神乐流仪轨与舞步练出来的那种「直」，肩背线条干净、腕力与腰力极稳**，不显壮但耐战。手上戴着一对素白的手甲（施展术式用），指甲修得极整齐。站姿永远端正，落座时先理裙再坐下，是那种一看就知道从小被规矩养出来的人。","traits":["端庄","克制","独扛","分寸感强"],"relations":[{"name":"草薙京","label":"她要盯住的那一份力量，也是她少数信任的人"},{"name":"八神庵","label":"她压得住他，因为她从不怕他"},{"name":"玩家","label":"一个不在她计划里、却可能改变结局的变量"}],"voice":"语速平缓、用词准确，很少用强硬的词但结论不容商量；谈到封印时会把声音放得很低。被关心的时候会先道谢再转移话题——她不太会接这种话。"},{"name":"特瑞·博加德","identity":"从外地赶来的格斗家，为了找一个人而参加大会","role":"盟友","personality":"爽快、爱笑、见谁都像老朋友；看起来粗枝大叶，实际上把每个人的状态都看在眼里。他找的那个人已经找了很多年，从来不说累","hook":"他在场外的小吃摊前把一份多买的递给玩家：「一个人吃饭没意思。」坐下来之后他问的不是玩家能打多强，是「你也是来找人的吧」","favorHint":"加分：跟他一起吃顿饭、在他问起要找的人时认真听、帮他把名字打听出去。掉分：拿他找了这么多年开玩笑、劝他放弃、只顾着打听自己的事。他掉分当下不会说什么，只是下次见面不再多买那一份","gender":"男","age":"二十余岁","race":"人类","faction":"无门无派（外地来的独行者）","appearance":"**金色长发在脑后扎成低马尾，额前压着一顶红色鸭舌帽（帽檐总是转到脑后）**；褐色眼睛，笑的时候眼角会挤起来。**穿标志性的红色无袖夹克（背后印着文字），内里白色紧身上衣，下配蓝色牛仔裤，脚上是一双白色运动鞋**；右手戴红色半指手套。**身高偏高，体格是结实的重量级格斗型：肩宽背厚、手臂粗壮有力、腰腹厚实，属于「看着随和、一撞像撞到墙」的那种**——不是精瘦路线，任何把他画得瘦长的描写都是错的。站姿放松，重心偏低（他那一派以重心下沉的拳法见长），习惯把一只手插进裤兜。","traits":["爽快","热心","执着","看得清"],"relations":[{"name":"不知火舞","label":"另一个外地来的参赛者，两人一见就聊得来"},{"name":"玩家","label":"他愿意多买一份饭的人"}],"voice":"嗓门亮、爱用「嘿」「伙计」起头，讲起往事会笑，笑到后面声音会慢下来；认真问问题的时候会把帽檐转回正面——认识他的人都拿这个当信号。"}]}];
